export const sumulas = [{"id":"sv","short":"SV · STF","name":"Súmulas Vinculantes do STF","area":"Súmulas · Supremo Tribunal Federal","law":"63 entradas · PDF fornecido","description":"Enunciados, precedentes e aplicações no STF, com indicação das situações registradas no documento.","icon":"§","kind":"sumulas","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26","source":{"filename":"Sumulas_Vinculantes_STF_Completo.pdf","pdf":"sources/Sumulas_Vinculantes_STF_Completo.pdf","pages":236,"sha256":"a705152ccb223acd38f71024a24c2f39d87808795694e8612adf94134452e6e6","declaredConsultationDate":"2026-10-16","kind":"supplied_pdf","edition":"PDF fornecido · consulta declarada em 16/10/2026","coverage":"63 entradas numeradas de 1 a 63, incluindo a SV 9 indicada como cancelada e a SV 30 como pendente de publicação.","reviewStatus":"Enunciados e material de aplicação extraídos do PDF fornecido. A data de consulta e as situações são as declaradas no documento; não houve conferência com o portal do STF nesta importação."},"sections":[{"id":"grupo-0","scope":"main","title":"Súmulas 1 a 10"},{"id":"grupo-1","scope":"main","title":"Súmulas 11 a 20"},{"id":"grupo-2","scope":"main","title":"Súmulas 21 a 30"},{"id":"grupo-3","scope":"main","title":"Súmulas 31 a 40"},{"id":"grupo-4","scope":"main","title":"Súmulas 41 a 50"},{"id":"grupo-5","scope":"main","title":"Súmulas 51 a 60"},{"id":"grupo-6","scope":"main","title":"Súmulas 61 a 63"}],"introductions":[],"articles":[{"id":"1","number":"1","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":1,"endPage":3,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1185","paragraphs":[{"page":1,"runs":[{"text":"Ofende a garantia constitucional do ato jurídico perfeito a decisão que, sem ponderar as circunstâncias do caso concreto, desconsidera a validez e a eficácia de acordo constante de termo de adesão instituído pela Lei Complementar 110/2001.","deleted":false}]}],"notes":[{"page":1,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":1,"runs":[{"text":"Inconstitucionalidade do Enunciado 21 das Turmas Recursais da Seção Judiciária do Rio de Janeiro, que preconiza a desconsideração de acordo firmado pelo trabalhador e previsto na LC 110/2001. Caracterização de afastamento, de ofício, de ato jurídico perfeito e acabado. Ofensa ao princípio inscrito no art. 5º, XXXVI, do Texto Constitucional.","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"[ RE 418.918 , rel. min. Ellen Gracie , P, j. 30-3-2005, DJ de 1º-7-2005.]","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"No que concerne à existência de vício de consentimento, consistente no desconhecimento do trabalhador comum quanto às cláusulas do ajuste, reputo incabível a sua proclamação em abstrato, como se fez com a adoção do Enunciado 21, uma vez que a perquirição acerca de vício em algum dos elementos formadores da vontade do agente haverá de ser demonstrada caso a caso, acordo a acordo, por demandar avaliação do elemento subjetivo do pactuante no momento da avença, consideradas as circunstâncias específicas e indissociáveis da personalidade de cada um.","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"[ RE 418.918 , voto da rel. min. Ellen Gracie, j. 30-3-2005, P, DJ de 1º-7-2005.]","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":1,"runs":[{"text":"● A questão da exigibilidade das contribuições sociais criadas pelos arts. 1º e 2º da Lei Complementar n. 110/2001, destinadas ao pagamento dos expurgos inflacionários das contas vinculadas ao Fundo de Garantia do Tempo de Serviço - FGTS, decorrentes da aplicação de índice de correção monetária dessas contas abaixo da inflação real, não tem repercussão geral, pois ausente relevância econômica, política, social ou jurídica que transcenda ao interesse das partes","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"[ Tese definida no RE 571.184 RG , rel. min. Cármen Lúcia , j. 16-10-2008, P, DJE 206 de 31-10-2008, Tema 120]","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"A relevância jurídica ou econômica que teria a discussão perdeu sentido. Já há até mesmo Súmula Vinculante sobre os termos de adesão aos acordos do FGTS que foram criados pela própria Lei Complementar n. 110/2001 ( Súmula Vinculante n. 1: Ofende a garantia constitucional do ato jurídico perfeito a decisão que, sem ponderar as circunstâncias do caso Concreto, desconsidera a validez e a eficácia de acordo constante de termo de adesão instituído pela Lei Complementar n. 110/2001 ).","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"[ RE 571.184 RG , rel. min. Cármen Lúcia , j. 16-10-2008, P, DJE 206 de 31-10-2008.]","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"● Ofende a garantia constitucional do ato jurídico perfeito a decisão que, sem ponderar as circunstâncias do caso concreto, desconsidera a validez e a eficácia do acordo constante de termo de adesão instituído pela Lei complementar 110/2011","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"[Tese definida no RE 591.068 QO-RG , rel. min. Gilmar Mendes , P, j. 7-8-2008, DJE 35 de 20-2-2009, Tema 101.]","deleted":false}],"heading":false},{"page":1,"runs":[{"text":"A decisão recorrida limita-se a registrar que a transação deu-se fora dos autos, sem utilização de escritura pública e sem a presença de advogado, deixando de avaliar se este procedimento resultou objetivamente em","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"prejuízo não consentido ou ignorado pelo titular da conta vinculada. A forma adotada para a transação, que teve fundamento na LC 110/2001, já foi analisada por esta Corte e considerada legítima, sendo ônus da parte interessada demonstrar se, no caso concreto, diante das circunstâncias peculiares dos que formalizaram o pacto, houve prejuízo em decorrência de vício de consentimento do titular do direito. Trata-se, pois, de matéria já exaustivamente decidida nesta Corte, na linha contrária à que foi adotada pelo acórdão recorrido.","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"[ RE 591.068 QO-RG , voto do rel. min. Gilmar Mendes , j. 7-8-2008, P, j. 7-8-2008, DJE 35 de 20-2-2009, Tema 101.]","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":2,"runs":[{"text":"Reexame de prova e impossibilidade de aplicação da Súmula Vinculante 1","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"I. O Plenário do Supremo Tribunal Federal, ao julgar o RE 418.918/RJ, rel. min. Ellen Gracie, conheceu e deu provimento ao recurso extraordinário da Caixa Econômica Federal, ao entendimento de que a decisão que desconsidera o Termo de Adesão a que alude a LC 110/2001, assinado pela Caixa Econômica Federal e pelos trabalhadores, viola o instituto do ato jurídico perfeito (CF/1988, art. 5º, XXXVI). II. O Tribunal a quo analisou as provas contidas nos autos e afirmou inexistir prova da celebração do acordo entre o agravado e a Caixa Econômica Federal. Assim, para se chegar a conclusão contrária à adotada pelo acórdão recorrido, necessário seria o reexame do conjunto fático-probatório constante dos autos, o que atrai a incidência da Súmula 279 do STF.","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"[ AI 701.414 AgR , rel. min. Ricardo Lewandowski, 1ª T, j. 17-3-2009, DJE 71 de 17-4-2009.]","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"Validade do termo de adesão ao acordo previsto na LC 110/2001 em razão de análise do caso concreto","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"(...) o reconhecimento de que o titular da conta e a CEF optaram, na via extrajudicial, pela quitação da obrigação reconhecida judicialmente, ainda que em momento posterior à formação da coisa julgada no processo judicial, não vulnera a garantia constitucional do inciso XXXVI do art. 5º da Constituição Federal. Ressalto que, conforme disposto na LC 110/2001, é facultado ao titular da conta optar pela via consensual, mediante contrato de adesão, para recebimento dos créditos, com a devida homologação no juízo competente. Assim, caberia ao agravante comprovar eventual causa de invalidade dos referidos contratos de adesão, o que não ocorreu. Inexiste, portanto, violação à coisa julgada na decisão monocrática ora rescindenda, a qual conferiu a correta aplicação da lei ao caso concreto, reconhecendo a validade e a eficácia dos termos de acordo, diante da inexistência de comprovação de qualquer causa de invalidade prevista no ordenamento jurídico, tal como na Súmula Vinculante 1 (...).","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"[ AR 2.258 AgR , voto do rel. min. Gilmar Mendes, P, j. 23-9-2016, DJE 244 de 18-11-2016.]","deleted":false}],"heading":false},{"page":2,"runs":[{"text":"O presente caso, entretanto, cuida de questão diversa daquela examinada por esta Corte na ocasião do julgamento do RE 418.918/RJ, Pleno, relatora a ministra Ellen Gracie, RTJ 195/321, e consolidada na Súmula Vinculante 1 desta Corte. No julgamento do mencionado recurso extraordinário, foi declarada a inconstitucionalidade do Enunciado 21 das Turmas Recursais da Seção Judiciária do Rio de Janeiro, que afastava a aplicação do acordo firmado por trabalhadores com a ora agravante, nos termos da LC 110/2001, por vício de consentimento. Naquele caso específico, a validade do acordo, celebrado antes do ajuizamento da ação judicial, foi afastada pelo Tribunal local de ofício e sem que fossem analisadas as peculiaridades do caso concreto. Nos presentes autos, o acórdão recorrido examinou as particularidades do caso, concluindo pela impossibilidade de homologação judicial do termo de adesão, nos seguintes termos: “Com efeito, na hipótese dos autos, não há que se falar em homologação de acordo, eis que o mesmo, para que produza seus efeitos na esfera judicial, depende de expressa concordância das partes com todas suas cláusulas e, enquanto não for judicialmente homologado, afigura-se integralmente recusável por qualquer das partes, não havendo como admitir-se qualquer cláusula de acordo que imponha renúncia, de forma irretratável, à garantia fundamental de pleno acesso à Justiça, como no caso (CF/1988, art. 5º, XXXV). Ainda que, na espécie, houve ação anulatória do termo de adesão em referência, no qual restou vitoriosa a recorrente, visto ser exageradamente prejudicial","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"ao pedido da apelante. Em sendo assim, tornar-se-ia ilegítimo violar a coisa julgada, no caso, validando o referido termo de adesão. Registre-se, ainda, que, nos termos do art. 842, última parte, do Código Civil/2002, se a transação recair sobre direitos contestados em juízo, deverá ser feita por termo nos autos, assinado pelos transigentes e homologado pelo juiz, não caracterizando, portanto, violação ao ato jurídico perfeito (art. 5º, XXXVI, da CF/1988) a decisão que deixa de homologar o acordo extrajudicial, ante a ausência de expressa concordância de uma das partes com os seus termos, como na espécie dos autos”. Assim, não merece prosperar a irresignação da recorrente.","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"[ RE 630.392 , rel. min. Dias Toffoli, dec. monocrática, j. 3-11-2011, DJE 222 de 23-11-2011.]","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"O Tribunal de origem não afastou a validade do termo de adesão ao acordo previsto na LC 110/2001, tão somente concluiu que fora ultrapassado o momento processual oportuno para a alegação de carência de ação fundamentada no termo do acordo. (...) É de ressaltar, ao final, que não houve afronta ao que decidido no julgamento do RE 418.918 e ao disposto na Súmula Vinculante 1, pois o Tribunal de origem analisou as particularidades do caso concreto.","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"[ RE 612.724 ED , voto da rel. min. Cármen Lúcia, 1ª T, j. 31-8-2010, DJE 190 de 8-10-2010.]","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"Ressalto, por fim, que não tem aplicação neste caso a Súmula Vinculante 1 desta Corte (...). Isso porque a decisão recorrida não desconsiderou acordo estabelecido nos termos da LC 110/2001, mas tão somente entendeu necessária a assistência do advogado, quando a transação recair sobre direitos contestados em juízo.","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"[ RE 560.592 , rel. min. Ricardo Lewandowski, dec. monocrática, j. 2-3-2010, DJE 45 de 12-3-2010.]","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":3,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 101, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"● Tema 120 de Repercussão Geral (não reconhecida).","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"Data de publicação do enunciado: DJE de 6-6-2007.","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":3,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"2","number":"2","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":4,"endPage":6,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1188","paragraphs":[{"page":4,"runs":[{"text":"É inconstitucional a lei ou ato normativo Estadual ou Distrital que disponha sobre sistemas de consórcios e sorteios, inclusive bingos e loterias.","deleted":false}]}],"notes":[{"page":4,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":4,"runs":[{"text":"Tem-se, com a exploração de loteria, derrogação excepcional de normas de Direito Penal: DL 204, de 27-2-1967. A competência legislativa, por isso mesmo, é da União, na forma do que dispõe o art. 22, I, da Constituição Federal. Nesse sentido, aliás, o decidido pelo Supremo Tribunal Federal no julgamento da ADI 1.169 MC/DF, relator o ministro Ilmar Galvão. Ademais, porque as loterias estão abrangidas pela terminologia sorteios, segue-se que a competência para legislar a respeito é da União: CF/1988, art. 22, XX.","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"[ ADI 2.847 , voto do rel. min. Carlos Velloso , P, j. 5-8-2004, DJ de 26-11-2004.]","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"A exploração de loteria será lícita se expressamente autorizada a sua exploração por norma jurídica específica. Essa norma específica - e isso me parece evidente - é norma penal, porque consubstancia uma isenção à regra que define a ilicitude. (...) Então, se apenas à União, e privativamente - para começar - a CF/1988 atribui competência para legislar sobre matéria penal, apenas a União poderá dispor a regra de isenção de que se cuida. (...) Portanto, nem a lei estadual, nem a lei distrital, nem a lei municipal podem operar migração, dessa atividade, do campo da ilicitude para o campo da licitude, pois isso é da competência privativa da União, nos termos do art. 22, I, da CF/1988.","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"[ ADI 2.847 , rel. min. Carlos Velloso , voto do min. Eros Grau , P, j. 5-8-2004, DJ de 26-11-2004.]","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":4,"runs":[{"text":"Abrangência da expressão “sorteios”","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"1. Esta Suprema Corte já assentou que a expressão “sistema de sorteios” constante do art. 22, XX, da CF/1988 alcança os jogos de azar, as loterias e similares, dando interpretação que veda a edição de legislação estadual sobre a matéria, diante da competência privativa da União.","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"[ ADI 3.895 , rel. min. Menezes Direito, P, j. 4-6-2008, DJE 162 de 29-8-2008.]","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"Na dicção da ilustrada maioria, entendimento em relação ao qual guardo reservas, a cláusula reveladora da competência privativa da União para legislar sobre sistemas de consórcios e sorteios - art. 22, XX, da CF/1988 - abrange a exploração de loteria, de jogos de azar.","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"[ ADI 2.950 , rel. min. Marco Aurélio, P, j. 29-8-2007, DJE 18 de 1º-2-2008.]","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"O eminente procurador-geral da República, ao oferecer o seu douto parecer nos presentes autos, sustentou, a meu juízo, com inteira razão, que os diplomas normativos ora impugnados efetivamente vulneraram a cláusula de competência, que, inscrita no art. 22, XX, da Constituição da República, atribui, ao tema dos “sorteios” (expressão que abrange, na jurisprudência desta Corte, os jogos de azar, as loterias e similares), um máximo coeficiente de federalidade, apto a afastar, nessa específica matéria, a possibilidade constitucional de legítima regulação normativa por parte dos Estados-membros, do Distrito Federal, ou, ainda, dos Municípios.","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"[ ADI 2.995 , voto do rel. min. Celso de Mello, P, j. 13-12-2006, DJE 112 de 28-9-2007.]","deleted":false}],"heading":false},{"page":4,"runs":[{"text":"Competência material dos Estados para explorar serviços de loteria","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"Os arts. 1º e 32 do Decreto-Lei 204/1967, ao estabelecerem a exclusividade da União sobre a prestação dos serviços de loteria, não foram recepcionados pela Constituição Federal de 1988 (...). A competência privativa da União para legislar sobre sistemas de consórcios e sorteios (art. 22, inciso XX, da CF/88) não preclui a competência material dos Estados para explorar as atividades lotéricas nem a competência regulamentar dessa exploração. (...) a Súmula Vinculante 2 não trata da competência material dos Estados de instituir loterias dentro das balizas federais, ainda que tal materialização tenha expressão através de decretos ou leis estaduais, distritais ou municipais. (...) O enunciado da súmula e os precedentes que a fundamentaram expressamente elucidaram que a disposição legal ou normativa vedada aos Estados e ao Distrito Federal é a que inova e, portanto, legisla sobre o tema de consórcios e sorteios, inclusive bingos e loterias.","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"[ ADPF 492 , rel. min. Gilmar Mendes, P, j. 30-9-2020, DJE 292 de 15-12-2020.]","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"Exigência de licitação para delegar a exploração de loterias a agentes privados","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"5. O sentido da interpretação conferida à Súmula Vinculante nº 02 pelas instâncias de origem encontra-se superado pela jurisprudência atual do Supremo Tribunal Federal. 6. O entendimento mais recente distingue a competência legislativa da União sobre sistemas de consórcios e sorteios da competência material dos Estados para explorar loterias, desde que observada a legislação federal e que a delegação a agentes privados seja precedida de licitação.","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"[ ARE 1.548.004 AgR , rel. min. Flávio Dino, 1ª T, j. 1º-7-2025, DJE s/n 8-7-2025.]","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"Exploração da atividade de bingo","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"Ao contrário do que pretendido, o Supremo Tribunal Federal não permitiu nem liberou a exploração da atividade de bingos. Este Supremo Tribunal declarou inconstitucional lei ou ato normativo estadual ou distrital que disponha sobre sistemas de consórcios e sorteios, até mesmo bingos e loterias. Portanto, não prospera a pretensão da reclamante, que, a pretexto de alegar contrariedade à Súmula Vinculante 2 do Supremo Tribunal Federal, pretende a liberação da exploração de atividade de bingos por meio desta reclamação.","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"[ Rcl 10.198 , rel. min. Cármen Lúcia, dec. monocrática, j. 21-2-2011, DJE 44 de 9-3-2011.]","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"Este Tribunal fixou o entendimento de que a atividade dos bingos está abrangida no preceito veiculado pelo art. 22, XX, da Constituição do Brasil, que é categórico ao estipular a competência da União para legislar sobre sorteios. (...) 8. No voto que proferi por ocasião do julgamento da ADI 2.948, deixei consignado que a exploração das atividades abrangidas na categoria “sorteio” será lícita se expressamente autorizada a sua exploração por norma jurídica específica. Essa norma específica é norma penal, porque consubstancia uma isenção à regra que define a ilicitude penal. 9. Somente a regra de isenção, de competência legislativa privativa da União, retiraria a atividade dos bingos do universo da ilicitude, admitindo a sua exploração. Haveria aí uma operação de transposição da atividade do campo da ilicitude para o campo da licitude.","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"[ RE 524.501 , rel. min. Eros Grau, dec. monocrática, j. 13-6-2008, DJE 118 de 30-6-2008.]","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"Marco temporal para cabimento de reclamação por descumprimento da Súmula Vinculante 2","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"A Constituição Federal dispõe, em seu art. 103-A, caput e § 3º, que a súmula aprovada por dois terços dos membros do Supremo Tribunal Federal terá efeito vinculante a partir de sua publicação na imprensa oficial, cabendo reclamação do ato administrativo ou decisão judicial que a contrariar ou que indevidamente a aplicar. No presente caso, verifico que o ato impugnado foi proferido em 9-2-2007 (fls. 29-31), data anterior à publicação da Súmula Vinculante 2 na imprensa oficial, ocorrida em 6-6-2007. Não ocorre, portanto, a hipótese que autoriza a reclamação por descumprimento de súmula vinculante. Ademais, a jurisprudência do Supremo Tribunal Federal é no sentido de que inexiste ofensa à autoridade de pronunciamento da Corte se o ato de que se reclama é anterior à decisão por ela emanada.","deleted":false}],"heading":false},{"page":5,"runs":[{"text":"[ Rcl 5.343 , rel. min. presidente Ellen Gracie, dec. monocrática, j. 3-7-2007, DJ de 1º-8-2007.]","deleted":false}],"heading":false},{"page":6,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":6,"runs":[{"text":"● Tema 924 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":6,"runs":[{"text":"Data de publicação do enunciado: DJE de 6-6-2007.","deleted":false}],"heading":false},{"page":6,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":6,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"3","number":"3","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":7,"endPage":12,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1191","paragraphs":[{"page":7,"runs":[{"text":"Nos processos perante o Tribunal de Contas da União asseguram-se o contraditório e a ampla defesa quando da decisão puder resultar anulação ou revogação de ato administrativo que beneficie o interessado, excetuada a apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão.","deleted":false}]}],"notes":[{"page":7,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":7,"runs":[{"text":"Possibilidade de revogação de atos administrativos que não se pode estender indefinidamente. Poder anulatório sujeito a prazo razoável. Necessidade de estabilidade das situações criadas administrativamente. 8. Distinção entre atuação administrativa que independe da audiência do interessado e decisão que, unilateralmente, cancela decisão anterior. Incidência da garantia do contraditório, da ampla defesa e do devido processo legal ao processo administrativo.","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"[ MS 24.268 , rel. min. Ellen Gracie , red. p/ o ac. min. Gilmar Mendes , P, j. 5-2-2004, DJ de 17-9-2004.]","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"(...) quando o Tribunal de Contas aprecia a legalidade de um ato concessivo de pensão, aposentadoria ou reforma, ele não precisa ouvir a parte diretamente interessada, porque a relação jurídica travada, nesse momento, é entre o Tribunal de Contas e a Administração Pública. Num segundo momento, porém, concedida a aposentadoria, reconhecido o direito à pensão ou à reforma, já existe um ato jurídico que, no primeiro momento, até se prove o contrário, chama-se ato jurídico perfeito, porque se perfez reunindo os elementos formadores que a lei exigia para tal. E, nesse caso, a pensão, mesmo fraudulenta - porque estou convencido, também, de que, na sua origem, ela foi fraudulenta -, ganha esse tônus de juridicidade.","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"[ MS 24.268 , rel. min. Ellen Gracie , red. p/ o ac. min. Gilmar Mendes , voto do min. Ayres Britto , P, j. 5-2-2004, DJ de 17-9-2004.]","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":7,"runs":[{"text":"● Em atenção aos princípios da segurança jurídica e da confiança legítima, os Tribunais de Contas estão sujeitos ao prazo de 5 anos para o julgamento da legalidade do ato de concessão inicial de aposentadoria, reforma ou pensão, a contar da chegada do processo à respectiva Corte de Contas","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"[Tese definida no RE 636.553, rel. min. Gilmar Mendes, P, j. 19-2-2020, DJE 129 de 26-5-2020, Tema 445.]","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"(...) a concessão de aposentadoria ou pensão constitui ato administrativo complexo, que somente se aperfeiçoa após o julgamento de sua legalidade pelo Tribunal de Contas. (...) por constituir exercício da competência constitucional de controle externo (art. 71, III, CF/88), tal ato ocorre sem a participação dos interessados e, portanto, sem a observância do contraditório e da ampla defesa. Nesse sentido, cito o teor da Súmula Vinculante 3 (...). No entanto, é preciso distinguir as hipóteses em que (1) o TCU anula as aposentadorias ou pensões por ele próprio já julgadas legais e registradas - nesse caso, há anulação de ato administrativo complexo aperfeiçoado - das outras em que (2) o TCU julga ilegais e nega registro às aposentadorias e pensões concedidas pelos órgãos da Administração Pública - atividade de controle externo realizada sem a audiência das partes interessadas (...).","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"[ RE 636.553 , rel. min. Gilmar Mendes , P, j. 19-2-2020, DJE 129 de 26-5-2020.]","deleted":false}],"heading":false},{"page":7,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":7,"runs":[{"text":"Ausência de aderência estrita entre a Súmula Vinculante 3 e acórdão de natureza genérica do TCU","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"DIREITO ADMINISTRATIVO. AGRAVO INTERNO EM RECLAMAÇÃO. REGIME DA LEI 8.038/1990 E DO CPC/1973. VIOLAÇÃO À SÚMULA VINCULANTE 3. ACÓRDÃO DIRIGIDO AO ÓRGÃO CONTROLADO, QUE ATINGE A GENERALIDADE DOS SERVIDORES. AUSÊNCIA DE ADERÊNCIA ESTRITA. 1. Não possui relação de aderência estrita com a Súmula Vinculante 3 - que garante o contraditório e a ampla defesa nos processos perante o Tribunal de Contas da União - o acórdão do TCU determinando providência que atinge a generalidade dos servidores do órgão controlado, considerados em sua coletividade. 2. Contraditório que deverá ser exercido no órgão de origem. Necessidade de se manter a viabilidade da atividade fiscalizatória da Corte de Contas. 3. A reclamação não se presta à análise de suposta desconformidade de ato com o direito objetivo, não podendo funcionar como sucedâneo recursal ou substituto da ação própria cabível.","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"[ Rcl 7.411 AgR , rel. min. Roberto Barroso, 1ª T, j. 26-5-2017, DJE 118 de 6-6-2017.]","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"Distinção entre fiscalização dirigida contra indivíduos específicos e atividade genérica de auditoria","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"Embora oportuna a atuação do Órgão apontado como coator, existe a problemática - de maior envergadura - ligada ao direito de defesa. O processo foi deflagrado ante denúncia anônima relativa a três empregados cujo ingresso na Eletrosul se deu de forma irregular. Quanto aos impetrantes constantes (...) da deliberação do Tribunal de Contas, revela-se fiscalização dirigida contra indivíduos específicos aos quais não foi aberta oportunidade para manifestação, a resultar em ofensa ao devido processo legal. A partir do momento em que materializado, no patrimônio dos prestadores de serviços, o direito, iniciado o exercício dos novos cargos, o afastamento não prescinde do contraditório, viabilizada a manifestação dos beneficiários, o que não ocorreu. A óptica foi consagrada no verbete vinculante nº 3 da Súmula (...). No que diz respeito aos impetrantes não nominados na decisão atacada, a determinação foi no sentido de o próprio Diretor-Presidente da Eletrosul identificar situações semelhantes e aplicar o entendimento assentado. O contraditório há ser garantido no Órgão de origem, que deve cumprir a deliberação do Tribunal de Contas.","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"[ MS 26.010 , rel. min. Marco Aurélio, 1ª T, j. 21-12-2020, DJE 25 de 10-2-2021.]","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"Garantia do contraditório e da ampla defesa e inexistência de direito líquido e certo à prorrogação de contrato administrativo","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"DIREITO ADMINISTRATIVO E PROCESSUAL CIVIL. AGRAVO REGIMENTAL EM MANDADO DE SEGURANÇA. ATO DO TCU. CONTRADITÓRIO E AMPLA DEFESA. NÃO PRORROGAÇÃO DE CONTRATO ADMINISTRATIVO. INEXISTÊNCIA DE DIREITO LÍQUIDO E CERTO. 1. Não violação à Súmula Vinculante 3/STF: o pronunciamento do Tribunal de Contas limitou-se a determinar que a autoridade administrativa se abstivesse de prorrogar o contrato administrativo, firmado com a empresa ora agravante. Não houve anulação ou revogação de nenhum ato administrativo. 2. Não há direito líquido e certo à prorrogação de contrato celebrado com o poder público, mas mera expectativa de direito, subordinada à discricionariedade da Administração Pública. Deste modo, não cabe falar em violação ao contraditório e à ampla defesa. Precedente do Plenário. 3. As instâncias administrativa e judicial são, em regra, independentes e autônomas, não havendo prevenção entre ambas. E, no caso concreto, não há sequer determinações conflitantes entre elas. 4. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"[ MS 33.983 AgR , rel. min. Roberto Barroso, 1ª T, j. 15-3-2016, DJE 93 de 10-5-2016.]","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"Garantia do contraditório e da ampla defesa em razão de ato do TCU que exclua benefício de pensão","deleted":false}],"heading":false},{"page":8,"runs":[{"text":"Há precedente nesta Corte no sentido de que o Tribunal de Contas da União será parte legítima para figurar no polo passivo da ação mandamental quando, a partir de sua decisão, for determinada a exclusão de um direito. (Precedente: MS 24.927, rel. min. Cezar Peluso, DJE 28-9-2005). 2. In casu , o TCU determinou à Secretaria de Recursos Humanos do Ministério do Planejamento, Orçamento e Gestão que fossem suspensas pensões de filhas solteiras maiores de 21 anos que ocupassem cargo público efetivo. 3. A Súmula Vinculante 3 do STF excepciona a observância prévia do contraditório e da ampla defesa na apreciação da legalidade do ato de concessão de aposentadoria, reforma e pensão pelo Tribunal de Contas da União. Contudo, o presente caso","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"não se enquadra na exceção prevista, pois não se trata de concessão inicial de aposentadoria, de reforma ou de pensão. Dessa forma, podendo a decisão resultar anulação ou revogação de ato administrativo que beneficie o interessado, cabível o exercício da ampla defesa e do contraditório. No entanto, não se verifica abertura de prazo pelo TCU, a fim de que houvesse oportunidade de defesa a (...) diante da exclusão do seu benefício de pensão. 4. Portanto, não merece ser reformada a decisão agravada que anulou o acórdão 1.843/2006 do TCU para que se possibilite que (...) exerça o contraditório e a ampla defesa a que tem direito, com o restabelecimento da pensão até a nova apreciação pela Corte de Contas.","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"[ MS 27.031 AgR , rel. min. Luiz Fux, 1ª T, j. 8-9-2015, DJE 193 de 28-9-2015.]","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"Necessidade de observância do contraditório e da ampla defesa após o prazo de cinco anos a contar da aposentadoria","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"Direito Administrativo. Mandado de segurança. Tribunal de Contas da União. Negativa de registro à pensão por morte. Alegada decadência e violação ao contraditório e à ampla defesa. Revogação de liminar. Efeitos prospectivos. 1. Afastamento da alegada decadência do direito de o TCU rever o ato concessivo da pensão e da alegada violação ao contraditório e à ampla defesa, nos termos da jurisprudência consolidada deste Tribunal. 2. Não se aplica ao Tribunal de Contas da União, no exercício do controle da legalidade de aposentadoria, reforma e pensão, a decadência prevista na Lei 9.784/1999, devendo, no entanto, ser assegurado o contraditório e a ampla defesa somente se decorridos mais de cinco anos desde a entrada do processo no Tribunal de Contas.","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"[ MS 30.843 , rel. min. Roberto Barroso, dec. monocrática, j. 11-10-2017, DJE 65 de 6-4-2018.]","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"A inércia da Corte de Contas, por mais de cinco anos, a contar da aposentadoria, consolidou afirmativamente a expectativa do ex-servidor quanto ao recebimento de verba de caráter alimentar. Esse aspecto temporal diz intimamente com: a) o princípio da segurança jurídica, projeção objetiva do princípio da dignidade da pessoa humana e elemento conceitual do Estado de Direito; b) a lealdade, um dos conteúdos do princípio constitucional da moralidade administrativa ( caput do art. 37). São de se reconhecer, portanto, certas situações jurídicas subjetivas ante o poder público, mormente quando tais situações se formalizam por ato de qualquer das instâncias administrativas desse Poder, como se dá com o ato formal de aposentadoria. (...) 5. O prazo de cinco anos é de ser aplicado aos processos de contas que tenham por objeto o exame de legalidade dos atos concessivos de aposentadorias, reformas e pensões. Transcorrido in albis o interregno quinquenal, a contar da aposentadoria, é de se convocar os particulares para participarem do processo de seu interesse, a fim de desfrutar das garantias constitucionais do contraditório e da ampla defesa (art. 5º, LV).","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"[ MS 25.116 , rel. min. Ayres Britto, P, j. 8-9-2010, DJE 27 de 10-2-2011.]","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"Necessidade de observância do contraditório e da ampla defesa após o prazo de cinco anos a contar do recebimento do processo administrativo de aposentadoria ou pensão no TCU","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"Anoto, ademais, que o entendimento inicialmente firmado por esta Corte foi no sentido de que o TCU sequer se submetia aos princípios do contraditório e da ampla defesa na apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão (Súmula Vinculante 3), já que a concessão de benefício constitui ato complexo, no qual não é assegurada a participação do interessado. 5. Somente a partir do julgamento dos MS 25.116 e MS 25.403, o Supremo Tribunal Federal, em homenagem aos princípios da boa-fé e da segurança jurídica, mitigou esse entendimento, apenas para o fim de assegurar o contraditório e a ampla defesa quando ultrapassados mais de cinco anos entre a chegada do processo no TCU e a decisão da Corte de Contas. Este precedente foi publicado em 10-2-2011, sendo, portanto, superveniente à decisão do TCU sobre o benefício do ora agravante. De todo modo, no caso não transcorreram 5 (cinco) anos entre a entrada do processo no TCU, em 14-11-2003 (fl. 88), e o seu julgamento, em 14-2-2006 (decisão publicada no DOU de 17-2-2006).","deleted":false}],"heading":false},{"page":9,"runs":[{"text":"[ MS 26.069 AgR , voto do rel. min. Roberto Barroso, 1ª T, j. 24-2-2017, DJE 47 de 13-3-2017.]","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"Negativa de registro de aposentadoria julgada ilegal pelo TCU. Decisão proferida após mais de 5 (cinco) anos da chegada do processo administrativo ao TCU e após mais de 10 (dez) anos da concessão da aposentadoria pelo órgão de origem. Princípio da segurança jurídica (confiança legítima). Garantias constitucionais do contraditório e da ampla defesa. Exigência. 5. Concessão parcial da segurança. I - Nos termos dos precedentes firmados pelo Plenário desta Corte, não se opera a decadência prevista no art. 54 da Lei 9.784/1999 no período compreendido entre o ato administrativo concessivo de aposentadoria ou pensão e o posterior julgamento de sua legalidade e registro pelo Tribunal de Contas da União - que consubstancia o exercício da competência constitucional de controle externo (art. 71, III, CF/1988). II - A recente jurisprudência consolidada do STF passou a se manifestar no sentido de exigir que o TCU assegure a ampla defesa e o contraditório nos casos em que o controle externo de legalidade exercido pela Corte de Contas, para registro de aposentadorias e pensões, ultrapassar o prazo de cinco anos, sob pena de ofensa ao princípio da confiança - face subjetiva do princípio da segurança jurídica. Precedentes. III - Nesses casos, conforme o entendimento fixado no presente julgado, o prazo de 5 (cinco) anos deve ser contado a partir da data de chegada ao TCU do processo administrativo de aposentadoria ou pensão encaminhado pelo órgão de origem para julgamento da legalidade do ato concessivo de aposentadoria ou pensão e posterior registro pela Corte de Contas. IV - Concessão parcial da segurança para anular o acórdão impugnado e determinar ao TCU que assegure ao impetrante o direito ao contraditório e à ampla defesa no processo administrativo de julgamento da legalidade e registro de sua aposentadoria, assim como para determinar a não devolução das quantias já recebidas. V - Vencidas (i) a tese que concedia integralmente a segurança (por reconhecer a decadência) e (ii) a tese que concedia parcialmente a segurança apenas para dispensar a devolução das importâncias pretéritas recebidas, na forma do que dispõe a Súmula 106 do TCU.","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"[ MS 24.781 , rel. min. Ellen Gracie , red. p/ o ac. min. Gilmar Mendes, P, j. 2-3-2011, DJE 110 de 9-6-2011.]","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"Procedimento de tomada de contas","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"(...) o exame dos fundamentos subjacentes à presente causa leva-me a reconhecer a inexistência, na espécie, de situação caracterizadora de transgressão ao enunciado constante da Súmula Vinculante 3/STF. É que o ato objeto da presente reclamação foi proferido por Tribunal de Contas estadual, e não pelo E. Tribunal de Contas da União, a evidenciar que o acórdão reclamado não pode ser qualificado como transgressor da autoridade da Súmula Vinculante 3/STF, como se depreende do próprio teor do enunciado sumular ora invocado como parâmetro de controle. Esse fato - incoincidência dos fundamentos - inviabiliza o próprio conhecimento da presente reclamação pelo Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"[ Rcl 11.738 AgR , voto do rel. min. Celso de Mello, 2ª T, j. 7-10-2014, DJE 242 de 11-12-2014.]","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"A exigibilidade do contraditório pressupõe o envolvimento, no processo administrativo, de acusado ou de litígio. Descabe observá-lo em julgamento implementado pelo Tribunal de Contas da União ante auditoria realizada em órgão público.","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"[ MS 31.344 , rel. min. Marco Aurélio, 1ª T, j. 23-4-2013, DJE 89 de 14-5-2013.]","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"(...) a Súmula Vinculante 3 se dirige, única e exclusivamente, às decisões do Tribunal de Contas da União que anulem ou revoguem atos administrativos que beneficiem algum interessado, situação esta absolutamente diversa das tomadas de contas, procedimento próprio em que a Corte de Contas verifica a regularidade da utilização das verbas públicas pelos responsáveis.","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"[ Rcl 6.396 AgR , voto do rel. min. Joaquim Barbosa, P, j. 21-10-2009, DJE 213 de 13-11-2009.]","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"Rejeição da aplicação da teoria da transcendência dos motivos determinantes","deleted":false}],"heading":false},{"page":10,"runs":[{"text":"VIOLAÇÃO DA SÚMULA VINCULANTE 3. NÃO OCORRÊNCIA. APLICABILIDADE DA TEORIA DA TRANSCENDÊNCIA DOS MOTIVOS DETERMINANTES REJEITADA PELO SUPREMO. AGRAVO DESPROVIDO. I - Só é possível verificar se houve ou não descumprimento da Súmula Vinculante 3 nos processos em curso no Tribunal de Contas da União, uma vez que o enunciado, com força vinculante, apenas","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"àquela Corte se dirige. II - Este Supremo Tribunal, por ocasião do julgamento da Rcl 3.014/SP, rel. min. Ayres Britto, rejeitou a aplicação da chamada “teoria da transcendência dos motivos determinantes”. III - Agravo a que se nega provimento.","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"[ Rcl 9.778 AgR , rel. min. Ricardo Lewandowski, P, j. 26-10-2011, DJE 215 de 11-11-2011.]","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"TCU e princípios do contraditório e da ampla defesa","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"1. Nos termos da jurisprudência do STF, o ato de concessão de aposentadoria é complexo, aperfeiçoando-se somente após a sua apreciação pelo Tribunal de Contas da União, sendo, desta forma, inaplicável o art. 54, da Lei 9.784/1999, para os casos em que o TCU examina a legalidade do ato de concessão inicial de aposentadoria, reforma e pensão. 2. Inexiste afronta ao princípio do contraditório e da segurança jurídica quando a análise do ato de concessão de aposentadoria, pensão ou reforma for realizada pelo TCU dentro do prazo de cinco anos, contados da entrada do processo administrativo na Corte de Contas. 3. Os princípios do ato jurídico perfeito e da proteção ao direito adquirido não podem ser oponíveis ao ato impugnado, porquanto a alteração do contexto fático implica alteração dos fundamentos pelos quais o próprio direito se constitui. O STF adota o entendimento de que a alteração de regime jurídico garante ao servidor o direito à irredutibilidade dos proventos, mas não à manutenção do regime anterior.","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"[ MS 31.704 , rel. min. Edson Fachin, 1ª T, j. 19-4-2016, DJE 98 de 16-5-2016.]","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"(...) tenho para mim, na linha de decisões que proferi nesta Suprema Corte, que se impõe reconhecer, mesmo em se tratando de procedimento administrativo, que ninguém pode ser privado de sua liberdade, de seus bens ou de seus direitos sem o devido processo legal, notadamente naqueles casos em que se estabelece uma relação de polaridade conflitante entre o Estado, de um lado, e o indivíduo, de outro. Cumpre ter presente, bem por isso, na linha dessa orientação, que o Estado, em tema de restrição à esfera jurídica de qualquer cidadão, não pode exercer a sua autoridade de maneira abusiva ou arbitrária (...). Isso significa, portanto, que assiste ao cidadão (e ao administrado), mesmo em procedimentos de índole administrativa, a prerrogativa indisponível do contraditório e da plenitude de defesa, com os meios e recursos a ela inerentes, consoante prescreve a Constituição da República em seu art. 5º, LV. O respeito efetivo à garantia constitucional do due process of law , ainda que se trate de procedimento administrativo (como o instaurado, no caso ora em exame, perante o E. Tribunal de Contas da União), condiciona, de modo estrito, o exercício dos poderes de que se acha investida a Pública Administração, sob pena de descaracterizar-se, com grave ofensa aos postulados que informam a própria concepção do Estado Democrático de Direito, a legitimidade jurídica dos atos e resoluções emanados do Estado, especialmente quando tais deliberações, como sucede na espécie, importarem em invalidação, por anulação, de típicas situações subjetivas de vantagem.","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"[ MS 27.422 AgR , voto do rel. min. Celso de Mello, 2ª T, j. 14-4-2015, DJE 86 de 11-5-2015.]","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"Acórdão do TCU que, sem intimação da servidora interessada, determinou que se procedesse à cobrança de valores recebidos a título de adicional de dedicação exclusiva. Incidência do entendimento sumulado do Supremo Tribunal Federal. 2. Segurança concedida para garantir o exercício do contraditório e da ampla defesa.","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"[ MS 27.760 , rel. min. Ayres Britto, 2ª T, j. 20-3-2012, DJE 71 de 12-4-2012.","deleted":false}],"heading":false},{"page":11,"runs":[{"text":"AGRAVO REGIMENTAL EM MANDADO DE SEGURANÇA. ATO DE CONCESSÃO INICIAL DE PENSÃO DO MONTEPIO CIVIL DA UNIÃO. REGISTRO. LEGALIDADE DO ATO RECONHECIDA EM ACÓRDÃO DO TRIBUNAL DE CONTAS DA UNIÃO. DETERMINAÇÃO DA CORTE DE CONTAS DE ALTERAÇÃO DO PAGAMENTO DA PENSÃO POR SUPOSTA OCORRÊNCIA DE UNIÃO ESTÁVEL SUPERVENIENTE. CONTRADITÓRIO E AMPLA DEFESA. AUSÊNCIA. SÚMULA VINCULANTE 3. INCIDÊNCIA. SEGURANÇA CONCEDIDA. JULGAMENTO MONOCRÁTICO. POSSIBILIDADE. 1. O Tribunal de Contas da União considerou legal o ato de concessão inicial de pensão do montepio civil da União em favor da impetrante e de sua irmã, ordenando o seu registro. 2. A Corte de Contas também determinou a adoção de medidas com o","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"objetivo de efetuar a alteração dessa pensão para que a irmã da impetrante passasse a ser a única beneficiária, com fundamento em suposta ocorrência de união estável superveniente. 3. Necessidade de garantir-se à impetrante o exercício do contraditório e da ampla defesa quanto à suposta união estável por ela mantida. 4. Incidência na espécie da Súmula Vinculante 3. 5. Cassação do acórdão do Tribunal de Contas da União para restabelecer o pagamento integral da pensão até que seja proferida nova decisão pela Corte de Contas.","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"[ MS 28.061 AgR , rel. min. Ellen Gracie, P, j. 2-3-2011, DJE 68 de 11-4-2011.]","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"Terceiro interessado e garantia do contraditório e da ampla defesa","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"(...) a Súmula Vinculante 3 tem como objetivo resguardar os princípios do contraditório e a ampla defesa no âmbito do Tribunal de Contas da União sempre que, de sua decisão, puder resultar anulação ou revogação de ato que beneficie o interessado, excetuada a apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão. Entretanto, não se infere daquele enunciado sumular interpretação que garanta ao terceiro eventualmente prejudicado pela decisão da Corte de Contas a possibilidade ser considerado como parte no procedimento administrativo, uma vez que, como evidenciam as disposições do Regimento Interno do TCU acerca da fiscalização de atos e contratos, tal procedimento fiscalizatório dá-se entre o órgão fiscalizador e a entidade fiscalizada, sendo suficiente para garantir o contraditório a previsão do art. 250, V, do RITCU, que assim dispõe: “Art. 250. Ao apreciar processo relativo à fiscalização de atos e contratos, o relator ou o Tribunal: (...) V - determinará a oitiva da entidade fiscalizada e do terceiro interessado para, no prazo de quinze dias, manifestarem-se sobre fatos que possam resultar em decisão do Tribunal no sentido de desconstituir ato ou processo administrativo ou alterar contrato em seu desfavor.” (...) Sendo assim, como também posto na decisão embargada, não se evidencia, prima facie , qualquer afronta aos princípios do contraditório e da ampla defesa, tendo em conta que a embargante foi notificada para apresentar manifestação, nos termos do art. 250, V, do RITCU, mantendo-se, entretanto, inerte.","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"[ MS 35.739 MC-ED , rel. min. Edson Fachin, dec. monocrática, j. 1º-8-2018, DJE 159 de 7-8-2018.]","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":12,"runs":[{"text":"● Ver Súmula 6 e Súmula 473.","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"● Tema 445 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"Data de publicação do enunciado: DJE de 6-6-2007.","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":12,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"4","number":"4","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":13,"endPage":20,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1195","paragraphs":[{"page":13,"runs":[{"text":"Salvo nos casos previstos na Constituição, o salário mínimo não pode ser usado como indexador de base de cálculo de vantagem de servidor público ou de empregado, nem ser substituído por decisão judicial.","deleted":false}]}],"notes":[{"page":13,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":13,"runs":[{"text":"INCONSTITUCIONALIDADE DE VINCULAÇÃO DO ADICIONAL DE INSALUBRIDADE AO SALÁRIO MÍNIMO: PRECEDENTES. IMPOSSIBILIDADE DA MODIFICAÇÃO DA BASE DE CÁLCULO DO BENEFÍCIO POR DECISÃO JUDICIAL. RECURSO EXTRAORDINÁRIO AO QUAL SE NEGA PROVIMENTO. O sentido da vedação constante da parte final do inciso IV do art. 7º da CF/1988 impede que o salário mínimo possa ser aproveitado como fator de indexação (...). A norma constitucional tem o objetivo de impedir que aumento do salário mínimo gere, indiretamente, peso maior do que aquele diretamente relacionado com o acréscimo. Essa circunstância pressionaria reajuste menor do salário mínimo, o que significaria obstaculizar a implementação da política salarial prevista no art. 7º, IV, da Constituição da República. O aproveitamento do salário mínimo para formação da base de cálculo de qualquer parcela remuneratória ou com qualquer outro objetivo pecuniário (indenizações, pensões, etc.) esbarra na vinculação vedada pela Constituição do Brasil.","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"[ RE 565.714 , rel. min. Cármen Lúcia , P, j. 30-4-2008, DJE 147 de 8-8-2008, republicação no DJE 211 de 7-11-2008, Tema 25.]","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":13,"runs":[{"text":"● A fixação de multa administrativa em múltiplos do salário mínimo não viola o disposto no art. 7º, IV, da Constituição Federal.","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"[Tese definida no ARE 1.409.059 , rel. min. Gilmar Mendes , P, j. 5-11-2025, DJE s/n 27-11-2025, Tema 1.244.]","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"● Afronta o art. 7º, inciso IV, da Constituição Federal a adoção do salário mínimo como base de cálculo para a fixação de piso salarial.","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"[Tese definida no RE 603.451 RG , rel. min. Ellen Gracie , P, j. 11-3-2010, DJE 71 de 23-4-2010, Tema 256.]","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"(...) o Tribunal de origem consignou que o salário mínimo não foi utilizado como indexador para futuras revisões no valor da remuneração do recorrido, mas apenas para encontrar o valor base daquela e que, após, as atualizações foram realizadas com índice diverso. Desse modo, não há ofensa à Súmula Vinculante nº 4, visto que não houve a alegada utilização do salário mínimo como indexador para futuras atualizações da remuneração do recorrido (...).","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"[ ARE 1.473.461 AgR , rel. min. Gilmar Mendes , 2ª T, j. 13-5-2024, DJE de 20-5-2024]","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"(...) verifico que o acórdão proferido pelo Tribunal de origem (...) está em consonância com a jurisprudência firmada no âmbito desta Corte, segundo a qual não há vedação para a fixação de piso salarial em múltiplos do salário mínimo, desde que inexistam reajustes automáticos. No caso, não se vislumbra afronta à Súmula Vinculante 4, uma vez que o ato reclamado não determinou a utilização do salário mínimo como indexador, mas apenas reconheceu a possibilidade de aplicação do piso salarial previsto na Lei 4.950-A/1966, estabelecendo, expressamente, a vedação de sua utilização como fator de correção da remuneração.","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"[ Rcl 32.029 , rel. min. Gilmar Mendes , dec. monocrática, j. 3-10-2018, DJE 214 de 8-10-2018.]","deleted":false}],"heading":false},{"page":13,"runs":[{"text":"DIREITO ADMINISTRATIVO E PROCESSUAL CIVIL. AGRAVO INTERNO EM RECLAMAÇÃO. VINCULAÇÃO DE REAJUSTES AO SALÁRIO MÍNIMO. EXTRAPOLAÇÃO DOS LIMITES OBJETIVOS DA COISA JULGADA","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"NA FASE DE LIQUIDAÇÃO. IMPOSSIBILIDADE. 1. A verificação a respeito da ocorrência do trânsito em julgado deve levar em conta a viabilidade de rediscussão, em grau recursal, do conteúdo da decisão reclamada. Se a decisão impugnada na reclamação, proferida em sede de execução, não foi alcançada pela preclusão, inaplicável a Súmula 734/STF. 2. Viola a Súmula Vinculante 4 decisão que, extrapolando os limites objetivos da coisa julgada, determina, em sede de execução, o reajuste periódico de piso de categoria e dos padrões remuneratórios escalonados de carreira de servidores públicos com base no salário mínimo.","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"[ Rcl 25.784 AgR , rel. min. Roberto Barroso , 1ª T, j. 29-6-2018, DJE 157 de 6-8-2018.]","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"Verifica-se que o Supremo Tribunal Federal, no julgamento do RERG 603.451, Rel. Min. Rosa Weber, DJe 20.2.2015 (Tema 256), manteve a orientação já consolidada na Súmula Vinculante 4 de que o salário mínimo não pode ser usado como indexador de base de cálculo de vantagem de servidor público ou de empregado, nem ser substituído por decisão judicial. No entanto, tendo em vista que o caso em questão guarda certas peculiaridades, deixo de efetuar a devolução para adequação ao disposto no art. 328 do RISTF. A manutenção da estrutura de cargos e salários implementada pela FEPASA a partir do piso salarial da categoria, de 2,5 salários mínimos, quando sub judice a controvérsia, demanda a análise da legislação infraconstitucional aplicável à espécie, Lei Estadual 9.343/96, bem como a interpretação das cláusulas do acordo coletivo de trabalho e o acervo fático-probatório constante dos autos, o que atrai o óbice das Súmulas 279, 280 e 454 desta Corte.","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"[ ARE 1.078.369 , rel. min. Edson Fachin , dec. monocrática, j. 7-5-2018, DJE 90 de 10-5-2018.]","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"● Salvo nos casos previstos na Constituição, o salário mínimo não pode ser usado como indexador de base de cálculo de vantagem de servidor público ou de empregado, nem ser substituído por decisão judicial.","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"[ RE 565.714 , rel. min. Cármen Lúcia , P, j. 30-4-2008, DJE 147 de 8-8-2008, republicação no DJE 211 de 7-11-2008, Tema 25.]","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"SEGUNDO AGRAVO REGIMENTAL NA RECLAMAÇÃO. DIREITO CONSTITUCIONAL E DIREITO DO TRABALHO. EMPREGADOS DO HOSPITAL DAS FORÇAS ARMADAS. ADICIONAL DE INSALUBRIDADE. BASE DE CÁLCULO. ALTERAÇÃO. PISO SALARIAL. DECISÃO JUDICIAL. DESCUMPRIMENTO DA SÚMULA VINCULANTE 4 DO SUPREMO TRIBUNAL FEDERAL. OCORRÊNCIA. AGRAVO REGIMENTAL A QUE SE NEGA PROVIMENTO. 1. A alteração da base de cálculo do adicional de insalubridade por decisão judicial encontra óbice na proibição imposta ao Poder Judiciário de atuar como legislador positivo. 2. Pronunciamento judicial ensejador da substituição da base de cálculo de vantagem de empregado público, ausente lei ou convenção coletiva definindo-a, contraria a autoridade da Súmula Vinculante 4 do Supremo Tribunal Federal. 3. In casu , a decisão reclamada estabeleceu nova base de cálculo para o adicional de insalubridade dos empregados do Hospital das Forças Armadas, com fundamento no piso salarial previsto no anexo I da Lei 10.225/2001. Entretanto, essa norma legal não fixou nova base de cálculo, nem há notícia de convenção coletiva determinando parâmetro diverso do salário mínimo.","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"[ Rcl 13.685 AgR-segundo , rel. min. Luiz Fux , 1ª T, j. 28-4-2015, DJE 89 de 14-5-2015.]","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"O Plenário deste Tribunal, apreciando o RE 565.714, relatado pela ministra Cármen Lúcia, decidiu não ser legítimo o cálculo do adicional de insalubridade com base no valor da remuneração percebida pelo servidor. No entanto, apesar de se também reconhecer a proibição constitucional da vinculação de qualquer vantagem ao salário mínimo, o Supremo entendeu que o Judiciário não poderia substituir a base de cálculo do benefício, sob pena de atuar como legislador positivo.","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"[ RE 642.633 AgR , rel. min. Joaquim Barbosa , 2ª T, j. 4-10-2011, DJE 204 de 24-10-2011.]","deleted":false}],"heading":false},{"page":14,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":14,"runs":[{"text":"Fixação da base de cálculo pelo Poder Judiciário em caso de omissão legislativa","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"(...) O ato impugnado manteve a sentença de 1ª instância, que fixou o salário base da servidora como parâmetro para o cálculo sobre o qual deve incidir a fração para pagamento do adicional de insalubridade, substituindo o salário mínimo, baseado na ausência de lei regulamentadora. 2. Sanção, no âmbito do município de São José do Rio Preto, da Lei Complementar 609/2019, que instituiu a base de cálculo para os adicionais de insalubridade e periculosidade. 3. Nessas circunstâncias, há violação ao Enunciado Vinculante 4, tendo em vista que, após a regulamentação normativa fixando a base de cálculo sobre a qual deve incidir a fração para pagamento do adicional de insalubridade, não cabe ao Poder Judiciário atuar como legislador positivo, sob pena de desequilibrar o Princípio da Separação dos Poderes.","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"[ Rcl 39.952 AgR , rel. min. Rosa Weber, red. p/ o ac. min. Alexandre de Moraes, 1ª T, j. 15-3-2021, DJE 58 de 26-3-2021.]","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"I - É vedada a substituição, por meio de decisão judicial, do salário mínimo estabelecido por lei como base de cálculo do adicional de insalubridade. II - A jurisprudência do STF considera possível a fixação, por decisão judicial, do vencimento básico do servidor público como base de cálculo do adicional de insalubridade, quando houver omissão legislativa em dispor sobre a questão.","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"[ RE 987.079 AgR , rel. min. Ricardo Lewandowski, 2ª T, j. 31-3-2017, DJE 74 de 11-4-2017.]","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"A jurisprudência de ambas as Turmas desta Corte evoluiu para afirmar o entendimento de que não viola os arts. 2º; 5º, II; 7º, IV; e 37, caput , da Constituição da República nem contraria a Súmula Vinculante 4 do STF a decisão que, face a lacuna normativa, fixa o vencimento básico como base de cálculo do adicional de insalubridade devido a servidor municipal. Precedentes. 2. Não se conhece dos embargos de divergência quando firmada a jurisprudência de ambas as Turmas no sentido da decisão embargada (art. 332 do RISTF), a evidenciar a superação da tese assentada no aresto cotejado. Embargos de divergência não conhecidos.","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"[ RE 673.644 AgR-EDv , rel. min. Rosa Weber, P, j. 6-10-2016, DJE 226 de 24-10-2016.]","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"Não obstante o afastamento da incidência da norma em comento, em virtude da proibição constitucional de vinculação de qualquer vantagem de servidor público ou empregado ao salário mínimo (art. 7º, IV, da CF/1988), decidiu-se pela impossibilidade da modificação da base de cálculo do adicional de insalubridade pelo Poder Judiciário, dada a vedação de esse atuar como legislador positivo. Essa orientação foi consolidada na Súmula Vinculante 4. No entanto, conforme ressaltei na decisão agravada, entendo que, no presente caso, não houve ofensa à CF/1988, uma vez que o Poder Judiciário, pelo princípio da inafastabilidade da jurisdição, apenas preencheu a lacuna da lei ao fixar a base de cálculo do adicional de insalubridade, diante da ausência de legislação local que a fixasse, já que a Lei municipal 494/1974, em seu art. 134, VII, previu o direito ao adicional, mas não dispôs qual seria a base de cálculo, o que tornaria o direito da servidora inexequível.","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"[ RE 687.395 AgR , voto do rel. min. Dias Toffoli, 1ª T, j. 4-2-2014, DJE 46 de 10-3-2014.]","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"Base de cálculo do adicional de insalubridade. 4. Ausência de legislação local que discipline o tema. 5. Vedação de vinculação da base de cálculo do referido adicional ao salário mínimo. Jurisprudência do STF. 6. Acórdão do Tribunal de origem que, ante a omissão legislativa e a impossibilidade de vinculação ao salário mínimo, fixa a base de cálculo do adicional de insalubridade de acordo com os vencimentos básicos do servidor. Não há contrariedade à orientação fixada pelo STF, que apenas veda ao Poder Judiciário a alteração do indexador legalmente estabelecido, o que não ocorreu no caso dos autos.","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"[ RE 635.669 AgR , rel. min. Gilmar Mendes, 2ª T, j. 28-8-2012, DJE 182 de 17-9-2012.]","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"Fixação do quantum indenizatório com base no salário mínimo","deleted":false}],"heading":false},{"page":15,"runs":[{"text":"RECLAMAÇÃO - ALEGADA TRANSGRESSÃO AO TEOR DA SÚMULA VINCULANTE Nº 04/STF - DETERMINAÇÃO, PELO PODER JUDICIÁRIO, DE SUBSTITUIÇÃO DA BASE DE CÁLCULO DO ADICIONAL DE INSALUBRIDADE (SALÁRIO MÍNIMO PARA VENCIMENTO BÁSICO) - INADMISSIBILIDADE - PRECEDENTES - RECLAMAÇÃO PROCEDENTE.","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"[ Rcl 41.284 , rel. min. Celso de Mello, 2ª T, j. 10-10-2020, DJE 249 de 15-10-2020.]","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"A jurisprudência do STF admite o uso do salário mínimo como fixador inicial de condenação, desde que não haja atrelamento para fins de atualização. Nesta hipótese, não há afronta à Súmula Vinculante 4 ou ao art. 7º, IV, da CRFB/1988.","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"[ Rcl 19.193 AgR , rel. min. Roberto Barroso, 1ª T, j. 7-6-2016, DJE 171 de 16-8-2016.]","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"Impossibilidade de indexação da gratificação de função especializada ao salário mínimo","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"(...) Esse não é o entendimento adotado pela Primeira e Segunda Turmas deste Supremo Tribunal, que decidiu haver ofensa à Súmula Vinculante n. 4 a indexação da gratificação de função especializada ao salário-mínimo. (...) Não se há cogitar, portanto, de ser possível indexar ao salário-mínimo regional a gratificação de função especializada prevista na Lei municipal n. 3.272/1985, em observância à Súmula Vinculante n. 4 deste Supremo Tribunal. No ponto, a conclusão adotada no acórdão recorrido diverge da jurisprudência firmada por este Supremo Tribunal. 5. Pelo exposto, dou parcial provimento ao presente recurso extraordinário (al. b do inc. V do art. 932 do Código de Processo Civil e § 1º do art. 21 do Regimento Interno do Supremo Tribunal Federal) para, nos termos da Súmula Vinculante n. 4 deste Supremo Tribunal, anular o julgado recorrido e determinar a remessa dos autos à Turma Recursal de origem para decidir como de direito.","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"[ RE 1.417.391 , rel. min. Cármen Lúcia, dec. monocrática, j. 7-2-2023, DJE 32 de 23-2-2023.]","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"Impossibilidade de vinculação do adicional de insalubridade ao salário mínimo","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"1. Nas discussões relativas à Súmula Vinculante nº 4, o Supremo Tribunal Federal assentou ser inconstitucional a utilização do salário mínimo como base de cálculo do adicional de insalubridade, mas determinou que o critério legal não pode ser substituído por decisão judicial, o que ocorreu na espécie. 2. Ao afastar a lei municipal que vincula o valor do adicional de insalubridade ao salário mínimo, substituindo-o, por decisão judicial, pelos vencimentos básicos do servidor municipal, a autoridade reclamada descumpriu a parte final do que foi assentado na Súmula Vinculante nº 4 do Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"[ Rcl 63.448 AgR , rel. min. Dias Toffoli, 2ª T, j. 25-3-2024, DJE s/n de 15-4-2024.]","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"Inadmissibilidade de reclamação por ausência de identidade com a Súmula Vinculante 4","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"Agravo regimental na reclamação. Artigo 5º da Lei Federal 4.950-A/1966. Fixação do piso salarial do trabalhador em múltiplos do salário mínimo vigente ao tempo da contratação. Reajustes remuneratórios subsequentes de acordo com a convenção coletiva da categoria respectiva. Súmula Vinculante 4 e ADPF 53/PI. Vedação de indexação do salário mínimo para reajustes remuneratórios. Ausência de aderência estrita entre o ato reclamado e o paradigma da Corte. Agravo regimental não provido. 1. A aderência estrita do objeto do ato reclamado ao conteúdo das decisões paradigmas é requisito de admissibilidade da reclamação constitucional. 2. A manutenção dos critérios estabelecidos em lei anterior à Constituição de 1988, dissociando-os da indexação pelo salário mínimo mediante a fixação do momento em que apurado o valor do direito prescrito na norma, não possui aderência estrita com a Súmula Vinculante 4 e a ADPF 53/PI.","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"[ Rcl 16.831 AgR , rel. min. Dias Toffoli, 2ª T, j. 7-11-2017, DJE 261 de 17-11-2017.]","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"Constitucional. Reclamação. Servidor público. Remuneração. Fixação de piso salarial por meio de acordo trabalhista celebrado no ano de 1987. Liminar que restabelece a remuneração dos servidores interessados nos termos do ajuste. Alegação de afronta à Súmula Vinculante 4. Não ocorrência. Ausência de identidade entre a decisão reclamada e a referida súmula vinculante. Inadmissibilidade da reclamação. 1. Não há identidade entre o objeto Súmula Vinculante 4 e o objeto de liminar que, sem vincular ou indexar os vencimentos dos servidores interessados ao salário mínimo vigente, apenas determina o cumprimento de acordo trabalhista, celebrado no ano de 1987, em respeito aos princípios da coisa julgada, do ato jurídico perfeito e da irredutibilidade dos vencimentos.","deleted":false}],"heading":false},{"page":16,"runs":[{"text":"[ Rcl 13.236 AgR-segundo , rel. min. Teori Zavascki, P, j. 17-10-2013, DJE 223 de 12-11-2013.]","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 4 quando o adicional de insalubridade for calculado sobre vencimento pago ao servidor público","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"(...) Na espécie, conforme consignado na decisão reclamada referente à alteração do art. 72 da Lei nº 891/2008 promovida pela Lei nº 1.422/2017, em que pese a base de cálculo estipulada como “o menor vencimento pago ao servidor público do Município de Nova Prata do Iguaçu, independente da classe,” coincidir com o salário mínimo, não há previsão expressa do salário mínimo como base de cálculo do adicional de insalubridade o que, por certo, não revela contrariedade ao enunciado da Súmula Vinculante nº 4. (...)","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"[ Rcl 69.451 , rel. min. Dias Toffoli, dec. monocrática, j. 28-6-2024, DJE s/n de 2-7-2024.]","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Incabível a utilização do salário mínimo como indexador para benefícios previdenciários","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Não há direito adquirido à forma de reajustamento com base em múltiplos do salário mínimo, tendo em vista a vedação constitucional expressa (art. 7º, IV, CF) e o enunciado da Súmula Vinculante 4, que proíbe a utilização do salário mínimo como indexador, inclusive para benefícios previdenciários.","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"[ ARE 1.564.781 AgR , rel. min. Gilmar Mendes, 2ª T, j. 5-11-2025, DJE s/n 11-11-2025.]","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Incabível a vinculação dos reajustes da aposentadoria ao salário mínimo estadual","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Como já demonstrado na decisão agravada, na hipótese, o Tribunal de origem, com base na Lei 10.394/1970, consignou que o reajuste da aposentadoria da ora agravante deveria observar o critério do salário mínimo regional, afastando o entendimento firmado por esta Corte na Súmula Vinculante 4. Não obstante, reitero que o decidido pela instância a quo, acerca da vinculação dos reajustes da aposentadoria ao salário mínimo estadual, encontra-se em dissonância com a jurisprudência do Supremo Tribunal Federal, segundo a qual a indexação de benefício pago a servidor pelo salário mínimo é inconstitucional. Não obstante, reitero que o decidido pela instância a quo, acerca da vinculação dos reajustes da aposentadoria ao salário mínimo estadual, encontra-se em dissonância com a jurisprudência do Supremo Tribunal Federal, segundo a qual a indexação de benefício pago a servidor pelo salário mínimo é inconstitucional.","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"[ RE 1.440.074 AGR , rel. min. Gilmar Mendes, 2ª T, j. 19-08-2024, DJE s/n de 23-08-2024.]","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Proibição de fixação de piso salarial em múltiplos do salário mínimo quando implique em reajustes automáticos","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Com efeito, o Tribunal de origem entendeu que a Orientação Jurisprudencial 71 da SbDI-2 do TST, que autoriza a aplicação da Lei 4.950-A/1966, que fixa o salário mínimo profissional de engenheiros e outras categorias afins em múltiplos do salário mínimo, não ofende a Súmula Vinculante 4 (...). A proibição de indexação ao salário mínimo abrange os casos em que o aumento do valor do salário mínimo sempre implicar em reajuste automático da base de cálculo em questão. Portanto, não há vedação para a fixação de piso salarial em múltiplos do salário mínimo, desde que inexistam reajustes automáticos. Dessa forma, verifica-se que o acórdão recorrido, ao aplicar a OJ 71, da SBDI-2 do TST, não afrontou a Súmula Vinculante 4, nem a ADPF 53 MC.","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"[ ARE 922.319 AgR , rel. min. Edson Fachin, 2ª T, j. 20-4-2017, DJE 89 de 2-5-2017.]","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"A proibição de indexação ao salário mínimo abrange os casos em que o aumento do valor do salário mínimo sempre implicar em reajuste automático da base de cálculo em questão. Portanto, não há vedação para a fixação de piso salarial em múltiplos do salário mínimo, desde que inexistam reajustes automáticos. Por outro lado, não cabe ao Poder Judiciário atuar como legislador positivo, alterando salário profissional previsto em lei.","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"[ Rcl 9.951 AgR , voto do rel. min. Edson Fachin, 1ª T, j. 8-9-2015, DJE 193 de 28-9-2015.]","deleted":false}],"heading":false},{"page":17,"runs":[{"text":"Súmula Vinculante 4 e o emprego de múltiplos de salário mínimo para fixação do valor inicial da condenação","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"(...) a jurisprudência do Supremo Tribunal Federal é firme no sentido de que a inconstitucionalidade da vinculação do salário mínimo restringe-se à sua utilização como índice de atualização, sem impedimento de seu emprego para fixação do valor inicial da condenação, a qual deve ser corrigida, daí em diante, pelos índices oficiais de atualização.","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"[ ARE 1.057.945 AgR , voto do rel. min. Gilmar Mendes, 2ª T, j. 29-9-2017, DJE 232 de 10-10-2017.]","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"(...) não há afronta à Súmula Vinculante 4 deste Supremo Tribunal Federal, pois pela decisão impugnada não se determinou a utilização do salário mínimo como indexador, ou seja, o salário profissional, após fixado em múltiplos de salários mínimos, nos termos da Lei 4.950-A/1966, não segue os aumentos do salário mínimo. A jurisprudência deste Supremo Tribunal consolidou-se no sentido de que a inconstitucionalidade da vinculação do salário mínimo restringe-se à sua utilização como índice de atualização, sem impedimento de seu emprego para fixação do valor inicial da condenação, a qual deve ser corrigida, daí em diante, pelos índices oficiais de atualização.","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"[ Rcl 18.356 AgR , voto da rel. min. Cármen Lúcia, 2ª T, j. 11-11-2014, DJE 228 de 20-11-2014.]","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"Súmula 228 do TST e violação à Súmula Vinculante 4 do STF","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"Após a edição do referido verbete por esta Corte Suprema, o Tribunal Superior do Trabalho deu nova redação à Súmula 228 daquela Corte, que passou a conter a seguinte diretriz: “A partir de 9 de maio de 2008, data da publicação da Súmula Vinculante 4 do Supremo Tribunal Federal, o adicional de insalubridade será calculado sobre o salário básico, salvo critério mais vantajoso fixado em instrumento coletivo”. Todavia, no julgamento de pedido liminar deduzido na Rcl 6.266/DF, o então presidente, ministro Gilmar Mendes, determinou a suspensão da aplicação da Súmula 228 do Tribunal Superior do Trabalho, na parte em que permite a utilização do salário básico para calcular o adicional de insalubridade (...). Note-se que, no presente caso, o Tribunal Superior do Trabalho, em observân-cia à Súmula Vinculante 4, entendeu que “a utilização do salário mínimo como indexador do adicional de insalubridade, no caso, apesar de incompatível com a ordem judicial atual, deve ser mantida até que se edite lei ou norma coletiva superando tal incompatibilidade” (e-STF, doc. 11, p. 7). Com efeito, não compete ao Poder Judiciário estipular base de cálculo não fixada em lei ou norma coletiva, sob pena de atuar como legislador positivo.","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"[ Rcl 13.860 , rel. min. Rosa Weber, dec. monocrática, j. 11-3-2014, DJE 050 de 14-03-2014.]","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"(...) com base no que ficou decidido no RE 565.714/SP e fixado na Súmula Vinculante 4, este Tribunal entendeu que não é possível a substituição do salário mínimo, seja como base de cálculo, seja como indexador, antes da edição de lei ou celebração de convenção coletiva que regule o adicional de insalubridade. Logo, à primeira vista, a nova redação estabelecida para a Súmula 228/TST revela aplicação indevida da Súmula Vinculante 4, porquanto permite a substituição do salário mínimo pelo salário básico no cálculo do adicional de insalubridade sem base normativa. Ante o exposto, defiro a medida liminar para suspender a aplicação da Súmula 228/TST na parte em que permite a utilização do salário básico para calcular o adicional de insalubridade.","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"[ Rcl 6.266 MC , min. Gilmar Mendes, dec. monocrática proferida no exercício da Presidência, j. 15-7-2008, DJE 144 de 5-8-2008.]","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"Vinculação ao salário mínimo por acordo judicial trabalhista ou por norma coletiva e mudança do regime celetista para o estatutário","deleted":false}],"heading":false},{"page":18,"runs":[{"text":"AGRAVO INTERNO. RECURSO EXTRAORDINÁRIO. DIREITO CONSTITUCIONAL E ADMINISTRATIVO. SERVIDORES PÚBLICOS DO MUNICÍPIO DE NATAL. SALÁRIO BASE. VINCULAÇÃO AO SALÁRIO MÍNIMO POR NORMA COLETIVA. TRANSPOSIÇÃO DO REGIME CELETISTA AO ESTATUTÁRIO. VIOLAÇÃO À SÚMULA VINCULANTE 4. OCORRÊNCIA. INEXISTÊNCIA DE DIREITO ADQUIRIDO A REGIME JURÍDICO. DECISÃO AGRAVADA EM CONFORMIDADE COM A JURISPRUDÊNCIA DO SUPREMO TRIBUNAL FEDERAL. 1. Decisão agravada em conformidade com a jurisprudência desta CORTE","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"no sentido de que a transposição do regime celetista para o estatutário determina a perda das vantagens inerentes à situação anterior, pois não há direito adquirido a regime jurídico.","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"[ RE 754.561 AgR , rel. min. Alexandre Moraes, 1ª T, j. 27-4-2018, DJE 90 de 10-5-2018.]","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"Vinculação do salário-base da categoria ao salário-mínimo por meio de acordo homologado pela Justiça do Trabalho","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"O entendimento assinalado na decisão agravada não diverge da jurisprudência firmada no Supremo Tribunal Federal, cristalizada no enunciado da Súmula Vinculante nº 04: “Salvo nos casos previstos na Constituição, o salário mínimo não pode ser usado como indexador e base de cálculo de vantagem de servidor público ou de empregado, nem ser substituído por decisão judicial”. Nesse sentido, o acordo judicial firmado entre servidores e o Município do Natal, que vincula o salário-base da respectiva categoria ao salário mínimo, ainda que homologado pela Justiça do Trabalho, viola o Enunciado da Súmula Vinculante nº 4 desta Suprema Corte.","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"[ ARE 708.018 AgR-terceiro , rel. Min. Rosa Weber, 1ª T, j. 22-5-2020, DJE 141 de 8-6-2020.]","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"Vinculação excepcional e transitória ao salário mínimo e superveniência de legislação","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"(...) Como evidenciado na decisão agravada, o entendimento adotado pelo Tribunal de origem diverge da orientação jurisprudencial firmada por este Supremo Tribunal, no sentido de não haver direito adquirido a regime jurídico previdenciário quanto à indexação de benefício pago a servidor pelo salário mínimo (Súmula Vinculante n. 4 deste Supremo Tribunal) e à manutenção da alíquota de 5% da contribuição previdenciária. (...) 6. Também ficou assentado na decisão questionada que, em 8.8.2022, esta Primeira Turma reafirmou a orientação jurisprudencial de que a exceção prevista na Ação Direta de Inconstitucionalidade n. 4.420/SP aplica-se somente ao direito adquirido a aposentar-se, não sendo extensível à revisão dos proventos com vinculação ao salário mínimo e à majoração de alíquota de contribuição previdenciária dos aposentados, mesmo nas situações em que preenchidos os requisitos para aposentadoria antes da entrada em vigor da Lei estadual n. 14.016/2010 (...)","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"[ RE 1.418.004 AgR , rel. min. Cármen Lúcia, 1ª T, j. 3-4-2023, DJE de 10-4-2023.]","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"(...) apenas para casos de omissão legislativa o Plenário do STF, no julgamento do RE 672.634-AgR-EDv-AgR, Relª. Minª. Cármen Lúcia, decidiu que não há divergência entre as Turmas desta Corte no sentido de que “não viola a Constituição a decisão do Tribunal que, em razão da omissão legislativa, fixa o vencimento básico do servidor como base de cálculo do adicional de insalubridade” (grifos nossos). (...)10. De modo que, quando a lei estipular essa base de cálculo, não cabe ao Poder Judiciário substituí-la por outra. Nessa perspectiva, considerando que, na hipótese, há legislação estadual que fixa o salário mínimo como indexador da base de cálculo do adicional de insalubridade, não poderia o Tribunal de origem alterá-lo para utilizar como parâmetro cálculo diverso do estipulado na lei.","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"[ RE 1.438.470 , rel. min. Roberto Barroso, dec. monocrática, j. 20-6-2023, DJE s/n de 22-6-2023.]","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"AGRAVO REGIMENTAL NA RECLAMAÇÃO. DIREITO CONSTITUCIONAL. SERVIDORES MUNICIPAIS. SALÁRIO-BASE. VINCULAÇÃO AO SALÁRIO MÍNIMO. DECISÃO JUDICIAL. DESCUMPRIMENTO DA SÚMULA VINCULANTE 4 DO SUPREMO TRIBUNAL FEDERAL. OCORRÊNCIA. AGRAVO REGIMENTAL A QUE SE NEGA PROVIMENTO. 1. O acordo judicial firmado entre servidores e o município de natal que vincula o salário-base da respectiva categoria ao salário mínimo vulnera o enunciado da súmula vinculante 4. 2. A superveniência de lei local, alterando a base de cálculo dos vencimentos-base dos servidores, sem indexá-los ao salário mínimo, não contraria o postulado da segurança jurídica, porquanto é pacífica a jurisprudência da corte no sentido de que inexiste direito adquirido a regime jurídico. 3. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":19,"runs":[{"text":"[ Rcl 15.024 AgR , rel. min. Luiz Fux, 1ª T, j. 15-12-2015, DJE 28 de 16-2-2016.]","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"Arguição de Descumprimento de Preceito Fundamental. Direito do Trabalho. Art. 16 da Lei 7.394/1985. Piso salarial dos técnicos em radiologia. Adicional de insalubridade. Vinculação ao salário mínimo. Súmula Vinculante 4. Impossibilidade de fixação de piso salarial com base em múltiplos do salário mínimo. (...) O art. 16 da Lei 7.394/1985 deve ser declarado ilegítimo, por não recepção, mas os critérios estabelecidos pela referida lei devem continuar sendo aplicados, até que sobrevenha norma que fixe nova base de cálculo, seja lei federal, editada pelo Congresso Nacional, sejam convenções ou acordos coletivos de trabalho, ou, ainda, lei estadual, editada conforme delegação prevista na LC 103/2000. 3. Congelamento da base de cálculo em questão, para que seja calculada de acordo com o valor de dois salários mínimos vigentes na data do trânsito em julgado desta decisão, de modo a desindexar o salário mínimo. Solução que, a um só tempo, repele do ordenamento jurídico lei incompatível com a Constituição atual, não deixa um vácuo legislativo que acabaria por eliminar direitos dos trabalhadores, mas também não esvazia o conteúdo da decisão proferida por este Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"[ ADPF 151 MC , rel. min. Joaquim Barbosa, red. p/ o ac. min. Gilmar Mendes, P, j. 2-2-2011, DJE 84 de 6-5-2011.]","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":20,"runs":[{"text":"● Ver Súmula Vinculante 15, Súmula Vinculante 16 e Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"● A PSV 53, que requereu o cancelamento da Súmula Vinculante 4, foi rejeitada pelo Plenário do STF em 12-3-2019.","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"Data de publicação do enunciado: DJE de 9-5-2008.","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":20,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"5","number":"5","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":21,"endPage":25,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1199","paragraphs":[{"page":21,"runs":[{"text":"A falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição.","deleted":false}]}],"notes":[{"page":21,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":21,"runs":[{"text":"Na espécie, o único elemento apontado pelo acórdão recorrido como incompatível com o direito de ampla defesa consiste na ausência de defesa técnica na instrução do processo administrativo disciplinar em questão. Ora, se devidamente garantido o direito (i) à informação, (ii) à manifestação e (iii) à consideração dos argumentos manifestados, a ampla defesa foi exercida em sua plenitude, inexistindo ofensa ao art. 5º, LV, da CF/1988. (...) Por si só, a ausência de advogado constituído ou de defensor dativo com habilitação não importa nulidade de processo administrativo disciplinar (...). Ressalte-se que, mesmo em determinados processos judiciais - como no habeas corpus , na revisão criminal, em causas da Justiça Trabalhista e dos Juizados Especiais -, esta Corte assentou a possibilidade de dispensa da presença de advogado. (...) Nesses pronunciamentos, o Tribunal reafirmou que a disposição do art. 133 da CF/1988 não é absoluta, tendo em vista que a própria Carta Maior confere o direito de postular em juízo a outras pessoas.","deleted":false}],"heading":false},{"page":21,"runs":[{"text":"[ RE 434.059 , voto do rel. min. Gilmar Mendes , P, j. 7-5-2008, DJE 172 de 12-9-2008.]","deleted":false}],"heading":false},{"page":21,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":21,"runs":[{"text":"● A oitiva do condenado pelo Juízo da Execução Penal, em audiência de justificação realizada na presença do defensor e do Ministério Público, afasta a necessidade de prévio Procedimento Administrativo Disciplinar (PAD), assim como supre eventual ausência ou insuficiência de defesa técnica no PAD instaurado para apurar a prática de falta grave durante o cumprimento da pena.","deleted":false}],"heading":false},{"page":21,"runs":[{"text":"[Tese definida no RE 972.598 , rel. min. Roberto Barroso , P, j. 4-5-2020, DJE 196 de 6-8-2020, Tema 941.]","deleted":false}],"heading":false},{"page":21,"runs":[{"text":"(...) a realização de audiência em juízo - audiência de justificação -, na qual seja assegurado ao condenado o direito ao contraditório e à ampla defesa, supre a necessidade do prévio procedimento administrativo disciplinar (PAD) para o reconhecimento de falta grave, assim como supre eventual inexistência ou insuficiência da defesa no plano administrativo, devidamente sanada no âmbito judiciário. (...). Destaque-se que o enunciado 5 da Súmula Vinculante deste Tribunal (...) tangencia o tema debatido e merece ser aqui enfrentado. (...) é sabido que, após a publicação do referido enunciado, em maio de 2008, vem se consolidando o entendimento nesta Corte (...) de que tal preceito sumular não se aplicaria ao processo administrativo disciplinar para apurar falta grave em estabelecimentos prisionais. (...).no caso de reconhecimento de falta grave em estabelecimentos prisionais, é necessário que haja o efetivo exercício do contraditório e da ampla defesa, por meio de defesa técnica habilitada, respeitando-se o devido processo legal, para que o prévio procedimento administrativo disciplinar não seja considerado inconstitucional ou nulo. (...). Não significa, contudo, que o procedimento administrativo disciplinar seja um pressuposto de validade da decisão judicial que reconhece o cometimento de falta grave, já que a essência constitucional determinante que confere validade à decisão judicial é o respeito aos princípios do devido processo legal, do contraditório e da ampla defesa, e não a realização do processo administrativo. Os princípios constitucionais são pressupostos de validade do procedimento administrativo disciplinar, e não o contrário. O procedimento administrativo disciplinar não é pressuposto de validade para realização dos princípios constitucionais. A consequência lógica de tal equação jurídica é que o procedimento administrativo disciplinar é dispensável para a decisão judicial que reconhece a falta grave, no curso da execução penal, se o exercício do direito ao contraditório e à ampla defesa, por meio de defesa técnica devidamente habilitada, respeitando-se o devido processo legal, se der de forma plena, porém, de outro modo que não seja no curso do procedimento","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"administrativo disciplinar.","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"[ RE 972.598 , rel. min. Roberto Barroso , voto do min. Gilmar Mendes , P, j. 4-5-2020, DJE 196 de 6-8-2020, Tema 941.]","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":22,"runs":[{"text":"Aplicação do princípio da instrumentalidade das formas para suprir a ausência de defesa técnica em processo administrativo disciplinar (PAD) para apurar falta grave","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"Pretendida nulidade do ato que reconheceu a prática da falta de natureza grave por ausência de procedimento administrativo disciplinar (PAD). (...) 1. Ao contrário do que afirma a recorrente, foi instaurado procedimento administrativo disciplinar (...), o qual não foi homologado pelo Juízo de Direito da Vara de Execução Criminal de Novo Hamburgo/RS, que entendeu que a defesa do apenado deveria ser feita por advogado habilitado. 2. No entanto, essa irregularidade foi suprida pela repetição do procedimento em juízo, quando foi feita a oitiva do paciente, devidamente acompanhado de seu defensor e na presença do Ministério Público estadual. Portanto, não há que se falar em inobservância dos preceitosconstitucionais do contraditório e da ampla defesa no ato que reconheceu a prática de falta grave pelo paciente. 3. Aquele juízo na audiência de justificação, ao não potencializar a forma pela forma, que resultaria na pretendida nulidade do PAD pela defesa, andou na melhor trilha processual, pois entendeu que aquele ato solene teria alcançado, de forma satisfatória, a finalidade essencial pretendida no procedimento administrativo em questão. Cuida-se, na espécie, do princípio da instrumentalidade das formas, segundo o qual se consideram válidos os atos que, realizados de outro modo, lhe preencham a finalidade essencial (art. 154 do CPC/1973) e, ainda que a lei prescreva determinada forma, sem cominação de nulidade, o juiz poderá, mesmo que realizado de outro modo, considerá-lo hígido quando tenha alcançado sua finalidade essencial (art. 244 do CPC/1973).","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"[ RHC 109.847 , rel. min. Dias Toffoli , 1ª T, j. 22-11-2011, DJE 231 de 6-12-2011.]","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"Defesa técnica em processo administrativo disciplinar (PAD) e ampla defesa","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"No que toca à falta de nomeação de defensor ad hoc para os, então, indiciados, tal não se justifica. Desde o início da instrução do PAD, os agravantes foram devidamente notificados a acompanhar o procedimento investigativo, apondo ciente nos instrumentos convocatórios. Eram servidores públicos remunerados e nada justificaria onerar o poder público com mais esse custo, principalmente considerando o volume de recursos públicos já desviado pelos agravantes, conforme apurado nos autos do processo administrativo-disciplinar. Tanto é assim que as defesas formais acostadas aos autos (...) dão conta que os agravantes foram representados por defensores habilitados por instrumentos procuratórios, bacharéis em Direito e devidamente registrados na Ordem dos Advogados do Brasil. Ainda que assim não fosse, melhor sorte não teriam os agravantes, visto que incidiria a Súmula Vinculante 5, a qual dispõe que “a falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição”. (...) Assim, também, os depoimentos dos acusados e de testemunhas introduzidos no PAD, de que tratam os agravantes, foram devidamente refeitos em sede administrativo-disciplinar, como se observa dos documentos referenciados acima. Desse modo, não houve produção probatória eivada de nulidade, seja pela irrelevância dos documentos produzidos em sede de inquérito policial para o deslinde da ardilosa trama de dilapidação do patrimônio público detalhada e rigorosamente comprovada nos autos, seja pela observância plena do contraditório e da ampla defesa, haja vista as reiteradas oportunidades de participação e manifestação dos agravantes na instrução processual.","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"[ MS 23.280 AgR-segundo , voto do rel. min. Gilmar Mendes , P, j. 1º-7-2016, DJE 169 de 12-8-2016.]","deleted":false}],"heading":false},{"page":22,"runs":[{"text":"Não implica má aplicação da Súmula Vinculante 5 (“A falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição”) decisão que, em sede de embargos de declaração, reforma o mérito de julgado anterior à edição da referida súmula, para, com base em outros elementos dos autos, afastar a afirmação de nulidade de ato de intimação de advogado em processo administrativo disciplinar.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"2. Prejudicado o fundamento da obrigatoriedade da presença do advogado em todos os atos do processo, a efetividade e a ocorrência de eventual prejuízo em razão do meio adotado para intimação de procurador regularmente constituído para atuação em demanda administrativa somente podem ser aferidas com revisão das circunstâncias fáticas e da legislação infraconstitucional, questões que escapam ao conteúdo da referida Súmula Vinculante e, portanto, à própria via da reclamação constitucional.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"[ Rcl 17.351 AgR , rel. min. Roberto Barroso , 1ª T, j. 10-5-2016, DJE 106 de 24-5-2016.]","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"O recurso não merece prosperar. Isso porque o acórdão recorrido está em sintonia com a jurisprudência desta Corte que se firmou no sentido de que a falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição. Outrossim, insta esclarecer que a alegação de que a Súmula Vinculante 5 só teria validade a partir de sua edição, no ano de 2008, não se revela plausível, eis que destituída de supedâneo jurídico. Com efeito, o entendimento consignado na Súmula já estava pacificado no Supremo Tribunal Federal antes mesmo de sua edição, sendo que a aprovação deste enunciado pelo Plenário constitui tão somente a consolidação formal de uma jurisprudência reiterada. Dessa forma, não há que se falar em violação ao contraditório e à ampla defesa, ajustando-se o acórdão impugnado de forma plena e harmônica ao entendimento desta Corte.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"[ ARE 842.500 , rel. min. Gilmar Mendes , dec. monocrática, j. 23-10-2014, DJE 214 de 31-10-2014.]","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"A CF/1988 (art. 5º, LV) ampliou o direito de defesa, assegurando aos litigantes, em processo judicial ou administrativo, e aos acusados em geral o contraditório e a ampla defesa, com os meios e recursos a ela inerentes. (...) Assinale-se, por outro lado, que há muito a doutrina constitucional vem enfatizando que o direito de defesa não se resume a um simples direito de manifestação no processo. Efetivamente, o que o constituinte pretende assegurar - como bem anota Pontes de Miranda - é uma pretensão à tutela jurídica (...). Por fim, não merece guarida aalegação da impetrante de que, pelo fato de não estar acompanhada de advogado, seria o processo administrativo nulo, em violação às garantias constitucionais da ampla defesa e do contraditório (CF/1988, art. 5º, LV). Isso porque esta Corte, com base em reiterados julgados, determinou que a designação de causídico em processo administrativo é mera faculdade da parte, entendimento esse que se sedimentou na Súmula Vinculante 5 (...).","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"[ MS 22.693 , voto do rel. min. Gilmar Mendes , P, j. 17-11-2010, DJE 241 de 13- 12-2010.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"Defesa técnica em processo administrativo disciplinar (PAD) para apurar falta grave em estabelecimentos prisionais","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"Em qualquer hipótese, a jurisprudência desta Suprema Corte já assentou a inaplicabilidade do verbete da Súmula Vinculante 5 aos processos disciplinares administrativos para apuração de cometimento da falta grave.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"[ Rcl 8.830 AgR , rel. min. Rosa Weber, j. 23-2-2016, 1ª T, DJE 46 de 11-3-2016.]","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"A jurisprudência desta Corte é firme no sentido de que a Súmula Vinculante 5 não é aplicável em procedimentos administrativos para apuração de falta grave em estabelecimentos prisionais. Tal fato, todavia, não permite ampliar o alcance da referida súmula vinculante e autorizar o cabimento desta reclamação, pois o acórdão reclamado apenas adotou o verbete como uma das premissas para decidir no caso concreto.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"[ Rcl 9.340 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 26-8-2014, DJE 172 de 5-9-2014.]","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"Ressalte-se que, no caso em espécie, a presença de assistente jurídico da penitenciária não garante a observância dos princípios constitucionais do contraditório e da ampla defesa, pois sem o devido acompanhamento de advogado ou de defensor público nomeado.","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"[ AI 805.454 , rel. min. Dias Toffoli , dec. monocrática, j. 1º-8-2011, DJE 148 de 3-8-2011.]","deleted":false}],"heading":false},{"page":23,"runs":[{"text":"Recentemente, o Supremo Tribunal Federal aprovou o texto da Súmula Vinculante 5 (...). Todavia, esse enunciado é aplicável apenas em procedimentos de natureza cível. Em procedimento administrativo disciplinar, instaurado para apurar o cometimento de falta grave por réu condenado, tendo em vista estar em jogo a","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"liberdade de ir e vir, deve ser observado amplamente o princípio do contraditório, com presença de advogado constituído ou defensor público nomeado, devendo ser-lhe apresentada defesa, em observância às regras específicas contidas na LEP/1984 (arts. 1º; 2º; 10; 44, III; 15; 16; 41, VII e IX; 59; 66, V, a, VII e VIII; 194), no CPP/1941 (arts. 3º e 261) e na própria CF/1988 (art. 5º, LIV e LV).","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"[ RE 398.269 , voto do rel. min. Gilmar Mendes , 2ª T, j. 15-12-2009, DJE 35 de 26-2-2010.","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"Necessidade de defesa técnica para inclusão de preso em regime disciplinar diferenciado","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"(...) a lei pressupõe prévia manifestação da defesa, providência que não se contenta com a mera intimação, tampouco existência protocolar, de defesa técnica. Assim, na hipótese de ausência de apresentação de defesa, incumbe ao juiz da Execução sanar a irregularidade, propiciando a intimação do preso para fins de constituição de novo profissional e, em caso de inércia, nomear a Defensoria Pública ou defensor dativo. Não é possível, todavia, dar prosseguimento ao procedimento de inclusão em regime disciplinar diferenciado mediante simples oportunidade de defesa, já que a lei exige efetiva prática da defesa em sua amplitude. O não exercício da defesa técnica, nesse caso, não se resolve pela presunção de renúncia, na medida em que se trata de providência que desborda do poder de disposição dos atores processuais. (...) Oportuno salientar que a jurisprudência da Corte é consolidada no sentido de que a Súmula Vinculante 5 (“A falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição.”) não se aplica a processos em que se debata a prática de falta grave, o que deve ser estendido à hipótese de inclusão em regime disciplinar diferenciado, especialmente em razão da gravidade da sanção disciplinar perseguida e do caráter indisponível do interesse em desate (...). Cumpre acrescentar que, no caso concreto, conforme informações prestadas pelo juízo da execução penal, não ocorreu audiência em juízo, ato processual que eventualmente, se presente defesa técnica, poderia convalidar a irregularidade anterior. Sendo assim, o procedimento de inclusão em regime disciplinar diferenciado ocorreu à revelia do paciente, contentando-se o juízo da execução penal com a ciência inerte da defesa técnica, cuja existência de procuração nos autos, inclusive, é matéria controvertida. Mesmo sem adentrar nessa questão, forte no caráter indisponível da matéria em debate, a ausência de manifestação da defesa técnica contraria o devido processo legal e, nessa medida, invalida o ato decisório. Registro ainda que não se trata de sindicar inclusão cautelar em regime disciplinar diferenciado, hipótese em que o diferimento do contraditório poderia ser justificado, como é próprio das tutelas de urgência. (...) Posto isso, com fulcro no art. 21, § 1º, do RISTF, não conheço do habeas corpus , mas concedo a ordem de ofício para o fim de anular a decisão que determinou a inclusão do paciente em regime disciplinar diferenciado sem prévia manifestação da defesa técnica.","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"[ HC 132.377 , rel. min. Edson Fachin, dec. monocrática, j. 29-9-2016, DJE 211 de 4-10-2016.","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"Nomeação de defensor dativo e defesa técnica","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"Conforme já assentado pela decisão ora agravada, tendo sido o recorrente omisso quanto à apresentação de defesa, a comissão processante cuidou de nomear, em substituição ao advogado oficiante no feito, um defensor dativo, a fim de que fosse sanada tal omissão. (...) Assim, ao contrário do afirmado pelo recorrente, não houve cerceamento de defesa. Ademais, o fato de a defesa final ter sido realizada por bacharel em direito, em vez de advogado inscrito na OAB, não viola o texto constitucional, pois, conforme entendimento já firmado por esta Corte, a falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição (Súmula Vinculante 5). Dessa forma, não há fundamentos capazes de infirmar a decisão agravada.","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"[ RE 570.496 AgR , voto do rel. min. Gilmar Mendes , 2ª T, j. 28-2-2012, DJE 52 de 13-3-2012.]","deleted":false}],"heading":false},{"page":24,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":24,"runs":[{"text":"● A PSV 58, que requereu o cancelamento da Súmula Vinculante 5, foi rejeitada pelo Plenário do STF em 30-11-2016.","deleted":false}],"heading":false},{"page":25,"runs":[{"text":"Data de publicação do enunciado: DJE de 16-5-2008.","deleted":false}],"heading":false},{"page":25,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":25,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"6","number":"6","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":26,"endPage":27,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1202","paragraphs":[{"page":26,"runs":[{"text":"Não viola a Constituição o estabelecimento de remuneração inferior ao salário mínimo para as praças prestadoras de serviço militar inicial.","deleted":false}]}],"notes":[{"page":26,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":26,"runs":[{"text":"I - A CF/1988 não estendeu aos militares a garantia de remuneração não inferior ao salário mínimo, como o fez para outras categorias de trabalhadores. II - O regime a que se submetem os militares não se confunde com aquele aplicável aos servidores civis, visto que têm direitos, garantias, prerrogativas e impedimentos próprios. III - Os cidadãos que prestam serviço militar obrigatório exercem um múnus público relacionado com a defesa da soberania da pátria. IV - A obrigação do Estado quanto aos conscritos limita-se a fornecer-lhes as condições materiais para a adequada prestação do serviço militar obrigatório nas Forças Armadas.","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"[ RE 570.177 , rel. min. Ricardo Lewandowski, P, j. 30-4-2008, DJE 117 de 27-6-2008, Tema 15.]","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":26,"runs":[{"text":"● Não viola a Constituição o estabelecimento de remuneração inferior ao salário mínimo para as praças prestadoras de serviço militar inicial.","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"[Tese definida no RE 570.177 , rel. min. Ricardo Lewandowski, P, J. 30-4-2008, DJE 117 de 27-6-2008, Tema 15.]","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"O Plenário desta Corte, em sessão realizada por meio eletrônico, concluiu, no exame do RE 570.177/SP, relator o ministro Ricardo Lewandowski, pela existência da repercussão geral do tema constitucional versado no presente feito. Na sessão plenária de 30 de abril de 2008, o Tribunal, ao apreciar o mérito do mencionado recurso extraordinário, manteve o entendimento no sentido da constitucionalidade dos dispositivos legais que determinam o pagamento de soldo inferior ao salário mínimo para as praças que prestam serviço militar obrigatório (...).","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"[ RE 551.788 , rel. min. Dias Toffoli, dec. monocrática, j. 18-5-2011, DJE 107 de 6-6-2011.]","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"O acórdão recorrido decidiu ser constitucional o pagamento de soldo inferior a um salário mínimo à praça prestadora do serviço militar inicial. (...) 3. O Plenário do Supremo Tribunal Federal, em 30-4-2008, ao julgar o RE 570.177/MG, rel. min. Ricardo Lewandowski, com repercussão geral reconhecida no mesmo recurso extraordinário, DJE de 29-2-2008, nos termos da Lei 11.418/2006, concluiu ser constitucional a remuneração inferior ao salário mínimo para as praças prestadoras de serviço militar inicial. Em razão do precedente, o Plenário, em 7-5-2008, aprovou a Súmula Vinculante 6 (...). 4. Assim, o acórdão ora impugnado está em consonância com a orientação firmada pelo Plenário desta Corte sobre a matéria em referência, razão pela qual nego seguimento ao recurso extraordinário com fundamento no art. 557, caput , do CPC/1973.","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"[ RE 551.322 , rel. min. Ellen Gracie, dec. monocrática, j. 26-05-2010, DJE 105 de 11-6-2010.]","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":26,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 15, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"Data de publicação do enunciado: DJE de 16-5-2008.","deleted":false}],"heading":false},{"page":26,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":27,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"7","number":"7","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":28,"endPage":29,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1205","paragraphs":[{"page":28,"runs":[{"text":"A norma do § 3º do artigo 192 da Constituição, revogada pela Emenda Constitucional 40/2003, que limitava a taxa de juros reais a 12% ao ano, tinha sua aplicação condicionada à edição de lei complementar.","deleted":false}]}],"notes":[{"page":28,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":28,"runs":[{"text":"O Tribunal acolheu a questão de ordem proposta pela senhora ministra Ellen Gracie, para: a) nos termos do voto da relatora, definir procedimento próprio para exame de repercussão geral nos casos de questões constitucionais que formam a jurisprudência dominante nesta Corte, vencido o senhor ministro Marco Aurélio; b) reconhecer a existência de repercussão geral quanto às questões que envolvem a autoaplicabilidade do art. 192, § 3º, da CF/1988, na redação vigente anteriormente à EC 40/2003, e a possibilidade de limitação dos juros a 12% ao ano; c) fixar que essa questão constitucional tem jurisprudência dominante nesta Corte; d) negar distribuição ao recurso extraordinário para que nele sejam adotados os procedimentos previstos no art. 543-B, § 3º, do CPC/1973, e autorizar que se negue a distribuição aos recursos que chegarem ao Supremo Tribunal Federal sobre o mesmo tema; e) aprovar como Súmula Vinculante o texto do verbete número 648 da Súmula do Tribunal (...).","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"[ RE 582.650 QO , rel. min. Ellen Gracie, extrato de ata, P, j. 11-6-2008, DJE 202 de 24-10-2008, Tema 98.]","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"Tendo a CF/1988, no único artigo em que trata do Sistema Financeiro Nacional (art. 192), estabelecido que este será regulado por lei complementar, com observância do que determinou no caput , nos seus incisos e parágrafos, não é de se admitir a eficácia imediata e isolada do disposto em seu § 3º, sobre taxa de juros reais (12% ao ano), até porque estes não foram conceituados. Só o tratamento global do Sistema Financeiro Nacional, na futura lei complementar, com a observância de todas as normas do caput , dos incisos e parágrafos do art. 192, é que permitirá a incidência da referida norma sobre juros reais e desde que estes também sejam conceituados em tal diploma.","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"[ ADI 4 , rel. min. Sydney Sanches, P, j. 7-3-1991, DJ de 25-6-1993.]","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":28,"runs":[{"text":"● A norma do § 3º do artigo 192 da Constituição, revogada pela Emenda Constitucional 40/2003, que limitava a taxa de juros reais a 12% ao ano, tinha sua aplicação condicionada à edição de lei complementar.","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"[Tese definida no RE 582.650 QO , rel. min. Ellen Gracie, P, J. 16-4-2008, DJE 202 de 24-10-2008, Tema 98.]","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"A parte recorrente alega ofensa aos arts. 62 e 192, § 3º, da Constituição Federal. A instância judicante de origem, ao apreciar cláusula de contrato bancário, decidiu que é autoaplicável o § 3º do art. 192 do Magno Texto (redação anterior à EC 40/2003), que limitou os juros remuneratórios a 12% ao ano, bem como vedou a aplicação da capitalização dos juros em qualquer periodicidade. O recurso deve ser provido. Quanto à autoaplicabilidade do mencionado dispositivo constitucional, tenho que incide no caso a Súmula Vinculante 7.","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"[ RE 544.933 , rel. min. Roberto Barroso, dec. monocrática, j. 16-9-2016, DJE 202 de 22-9-2016.]","deleted":false}],"heading":false},{"page":28,"runs":[{"text":"A discussão neste processo a respeito do limite dos juros aplicáveis em contratos bancários é de natureza infraconstitucional, pois fundamentada no CDC/1990, na MP 2.170-36/2001 e na jurisprudência do Superior Tribunal de Justiça. Assim, eventual ofensa constitucional, se existente, seria indireta. (...) Ademais, como posto na decisão agravada, inaplicável o art. 192, § 3º, da Constituição da República, revogado pela EC 40/2003, pois a sua aplicação estava condicionada à edição de lei complementar, nos termos da Súmula","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Vinculante 7 do Supremo Tribunal. (...) Finalmente, a análise quanto ao aumento arbitrário dos lucros decorrente da taxa de juros aplicada pelo agravado demandaria o reexame das provas dos autos, inviável em recurso extraordinário.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"[ AI 853.463 ED , voto da rel. min. Cármen Lúcia, 2ª T, j. 11-9-2012, DJE 188 de 25-9-2012.]","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"JUROS. LIMITAÇÃO. PARÁGRAFO 3º DO ART. 192 DA CF/1988. VERBETE VINCULANTE 7 DA SÚMULA DO SUPREMO. O § 3º do art. 192 da CF/1988, revogado pela EC 40/2003, não era autoaplicável.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"[ RE 450.305 AgR , rel. min. Marco Aurélio, 1ª T, j. 12-8-2008, DJE 25 de 6-2-2009.]","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":29,"runs":[{"text":"Contratos celebrados após o advento da EC 40/2003","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"A parte recorrente alega que ocorreu violação ao art. 192, § 3º, da Constituição, bem como à Súmula Vinculante 7. O recurso não deve ser provido. O Supremo Tribunal Federal, ao apreciar o AI 804.209 RG, rel. min. Gilmar Mendes, decidiu pela ausência de repercussão geral da controvérsia envolvendo a limitação dos juros remuneratórios em 12% ao ano, relativamente aos contratos formalizados após o advento da EC 40/2003, como ocorre no presente processo.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"[ AI 864.760 , rel. min. Roberto Barroso, dec. monocrática, j. 5-8-2016, DJE 173 de 17-8-2016.]","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Juros. Limitação em 12% ao ano. Contratos celebrados após o advento da EC 40/2003. Legislação infraconstitucional. Inexistência de repercussão geral.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"[ AI 804.209 RG , rel. min. Gilmar Mendes, P, j. 16-9-2010, DJE 194 de 15-10-2010, Tema 310.]","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":29,"runs":[{"text":"● A Súmula Vinculante 7 resultou da conversão da Súmula 648.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"● Tema 310 de Repercussão Geral (não reconhecida).","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"● Tema 421 de Repercussão Geral (não reconhecida).","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-6-2008.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":29,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"8","number":"8","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":30,"endPage":32,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1209","paragraphs":[{"page":30,"runs":[{"text":"São inconstitucionais o parágrafo único do artigo 5º do Decreto-Lei 1.569/1977 e os artigos 45 e 46 da Lei 8.212/1991, que tratam da prescrição e decadência do crédito tributário.","deleted":false}]}],"notes":[{"page":30,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":30,"runs":[{"text":"As normas relativas à prescrição e à decadência tributárias têm natureza de normas gerais de direito tributário, cuja disciplina é reservada a lei complementar, tanto sob a Constituição pretérita (art. 18, § 1º, da CF/1967/1969) quanto sob a Constituição atual (art. 146, b, III, da CF/1988). Interpretação que preserva a força normativa da Constituição, que prevê disciplina homogênea, em âmbito nacional, da prescrição, decadência, obrigação e crédito tributários. (...) O CTN/1966 (Lei 5.172/1966), promulgado como lei ordinária e recebido como lei complementar pelas Constituições de 1967/1969 e 1988, disciplina a prescrição e a decadência tributárias.","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"[ RE 556.664 , rel. min. Gilmar Mendes, P, j. 12-6-2008, DJE 216 de 14-11-2008.]","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"Estou acolhendo parcialmente o pedido de modulação de efeitos, tendo em vista a repercussão e a insegurança jurídica que se pode ter na hipótese; mas estou tentando delimitar esse quadro de modo a afastar a possibilidade de repetição de indébito de valores recolhidos nestas condições, com exceção das ações propostas antes da conclusão do julgamento. Nesse sentido, eu diria que o Fisco está impedido, fora dos prazos de decadência e prescrição previstos no CTN/1966, de exigir as contribuições da seguridade social. No entanto, os valores já recolhidos nestas condições, seja administrativamente, seja por execução fiscal, não devem ser devolvidos ao contribuinte, salvo se ajuizada a ação antes da conclusão do presente julgamento. Em outras palavras, são legítimos os recolhimentos efetuados nos prazos previstos nos arts. 45 e 46 e não impugnados antes da conclusão deste julgamento. Portanto, reitero o voto pelo desprovimento do recurso extraordinário, declarando a inconstitucionalidade do parágrafo único do art. 5º do DL 1.569/1977 e dos arts. 45 e 46 da Lei 8.212/1991, porém, com a modulação dos efeitos, ex nunc , apenas em relação às eventuais repetições de indébito ajuizadas após a presente data, a data do julgamento.","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"[ RE 556.664 , proposta do rel. min. Gilmar Mendes, P, j. 12-6-2008, DJE 216 de 14-11-2008.]","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"Declaração de inconstitucionalidade, com efeito ex nunc , salvo para as ações judiciais propostas até 11-6-2008, data em que o Supremo Tribunal Federal declarou a inconstitucionalidade dos arts. 45 e 46 da Lei 8.212/1991.","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"[ RE 559.943 , rel. min. Cármen Lúcia, P, j. 12-6-2008, DJE 182 de 26-9-2008, Tema 3.]","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":30,"runs":[{"text":"● São inconstitucionais o parágrafo único do art. 5º do Decreto-Lei 1.569/1977 e os arts. 45 e 46 da Lei 8.212/1991, que tratam de prescrição e decadência de crédito tributário.","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"[Tese definida no RE 559.943 , rel. min. Cármen Lúcia, P, j. 12-6-2008, DJE 182 de 26-9-2008, Tema 3.]","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"AGRAVO REGIMENTAL NA RECLAMAÇÃO. EXECUÇÃO TRABALHISTA. PRESCRIÇÃO. ALEGAÇÃO DE DESCUMPRIMENTO DA SÚMULA VINCULANTE 8. AGRAVO REGIMENTAL AO QUAL SE NEGA PROVIMENTO. 1. A decisão reclamada observou a prescrição quinquenal: inexistência de descumprimento da Súmula Vinculante 8.","deleted":false}],"heading":false},{"page":30,"runs":[{"text":"[ Rcl 7.971 AgR , rel. min. Cármen Lúcia, P, j. 25-11-2009, DJE 232 de 11-12-2009.]","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"CONSTITUCIONAL. TRIBUTÁRIO. PRESCRIÇÃO E DECADÊNCIA. RESERVA DE LEI COMPLEMENTAR. LEI ORDINÁRIA QUE DISPÕE DE FORMA CONTRÁRIA ÀQUELA NORMATIZADA EM LEI COMPLEMENTAR DE NORMAS GERAIS. ART. 146, III, B, DA CF/1988. ART. 46 DA LEI 8.212/1991. PROCESSO CIVIL. AGRAVO REGIMENTAL. Viola a reserva de lei complementar para dispor sobre normas gerais em matéria tributária (art. 146, III, b, da CF/1988) lei ordinária da União que disponha sobre prescrição e decadência. Precedentes. “São inconstitucionais o parágrafo único do art. 5º do DL 1.569/1977 e os arts. 45 e 46 da Lei 8.212/1991, que tratam de prescrição e decadência de crédito tributário” (Súmula Vinculante 8).","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"[ RE 502.648 AgR , rel. min. Joaquim Barbosa, 2ª T, j. 19-8-2008, DJE 227 de 28-11-2008.]","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":31,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 8 para dívidas de natureza não tributária","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"Inicialmente, constata-se acórdão recorrido diverge do entendimento sumulado desta Corte, segundo o qual a Súmula Vinculante 8 diz respeito apenas aos créditos de natureza tributária. (...) Nesse sentido, a jurisprudência do STF se firmou no sentido da cassação da decisão recorrida, haja vista o erro de premissa ao se adotar o entendimento da Súmula Vinculante 8 para dívidas de natureza não tributária. (...) Ante o exposto, conheço do agravo e dou provimento ao recurso extraordinário, nos termos do art. 21, § 2º, RISTF, para cassar o acórdão recorrido e determinar que outro seja proferido, considerando a inaplicabilidade da Súmula Vinculante 8 ao caso.","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"[ ARE 1.014.703 , rel. min. Edson Fachin, dec. monocrática, j. 15-2-2017, DJE 33 de 20-2-2017.]","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"O Plenário desta Corte, ao debater a edição da Súmula Vinculante 8, acentuou que a declaração de inconstitucionalidade do parágrafo único do art. 5º do DL 1.569/1977 e dos arts. 45 e 46 da Lei 8.212/1991 não alcança os créditos de natureza não tributária (...). (...) esta Corte firmou o entendimento de que o parágrafo único do art. 5º do DL 1.569/1977 e os arts. 45 e 46 da Lei 8.212/1991 são inconstitucionais porque as normas relativas à prescrição e à decadência tributárias têm natureza de normas gerais de direito tributário, cuja disciplina é reservada a lei complementar, tanto sob a Constituição pretérita (art. 18, § 1º, da CF de 1967/1969) quanto sob a Constituição atual (art. 146, b, III, da CF/1988). Esse fundamento, à toda evidência, preserva a incidência do parágrafo único do art. 5º do DL 1.569/1977 a créditos de natureza não tributária, porquanto não há, quanto a eles, reserva de lei complementar para a edição de normas sobre prescrição e decadência.","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"[ RE 868.859 , rel. min. Teori Zavascki, dec. monocrática, j. 4-4-2016, DJE 65 de 8-4-2016.]","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"Trata-se de recurso extraordinário interposto contra acórdão do Tribunal Superior do Trabalho, que entendeu pela ocorrência da prescrição da multa por infração à norma celetista. Em suma, o Tribunal de origem, em razão do teor da Súmula Vinculante 8, não acolheu a pretensão da recorrente em ver reconhecida a suspensão da prescrição prevista no art. 5º, parágrafo único, do DL 1.569/1977. (...) Em síntese, para ficar indene de dúvidas, destaco que o Supremo Tribunal Federal não declarou a inconstitucionalidade da suspensão da prescrição de créditos não tributários decorrente da aplicação do caput do art. 5º do DL 1.569/1977, mas também não declarou sua constitucionalidade. O tema ainda se encontra em aberto para discussão no âmbito desta Casa e também no presente feito. De qualquer modo, observo que o Tribunal Superior do Trabalho não emitiu juízo sobre a validade do art. 5º do DL 1.569/1977 - que prevê a suspensão da prescrição, em razão de se tratar de execução de crédito de pequeno valor, que só deve ser ajuizada quando os débitos superarem o valor mínimo previsto em lei - nas hipóteses de execução de créditos não tributários, limitando-se a concluir pela incidência da Súmula Vinculante 8, ao caso dos autos.","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"[ RE 919.882 , rel. min. Dias Toffoli, dec. monocrática, j. 27-10-2015, DJE 221 de 6-11-2015.]","deleted":false}],"heading":false},{"page":31,"runs":[{"text":"O parágrafo único do art. 5º do DL 1.569/1977 foi declarado inconstitucional por esta Corte apenas na parte em que se refere à suspensão da prescrição dos créditos tributários, por se exigir, quanto ao tema, lei complementar. 2. O Supremo Tribunal Federal não declarou a inconstitucionalidade da suspensão da","deleted":false}],"heading":false},{"page":32,"runs":[{"text":"prescrição de créditos não tributários decorrente da aplicação do caput do art. 5º do DL 1.569/1977. O tema ainda se encontra em aberto para discussão no âmbito do STF. 3. Afastada, no caso concreto, a aplicação da Súmula Vinculante 8, os autos devem retornar ao Tribunal Superior do Trabalho para que esse emita juízo sobre o art. 5º do DL 1.569/1977, considerada a hipótese de execução de crédito não tributário, sob pena de supressão de instância.","deleted":false}],"heading":false},{"page":32,"runs":[{"text":"[ RE 816.084 AgR , rel. min. Marco Aurélio, red. p/ o ac. min. Dias Toffoli, 1ª T, j. 10-3-2015, DJE 91 de 18-5-2015.]","deleted":false}],"heading":false},{"page":32,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":32,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 3, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":32,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-6-2008.","deleted":false}],"heading":false},{"page":32,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":32,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"9","number":"9","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":33,"endPage":34,"status":"cancelled","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1212","paragraphs":[{"page":33,"runs":[{"text":"O disposto no artigo 127 da Lei 7.210/1984 (Lei de Execução Penal) foi recebido pela ordem constitucional vigente, e não se lhe aplica o limite temporal previsto no caput do artigo 58.","deleted":false}]}],"notes":[{"page":33,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":33,"runs":[{"text":"O instituto da remição deve pautar-se pelo disposto no art. 1º da LEP/1984 (...). Não pode, no entanto, ser interpretado de maneira a desprestigiar os apenados que cumprem regularmente sua pena, mesmo porque, segundo remansoso entendimento desta Corte, o benefício compreendido no aludido instituto constitui mera expectativa de direito. Assim, é perfeitamente legítima a sua perda, nos termos do art. 127 da LEP/1984, na hipótese de cometimento de falta grave, como ocorre no caso dos presentes autos. Não há que se falar, pois, em desproporção entre a falta e a sanção, nem em violação ao princípio da igualdade, mesmo porque o instituto em tela consubstancia determinada política criminal que visa, em última análise, à paulatina reinserção social do apenado. O parâmetro oferecido pela impetrante “para nortear a decisão sobre a perda dos dias remidos” (fl. 6), representado pelo disposto nos arts. 53 e 58 da LEP/1984, à evidência, não se aplica à hipótese. É que tais preceitos cuidam exclusivamente do isolamento do apenado e da suspensão e restrição de direitos, não guardando relação com a matéria tratada no presente habeas corpus .","deleted":false}],"heading":false},{"page":33,"runs":[{"text":"[ HC 90.107 , voto do rel. min. Ricardo Lewandowski, 1ª T, j. 27-3-2007, DJE 4 de 27-4-2007.]","deleted":false}],"heading":false},{"page":33,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":33,"runs":[{"text":"● 1. A revogação ou modificação do ato normativo em que se fundou a edição de enunciado de súmula vinculante acarreta, em regra, a necessidade de sua revisão ou cancelamento pelo Supremo Tribunal Federal, conforme o caso. 2. É constitucional a previsão legislativa de perda dos dias remidos pelo condenado que comete falta grave no curso da execução penal.","deleted":false}],"heading":false},{"page":33,"runs":[{"text":"[...] a súmula teve como intuito precípuo fixar a tese de que a previsão legislativa de perda dos dias remidos foi recepcionada pela nova ordem constitucional de 1988 e que, consequentemente, não haveria de se falar em direito adquirido aos dias remidos em razão de estarem submetidos a regras específicas, afastando-se, com isso, as teses defensivas nesse sentido. [...] Destarte, a alteração redacional do diploma legislativo nem sequer chegou a ferir o disposto no enunciado sumular [...]. O que se fez, pela alteração legislativa superveniente, foi limitar a 1/3 (um terço) o tempo remido suscetível de ser revogado pelo juiz em caso de o condenado cometer falta grave. [...] Quanto à necessidade de revisão da redação sumulada, entendo ser ato conveniente e útil, em vista do risco de a nova redação dar azo à multiplicação de processos mais uma vez. No entanto, tal discussão será travada, em momento oportuno, seguindo os devidos ritos estabelecidos no regimento interno do STF [...].","deleted":false}],"heading":false},{"page":33,"runs":[{"text":"[ Tese definida no RE 1.116.485 , rel. min. Luiz Fux, P, j. 1º-3-2023, DJE s/n de 24-4-2023, Tema 477. ]","deleted":false}],"heading":false},{"page":33,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":33,"runs":[{"text":"Cancelamento da Súmula Vinculante 9","deleted":false}],"heading":false},{"page":33,"runs":[{"text":"Ao julgar o RE 1.116.485 (Rel. Min. Luiz Fux, j. em 01.03.2023), paradigma do Tema 477 da repercussão geral, o Plenário do STF aprovou a seguinte tese: “1. A revogação ou modificação do ato normativo em que se fundou a edição de enunciado de súmula vinculante acarreta, em regra, a necessidade de sua revisão ou cancelamento pelo Supremo Tribunal Federal, conforme o caso. 2. É constitucional a previsão legislativa de perda dos dias remidos pelo condenado que comete falta grave no curso da execução penal”. 5. Havendo decisão de mérito em repercussão geral sobre o tema proposto, não é preciso atribuir nova redação à Súmula","deleted":false}],"heading":false},{"page":34,"runs":[{"text":"Vinculante nº 9. A finalidade de uniformizar a jurisprudência foi devidamente atendida. Há, no entanto, interesse no cancelamento do verbete, evitando a manutenção de súmula em desconformidade com precedente vinculante da Corte. 6. Procedência do pedido formulado na PSV 60 e improcedência do pedido formulado na PSV 64, com o cancelamento da Súmula Vinculante nº 9.","deleted":false}],"heading":false},{"page":34,"runs":[{"text":"[ PSV 60 , rel. min. Luís Roberto Barroso, P, j. 26-9-2025, DJE s/n 4-11-2025.]","deleted":false}],"heading":false},{"page":34,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":34,"runs":[{"text":"● Tema 477 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":34,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-6-2008.","deleted":false}],"heading":false},{"page":34,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":34,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"10","number":"10","scope":"main","kind":"vinculante","sectionId":"grupo-0","page":35,"endPage":45,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1216","paragraphs":[{"page":35,"runs":[{"text":"Viola a cláusula de reserva de plenário (CF, artigo 97) a decisão de órgão fracionário de tribunal que, embora não declare expressamente a inconstitucionalidade de lei ou ato normativo do Poder Público, afasta sua incidência, no todo ou em parte.","deleted":false}]}],"notes":[{"page":35,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":35,"runs":[{"text":"Discute-se no recurso extraordinário se o acórdão recorrido violou a reserva de plenário para declaração de inconstitucionalidade de lei (art. 97 da CF/1988), na medida em que deixou de aplicar retroativamente o art. 3º da LC 118/2005, como determinam o art. 4º da mesma lei e o art. 106, I, do CTN/1966. (...) Ao deixar de aplicar os dispositivos em questão por risco de violação da segurança jurídica (princípio constitucional), é inequívoco que o acórdão recorrido declarou-lhes implícita e incidentalmente a inconstitucionalidade parcial. (...) Portanto, ao invocar precedente da Seção, e não do Órgão Especial, para decidir pela inaplicabilidade de norma ordinária federal com base em disposição constitucional, entendo que o acórdão recorrido deixou de observar a necessária reserva de plenário, nos termos do art. 97 da CF/1988.","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"[ RE 482.090 , voto do rel. min. Joaquim Barbosa, P, j. 18-6-2008, DJE 48 de 13-3-2009.]","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":35,"runs":[{"text":"● É nula a decisão de órgão fracionário que se recusa a aplicar o art. 94, II, da Lei 9.472/1997, sem observar a cláusula de reserva de Plenário (CF/1988, art. 97), observado o art. 949 do Código de Processo Civil.","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"[Tese definida no ARE 791.932 , rel. min. Alexandre de Moraes , P, j. 11-10-2018, DJE 44 de 6-3-2019, Tema 739.]","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"● É desnecessária a submissão à regra da reserva de plenário quando a decisão judicial estiver fundada em jurisprudência do Plenário ou em Súmula deste Supremo Tribunal Federal; (...).","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"[Tese definida no ARE 914.045 RG , rel. min. Edson Fachin, P, j. 15-10-2015, DJE 232 de 19-11-2015, Tema 856.]","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"A jurisprudência pacífica desta Corte, agora reafirmada em sede de repercussão geral, entende que é desnecessária a submissão de demanda judicial à regra da reserva de plenário na hipótese em que a decisão judicial estiver fundada em jurisprudência do Plenário do Supremo Tribunal Federal ou em Súmula deste Tribunal, nos termos dos arts. 97 da Constituição Federal e 481, parágrafo único, do CPC/1973.","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"[ ARE 914.045 RG , rel. min. Edson Fachin, P, j. 15-10-2015, DJE 232 de 19-11-2015, Tema 856.]","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":35,"runs":[{"text":"Afastamento de aplicação de dispositivo legal com fundamento em omissão inconstitucional parcial viola a Súmula Vinculante 10","deleted":false}],"heading":false},{"page":35,"runs":[{"text":"(...) observo que a autoridade reclamada, ao realizar o que denominou de “interpretação da legislação conforme à Constituição”, afastou a aplicação do art. 1º da Lei 10.698/2003 (...). E assim o fez por entender que o referido diploma legal teria natureza de revisão geral anual, razão pela qual o reajuste deveria ser concedido de forma igualitária a todos os servidores. Tal leitura pelo Tribunal reclamado configura, na verdade, omissão inconstitucional parcial, na medida em que considera a incompletude do legislador em conceder o","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"aumento para todos os servidores públicos. (...) Ao assim decidir, observo que, por via transversa (interpretação conforme), houve o afastamento da aplicação do referido texto legal, o que não foi realizado pelo órgão do Tribunal designado para tal finalidade. Dessa forma, restou configurada a violação ao art. 97 da Constituição Federal, cuja proteção é reforçada pela Súmula Vinculante 10 do STF (...).","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"[ Rcl 14.872 , voto do rel. min. Gilmar Mendes , 2ª T, j. 31-5-2016, DJE 135 de 29-6-2014.]","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"Afastamento de aplicação de dispositivo legal por fundamento constitucional viola a Súmula Vinculante 10","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"A jurisprudência da CORTE tem reiteradamente proclamado que a desconsideração do princípio em causa gera, como inevitável efeito consequencial, a nulidade absoluta da decisão judicial colegiada que, emanando de órgão meramente fracionário, haja declarado a inconstitucionalidade de determinado ato estatal (...) Dessa forma, embora não tenha declarado expressamente a inconstitucionalidade incidental, as decisões monocráticas afastaram, por via indireta, a aplicação da Lei 14.182/2021, tendo, consequentemente, exercido o controle difuso de constitucionalidade sem aplicação do art. 97 da CF/88 e violado o enunciado da Súmula Vinculante 10, por desrespeito à Cláusula de Reserva de Plenário.","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"[ Rcl 64.901 AgR , rel. min. Alexandre de Moraes , 1ª T, j. 13-5-2024, DJE s/n de 20-5-2024.]","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"O acórdão reclamado determinou a promoção de (...) independentemente de uma subetapa e de duas etapas do processo de promoção a que se submetem os demais oficiais, conforme a Lei estadual n.º 7.990/2001 e o Decreto estadual n.º 28.792/1982. Ao afastar essas normas e etapas do processo de promoção, o TJ-BA decidiu que elas contrariavam princípios administrativos constitucionais, como legalidade, impessoalidade, moralidade, publicidade e eficiência. Porém, a decisão foi tomada por um órgão fracionário do tribunal e não submeteu a questão da constitucionalidade dessas normas ao plenário ou órgão especial, conforme exigido pela cláusula de reserva de plenário estipulada no art. 97 da CF e reforçada pela SV n.º 10 do STF.","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"[ Rcl 67.062 , rel. min. Flávio Dino , dec. monocrática, j. 8-5-2024, DJE s/n de 9-5-2024.]","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"PLENÁRIO - RESERVA - VERBETE VINCULANTE Nº 10 DA SÚMULA DO SUPREMO - NORMA LEGAL - AFASTAMENTO. O afastamento de norma legal por órgão fracionário, de modo a revelar o esvaziamento da eficácia do preceito, implica contrariedade à cláusula de reserva de plenário e ao verbete vinculante nº 10 da Súmula do Supremo. (...) o Tribunal Regional Federal da 1ª Região, por meio de órgão fracionário, ao afastar o Decreto nº 2.637/1998, tomando como parâmetro o artigo 170, inciso IV, da Constituição Federal, olvidou o versado no artigo 97 da Lei das leis, segundo o qual “somente pelo voto da maioria absoluta de seus membros ou dos membros do respectivo órgão especial poderão os tribunais declarar a inconstitucionalidade de lei ou ato normativo do Poder Público”.","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"[ RE 635.088 AgR-segundo , rel. min. Marco Aurélio , 1ª T, j. 4-2-2020, DJE 49 de 9-3-2020.]","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"(...) tem-se que o caso dos autos fornece suporte fático para a incidência da Súmula Vinculante 10 do STF. Isso porque o ato reclamado, ao entender que os honorários de sucumbência, nas causas em que a Fazenda Pública for vencedora, não pertencem aos advogados que patrocinaram a causa, mas ao erário, por constituírem verba pública, declarou expressamente a inconstitucionalidade da norma especial de regência aplicável ao caso, qual seja, a Lei municipal 3.046, de 22 de julho de 2014 (arts. 1º e 5º), sem a observância do que determina o art. 97 da Constituição Federal. Assim, a jurisprudência do STF é firme no sentido de que há violação à cláusula de reserva de plenário quando a decisão de órgão fracionário afasta a aplicação da norma legal em razão de sua inconstitucionalidade, conforme verificado no caso concreto.","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"[ Rcl 23.646 , rel. min. Edson Fachin , dec. monocrática, j. 8-11-2016, DJE 239 de 10-11-2016.]","deleted":false}],"heading":false},{"page":36,"runs":[{"text":"(...) com base em fundamentos extraídos da Constituição Federal, o órgão fracionário da Corte reclamada afastou, em parte, a aplicação do art. 5º, II, da Lei 7.347/1985, com redação da Lei 11.448/2007, o qual legitima a propositura de ação civil pública pela Defensoria Pública: “Art. 5º Têm legitimidade para propor a ação principal e a ação cautelar: I - o Ministério Público; II - a Defensoria Pública”. Assim, ao afastar, com espeque","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"na Constituição da República, a aplicação do dispositivo supracitado, sem a observância da cláusula de reserva de plenário, o acórdão reclamado contrariou, inegavelmente, o enunciado da Súmula Vinculante 10. Destaco que esta Suprema Corte, em 7-5-2015, julgou improcedente a ADI 3.943, de relatoria da ministra Cármen Lúcia, em que questionada a inconstitucionalidade do art. 5º, II, da Lei 7.347/1985. Registro que, no referido julgamento, foi afastada a interpretação adotada na decisão reclamada, que condiciona a atuação da Defensoria Pública, diante de situação justificadora do ajuizamento de ação civil pública, à comprovação prévia da pobreza do público-alvo.","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"[ Rcl 17.744 AgR , voto da rel. min. Rosa Weber , 1ª T, j. 15-3-2016, DJE 72 de 18-4-2016.]","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"(...) in casu, o afastamento da aplicação do mencionado dispositivo do diploma civil revela verdadeira ofensa à Súmula Vinculante 10 (...). Deveras, o acórdão reclamado negou aplicabilidade ao art. 59 do Código Civil pelo fundamento de que tal norma seria incompatível com o art. 217, I, da Constituição, apesar de não declarar expressamente sua incompatibilidade. Trata-se, em verdade, de uma declaração velada de inconstitucionalidade por órgão fracionário, o que não se coaduna com o art. 97 da Carta Magna, representando violação ao que disposto pelo mencionado verbete vinculante.","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"[ Rcl 11.760 AgR , voto do rel. min. Luiz Fux , 1ª T, j. 23-2-2016, DJE de 14-3-2016.]","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"Declaração de inconstitucionalidade parcial sem redução de texto","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"(...). VIOLAÇÃO À SÚMULA VINCULANTE 10. OCORRÊNCIA. ARTIGOS 4º E 5º DA LEI 11.442/2007. REDUÇÃO INTERPRETATIVA REALIZADA POR ÓRGÃO FRACIONÁRIO. CONTROLE DIFUSO DE CONSTITUCIONALIDADE. TÉCNICA DECISÓRIA DENOMINADA DECLARAÇÃO DE INCONSTITUCIONALIDADE PARCIAL SEM REDUÇÃO DE TEXTO. (...). 1. Na hipótese dos autos, a Justiça Laboral reconheceu o vínculo trabalhista entre as partes, afastando o teor da Lei 11.442/2007. Ao realizar essa redução interpretativa, o órgão fracionário do Tribunal Regional do Trabalho da 17ª Região exerceu o controle difuso de constitucionalidade e utilizou a técnica decisória denominada declaração de inconstitucionalidade parcial sem redução de texto, pela qual o intérprete declara a inconstitucionalidade de algumas interpretações possíveis do texto legal, sem, contudo, alterá-lo gramaticalmente, ou seja, censurou uma determinada interpretação por considerá-la inconstitucional. 2. Embora não tenha declarado expressamente a inconstitucionalidade incidental, o órgão fracionário do Tribunal Regional do Trabalho da 17ª Região afastou a aplicação da Lei 11.442/2007, exercendo, portanto, o controle difuso de constitucionalidade sem aplicação do artigo 97 da CF, o que viola o enunciado da Súmula Vinculante 10, por desrespeito à cláusula de reserva de Plenário.","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"[ Rcl 28.848 AgR , rel. min. Marco Aurélio , red. p/ o ac. min. Alexandre de Moraes , 1ª T, j. 8-6-2020, DJE 156 de 23-6-2020.]","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"Desnecessidade de observância da cláusula de reserva de plenário em decisão liminar monocrática","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"(...) a decisão proferida em medida cautelar em ação direta de inconstitucionalidade estadual não se submete à cláusula da reserva de plenário, não havendo falar, em decorrência, de violação da Súmula Vinculante 10/STF. Nesse sentido a firme jurisprudência desta Suprema Corte. (...) Por outro lado, emerge dos precedentes da Súmula Vinculante 10 que seu fundamento reside na necessária observância do postulado da reserva de plenário (art. 97 da Carta Política) como condição de validade e eficácia da declaração de inconstitucionalidade dos atos normativos, seja no controle abstrato, seja no controle difuso. Nessa medida, uma vez submetida, como na espécie, a decisão monocrática do relator, exarada em sede de tutela de urgência, à ratificação do Órgão Especial do Tribunal de Justiça, sequer se pode cogitar de negativa de vigência à cláusula de reserva do plenário albergada no art. 97 da Lei Fundamental, sendo certo, em qualquer hipótese, que o relator atua monocraticamente como longa manus do órgão colegiado na presença do periculum in mora.","deleted":false}],"heading":false},{"page":37,"runs":[{"text":"[ Rcl 11.768 AgR , voto da rel. min. Rosa Weber , 1ª T, j. 2-2-2016, DJE de 24-2-2016.]","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"Agravo regimental em reclamação. Súmula Vinculante 10. Decisão liminar monocrática. Não configurada violação da cláusula de reserva de plenário. Agravo regimental ao qual se nega provimento. 1. Decisão proferida em sede de liminar prescinde da aplicação da cláusula de reserva de plenário (art. 97 da CF/1988) e, portanto, não viola a Súmula Vinculante 10. Precedentes. 2. A atuação monocrática do magistrado, em sede cautelar, é medida que se justifica pelo caráter de urgência da medida, havendo meios processuais para submeter a decisão liminar ao crivo do órgão colegiado em que se insere a atuação do relator original do processo. 3. Agravo regimental não provido.","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[ Rcl 17.288 AgR , rel. min. Dias Toffoli , 1ª T, j. 25-6-2014, DJE 105 de 2-6-2014.]","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"AGRAVO REGIMENTAL NA RECLAMAÇÃO. DECISÃO MONOCRÁTICA QUE INDEFERE MEDIDA CAUTELAR EM AÇÃO DIRETA DE INCONSTITUCIONALIDADE ESTADUAL. ALEGAÇÃO DE CONTRARIEDADE À SÚMULA VINCULANTE 10 DO SUPREMO TRIBUNAL FEDERAL. AGRAVO AO QUAL SE NEGA PROVIMENTO. 1. Indeferimento de medida cautelar não afasta a incidência ou declara a inconstitucionalidade de lei ou ato normativo. 2. Decisão proferida em sede cautelar: desnecessidade de aplicação da cláusula de reserva de plenário estabelecida no art. 97 da Constituição da República.","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[ Rcl 10.864 AgR , rel. min. Cármen Lúcia , P, j. 24-3-2011, DJE 70 de 13-4-2011.]","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"Exceção à cláusula de reserva de plenário em razão de pronunciamento prévio do plenário ou do órgão especial de Tribunal","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"Não há falar em contrariedade à Súmula Vinculante 10, a autorizar o cabimento da reclamação, nos moldes do art. 103-A, § 3º, da Constituição da República, quando o ato judicial reclamado se utiliza de raciocínio decisório de controle de constitucionalidade, deixando de aplicar a lei, quando já existe pronunciamento acerca da matéria por este Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[ Rcl 16.528 AgR , rel. min. Rosa Weber, j. 7-3-2017, 1ª T, DJE de 22-3-2017.]","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[...] ressalte-se que o Supremo Tribunal Federal afasta a incidência da reserva de plenário quando o entendimento adotado pelo acórdão recorrido se revela alinhado com a jurisprudência assentada pelo Plenário ou por ambas as Turmas deste Tribunal.","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[ ARE 784.441 , rel. min. Luís Roberto Barroso, j. 15-2-2016, dec. monocrática, DJE 30 de 18-2-2016.]","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"AGRAVO REGIMENTAL. RECLAMAÇÃO. SÚMULA VINCULANTE 10. ACÓRDÃO RECLAMADO COM FUNDAMENTO EM DECISÃO DO PLENÁRIO DO STF. 1. No julgamento do RE 389.808, o Plenário do Supremo Tribunal Federal julgou inconstitucional o art. 6º da LC 105/2001. Assim, os Tribunais podem deixar de submeter a arguição de inconstitucionalidade aos seus próprios plenários, aplicando o disposto no parágrafo único do art. 481 do CPC/1973. 2. É certo que a questão está em revisão no âmbito do Supremo Tribunal, tendo sido admitida, no RE 601.314, a repercussão geral do tema. A despeito disso, os tribunais que seguem a orientação atualmente fixada não necessitam submeter a questão aos respectivos plenários (Rcl 17.574, rel. min. Gilmar Mendes). 3. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[ Rcl 18.598 AgR , rel. min. Luís Roberto Barroso, j. 7-4-2015, 1ª T, DJE 82 de 5-5- 2015.]","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"Não se vislumbra contrariedade à Súmula Vinculante 10 deste Supremo Tribunal por inobservância do princípio da reserva de plenário, pois “os órgãos fracionários dos tribunais não submeterão ao plenário, ou ao órgão especial, a arguição de inconstitucionalidade, quando já houver pronunciamento destes ou do Plenário do Supremo Tribunal Federal sobre a questão” (parágrafo único do art. 481 do CPC/1973). A Súmula Vinculante 10 do Supremo Tribunal Federal não retirou, como não o poderia, a higidez da exceção ao princípio da reserva de plenário (art. 97 da Constituição da República), conforme se extrai dos precedentes mencionados na elaboração do verbete citado. Não se exige a reserva estabelecida no art. 97 da CF/1988 quando o plenário, ou órgão equivalente de tribunal, já tiver decidido sobre a questão","deleted":false}],"heading":false},{"page":38,"runs":[{"text":"[ RE 876.067 AgR , voto da rel. min. Cármen Lúcia , 2ª T, j. 12-5-2015, DJE 96 de 22-5-2015.]","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"A jurisprudência desta Corte admite exceção à cláusula de reserva de plenário, quando o órgão fracionário declara a inconstitucionalidade de uma norma com base na própria jurisprudência do Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"[ Rcl 11.055 ED , rel. min. Luís Roberto Barroso, j. 4-11-2014, 1ª T, DJE 227 de 19-11-2014.]","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"Não há reserva de plenário (art. 97 da CF/1988) à aplicação de jurisprudência firmada pelo Pleno ou por ambas as Turmas desta Corte. Ademais, não é necessária identidade absoluta para aplicação dos precedentes dos quais resultem a declaração de inconstitucionalidade ou de constitucionalidade. Requer-se, sim, que as matérias examinadas sejam equivalentes. Assim, cabe à parte que se entende prejudicada discutir a simetria entre as questões fáticas e jurídicas que lhe são peculiares e a orientação firmada por esta Corte. 3. De forma semelhante, não se aplica a reserva de plenário à constante rejeição, por ambas as Turmas desta Corte, de pedido para aplicação de efeitos meramente prospectivos à decisão.","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"[ AI 607.616 AgR , rel. min. Joaquim Barbosa, j. 31-8-2010, 2ª T, DJE 185 de 1º10-2010.]","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"Exceção à cláusula de reserva de plenário e desnecessidade de aplicação literal de precedente","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"A Corte de origem aplicou adequadamente o entendimento constante da ADI 1.089/DF. As razões de decidir extraídas do referido precedente são suficientes para demonstrar que a Corte Suprema não permite que o Estado-membro crie uma nova hipótese de incidência sem o amparo da norma geral editada pela União. 2. A aplicação do precedente não precisa ser absolutamente literal. Se, a partir do julgado, for possível concluir um posicionamento acerca de determinada matéria, já se afigura suficiente a invocação do aresto para afastar a vigência da norma maculada pelo vício da inconstitucionalidade já reconhecido pelo Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"[ RE 578.582 AgR , rel. min. Dias Toffoli , 1ª T, j. 27-11-2012, DJE 248 de 19-12-2012.]","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"I - A obediência à cláusula de reserva de plenário não se faz necessária quando houver orientação consolidada do STF sobre a questão constitucional discutida. II - Possibilidade de reconhecimento de inconstitucionalidade de lei ou ato normativo do poder público pelos órgãos fracionários dos tribunais, com base em julgamentos do plenário ou órgão especial que, embora não guardem identidade absoluta com o caso em concreto, analisaram matéria constitucional equivalente.","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"[ RE 571.968 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 22-5-2012, DJE 109 de 5-6-2012.]","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"Impossibilidade de aplicação da cláusula de reserva de plenário a decisão de juiz singular","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"Conforme mencionado na decisão ora agravada, observa-se que a Constituição Federal elenca, em seu art. 97, a hipótese de aplicação da Súmula Vinculante 10, estando ela direcionada aos casos em que órgão fracionário de Tribunal, embora não declare expressamente a inconstitucionalidade de norma jurídica, afasta sua aplicação, no todo ou em parte, sem a devida observância da denominada “cláusula de reserva de plenário” (art. 97 da CF de 1988) (...) Assim, reitero que inexiste ofensa ao referido dispositivo, porquanto ele não se aplica a julgamento de competência não colegiada, como ocorre no presente caso, em que o ato reclamado versa sobre decisão monocrática proferida pela 4ª Vara do Trabalho de Recife.","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"[ Rcl 57.125-ED , rel. min. Gilmar Mendes , 2ª T, j. 22-2-2023, DJE 37 de 1-3-2023.]","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"O art. 97 da CF/1988 e a Súmula Vinculante 10 são aplicáveis ao controle de constitucionalidade difuso realizado por órgãos colegiados. Por óbvio, o requisito é inaplicável aos juízos singulares, que não dispõem de “órgãos especiais”. Ademais, o controle de constitucionalidade incidental, realizado pelos juízes singulares, independe de prévia declaração de inconstitucionalidade por tribunal. A tese exposta na inicial equivaleria à extinção do controle de constitucionalidade difuso e incidental, pois caberia aos juízes singulares tão somente aplicar decisões previamente tomadas por tribunais no controle concentrado e abstrato de constitucionalidade.","deleted":false}],"heading":false},{"page":39,"runs":[{"text":"[ Rcl 14.889 MC , rel. min. Joaquim Barbosa , dec. monocrática, j. 13-11-2012, DJE 226 de 19-11-2012.]","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"Veja-se, assim, que o objetivo da Súmula Vinculante 10 é dar eficácia à cláusula constitucional da reserva de plenário, cuja obediência é imposta aos tribunais componentes da estrutura judiciária do Estado brasileiro. Ocorre que a decisão, ora reclamada, foi proferida por juiz singular, o que torna o objeto da presente ação incompatível com o paradigma de confronto constante da Súmula Vinculante 10. Isso porque é inviável a aplicação da súmula ou da cláusula de reserva de plenário, dirigida a órgãos judicantes colegiados, a juízo de caráter singular, por absoluta impropriedade, quando da realização de controle difuso de constitucionalidade.","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"[ Rcl 13.158 , rel. min. Dias Toffoli , dec. monocrática, j. 8-8-2012, DJE 160 de 15-8-2012.]","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"Não viola a Súmula vinculante 10 decisão de órgão fracionário ou especial que suspende eficácia de norma estadual em razão de lei federal superveniente que contém norma geral em sentido diverso","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"4. A superveniência de norma geral, a disciplinar em sentido diverso a questão objeto das normas estaduais, acarreta a suspensão dessas, nos termos do § 4º do art. 24 da Constituição Federal. 5. A exigência de reserva de plenário, nos termos do art. 97 da Constituição Federal e da Súmula Vinculante 10, é imposta a órgãos fracionários e membros de plenário ou órgão especial como condição para a declaração de inconstitucionalidade, direta ou indireta, de lei ou ato normativo do poder público que afaste a incidência, no todo ou em parte, da norma impugnada e não na hipótese em que a norma estadual é afastada em face da suspensão parcial de sua eficácia em decorrência da superveniência de lei federal sobre normas gerais que disciplinou a matéria em evidência em sentido contrário.","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"[ Rcl 69.080 AgR , rel. min. Edson Fachin , 2ª T, j. 14-10-2024, DJE de 24-10-2024.]","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"Reserva de plenário e embasamento de decisão em princípios constitucionais","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"O órgão reclamado, invocando uma ponderação entre os princípios constitucionais da legalidade e da primazia da juventude, terminou por negar vigência ao limite etário previsto no art. 2º, II, da Lei Complementar amazonense 30/2001, sem a observância de cláusula de reserva de plenário, em clara afronta à segunda parte da Súmula Vinculante 10 (...).","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"[ Rcl 19.717 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 2-8-2016, DJE 177 de 22-8-2016.]","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"Reserva de plenário e interpretação da lei aplicável ao caso","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"3. O redirecionamento da execução trabalhista a corresponsável tem como fundamento o reconhecimento da responsabilidade solidária das empresas integrantes do mesmo grupo econômico, nos termos do art. 2º, §§ 2º e 3º, da CLT, estando fundada tão somente em juízo interpretativo das normas celetistas, que possuem suas particularidades. Não há, pois, violação do art. 97 da Constituição ou da Súmula Vinculante nº 10 quando o Tribunal de Origem nem sequer adentra na análise do art. 513, § 5º, do CPC, interpretando e aplicando ao caso concreto outras normas mais específicas, sem cogitar de incompatibilidade daquele dispositivo, de aplicação geral, com a Constituição.","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"[ RE 1.387.795 , rel. min. Dias Toffoli, j. 13-10-2025, P, DJE de 10-12-2025, Tema 1.232.]","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"Quanto à alegação de ofensa ao teor da Súmula Vinculante 10, mantenho o entendimento constante da decisão agravada, pois o que articulado pela parte agravante não encontra guarida na jurisprudência desta Corte, uma vez que o acórdão reclamado não declarou inconstitucional a norma legal indicada. Nesse contexto, não houve afastamento - por inconstitucionalidade, direta ou indiretamente, de qualquer dispositivo legal. A jurisprudência do Supremo Tribunal Federal é firme acerca da não exigência de reserva de plenário para a mera interpretação e aplicação de normas jurídicas, que emerge do próprio exercício da jurisdição, sendo necessário para caracterizar violação à tal cláusula que a decisão de órgão fracionário fundamente-se na incompatibilidade entre a norma legal indicada e a Carta da República, o que não se verificou no caso concreto.","deleted":false}],"heading":false},{"page":40,"runs":[{"text":"[ Rcl 64.588 AgR , rel. min. Edson Fachin, j. 22-4-2024, 2ª T, DJE de 20-5-2024.]","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"18. No que diz respeito à alegação de violação à Súmula Vinculante 10, destaco que o entendimento nela consubstanciado tem por fundamento o art. 97 da Constituição, que veda a declaração de inconstitucionalidade de lei ou ato normativo por órgão fracionário de Tribunal. (...) 19. Naturalmente, isso não significa que os órgãos fracionários estejam proibidos de interpretar a legislação ordinária, com ou sem referência à Constituição. A aplicação do direito pressupõe a definição do seu sentido e alcance. Essa é a atividade cotidiana dos Tribunais e de seus órgãos fracionários. O que não se admite é o afastamento do ato, por força de norma constitucional, sem observância da reserva de plenário. A diferença entre as duas hipóteses nem sempre será clara, mas há uma zona de certeza positiva quanto à incidência do art. 97 da Constituição: se o Tribunal de origem esvaziar a lei ou o ato normativo, i.e., se não restar qualquer espaço para a aplicação do diploma, não haverá dúvida de que o que ocorreu foi um afastamento, não uma simples interpretação.","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"[ Rcl 31.928 , rel. min. Roberto Barroso , dec. monocrática, j. 19-9-2018, DJE 200 de 21-9-2018.]","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"A decisão reclamada não afastou a incidência do art. 37, I, da LC 75/1993, apenas conferiu interpretação à lei orgânica do Ministério Público para reconhecer a legitimidade da atuação do Parquet estadual perante o STJ. 2. A ausência de juízo de inconstitucionalidade acerca da norma em apreço afasta a violação à Súmula Vinculante 10 desta Corte.","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"[ Rcl 18.013 AgR , rel. min. Luiz Fux , 1ª T, j. 10-5-2016, DJE 113 de 3-6-2016.]","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"Cumpre assinalar, no ponto, que não transgride a autoridade da Súmula Vinculante 10/STF o acórdão proferido por órgão fracionário que, sem invocar nas razões conflito entre ato do poder público e critérios resultantes do texto constitucional, limita-se a interpretar normas de direito local. Cabe ter presente, por relevante, que o Plenário desta Corte, defrontando-se com idêntica situação jurídica, enfatizou que a discussão da matéria ora em exame envolve típica hipó- tese de interpretação de normas locais, circunstância esta que descaracteriza o alegado desrespeito ao enunciado da Súmula Vinculante 10/STF.","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"[ Rcl 13.514 AgR , voto do rel. min. Celso de Mello , 2ª T, j. 10-6-2014, DJE 148 de 1º-8-2014.]","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"Registro, ainda, que é permitido aos magistrados, no exercício de atividade hermenêutica, revelar o sentido das normas legais, limitando a sua aplicação a determinadas hipóteses, sem que estejam declarando a sua inconstitucionalidade. Se o Juízo reclamado não declarou a inconstitucionalidade de norma nem afastou sua aplicabilidade com apoio em fundamentos extraídos da CF/1988, não é pertinente a alegação de violação à Súmula Vinculante 10 e ao art. 97 da CF/1988.","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"[ Rcl 12.122 AgR , voto do rel. min. Gilmar Mendes , P, j. 19-6-2013, DJE 211 de 24-10-2013.]","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"A simples ausência de aplicação de uma dada norma jurídica ao caso sob exame não caracteriza, apenas por isso, violação da orientação firmada pelo Supremo Tribunal Federal. 2. Para caracterização da contrariedade à Súmula Vinculante 10 do Supremo Tribunal Federal, é necessário que a decisão fundamente-se na incompatibilidade entre a norma legal tomada como base dos argumentos expostos na ação e a CF/1988. 3. O Superior Tribunal de Justiça não declarou a inconstitucionalidade ou afastou a incidência dos arts. 273, § 2º, e 475-O do CPC/1973 e do art. 115 da Lei 8.213/1991, restringindo-se a considerá-los inaplicáveis ao caso.","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"[ Rcl 6.944 , rel. min. Cármen Lúcia , P, j. 23-6-2010, DJE 149 de 13-8-2010.]","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"Reserva de plenário e norma anterior à CF/1988","deleted":false}],"heading":false},{"page":41,"runs":[{"text":"AGRAVO REGIMENTAL. RECLAMAÇÃO. ALEGADO DESRESPEITO À CLÁUSULA DE RESERVA DE PLENÁRIO. VIOLAÇÃO DA SÚMULA VINCULANTE 10. NÃO OCORRÊNCIA. NORMA PRÉ-CONSTITUCIONAL. AGRAVO REGIMENTAL A QUE SE NEGA PROVIMENTO. I - A norma cuja incidência teria sido afastada possui natureza pré-constitucional, a exigir, como se sabe, um eventual juízo negativo de recepção (por incompatibilidade com as normas constitucionais supervenientes), e não um juízo declaratório de inconstitucionalidade, para o qual se imporia, certamente, a observância da cláusula de reserva de plenário.","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"[ Rcl 15.786 AgR , rel. min. Ricardo Lewandowski , P, j. 18-12-2013, DJE 34 de 19-2-2014.]","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"A cláusula de reserva de plenário (full bench) é aplicável somente aos textos normativos erigidos sob a égide da CF/1988. 2. As normas editadas quando da vigência das Constituições anteriores se submetem somente ao juízo de recepção ou não pela atual ordem constitucional, o que pode ser realizado por órgão fracionário dos Tribunais sem que se tenha por violado o art. 97 da CF/1988.","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"[ AI 669.872 AgR , rel. min. Luiz Fux , 1ª T, j. 11-12-2012, DJE 29 de 14-2-2013.]","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"(...) sustenta o recorrente que houve violação ao art. 97 da CF/1988, bem como ao enunciado da Súmula Vinculante 10, em virtude de o Tribunal a quo ter negado aplicação ao § 3º do art. 4º da Lei 4.156/1962, sem, contudo, declarar sua inconstitucionalidade. No entanto, verifico que a pretensão do recorrente não encontra amparo na jurisprudência do Supremo Tribunal Federal, uma vez que o diploma legislativo afastado é anterior à CF/1988. Dessa forma, inaplicável a reserva de plenário prevista no art. 97 da CF/1988, existindo mero juízo de recepção do texto pré-constitucional. Em outros termos, examinar se determinada norma foi ou não revogada pela CF/1988 não depende da observância do princípio do Full Bench.","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"[ AI 831.166 AgR , voto do rel. min. Gilmar Mendes , 2ª T, j. 29-3-2011, DJE 159 de 19-8-2014.]","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"Responsabilidade subsidiária da Administração Pública por débitos trabalhistas","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"No mérito, destaco que este Tribunal, no julgamento da ADC 16/DF, de relatoria do ministro Cezar Peluso, declarou a constitucionalidade do art. 71 da Lei 8.666/1993, entendendo, por conseguinte, que a mera inadimplência do contratado não tem o condão de transferir à Administração Pública a responsabilidade pelo pagamento dos encargos trabalhistas, previdenciários, fiscais e comerciais resultantes da execução do contrato. (...) Importante ressaltar que, no julgamento da ADC 16/DF, este Tribunal reconheceu que eventual omissão da Administração Pública no dever de fiscalizar as obrigações do contratado poderia gerar essa responsabilidade, caso efetivamente demonstrada a culpa in vigilando do ente público. (...) Pelos elementos que constam dos autos, entendo que a atribuição da responsabilidade subsidiária não se deu de forma automática, mas por ter entendido o juízo trabalhista que ficou efetivamente delineada a culpa da administração. (...) Verifica-se, portanto, que a decisão reclamada não descumpriu a orientação firmada por este Tribunal, mas, sim, adotou-a plenamente. Assim, não há falar em desrespeito à ADC 16/DF ou à Súmula Vinculante 10.","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"[ Rcl 26.378 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 24-5-2017, DJE 112 de 29-5-2017.]","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"No que tange à alegação de que o ato reclamado reconheceu a culpa da Administração com base em presunção, examinando o ato reclamado, verifico que, com base na análise das provas produzidas nos autos, ele reconheceu a responsabilidade subsidiária da parte reclamante por débitos trabalhistas, em face de reconhecer a sua culpa, ao faltar com o dever de fiscalização do cumprimento das obrigações trabalhistas, por parte da devedora principal. Ao ser declarada a constitucionalidade do art. 71, § 1º, da Lei 8.666/1993, na ADC 16, com efeito vinculante, ficou vedada a responsabilização subsidiária automática da Administração Pública pelos débitos trabalhistas de empresa contratada em contrato de terceirização. Contudo, não se vedou o reconhecimento de responsabilidade subsidiária em casos como o presente, nos quais fica constatada a culpa do poder público. Ademais, ressalto a impossibilidade de se reverter o entendimento adotado pelo ato reclamado, sobre a existência, no caso concreto, de culpa, porque, nos termos da jurisprudência desta Corte, não é cabível o manejo de reclamação para se obter o reexame do conjunto fático-probatório dos autos. Em situações como a presente, a jurisprudência do Supremo Tribunal Federal entende não haver violação da autoridade da decisão proferida na ADC 16, a qual declarou a constitucionalidade do art. 71, § 1º, da Lei 8.666/1993, nem afronta à Súmula Vinculante 10 desta Corte.","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"[ Rcl 21.956 AgR , voto do rel. min. Edson Fachin , 1ª T, j. 1º-3-2016, DJE 58 de 31-3-2016.]","deleted":false}],"heading":false},{"page":42,"runs":[{"text":"Na ADC 16, este Tribunal afirmou a tese de que a Administração Pública não pode ser responsabilizada automaticamente por débitos trabalhistas de suas contratadas ou conveniadas. Só se admite sua condenação,","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"em caráter subsidiário, quando o juiz ou tribunal conclua que a entidade estatal contribuiu para o resultado danoso ao agir ou omitir-se de forma culposa (in eligendo ou in vigilando). 2. Afronta a autoridade da ADC 16 e da Súmula Vinculante 10 acórdão de órgão fracionário de tribunal que sustenta a responsabilidade da Administração em uma presunção de culpa - i.e., que condena o ente estatal com base no simples inadimplemento da prestadora.","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"[ Rcl 16.846 AgR , rel. min. Roberto Barroso , 1ª T, j. 19-5-2015, DJE 153 de 5-8-2015.]","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"Não vislumbro, desse modo, a ocorrência do alegado desrespeito à autoridade da decisão que esta Corte proferiu, com eficácia vinculante, no julgamento da ADC 16/DF. De outro lado, e no que concerne ao alegado desrespeito à diretriz resultante da Súmula Vinculante 10/STF, não verifico, na decisão de que ora se reclama, a existência de qualquer juízo, ostensivo ou disfarçado, de inconstitucionalidade do art. 71 da Lei 8.666/1993. Na realidade, tudo indica que, em referido julgamento, o órgão judiciário reclamado apenas reconheceu, no caso concreto, a omissão do poder público, em virtude do descumprimento de sua obrigação de fiscalizar a fiel execução das obrigações trabalhistas pela contratada, não havendo formulado juízo de inconstitucionalidade, o que afasta, ante a inexistência de qualquer declaração de ilegitimidade inconstitucional, a ocorrência de transgressão ao enunciado constante da Súmula Vinculante 10/STF.","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"[ Rcl 12.580 AgR , voto do rel. min. Celso de Mello , P, j. 21-2-2013, DJE 48 de 13-3-2013.]","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"Violação à reserva de plenário e decisão superveniente proferida pelo Pleno ou órgão especial","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"Na esteira da jurisprudência desta Corte, ao afastar a aplicação da Lei 14.406/ 2008, o órgão fracionário do Tribunal de origem desatendeu a cláusula de reserva de plenário, prevista no art. 97 da CF/1988, nos termos da Súmula Vinculante 10 (...). Ressalte-se que a superveniência de decisão proferida, em sede de arguição de inconstitucionalidade, pelo órgão especial do Tribunal de origem não elide a nulidade verificada quando da prolação do acórdão pelo órgão fracionário. (...) Ante o exposto, dou provimento ao recurso extraordinário para determinar o retorno dos autos ao Tribunal de origem, a fim de que profira novo julgamento, observada a previsão contida no art. 97 da CF/1988 (557, § 1º-A, do CPC/1973)","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"[ RE 613.725 , rel. min. Rosa Weber , dec. monocrática, j. 27-11-2012, DJE 237 de 4-12-2012.]","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"(...) esta Corte, em sessão plenária de 18-6-2008, corroborada pela discussão que envolveu o julgamento do RE 482.090/SP, rel. min. Joaquim Barbosa, aprovou a Súmula Vinculante 10 (...). Ressalte-se que, durante os debates, fixou-se entendimento de que a afronta ao art. 97 da CF/1988 persiste mesmo que o Tribunal a quo tenha, por meio do Pleno ou de seu órgão especial, declarado, após a interposição do recurso extraordinário sob julgamento, a inconstitucionalidade do dispositivo afastado. Nessa hipótese, a decisão atacada também será cassada, mas apenas para aplicação, pelo relator ou pelo órgão fracionário, do precedente firmado pelo Pleno ou pelo órgão especial competente para a declaração de inconstitucionalidade.","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"[ RE 594.801 AgR , rel. min. Ricardo Lewandowski , dec. monocrática, j. 12-6-2012, DJE 116 de 15-6-2012.]","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"Violação à reserva de plenário e recurso extraordinário interposto com outro fundamento","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"Da decisão que declara a inconstitucionalidade de lei federal, sem observância da reserva de plenário, é cabível o recurso extraordinário fundado na violação do art. 97 da CF/1988 (art. 102, III, a, da CF/1988). Descabe sobrepor as hipóteses de cabimento do recurso extraordinário para viabilizar o julgamento de mérito de demanda cujas razões recursais são deficientes (interposição exclusivamente nos termos do art. 102, III, b, da CF/1988).","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"[ RE 432.884 AgR , rel. min. Joaquim Barbosa , 2ª T, j. 26-6-2012, DJE 158 de 13-8-2012.]","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"Violação à reserva de plenário e Súmula 331, IV e V, do TST","deleted":false}],"heading":false},{"page":43,"runs":[{"text":"1. De acordo com a Súmula Vinculante 10, o afastamento da incidência de lei, mesmo sem declaração expressa de inconstitucionalidade, exige a observância da cláusula de reserva de plenário. Essa regra não é observada quando a decisão do órgão fracionário, sob o fundamento de interpretar dispositivo legal, não deixa","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"qualquer espaço para que ele seja aplicado. 2. Viola a Súmula Vinculante 10 a decisão que, invocando o art. 25, § 1º, da Lei 8.987/1995, afasta genericamente o comando que permite a terceirização, pelas concessionárias de serviço público, de atividades inerentes ao serviço concedido. 3. Agravo interno a que se nega provimento.","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"[ Rcl 27.169 AgR , rel. min. Roberto Barroso , 1ª T, j. 29-5-2018, DJE 125 de 25-6-2018.]","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"Procede a irresignação. Tenho por pertinentes as mesmas razões que consignei ao deferir a liminar. Notem, a partir da leitura do acórdão reclamado, que, embora não reconhecido o vínculo empregatício, acabou admitido o direito às verbas trabalhistas ante a ilicitude da terceirização de atividade-fim da concessionária, considerado o dever de tratamento isonômico entre empregados, presentes os artigos 5º, cabeça, e 7º, incisos XXX, XXXII e XXXIV, da Constituição Federal. Limitou-se - a despeito do previsto no artigo 94, inciso II, da Lei 9.472/1997 - o alcance da terceirização a hipóteses estritas, versadas no verbete 331 da Súmula do Tribunal Superior do Trabalho. (...) Em síntese, apesar de enquadrada a atuação do trabalhador na atividade-fim da concessionária de serviço público, acabou afastado, de forma categórica, sem observância da cláusula de reserva de plenário, o disposto no artigo 94, inciso II, da Lei 9.472/1997, no que permitida à concessionária \"contratar com terceiros o desenvolvimento de atividades inerentes, acessórias ou complementares ao serviço, bem como a implementação de projetos associados\". Ao fazê-lo, o Tribunal reclamado desrespeitou o contido no verbete vinculante 10 da Súmula do Supremo.","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"[ Rcl 18.701 , rel. min. Marco Aurélio , dec. monocrática, j. 27-3-2018, DJE 63 de 4-4-2018.]","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"Na espécie, identifico o confronto entre os atos emanados do juízo reclamado e o que expressamente dispõe a Súmula Vinculante 10, de seguinte teor (...). 3. Isso porque o acórdão impugnado na presente reclamação efetivamente afastou a aplicação do art. 71, § 1º, da Lei 8.666/1993, que não permite a transferência de responsabilidades por encargos trabalhistas para os entes públicos, aplicando ao caso o inciso IV da Súmula 331 do TST, sem fazer qualquer controle de constitucionalidade acerca daquele ato normativo.","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"[ Rcl 10.223 , rel. min. Rosa Weber , dec. monocrática, j. 15-12-2016, DJE 17 de 1º-2-2017.]","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"Acórdão que entendeu ser aplicável ao caso o que dispõe o inciso IV da Súmula/TST 331, sem a consequente declaração de inconstitucionalidade do art. 71, § 1º, da Lei 8.666/1993 com a observância da cláusula da reserva de plenário, nos termos do art. 97 da CF/1988. 2. Não houve no julgamento do Incidente de Uniformização de Jurisprudência TST-IUJ-RR-297.751/96 a declaração formal da inconstitucionalidade do art. 71, § 1º, da Lei 8.666/1993, mas apenas e tão somente a atribuição de certa interpretação ao mencionado dispositivo legal. (...) 6. O acórdão impugnado, ao aplicar ao presente caso a interpretação consagrada pelo Tribunal Superior do Trabalho no item IV do Enunciado 331, esvaziou a força normativa do art. 71, § 1º, da Lei 8.666/1993. 7. Ocorrência de negativa implícita de vigência ao art. 71, § 1º, da Lei 8.666/1993, sem que o Plenário do Tribunal Superior do Trabalho tivesse declarado formalmente a sua inconsti-tucionalidade. 8. Ofensa à autoridade da Súmula Vinculante 10 devidamente configurada. 9. Agravo regimental provido. 10. Procedência do pedido formulado na presente reclamação. 11. Cassação do acórdão impugnado.","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"[ Rcl 8.150 AgR , rel. min. Eros Grau , red. p/ o ac. min. Ellen Gracie , P, j. 24-11- 2010, DJE 42 de 3-3-2011.]","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"Turma Recursal de Juizados Especiais ou de Pequenas Causas e inaplicabilidade do princípio da reserva de plenário","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"O princípio da reserva de plenário não se aplica no âmbito dos juizados de pequenas causas (art. 24, X, da CF/1988) e dos juizados especiais em geral (art. 98, I, da CF/1988), que, pela configuração atribuída pelo legislador, não funcionam, na esfera recursal, sob o regime de plenário ou de órgão especial. 2. A manifesta improcedência da alegação de ofensa ao art. 97 da Carta Magna pela Turma Recursal de Juizados Especiais demonstra a ausência da repercussão geral da matéria, ensejando a incidência do art. 543-A do CPC/1973.","deleted":false}],"heading":false},{"page":44,"runs":[{"text":"[ ARE 868.457 RG , rel. min. Teori Zavascki , P, j. 16-4-2015, DJE 77 de 24-4-2015, Tema 805.]","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"Realmente, o art. 97 da CF/1988, ao subordinar o reconhecimento da inconstitucionalidade de preceito normativo a decisão nesse sentido da “maioria absoluta de seus membros ou dos membros dos respectivos órgãos especiais”, está se dirigindo aos Tribunais indicados no art. 92 e aos respectivos órgãos especiais de que trata o art. 93, XI. A referência, portanto, não atinge juizados de pequenas causas (art. 24, X) e juizados especiais (art. 98, I), que, pela configuração atribuída pelo legislador, não funcionam, na esfera recursal, sob regime de plenário ou de órgão especial. As Turmas Recursais, órgãos colegiados desses juizados, podem, portanto, sem ofensa ao art. 97 da CF/1988 e à Súmula Vinculante 10, decidir sobre a constitucionalidade ou não de preceitos normativos.","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"[ ARE 792.562 AgR , voto do rel. min. Teori Zavascki , 2ª T, j. 18-3-2014, DJE 65 de 2-4-2014.]","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":45,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 856, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"● Tema 1.232 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"● Tema 805 de Repercussão Geral (não reconhecida).","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"Data de publicação do enunciado: DJE de 27-6-2008.","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":45,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"11","number":"11","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":46,"endPage":50,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1220","paragraphs":[{"page":46,"runs":[{"text":"Só é lícito o uso de algemas em casos de resistência e de fundado receio de fuga ou de perigo à integridade física própria ou alheia, por parte do preso ou de terceiros, justificada a excepcionalidade por escrito, sob pena de responsabilidade disciplinar, civil e penal do agente ou da autoridade e de nulidade da prisão ou do ato processual a que se refere, sem prejuízo da responsabilidade civil do Estado.","deleted":false}]}],"notes":[{"page":46,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":46,"runs":[{"text":"Em primeiro lugar, levem em conta o princípio da não culpabilidade. É certo que foi submetida ao veredicto dos jurados pessoa acusada da prática de crime doloso contra a vida, mas que merecia tratamento devido aos humanos, aos que vivem em um Estado Democrático de Direito. (...) Ora, estes preceitos - a configurarem garantias dos brasileiros e dos estrangeiros residentes no País - repousam no inafastável tratamento humanitário do cidadão, na necessidade de lhe ser preservada a dignidade. Manter o acusado em audiência, com algema, sem que demonstrada, ante práticas anteriores, a periculosidade, significa colocar a defesa, antecipadamente, em patamar inferior, não bastasse a situação de todo degradante. O julgamento no Júri é procedido por pessoas leigas, que tiram as mais variadas ilações do quadro verificado. A permanência do réu algemado indica, à primeira visão, cuidar-se de criminoso da mais alta periculosidade, desequilibrando o julgamento a ocorrer, ficando os jurados sugestionados.","deleted":false}],"heading":false},{"page":46,"runs":[{"text":"[ HC 91.952 , voto do rel. min. Marco Aurélio, P, j. 7-8-2008, DJE 241 de 19-12-2008.]","deleted":false}],"heading":false},{"page":46,"runs":[{"text":"O uso legítimo de algemas não é arbitrário, sendo de natureza excepcional, a ser adotado nos casos e com as finalidades de impedir, prevenir ou dificultar a fuga ou reação indevida do preso, desde que haja fundada suspeita ou justificado receio de que tanto venha a ocorrer, e para evitar agressão do preso contra os próprios policiais, contra terceiros ou contra si mesmo.","deleted":false}],"heading":false},{"page":46,"runs":[{"text":"[ HC 89.429 , rel. min. Cármen Lúcia, 1ª T, j. 22-8-2006, DJ de 2-2-2007.]","deleted":false}],"heading":false},{"page":46,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":46,"runs":[{"text":"Condições adicionais para o uso de algemas por menor","deleted":false}],"heading":false},{"page":46,"runs":[{"text":"A turma, por unanimidade, [...] considerando a relevância da matéria em questão, fixar as seguintes condições, a par das existentes na Súmula Vinculante n. 11, quando se tratar, como na espécie, de uso de algemas por menor: a) apreendido o menor e não sendo o caso de liberação, seja ele encaminhado ao representante do Ministério Público competente, nos termos do art. 175 do Estatuto da Criança e do Adolescente, que deverá avaliar e opinar sobre a eventual necessidade de utilização de algemas que possa ter sido apresentada pela autoridade policial que estiver realizando a diligência em questão; b) que, nos termos do § 1º do art. 175 do Estatuto da Criança e do Adolescente, não sendo possível a apresentação imediata do menor ao Ministério Público, seja ele encaminhado para entidade de atendimento especializada, que deverá apresentá-lo em vinte e quatro horas ao representante do Ministério Público; c) nas localidades em que não houver entidade de atendimento especializada para receber o menor apreendido, fique ele aguardando a apresentação ao representante do Ministério Público em repartição policial especializada e, na falta desta, em dependência separada da destinada a maiores, nos termos do § 2º do art. 175 do Estatuto da Criança e do Adolescente, não podendo assim permanecer por mais de vinte e quatro horas; d) apresentado o menor ao representante do Ministério Público e emitido o parecer sobre a eventual necessidade de utilização das algemas, seja essa questão submetida à autoridade judiciária que deverá se manifestar de forma motivada sobre a matéria no momento da audiência de apresentação do menor; e) seja remetido ao Conselho Tutelar para se manifestar","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"sobre as providências relatadas pela autoridade policial, para decisão final do Ministério Público; f) seja remetida a conclusão do presente julgamento ao Conselho Nacional de Justiça para adoção de providências, incluídas normativas infralegais, para fins de execução; g) seja remetida a conclusão do presente julgamento aos Presidentes dos Tribunais de Justiça, para fins de encaminhamento a todas as autoridades judiciais que exerçam a competência relacionada a infância e juventude; e h) seja remetida a conclusão do presente julgamento aos Procuradores-Gerais de Justiça, para fins de encaminhamento a todos os Promotores de Justiça que exerçam a competência relacionada a infância e juventude.","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"[ Rcl 61.876 , rel. min. Cármen Lúcia , 1ª T, j. 7-5-2024, DJE s/n de 8-8-2024.]","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"Descabimento de reclamação para prevenir uso de algemas","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"Nesse contexto, a leitura da inicial não permite identificar ato concreto passível de ser impugnado mediante reclamação, uma vez que a decisão do Juízo da 5ª Vara Criminal da Circunscrição Judiciária de Brasília/DF não desrespeitou o que definido por esta Corte na Súmula Vinculante 11. Ao indeferir o pedido da defesa, o juízo reclamado deixou o uso das algemas à discrição da autoridade policial responsável pela escolta do reclamante, conforme as circunstâncias e as necessidades do caso concreto. Cumpre ressaltar, nesse ponto, que a Súmula Vinculante 11 não aboliu o uso das algemas, mas pretendeu apenas evitar os abusos que, se comprovados, implicam a responsabilização penal e administrativa dos responsáveis. Dessa forma, considerando-se a natureza preventiva do pedido, veiculado contra ato futuro e incerto, não há falar em afronta à autoridade da Súmula Vinculante 11 desta Corte.","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"[ Rcl 14.434 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 28-8-2012, DJE 172 de 31-8-2012.]","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"Impossibilidade de reavaliação do conjunto fático-probatório que serviu de fundamento para o uso de algemas","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"(...) o paradigma tido como violado legitima a utilização excepcional de algemas, desde que o ato seja adequadamente fundamentado. (...) a fundamentação apresentada aponta quais seriam os motivos concretos e peculiares justificadores da eventual utilização das algemas, razão pela qual não há falar-se em ofensa à Súmula Vinculante 11. No mais, divergir de tal fundamentação demandaria aprofundamento em matéria fático-probatória, o que é inviável em sede de Reclamação constitucional. (...) Por fim, o fundado receio de perigo à integridade física alheia, ocasionado pelo alto número de réus e pelo número reduzido de policiais para garantir a segurança dos presentes durante a realização de ato judicial, é argumento legítimo para autorizar o excepcional uso de algemas, (...).","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"[ Rcl 32.192 , rel. min. Alexandre de Moraes , dec. monocrática, j. 23-10-2018, DJE 231 de 30-10-2018.]","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"AGRAVO REGIMENTAL EM RECLAMAÇÃO. CRIMINAL. USO DE ALGEMAS EM AUDIÊNCIA. ALEGADO DESCUMPRIMENTO DA SÚMULA VINCULANTE 11. SUBSTRATO FÁTICO E JURÍDICO DIVERSO. ESTRITA OBSERVÂNCIA AO ENUNCIADO SUMULAR. IMPROCEDÊNCIA DA RECLAMAÇÃO. 1. Inexiste substrato fático ou jurídico capaz de atrair a incidência do enunciado da Súmula Vinculante 11, justificada a excepcionalidade do uso das algemas em audiência ante o fundado receio de perigo à integridade física alheia, ocasionado pelo alto número de réus e reduzida quantidade de policiais para garantir a segurança dos presentes durante a realização do ato.","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"[ Rcl 14.663 AgR , rel. min. Rosa Weber , 1ª T. j. 15-3-2016, DJE 68 de 13-4-2016.]","deleted":false}],"heading":false},{"page":47,"runs":[{"text":"A decisão atacada levou em conta a existência de fundado perigo consubstanciado no envolvimento dos acusados com facção criminosa, na deficiência da segurança do Fórum e, ainda, no grande número de advogados e funcionários presentes à sala de audiência. 5. O uso de algemas durante a audiência de instrução e julgamento somente afronta o enunciado da Súmula Vinculante 11 quando impõe constrangimento absolutamente desnecessário, o que não se verifica nos autos. 6. Não é possível admitir-se, em sede de habeas corpus , qualquer dúvida a respeito das questões de fato apontadas pela magistrada para determinar o uso das algemas durante a realização das audiências.","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"[ HC 103.003 , rel. min. Ellen Gracie , 2ª T, j. 29-3-2011, DJE 162 de 24-8-2011.]","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"Verifico, portanto, não haver, nos autos da presente reclamação, substrato fático ou jurídico capaz de atrair a incidência do enunciado da Súmula Vinculante 11, visto que há, in casu , justificativa idônea para o uso das algemas durante a realização da audiência. Assim, não é possível admitir-se, em reclamação, qualquer dúvida a respeito das questões de fato apontadas pelo magistrado para determinar o uso das algemas durante a realização das audiências.","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"[ Rcl 9.877 , rel. min. Ellen Gracie , dec. monocrática, j. 11-6-2010, DJE 116 de 25-6-2010.]","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"Necessidade de comprovação de efetivo prejuízo à defesa em razão do uso injustificado de algema","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"(...) é de registrar-se, tal como assinalado pelo Ministério Público Federal em seu douto parecer, que o uso injustificado de algemas em audiência, ainda que impugnado em momento procedimentalmente adequado, traduziria causa de nulidade meramente relativa, de modo que o seu eventual reconhecimento exigiria a demonstração inequívoca, pelo interessado, de efetivo prejuízo à defesa - o que não se evidenciou no caso -, pois não se declaram nulidades processuais por mera presunção, consoante tem proclamado a jurisprudência do Supremo Tribunal Federal (...). O entendimento ora referido reafirma a doutrina segundo a qual a disciplina normativa das nulidades no sistema jurídico brasileiro rege-se pelo princípio de que “Nenhum ato será declarado nulo, se da nulidade não resultar prejuízo para a acusação ou para a defesa” (CPP/1941, art. 563 (...)). Esse postulado básico - pas de nullité sans grief - tem por finalidade rejeitar o excesso de formalismo, desde que a eventual preterição de determinada providência legal não tenha causado prejuízo para qualquer das partes (...).","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"[ Rcl 16.292 AgR , voto do rel. min. Celso de Mello , 2ª T, j. 15-3-2016, DJE 80 de 26-4-2016.]","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"Quanto ao tema atinente ao uso de algemas no interrogatório do paciente, não prospera a irresignação do impetrante, uma vez que não há qualquer comprovação nos autos de que o réu esteve algemado, bem como não houve a insurgência da defesa em tempo hábil, restando a matéria preclusa. De qualquer modo, também não ficou demonstrado prejuízo a defesa, bem como as situações físicas da sala de audiências justificam, em tese, o uso de algemas. (...) Por fim, como já destacado, o princípio pas de nullité sans grief exige a demonstração de prejuízo concreto à parte que suscita o vício, independentemente da sanção prevista para o ato, podendo ser ela tanto a de nulidade absoluta (...) quanto relativa (...), pois “não se declara nulidade por mera presunção” (RHC 99.779, rel. min. Dias Toffoli, DJE de 13-9-2011). Esse princípio, corolário da natureza instrumental do processo, exige a demonstração de prejuízo concreto pela parte que argui a mácula (arts. 563 e 566 do Código de Processo Penal (...)), o que não se deu na espécie.","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"[ HC 121.350 , voto do rel. min. Luiz Fux , 1ª T, j. 13-5-2014, DJE 189 de 29-9-2014.]","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"Necessidade de justificação por escrito pela autoridade policial para o uso de algema em cumprimento de mandado de prisão temporária","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"(...) nestes autos os reclamantes insurgem-se contra ato praticado por policiais em cumprimento ao mandado de prisão temporária decretado pelo Juízo da 2ª Vara Criminal da Comarca de Betim/MG. (...) Destaco, também, que o Juízo da 2ª Vara Criminal da Comarca de Betim/MG, ao decretar a prisão temporária dos reclamantes, consignou que o mandado deveria ser cumprido “com as cautelas previstas em lei, evitando qualquer abuso ou arbitrariedade por parte dos seus cumpridores” (...). No caso, a utilização excepcional das algemas foi devidamente justificada pela autoridade policial, nos termos exigidos pela Súmula Vinculante 11. Ficou demonstrada a existência de fundado perigo à integridade física dos conduzidos, de terceiros e dos agentes policiais que realizaram a escolta. Ademais, como bem destacado pelo MPF, “eventual nulidade decorrente do uso de algemas no cumprimento do mandado não vicia a prisão processual”.","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"[ Rcl 8.409 , rel. min. Gilmar Mendes , dec. monocrática, j. 29-11-2010, DJE 234 de 3-12-2010.]","deleted":false}],"heading":false},{"page":48,"runs":[{"text":"Necessidade de justificativa por escrito pelo magistrado para o uso de algema em réu preso","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"O parâmetro invocado é a Súmula Vinculante 11 (...). Por fim, o fundado receio de perigo à integridade física alheia, ocasionado pelo alto número de réus e pelo número reduzido de policiais para garantir a segurança dos presentes durante a realização de ato judicial, é argumento legítimo para autorizar o excepcional uso de algemas, conforme entendimento deste SUPREMO (Rcl 30.410/SP, Rel. Min. Edson Fachin, DJe de 28/06/2018; Rcl 30.802/MT, Rel. Min. Luiz Fux, DJe de 18/06/2018; Rcl 30.729/MT, Rel. Min. Dias Toffoli, DJe de 13/06/2018; Rcl 19.501 AgR/SP, Rel. Min. Alexandre de Moraes, Primeira Turma, DJe de 14/03/2018 e Rcl 14.663 AgR, Rel. Min. Rosa Weber, Primeira Turma, DJe de 13/4/2016) (...).","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"[ Rcl 31.058 , rel. min. Alexandre de Moraes , dec. monocrática, j. 8-8-2018, DJE 164 de 14-8-2018.]","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"(...) a decisão desvirtua a lógica da Súmula. Compreende que a infração que motiva a acusação não afasta a periculosidade do agente, partindo da inconfessada premissa de que o uso de algemas configura regra não afastada pelo caso concreto. Mas a ótica da Súmula é inversa. E ótica vinculante! O fato de o réu encontrar-se preso é absolutamente neutro, pois não se imagina que o uso de algemas seja cogitado na hipótese de acusado que responde à acusação em liberdade. À obviedade, ao exigir causa excepcionante, a Súmula não se contenta com os requisitos da prisão, naturalmente presentes. Com efeito, é certo que as impressões do Juiz da causa merecem prestígio e podem sustentar, legitimamente, o uso de algemas. Não se admite, contudo, que mediante mero jogo de palavras, calcado no singelo argumento de que não se comprovou a inexistência de exceção, seja afastada a imperatividade da Súmula Vinculante. Se a exceção não se confirmou, a regra merece aplicação, de modo que, a teor do verbete, o ato judicial é nulo, com prejuízo dos posteriores.","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"[ Rcl 22.557 , rel. min. Edson Fachin , dec. monocrática, j. 14-12-2015, DJE 254 de 17-12-2015.]","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"No caso em comento, o enunciado da Súmula Vinculante 11 assentou o entendimento de que a utilização de algemas se revela medida excepcional, notadamente quando envolver processos perante o Tribunal do Júri em que jurados poderiam ser influenciados pelo fato de o acusado ter permanecido algemado no transcurso do julgamento. Com efeito, a utilização das algemas somente se legitima em três situações, a saber: (i) quando há fundado receio de fuga, (ii) quando há resistência à prisão ou (iii) quando há risco à integridade física do próprio acusado ou de terceiros ( e.g ., magistrados ou autoridades policiais). Mais que isso, é dever do agente apresentar, posteriormente, por escrito, as razões que o levaram a proceder à utilização das algemas. Do contrário, haverá a responsabilização tanto do agente que efetuou a prisão (criminal, cível e disciplinar) quanto do Estado, bem como a decretação de nulidade da prisão e/ou dos atos processuais referentes à constrição ilegal da liberdade ambulatorial do indivíduo. Ocorre que, in casu , a autoridade reclamada (Juízo da 2ª Vara Criminal da Comarca de Americana/SP) apresentou extensa fundamentação ao indeferir o pedido de relaxamento da prisão. Daí por que se mostra infundada a pretensão dos reclamantes.","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"[ Rcl 12.511 MC , rel. min. Luiz Fux , dec. monocrática, j. 16-10-2012, DJE 204 de 18-10-2012.]","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"O uso de algemas durante audiência de instrução e julgamento pode ser determinado pelo magistrado quando presentes, de maneira concreta, riscos à segurança do acusado ou das pessoas ao ato presentes. (...) II - No caso em análise, a decisão reclamada apresentou fundamentação idônea justificando a necessidade do uso de algemas, o que não afronta à Súmula Vinculante 11.","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"[ Rcl 9.468 AgR , rel. min. Ricardo Lewandowski , P, j. 24-3-2011, DJE 68 de 11-4-2011.]","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"Uso injustificado de algema em razão de ato não processual praticado por autoridade policial","deleted":false}],"heading":false},{"page":49,"runs":[{"text":"A leitura do processo, especialmente do pronunciamento mediante o qual implementada a segregação, revela a ausência de manifestação do juízo criminal acerca da utilização das algemas. Embora evidenciado o emprego injustificado do artefato, a providência decorreu de ato administrativo da autoridade policial, situação não abarcada pelo verbete, no que alude à prática de ato processual. As algemas foram utilizadas um dia após a prisão, quando o reclamante já se encontrava na delegacia de polícia, tão somente no momento da exibição dos presos à imprensa. Eventual responsabilização do Estado ou, até mesmo, dos agentes envolvidos,","deleted":false}],"heading":false},{"page":50,"runs":[{"text":"decorrente dos fatos noticiados na inicial, deve ser buscada na via apropriada. Descabe potencializar o alcance da reclamação.","deleted":false}],"heading":false},{"page":50,"runs":[{"text":"[ Rcl 7.116 , voto do rel. min. Marco Aurélio , 1ª T, j. 24-5-2016, DJE 135 de 29-6-2016.]","deleted":false}],"heading":false},{"page":50,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":50,"runs":[{"text":"● A PSV 13, que requereu o cancelamento da Súmula Vinculante 11, foi rejeitada pelo Plenário do STF em 14-8-2019.","deleted":false}],"heading":false},{"page":50,"runs":[{"text":"Data de publicação do enunciado: DJE de 22-8-2008.","deleted":false}],"heading":false},{"page":50,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":50,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"12","number":"12","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":51,"endPage":53,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1223","paragraphs":[{"page":51,"runs":[{"text":"A cobrança de taxa de matrícula nas universidades públicas viola o disposto no art. 206, IV, da Constituição Federal.","deleted":false}]}],"notes":[{"page":51,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":51,"runs":[{"text":"(...) a gratuidade do ensino público em estabelecimentos oficiais, conforme se lê no caput do art. 206, IV, configura um princípio. Um princípio que não encontra qualquer limitação, no tocante aos distintos graus de formação acadêmica. (...) O que não se mostra factível, do ponto de vista constitucional, é que as universidades públicas, integralmente mantidas pelo Estado, criem obstáculos de natureza financeira para o acesso dos estudantes aos cursos que ministram, ainda que de pequena expressão econômica, a pretexto de subsidiar alunos carentes, como ocorre no caso dos autos. (...) Não se afigura razoável, ademais, que se cobre uma taxa de matrícula dos estudantes das universidades públicas, em especial das federais, visto que a CF/1988, no art. 212, determina à União que aplique, anualmente, nunca menos de 18% da receita resultante de impostos na manutenção e desenvolvimento do ensino.","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"[ RE 500.171 , voto do rel. min. Ricardo Lewandowski , P, j. 13-8-2008, DJE 202 de 24-10-2008, Tema 40.]","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":51,"runs":[{"text":"● A cobrança de taxa de matrícula nas universidades públicas viola o disposto no art. 206, IV, da Constituição Federal.","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"[Tese definida no RE 500.171 , rel. min. Ricardo Lewandowski , P, j. 13-8-2008, DJE 202 de 24-10-2008, Tema 40.]","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"● A garantia constitucional da gratuidade de ensino não obsta a cobrança por universidades públicas de mensalidade em cursos de especialização.","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"[Tese definida no RE 597.854 , rel. min. Edson Fachin , P, j. 26-4-2017, DJE 214 de 21-9-2017, Tema 535.]","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"No caso, não há aderência estrita entre os atos reclamados e o teor da Súmula Vinculante 12 (“A cobrança de taxa de matrícula nas universidades públicas viola o disposto no art. 206, IV, da Constituição Federal”). É que, na decisão do TRF da 4ª Região, a relatora da ação cautelar “limitou-se a manter o comando sentencial impugnado, ante a ausência de risco de perecimento de direito, a justificar a concessão de liminar, antes do devido contraditório, e a existência de divergência sobre o tema objeto da lide no âmbito do próprio Supremo Tribunal Federal” (doc. 15, fl. 12). Por outro lado, informa o Juízo da 4ª Vara Federal da Seção Judiciária de Santa Catarina que “a sentença reclamada não tratou de questão abarcada pela Súmula Vinculante 12”, sendo embasada, na realidade, “no princípio da gratuidade do ensino público em estabelecimentos oficiais (art. 206, IV, da CF/1988), e no art. 44, III, da Lei de Diretrizes e Bases da Educação Nacional (Lei 9.394/1996), que enquadra os cursos de especialização como educação superior” (doc. 16, fls. 1/2). Nessas circunstâncias, conforme bem observa o procurador-geral da República, Rodrigo Janot Monteiro de Barros, “não se verifica similaridade entre o debate travado na presente reclamação e o verbete da Súmula Vinculante 12, apta a instaurar o exercício da jurisdição, em sede reclamatória, pelo Supremo Tribunal Federal” (...).","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"[ Rcl 16.910 , rel. min. Teori Zavascki , dec. monocrática, j. 1º-3-2016, DJE 42 de 7-3-2016.]","deleted":false}],"heading":false},{"page":51,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":51,"runs":[{"text":"Cobrança de taxa de matrícula em curso de língua estrangeira","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"À primeira vista, afigura-se plausível a pretensão do reclamante no sentido de que a decisão impugnada teria aplicado indevidamente o enunciado da Súmula Vinculante 12 (...). Isso porque, da análise dos autos, pode-se constatar que a reclamante, Universidade Federal do Ceará, está cobrando taxa de matrícula para os cursos de línguas estrangeiras, realizados dentro do Projeto “Casas de Cultura Estrangeira” (...), e não para a matrícula em seus cursos de graduação. A análise dos precedentes desta Suprema Corte que motivaram a aprovação da Súmula Vinculante 12 não tratam de qualquer curso realizado pelas universidades públicas, mas apenas dos cursos de ensino superior.","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"[ Rcl 8.596 MC , min. Gilmar Mendes, dec. monocrática proferida no exercício da Presidência, j. 10-7-2009, DJE 146 de 5-8-2009.]","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"Cobrança de taxa de matrícula em universidade pública","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"EDUCAÇÃO. ENSINO SUPERIOR. TAXA DE MATRÍCULA. COBRANÇA. IMPOSSIBILIDADE. O Plenário deste Tribunal fixou entendimento no sentido de que a exigência da cobrança de taxa de matrícula nas universidades públicas viola o disposto no art. 206, IV, da Constituição do Brasil [Súmula Vinculante 12].","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"[ AI 672.123 AgR , rel. min. Eros Grau, 2ª T, j. 1º-12-2009, DJE 237 de 18-12-2009.]","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"Cobrança de taxa para expedição de diploma","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"O Tribunal, no RE 562.779/DF, da relatoria do ministro Ricardo Lewandowski, sob o ângulo da repercussão geral, assentou a inconstitucionalidade da cobrança de taxa de matrícula como requisito para ingresso em universidade federal, por representar violação ao art. 206, IV, da Carta da República. Consignou constituir a matrícula formalidade essencial para acesso do aluno à educação superior, de modo que se apresenta inadequada qualquer limitação ao princípio constitucional do ensino público gratuito nos estabelecimentos oficiais. Na ocasião, votei com a maioria, ressaltando a ideia básica que serve de causa ao princípio: viabilizar o acesso dos que não podem cursar o nível superior sem prejuízo do próprio sustento e da família. Nesse sentido, o Pleno aprovou o Verbete Vinculante 12. O mesmo raciocínio e conclusão devem ser empregados no caso de cobrança de taxa para expedição de diploma.","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"[ RE 597.872 AgR , voto do rel. min. Marco Aurélio, 1ª T, j. 3-6-2014, DJE 164 de 26-8-2014.].","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"Cobrança de taxa para inscrição em processo seletivo seriado ou vestibular","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"TAXA DE INSCRIÇÃO EM PROCESSO SELETIVO SERIADO. INGRESSO NO ENSINO SUPERIOR. UNIVERSIDADE PÚBLICA. ART. 206, IV, DA CF/1988. O mesmo raciocínio utilizado na elaboração do Verbete Vinculante 12 deve ser observado nas hipóteses de cobrança de taxa para inscrição de processo seletivo seriado em universidade pública, considerada a gratuidade do ensino público em estabelecimentos oficiais.","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"[ AI 748.944 AgR , rel. min. Marco Aurélio, 1ª T, j. 5-8-2014, DJE 164 de 26-8-2014.]","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"Vislumbro, neste juízo prévio, o confronto entre o ato emanado do juízo reclamado e o que expressamente dispõe a Súmula Vinculante 12 (...). É que, ao julgar o RE 500.171/GO, rel. min. Ricardo Lewandowski, DJE 23-10-2008, que originou a referida súmula, o Plenário desta Suprema Corte estabeleceu que a cobrança de matrícula para cursar a universidade é que ofende o art. 206, IV, da CF/1988, e não a taxa cobrada para inscrição em processo de seleção.","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"[ Rcl 7.831 MC , rel. min. Ellen Gracie, dec. monocrática, j. 6-4-2009, DJE 70 de 16-4-2009.]","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"Gratuidade de ensino prestado por fundação pública","deleted":false}],"heading":false},{"page":52,"runs":[{"text":"A gratuidade do ensino em estabelecimentos oficiais já foi pacificada pelo Supremo, resultando, inclusive, na edição do Verbete 12 da Súmula Vinculante do Tribunal. O mesmo raciocínio utilizado na elaboração do referido enunciado deve ser observado nos casos de cobrança por serviços de ensino fundamental e médio prestados por fundação pública, integrante da Administração Indireta municipal, considerada a regra do art.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"206, IV, da Carta de 1988.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"[ RE 490.839 , rel. min. Marco Aurélio, dec. monocrática, j. 1º-6-2015, DJE 111 de 11-6-2015.]","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Modulação de efeitos da declaração de inconstitucionalidade da cobrança de taxa de matrícula nas universidades públicas","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Cumpre mencionar que, em 16-3-2011, este Supremo Tribunal, por maioria, acolheu os embargos de declaração opostos no RE 500.171, para atribuir efeitos ex nunc à declaração de inconstitucionalidade da cobrança da taxa em debate. (...) Decidiu-se, também, que seriam resguardados os direitos dos estudantes que tivessem ingressado individualmente em juízo para pleitear o seu ressarcimento, não sendo autorizada, apenas, a devolução em massa pelas universidades públicas.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"[ RE 563.386 AgR , voto da rel. min. Cármen Lúcia, 1ª T, j. 14-6-2011, DJE 125 de 1º-7-2011.]","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Modulação dos efeitos da decisão que declarou a inconstitucionalidade da cobrança da taxa de matrícula nas universidades públicas a partir da edição da Súmula Vinculante 12, ressalvado o direito daqueles que já haviam ajuizado ações com o mesmo objeto jurídico.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"[ RE 500.171 ED , rel. min. Ricardo Lewandowski, P, j. 16-3-2011, DJE 106 de 3-6-2011.]","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":53,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 40, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Data de publicação do enunciado: DJE de 22-8-2008.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":53,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"13","number":"13","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":54,"endPage":62,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1227","paragraphs":[{"page":54,"runs":[{"text":"A nomeação de cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive, da autoridade nomeante ou de servidor da mesma pessoa jurídica investido em cargo de direção, chefia ou assessoramento, para o exercício de cargo em comissão ou de confiança ou, ainda, de função gratificada na administração pública direta e indireta em qualquer dos poderes da União, dos Estados, do Distrito Federal e dos Municípios, compreendido o ajuste mediante designações recíprocas, viola a Constituição Federal.","deleted":false}]}],"notes":[{"page":54,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":54,"runs":[{"text":"AÇÃO DECLARATÓRIA DE CONSTITUCIONALIDADE, AJUIZADA EM PROL DA RESOLUÇÃO 7, DE 18-10-2005, DO CONSELHO NACIONAL DE JUSTIÇA. ATO NORMATIVO QUE “DISCIPLINA O EXERCÍCIO DE CARGOS, EMPREGOS E FUNÇÕES POR PARENTES, CÔNJUGES E COMPANHEIROS DE MAGISTRADOS E DE SERVIDORES INVESTIDOS EM CARGOS DE DIREÇÃO E ASSESSORAMENTO, NO ÂMBITO DOS ÓRGÃOS DO PODER JUDICIÁRIO E DÁ OUTRAS PROVIDÊNCIAS”. PROCEDÊNCIA DO PEDIDO. 1. Os condicionamentos impostos pela Resolução 7/2005 do CNJ não atentam contra a liberdade de prover e desprover cargos em comissão e funções de confiança. As restrições constantes do ato resolutivo são, no rigor dos termos, as mesmas já impostas pela CF/1988, dedutíveis dos republicanos princípios da impessoalidade, da eficiência, da igualdade e da moralidade. (...) 3. Ação julgada procedente para: a) emprestar interpretação conforme à Constituição para deduzir a função de chefia do substantivo “direção” nos incisos II, III, IV, V do art. 2º do ato normativo em foco; b) declarar a constitucionalidade da Resolução 7/2005 do Conselho Nacional de Justiça.","deleted":false}],"heading":false},{"page":54,"runs":[{"text":"[ ADC 12 , rel. min. Ayres Britto , P, j. 20-8-2008, DJE 237 de 18-12-2008.]","deleted":false}],"heading":false},{"page":54,"runs":[{"text":"I - Embora restrita ao âmbito do Judiciário a Resolução 7/2005 do Conselho Nacional de Justiça, a prática do nepotismo nos demais Poderes é ilícita. II - A vedação do nepotismo não exige a edição de lei formal para coibir a prática. III - Proibição que decorre diretamente dos princípios contidos no art. 37, caput , da CF/1988.","deleted":false}],"heading":false},{"page":54,"runs":[{"text":"[ RE 579.951 , rel. min. Ricardo Lewandowski , P, j. 20-8-2008, DJE 202 de 24-10-2008, Tema 66.]","deleted":false}],"heading":false},{"page":54,"runs":[{"text":"Então, quando o art. 37 refere-se a cargo em comissão e função de confiança, está tratando de cargos e funções singelamente administrativos, não de cargos políticos. Portanto, os cargos políticos estariam fora do alcance da decisão que tomamos na ADC 12, porque o próprio Capítulo VII é Da Administração Pública enquanto segmento do Poder Executivo. E sabemos que os cargos políticos, como por exemplo, os de Secretário Municipal, são de agentes do Poder, fazem parte do Poder Executivo. O cargo não é em comissão, no sentido do art. 37. Somente os cargos e funções singelamente administrativos - é como penso - são alcançados pela imperiosidade do art. 37, com seus lapidares princípios. Então, essa distinção me parece importante para, no caso, excluir do âmbito da nossa decisão anterior os secretários municipais, que correspondem a secretários de Estado, no âmbito dos Estados, e ministros de Estado, no âmbito federal.","deleted":false}],"heading":false},{"page":54,"runs":[{"text":"[ RE 579.951 , rel. min. Ricardo Lewandowski , voto do min. Ayres Britto , P, j. 20-8-2008, DJE 202 de 24-10-2008, Tema 66.]","deleted":false}],"heading":false},{"page":54,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":54,"runs":[{"text":"● A vedação ao nepotismo não exige a edição de lei formal para coibir a prática, dado que essa proibição decorre diretamente dos princípios contidos no art. 37, caput , da Constituição Federal.","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"[Tese definida no RE 579.951 , rel. min. Ricardo Lewandowski , P, j. 20-8-2008, DJE 202 de 24-10-2008, Tema 66.]","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"● Leis que tratam dos casos de vedação a nepotismo não são de iniciativa exclusiva do Chefe do Poder Executivo.","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"[Tese definida no RE 570.392 , rel. min. Cármen Lúcia , P, j. 11-12-2014, DJE 32 de 19-2-2015, Tema 29.]","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":55,"runs":[{"text":"Agente político e nepotismo","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"1. Nos representativos que embasaram a aprovação da Súmula Vinculante 13, a discussão centrou-se nas nomeações para cargos em comissão e funções de confiança da administração pública (art. 37, V, CF/1988) (...). 2. A grande distinção é que a construção do enunciado se refere especificamente ao art. 37, V, CF/1988, e não a cargos políticos e nomeação política. A previsão de nomeação do primeiro escalão do chefe do Executivo está no art. 84 da Constituição Federal, tal entendimento deve ser aplicado por simetria aos Secretários estaduais e municipais (art. 76, da CF/1988). 3. A nomeação de parente, cônjuge ou companheira para cargos de natureza eminentemente política, como no caso concreto, em que a esposa do Prefeito foi escolhida para exercer cargo de Secretária Municipal, não se subordina ao Enunciado Vinculante 13 (...).","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"[ Rcl 31.732 , rel. min. Marco Aurélio , red. p/ o ac. min. Alexandre de Moraes , 1ª T, j. 5-11-2019, DJE 19 de 3-2-2020.]","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"NOMEAÇÃO PARA CARGOS POLÍTICOS DO PRIMEIRO ESCALÃO DO PODER EXECUTIVO. CRITÉRIOS FIXADOS DIRETAMENTE PELO TEXTO CONSTITUCIONAL. EXCEPCIONALIDADE DA APLICAÇÃO DA SV 13 NO CASO DE COMPROVADA FRAUDE. INOCORRÊNCIA. NOMEAÇÃO VÁLIDA. DESPROVIMENTO. PRECEDENTES. 1. O texto constitucional estabelece os requisitos para a nomeação dos cargos de primeiro escalão do Poder Executivo (Ministros), aplicados por simetria aos Secretários estaduais e municipais. 2. Inaplicabilidade da SV 13, salvo comprovada fraude na nomeação, conforme precedentes (...).","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"[ Rcl 34.413 AgR , rel. min. Alexandre de Moraes , 1ª T, j. 27-9-2019, DJE 220 de 10-10-2019.]","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"A Reclamada e as partes beneficiadas sustentam, no mérito, (...) que (...) foram nomeados para cargo de natureza política, em face do qual não se aplicaria a Súmula Vinculante 13. (...) Em que pesem as decisões do Tribunal excepcionando a sua incidência a cargos de natureza política, a orientação que emerge dos debates da aprovação da Súmula, assim como dos precedentes que lhe deram origem, não autoriza a interpretação segundo a qual a designação de parentes para cargo de natureza política é imune ao princípio da impessoalidade. Noutras palavras, cargos políticos também estão abrangidos pela Súmula Vinculante. Essa conclusão decorre dos próprios fundamentos pelos quais o Tribunal reconheceu na proibição de nepotismo uma zona de certeza dos princípios da moralidade, da impessoalidade e da eficiência. (...) A interpretação que excepciona da incidência da Súmula Vinculante os cargos de natureza política não encontra, portanto, amparo na Constituição. (...) Ante o exposto, julgo integralmente procedente a presente reclamação para cassar: (...).","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"[ Rcl 26.448 , rel. min. Edson Fachin , dec. monocrática, j. 12-9-2019, DJE 201 de 17-9-2019.]","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"2. Nomeação de cônjuge de Prefeita para ocupar cargo de Secretário municipal. 3. Agente político. Ausência de violação ao disposto na Súmula Vinculante 13. 4. Os cargos que compõem a estrutura do Poder Executivo são de livre nomeação e exoneração pelo Chefe desse Poder. 4. Fraude à lei ou hipótese de nepotismo cruzado por designações recíprocas. Inocorrência.","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"[ Rcl 22.339 AgR , rel. min. Edson Fachin , red. p/ o ac. min. Gilmar Mendes , 2ª T, j. 4-9-2018, DJE 55 de 21-3-2019.]","deleted":false}],"heading":false},{"page":55,"runs":[{"text":"RECURSO EXTRAORDINÁRIO. CONSTITUCIONAL. ADMINISTRATIVO. LEI 4.627/2013, QUE MODIFICOU A LEI 3.809/1999 DO MUNICÍPIO DE TUPÃ SP. AÇÃO DIRETA DE INCONSTITUCIONALIDADE EM ÂMBITO","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"ESTADUAL. PROVIMENTO DE CARGOS PÚBLICOS. GRAU DE PARENTESCO. AGENTES POLÍTICOS. NEPOTISMO. SÚMULA VINCULANTE 13. PRINCÍPIOS REPUBLICANOS DA MORALIDADE, IMPESSOALIDADE, IGUALDADE E EFICIÊNCIA DA ADMINISTRAÇÃO PÚBLICA. SEGURANÇA JURÍDICA. MANIFESTAÇÃO PELA REPERCUSSÃO GERAL.","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"[ RE 1.133.118 RG , rel. min. Luiz Fux , j. 14-06-2018, P, DJE 123 de 21-6-2018, Tema 1.000.]","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"Direito Administrativo. Agravo interno em reclamação. Nepotismo. Súmula Vinculante 13. 1. O Supremo Tribunal Federal tem afastado a aplicação da Súmula Vinculante 13 a cargos públicos de natureza política, ressalvados os casos de inequívoca falta de razoabilidade, por manifesta ausência de qualificação técnica ou inidoneidade moral. Precedentes. 2. Não há nos autos qualquer elemento que demonstre a ausência de razoabilidade da nomeação.","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"[ Rcl 28.024 AgR , rel. min. Roberto Barroso , 1ª T, j. 29-5-2018, DJE 125 de 25-6-2018.]","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"7. A jurisprudência do Supremo Tribunal Federal tem majoritariamente afastado a aplicação da Súmula Vinculante 13 aos cargos de natureza política, conceito no qual se incluem os secretários municipais ou estaduais. (...) 8. Registro que as hipóteses de nepotismo cruzado, fraude à lei ou inequívoca falta de razoabilidade da indicação, por manifesta ausência de qualificação técnica ou idoneidade moral do nomeado, vem sendo ressalvadas da aplicação desse entendimento pela jurisprudência do Supremo Tribunal Federal. No entanto, os documentos que instruem os autos não constituem prova inequívoca a respeito da presença de tais circunstâncias. De forma específica, os comprovantes de escolaridade que instruem os autos (docs. 47, 48 e 49) não corroboram a alegação de que a qualificação técnica dos nomeados seria manifestamente insuficiente para o exercício dos cargos públicos para os quais foram nomeados.","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"[ Rcl 29.099 , rel. min. Roberto Barroso , dec. monocrática, j. 4-4-2018, DJE 66 de 9-4-2018.]","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"A jurisprudência do STF preconiza que, ressalvada situação de fraude à lei, a nomeação de parentes para cargos públicos de natureza política não desrespeita o conteúdo normativo do enunciado da Súmula Vinculante 13.","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"[ RE 825.682 AgR , rel. min. Teori Zavascki , 2ª T, j. 10-2-2015, DJE 39 de 2-3-2015.]","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"Os cargos políticos são caracterizados não apenas por serem de livre nomeação ou exoneração, fundadas na fidúcia, mas também por seus titulares serem detentores de um munus governamental decorrente da Constituição Federal, não estando os seus ocupantes enquadrados na classificação de “agentes administrativos”. 2. Em hipóteses que atinjam ocupantes de cargos políticos, a configuração do nepotismo deve ser analisada caso a caso, a fim de se verificar eventual “troca de favores” ou fraude a lei. 3. Decisão judicial que anula ato de nomeação para cargo político apenas com fundamento na relação de parentesco estabelecida entre o nomeado e o chefe do Poder Executivo, em todas as esferas da Federação, diverge do entendimento da Suprema Corte consubstanciado na Súmula Vinculante 13.","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"[ Rcl 7.590 , rel. min. Dias Toffoli , 1ª T, j. 30-9-2014, DJE 224 de 14-11-2014.]","deleted":false}],"heading":false},{"page":56,"runs":[{"text":"Em princípio, a questão parece enquadrar-se no teor da Súmula Vinculante 13: o interessado é parente de segundo grau, em linha colateral, da vice-prefeita do Município, que, embora não seja a autoridade nomeante, encaixa-se na categoria de “servidor da mesma pessoa jurídica investido em cargo de direção, chefia ou assessoramento”, se compreendida de forma ampla. Resta saber, portanto, se a circunstância de se tratar de cargo de natureza política impediria a incidência do enunciado. 6. Na Rcl 6.650 MC-AgR/PR (rel. min. Ellen Gracie), esta Corte afirmou a “[i]mpossibilidade de submissão do reclamante, Secretário Estadual de Transporte, agente político, às hipóteses expressamente elencadas na Súmula Vinculante 13, por se tratar de cargo de natureza política”. No entanto, não se pode perder de vista que se estava em sede cautelar, de modo que a matéria não foi conhecida de forma exauriente e aprofundada. Tanto assim que, nessa ocasião, alguns ministros observaram que a caracterização do nepotismo não estaria afastada em todo e qualquer caso de nomeação para cargo político, cabendo examinar cada situação com a cautela necessária. (...) 7. Notas","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"semelhantes foram feitas quando do julgamento do precedente que resultou na edição da Súmula Vinculante (RE 579.951/RN, rel. min. Ricardo Lewandowski). Além do relator, os ministros Cármen Lúcia e Cezar Peluso registraram a possibilidade de se caracterizar o nepotismo em algumas dessas situações - o que só se poderia examinar no caso concreto. 8. Estou convencido de que, em linha de princípio, a restrição sumular não se aplica à nomeação para cargos políticos. Ressalvaria apenas as situações de inequívoca falta de razoabilidade, por ausência manifesta de qualificação técnica ou de inidoneidade moral.","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"[ Rcl 17.627 , rel. min. Roberto Barroso , dec. monocrática, j. 8-5-2014, DJE 92 de 15-5-2014.]","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"Assim, em linha com o afirmado pelo reclamante, tenho que os acórdãos proferidos por este Supremo Tribunal Federal no RE 579.951 e na medida cautelar na Rcl 6.650 não podem ser considerados representativos da jurisprudência desta Corte e tampouco podem ser tomados como reconhecimento definitivo da exceção à Súmula Vinculante 13 pretendida pelo Município reclamado. Bem vistas as coisas, o fato é que a redação do verbete não prevê a exceção mencionada e esta, se vier a ser reconhecida, dependerá da avaliação colegiada da situação concreta descrita nos autos, não cabendo ao relator antecipar-se em conclusão contrária ao previsto na redação da súmula, ainda mais quando baseada em julgamento proferido em medida liminar. Registro, ainda, que a apreciação indiciária dos fatos relatados, própria do juízo cautelar, leva a conclusão desfavorável ao reclamado. É que não há, em passagem alguma das informações prestadas pelo Município, qualquer justificativa de natureza profissional, curricular ou técnica para a nomeação do parente ao cargo de Secretário Municipal de Educação. Tudo indica, portanto, que a nomeação impugnada não recaiu sobre reconhecido profissional da área da educação que, por acaso, era parente do prefeito, mas, pelo contrário, incidiu sobre parente do prefeito que, por essa exclusiva razão, foi escolhido para integrar o secretariado municipal.","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"[ Rcl 12.478 MC , rel. min. Joaquim Barbosa , dec. monocrática, j. 3-11-2011, DJE 212 de 8-11-2011.]","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"As nomeações para cargos políticos não se subsumem às hipóteses elencadas nessa súmula. Daí a impossibilidade de submissão do caso do reclamante, nomeação para o cargo de Secretário Estadual de Transporte, agente político, à vedação imposta pela Súmula Vinculante 13, por se tratar de cargo de natureza eminentemente política. Por esta razão, não merece provimento o recurso ora interposto.","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"[ Rcl 6.650 MC-AgR , voto da rel. min. Ellen Gracie , P, j. 16-10-2008, DJE 222 de 21-11-2008.]","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"Caracterização do nepotismo por critérios objetivos","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"O ingresso de servidor público nos quadros da Administração por concurso público é o meio pelo qual a Constituição consagra o princípio meritocrático. Há funções e cargos que são destinados exclusivamente a servidores de carreira e, por isso, o acesso de servidores a cargos e funções de confiança não é, em princípio, incompatível com a Constituição. Há situações, no entanto, em que o exercício da função de confiança apresenta potencial conflito de interesse. É precisamente o que ocorre quando a nomeação para cargo ou a designação para função recai sobre servidor que guarda relação de parentesco ou relação íntima com a autoridade nomeante. Nesses casos, tal como se dá com a nomeação de quem não tem vínculo, o exercício do cargo passa a atender critérios que não são exclusivamente públicos e a confiança que se deve ter no desempenho da função pública é prejudicada. Contraria, pois, a Súmula Vinculante a nomeação de servidor de cargo efetivo ou a sua designação para função de confiança, quando feita por autoridade que guarde com ele vínculo de parentesco.","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"[ Rcl 26.448 , rel. min. Edson Fachin , dec. monocrática, j. 12-9-2019, DJE 201 de 17-9-2019.]","deleted":false}],"heading":false},{"page":57,"runs":[{"text":"Pelos documentos citados, tem-se que o irmão do impetrante fora investido no cargo de Juiz Federal quando o impetrante foi nomeado para exercer função comissionada no Tribunal Regional Federal da 1ª Região. (...) Não prospera, portanto, o argumento de que seria necessária comprovação de “vínculo de amizade ou troca de favores” entre o irmão do ora impetrante e o desembargador de quem é assistente processual, pois é a análise objetiva da situação de parentesco entre o servidor e a pessoa nomeada para exercício de cargo em comissão","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"ou de confiança na mesma pessoa jurídica da Administração Pública que configura a situação de nepotismo vedada, originariamente, pela Constituição da República. Logo, é desnecessário demonstrar a intenção de violar a vedação constitucional ou a obtenção de qualquer benefício com o favorecimento de parentes de quem exerça poder na esfera pública para que se estabeleça relação de nepotismo.","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"[ MS 27.945 , voto da rel. min. Cármen Lúcia , 2ª T, j. 26-8-2014, DJE 171 de 4-9-2014.]","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"Competência do TCU para apurar ato que configura nepotismo cruzado","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"Reconhecida a competência do Tribunal de Contas da União para a verificação da legalidade do ato praticado pelo impetrante, nos termos do art. 71, VIII e IX, da CF/1988. Procedimento instaurado no TCU a partir de encaminhamento de autos de procedimento administrativo concluído pelo Ministério Público Federal no Estado do Espírito Santo. No mérito, configurada a prática de nepotismo cruzado, tendo em vista que a assessora nomeada pelo impetrante para exercer cargo em comissão no Tribunal Regional do Trabalho da 17ª Região, sediado em Vitória/ES, é nora do magistrado que nomeou a esposa do impetrante para cargo em comissão no Tribunal Regional do Trabalho da 1ª Região, sediado no Rio de Janeiro/RJ. A nomeação para o cargo de assessor do impetrante é ato formalmente lícito. Contudo, no momento em que é apurada a finalidade contrária ao interesse público, qual seja, uma troca de favores entre membros do Judiciário, o ato deve ser invalidado, por violação ao princípio da moralidade administrativa e por estar caracterizada a sua ilegalidade, por desvio de finalidade.","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"[ MS 24.020 , rel. min. Joaquim Barbosa , 2ª T, j. 6-3-2012, DJE 114 de 13-6-2012.]","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"Lei estadual que prevê hipóteses de exceção ao nepotismo","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"A previsão impugnada, ao permitir (excepcionar), relativamente a cargos em comissão ou funções gratificadas, a nomeação, a admissão ou a permanência de até dois parentes das autoridades mencionadas no caput do art. 1º da Lei estadual 13.145/1997 e do cônjuge do chefe do Poder Executivo, além de subverter o intuito moralizador inicial da norma, ofende irremediavelmente a CF/1988.","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"[ ADI 3.745 , rel. min. Dias Toffoli , P, j. 15-5-2013, DJE 148 de 1º-8-2013.]","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"Lei municipal que veda participação em licitações em decorrência de parentesco","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"É importante registrar que a Lei 8.666/1993 estabelece, em seu art. 9º, uma série de impedimentos à participação nas licitações. (...) É certo que o referido art. 9º não estabeleceu, expressamente, restrição à contratação com parentes dos administradores, razão por que há doutrinadores que sustentam, com fundamento no princípio da legalidade, que não se pode impedir a participação de parentes nos procedimentos licitatórios, se estiverem presentes os demais pressupostos legais, em particular a existência de vários interessados em disputar o certame ( ... ). Não obstante, entendo que, em face da ausência de regra geral para este assunto, o que significa dizer que não há vedação ou permissão acerca do impedimento à participação em licitações em decorrência de parentesco, abre-se campo para a liberdade de atuação dos demais entes da Federação, a fim de que eles legislem de acordo com suas particularidades locais (no caso dos Municípios, com fundamento no art. 30, II, da CF/1988), até que sobrevenha norma geral sobre o tema. E dentro da permissão constitucional para legislar sobre normas específicas em matéria de licitação, é de se louvar a iniciativa do Município de Brumadinho/MG de tratar, em sua Lei Orgânica, de questão das mais relevantes em nossa pólis, que é a moralidade administrativa, princípio-guia de toda a atividade estatal, nos termos do art. 37, caput , da CF/1988.","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"[ RE 423.560 , voto do rel. min. Joaquim Barbosa , 2ª T, j. 29-5-2012, DJE 119 de 19-6-2012.]","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"Necessidade de se demonstrar potencial de interferência em seleção de candidato a cargo de direção, chefia ou assessoramento para configuração de nepotismo","deleted":false}],"heading":false},{"page":58,"runs":[{"text":"Não se pode perder de vista que o precedente representativo da Súmula Vinculante 13 é o resultado produzido pela declaração de constitucionalidade da Resolução 7/2005 do Conselho Nacional de Justiça - CNJ (...).","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"Sobre o alcance do ato normativo acima transcrito, já me manifestei, enquanto Conselheiro Nacional de Justiça, em situações envolvendo o Poder Judiciário, considerando NECESSÁRIA a presença de vínculo de subordinação entre dois cargos de comissão de assessoramento, exercidos por parentes, para configurar o nepotismo (...). Na presente hipótese, tem razão a reclamante. Essa premissa deixou de ser considerada pelo ato reclamado (...). Como se vê, o caso acima envolve nomeação de pessoas que, apesar de parentes entre si, não guardam nenhum parentesco com a autoridade nomeante, nem qualquer vínculo de subordinação entre elas. Inclusive, integram os quadros de pessoas jurídicas distintas. Sendo, portanto, indevida a aplicação da Súmula Vinculante 13 no caso.","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"[ Rcl 28.164 , rel. min. Alexandre de Moraes , dec. monocrática, j. 27-3-2018, DJE 61 de 3-4-2018.]","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"Ao editar a Súmula Vinculante 13, embora não se tenha pretendido esgotar todas as possibilidades de configuração de nepotismo na Administração Pública, foram erigidos critérios objetivos de conformação, a saber: i) ajuste mediante designações recíprocas, quando inexistente a relação de parentesco entre a autoridade nomeante e o ocupante do cargo de provimento em comissão ou função comissionada; ii) relação de parentesco entre a pessoa nomeada e a autoridade nomeante; iii) relação de parentesco entre a pessoa nomeada e o ocupante de cargo de direção, chefia ou assessoramento a quem estiver subordinada e iv) relação de parentesco entre a pessoa nomeada e a autoridade que exerce ascendência hierárquica ou funcional sobre a autoridade nomeante. 2. A incompatibilidade da prática enunciada na Súmula Vinculante 13 com o art. 37, caput , da CF/1988 não decorre diretamente da existência de relação de parentesco entre pessoa designada e agente político ou servidor público ocupante de cargo em comissão ou função comissionada, mas da presunção de que a escolha para ocupar cargo de direção, chefia ou assessoramento tenha sido direcionada a pessoa com relação de parentesco com alguém que tenha potencial de interferir no processo de seleção.","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"[ Rcl 19.529 AgR , rel. min. Dias Toffoli , 2ª T, j. 15-3-2016, DJE 72 de 18-4-2016.]","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"Em sede reclamatória, com fundamento na Súmula Vinculante 13, é imprescindível a perquirição de projeção funcional ou hierárquica do agente político ou do servidor público de referência no processo de seleção para fins de configuração objetiva de nepotismo na contratação de pessoa com relação de parentesco com ocupante de cargo de direção, chefia ou assessoramento no mesmo órgão, salvo ajuste mediante designações recíprocas. 3. Reclamação julgada improcedente. Cassada a liminar anteriormente deferida.","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"[ Rcl 18.564 , rel. min. Gilmar Mendes , red. p/ o ac. min. Dias Toffoli , 2ª T, j. 23-2-2016, DJE 161 de 3-8-2016.]","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"Nepotismo e conceito de parentesco por afinidade segundo o Código Civil/2002","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"(...), a jurisprudência desta Corte afirma que o conceito de parentesco para efeitos da incidência da Súmula não é o do Código Civil, como bem apontou o e. Min. Nelson Jobim, quando do julgamento da ADC 12 MC, Rel. Min. Ayres Britto: “a questão do parentesco definida no Código Civil é para efeitos civis e, aqui, visa-se a vigência absoluta do princípio da impessoalidade”. Isso porque, como bem destacou o e. Min. Cezar Peluso, “o problema não é de definir quais são os parentes para efeitos civis, mas definir quais aquelas pessoas que, sob a classe de parentela, tendem a ser escolhidas, não por interesse público, mas por interesse de caráter pessoal”. (...) Como se observa da leitura desses precedentes, a limitação constante do § 1º do art. 1.595 do Código Civil não tem aplicação para efeitos da Súmula Vinculante 13, vale dizer, o parentesco por afinidade não é limitado apenas aos ascendentes, descendentes, irmãos, cônjuges ou companheiros. Para efeitos da Súmula Vinculante 13, os chamados “concunhados” estão abrangidos no conceito de parente de 3º grau em linha colateral.","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"[ Rcl 26.448 , rel. min. Edson Fachin , dec. monocrática, j. 12-9-2019, DJE 201 de 17-9-2019.]","deleted":false}],"heading":false},{"page":59,"runs":[{"text":"A Súmula Vinculante 13 é expressa em incluir a nomeação de parentes por afinidade, até o terceiro grau, inclusive, no conceito de nepotismo. Tal formulação, é verdade, pode se entender que conflitaria com o conceito de parentesco delimitado na lei civil, que, conforme já ressaltado, limita-o aos ascendentes,","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"descendentes e irmãos do cônjuge ou companheiro. Essa suposta incompatibilidade, contudo, foi afastada por este Tribunal por ocasião do julgamento da ADC 12 MC/DF, rel. min. Ayres Britto. (...) Verifica-se, dessa forma, que há independência entre as esferas civil e administrativo-constitucional, razão pela qual o conceito de parentesco estabelecido no Código Civil/2002 não tem o mesmo alcance para fins de obediência aos princípios da impessoalidade, moralidade e eficiência, que vedam a prática de nepotismo na Administração Pública.","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"[ Rcl 9.013 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 21-9-2011, DJE 184 de 26-9-2011.]","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Nepotismo e conselheiro fiscal de Instituto de Previdência Municipal","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"(...) o cargo de conselheiro fiscal do Instituto de Previdência municipal, cuja a nomeação é de livre escolha do chefe do Poder Executivo, está intimamente ligado à operacionalização do regime próprio de previdência e à devida gestão dos recursos. Sendo, portanto, fundamental zelar pela imparcialidade das decisões do colegiado, garantindo a devida independência dos conselheiros membros, em proteção aos princípios da moralidade e impessoalidade. (...) Nessas circunstâncias, em que o chefe do Poder Executivo nomeia seus dois irmãos como representantes do Executivo junto ao quadro do Conselho Fiscal IAPREV, tem-se configurada a prática de nepotismo, nos termos vedados pela Súmula Vinculante 13.","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"[ Rcl 28.842 , rel. min. Alexandre de Moraes , dec. monocrática, j. 15-5-2018, DJE 97 de 18-5-2018.]","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Nepotismo e conselheiro de Tribunal de Contas","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Com efeito, a doutrina, de um modo geral, repele o enquadramento dos Conselheiros dos Tribunais de Contas na categoria de agentes políticos, os quais, como regra, estão fora do alcance da Súmula Vinculante 13, salvo nas exceções acima assinaladas, quais sejam, as hipóteses de nepotismo cruzado ou de fraude à lei. (...) Convém assinalar, ainda, que se afigura de duvidosa constitucionalidade, à luz do princípio da simetria, a escolha de membros do Tribunal de Contas pela Assembleia Legislativa por votação aberta, quando o art. 52, III, b , da CF/1988 determina que seja fechada em casos análogos, instituída para a proteção dos próprios parlamentares. Não fosse tudo isso, a nomeação do irmão, pelo governador do Estado, para ocupar o cargo de Conselheiro do TCE, agente incumbido pela CF/1988 de fiscalizar as contas do nomeante, está a sugerir, ao menos neste exame preliminar da matéria, afronta direta aos mais elementares princípios republicanos.","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"[ Rcl 6.702 MC-AgR , voto do rel. min. Ricardo Lewandowski , P, j. 4-3-2009, DJE 79 de 30-4-2009.]","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Nepotismo e Procurador-Geral de Município","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Veja que os órgãos integrantes do primeiro escalão do Executivo municipal encontram-se taxativamente enumerados nos incisos do art. 12 da lei, dentre os quais não se encontra a Procuradoria municipal. (...) Em todo caso, ainda que a lei municipal tivesse, efetivamente, atribuído índole política às funções exercidas pelo Procurador-Geral, isso não se revelaria suficiente para transmudar a natureza de suas atribuições, de caráter eminentemente técnico, voltadas, primordialmente, à representação judicial do ente municipal e assessoramento jurídico do prefeito. Em outras palavras, o Procurador-Geral, diferentemente dos Secretários elencados no art. 12, não participa da formulação das linhas de atuação política da municipalidade. Assim sendo, a autoridade reclamada, ao afastar o caráter político do cargo em exame para enquadrá-lo nas vedações insertas na Súmula Vinculante n. 13, não aplicou indevidamente o preceito sumular.","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"[ Rcl 60.852 , rel. min. Nunes Marques , dec. monocrática, j. 5-6-2024, DJE de 6-6-2024.]","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Servidor concursado e norma antinepotismo","deleted":false}],"heading":false},{"page":60,"runs":[{"text":"Evidente que se devem retirar da incidência da norma os servidores admitidos mediante concurso público, ocupantes de cargo de provimento efetivo. A norma antinepotismo deve incidir sobre cargos de provimento em comissão, as funções gratificadas e os cargos de direção e assessoramento. Esse o quadro, julgo procedente, em parte, a ação direta para emprestar interpretação conforme à Constituição para declarar constitucional o inciso VI do art. 32 da Constituição do Estado do Espírito Santo, somente quando incida sobre os cargos de provimento em comissão, função gratificada, cargos de direção e assessoramento: é o meu voto.","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"[ ADI 524 , voto do rel. min. Sepúlveda Pertence , red. p/ o ac. min. Ricardo Lewandowski , P, j. 20-5-2015, DJE 151 de 3-8-2015.]","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Servidor público efetivo sem cargo de direção, chefia ou assessoramento e relação de parentesco com servidor comissionado no mesmo órgão","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"(...) No caso em exame, a parente colateral da servidora da mesma pessoa jurídica, a irmã da reclamante, não está investida em cargo de direção, chefia ou assessoramento, mas somente no cargo de professora. Portanto, a nomeação da reclamante a cargo de comissão ou confiança, na espécie, Vice-Diretora, não contraria a Súmula Vinculante n. 13 do Supremo Tribunal Federal. (...) Pelo exposto, julgo parcialmente procedente a presente reclamação para cassar a decisão proferida (...) e determinar outra seja proferida como de direito, sem a aplicação da Súmula Vinculante n. 13 deste Supremo Tribunal. (...)","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"[ Rcl 60.948 , rel. min. Cármen Lúcia , dec. monocrática, j. 21-7-2023, DJE s/n de 24-7-2023.]","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Considerada a amplitude e a complexidade da estrutura administrativa dos diversos órgãos do Poder Judiciário no tocante à gestão de seus servidores (efetivos ou não), entendo que não configura nepotismo a nomeação de pessoa sem vínculo efetivo com o órgão para cargo de direção, chefia ou assessoramento sem que se questione a existência de qualquer influência do servidor efetivo com quem o nomeado é casado, mantém relação estável ou possui relação de parentesco sobre a autoridade nomeante, seja para fins de se alcançarem interesses pessoais do servidor efetivo (devido a relações de amizade, subordinação ou mudança de localidade, por exemplo) ou da autoridade nomeante (mediante troca de favores), sob pena de se afrontar um dos princípios que a própria Resolução/CNJ 7/2005 e a Súmula Vinculante 13 pretenderam resguardar, qual seja, o princípio constitucional da impessoalidade. (...) para se configurar o nepotismo, o cônjuge, servidor efetivo, da nomeada em cargo em comissão, deve estar investido em cargo de chefia, direção ou de assessoramento. E essa verificação deve ser feita na data da nomeação da impetrante.","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"[ MS 28.485 , voto do rel. min. Dias Toffoli , 1ª T, j. 11-11-2014, DJE 238 de 4-12-2014.]","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Súmula Vinculante 13 e não exaurimento das possibilidades de nepotismo","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Ao editar a Súmula Vinculante 13, a Corte não pretendeu esgotar todas as possibilidades de configuração de nepotismo na Administração Pública, dada a impossibilidade de se preverem e de se inserirem, na redação do enunciado, todas as molduras fático-jurídicas reveladas na pluralidade de entes da Federação (União, Estados, Distrito Federal, Territórios e Municípios) e das esferas de Poder (Executivo, Legislativo e Judiciário), com as peculiaridades de organização em cada caso. Dessa perspectiva, é certo que a edição de atos regulamentares ou vinculantes por autoridade competente para orientar a atuação dos demais órgãos ou entidades a ela vinculados quanto à configuração do nepotismo não retira a possibilidade de, em cada caso concreto, proceder-se à avaliação das circunstâncias à luz do art. 37, caput , da CF/1988","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"[ MS 31.697 , voto do rel. min. Dias Toffoli , 1ª T, j. 11-3-2014, DJE 65 de 2-4-2014.]","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"A redação do enunciado da Súmula Vinculante 13 não pretendeu esgotar todas as possibilidades de configuração de nepotismo da Administração Pública, uma vez que a tese constitucional nele consagrada consiste na proposição de que essa irregularidade decorre diretamente do caput do art. 37 da Constituição Federal, independentemente da edição de lei formal sobre o tema.","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"[ Rcl 15.451 AgR , rel. min. Dias Toffoli , P, j. 27-2-2014, DJE 66 de 3-4-2014.]","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":61,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 66, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Data de publicação do enunciado: DJE de 29-8-2008.","deleted":false}],"heading":false},{"page":61,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":62,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"14","number":"14","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":63,"endPage":73,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1230","paragraphs":[{"page":63,"runs":[{"text":"É direito do defensor, no interesse do representado, ter acesso amplo aos elementos de prova que, já documentados em procedimento investigatório realizado por órgão com competência de polícia judiciária, digam respeito ao exercício do direito de defesa.","deleted":false}]}],"notes":[{"page":63,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":63,"runs":[{"text":"Há, é verdade, diligências que devem ser sigilosas, sob risco de comprometimento do seu bom sucesso. Mas, se o sigilo é aí necessário à apuração e à atividade instrutória, a formalização documental de seu resultado já não pode ser subtraída ao indiciado nem ao defensor, porque, é óbvio, cessou a causa mesma do sigilo. (...) Os atos de instrução, enquanto documentação dos elementos retóricos colhidos na investigação, esses devem estar acessíveis ao indiciado e ao defensor, à luz da Constituição da República, que garante à classe dos acusados, na qual não deixam de situar-se o indiciado e o investigado mesmo, o direito de defesa. O sigilo aqui, atingindo a defesa, frustra-lhe, por conseguinte, o exercício. (...) 5. Por outro lado, o instrumento disponível para assegurar a intimidade dos investigados (...) não figura título jurídico para limitar a defesa nem a publicidade, enquanto direitos do acusado. E invocar a intimidade dos demais investigados, para impedir o acesso aos autos, importa restrição ao direito de cada um dos envolvidos, pela razão manifesta de que os impede a todos de conhecer o que, documentalmente, lhes seja contrário. Por isso, a autoridade que investiga deve, mediante expedientes adequados, aparelhar-se para permitir que a defesa de cada paciente tenha acesso, pelo menos, ao que diga respeito a seu constituinte.","deleted":false}],"heading":false},{"page":63,"runs":[{"text":"[ HC 88.190 , voto do rel. min. Cezar Peluso, 2ª T, j. 29-8-2006, DJ de 6-10-2006.]","deleted":false}],"heading":false},{"page":64,"runs":[{"text":"Tese de Controle Concentrado","deleted":false}],"heading":true},{"page":64,"runs":[{"text":"● 1. O Ministério Público dispõe de atribuição concorrente para promover, por autoridade própria, e por prazo razoável, investigações de natureza penal, desde que respeitados os direitos e garantias que assistem a qualquer indiciado ou a qualquer pessoa sob investigação do Estado. Devem ser observadas sempre, por seus agentes, as hipóteses de reserva constitucional de jurisdição e, também, as prerrogativas profissionais da advocacia, sem prejuízo da possibilidade do permanente controle jurisdicional dos atos, necessariamente documentados (Súmula Vinculante 14), praticados pelos membros dessa Instituição (tema 184); 2. A realização de investigações criminais pelo Ministério Público tem por exigência: (i) comunicação imediata ao juiz competente sobre a instauração e o encerramento de procedimento investigatório, com o devido registro e distribuição; (ii) observância dos mesmos prazos e regramentos previstos para conclusão de inquéritos policiais; (iii) necessidade de autorização judicial para eventuais prorrogações de prazo, sendo vedadas renovações desproporcionais ou imotivadas; iv) distribuição por dependência ao Juízo que primeiro conhecer de PIC ou inquérito policial a fim de buscar evitar, tanto quanto possível, a duplicidade de investigações; v) aplicação do artigo 18 do Código de Processo Penal ao PIC (Procedimento Investigatório Criminal) instaurado pelo Ministério Público; 3. Deve ser assegurado o cumprimento da determinação contida nos itens 18 e 189 da Sentença no Caso Honorato e Outros versus Brasil, de 27 de novembro de 2023, da Corte Interamericana de Direitos Humanos - CIDH, no sentido de reconhecer que o Estado deve garantir ao Ministério Público, para o fim de exercer a função de controle externo da polícia, recursos econômicos e humanos necessários para investigar as mortes de civis cometidas por policiais civis ou militares; 4. A instauração de procedimento investigatório pelo Ministério Público deverá ser motivada sempre que houver suspeita de envolvimento de agentes dos órgãos de segurança pública na prática de infrações penais ou sempre que mortes ou ferimentos graves ocorram em virtude da utilização de armas de fogo por esses mesmos agentes. Havendo representação ao Ministério Público, a não instauração do procedimento investigatório deverá ser sempre motivada; 5. Nas investigações de natureza penal, o Ministério Público pode requisitar a realização de perícias técnicas, cujos peritos deverão gozar de plena autonomia funcional, técnica e científica na realização dos laudos.","deleted":false}],"heading":false},{"page":64,"runs":[{"text":"[Tese definida na ADI 2.943 , rel. min. Edson Fachin, P, j. 2-5-2024, DJE s/n de 10-9-2024.]","deleted":false}],"heading":false},{"page":64,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":64,"runs":[{"text":"● O Ministério Público dispõe de competência para promover, por autoridade própria, e por prazo razoável, investigações de natureza penal, desde que respeitados os direitos e garantias que assistem a qualquer indiciado ou a qualquer pessoa sob investigação do Estado, observadas, sempre, por seus agentes, as hipóteses de reserva constitucional de jurisdição e, também, as prerrogativas profissionais de que se acham investidos, em nosso país, os advogados (Lei 8.906/1994, art. 7º, notadamente os incisos I, II, III, XI, XIII, XIV e XIX), sem prejuízo da possibilidade - sempre presente no Estado Democrático de Direito - do permanente controle jurisdicional dos atos, necessariamente documentados (Súmula Vinculante 14), praticados pelos membros dessa instituição.","deleted":false}],"heading":false},{"page":64,"runs":[{"text":"[ Tese definida no RE 593.727 , rel. min. Cezar Peluso, red. p/ o ac. min. Gilmar Mendes, P, j. 14-5-2015, DJE 175 de 8-9-2015, Tema 184.]","deleted":false}],"heading":false},{"page":64,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":64,"runs":[{"text":"Acesso a dados de testemunha ou vítima protegida","deleted":false}],"heading":false},{"page":64,"runs":[{"text":"Assim, injustificável o óbice à extração de cópia da pasta referente à proteção de vítima e testemunha, mormente porque na denúncia sequer consta o nome da “vítima” arrolada pela acusação (...). Ante o exposto, julgo procedente a presente reclamação (art. 557, § 1º, do CPC/1973), para garantir o direito de o reclamante extrair cópia reprográfica da pasta de vítimas e testemunhas protegidas (Provimento 32/2000 TJ/SP),","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"esclarecendo-se que o acesso diz respeito apenas aos dados das vítimas e testemunhas referentes aos autos (...).","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"[ Rcl 11.358 , rel. min. Gilmar Mendes , dec. monocrática, j. 10-12-2012, DJE 244 de 13-12-2012.]","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"Restou esclarecido nos autos que o fundado temor das testemunhas de acusação sofrerem atentados ou represálias é que ensejou o sigilo de seus dados qualificativos. Inobstante, consignado também que a identificação das testemunhas protegidas fica anotada em separado, fora dos autos, com acesso exclusivo ao magistrado, promotor de justiça e advogados de defesa, a afastar qualquer prejuízo ao acusado. Não bastasse, a magistrada de primeiro grau ressaltou que o acesso a tais dados já fora franqueado ao reclamante, possibilitando-lhe identificar, a qualquer tempo, as testemunhas protegidas no referido arquivo, com o que resguardado o exercício do postulado constitucional da ampla defesa. 7. Portanto, não há, nos autos da presente reclamação, substrato fático ou jurídico capaz de atrair a incidência do enunciado da Súmula Vinculante 14, diante do acesso do reclamante às informações referentes às testemunhas de acusação.","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"[ Rcl 10.149 , rel. min. Rosa Weber , dec. monocrática, j. 22-2-2012, DJE 42 de 29-2-2012.]","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"Acesso a mídias de interceptação telefônica","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"(...) a defesa reitera que a reclamação mantém seu objeto porque ainda não foram disponibilizados nos autos os elementos probatórios produzidos na renovação da interceptação telefônica e na inclusão de novo numeral (eDOC 13, p. 3).(...) Tendo em conta essa notícia de que supostamente referidos dados teriam sido omitidos da defesa, vislumbro que aos defensores foi negado conhecimento sobre elemento de prova que diga respeito a relevante exercício do direito de defesa. Necessária se faz, portanto, a concessão de acesso a esses conteúdos, em obediência ao disposto na Súmula Vinculante 14. Ante o exposto, julgo parcialmente procedente o pedido apenas para garantir o direito de o reclamante a ter acesso aos dados probatórios produzidos na renovação da interceptação telefônica e na inclusão de novo numeral, desde que já documentados e que não digam respeito a diligências em andamento que possam ser prejudicadas (...) Ante o exposto, julgo parcialmente procedente o pedido apenas para garantir o direito de o reclamante a ter acesso aos dados probatórios produzidos na renovação da interceptação telefônica e na inclusão de novo numeral, desde que já documentados e que não digam respeito a diligências em andamento que possam ser prejudicadas, o que deverá ser especificamente motivado pela autoridade, nos termos do aludido enunciado sumular.","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"[ Rcl 61.946 , rel. min. Gilmar Mendes , dec. monocrática, j. 10-10-2023, DJE s/n de 11-10-2023.]","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"Busca-se, nesta sede processual, seja julgada procedente a presente reclamação, para 'garantir-se o acesso a todas as gravações em mídias produzidas a partir das interceptações telefônicas captadas no curso do inquérito, de maneira descriptografada e com a entrega de todas as senhas, de molde a garantir o respeito à Súmula Vinculante 14 deste Tribunal'. (...) O Estatuto da Advocacia - ao dispor sobre o acesso do Advogado aos procedimentos estatais, inclusive àqueles que tramitem em regime de sigilo (hipótese em que se lhe exigirá a exibição do pertinente instrumento de mandato) - assegura-lhe, como típica prerrogativa de ordem profissional, o direito de examinar os autos, sempre em benefício de seu constituinte, e em ordem a viabilizar, quanto a este, o exercício do direito de conhecer os dados probatórios já formalmente produzidos no âmbito da investigação penal, para que se possibilite a prática de direitos básicos de que também é titular aquele contra quem foi instaurada, pelo Poder Público, determinada persecução criminal. (...) julgo parcialmente procedente esta reclamação, em ordem a garantir ao ora reclamante, por intermédio de seus Advogados, o direito de acesso ¿a todos as gravações em mídias produzidas a partir das interceptações telefônicas captadas no curso do inquérito, de maneira descriptografada e com a entrega de todas as senhas' (...).","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"[ Rcl 37.848 , rel. min. Celso de Mello , dec. monocrática, j. 8-10-2020, DJE 247 de 13-10-2020.]","deleted":false}],"heading":false},{"page":65,"runs":[{"text":"Acesso a informações sob o regime de sigilo da lei das organizações criminosas pela defesa","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"Reclamação. 2. Direito Penal. 3. Delação premiada. “Operação Alba Branca”. Suposta violação à Súmula Vinculante 14. Existente. TJ/SP negou acesso à defesa ao depoimento do colaborador (...), nos termos da Lei 12.850/2013. Ocorre que o art. 7º, § 2º, do mesmo diploma legal consagra o “amplo acesso aos elementos de prova que digam respeito ao exercício do direito de defesa”, ressalvados os referentes a diligências em andamento. É ônus da defesa requerer o acesso ao juiz que supervisiona as investigações. O acesso deve ser garantido caso estejam presentes dois requisitos. Um, positivo: o ato de colaboração deve apontar a responsabilidade criminal do requerente (Inq 3.983, rel. min. Teori Zavascki, Tribunal Pleno, julgado em 3-3-2016). Outro, negativo: o ato de colaboração não deve referir-se a diligência em andamento. A defesa do reclamante postulou ao relator do processo o acesso aos atos de colaboração do investigado. 4. Direito de defesa violado. 5. Reclamação julgada procedente, confirmando a liminar deferida.","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"[ Rcl 24.116 , rel. min. Gilmar Mendes , 2ª T, j. 13-12-2016, DJE 28 de 13-2-2017.]","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"O conteúdo dos depoimentos prestados em regime de colaboração premiada está sujeito a regime de sigilo, nos termos da Lei 12.850/2013 (...). 2. O sigilo perdura, em princípio, enquanto não “(...) recebida a denúncia” (art. 7º, § 3º) e especialmente no período anterior à formal instauração de inquérito. Entretanto, instaurado formalmente o inquérito propriamente dito, o acordo de colaboração e os correspondentes depoimentos permanecem sob sigilo, mas com a ressalva do art. 7º, § 2º, da Lei 12.850/2013 (...). 3. Assegurado o acesso do investigado aos elementos de prova carreados na fase de inquérito, o regime de sigilo consagrado na Lei 12.850/2013 guarda perfeita compatibilidade com a Súmula Vinculante 14, que garante ao defensor legalmente constituído (...).","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"[ Pet 6.164 AgR , rel. min. Teori Zavascki , 2ª T, j. 6-9-2016, DJE 201 de 21-9-2016.]","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"A postulação em causa, que tem suporte jurídico na Súmula Vinculante 14/STF, mostra-se acolhível, pois, mesmo tratando-se de procedimento em regime de sigilo, instaurado com apoio em depoimento prestado por agente colaborador na forma da Lei 12.850/2013, revela-se plenamente legítima a pretensão de acesso aos autos daquele cuja suposta participação em alegada prática delituosa constitui objeto da delação manifestada ao Ministério Público e/ou à Polícia Judiciária, cabendo ao Poder Judiciário garantir-lhe a possibilidade de conhecimento das peças (inclusive das declarações do agente colaborador) a ele referentes. Ao assim decidir, garantindo ao delatado, por intermédio de seu advogado, o direito ao pleno conhecimento dos dados informativos já formalmente incorporados aos autos, faço-o com apoio em precedentes desta Corte (...). O sistema normativo brasileiro assegura ao advogado regularmente constituído pelo indiciado (ou pelo réu) o direito de pleno acesso aos autos de persecução penal, mesmo que sujeita, em juízo ou fora dele, a regime de sigilo (necessariamente excepcional), limitando-se, no entanto, tal prerrogativa jurídica às provas já produzidas e formalmente incorporadas ao procedimento investigatório, excluídas, consequentemente, as informações e providências investigatórias ainda em curso de execução e, por isso mesmo, não documentadas no próprio inquérito ou processo judicial.","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"[ Pet 5.700 , rel. min. Celso de Mello , dec. monocrática, j. 22-9-2015, DJE 190 de 24-9-2015.]","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"Acesso a informações sob o regime de sigilo da lei das organizações criminosas por terceiros interessados","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"Enquanto não instaurado formalmente o inquérito propriamente dito acerca dos fatos declarados, o acordo de colaboração e os correspondentes depoimentos estão sujeitos a estrito regime de sigilo. Instaurado o inquérito, “o acesso aos autos será restrito ao juiz, ao Ministério Público e ao delegado de polícia, como forma de garantir o êxito das investigações, assegurando-se ao defensor, no interesse do representado, amplo acesso aos elementos de prova que digam respeito ao exercício do direito de defesa, devidamente precedido de autorização judicial, ressalvados os referentes às diligências em andamento” (art. 7º, § 2º). Assegurado, como assegura, o acesso do investigado aos elementos de prova carreados na fase de inquérito, o regime de sigilo consagrado na Lei 12.850/2013 guarda perfeita compatibilidade com a Súmula Vinculante 14.","deleted":false}],"heading":false},{"page":66,"runs":[{"text":"[ Rcl 22.009 AgR , rel. min. Teori Zavascki , 2ª T, j. 16-2-2016, DJE 95 de 12-5-2016.]","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"(...) a imposição legal de sigilo ao procedimento penal em que celebrado acordo de colaboração premiada não tolhe o direito do investigado (e de seu Advogado) de acesso aos elementos de informação constantes dos autos, e nestes já formalmente documentados, em face do princípio da comunhão da prova. Esse entendimento, como ninguém o ignora, tem o beneplácito do magistério jurisprudencial desta Suprema Corte, achando-se consagrado, inclusive, na Súmula Vinculante 14/STF (...). É que a prova penal, uma vez regularmente introduzida no procedimento persecutório, não pertence a ninguém, mas integra os autos do respectivo inquérito ou processo, constituindo, desse modo, acervo plenamente acessível a todos quantos sofram, em referido procedimento sigiloso, atos de persecução penal por parte do Estado.","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"[ HC 127.483 , rel. min. Dias Toffoli , voto do min. Celso de Mello , P, j. 27-8-2015, DJE 21 de 4-2-2016.]","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"Acesso a relatórios de inteligência financeira com informação de terceiros","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"Inexiste ofensa à Súmula Vinculante 14 quando indeferido acesso a relatórios de inteligência financeira, com a finalidade de proteger o sigilo de informações de terceiros.","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"[Rcl 75.855 AgR , rel. min. Nunes Marques , 2ª T, j. 27-10-2025, DJE s/n 6-11-2025.]","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"Acesso aos autos de procedimento investigatório que envolve detentores de cargos ou funções públicas","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"(...) o fundamento principal para negativa de acesso aos documentos pelas defensoras do autor seria o de que alguns investigados são detentores de cargos e funções públicas, e que a investigação poderia ficar prejudicada por eventuais influências sobre testemunhas, investigados ou outras pessoas que possam, de alguma forma, auxiliar na produção de provas. (...). Tais fundamentos, isoladamente considerados, não justificam a negativa de acesso aos autos pelas advogadas do autor ao que já foi documento nos autos, especialmente sobre sua pessoa. A autoridade policial, obviamente, deve manter sigilo ao que julgar pertinente para não atrapalhar quaisquer diligências que estejam em curso quanto aos outros investigados, porém a citação de mero envolvimento de pessoas com funções ou cargos públicos, de forma abstrata e genérica, não é suficiente para dificultar o acesso ao que já documentado nos autos, sob pena de prejudicar o contraditório e a ampla defesa do autor. (...) na ausência de motivo concreto para a negativa de acesso aos autos do inquérito policial pelas defensoras do autor, é caso de se reconhecer violação à Súmula Vinculante 14.","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"[ Rcl 45.950 AgR , rel. min. Roberto Barroso , dec. monocrática, j. 27-4-2021, DJE 80 de 29-4-2021.]","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"Acesso aos autos de procedimento investigatório sigiloso por pessoa não investigada ou indiciada","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"1. A inexistência de argumentação apta a infirmar o julgamento monocrático conduz à manutenção da decisão recorrida. 2. Não há aderência estrita entre a realidade fática dos autos e a Súmula Vinculante 14, pois, no caso concreto, a autoridade coatora informa que o reclamante, até aquele momento, não figura como investigado no procedimento investigatório. 3. Agravo regimental desprovido.","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"[ Rcl 62.463 AgR , rel. min. Edson Fachin , 2ª T, j. 21-2-2024, DJE s/n de 1-3-2024.]","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"Acesso de terceiro delatado a acordo de colaboração premiada","deleted":false}],"heading":false},{"page":67,"runs":[{"text":"1. O acordo de colaboração premiada é meio de obtenção de prova e a ele a defesa deve ter acesso, nos termos da Súmula Vinculante 14, mediante observação de dois requisitos: um positivo - o ato de colaboração deve apontar a responsabilidade criminal do recorrente; e um negativo - o ato de colaboração não deve referir-se à diligência em andamento. 2. Ao delatado não deve ser fornecido acesso integral a todos os elementos do acordo de colaboração premiada, mas aos que lhe digam respeito, a fim de que possa exercer plenamente o direito de defesa. Se há declarações de colaboradores que mencionam e incriminam o delatado, o Juízo de origem deve autorizar o acesso aos termos pertinentes, salvo se, motivadamente, apontar que hás diligências em curso que possam ser prejudicadas pela divulgação. (...) 4. Pelo conhecimento parcial do agravo regimental e, na extensão em que conhecido, pelo provimento, para que o delatado tenha acesso às declarações prestadas por colaboradores que o incriminem, já documentadas e que não se refiram a","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"diligências em andamento que possam ser prejudicadas pela divulgação, nos termos da SV 14 do STF.","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"[ Pet 7.356 AgR , rel. min. Edson Fachin , red. p/ o ac. min. Gilmar Mendes , 2ª T, j. 5-5-2023, DJE s/n de 28-7-2023.]","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"A autoridade reclamada, ao negar acesso ao conteúdo e extração de cópia dos autos em que firmado acordo de colaboração premiada, o fez ante a premissa de que \"a colaboração não configura prova ou meios de obtenção de provas, de modo que sua publicidade, nesse momento, em que pese os argumentos expedidos pelo peticionário, pode, deveras, impedir ou dificultar as investigações\". (...) o reclamante não postula a invalidação dos termos de colaboração premiada, tão somente busca acesso a eles, em consonância com o exercício do direito de defesa e com o teor do enunciado vinculante evocado. (...) extrai-se do art. 7º, § 2º, da Lei n. 12.850/2013 interpretação no sentido de não ser oponível ao delatado o sigilo do acordo de colaboração, sob pena de comprometer-se a ampla defesa. (...). Nesse caso, cumprirá ao Juízo demonstrar que o acesso se encontra inviabilizado a fim de se evitar o comprometimento de diligências em curso, fundamentando a decisão, o que não foi observado pela autoridade reclamada. (...) não se pode olvidar da evidente carga acusatória das declarações de um delator, assim como não se ignora que, embora não seja considerada prova de maneira isolada, a delação contribui para a formação de conjunto probatório a ser valorado e considerado pelo julgador (reclamação n. 42.785, ministro Gilmar Mendes, DJe de 2 de outubro de 2020). (...). Em suma: a autoridade reclamada, ao negar ao reclamante acesso aos autos em questão, deixou de observar o teor do enunciado vinculante n. 14 da Súmula.","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"[ Rcl 48.362 , rel. min. Nunes Marques , dec. monocrática, j. 6/8/2021, DJE 162 de 16/8/2021.]","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"Contraditório diferido e inquérito policial","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"O inquérito não possui contraditório, mas as medidas invasivas deferidas judicialmente devem se submeter a esse princípio, e a sua subtração acarreta nulidade. Obviamente não é possível falar-se em contraditório absoluto quando se trata de medidas invasivas e redutoras da privacidade. Ao investigado não é dado conhecer previamente - sequer de forma concomitante - os fundamentos da medida que lhe restringe a privacidade. Intimar o investigado da decisão de quebra de sigilo telefônico tornaria inócua a decisão. Contudo, isso não significa a ineficácia do princípio do contraditório. Com efeito, cessada a medida, e reunidas as provas colhidas por esse meio, o investigado deve ter acesso ao que foi produzido, nos termos da Súmula Vinculante 14. Os fundamentos da decisão que deferiu a escuta telefônica, além das decisões posteriores que mantiveram o monitoramento, devem estar acessíveis à parte investigada no momento de análise da denúncia e não podem ser subtraídas da Corte, que se vê tolhida na sua função de apreciar a existência de justa causa da ação penal. Trata-se de um contraditório diferido, que permite ao cidadão exercer um controle sobre as invasões de privacidade operadas pelo Estado.","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"[ Inq 2.266 , voto do rel. min. Gilmar Mendes , P, j. 26-5-2011, DJE 52 de 13-3-2012.]","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"Direito de o defensor acessar as provas produzidas nos autos não contempla nova produção de provas","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"Ressalto que o enfocado verbete sumular nº 14 não se presta, a rigor, a solucionar o ônus probatório, ou o direito à produção de provas não documentadas nos autos, e, sim, a garantir que documentos efetivamente produzidos nos mesmos autos a que responde a parte não tenham o seu acesso por ela indevidamente sonegado. Está fora da abrangência do enunciado vinculante tudo o que respeita à produção de prova propriamente, como o material pretendido pelos agravantes, pois não se enquadra na compreensão de acesso ao quanto já produzido e oposto à parte nos autos para que dele possa se defender em plenitude.","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"[ Rcl 75.093 , rel. min. André Mendonça , 2ª T, j. 7-4-2025, DJE s/n 15-4-2025.]","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"Direito de acesso pela defesa à provas já concluídas que constem de outro processo","deleted":false}],"heading":false},{"page":68,"runs":[{"text":"Apesar das informações, se foram tiradas fotografias ou realizadas filmagens durante a busca e apreensão, tais provas devem ser franqueadas à Defesa. O fato de integrarem um outro processo e que estaria com o Ministério Público não exclui esse direito. Não foi ainda esclarecido pela autoridade coatora se haveria algum","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"prejuízo à investigação decorrente de eventual acesso da Defesa a tal prova. Não havendo esclarecimento, mesmo tendo sido ele oportunizado, é de se presumir que não existe prejuízo. Por outro lado, basta a entrega à Defesa de cópia das fotografias e filmagens realizadas quando da busca e apreensão, não sendo necessário franquear acesso a todo o referido processo que correria perante o Ministério Público e que não integra o objeto desta reclamação. Negar à Defesa o acesso a supostas fotografias ou filmagens realizadas durante busca e apreensão já encerrada representa, ainda que não fosse essa a intenção da autoridade reclamada, violação à Súmula Vinculante 14.","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"[ Rcl 13.156 , rel. min. Rosa Weber , dec. monocrática, j. 1º-2-2012, DJE 42 de 29-2-2012.]","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"Ilegitimidade da pessoa jurídica para invocar a Súmula Vinculante 14 em defesa de direitos de investigados","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"No presente caso, a reclamação constitucional é ajuizada por pessoa jurídica que alega possuir interesse jurídico no acesso aos autos de Inquérito destinado a apurar a suposta prática de crimes (...). Ocorre que, exatamente por ser pessoa jurídica, “não poderá figurar como réu em eventual ação penal e tampouco figura na qualidade de investigado”. Assim, “caso a decisão esteja ainda por ferir direitos de pessoas físicas, essas sim investigadas, são elas próprias que devem ajuizar a reclamação constitucional para cumprimento da Súmula 14, jamais pessoa jurídica da qual sejam sócios ou administradores” (Rcl 10812, Rel. Min. GILMAR MENDES, DJe de 2/12/2010).","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"[ Rcl 78.854 , rel. min. Alexandre de Moraes , dec. monocrática, j. 12-5-2025, DJE s/n 13-5-2025.]","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"Impossibilidade de acesso ao acervo produzido em procedimento sigiloso pelo defensor da vítima","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"A teleologia do paradigma traduz a necessidade de que o acervo produzido em procedimento sigiloso, ressalvadas as diligências em curso, seja acessível por aqueles que, efetiva ou potencialmente, sofrerão os correspondentes atos de persecução penal, ou seja, os investigados/réus. No caso em análise o reclamante é defensor da vítima, e não do investigado. De toda sorte, ainda que alguma razão jurídica houvesse nesse ponto, friso que a negativa de acesso aos autos foi devidamente justificada pela autoridade reclamada, sobretudo em razão de haver diligências em curso. (...) Ante o exposto, nego provimento ao agravo regimental (...)","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"[ Rcl 66.860 AgR , rel. min. André Mendonça , 2ª T, j. 19-11-2024, DJE s/n 12-12-2024.]","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"Impossibilidade de acesso aos depoimentos na condição de testemunha","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"Nesse contexto, resta clara a ausência de aderência estrita entre o ato reclamado e o enunciado de Súmula Vinculante n. 14, que se alega violado, tendo em vista que não há, na decisão impugnada, qualquer negativa de aplicação às balizas interpretativas conferidas, por esta Corte, ao enunciado sumular invocado. Com efeito, a oitiva do representado na condição de testemunha não se enquadra na jurisprudência desta Suprema Corte quanto ao espectro de incidência da Súmula Vinculante n. 14. (...) Ex positis, NEGO SEGUIMENTO à presente Reclamação (...)","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"[ Rcl 63.445 , rel. min. Luiz Fux , dec. monocrática, j. 2-2-2024, DJE s/n de 5-2-2024.]","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"Impugnação de termo de colaboração premiada por terceiros interessados","deleted":false}],"heading":false},{"page":69,"runs":[{"text":"1. O Termo de Colaboração Premiada revela natureza de negócio jurídico processual, consistindo meio de obtenção de prova cujo sigilo perdura até que sobrevenha decisão de recebimento da denúncia (art. 7º, §1º e §3º, da Lei 12.850/2013). 2. O Termo do Acordo de Colaboração, celebrado entre Ministério Público e Colaborador, não é alcançado pela regra de que ao defensor deve ser garantido o acesso aos elementos de prova que digam respeito ao exercício da ampla defesa. 3. O Termo de Colaboração Premiada, porquanto negócio jurídico processual personalíssimo, não admite impugnação de terceiros, conforme jurisprudência do Supremo Tribunal Federal sedimentada a partir do HC 127.483/PR, Tribunal Pleno, Rel. Min. Dias Toffoli, DJe de 04/02/2016.","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"[ Inq 4.619 AgR , rel. min. Luiz Fux , 1ª T, j. 10-9-2018, DJE 202 de 25-9-2018.]","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"1. O Plenário do Supremo Tribunal Federal já firmou entendimento, em mais de uma ocasião (HC 127483 e PET 7074-AgR), no sentido de que o delatado não possui legitimidade para impugnar o acordo de colaboração premiada. É que seu interesse se restringe aos elementos de prova obtidos a partir dos acordos de colaboração premiada, e eventual ação penal seria o foro próprio para esta impugnação. A mudança jurisprudencial ocasional gera insegurança jurídica e reduz a confiança na jurisdição. 2. A negativa de acesso aos acordos de colaboração premiada pelo investigado delatado não afronta o enunciado de súmula vinculante 14, na medida em que não é o acordo em si que repercute na esfera jurídica do investigado, mas os elementos de prova produzidos a partir dele. E tais elementos estão nos autos, em especial, o depoimento dos colaboradores e os documentos por eles fornecidos. Após o recebimento da denúncia, se for o caso de instaurar a ação penal, o acordo será público e o investigado terá acesso a ele.","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"[ Inq 4.405 AgR , rel. min. Roberto Barroso , 1ª T, j. 27-2-2018, DJE 64 de 5-4-2018.]","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"Interpretação restritiva da Súmula Vinculante 14 e a necessidade de demonstração do efetivo prejuízo à defesa","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"A jurisprudência do Supremo Tribunal Federal tem interpretado a Súmula Vinculante 14 de forma restritiva, exigindo a demonstração de que o acesso aos elementos de prova já documentados foi efetivamente obstado, e que esses elementos sejam imprescindíveis para o exercício do direito de defesa. Não basta a mera alegação de que o acesso foi limitado; é necessário comprovar que a defesa foi impedida de examinar provas relevantes para a sua tese.","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"[ Rcl 77.473 , rel. min. Gilmar Mendes , dec. monocrática, j. 29-3-2025, DJE s/n 1º-4-2025.]","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"Inviabilidade do acesso pela defesa a procedimentos investigatórios não concluídos","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"Reconheço que a incidência da garantia à ampla defesa (art. 5º, LV) no inquérito policial contempla, de forma inequívoca, o direito constitucional assegurado ao defensor de acessar os autos e os elementos informativos documentados no processo. Trata-se de direito garantido pela legislação federal (art. 7º da Lei n. 8.906/1994 - Estatuto da Ordem dos Advogados do Brasil) e notoriamente reconhecido pela jurisprudência deste Supremo Tribunal Federal (Súmula Vinculante n. 14). (...) Na hipótese dos autos, entretanto, concordo com os fundamentos expendidos pelo eminente Ministro Dias Toffoli quando decretou o sigilo da mídia acautelada, estabeleceu condições para sua visualização e ordenou a preservação das gravações até a finalização da diligência pela autoridade policial. (...) A circunstância de as diligências não terem sido finalizadas pode configurar óbice à plenitude de acesso a certos elementos de informação “pendentes de arrecadação, análise ou documentação”, como evidenciou o Relator.","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"[ INQ 4.940 AgR-Segundo , rel. min. Dias Toffoli , P, j. 26-2-2024, DJE s/n de 30-4-2024.]","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"(...) verifico que, in casu , a irresignação do reclamante não merece acolhida. Isso porque o entendimento adotado no ato reclamado não constitui ato que ofendam a tese firmada no enunciado 14 da Súmula Vinculante do Supremo Tribunal Federal (...). Deveras, o direito de acesso aos dados de investigação não é absoluto, porquanto o legislador ordinário trouxe temperamentos a essa prerrogativa, consoante se infere da exegese do artigo 7º, §§ 10 e 11, da lei 8.906/1994 - Estatuto da Advocacia e a Ordem dos Advogados do Brasil - OAB, com a redação conferida pela Lei 13.245/2016, (...). Nesse contexto, cabe referir que o espectro de incidência do Enunciado 14 da Súmula vinculante do Supremo Tribunal Federal não abrange diligências ainda em andamento e elementos ainda não documentados, mormente se considerados os dispositivos legais supramencionados, além de se fazer necessária a apresentação de procuração nas hipóteses de autos sujeitos a sigilo. (...) verifico que sequer se negou à defesa o direito de acesso a autos de investigação, razão pela qual não merece prosperar o presente intento reclamatório","deleted":false}],"heading":false},{"page":70,"runs":[{"text":"[ Rcl 30.957 , rel. min. Luiz Fux , dec. monocrática, j. 10-8-2018, DJE 164 de 14-8-2018.]","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"(...) o paradigma tido como violado confere ao defensor do investigado amplo acesso aos elementos já documentados nos autos, mas é enfático ao ressalvar as diligências ainda em andamento. Com efeito, a presente Reclamação é improcedente, pois não se ajusta ao contexto do parâmetro de controle acima transcrito. Verifico, à luz do ato impugnado, que o pleito foi indeferido porque havia diligências em andamento e o eventual acesso a essas informações poderia causar prejuízo às investigações. (...) Dessa forma, a pendência na conclusão de diligências investigatórias já deferidas pela autoridade reclamada é argumento legítimo para o indeferimento do acesso irrestrito pleiteado pelo reclamante. (...) Portanto, as diligências ainda em andamento não estão contempladas pelo teor da Súmula Vinculante 14 (Rcl 28.661/SC, Rel. Min. Alexandre de Moraes, DJe de 19/10/2017).","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"[ Rcl 29.958 , rel. min. Alexandre de Moraes , dec. monocrática, j. 9-8-2018, DJE 164 de 14-8-2018.]","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"1. O direito do investigado de ter acesso aos autos não compreende diligências em andamento, na exata dicção da Súmula Vinculante 14 do Supremo Tribunal Federal. (...) 6. O Supremo Tribunal Federal assentou a essencialidade do acesso por parte do investigado aos elementos probatórios formalmente documentados no inquérito - ou procedimento investigativo similar - para o exercício do direito de defesa, ainda que o feito seja classificado como sigiloso. Precedentes. 7. Nesse contexto, independentemente das circunstâncias expostas pela autoridade reclamada, é legitimo o direito de o agravante ter acesso aos elementos de prova devidamente documentados nos autos do procedimento em que é investigado e que lhe digam respeito, ressalvadas apenas e tão somente as diligências em curso.","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"[ Rcl 28.903 AgR , rel. min. Edson Fachin , red. p/ o ac. min. Dias Toffoli , 2ª T, j. 23-3-2018, DJE 123 de 21-6-2018.]","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"Autos de inquérito policial que estavam circunstancialmente indisponíveis em razão da pendência de realização de diligência sigilosa. Além disso, os autos encontravam-se fisicamente em poder da autoridade policial, providência que, temporariamente, impedia o imediato acesso da defesa. Razões atinentes à gestão processual que evidenciam ausência de demonstração inequívoca de atos violadores da Súmula Vinculante 14.","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"[ Rcl 25.012 AgR , rel. min. Edson Fachin , 2ª T, j. 14-3-2017, DJE de 27-3-2017.]","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"Segundo se extrai da leitura da Súmula Vinculante 14, o defensor pode ter acesso às diligências já documentadas no inquérito policial. No entanto, a diligência à qual o reclamante pleiteia acesso ainda está em andamento e, em virtude disto, a súmula vinculante não é aplicável ao presente caso. Rcl 10.110, rel. min. Ricardo Lewandowski. 6. Assim, independentemente da existência ou não da contradição suscitada pela defesa, o acesso às diligências que ainda se encontram em andamento não é contemplado pelo teor da Súmula Vinculante 14.","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"[ Rcl 22.062 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 15-3-2016, DJE 103 de 20-5-2016.]","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"Agravo regimental em reclamação. 2. Súmula Vinculante 14. Violação não configurada. 3. Os autos não se encontram em Juízo. Remessa regular ao Ministério Público. 4. Inquérito originado das investigações referentes à operação “Dedo de Deus”. Existência de diversas providências requeridas pelo Parquet que ainda não foram implementadas ou que não foram respondidas pelos órgãos e que perderão eficácia se tornadas de conhecimento público. 5. Ausência de argumentos capazes de infirmar a decisão agravada. 6. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"[ Rcl 16.436 AgR , rel. min. Gilmar Mendes , P, j. 28-5-2014, DJE 167 de 29-8-2014.]","deleted":false}],"heading":false},{"page":71,"runs":[{"text":"A decisão ora questionada está em perfeita consonância com o texto da Súmula Vinculante 14 desta Suprema Corte, que, como visto, autorizou o acesso dos advogados aos autos do inquérito, apenas resguardando as diligências ainda não concluídas. III - Acesso que possibilitou a apresentação de defesa prévia com base nos elementos de prova até então encartados, sendo certo que aquele ato não é a única e última oportunidade para expor as teses defensivas. Os advogados poderão, no decorrer da instrução criminal, acessar todo o","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"acervo probatório, na medida em que as diligências forem concluídas.","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"[ Rcl 10.110 , rel. min. Ricardo Lewandowski , P, j. 20-10-2011, DJE 212 de 8-11-2011.]","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"Não afronta a Súmula Vinculante 14 a negativa de desarquivamento de autos físicos quando assegurado acesso integral em meio eletrônico e inexistente indicação concreta de falhas","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"(...) Como se vê, o caso dos autos efetivamente desborda das balizas estabelecidas no paradigma, que não especifica o meio pelo qual o acesso deve ser franqueado ao advogado. No caso, a autoridade reclamada assentou que a defesa tem acesso à íntegra dos autos em meio eletrônico. Além disso, consignou que o advogado não relatou ao Juízo de origem qualquer apontamento específico sobre peças faltantes, logo o pedido genérico de acesso aos autos físicos, integralmente digitalizados há mais de seis anos, efetivamente não justificaria o seu desarquivamento. Nesse contexto, não há aderência estrita da situação relatada ao enunciado vinculante.”","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"[ Rcl 60.105 , rel. min. Edson Fachin , dec. monocrática, j. 2-6-2023, DJE s/n de 6-6-2023]","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"Possibilidade de acesso aos depoimentos das testemunhas antes do interrogatório","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"No caso, conforme despacho da autoridade policial, já foram tomados os depoimentos de testemunhas, mas os respectivos termos não foram juntados aos autos. A autoridade policial argumentou que, por estratégia de investigação, o investigado deve ser ouvido antes de tomar conhecimento do depoimento das testemunhas. Acrescentou que o interrogatório e os depoimentos das testemunhas fazem parte de uma única diligência policial. Dessa forma, não haveria diligência concluída, de juntada obrigatória aos autos. O ato contraria o entendimento desta Corte representado pela Súmula Vinculante 14. O depoimento de testemunhas é uma diligência separada do interrogatório do investigado. Não há diligência única, ainda em andamento. De forma geral, a diligência em andamento que pode autorizar a negativa de acesso aos autos é apenas a colheita de provas cujo sigilo é imprescindível. O argumento da diligência em andamento não autoriza a ocultação de provas para surpreender o investigado em seu interrogatório. É direito do investigado tomar conhecimento dos depoimentos já colhidos no curso do inquérito, os quais devem ser imediatamente entranhados aos autos. Em consequência, a defesa deve ter prazo razoável para preparar-se para a diligência, na forma em que requerido.","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"[ Inq 4.244 , rel. min. Gilmar Mendes , dec. monocrática, j. 25-4-2017, DJE 87 de 26-4-2017.]","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"Possibilidade de obtenção de cópias de todos os elementos de prova já documentados, inclusive daqueles em formato audiovisual","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"Nada, absolutamente nada, respalda ocultar de envolvido - como é o caso da reclamante - dados contidos em autos de procedimento investigativo ou em processo alusivo a ação penal, pouco importando eventual sigilo do que documentado. Esse é o entendimento revelado no verbete vinculante 14 (...). Tendo em vista a expressão “acesso amplo”, deve-se facultar à defesa o conhecimento da integralidade dos elementos resultantes de diligências, documentados no procedimento investigatório, permitindo, inclusive, a obtenção de cópia das peças produzidas. O sigilo refere-se tão somente às diligências, evitando a frustração das providências impostas. Em síntese, o acesso ocorre consideradas as peças constantes dos autos, independentemente de prévia indicação do Ministério Público. 3. Defiro a liminar para que a reclamante, na condição de envolvida, tenha acesso irrestrito e imediato, por meio de procurador constituído, facultada inclusive a extração de cópia, aos elementos constantes do procedimento investigatório (...).","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"[ Rcl 31.213 MC , rel. min. Marco Aurélio , dec. monocrática, j. 20-8-2018, DJE 174 de 24-8-2018.]","deleted":false}],"heading":false},{"page":72,"runs":[{"text":"O direito ao “acesso amplo”, descrito pelo verbete mencionado, engloba a possibilidade de obtenção de cópias, por quaisquer meios, de todos os elementos de prova já documentados, inclusive mídias que contenham gravação de depoimentos em formato audiovisual. II - A simples autorização de ter vista dos autos, nas dependências do Parquet , e transcrever trechos dos depoimentos de interesse da defesa, não atende ao enunciado da Súmula Vinculante 14. III - A jurisprudência do Supremo Tribunal Federal entende ser desnecessária a degravação da audiência realizada por meio audiovisual, sendo obrigatória apenas a","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"disponibilização da cópia do que registrado nesse ato.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"[ Rcl 23.101 , rel. min. Ricardo Lewandowski , 2ª T, j. 22-11-2016, DJE 259 de 6-12-2016.]","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Proibição da retirada do processo da Secretaria","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Conforme ressaltado na manifestação da Procuradoria-Geral da República, as informações prestadas revelam haver sido viabilizado o acesso ao processo, apenas se obstaculizando fosse retirado da Secretaria do Juízo, a fim de evitar prejuízo aos demais advogados e tumulto processual. Inexiste, nessa providência, inobservância ao Verbete Vinculante 14 da Súmula do Supremo.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"[ Rcl 13.215 , voto do rel. min. Marco Aurélio , 1ª T, j. 23-4-2013, DJE 89 de 14-5-2013.]","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Súmula Vinculante 14 e inaplicabilidade para procedimentos de natureza cível ou administrativa","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Por fim, melhor sorte não assiste ao reclamante no tocante à alegada violação ao conteúdo da Súmula Vinculante nº 14. Isso porque, o enunciado sumular, embora de imensa importância, tem sua origem e seu campo primário de aplicação nos procedimentos de investigação criminal. A sua invocação para tutelar o acesso a provas em processos de natureza cível e administrativa tem sido rechaçada pela jurisprudência desta Corte na via da reclamação. Assim, embora as alegações do reclamante sobre cerceamento de defesa (impossibilidade de atuação de assistente técnico, prazo exíguo para análise de perícia) sejam de extrema gravidade e possam, em tese, configurar violação direta aos princípios constitucionais do contraditório e da ampla defesa (art. 5º, inc. LV, CRFB), o instrumento processual da reclamação, por ofensa à SV nº 14, mostra-se inadequado para sanar tal violação em sede de processo administrativo, conforme entendimento restritivo do próprio STF.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"[ Rcl 90.627 , rel. min. André Mendonça , dec. monocrática, j. 20-2-2026, DJE s/n 23-2-2026.]","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"O Verbete 14 da Súmula Vinculante do Supremo não alcança sindicância administrativa objetivando elucidar fatos sob o ângulo do cometimento de infração administrativa.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"[ Rcl 10.771 AgR , rel. min. Marco Aurélio , 1ª T, j. 4-2-2014, DJE 33 de 18-2-2014.]","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Como já demonstrado, a Súmula Vinculante 14 é aplicada apenas a procedimentos administrativos de natureza penal, sendo incorreta sua observância naqueles de natureza cível.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"[ Rcl 8.458 AgR , voto do rel. min. Gilmar Mendes , P, j. 26-6-2013, DJE 184 de 19-9-2013.]","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":73,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 184, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Data de publicação do enunciado: DJE de 9-2-2009.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":73,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"15","number":"15","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":74,"endPage":75,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1233","paragraphs":[{"page":74,"runs":[{"text":"O cálculo de gratificações e outras vantagens do servidor público não incide sobre o abono utilizado para se atingir o salário mínimo.","deleted":false}]}],"notes":[{"page":74,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":74,"runs":[{"text":"Ambas as Turmas entendem que a incidência de gratificações e outras vantagens sobre o resultado da soma do vencimento com o abono - este utilizado para se atingir o mínimo legal, que é o salário mínimo - contraria o art. 7º, IV, da CF/1988, por importar vinculação nele vedada. Isso porque, a cada aumento do salário mínimo e, por consequência, do abono, aumentar-se-iam também as gratificações e vantagens dos servidores.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"[ RE 572.921 QO-RG , voto do rel. min. Ricardo Lewandowski, P, j. 13-11-2008, DJE 25 de 6-2-2009, Tema 141.]","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":74,"runs":[{"text":"● O cálculo de gratificações e outras vantagens do servidor público não incide sobre o abono utilizado para se atingir o salário mínimo.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"[Tese definida no RE 572.921 QO-RG , rel. min. Ricardo Lewandowski, P, j. 13-11-2008, DJE 25 de 6-2-2009, Tema 141.]","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":74,"runs":[{"text":"● Total de remuneração e vedação constitucional à percepção inferior ao salário mínimo","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"É pacífica a jurisprudência desta Corte de que a garantia de percepção de salário mínimo conferida ao servidor por força dos arts. 7º, IV, e 39, § 3º, da CF/1988 corresponde à sua remuneração total e não apenas ao vencimento básico, que pode ser inferior ao mínimo, e, também, que sobre o abono pago para atingir o salário mínimo não devem incidir as gratificações e demais vantagens pecuniárias, sob pena de ofensa ao art. 7º, IV, da CF/1988.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"[ RE 499.937 AgR , rel. min. Dias Toffoli, 1ª T, j. 25-10-2011, DJE 228 de 1º-12-2011.]","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"De acordo com a jurisprudência desta Corte, a incidência de gratificações e outras vantagens sobre o resultado da soma do vencimento com o abono contraria o art. 7º, IV, da CF/1988, porquanto, a cada aumento do salário mínimo e, por consequência, do abono, aumentar-se-iam, indiretamente, também as gratificações e vantagens dos servidores. Consubstanciaria, dessa forma, uma vinculação indireta ao salário mínimo, vinculação, essa, vedada pela CF/1988 e objeto de reiteradas decisões desta Casa.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"[ RE 518.933 AgR , rel. min. Ricardo Lewandowski, dec. monocrática, j. 30-9-2009, DJE 197 de 20-10-2009.]","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":74,"runs":[{"text":"● Vide Súmula Vinculante 4 e Súmula Vinculante 16.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 141, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"Data de publicação do enunciado: DJE de 1º-7-2009.","deleted":false}],"heading":false},{"page":74,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":75,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"16","number":"16","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":76,"endPage":78,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1237","paragraphs":[{"page":76,"runs":[{"text":"Os artigos 7º, IV, e 39, § 3º (redação da EC 19/98), da Constituição, referem-se ao total da remuneração percebida pelo servidor público.","deleted":false}]}],"notes":[{"page":76,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":76,"runs":[{"text":"Ambas as Turmas da Corte, seguindo a orientação firmada pelo Plenário, corroboraram o entendimento de que a remuneração total do servidor, e não o seu salário-base, é que não pode ser inferior ao salário mínimo.","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"[ RE 582.019 QO-RG , voto do rel. min. Ricardo Lewandowski, P, j. 13-11-2008, DJE 30 de 13-2-2009, Tema 142.]","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":76,"runs":[{"text":"● É defeso o pagamento de remuneração em valor inferior ao salário mínimo ao servidor público, ainda que labore em jornada reduzida de trabalho.","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"[Tese definida no RE 964.659 RG , rel. min. Dias Toffoli, j. 8-8-2022, P, DJE de 1º-9-2022, Tema 900]","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"● Os arts. 7º, IV, e 39, § 3º (redação da EC 19/1998), da Constituição referem-se ao total da remuneração percebida pelo servidor público.","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"[Tese definida no RE 582.019 QO-RG , rel. min. Ricardo Lewandowski, P, j. 13-11-2008, DJE 30 de 13-2-2009, Tema 142.]","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"Ação direta de inconstitucionalidade. Art. 95, I, da Constituição do Estado de Goiás e art. 56 da Lei estadual 11.416/1991. 2. Servidor público. Garantia de vencimento básico não inferior ao salário mínimo. Impossibilidade. Orientação do STF no sentido de que a garantia do salário mínimo, prevista no art. 7º, IV, c/c art. 39, § 3º, da Constituição Federal, é alusiva ao total da remuneração do servidor, incorrendo em inconstitucionalidade material o dispositivo que vincula tal garantia ao vencimento básico. 3. Militar. Soldo. Garantia de valor não inferior ao salário mínimo. Impossibilidade. A jurisprudência desta Corte assentou entendimento no sentido de que não se estende aos militares a garantia de remuneração não inferior ao salário mínimo vigente. 4. Ação direta de inconstitucionalidade julgada procedente.","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"[ ADI 751 , rel. min. Gilmar Mendes, P, j. 9-5-2019, DJE 107 de 22-5-2019.]","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":76,"runs":[{"text":"Ação rescisória e aplicação da Súmula Vinculante 16","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"CONSTITUCIONAL. ADMINISTRATIVO. AGRAVO REGIMENTAL EM AGRAVO DE INSTRUMENTO. SERVIDOR PÚBLICO. PERCEPÇÃO DE VENCIMENTO BASE NÃO INFERIOR AO SALÁRIO MÍNIMO. AÇÃO RESCISÓRIA. SÚMULA 343 DO SUPREMO TRIBUNAL FEDERAL. NÃO INCIDÊNCIA. ACÓRDÃO RECORRIDO EM DESACORDO COM A SÚMULA VINCULANTE 16. 1. É cabível ação rescisória por ofensa à literal disposição constitucional, ainda que a decisão rescindenda tenha por fundamento interpretação controvertida ou seja anterior à orientação assentada pelo Supremo Tribunal Federal (RE 328.812 ED, da relatoria do ministro Gilmar Mendes). 2. Nos termos da Súmula Vinculante 16, “os art. 7º, IV, e 39, § 3º (redação da EC 19/1998), da CF/1988 referem-se ao total da remuneração percebida pelo servidor público”. 3. Agravo regimental desprovido.","deleted":false}],"heading":false},{"page":76,"runs":[{"text":"[ AI 659.048 AgR-segundo , rel. min. Ayres Britto, 2ª T, j. 20-9-2011, DJE 216 de 14-11-2011.]","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"Adicional de penosidade e garantia do salário mínimo","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"Como se depreende dos debates, o termo “total da remuneração percebida pelo servidor público” utilizado no verbete da Súmula Vinculante foi introduzido no sentido de abranger o total remuneratório do servidor, a incluir, inclusive, verbas indenizatórias, tais como diárias. A autoridade reclamada, ressaltando a natureza salarial do adicional de penosidade, entendeu por excluí-lo do salário-base para fins do disposto no art. 7º, VII, assentando o caráter excepcional e condicional da verba. Ao proceder desse modo, o acórdão reclamado contrariou o que contido na Súmula Vinculante 16.","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"[ Rcl 31.165 , rel. min. Edson Fachin , dec. monocrática, j. 28-2-2020, DJE 43 de 3-3-2020.]","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"Impossibilidade de indexação de vencimento básico ao salário mínimo","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"(...) a jurisprudência dessa Suprema Corte é pacífica no sentido de que “a garantia do salário mínimo, prevista no art. 7º, IV, c/c art. 39, § 3º, da Constituição Federal, é alusiva ao total da remuneração do servidor, incorrendo em inconstitucionalidade material o dispositivo que vincula tal garantia ao vencimento básico” (ADI 751/GO, Rel. Min. Gilmar Mendes, Plenário, DJe de 22/5/2019). O entendimento foi afirmado na Tese 142 de repercussão geral (RE 582019 QO-RG, Rel. Min. Ricardo Lewandowski. Plenário, DJe de 13/2/2009) e está consubstanciado na Súmula Vinculante 16, de observância obrigatória não apenas pelos demais órgãos do Poder Judiciário, como também pela administração pública direta e indireta, nas esferas federal, estadual e municipal (CF/1988, art. 102-A, caput ). (...) Entendo, ainda, devidamente demonstrado o risco à economia do Estado do Rio Grande do Norte, porquanto a execução da decisão ora objurgada determina o pagamento de vencimento básico indexado ao valor do salário mínimo, resultando no pagamento de verbas de natureza alimentar, o que, somada à circunstância de ser percebida por servidor por força de ordem judicial, afasta a restituição aos cofres públicos (v.g. MS 26085/DF, Rel. Min. Cármen Lúcia, Plenário, DJe de 13/6/2008). (...) Ante o exposto, defiro o pedido para suspender a execução da decisão do Tribunal de Justiça do Rio Grande do Norte (...).","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"[ SS 5.248 , rel. min. presidente Dias Toffoli, dec. monocrática, j. 20-11-2019, DJE 257 de 26-11-2019.]","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"Impossibilidade de remuneração total inferior ao salário mínimo","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"(...) o Plenário do Supremo Tribunal Federal, ao apreciar o RE 572.921/RN e o RE 582.019/SP, ambos da relatoria do ministro Ricardo Lewandowski, reconheceu a existência da repercussão geral das matérias constitucionais versadas nestes feitos e reafirmou a jurisprudência dominante nesta Corte no sentido de que a garantia de percepção de salário mínimo conferida ao servidor por força dos arts. 7º, IV, e 39, § 3º, da CF/1988 corresponde à sua remuneração total e não apenas ao vencimento básico, que pode ser inferior ao mínimo, e, também, que sobre o abono pago para atingir o salário mínimo não devem incidir as gratificações e demais vantagens pecuniárias, sob pena de ofensa ao art. 7º, IV, da CF/1988. (...) Nesse contexto, o Supremo Tribunal Federal aprovou os enunciados das Súmulas Vinculantes 15 e 16 (...).","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"[ RE 499.937 AgR , voto do rel. min. Dias Toffoli , 1ª T, j. 25-10-2011, DJE 228 de 1º-12-2011.]","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"Servidor inativo e impossibilidade de remuneração proporcional inferior ao salário mínimo","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"Em casos semelhantes ao dos presentes autos, em que se discute a possibilidade de pagamento de vencimentos proporcionais de servidores em valor inferior ao salário mínimo, esta Corte tem se pronunciado no sentido de que os proventos proporcionais pagos a servidor aposentado não podem ter valor inferior ao salário mínimo. (...) Embora os precedentes citados tratem do pagamento de proventos de aposentadoria proporcionais ao tempo de serviço, entendo que se amoldam perfeitamente ao presente caso, pois a questão de fundo é a mesma, impossibilidade de pagamento de remuneração proporcional de servidores públicos, inativos ou não, em valor inferior ao salário mínimo.","deleted":false}],"heading":false},{"page":77,"runs":[{"text":"[ RE 547.281 , rel. min. Ellen Gracie , dec. monocrática, j. 6-4-2011, DJE 76 de 26-4-2011.]","deleted":false}],"heading":false},{"page":78,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":78,"runs":[{"text":"● Vide Súmula Vinculante 4 e Súmula Vinculante 15.","deleted":false}],"heading":false},{"page":78,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 142, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":78,"runs":[{"text":"● Tema 900 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":78,"runs":[{"text":"Data de publicação do enunciado: DJE de 1º-7-2009.","deleted":false}],"heading":false},{"page":78,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":78,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"17","number":"17","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":79,"endPage":85,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1241","paragraphs":[{"page":79,"runs":[{"text":"Durante o período previsto no parágrafo 1º do artigo 100 da Constituição, não incidem juros de mora sobre os precatórios que nele sejam pagos.","deleted":false}]}],"notes":[{"page":79,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":79,"runs":[{"text":"Efetivamente, o próprio texto constitucional determinava o prazo para pagamento do precatório, qual seja, até o final do exercício seguinte. Assim, somente no caso de seu descumprimento poder-se-ia falar em mora e, em consequência, nos juros a ela relativos, como penalidade pelo atraso no pagamento. Assim, o entendimento que se firmou no julgamento do RE 305.186/SP, Primeira Turma, sessão de 17-9-2002, rel. min. Ilmar Galvão, foi o de que “não são devidos juros moratórios no período compreendido entre a data de expedição e a data do efetivo pagamento de precatório judicial, no prazo constitucionalmente estabelecido, à vista da não caracterização, na espécie, de inadimplemento por parte do poder público”.","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"[ RE 298.616 , voto do rel. min. Gilmar Mendes , P, j. 31-10-2002, DJ de 3-10-2003.]","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"Sendo assim, não pode ser tido em mora, com maior razão, o devedor que cumprir o prazo constitucionalmente estabelecido. Esta foi a convicção manifestada pelo ministro Sepúlveda Pertence, no julgamento do RE 149.466, antes referido, quando ponderou que “juros de mora envolvem inadimplência”. Ora, se tal conclusão foi encampada pela Corte nas hipóteses em que o resgate parcelado da dívida constituía uma opção do devedor (art. 33 do ADCT), outra não pode ser a orientação quando se trata de pagamento abarcando lapso temporal imposto pelo texto permanente da Carta. Se não há inadimplência, ou mora debitoris , quando a entidade de direito público exercita a faculdade que lhe é mais favorável, não poderá haver quando utiliza a única forma de pagamento possível. Ademais, há de ponderar-se que, via de regra, a simples atualização monetária do montante pago no exercício seguinte à expedição do precatório já corrige, junto com o principal, todas as verbas acessórias, inclusive os juros lançados na conta originária. Sendo assim, a incidência contínua de juros moratórios representaria capitalização de tais juros, o que não se justificaria nem mesmo em face dos créditos de natureza alimentar.","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"[ RE 305.186 , voto do rel. min. Ilmar Galvão , 1ª T, j. 17-9-2002, DJ de 18-10-2002.]","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":79,"runs":[{"text":"● 1. Não incide a taxa SELIC, prevista no art. 3º da EC nº 113/2021, no prazo constitucional de pagamento de precatórios do § 5º do art. 100 da Constituição. 2. Durante o denominado \"período de graça\", os valores inscritos em precatório terão exclusivamente correção monetária, nos termos decididos na ADI 4.357-QO/DF e na ADI 4.425-QO/DF.","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"[Tese definida no RE 1.515.163 RG , rel. min. Luís Roberto Barroso , P, j. 11-10-2024, DJE s/n de 21-10-2024, Tema 1.335.]","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"● O enunciado da Súmula Vinculante 17 não foi afetado pela superveniência da Emenda Constitucional 62/2009, de modo que não incidem juros de mora no período de que trata o § 5º do art. 100 da Constituição. Havendo o inadimplemento pelo ente público devedor, a fluência dos juros inicia-se após o 'período de graça'.","deleted":false}],"heading":false},{"page":79,"runs":[{"text":"[Tese definida no RE 1.169.289 , P, rel. min. Marco Aurélio , red. p/ o acórdão min. Alexandre de Moraes , j. 16-06-2020, DJE 243 de 1-7-2020, Tema 1.037.]","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"● I - O art. 1º-F da Lei 9.494/1997, com a redação dada pela Lei 11.960/2009, na parte em que disciplina os juros moratórios aplicáveis a condenações da Fazenda Pública, é inconstitucional ao incidir sobre débitos oriundos de relação jurídico-tributária, aos quais devem ser aplicados os mesmos juros de mora pelos quais a Fazenda Pública remunera seu crédito tributário, em respeito ao princípio constitucional da isonomia (CRFB, art. 5º, caput ); quanto às condenações oriundas de relação jurídica não-tributária, a fixação dos juros moratórios segundo o índice de remuneração da caderneta de poupança é constitucional, permanecendo hígido, nesta extensão, o disposto no art. 1º-F da Lei 9.494/1997 com a redação dada pela Lei 11.960/2009;","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"II - O art. 1º-F da Lei 9.494/1997, com a redação dada pela Lei 11.960/2009, na parte em que disciplina a atualização monetária das condenações impostas à Fazenda Pública segundo a remuneração oficial da caderneta de poupança, revela-se inconstitucional ao impor restrição desproporcional ao direito de propriedade (CRFB, art. 5º, XXII), uma vez que não se qualifica como medida adequada a capturar a variação de preços da economia, sendo inidônea a promover os fins a que se destina.","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"[Tese definida no RE 870.947 , rel. min. Luiz Fux , P, j. 20-9-2017, DJE 262 de 20-11-2017, Tema 810.]","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"As expressões uma única vez e até o efetivo pagamento dão conta de que a intenção do legislador ordinário foi reger a atualização monetária dos débitos fazendários tanto na fase de conhecimento quanto na fase de execução. Daí por que o STF, ao julgar a ADI 4.357 e a ADI 4.425, teve de declarar a inconstitucionalidade por arrastamento do art. 1º-F da Lei 9.494/1997. Essa declaração, porém, teve alcance limitado e abarcou apenas a parte em que o texto legal estava logicamente vinculado no art. 100, § 12, da CRFB/1988, incluído pela EC 62/2009, o qual se refere tão somente à atualização de valores de requisitórios. Na parte em que rege a atualização monetária das condenações impostas à Fazenda Pública até a expedição do requisitório (i.e., entre o dano efetivo/ajuizamento da demanda e a condenação), o art. 1º-F da Lei 9.494/1997 ainda não foi objeto de pronunciamento expresso do Supremo Tribunal Federal quanto à sua constitucionalidade e, portanto, continua em pleno vigor. Ressalto, por oportuno, que este debate não se colocou na ADI 4.357 e ADI 4.425, uma vez que, naquelas demandas do controle concentrado, o art. 1º-F da Lei 9.494/1997 não foi impugnado originariamente e, assim, a decisão por arrastamento foi limitada à pertinência lógica entre o art. 100, § 12, da CRFB/1988 e o aludido dispositivo infraconstitucional.","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"[ RE 870.947 RG , voto do rel. min. Luiz Fux , P, j. 16-4-2015, DJE 77 de 27-4-2015]","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"● Incidem os juros da mora no período compreendido entre a data da realização dos cálculos e a da requisição ou do precatório.","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"[Tese definida no RE 579.431, rel. min. Marco Aurélio, P, j. 19-4-2017, DJE 145 de 30-6-2017, Tema 96.]","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"● É devida correção monetária no período compreendido entre a data de elaboração do cálculo da requisição de pequeno valor (RPV) e sua expedição para pagamento.","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"[Tese definida no ARE 638.195 , rel. min. Joaquim Barbosa , P, j. 29-5-2013, DJE 246 de 13-12-2013, Tema 450.]","deleted":false}],"heading":false},{"page":80,"runs":[{"text":"A diferença determinante entre precatórios e requisições de pequeno valor é a quantia a ser paga pelo ente público condenado em sentença transitada em julgado. Cada ente federado pode estabelecer o valor que entende ser de menor monta, para pagamento no prazo de sessenta dias, sem a necessidade de inclusão em listas ordinatórias de antiguidade e relevância para pagamento no exercício subsequente. A diferença baseada no valor é irrelevante para determinação da mora, pois em ambos os casos, precatórios e RPVs, os entes públicos estão proibidos de optar pela inadimplência. Portanto, a orientação firmada para precatórios é adequada para o tratamento da mora de RPVs. Em relação à correção monetária, cabe o mesmo tratamento dispensado aos juros. Ao passo em que os juros moratórios servem de elemento de dissuasão do atraso no cumprimento da obrigação de pagar os valores das condenações judiciais transitadas em julgado, a correção monetária recupera a perda do poder aquisitivo da moeda. (...) Portanto, caracterizada a mora e a inflação, é","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"cabível a correção monetária do crédito de RPV pago a destempo. (...) Ante o exposto, conheço do recurso extraordinário e lhe dou provimento, para reconhecer o direito à aplicação de correção monetária, calculado no período entre a elaboração da conta e a expedição da RPV.","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"[ ARE 638.195 , voto do rel. min. Joaquim Barbosa , P, j. 29-5-2013, DJE 246 de 13-12-2013, Tema 450. ]","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"● O art. 78 do Ato das Disposições Constitucionais Transitórias possui a mesma mens legis que o art. 33 desse Ato, razão pela qual, uma vez calculado o precatório pelo valor real do débito, acrescido de juros legais, não há mais falar em incidência desses nas parcelas anuais, iguais e sucessivas em que é fracionado, desde que adimplidas a tempo e corrigidas monetariamente.","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"[Tese definida no RE 590.751 , rel. min. Ricardo Lewandowski , P, j. 9-12-2010, DJE 63 de 4-4-2011, Tema 132.]","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"Ademais, conforme mencionado na decisão agravada, a jurisprudência desta Corte firmou-se no sentido de que não incidem juros compensatórios ou moratórios no pagamento de precatórios efetuado na forma prevista no art. 33 do ADCT, salvo, quanto aos últimos, na hipótese de atraso na quitação das prestações mencionadas naquele dispositivo. (...) Ressalto que esse entendimento foi mantido pelo Plenário do Supremo Tribunal Federal no recente julgamento do RE 590.751 RG/SP, de minha relatoria, que entendeu que a interpretação conferida pela Corte ao art. 33 do ADCT aplica-se, também, ao art. 78 do mesmo Ato, ante a identidade teleológica dos dois dispositivos. Desse modo, concluiu-se pela não incidência de juros moratórios e compensatórios sobre as frações resultantes do parcelamento de precatórios previsto naquelas duas normas.","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"[ RE 561.149 AgR , voto do rel. min. Ricardo Lewandowski , 2ª T, j. 22-5-2012, DJE 109 de 5-6-2012.]","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"● Durante o período previsto no § 1º do art. 100 (redação original e redação da EC 30/2000) da Constituição, não incidem juros de mora sobre os precatórios que nele sejam pagos.","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"[Tese definida no RE 591.085 QO-RG , rel. min. Ricardo Lewandowski , P, j. 4-12-2008, DJE 35 de 20-2-2009, Tema 147.]","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"Consoante assentado na decisão agravada, o Plenário do Supremo Tribunal Federal consagrou, no julgamento do RE 591.085/MS ( DJE de 20-2-2009), à unanimidade, sob o rito da repercussão geral, o entendimento de que não incidem juros de mora sobre precatórios durante o prazo previsto na redação original do art. 100, § 1º, da Constituição da República (art. 100, § 5º, da redação da EC 62/2009) para o seu pagamento. (...) Firmada a jurisprudência do Plenário da Corte no sentido da decisão embargada, mostram-se incabíveis os embargos, a teor do art. 332 do RISTF. Conforme também já assinalado na decisão agravada, não afronta o art. 5º, XXXVI, da Constituição da República a decisão que, limitada a interpretar adequadamente o título exequendo à luz do ordenamento constitucional vigente, preserva a eficácia do comando expresso de incidência dos juros de mora sobre todo o período em que verificada demora injustificada até o pagamento integral do débito.","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"[ RE 577.465 AgR-ED-ED-EDv-AgR , voto da rel. min. Rosa Weber , P, j. 23-9-2016, DJE 214 de 6-10-2016.]","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":81,"runs":[{"text":"Condenação de juros de mora no prazo constitucional e coisa julgada","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"(...) a jurisprudência desta Suprema Corte firmou entendimento no sentido de que a aplicação do enunciado da Súmula Vinculante 17 aos precatórios oriundos de sentenças já transitadas em julgado não ofende a coisa julgada. (...) Ressalto, por fim, que esta Corte pacificou o entendimento de que, quando não cumprido o prazo legal para o pagamento do precatório, havendo inobservância do prazo constitucional de pagamento das parcelas do precatório, incidem juros moratórios. (...) Posto isso, conheço do recurso extraordinário para reconhecer a contrariedade ao art. 100, §§ 5° e 12, da Constituição Federal, à Súmula Vinculante 17 (...).","deleted":false}],"heading":false},{"page":81,"runs":[{"text":"[ ARE 1.455.437 , rel. min. Cristiano Zanin , dec. monocrática, j. 16-05-2024, DJE de 20-5-2024.]","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"(...) PRECATÓRIO. JUROS MORATÓRIOS NO PRAZO PREVISTO NO ART. 100, § 5º, DA CONSTITUIÇÃO FEDERAL. SÚMULA VINCULANTE 17. INEXISTÊNCIA DE VIOLAÇÃO À COISA JULGADA. 1. Esta SUPREMA CORTE, no julgamento do AI 850.091 AgR, 1ª Turma, Rel. Min. CÁRMEN LÚCIA, decidiu que a “condenação ao pagamento de juros moratórios firmada na sentença com trânsito em julgado não impede a incidência da jurisprudência deste Supremo Tribunal Federal, que afastou a caracterização da mora no prazo constitucional para pagamento de precatórios”.","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"[ RE 566.030 AgR-AgR , rel. min. Alexandre de Moraes , 1ª T, j. 29-6-2018, DJE 157, 6-8-2018.]","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"Agravo regimental em agravo regimental em recurso extraordinário. 2. Precatório. 3. Incidência de juros de mora entre a data da expedição e do efetivo pagamento. 4. Sentença transitada em julgado estipulando a incidência dos juros até o depósito integral da dívida. Necessidade de observar a coisa julgada. 5. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"[ RE 524.821 AgR-AgR , rel. min. Gilmar Mendes , 2ª T, j. 25-8-2015, DJE 180 de 11-9-2015.]","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"Como afirmado na decisão agravada, o Tribunal a quo assentou o trânsito em julgado da sentença exequenda que estabeleceu a incidência de juros de mora até o depósito integral da dívida, não se aplicando, portanto, a jurisprudência deste Supremo Tribunal firmada no sentido da impossibilidade de incidência de juros moratórios durante o prazo constitucionalmente previsto para pagamento do precatório (...). Ademais, este Supremo Tribunal tem entendimento de que a discussão relativa aos limites objetivos da coisa julgada é de natureza infraconstitucional. (...) Os argumentos da agravante, insuficientes para modificar a decisão agravada, demonstram apenas inconformismo e resistência em pôr termo a processos que se arrastam em detrimento da eficiente prestação jurisdicional.","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"[ RE 654.571 AgR , voto da rel. min. Cármen Lúcia , 2ª T, j. 12-5-2015, DJE 94 de 21-5-2015.]","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"(...) tratando-se de pleito que visa a definir o alcance do dispositivo de sentença transitada em julgado, também se mostra incabível o acolhimento em recurso extraordinário, por se tratar de questão de natureza jurídica infraconstitucional, que desafiaria recurso especial. A questão só poderia ser alçada ao crivo do Supremo mediante recurso de pronunciamento de colegiado do Superior Tribunal de Justiça, em última instância. Todavia, o recurso especial foi desprovido e já certificado o trânsito em julgado. Logo, preclusa a alegação, conforme bem sustentado pelos agravados. 3. A arguição do agravo demonstra inconformismo com a conclusão proferida na ponderação entre a norma do art. 5º, XXXVI, e a do art. 100, § 1º, ambas da CF/1988, e o Verbete Vinculante 17. Isto é, pretende nova interpretação, que equivale a novo julgamento da causa, medida notadamente inviável.","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"[ RE 651.134 AgR , rel. min. Luiz Fux , 1ª T, j. 16-10-2012, DJE 220 de 8-11-2012.]","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"Impossibilidade de aplicação da taxa SELIC no período de graça constitucional","deleted":false}],"heading":false},{"page":82,"runs":[{"text":"1. Durante o período de que trata o § 5º do art. 100 da Constituição Federal, não incidem juros de mora, somente com o inadimplemento do ente público devedor, ou seja, após o período de graça, é possível a fluência dos juros moratórios (Súmula Vinculante 17/STF e RE 1.169.289/SC, tema 1.037 da repercussão geral). 2. O art. 3º da EC 113/2021, cuja constitucionalidade já foi reconhecida por esta Suprema Corte (...), estabelece que, a partir de sua entrada em vigor, em todas as condenações que envolvam a Fazenda Pública, para fins de atualização monetária, juros moratórios e juros compensatórios, inclusive do precatório, deve ser aplicada, uma única vez, até o efetivo pagamento, a taxa SELIC. 3. A taxa SELIC engloba juros e correção monetária, de modo que não pode ser cumulada com a aplicação de outros índices de atualização monetária, cumulação que representaria bis in idem (...). 4. A adequada compatibilização entre as normas constitucionais deve manter a efetividade dessas normas, sendo certo que admitir a incidência da taxa SELIC no período de graça de expedição de precatório acarretaria o esvaziamento completo da parte final do § 5º do art. 100 do texto constitucional, em nítida transgressão ao princípio da unidade da Constituição. 5. Necessidade de promover, portanto, com base na concordância prática, ajuste hermenêutico em relação ao art. 3º da EC","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"113/2021, de modo a, mantendo sua eficácia, reduzir, minimamente, seu âmbito de incidência. Assim, a partir da entrada em vigor da EC 113/2021, apenas no período a que se refere o art. 100, § 5º, da Constituição Federal, a taxa SELIC não deve incidir (art. 3º da EC 113/2021), preservando-se, em tal período, a imunidade aos juros e mantendo-se exclusivamente a correção monetária.","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"[ RE 1.475.938 , rel. min. Gilmar Mende s, 2ª T, j. 7-5-2024, DJE s/n de 15-5-2024.]","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"Impossibilidade de aplicação de juros após a consolidação do parcelamento do precatório previsto no art. 78 do ADCT","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"5. Ao caso, aplica-se o enunciado nº 17 da Súmula Vinculante do STF desta Corte (“Durante o período previsto no § 1º do artigo 100 da Constituição, não incidem juros de mora sobre os precatórios que nele sejam pagos”). 6. Impossibilidade de aplicação de juros moratórios e compensatórios após a consolidação do parcelamento previsto no art. 78 do ADCT, desde que as parcelas tenham sido adimplidas a tempo.","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"[ ARE 1.424.987 AgR , rel. min. André Mendonça , 2ª T, j. 13-9-2024, DJE s/n de 16-9-2024.]","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"Incidência de juros de mora em caso de pagamento do precatório fora do prazo constitucional","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"1. A jurisprudência desse Supremo Tribunal Federal é no sentido de que não incidem juros moratórios sobre os precatórios pagos durante o prazo previsto no art. 100, §5º, da Constituição. 2. Em caso de inadimplemento do prazo constitucional, os juros moratórios passam a incidir a partir do primeiro dia do exercício financeiro seguinte ao que deveria ter sido pago o precatório. Precedentes.","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"[ RE 940.236 AgR , rel. min. Marco Aurélio , red. p/ o ac. min. Roberto Barroso , 1ª T, j. 25-10-2016, DJE 176 de 10-8-2017.]","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"Não afronta a Súmula Vinculante 17 do STF a decisão que determina a não incidência de juros moratórios durante o período compreendido pelo verbete, fluindo os juros após o término desse prazo. Precedentes. 2. Não prospera a pretensão de submeter a não incidência prevista na Súmula Vinculante 17 do STF a uma condição resolutiva, que seria o pagamento do precatório dentro do prazo.","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"[ Rcl 15.906 AgR , rel. min. Edson Fachin , 1ª T, j. 18-8-2015, DJE 201 de 7-10-2015.]","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"A pretensão da agravante é no sentido da exclusão dos juros moratórios no período relativo ao lapso temporal previsto no art. 100, § 1º, da CF/1988. O Plenário, ao examinar o RE 298.616, no qual fiquei vencido, assentou que, observada a época própria do julgamento do precatório, impossível é cogitar da mora, porque ausente a inadimplência. (...) Na espécie, contudo, tem-se a inadimplência, ante o pagamento fora do prazo previsto constitucionalmente. Ante o quadro, conheço do agravo e o desprovejo","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"[ ARE 841.864 AgR , voto do rel. min. Marco Aurélio , 1ª T, j. 16-12-2014, DJE 28 de 11-2-2015.]","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"Em razão do regime constitucional e legal de administração financeira do Estado e de execução contra a Fazenda Pública entre 1º de julho e o último dia do exercício financeiro seguinte, não há que se falar em atraso do poder público no pagamento de precatórios. 2. O juro de mora é encargo decorrente da demora no adimplemento da obrigação, somente se justificando sua incidência no período que extrapola o tempo ordinário de pagamento do precatório. 3. Para os precatórios expedidos até 1º de julho e não pagos pelo poder público até o último dia do exercício financeiro seguinte, correrão juros de mora do primeiro dia do exercício financeiro seguinte ao fim do prazo constitucional até a data do efetivo pagamento.","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"[ Rcl 13.684 AgR , rel. min. Dias Toffoli , 1ª T, j. 28-10-2014, DJE 229 de 21-11-2014.]","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"Modulação dos efeitos da declaração de inconstitucionalidade do índice de correção monetária estabelecido na EC 62/2009","deleted":false}],"heading":false},{"page":83,"runs":[{"text":"Vale registrar que há dois paradigmas à luz dos quais deve ser analisado qual o índice de correção monetário adequado incidente ao débito fazendário: a dos precatórios já expedidos ou pagos até 25 de março de 2015; e a dos precatórios ainda não expedidos até essa data. A orientação firmada nas ADIs 4.357 e 4.425, no bojo","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"das quais fora deferida a modulação de efeitos para assegurar a incidência da TR, apenas se aplica aos débitos cujos respectivos precatórios já tivessem sido expedidos à época do julgamento das ações de controle concentrado de constitucionalidade. Por sua vez, a orientação definida no julgamento dos embargos de declaração no RE 870.947, paradigma do tema 810 da repercussão geral, que rechaçou a modulação de efeitos pleiteada, de maneira a determinar o imediato afastamento da TR como índice de correção monetária desde o ano de 2009 até 2015, incide nas hipóteses em que não tenha sido expedido o precatório correspondente. Assim, sendo o caso dos autos referente a precatório expedido anteriormente à data do julgamento das ações de controle concentrado, tem-se que o índice de correção monetária correto a ser aplicado é a TR, na forma definida pelo art. 1º-F, da Lei nº 9.494/1997, conforme a modulação de efeitos das decisões na ADIs. (...) Assim, não se verifica contrariedade entre o acórdão do Tribunal de origem e os precedentes desta Corte constitucional. (Grifos no original)","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"[ ARE 1.443.512 , rel. min. Gilmar Mendes , dec. monocrática, j. 4-4-2024, DJE s/n 5-4-2024.]","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"(...) acordam os ministros do Supremo Tribunal Federal, em sessão plenária (...), por maioria e nos termos do voto, ora reajustado, do ministro Luiz Fux (relator), em resolver a questão de ordem nos seguintes termos: 1) modular os efeitos para que se dê sobrevida ao regime especial de pagamento de precatórios, instituído pela EC 62/2009, por 5 (cinco) exercícios financeiros a contar de 1º de janeiro de 2016; 2) conferir eficácia prospectiva à declaração de inconstitucionalidade dos seguintes aspectos da ação direta de inconstitucionalidade, fixando como marco inicial a data de conclusão do julgamento da presente questão de ordem (25-3-2015) e mantendo-se válidos os precatórios expedidos ou pagos até esta data, a saber: 2.1.) fica mantida a aplicação do índice oficial de remuneração básica da caderneta de poupança (TR), nos termos da EC 62/2009, até 25-3-2015, data após a qual (i) os créditos em precatórios deverão ser corrigidos pelo Índice de Preços ao Consumidor Amplo Especial (IPCA-E) e (ii) os precatórios tributários deverão observar os mesmos critérios pelos quais a Fazenda Pública corrige seus créditos tributários; e 2.2.) ficam resguardados os precatórios expedidos, no âmbito da administração pública federal, com base nos arts. 27 da Lei 12.919/2013 e da Lei 13.080/2015, que fixam o IPCA-E como índice de correção monetária.","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"[ ADI 4.425 QO , rel. min. Luiz Fux , P, j. 25-3-2015, DJE 152 de 4-8-2015.]","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"Não incidem juros de mora no “período de graça”","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"Destaco, nesse contexto, o teor do enunciado vinculante n. 17 da Súmula, a revelar imprópria a contagem de juros moratórios no curso do referido interregno: (...) Mesmo considerando a redação dada ao § 5º do art. 100 pela Emenda Constitucional n. 62/2009 - atualmente conferida pela EC n. 114/2021 -, esta Corte consignou, também no âmbito da repercussão geral, a não incidência de juros moratórios no período de graça.","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"[ RE 1.514.944 AgR , rel. min. Nunes Marques , 2ª T, j. 1º-9-2025, DJE s/n 3-10-2025.]","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"Precatório e não incidência de juros moratórios no período entre a elaboração da conta e a sua expedição","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"A jurisprudência do STF entende que, não havendo atraso na satisfação do débito, não incidem juros moratórios entre a data da expedição e a data do efetivo pagamento do precatório. Súmula Vinculante 17 do STF. II - Esse entendimento se aplica ao período entre a elaboração da conta e a expedição do precatório.","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"[ RE 592.869 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 26-8-2014, DJE 171 de 4-9-2014.]","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":84,"runs":[{"text":"● A PSV 59 e a PSV 111, que requerem a revisão ou cancelamento da Súmula Vinculante 17, foram sobrestadas em razão da repercussão geral reconhecida no RE 579.431, cujo mérito foi julgado pelo STF, em 19-4-2017 e publicado no DJE 145 de 30-6-2017.","deleted":false}],"heading":false},{"page":84,"runs":[{"text":"Data de publicação do enunciado: DJE de 10-11-2009.","deleted":false}],"heading":false},{"page":85,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":85,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"18","number":"18","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":86,"endPage":88,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1245","paragraphs":[{"page":86,"runs":[{"text":"A dissolução da sociedade ou do vínculo conjugal, no curso do mandato, não afasta a inelegibilidade prevista no § 7º do artigo 14 da Constituição Federal.","deleted":false}]}],"notes":[{"page":86,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":86,"runs":[{"text":"A dissolução da sociedade conjugal, no curso do mandato, não afasta a inelegibilidade prevista no art. 14, § 7º, da CF/1988. II - Se a separação judicial ocorrer em meio à gestão do titular do cargo que gera a vedação, o vínculo de parentesco, para os fins de inelegibilidade, persiste até o término do mandato, inviabilizando a candidatura do ex-cônjuge ao pleito subsequente, na mesma circunscrição, a não ser que aquele se desincompatibilize seis meses antes das eleições.","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"[ RE 568.596 , rel. min. Ricardo Lewandowski , P, j. 1º-10-2008, DJE 222 de 21-11-2008, Tema 61.]","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"A regra estabelecida no art. 14, § 7º, da CF/1988, iluminada pelos mais basilares princípios republicanos, visa obstar o monopólio do poder político por grupos hegemônicos ligados por laços familiares. Precedente. 2. Havendo a sentença reconhecido a ocorrência da separação de fato em momento anterior ao início do mandato do ex-sogro do recorrente, não há falar em perenização no poder da mesma família (Consulta 964/DF - Res./TSE 21.775, de minha relatoria). 3. Recurso extraordinário provido para restabelecer o registro de candidatura.","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"[ RE 446.999 , rel. min. Ellen Gracie , 2ª T, j. 28-6-2005, DJ de 9-9-2005.]","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":86,"runs":[{"text":"● As hipóteses de inelegibilidade previstas no art. 14, § 7º, da Constituição Federal, inclusive quanto ao prazo de seis meses, são aplicáveis às eleições suplementares.","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"[Tese definida no RE 843.455 , rel. min. Teori Zavascki , P, j. 7-1-2015, DJE 18 de 1º-2-2016, Tema 781.]","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"● A Súmula Vinculante 18 do STF (“A dissolução da sociedade ou do vínculo conjugal, no curso do mandato, não afasta a inelegibilidade prevista no § 7º do art. 14 da Constituição Federal”) não se aplica aos casos de extinção do vínculo conjugal pela morte de um dos cônjuges.","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"[Tese definida no RE 758.461 , rel. min. Teori Zavascki , P, j. 22-5-2014, DJE 213 de 30-10-2014, Tema 678.]","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"O que está em questão é saber se em eleição suplementar para prefeito (cujo titular anterior teve seu mandato cassado) o prazo, dito de desincompatibilização, também é de 6 (seis) meses, conforme previsto no art. 14, § 7º, da CF/1988 (...). Mas a questão não pode ser vista por esse ângulo. Não se trata, aqui, de desincompatibilização da esposa candidata, até porque ela não exercia o cargo do qual devesse, ela própria, desincompatibilizar-se. A hipótese é de inelegibilidade, e como tal deve ser considerada para todos os efeitos. 4. Conforme jurisprudência assentada no Tribunal, (...) o § 7º do art. 14 da CF/1988 tem o desiderato ético, político e social de prevenir possível apoderamento familiar dos mandatos eletivos, inclusive com utilização indevida da estrutura administrativa. Trata-se de hipótese constitucional de inelegibilidade e, como tal, insuscetível de mitigação em favor dos seus destinatários.","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"[ RE 843.455 , voto do rel. min. Teori Zavascki , P, j. 7-10-2015, DJE 18 de 1º-2-2016.]","deleted":false}],"heading":false},{"page":86,"runs":[{"text":"CONSTITUCIONAL E ELEITORAL. MORTE DE PREFEITO NO CURSO DO MANDATO, MAIS DE UM ANO ANTES DO TÉRMINO. INELEGIBILIDADE DO CÔNJUGE SUPÉRSTITE. CF/1988, ART. 14, § 7º. INOCORRÊNCIA. 1. O que orientou a edição da Súmula Vinculante 18 e os recentes precedentes do STF foi a","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"preocupação de inibir que a dissolução fraudulenta ou simulada de sociedade conjugal seja utilizada como mecanismo de burla à norma da inelegibilidade reflexa prevista no § 7º do art. 14 da CF/1988. Portanto, não atrai a aplicação do entendimento constante da referida súmula a extinção do vínculo conjugal pela morte de um dos cônjuges.","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"[ RE 758.461 , rel. min. Teori Zavascki , P, j. 22-5-2014, DJE 213 de 30-10-2014.]","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"Há plausibilidade na alegação de que a morte de prefeito, no curso do mandato (que passou a ser exercido pelo vice-prefeito), não acarreta a inelegibilidade do cônjuge, prevista no art. 14, § 7º, da CF/1988. Trata-se de situação diferente da que ocorre nos casos de dissolução da sociedade conjugal no curso do mandato, de que trata a Súmula Vinculante 18.","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"[ AC 3.298 MC-AgR , rel. min. Teori Zavascki , 2ª T, j. 24-4-2013, DJE 235 de 29-11-2013.]","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"● A dissolução da sociedade ou do vínculo conjugal, no curso do mandato, não afasta a inelegibilidade prevista no § 7º do artigo 14 da Constituição Federal.","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"[Tese definida no RE 568.596 , rel. min. Ricardo Lewandowski , P, j. 1º-10-2008, DJE 222 de 21-11-2008, Tema 61.]","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":87,"runs":[{"text":"Autonomia administrativa de Município desmembrado evidenciada pelo decurso de tempo possibilita a candidatura de cônjuge de prefeito reeleito em Município vizinho","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"O acórdão emanado do E. Tribunal Superior Eleitoral, objeto do recurso extraordinário a que se refere o presente agravo, examinou, de maneira adequada, a controvérsia em referência, entendendo inexistir qualquer obstáculo à candidatura de (...) ora agravada (reeleita, em outubro de 2016, para novo mandato como prefeita municipal), pelo fato de o Município de Porto Seguro/BA haver sido desmembrado de Eunápolis/BA há mais de vinte anos, “o que evidencia sua autonomia administrativa”.","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"[ ARE 768.043 , rel. min. Celso de Mello , dec. monocrática, j. 28-11-2016, DJE 257 de 2-12-2016.]","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"Dissolução da sociedade conjugal durante o mandato e causa objetiva de inelegibilidade","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"A pretensão, portanto, esbarra no enunciado da Súmula Vinculante 18 (...). Como se observa, a inelegibilidade preconizada no enunciado da referida Súmula é objetiva, isto é, se a dissolução da sociedade ou do vínculo conjugal ocorrer apenas no transcorrer do segundo mandato do então prefeito, o cônjuge, tal como o ex-mandatário com quem mantinha o vínculo matrimonial, mantém-se inelegível para disputar o cargo de chefe do Executivo municipal para o pleito subsequente. Pouco importa, portanto, se houve ou não anterior separação de fato deflagrada no primeiro mandato exercido por seu ex-marido. Além disso, a discussão quanto à existência de fraude é irrelevante, pois, como dito, a hipótese descrita na súmula exige o preenchimento de circunstância objetiva, requerendo para sua configuração, tão somente, a ocorrência da dissolução do vínculo conjugal no curso do mandato, como de fato ocorreu no caso ora em exame.","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"[ AC 3.311 AgR , voto do rel. min. Ricardo Lewandowski , 2ª T, j. 19-3-2013, DJE 63 de 8-4-2013.]","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"Vínculo familiar afetivo e inelegibilidade","deleted":false}],"heading":false},{"page":87,"runs":[{"text":"Com efeito, o acórdão recorrido se funda em interpretação teleológica do art. 14, § 7º, da CF/1988, que, com substrato no princípio republicano, impede a formação de oligarquias políticas capazes de fragilizar o equilíbrio das eleições, diante do risco de manipulação da máquina pública em prol da perpetuação de um grupo delimitado no poder. (...) Embora a filiação socioafetiva não se revista dos mesmos rigores formais da adoção, a leitura do art. 14, § 7º, da CF/1988 à luz do princípio republicano conduz a que a inelegibilidade também incida in casu. É que o chamado filho de criação, da mesma forma como ocorre com a filiação formal, acaba por ter sua candidatura beneficiada pela projeção da imagem do pai socioafetivo que tenha exercido o mandato, atraindo para si os frutos da gestão anterior com sensível risco para a perpetuação de oligarquias.","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"Parece clara, assim, a perspectiva de desequilíbrio no pleito, atraindo, por identidade de razões, a incidência da referida regra constitucional.","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"[ AC 2.891 MC , rel. min. Luiz Fux , dec. monocrática, j. 6-6-2011, DJE 115 de 16- 6-2011.]","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":88,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 61, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 678, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"Data de publicação do enunciado: DJE de 10-11-2009.","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":88,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"19","number":"19","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":89,"endPage":91,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1248","paragraphs":[{"page":89,"runs":[{"text":"A taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis não viola o artigo 145, II, da Constituição Federal.","deleted":false}]}],"notes":[{"page":89,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":89,"runs":[{"text":"(...) observo, inicialmente, que o Supremo Tribunal Federal fixou balizas quanto à interpretação dada ao art. 145, II, da Constituição Federal, no que concerne à cobrança de taxas pelos serviços públicos de limpeza prestados à sociedade. Com efeito, a Corte entende como específicos e divisíveis os serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, desde que essas atividades sejam completamente dissociadas de outros serviços públicos de limpeza realizados em benefício da população em geral ( uti universi ) e de forma indivisível, tais como os de conservação e limpeza de logradouros e bens públicos (praças, calçadas, vias, ruas, bueiros). Decorre daí que as taxas cobradas em razão exclusivamente dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis são constitucionais, ao passo que é inconstitucional a cobrança de valores tidos como taxa em razão de serviços de conservação e limpeza de logradouros e bens públicos. (...) Além disso, no que diz respeito ao argumento da utilização de base de cálculo própria de impostos, o Tribunal reconhece a constitucionalidade de taxas que, na apuração do montante devido, adote um ou mais dos elementos que compõem a base de cálculo própria de determinado imposto, desde que não se verifique identidade integral entre uma base e a outra.","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"[ RE 576.321 QO-RG , voto do rel. min. Ricardo Lewandowski , P, j. 4-12-2008, DJE 30 de 13-2-2009, Tema 146.]","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":89,"runs":[{"text":"● I - A taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis não viola o art. 145, II, da Constituição Federal;","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"II - A taxa cobrada em razão dos serviços de conservação e limpeza de logradouros e bens públicos ofende o art. 145, II, da Constituição Federal;","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"III - É constitucional a adoção, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e outra.","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"[Tese definida no RE 576.321 QO-RG , rel. min. Ricardo Lewandowski , P, j. 4-12-2008, DJE 30 de 13-2-2009, Tema 146.]","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"A irresignação merece prosperar. Inicialmente, ressalta-se que “A taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, não viola o art. 145, II, da Constituição Federal” (Súmula Vinculante 19). (...) constata-se que o acórdão recorrido destoa da jurisprudência desta Corte, segundo a qual é constitucional a taxa de serviços urbanos referente à limpeza pública quando a sua base de cálculo guarda pertinência com a metragem da área construída do imóvel e respectiva finalidade. (...) Ante o exposto, conheço do recurso a que se dá provimento, nos termos do art. 21, § 2º, do RISTF, com a finalidade de reformar o acórdão recorrido para fins de determinar a inclusão dos valores relativos à taxa de serviços urbanos da parte recorrente no exercício de 2002 na execução fiscal subjacente.","deleted":false}],"heading":false},{"page":89,"runs":[{"text":"[ RE 952.512 , rel. min. Edson Fachin , dec. monocrática, j. 31-3-2017, DJE 68 de 5-4-2017.]","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"O reclamante aponta violada a Súmula Vinculante 19, (...) a Corte reclamada declarou a inexigibilidade da denominada “taxa de serviços urbanos”, prevista na Lei Municipal 106/2006, à consideração de que esta engloba, em um único valor, os serviços de coleta de lixo, de conservação de calçamento e limpeza pública. O referido acórdão, ao contrário do que alegado pelo reclamante, prestigia o entendimento cristalizado na Súmula Vinculante 19, no sentido da constitucionalidade da taxa cobrada em razão da prestação de serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, desde que tais atividades sejam dissociadas de outros serviços públicos de limpeza realizados em benefício da população em geral e de forma indivisível. (...) 5. Quanto ao pedido de declaração da inexigibilidade apenas da taxa de conservação de ruas e da taxa de limpeza pública, registro que não compete a esta Suprema Corte, na via reclamatória, apreciar o referido pleito. Com efeito, a jurisprudência desta Suprema Corte reputa inviável conferir à reclamação a natureza de sucedâneo recursal ou de meio ensejador do reexame do conteúdo do ato reclamado. (...) 6. Ante o exposto, ausente afronta à Súmula Vinculante 19, nego seguimento à reclamação (art. 21, § 1º, do RISTF), resultando prejudicado o pedido liminar.","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"[ Rcl 24.611 , rel. min. Rosa Weber , dec. monocrática, j. 28-11-2016, DJE 256 de 1º-12-2016.]","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"A jurisprudência deste Tribunal já firmou o entendimento no sentido de que o serviço de coleta de lixo domiciliar deve ser remunerado por meio de taxa, uma vez que se trata de atividade específica e divisível, de utilização efetiva ou potencial, prestada ao contribuinte ou posta à sua disposição. Ao inverso, a taxa de serviços urbanos, por não possuir tais características, é inconstitucional.","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"[ AI 702.161 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 15-12-2015, DJE 25 de 12-2-2016.]","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"O Supremo Tribunal Federal firmou entendimento no sentido da legitimidade da taxa de coleta de lixo proveniente de imóveis, entendendo como específico e divisível o serviço público de coleta e tratamento de lixo domiciliar prestado ao contribuinte ou posto à sua disposição.","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"[ AI 311.693 AgR , rel. min. Dias Toffoli , 1ª T, j. 6-12-2011, DJE 78 de 23-4-2012.]","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"O exame da possibilidade de o serviço público ser destacado em unidades autônomas e individualizáveis de fruição não se esgota com o estudo da hipótese de incidência aparente do tributo. É necessário analisar a base de cálculo da exação, que tem por uma de suas funções confirmar, afirmar ou infirmar o critério material da regra-matriz de incidência.","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"[ RE 571.241 AgR , rel. min. Joaquim Barbosa , 2ª T, j. 20-4-2010, DJE 100 de 4-6-2010.]","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":90,"runs":[{"text":"Área do imóvel como elemento para apurar o valor da taxa","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"(...) no cálculo das taxas, não há como se exigir correspondência precisa com o valor despendido na prestação do serviço, ou, ainda, a adoção de fatores exclusivamente vinculados ao seu custo. Basta uma equivalência razoável entre o valor pago pelo contribuinte e o custo individual do serviço que lhe é prestado. (...) a adoção da área do imóvel como elemento para apurar o valor de taxas cobradas pelo serviço público de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis não viola o texto constitucional (...).","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"[ RE 1.384.690 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 31-5-2022, DJE 107 de 2-6-2022.]","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"Fixação da taxa em valor fixo e diferenciado para imóveis residenciais e não residenciais","deleted":false}],"heading":false},{"page":90,"runs":[{"text":"(...) o acórdão recorrido divergiu da orientação do Supremo Tribunal Federal cristalizada na Súmula Vinculante 19. (...) é constitucional a taxa de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, desde que essas atividades sejam completamente dissociadas de outros serviços públicos de limpeza realizados em benefício da população em geral, como ocorre no caso dos autos. Resta controvertida (...) a demanda precisamente no ponto de fixação da taxa em valor fixo e diferenciado para imóveis","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"residenciais e não residenciais. (...) o princípio da isonomia tributária se perfaz na devida repartição dos custos dos serviços entre os usuários. Isto é, traduz-se o princípio da isonomia, bem como a capacidade contributiva, ao promover a especificidade e a divisibilidade na razoável presunção de que imóveis residenciais e não residenciais produzem quantidades e variantes diferentes de resíduos, desfrutando dos serviços de coleta em medidas diversas.","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"[ RE 1.291.252 , rel. min. Dias Toffoli , dec. monocrática, j. 11-11-2020, DJE 274 de 18-11-2020.]","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":91,"runs":[{"text":"● Vide Súmula Vinculante 29 e Súmula 670.","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 146, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"Data de publicação do enunciado: DJE de 10-11-2009.","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":91,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"20","number":"20","scope":"main","kind":"vinculante","sectionId":"grupo-1","page":92,"endPage":97,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1252","paragraphs":[{"page":92,"runs":[{"text":"A Gratificação de Desempenho de Atividade Técnico-Administrativa - GDATA, instituída pela Lei 10.404/2002, deve ser deferida aos inativos nos valores correspondentes a 37,5 (trinta e sete vírgula cinco) pontos no período de fevereiro a maio de 2002 e, nos termos do artigo 5º, parágrafo único, da Lei 10.404/2002, no período de junho de 2002 até a conclusão dos efeitos do último ciclo de avaliação a que se refere o artigo 1º da Medida Provisória 198/2004, a partir da qual passa a ser de 60 (sessenta) pontos.","deleted":false}]}],"notes":[{"page":92,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":92,"runs":[{"text":"Gratificação de Desempenho de Atividade Técnico-Administrativa (GDATA) instituída pela Lei 10.404/2002: extensão a inativos: pontuação variável conforme a sucessão de leis regentes da vantagem. Recurso extraordinário conhecido e provido, em parte, para que a GDATA seja deferida aos inativos nos valores correspondentes a 37,5 (trinta e sete vírgula cinco) pontos no período de fevereiro a maio de 2002 e nos termos do art. 5º, parágrafo único, da Lei 10.404/2002, para o período de junho de 2002 até a conclusão dos efeitos do último ciclo de avaliação a que se refere o art. 1º da MP 198/2004, a partir da qual passa a ser de 60 (sessenta) pontos.","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"[ RE 476.279 , rel. min. Sepúlveda Pertence , P, j. 19-4-2007, DJE 37 de 15-6-2007.]","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":92,"runs":[{"text":"● I - O termo inicial do pagamento diferenciado das gratificações de desempenho entre servidores ativos e inativos é o da data da homologação do resultado das avaliações, após a conclusão do primeiro ciclo;","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"II - A redução, após a homologação do resultado das avaliações, do valor da gratificação de desempenho paga aos inativos e pensionistas não configura ofensa ao princípio da irredutibilidade de vencimentos.","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"[Tese definida no ARE 1.052.570 RG , rel. min. Alexandre de Moraes , P, j. 15-2-2018, DJE 42 de 6-3-2018, Tema 983.]","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"2. O Tribunal de origem assentou que é devida a percepção da gratificação GDASS no patamar de 60% até que sobrevenha regulamentação e seja instituída avaliação de desempenho dos servidores da ativa. 3. (...), o entendimento proferido pelo Tribunal de origem está alinhado com a jurisprudência do Supremo Tribunal Federal, que no julgamento do ARE 1.052.570 RG, Rel. Min. Alexandre de Moraes, reconheceu a repercussão geral da controvérsia e reafirmou a jurisprudência no sentido de que o termo inicial do pagamento diferenciado das gratificações de desempenho entre servidores ativos e inativos é o da data da homologação do resultado das avaliações, após a conclusão do primeiro ciclo. Assentou, ainda, que não viola o princípio da irredutibilidade de vencimentos a redução do valor da gratificação dos inativos e pensionistas após a homologação do resultado das avaliações.","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"[ ARE 1.196.401 AgR , rel. min. Roberto Barroso , 1ª T, j. 30-5-2019, DJE 129 de 14-6-2019.]","deleted":false}],"heading":false},{"page":92,"runs":[{"text":"O recurso extraordinário não pode ser acolhido, tendo em vista que o acórdão recorrido está alinhado com a jurisprudência do Supremo Tribunal Federal. A legislação que instituiu as gratificações em exame determinou sua graduação segundo uma avaliação de desempenho institucional e individual, a ser realizada conforme critérios que serão instituídos por ato do Poder Executivo. Até que sobrevenha a regulamentação e sejam realizadas as avaliações, porém, a lei determina que todos os servidores da ativa receberão pelo mesmo","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"patamar. Nesse contexto, o acordão recorrido entendeu que a hipótese seria de gratificação dotada de caráter genérico, o que imporia a sua extensão aos servidores inativos ainda beneficiados pela regra de paridade. Vale dizer: aos servidores que tenham se aposentado antes da edição da Emenda Constitucional 41/2003, ou que, nos termos de seu art. 3º, já tivessem reunido as condições para tanto. Esse é, precisamente, o entendimento adotado pelo Supremo Tribunal Federal em diversas oportunidades quando do exame de gratificações análogas à GDASS, a exemplo da GDATA, objeto da Súmula Vinculante 20: (...). Implementadas as avaliações, a vantagem passa a ter caráter pro labore faciendo , pelo que deixa de ser extensível aos inativos no mesmo patamar que é paga aos ativos.","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"[ RE 1.112.425 , rel. min. Roberto Barroso , dec. monocrática, j. 19-3-2018, DJE 57 de 23-3-2018.]","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"● O termo inicial do pagamento diferenciado das gratificações de desempenho entre servidores ativos e inativos é o da data da homologação do resultado das avaliações, após a conclusão do primeiro ciclo de avaliações, não podendo a Administração retroagir os efeitos financeiros a data anterior.","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"[Tese definida no RE 662.406 , rel. min. Teori Zavascki , P, j. 11-12-2014, DJE 31 de 18-2-2015, Tema 664.]","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"O Supremo Tribunal Federal, no julgamento do RE 662.406 RG, rel. min. Teori Zavascki, assentou a tese de que o termo final para a extensão a inativos das gratificações de desempenho, tal como a GDASS, a GDAP e a GDATA, nos mesmos percentuais em que concedida aos servidores ativos, é o da data da homologação do resultado das avaliações, após a conclusão do primeiro ciclo de avaliações, não podendo a Administração retroagir os efeitos financeiros. 2. Entendimento que não viola o princípio da irredutibilidade de vencimentos.","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"[ ARE 881.698 AgR , rel. min. Roberto Barroso , 1ª T, j. 30-9-2016, DJE 221 de 18-10-2016.]","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"Apreciando a Gratificação de Desempenho de Atividade Técnica de Fiscalização Agropecuária (GDATFA), cujo regramento é similar ao da Gratificação de Desempenho de Atividade Médico-Pericial (GDAMP), o Plenário do STF, no julgamento do RE 662.406 (de minha relatoria, DJE de 18-2-2015, Tema 664), firmou a tese, dotada de repercussão geral, de que “o termo inicial do pagamento diferenciado das gratificações de desempenho entre servidores ativos e inativos é o da data da homologação do resultado das avaliações, após a conclusão do primeiro ciclo de avaliações, não podendo a Administração retroagir os efeitos financeiros a data anterior”. A partir desse termo, a gratificação perde sua natureza geral e adquire o caráter pro labore faciendo . 2. Assim, avaliados os servidores em atividade, o pagamento da GDAMP aos pensionistas e aposentados deverá observar o art. 13 da Lei 10.876/2004, o que não ofende o princípio da irredutibilidade de vencimentos.","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"[ ARE 881.402 AgR , rel. min. Teori Zavascki , 2ª T, j. 23-6-2015, DJE 151 de 3-8-2015.]","deleted":false}],"heading":false},{"page":93,"runs":[{"text":"A hipótese descrita nos autos é análoga àquela decidida por este Tribunal no julgamento do RE 476.279/DF e do RE 476.390/DF, quando se discutiu a respeito da extensão de outra gratificação (GDATA) aos inativos, entendimento sedimentado na Súmula Vinculante 20 (...). A GDATFA e a GDATA são gratificações com as mesmas natureza e características. Originalmente, ambas foram concedidas a todos os servidores de forma geral e irrestrita, apesar de terem sido criadas com o propósito de serem pagas de modo diferenciado, segundo a produção ou o desempenho profissional, individual ou institucional. (...) Num ponto, entretanto, a GDATFA difere da GDATA: ao contrário dessa última, em relação à GDAFTA a Administração iniciou e efetivou as avaliações que justificam o uso do critério diferenciador no pagamento (desempenho individual do servidor e institucional do órgão de lotação), passando a justificar a ausência de paridade entre os servidores ativos e os servidores inativos e pensionistas. Portanto, a meritocracia pretendida com a criação das gratificações de desempenho foi efetivada, o que passou a permitir a diferença no seu pagamento entre os servidores na ativa (de acordo com a produtividade e o desempenho profissional de cada um), e entre estes e os aposentados e pensionistas. A Súmula Vinculante 20 limita-se a prever que, considerando a ausência de realização das avaliações individuais e a institucional durante a vigência da GDATA, não é permitida a discriminação no seu pagamento. Por essa razão, determina o pagamento aos inativos e pensionistas no mesmo montante devido aos servidores ativos. (...) Em suma, a Súmula Vinculante 20 tratou de gratificação específica (GDATA) que, durante sua vigência, foi paga de modo contrário ao determinado na CF/1988, por não existir critérios de","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"avaliação justificadores do tratamento diferenciado dos servidores ativos e inativos. De outro lado, a gratificação discutida neste processo (GDAFTA) surgiu com as mesmas características da GDATA, mas durante sua vigência surgiu causa que validou o pagamento diferenciado da gratificação, em cada ciclo de avaliação. Porém, isso gerou discussão sobre o termo final do direito à paridade (...). Considerando essa nova discussão, que envolve a observância da paridade prevista no art. 40, § 8º, da CF/1988 (com a redação anterior à EC 41/2003), faz-se necessário o reconhecimento da repercussão geral em recurso extraordinário, com a diferenciação entre a tese sobre o termo final e o que foi consolidado na Súmula Vinculante 20 (que é insuficiente para a resolução dessa questão), para resolver a quantidade elevada de processos judiciais existentes sobre o assunto.","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"[ RE 662.406 RG , voto do rel. min. Teori Zavascki , P, j. 20-6-2013, DJE 157 de 13-8-2013, Tema 664.]","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"● A Gratificação de Desempenho do Plano Geral de Cargos do Poder Executivo - GDPGPE, prevista na Lei 11.357/2006, estende-se aos inativos e pensionistas, no patamar de oitenta pontos, até o implemento da avaliação dos servidores em atividade.","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"[Tese definida no RE 631.389 , rel. min. Marco Aurélio , P, j. 25-9-2013, DJE 106 de 3-6-2014, Tema 351.]","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"O Tribunal de origem consignou que as avaliações da GDPGPE retroagiriam à data de sua instituição, 1º de janeiro de 2009. (...) Verifica-se, logo, sua dissonância com a jurisprudência desta Corte, que reconheceu, no julgamento do tema 351 da repercussão geral (RE-RG 631.389, rel. Min. Marco Aurélio, DJe 3.6.2014), o direito dos servidores inativos a receber a GDPGPE no mesmo patamar que os ativos até o processamento dos resultados da primeira avaliação de desempenho. Tal julgado afastou a possibilidade de retroação dos efeitos da avaliação de desempenho (...). Ante o exposto, conheço do agravo para (...) e reformar o acórdão recorrido, determinando que o autor receba as diferenças entre o que lhe foi pago a título de GDPGPE e o pago aos servidores ativos de seu cargo de referência, até a data de homologação do resultado do primeiro ciclo avaliativo.","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"[ ARE 1.149.783 , rel. min. Gilmar Mendes , dec. monocrática, j. 30-8-2018, DJE 183 de 4-9-2018.]","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"● I - A Gratificação de Desempenho de Atividade de Ciência e Tecnologia (GDACT), instituída pela MP 2.048/2000, apesar de originalmente concebida como gratificação pro labore faciendo , teve caráter geral e foi estendida aos inativos até a sua regulamentação pelo Decreto 3.762/2001, quando passou a constituir gratificação paga em razão do efetivo exercício de cargo; (...)","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"[Tese definida no RE 572.884 , rel. min. Ricardo Lewandowski , P, j. 20-6-2012, DJE 34 de 21-2-2013, Tema 54.]","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"No caso dos autos, aplicam-se, mutatis mutandis , os mesmos fundamentos apresentados acima, uma vez que é manifesta a semelhança da GDAMP com a GDATFA e com a GDATA. De fato, nas aludidas gratificações verifica-se que a partir da data da homologação do resultado das avaliações, a gratificação perde sua natureza geral e adquire o caráter pro labore faciendo , impedindo, portanto, sua extensão aos inativos. (...) Isso posto, dou provimento ao recurso (art. 21, § 2º, do RISTF), para impedir a extensão aos inativos a Gratificação de Desempenho de Atividade Médico-Pericial (GDAPMP), instituída pela Lei 11.907/2009, no mesmo percentual deferido aos servidores em atividade, a partir da data da homologação do resultado das avaliações de desempenho.","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"[ RE 1.019.147 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 6-2-2017, DJE 25 de 9-2-2017.]","deleted":false}],"heading":false},{"page":94,"runs":[{"text":"No caso dos autos, aplicam-se, mutatis mutandis , os mesmos fundamentos apresentados acima, uma vez que é manifesta a semelhança da GDAMP com a GDATFA e com a GDATA. De fato, nas aludidas gratificações verifica-se que, a partir da data da homologação do resultado das avaliações, a gratificação perde sua natureza geral e adquire o caráter pro labore faciendo , impedindo, portanto, sua extensão aos inativos. (...) Por fim, este Supremo Tribunal assentou ser possível a redução na pontuação da Gratificação de Desempenho de Atividade Médico-Pericial GDAMP após a avaliação de desempenho, sem que isso contrarie o princípio da","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"irredutibilidade de vencimentos (...).","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[ ARE 1.009.278 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 25-11-2016, DJE 256 de 1º-12-2016.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"O Supremo Tribunal Federal entende que, após a implementação dos critérios de avaliação de desempenho, não se afigura possível a manutenção, para os servidores inativos, do mesmo percentual das gratificações concedidas aos servidores em atividade.","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[ RE 736.909 AgR , rel. min. Rosa Weber , 1ª T, j. 12-8-2014, DJE 171 de 4-9-2014.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"I - A Gratificação de Desempenho de Atividade de Ciência e Tecnologia (GDACT), instituída pelo art. 19 da MP 2.048-26/2000, de 29 de junho de 2000, por ocasião de sua criação, tinha o caráter de gratificação pessoal, pro labore faciendo , e, por esse motivo, não foi estendida, automaticamente, aos já aposentados e pensionistas. II - O art. 60-A, acrescentado pela Lei 10.769/2003 à MP 2.229-43/2001, estendeu aos inativos a GDACT, no valor correspondente a trinta por cento do percentual máximo aplicado ao padrão da classe em que o servidor estivesse posicionado. III - Dessa forma, não houve redução indevida, pois, como visto, a GDACT é gratificação paga em razão do efetivo exercício do cargo e não havia percentual mínimo assegurado ao servidor em exercício.","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[ RE 572.884 , rel. min. Ricardo Lewandowski , P, j. 20-6-2012, DJE 34 de 21-2-2013.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"É possível a extensão da GDARA aos inativos tendo em vista que a jurisprudência desta Corte tem aplicado às diversas gratificações concedidas no âmbito do serviço público federal o mesmo entendimento que embasou a Súmula Vinculante 20, que trata da Gratificação de Desempenho de Atividade Técnico-Administrativa (GDATA).","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[ RE 630.880 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 22-5-2012, DJE 109 de 5-6-2012.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"● É compatível com a Constituição a extensão, aos servidores públicos inativos, dos critérios de cálculo da Gratificação de Desempenho da Carreira da Previdência, Saúde e Trabalho - GDPST estabelecidos para os servidores públicos em atividade.","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[Tese definida no RE 631.880 RG , rel. min. Cezar Peluso , P, j. 9-6-2011, DJE 167 de 31-8-2011, Tema 409.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"● A fixação da GDATA e da GDASST em relação aos servidores inativos deve obedecer aos critérios a que estão submetidos os servidores em atividade de acordo com a sucessão de leis de regência.","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[Tese definida no RE 597.154 QO-RG , rel. min. Gilmar Mendes , P, j. 19-2-2009, DJE 99 de 29-5-2009, Tema 153.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"Da leitura dos trechos transcritos, verifico que o tribunal reclamado, ao determinar o pagamento da GDATA aos inativos em valor correspondente a 30 pontos, considerando, para tanto, a previsão do artigo 5° da Lei 10.404/2002, após a alteração da sua redação pela Lei 10.971/2004, e não os 10 pontos previstos na sua redação original, desrespeitou o enunciado da Súmula Vinculante 20, que decorreu do entendimento prevalecente do julgamento do RE 476.930, (...). Ademais, como pontuado no parecer ministerial, o período abrangido pelo acórdão reclamado refere-se aos meses de janeiro de 2003 a abril de 2004, o qual é anterior às alterações promovidas pela Lei 10.971/2004 (publicada em 25.11.2004).","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[ Rcl 31.866 , rel. min. Gilmar Mendes , dec. monocrática, j. 4-2-2019, DJE 23 de 6-2-2019.]","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"1. O Supremo Tribunal Federal fixou o entendimento no sentido de que a Gratificação de Desempenho de Atividade Técnico-Administrativa (GDATA) deve ser paga aos inativos no valor de 10 pontos, no período entre junho de 2002 a abril de 2004. Precedentes. 2. Embargos de declaração acolhidos, com excepcional atribuição de efeitos modificativos, reformando o acórdão embargado, a fim de determinar a aplicação de 10 pontos no período entre outubro de 2003 e 30 de abril de 2004, conforme o teor da Súmula Vinculante 20 e a redação do art. 5º, II, da Lei 10.404/2002.","deleted":false}],"heading":false},{"page":95,"runs":[{"text":"[ RE 831.325 AgR-ED , rel. min. Roberto Barroso , 1ª T, j. 23-2-2018, DJE 44 de 8-3-2018.]","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"(...) o Plenário do Supremo Tribunal Federal, no julgamento do RE 476.279/DF, decidiu que os servidores inativos têm direito à percepção da Gratificação de Desempenho de Atividade Técnico-Administrativa (GDATA), na proporção em que ela se caracterizar como geral, nos termos da Lei 10.404/2002.","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"[ RE 612.920 AgR , voto do rel. min. Dias Toffoli , 1ª T, j. 28-2-2012, DJE 64 de 29-3-2012.]","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":96,"runs":[{"text":"Extensão de gratificações de caráter geral aos servidores inativos","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"(...) Aplica-se à espécie vertente a jurisprudência do Supremo Tribunal Federal relativa à extensão aos inativos da Gratificação de Desempenho de Atividade Técnico-Administrativa - GDATA, firmada no julgamento do RE 476.279, Plenário, Rel. Min. Sepúlveda Pertence, (...). Nesse passo, sedimentando a orientação do Supremo Tribunal Federal, foi editada a Súmula Vinculante 20, (...). Assim, ante a similaridade entre a gratificação sub examine e a GDATA e a jurisprudência sedimentada nesta Corte, não há óbice à extensão da GDACE aos servidores públicos inativos, no período em que não regulamentados os critérios e procedimentos específicos para avaliação de desempenho pessoal dos servidores da ativa.","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"[ RE 1.178.387 , rel. min. Luiz Fux , dec. monocrática, j. 19-12-2018, DJE 19 de 1º-2-2019.]","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"O entendimento adotado no acórdão recorrido não diverge da jurisprudência firmada no âmbito deste Supremo Tribunal Federal no sentido de que as vantagens de caráter geral, concedidas aos servidores da ativa, são extensíveis aos inativos e pensionistas, conforme disposto no art. 40, § 8º, da CF/1988.","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"[ RE 752.493 AgR , rel. min. Rosa Weber , 1ª T, j. 12-8-2014, DJE 165 de 27-8-2014.]","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"O STF firmou entendimento no sentido de que se deve estender aos inativos gratificação de natureza geral paga de maneira indistinta a todos os servidores em atividade.","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"[ AR 1.688 AgR , rel. min. Ricardo Lewandowski , P, j. 14-5-2014, DJE 108 de 5-6-2014.]","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"Ambas as Turmas desta Corte têm entendido que vantagens concedidas de forma geral aos servidores militares da ativa devem ser estendidas aos inativos e seus pensionistas.","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"[ RE 418.379 AgR , rel. min. Joaquim Barbosa , 2ª T, j. 5-6-2012, DJE 122 de 22-6-2012.]","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"Extensão a inativos com direito à paridade de funções comissionadas originadas de reestruturação ocorrida após aposentadoria","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"Em suma, os autores desejam que as funções comissionadas criadas em 2001 - com efeitos financeiros a contar de 3.2002 - (Lei 2.387, de 26 de dezembro de 2001, do Estado de Mato Grosso do Sul, com as alterações posteriores produzidas pelas Leis 2.964/2004 e 3.146/2005), as quais são posteriores às suas aposentadorias - fossem pagas em seus contracheques como decorrência da paridade assegurada pelo 40, § 8º, da Constituição Federal, com redação anterior à EC 41/2003, bem como os arts. 6º e 7º da EC 41/2003 e o art. 2º da EC 47/2005. (...) ainda que os requerentes estivessem na ativa, no momento da entrada em vigor da reestruturação operada pela Lei 2.387/2001, não teriam direito à percepção da incorporação da DAI-3 ou DAI-4 nos percentuais e base de cálculo das funções criadas pela novel legislação estadual. Tal situação difere substancialmente das teses fixadas nos processos paradigmas dos temas 139 e 156, os quais se referem ao direito dos inativos de perceberem as gratificações concedidas aos ativos em caráter geral (ou seja, sem correlação com atividade específica). (...) A interpretação conferida pelos autores não encontra guarida no art. 40, § 8º, da Constituição Federal, com redação anterior à EC 41/2003, bem como nos arts. 6º e 7º da EC 41/2003 e art. 2º da EC 47/2005, estando rechaçada na jurisprudência desta Corte a extensão aos inativos, que possuem direito à paridade, da reestruturação - com criação de novas - das funções comissionadas concedidas aos servidores ativos após suas aposentadorias, por se tratarem de contraprestação específica (e não geral).","deleted":false}],"heading":false},{"page":96,"runs":[{"text":"[ AR 2.627 , rel. min. Gilmar Mendes , dec. monocrática, j. 1º-2-2019, DJE 24 de 7-2-2019.]","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":97,"runs":[{"text":"● Vide Súmula Vinculante 34.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 54, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 153, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"● Tese de 1Repercussão Geral definida no Tema 351, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 409, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"Data de publicação do enunciado: DJE de 10-11-2009.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":97,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"21","number":"21","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":98,"endPage":101,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1255","paragraphs":[{"page":98,"runs":[{"text":"É inconstitucional a exigência de depósito ou arrolamento prévios de dinheiro ou bens para admissibilidade de recurso administrativo.","deleted":false}]}],"notes":[{"page":98,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":98,"runs":[{"text":"A exigência de depósito ou arrolamento prévio de bens e direitos como condição de admissibilidade de recurso administrativo constitui obstáculo sério (e intransponível, para consideráveis parcelas da população) ao exercício do direito de petição (CF/1988, art. 5º, XXXIV), além de caracterizar ofensa ao princípio do contraditório (CF/1988, art. 5º, LV). A exigência de depósito ou arrolamento prévio de bens e direitos pode converter-se, na prática, em determinadas situações, em supressão do direito de recorrer, constituindo-se, assim, em nítida violação ao princípio da proporcionalidade.","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"[ ADI 1.976 , rel. min. Joaquim Barbosa , P, j. 28-3-2007, DJE 18 de 18-5-2007.]","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":98,"runs":[{"text":"● É inconstitucional a exigência de depósito prévio como requisito de admissibilidade de recurso administrativo.","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"[Tese definida no AI 698.626 QO-RG , rel. min. Ellen Gracie , P, j. 2-10-2008, DJE 232 de 5-12-2008, Tema 314.]","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"A decisão deste Tribunal com efeito vinculante que, segundo a reclamante, teria sido descumprida é a Súmula Vinculante 21 (...). No caso, verifico que a autoridade reclamada determinou o processamento dos recursos administrativos, anteriormente obstados em razão da ausência do depósito recursal. O CARF então julgou os recursos voluntários da contribuinte ora reclamante, (...), dando-lhes parcial provimento. (...) Assim, admitidos e julgados os recursos administrativos sem a exigência de depósito, não há falar em afronta à Súmula 21/STF. Ademais, a alegação de desvio de finalidade no Parecer 891/2010, alterado pelo Parecer 1973/2010, deixando de observar a decadência, é matéria que não possui aderência estrita com o entendimento consubstanciado na Súmula Vinculante 21, fato que acarreta a inadmissibilidade da ação, por ausência de pressuposto de cabimento necessário.","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"[ Rcl 33.655 , rel. min. Gilmar Mendes , dec. monocrática, j. 18-3-2019, DJE 54 de 20-3-2019.]","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"Verifica-se que o Plenário desta Suprema Corte, ao apreciar questão de ordem nos autos do AI 698.626, Rel. Min. Ellen Gracie, DJe de 5/12/2008, com repercussão geral reconhecida, Tema 314, ratificou o entendimento firmado por esta Corte no sentido de que é inconstitucional a exigência de depósito prévio como requisito de admissibilidade de recurso administrativo. (...) Saliente-se, ainda, que não houve modulação dos efeitos da decisão proferida pelo Plenário do Supremo Tribunal Federal nos autos do AI 698.626, que ratificou a jurisprudência desta Corte a respeito da matéria. Assevere-se, por fim, que esse entendimento se consolidou na Súmula Vinculante 21, (...). In casu , conclui-se que o acórdão recorrido divergiu dessa orientação. Ex positis , PROVEJO o recurso extraordinário, com fundamento no disposto no artigo 932, V, do CPC/2015, para o fim específico de declarar a nulidade da exigência de depósito prévio como requisito de admissibilidade do recurso administrativo em questão.","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"[ RE 1.101.605 , rel. min. Luiz Fux , dec. monocrática, j. 22-5-2018, DJE 102 de 25-5-2018.]","deleted":false}],"heading":false},{"page":98,"runs":[{"text":"O agravo deve ser provido. Nota-se que o presente recurso extraordinário versa sobre a inconstitucionalidade da nova redação conferida ao art. 250 do DL 5/1975, a qual condicionou a admissibilidade do recurso","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"administrativo ao depósito de, no mínimo, 50% (cinquenta por cento) da exigência fiscal definida na decisão. 2. Trata-se de determinação eivada de inconstitucionalidade, tal como constatou o Plenário do Supremo Tribunal Federal nos autos do AI 398.933 AgR, julgado sob relatoria do ministro Sepúlveda Pertence. (...) 3. Na oportunidade, concluiu-se que o recurso administrativo é um desdobramento do direito de petição, razão pela qual a ele deve ser assegurada a garantia prevista no art. 5º, XXXIV, da CF/1988. Ademais, afirmou-se que, por configurar patente supressão do direito de recorrer, a medida denota nítida afronta aos princípios da proporcionalidade e do contraditório. 4. Saliente-se, por fim, que referido entendimento foi ratificado pela edição da Súmula Vinculante 21 (...).","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"[ AI 428.249 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 9-4-2014, DJE 94 de 19-5-2014.]","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":99,"runs":[{"text":"Aplica-se a Súmula Vinculante 21 ainda que o recurso interposto seja anterior à sua publicação","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"A alegação de que o decisum reclamado limitou-se a analisar questão processual atinente ao âmbito de cognição da exceção de pré-executividade não merece acolhida. Isso porque o ato reclamado, sob o fundamento de que a decisão que exigiu o depósito prévio para efeito de interposição de recurso extrajudicial é anterior à mudança da orientação jurisprudencial desta Corte sobre a matéria, não reconheceu a inconstitucionalidade da exigência em questão, em nítido confronto ao entendimento deste Tribunal (...). Verifica-se, pois, que, diversamente do alegado pela agravante, o juízo reclamado não se limitou a analisar o cabimento da exceção de pré-executividade, mas deixou de aplicar orientação deste Tribunal que possui caráter vinculante. De se anotar, ainda, que já decidiu esta Corte que a “circunstância de o recurso ser interposto antes da edição do enunciado com força vinculante por este Tribunal não tem o condão de afastar a inconstitucionalidade da exigência de depósito prévio para interposição de apelos administrativos” (Rcl 10.938/PE, rel. min. Gilmar Mendes). Vale ressaltar, ademais, que a decisão reclamada não é a proferida no processo administrativo, mas aquela exarada pelo Juízo da Vara Federal de Colatina/ES, em momento posterior à edição da Súmula Vinculante 21. Desse modo, tenho que não merece reparos a decisão que se baseou na jurisprudência desta Corte no sentido da inconstitucionalidade da exigência de depósito prévio, consolidada na Súmula Vinculante 21 (...).","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"[ Rcl 22.546 AgR , voto do rel. min. Luiz Fux , 1ª T, j. 23-2-2016, DJE 47 de 14-3-2016.]","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"A Súmula Vinculante 21 foi manifestamente afrontada pela decisão reclamada. (...) O objetivo da Súmula Vinculante 21 é extinguir a exigência de depósito como requisito de admissibilidade de recursos administrativos (...). A circunstância de o recurso ser interposto antes da edição do enunciado com força vinculante por este Tribunal não tem o condão de afastar a inconstitucionalidade da exigência de depósito prévio para interposição de apelos administrativos. Ademais, a decisão reclamada é a que foi proferida pelo juiz de direito da 2ª Vara da Fazenda Pública da Comarca de Jaboatão dos Guararapes/PE contrariamente ao entendimento deste Supremo Tribunal Federal. Registro que referida decisão é posterior à edição da Súmula Vinculante 21. Ante o exposto, com base na jurisprudência pacífica da Corte, conheço da reclamação e julgo-a procedente, para cassar a decisão reclamada e determinar que outra seja proferida em seu lugar, de acordo com a Súmula Vinculante 21 (art. 161, parágrafo único, RISTF).","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"[ Rcl 10.938 , rel. min. Gilmar Mendes , dec. monocrática, j. 4-3-2011, DJE 53 de 22-3-2011.]","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"Comprovação de interposição de recurso administrativo e ausência de aderência estrita à Súmula Vinculante 21","deleted":false}],"heading":false},{"page":99,"runs":[{"text":"(...) a decisão objeto da presente reclamação não se manifestou sobre o mérito da atuação de autoridade tributária ao lavrar os Autos de Infração (...), tampouco sobre eventual exigência de depósito prévio em recurso interposto em processos administrativos decorrentes desses atos, limitando-se a afirmar a inadequação do instrumento eleito pela exequente, nos autos em referência (ora agravante), para questioná-los em sede judicial, porquanto incompatível a dilação probatória em sede de petição de exceção de pré-executividade. Não","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"há, portanto, aderência do objeto reclamado (entendimento sobre aspecto formal da admissibilidade da exceção de pré-executividade) ao conteúdo da Súmula Vinculante 21, (...). A SV 21 deriva de reiterada jurisprudência do STF no sentido de declarar a inconstitucionalidade de leis ou atos normativos que estabeleçam a necessidade de depósito prévio para que o cidadão possa apresentar seu recurso administrativo, não se relacionando com a pretensão de “nulidade do título executivo” (...).","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"[ Rcl 26.148 AgR , rel. min. Dias Toffoli , 2ª T, j. 21-8-2018, DJE 221 de 17-10-2018.]","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"Depósito prévio em processo judicial e ausência de identidade com a Súmula Vinculante 21","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"Bem examinados os autos, constato que esta reclamação é manifestamente incabível, o que impõe a imediata extinção do feito. Com efeito, a reclamante alega que foi violada a Súmula Vinculante 21 (...). Como se observa, a referida súmula refere-se, expressamente, à impossibilidade de exigência de depósito prévio para a admissibilidade de recurso administrativo, entendimento que não é extensível, como pretende a reclamante, aos processos judiciais. Além disso, não cabe analogia na interpretação dos verbetes de súmulas vinculantes. Assim, diante da ausência de identidade material entre os fundamentos do ato reclamado e aqueles emanados da súmula vinculante ora invocada, não merece seguimento a pretensão da reclamante.","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"[ Rcl 11.750 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 11-4-2012, DJE 72 de 13-4-2012.]","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"Incabível exigência de recolhimento prévio de multa para a admissibilidade de recurso administrativo na esfera trabalhista","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"Incompatibilidade da exigência de depósito prévio do valor correspondente à multa como condição de admissibilidade de recurso administrativo interposto junto à autoridade trabalhista (§ 1º do art. 636 da Consolidação das Leis do Trabalho) com a CF/1988. Inobservância das garantias constitucionais do devido processo legal e da ampla defesa (art. 5º, LIV e LV); do princípio da isonomia (art. 5º, caput ); do direito de petição (art. 5º, XXXIV, a). (...) Súmula Vinculante 21. 2. Ação julgada procedente para declarar a não recepção do § 1º do art. 636 da Consolidação das Leis do Trabalho pela Constituição da República de 1988.","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"[ ADPF 156 , rel. min. Cármen Lúcia , P, j. 18-8-2011, DJE 208 de 28-10-2011.]","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"Multa do art. 557, § 2º, do CPC/1973","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"A Súmula Vinculante 21 do STF não tem a necessária relação de pertinência estrita com acórdão proferido em processo judicial que aplica a multa prevista no art. 557, § 2º, do CPC/1973, com a condicionante legal do pagamento da referida multa para a interposição de outros recursos.","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"[ Rcl 11.750 AgR , rel. min. Edson Fachin , 1ª T, j. 15-9-2015, DJE 195 de 30-9-2015.]","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"Taxas e custas processuais e ausência de identidade com a Súmula Vinculante 21","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"A exigência de recolhimento de taxas ou emolumentos para a interposição de recurso administrativo é matéria que não possui aderência estrita com o entendimento consubstanciado na Súmula Vinculante 21 (...).","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"[ Rcl 50.859 AgR , rel. min. Alexandre de Moraes , 1ª T, j. 14-2-2022, DJE 32 de 18-2-2022.]","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"No caso, a autoridade reclamada deixou de conhecer do recurso administrativo interposto, em razão da ausência de recolhimento da taxa de expediente. (...). Da leitura da decisão, verifica-se que a autoridade reclamada limitou-se a exigir o preparo do recurso administrativo interposto, não havendo, pois, a imposição de depósito ou arrolamento prévios de dinheiro ou bens, na forma combatida pela Súmula Vinculante 21. Ora, a exigência de recolhimento de taxas ou emolumentos para a interposição de recurso administrativo é matéria que não possui aderência estrita com o entendimento consubstanciado na Súmula Vinculante 21, fato que acarreta a inadmissibilidade da ação, por ausência de pressuposto de cabimento necessário.","deleted":false}],"heading":false},{"page":100,"runs":[{"text":"[ Rcl 39.710 , rel. min. Gilmar Mendes , dec. monocrática, j. 30-7-2020, DJE 196 de 6-8-2020]","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"Como se observa, a Súmula Vinculante 21 refere-se, em sua literalidade, à impossibilidade de exigência de depósito ou arrolamento prévios de dinheiro ou bens como requisito de admissibilidade de recurso administrativo, entendimento que não é extensível, como pretende o reclamante, ao pagamento de taxas e de custas processuais.","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"[ Rcl 36.581 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 30-8-2019, DJE 192 de 4-9-2019.]","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"É imprópria a irresignação uma vez evidenciada a ausência de identidade material entre o ato atacado e o paradigma. Não está em jogo a exigência de depósito ou arrolamento de dinheiro ou bens como requisito de admissibilidade de recurso administrativo. Faz-se em discussão - certo ou errado, descabe perquirir - a pertinência do pagamento de custas, situação não alcançada pelo paradigma.","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"[ Rcl 29.648 , rel. min. Marco Aurélio , dec. monocrática, j. 29-8-2018, DJE 187 de 6-9-2018.]","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":101,"runs":[{"text":"● Vide Súmula Vinculante 28.","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"● Tema 679 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"Data de publicação do enunciado: DJE de 10-11-2009.","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":101,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"22","number":"22","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":102,"endPage":105,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1259","paragraphs":[{"page":102,"runs":[{"text":"A Justiça do Trabalho é competente para processar e julgar as ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive aquelas que ainda não possuíam sentença de mérito em primeiro grau quando da promulgação da Emenda Constitucional 45/2004.","deleted":false}]}],"notes":[{"page":102,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":102,"runs":[{"text":"Numa primeira interpretação do inciso I do art. 109 da Carta de Outubro, o Supremo Tribunal Federal entendeu que as ações de indenização por danos morais e patrimoniais decorrentes de acidente do trabalho, ainda que movidas pelo empregado contra seu (ex-)empregador, eram da competência da Justiça comum dos Estados-membros. 2. Revisando a matéria, porém, o Plenário concluiu que a Lei Republicana de 1988 conferiu tal competência à Justiça do Trabalho. Seja porque o art. 114, já em sua redação originária, assim deixava transparecer, seja porque aquela primeira interpretação do mencionado inciso I do art. 109 estava, em boa verdade, influenciada pela jurisprudência que se firmou na Corte sob a égide das Constituições anteriores. 3. Nada obstante, como imperativo de política judiciária - haja vista o significativo número de ações que já tramitaram e ainda tramitam nas instâncias ordinárias, bem como o relevante interesse social em causa -, o Plenário decidiu, por maioria, que o marco temporal da competência da Justiça trabalhista é o advento da EC 45/2004. Emenda que explicitou a competência da Justiça Laboral na matéria em apreço. 4. A nova orientação alcança os processos em trâmite pela Justiça comum estadual, desde que pendentes de julgamento de mérito. É dizer: as ações que tramitam perante a Justiça comum dos Estados, com sentença de mérito anterior à promulgação da EC 45/2004, lá continuam até o trânsito em julgado e correspondente execução. Quanto àquelas cujo mérito ainda não foi apreciado, hão de ser remetidas à Justiça do Trabalho, no estado em que se encontram, com total aproveitamento dos atos praticados até então. A medida se impõe, em razão das características que distinguem a Justiça comum estadual e a Justiça do Trabalho, cujos sistemas recursais, órgãos e instâncias não guardam exata correlação.","deleted":false}],"heading":false},{"page":102,"runs":[{"text":"[ CC 7.204 , rel. min. Ayres Britto , P, j. 29-6-2005, DJ de 9-12-2005.]","deleted":false}],"heading":false},{"page":102,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":102,"runs":[{"text":"● Compete à Justiça do Trabalho processar e julgar as ações de indenização por danos morais e patrimoniais decorrentes de acidentes de trabalho propostas por empregado contra empregador, inclusive as propostas pelos sucessores do trabalhador falecido, salvo quando a sentença de mérito for anterior à promulgação da EC 45/2004, hipótese em que, até o trânsito em julgado e a sua execução, a competência continuará a ser da Justiça Comum.","deleted":false}],"heading":false},{"page":102,"runs":[{"text":"[Tese definida no RE 600.091 , rel. min. Dias Toffoli , P, j. 25-5-2011, DJE 155 de 15-8-2011, Tema 242.]","deleted":false}],"heading":false},{"page":102,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":102,"runs":[{"text":"Ausência de repercussão geral sobre o prazo prescricional relativo às ações de indenização por danos morais e materiais decorrentes de acidente de trabalho antes do advento da EC 45/2004","deleted":false}],"heading":false},{"page":102,"runs":[{"text":"O Supremo Tribunal Federal firmou entendimento no sentido da competência da Justiça do Trabalho para julgar ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive aquelas nas quais, ao tempo da edição da EC 45/2004, ainda não havia sido proferida sentença de mérito em primeiro grau (Súmula Vinculante 22). O Plenário desta Corte","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"manifestou-se pela ausência de repercussão geral da controvérsia acerca do prazo prescricional relativo às ações de indenização por danos morais e materiais decorrentes de acidente de trabalho antes do advento da EC 45/2004 (ARE 650.932, rel. min. Ricardo Lewandowski - Tema 637).","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"[ AI 744.033 AgR , rel. min. Roberto Barroso , 1ª T, j. 11-3-2014, DJE 70 de 9-4-2014.]","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"A questão presente nestes autos refere-se à discussão sobre o prazo prescricional a ser aplicado às ações de reparação de danos decorrentes de acidente de trabalho, ante o advento da EC 45/2004. Conforme se infere da delimitação temática destes autos, não se está perante debate de feição constitucional. Com efeito, a controvérsia sob exame restringe-se, exclusivamente, à interpretação conferida pela Corte de origem à legislação infraconstitucional em análise. (...) Ressalto que este Tribunal tem afirmado, de forma reiterada, a adstrição do tema sob análise à esfera unicamente infraconstitucional. (...) Constatada a ausência de questão constitucional, impõe-se o reconhecimento da inexistência, na espécie, de elemento conceitual da própria repercussão geral a revelar a ausência do requisito, com os consectários dos arts. 543-A, § 5º, e 543-B, § 2º, do Código de Processo Civil.","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"[ ARE 650.932 RG , voto do rel. min. Ricardo Lewandowski , P, j. 21-3-2013, DJE 62 de 5-4-2013, Tema 637.]","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"Competência da Justiça comum estadual para julgar ações regressivas propostas pelo INSS contra empregador, com fundamento no art. 120 da Lei 8.213/1991","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"A teor da Súmula Vinculante 22: “A Justiça do Trabalho é competente para processar e julgar as ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive aquelas que ainda não possuíam sentença de mérito em primeiro grau quando da promulgação da Emenda Constitucional 45/2004”. Na espécie, trata-se de ação regressiva proposta pelo Instituto Nacional do Seguro Social (INSS), contra o empregador, para obter o ressarcimento de despesas tidas com o pagamento de pensão por morte de segurado, com fundamento no art. 120 da Lei 8.213/1991, de modo que a matéria não se insere na esfera de competência da Justiça Laboral, razão pela qual não se divisa a alegada ofensa aos dispositivos constitucionais suscitados.","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"[ RE 704.508 , rel. min. Rosa Weber , dec. monocrática, j. 5-12-2014, DJE 245 de 15-12-2014.]","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"Competência da Justiça do Trabalho em ação de indenização decorrente de acidente de trabalho","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"O recurso deve ser provido. O acórdão recorrido dissentiu do entendimento firmado pelo Supremo Tribunal Federal, no julgamento do CC 7.204, Rel. Min. Ayres Britto. Na oportunidade, o Plenário, ao afirmar a competência da Justiça do Trabalho para julgar ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho, excluiu aquelas nas quais já havia sido proferida sentença de mérito em primeiro grau, anteriormente à edição da Emenda Constitucional 45/2004. Veja-se, nesse sentido, a redação da Súmula Vinculante 22 (...).","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"[ RE 1.161.249 , rel. min. Roberto Barroso , dec. monocrática, j. 23-10-2018, DJE 230 de 29-10-2018.]","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"CONSTITUCIONAL E PROCESSUAL CIVIL. AGRAVO REGIMENTAL NOS EMBARGOS DE DECLARAÇÃO NA RECLAMAÇÃO. ALEGADA VIOLAÇÃO À SÚMULA VINCULANTE 22. NÃO OCORRÊNCIA. AUSÊNCIA DE SENTENÇA DE MÉRITO QUANDO DA PROMULGAÇÃO DA EC 45/2004. CORRETA A REMESSA DOS AUTOS À JUSTIÇA DO TRABALHO. AGRAVO REGIMENTAL A QUE SE NEGA PROVIMENTO.","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"[ Rcl 17.903 ED-AgR , rel. min. Alexandre de Moraes , 1ª T, j. 11-9-2017, DJE 214 de 21-9-2017.","deleted":false}],"heading":false},{"page":103,"runs":[{"text":"O Supremo Tribunal Federal já firmou entendimento no sentido da competência da Justiça do Trabalho para julgar ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive aquelas nas quais, ao tempo da edição da EC 45/2004, ainda não havia sido proferida sentença de mérito em primeiro grau como ocorre no presente processo. (...) O acórdão recorrido decidiu a matéria de maneira diversa do que determinado pelo Supremo Tribunal Federal na Súmula Vinculante 22, mas prequestionou a matéria ao afastar a competência da Justiça do Trabalho. (...) Diante do","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"exposto, com base no art. 21, § 2º, do RISTF, dou parcial provimento ao recurso para julgar incompetente a Justiça comum, e, com fundamento no art. 64, § 2º, do CPC e na Súmula Vinculante 22, determino a remessa dos autos à Justiça do Trabalho.","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"[ RE 485.842 , rel. min. Roberto Barroso , dec. monocrática, j. 28-9-2016, DJE 211 de 4-10-2016.]","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"Compete à Justiça do Trabalho processar e julgar as ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive naquelas em que, ao tempo da edição da EC 45/2004, ainda não havia sido proferida sentença de mérito em primeiro grau.","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"[ ARE 656.673 AgR , rel. min. Roberto Barroso , 1ª T, j. 25-3-2014, DJE 109 de 6-6-2014.]","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"Manutenção da competência da Justiça comum estadual para ação com sentença de mérito proferida antes da EC 45/2004, inclusive para a que envolve representação interna de entidade sindical","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"Desse modo, ao declarar competente a Justiça do Trabalho para o julgamento da ação, na qual foi proferida sentença de mérito no dia 3/12/2004, ou seja, antes da promulgação da EC 45/2004, o órgão judiciário reclamado ofendeu ao teor da Súmula Vinculante 22. (...) Isso posto, julgo procedente esta reclamação constitucional para cassar a decisão proferida pelo Tribunal Superior do Trabalho, nos autos do processo (...), e reconhecer a competência da justiça comum estadual do Estado da Bahia, para o julgamento do feito.","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"[ Rcl 26.565 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 26-6-2018, DJE 129 de 29-6-2018.]","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"Com efeito, a decisão atacada, conforme alegado, destoa do comando exarado pela súmula vinculante 22. Assim, ao analisar o recurso de revista supratranscrito, o TST desrespeitou o julgado no CC 7.204/MG, de relatoria Ministro Ayres Britto, o qual assentou que “as ações que tramitam perante a Justiça comum dos Estados, com sentença de mérito anterior à promulgação da EC 45/2004, lá continuam até o trânsito em julgado e correspondente execução”. (...) Desse modo, ao declarar competente a Justiça do Trabalho para o julgamento da ação, na qual foi proferida sentença de mérito no dia 3/12/2004, ou seja, antes da promulgação da EC 45/2004, o órgão judiciário reclamado ofendeu ao teor da Súmula Vinculante 22. (...) Isso posto, julgo procedente esta reclamação constitucional para cassar a decisão proferida pelo Tribunal Superior do Trabalho, nos autos do processo (...), e reconhecer a competência da justiça comum estadual do Estado da Bahia, para o julgamento do feito.","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"[ Rcl 26.565 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 26-6-2018, DJE 129 de 29-6-2018.]","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"Com efeito, decidiu-se que os processos com o mérito apreciado antes da promulgação da EC 45/2004 deveriam continuar tramitando na Justiça comum estadual, enquanto que os demais teriam de ser encaminhados à Justiça Trabalhista. No caso, não está configurada contrariedade à Súmula Vinculante 22, tendo em vista que o ato reclamado, ao deliberar pela remessa dos autos à Justiça Trabalhista, levou em conta a ausência de sentença de mérito quando da promulgação da EC 45/2004, circunstância que deve presidir a solução da presente controvérsia.","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"[ Rcl 17.903 ED , rel. min. Teori Zavascki , dec. monocrática, j. 22-8-2016, DJE 180 de 25-8-2016.]","deleted":false}],"heading":false},{"page":104,"runs":[{"text":"O recurso extraordinário é inadmissível. Inicialmente, observo que o Supremo Tribunal Federal já firmou entendimento no sentido da competência da Justiça do Trabalho para julgar ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho propostas por empregado contra empregador, inclusive aquelas nas quais, ao tempo da edição da EC 45/2004, ainda não havia sido proferida sentença de mérito em primeiro grau (Súmula Vinculante 22). Na hipótese dos autos, o Tribunal de origem assentou, peremptoriamente, que já foi proferida sentença de mérito na Justiça comum, antes do advento da EC 45/2004. Desse modo, em consonância com a orientação do Supremo Tribunal Federal, a presente ação deve continuar na Justiça comum até o trânsito em julgado e correspondente execução. (...) Cabe ressaltar, por oportuno, que o mencionado entendimento aplica-se também às controvérsias que envolvem a representação interna das entidades sindicais.","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"[ ARE 955.717 AgR , rel. min. Roberto Barroso , dec. monocrática, j. 10-6-2016, DJE 139 de 1º-8-2016.]","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"Com a promulgação da EC 45/2004, ampliou-se, de modo expressivo, a competência da Justiça do Trabalho, em cujas atribuições jurisdicionais inclui-se, agora, o poder para processar e julgar a controvérsia pertinente à representação interna de entidades sindicais (sindicatos, federações e confederações). Em decorrência dessa reforma constitucional, cessou a competência da Justiça comum do Estado-membro para processar e julgar as causas referentes aos litígios envolvendo dirigente sindical e a própria entidade que ele representa em matérias referentes a questões estatutárias. Doutrina. Precedentes (STF e STJ). Inocorrência, na espécie, da situação excepcional - prolação de sentença de mérito, pela Justiça estadual, em momento anterior ao marco temporal definido no julgamento plenário do CC 7.204/MG, rel. min. Ayres Britto (data da promulgação da EC 45/2004) - que, presente, justificaria o reconhecimento da competência (residual) do Poder Judiciário do Estado-membro para o processo e julgamento da causa. Consequente inaplicabilidade, ao caso, da ressalva feita no precedente referido.","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"[ ARE 681.641 AgR , rel. min. Celso de Mello , 2ª T, j. 5-3-2013, DJE 53 de 20-3-2013.]","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":105,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 242, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"● Tema 637 de Repercussão Geral (não reconhecida).","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"Data de publicação do enunciado: DJE de 11-12-2009.","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":105,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"23","number":"23","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":106,"endPage":108,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1262","paragraphs":[{"page":106,"runs":[{"text":"A Justiça do Trabalho é competente para processar e julgar ação possessória ajuizada em decorrência do exercício do direito de greve pelos trabalhadores da iniciativa privada.","deleted":false}]}],"notes":[{"page":106,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":106,"runs":[{"text":"“A determinação da competência da Justiça do Trabalho não importa que dependa a solução da lide de questões de direito civil” (CJ 6.959), bastando que a questão submetida à apreciação judicial decorra da relação de emprego. 2. Ação de interdito proibitório cuja causa de pedir decorre de movimento grevista, ainda que de forma preventiva. 3. O exercício do direito de greve respeita a relação de emprego, pelo que a EC 45/2003 incluiu, expressamente, na competência da Justiça do Trabalho conhecer e julgar as ações dele decorrentes (art. 114, II, da Constituição da República). 4. Recurso extraordinário conhecido e provido para fixar a competência da Justiça do Trabalho.","deleted":false}],"heading":false},{"page":106,"runs":[{"text":"[ RE 579.648 , rel. min. Menezes Direito , red. p/ o ac. min. Cármen Lúcia , j. 10-9-2008, DJE 43 de 6-3-2009.]","deleted":false}],"heading":false},{"page":106,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":106,"runs":[{"text":"● Compete à Justiça do Trabalho o julgamento das ações de interdito proibitório em que se busca garantir o livre acesso de funcionários e de clientes às agências bancárias interditadas em decorrência de movimento grevista.","deleted":false}],"heading":false},{"page":106,"runs":[{"text":"[Tese definida no RE 579.648 , rel. min. Menezes Direito , red. p/ o ac. min. Cármen Lúcia , P, j. 10-9-2008, DJE 43 de 6-3-2009, Tema 74.]","deleted":false}],"heading":false},{"page":106,"runs":[{"text":"A jurisprudência desta Corte firmou-se no sentido de que é competente a Justiça do Trabalho para processar e julgar as causas que envolvam ações possessórias ajuizadas em razão do exercício do direito de greve pelos trabalhadores da iniciativa privada. (...) Verificar-se, pois, que a decisão ora reclamada, ao “proibir o Sindicato réu de promover qualquer ato exercitado por meio de carros de som e alto falantes, que obste a regular prestação de serviços de vigilância na sede da empresa autora e em sua extensão”, afrontou o que prescrito pelo verbete sumular em questão, tendo em vista cuidar-se de questão referente à manutenção de posse, pleiteada através de interdito proibitório, onde se pretende evitar obstrução de acesso dos trabalhadores à empresa, decorrente de manifestações grevistas. Ante o exposto, julgo procedente o pedido da presente reclamação, com prejuízo da liminar, nos termos do art. 161, parágrafo único, do RISTF, para assentar a incompetência absoluta da Justiça Comum ao julgar a demanda, a fim de cassar todas as decisões proferidas no referido processo e estabelecer a competência da Justiça do Trabalho para o seu julgamento.","deleted":false}],"heading":false},{"page":106,"runs":[{"text":"[ Rcl 24.353 , rel. min. Edson Fachin , dec. monocrática, j. 30-1-2018, DJE 22 de 7-2-2018.]","deleted":false}],"heading":false},{"page":106,"runs":[{"text":"Entendo que a situação dos autos contraria o enunciado da Súmula Vinculante 23, que determina ser de competência da Justiça do Trabalho o processo e julgamento de ação possessória ajuizada em decorrência do exercício do direito de greve. (...) O presente caso se amolda ao precedente que deu origem à edição da Súmula Vinculante 23, uma vez que a decisão reclamada foi proferida em sede de interdito proibitório ajuizado com o objetivo de limitar o exercício do direito de greve, de modo que a atuação do Sindicato dos Empregados em Estabelecimentos Bancários de São Paulo, Osasco e Região e os movimentos por ele propostos não impeçam o livre funcionamento das empresas interessadas e o acesso de colaboradores, clientes e usuários às suas dependências. (...) Ante o exposto, julgo procedente a reclamação para cassar a decisão da 3ª Vara Cível - Foro Central da Capital de São Paulo, a qual deferiu a liminar nos autos do processo (...), bem como eventuais decisões posteriores, e fixar a competência da Justiça do Trabalho para processar e julgar a","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"respectiva causa.","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"[ Rcl 10.411 , rel. min. Dias Toffoli , dec. monocrática, j. 16-4-2013, DJE 81 de 2-5-2013.]","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"O Plenário desta Corte, no julgamento do RE 579.648/MG, após reconhecer a repercussão geral do tema, concluiu pela competência da Justiça do Trabalho para apreciar e julgar ação de interdito proibitório em que se busca garantir o livre acesso de funcionários e de clientes a agências bancárias. 2. Agravo regimental não provido.","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"[ RE 491.780 AgR , rel. min. Dias Toffoli , 1ª T, j. 4-10-2011, DJE 215 de 11-11-2011.]","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"O acórdão recorrido divergiu da orientação firmada pelo Supremo Tribunal Federal e expressa na Súmula Vinculante 23 ( DJE de 11-12-2009 e DOU de 11- 12-2009): (...) dou provimento ao agravo e o converto em recurso extraordinário, para dele conhecer e dar-lhe provimento para anular as decisões proferidas e fixar a competência da Justiça do Trabalho para o julgamento da lide.","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"[ AI 638.775 , rel. min. Joaquim Barbosa , dec. monocrática, j. 23-5-2011, DJE 105 de 2-6-2011.]","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":107,"runs":[{"text":"Justiça do Trabalho e ação de interdito proibitório","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"(...) verifica-se que, conforme expressamente assentado na decisão recorrida, os atos de turbação decorreram de manifestação de natureza grevista, a atrair, portanto, a competência da Justiça do Trabalho para o processo e julgamento da demanda, consoante entendimento pacificado pela Súmula Vinculante 23. Sobreleva anotar que para se divergir da afirmação do Tribunal a quo , de haver a turbação decorrido de ato de natureza grevista, far-se-ia necessário o reexame do conjunto fático-probatório dos autos, o que não se apresenta possível nesta seara, ante o óbice erigido pela Súmula 279 desta Suprema Corte. Ex positis , RECONSIDERO a decisão agravada, julgo PREJUDICADO o agravo interno e PROVEJO o recurso extraordinário, para declarar a competência material da Justiça do Trabalho para o processo e julgamento da demanda e determinar a remessa do feito ao órgão jurisdicional competente daquela justiça especializada.","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"[ RE 924.392 , rel. min. Luiz Fux , dec. monocrática, j. 23-10-2018, DJE 228 de 26-10-2018.]","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"Esta Corte, ao editar a Súmula 23, fixou o entendimento no sentido de que é competente a Justiça do Trabalho para processar e julgar as causas que envolvam ações possessórias ajuizadas em razão do exercício do direito de greve pelos trabalhadores da iniciativa privada. O Juízo ora reclamado deferiu a liminar para “proibir o Sindicato réu de promover qualquer ato exercitado por meio de carros de som e alto falantes, que obste a regular prestação de serviços de vigilância na sede da empresa autora e em sua extensão”. A decisão aparenta, pois, ter afrontado o que prescrito pelo verbete sumular, haja vista cuidar-se de questão referente à manutenção de posse, pleiteada através de interdito proibitório, onde se pretende evitar obstrução de acesso dos trabalhadores à empresa, decorrente de manifestações grevistas.","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"[ Rcl 24.353 MC , rel. min. Edson Fachin , dec. monocrática, j. 17-3-2017, DJE 55 de 22-3-2017.]","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"O Juízo da 13ª Vara Cível de Belém/PA não tem competência para apreciar e julgar o interdito proibitório proposto por Centrais Elétricas do Pará S.A. (CELPA) contra o Sindicato dos Trabalhadores nas Indústrias Urbanas do Estado do Pará (STIUPA), pois a causa de pedir da ação decorre de movimento grevista. (...) 8. Pelo exposto, na linha do entendimento firmado por este Supremo Tribunal, julgo procedente a reclamação para cassar a decisão impugnada e fixar a competência da Justiça do Trabalho para processar e julgar a ação de interdito proibitório (...).","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"[ Rcl 13.480 , rel. min. Cármen Lúcia , dec. monocrática, j. 14-3-2013, DJE 54 de 21-3-2013.]","deleted":false}],"heading":false},{"page":107,"runs":[{"text":"Na espécie vertente, a decisão impugnada nesta reclamação foi substituída por novo título judicial, pelo qual se reconhece a competência da Justiça do Trabalho para processar e julgar a ação de interdito proibitório ajuizada em decorrência do exercício do direito de greve pelos trabalhadores da iniciativa privada, o que traduz típica","deleted":false}],"heading":false},{"page":108,"runs":[{"text":"situação de prejuízo desta reclamação, em virtude de perda superveniente de seu objeto.","deleted":false}],"heading":false},{"page":108,"runs":[{"text":"[ Rcl 6.762 , rel. min. Cármen Lúcia , dec. monocrática, j. 1º-2-2012, DJE 27 de 8-2-2012.]","deleted":false}],"heading":false},{"page":108,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":108,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 74, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":108,"runs":[{"text":"Data de publicação do enunciado: DJE de 11-12-2009.","deleted":false}],"heading":false},{"page":108,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":108,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.Data de publicação do enunciado: DJe de 10.11.2009.","deleted":false}],"heading":false}]},{"id":"24","number":"24","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":109,"endPage":115,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1265","paragraphs":[{"page":109,"runs":[{"text":"Não se tipifica crime material contra a ordem tributária, previsto no art. 1º, incisos I a IV, da Lei 8.137/1990, antes do lançamento definitivo do tributo.","deleted":false}]}],"notes":[{"page":109,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":109,"runs":[{"text":"Embora não condicionada a denúncia à representação da autoridade fiscal (ADI 1.571 MC), falta justa causa para a ação penal pela prática do crime tipificado no art. 1º da Lei 8.137/1990 - que é material ou de resultado -, enquanto não haja decisão definitiva do processo administrativo de lançamento, quer se considere o lançamento definitivo uma condição objetiva de punibilidade ou um elemento normativo de tipo. 2. Por outro lado, admitida por lei a extinção da punibilidade do crime pela satisfação do tributo devido, antes do recebimento da denúncia (Lei 9.249/1995, art. 34), princípios e garantias constitucionais eminentes não permitem que, pela antecipada propositura da ação penal, se subtraia do cidadão os meios que a lei mesma lhe propicia para questionar, perante o Fisco, a exatidão do lançamento provisório, ao qual se devesse submeter para fugir ao estigma e às agruras de toda sorte do processo criminal.","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"[ HC 81.611 , rel. min. Sepúlveda Pertence , P, j. 10-12-2003, DJ de 13-5-2005.]","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":109,"runs":[{"text":"Constituição definitiva de crédito tributário e extradição","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"O requisito da dupla tipicidade previsto no art. 77, II, da Lei 6.815/1980 também foi atendido. Isso porque, ao atribuir a prática de quinze delitos de sonegação de impostos, sendo duas tentativas, mediante a omissão de declarações de imposto de renda, imposto de renda de pessoa jurídica e imposto sobre transações referentes aos anos de 2000 a 2004. O art. 370 do Código Penal alemão assim dispõe: (...). Tal figura típica encontra perfeita correspondência no Brasil no tipo penal previsto no art. 1º, I, da Lei 8.137/1990 (sonegação fiscal): (...). 5. Ademais, não há que falar na exigência da comprovação da constituição definitiva do crédito tributário para a concessão da extradição. Exige-se, sim, a tipicidade em ambos os Estados para o reconhecimento do pedido, e não que o Estado requerente siga as mesmas regras fazendárias existentes no Brasil. (...) 9. Ante o exposto, preenchidos todos os requisitos legais necessários, defiro a extradição (...).","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"[ Ext 1.222 , voto do rel. min. Teori Zavascki , 2ª T, j. 20-8-2013, DJE 172 de 3-9-2013.]","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"Instauração de inquérito policial para apurar crimes que independem de conclusão de processo administrativo-fiscal","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"DIREITO PENAL. RECLAMAÇÃO. ALEGAÇÃO DE VIOLAÇÃO À SÚMULA VINCULANTE 24. AUSÊNCIA DE ADERÊNCIA ENTRE O ATO RECLAMADO E O PARADIGMA APONTADO COMO VIOLADO. 1. A instauração de procedimento investigatório para apurar outros crimes, além das condutas típicas previstas no art. 1º, I a IV, da Lei nº 8.137/90, não ofende a autoridade da Súmula Vinculante 24. 2. Reclamação, cuja finalidade tem previsão constitucional taxativa, não admite o aprofundamento sobre matérias fáticas. 3. Os documentos dos autos não demonstram aderência entre o ato reclamado e a Súmula Vinculante 24. 4. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"[ Rcl 55.850 AgR , rel. min. Roberto Barroso , 1 T, j. 13-3-2023, DJE s/n de 15-3-2023.]","deleted":false}],"heading":false},{"page":109,"runs":[{"text":"1. Embargos de declaração interpostos contra decisão monocrática do Relator, recebidos como agravo regimental. (...). 2. Não se resumindo a investigação à apuração de crime material contra a ordem tributária - englobando também outros delitos -, não há como acolher a tese de ilegalidade da medida de busca e","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"apreensão, por suposta violação do enunciado da Súmula Vinculante 24 (HC 107.362, Rel. Min. Teori Zavascki, Segunda Turma, DJe-039 de 2.3.2015 e HC 118.985 AgR, Rel. Min. Edson Fachin, Primeira Turma, DJe-128 de 21.6.2016).","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"[ HC 139.151 ED , rel. min. Rosa Weber , 1º T, j. 5-10-2018, DJE 226 de 24-10-2018.","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"AGRAVO REGIMENTAL EM RECLAMAÇÃO. ALEGADA OFENSA À SÚMULA VINCULANTE 24. INVESTIGAÇÃO DE CRIME MATERIAL CONTRA A ORDEM TRIBUTÁRIA NÃO CONFIGURADA. 1. O crime de sonegação fiscal previdenciária (art. 337-A do Código Penal) absorve o crime de falso previsto no art. 297, § 4º, do Código Penal quando este tiver sido praticado com o único fim de deixar de recolher contribuições previdenciárias. 2. Na hipótese dos autos, não restou comprovado que o crime de falso se exauriu no crime tributário, de modo que não incide a Súmula Vinculante 24.","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"[ Rcl 24.424 AgR , rel. min. Roberto Barroso , 1ª T, j. 20-4-2018, DJE 86 de 4-5-2018.]","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"8. Sobressai da narrativa dos agravantes que “são investigados outros crimes além dos tipificados no 'art. 1º, incisos I a IV, da Lei 8.137/1990', dentre eles, crimes contra a administração em geral e de \"lavagem\" ou ocultação de bens, direitos e valores”, sendo certo o entendimento sufragado por esta Corte no sentido da prescindibilidade do esgotamento das vias administrativas para a investigação do crime de lavagem de dinheiro, conquanto o crime antecedente possa se consubstanciar em crime material contra a ordem tributária, mostrando-se possível a mitigação do enunciado 24 da Súmula Vinculante do Supremo Tribunal Federal na hipótese da investigação de crimes cuja natureza é distinta da fiscal. Precedentes: HC 118.985 AgR, Primeira Turma, Rel. Min. Edson Fachin, DJe de 21/06/2016; e ARE 936.653 AgR, Primeira Turma, Rel. Min. Roberto Barroso, DJe de 14/06/2016.","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"[ Rcl 28.147 AgR , rel. min. Luiz Fux , 1ª T, j. 28-11-2017, DJE 80 de 25-4-2018.]","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"AGRAVO INTERNO. RECLAMAÇÃO. ALEGADA OFENSA À SÚMULA VINCULANTE 24. INEXISTÊNCIA NO CASO CONCRETO. 1. A instauração de inquérito policial para apurar outros crimes, além do previsto no art. 1º da Lei 8.137/1990, não ofende o estabelecido no que enunciado pela Súmula Vinculante 24.","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"[ Rcl 24.768 AgR , rel. min. Alexandre de Moraes , 1ª T, j. 21-8-2017, DJE 197 de 1º-9-2017.]","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"Nos termos da Súmula Vinculante 24, a persecução criminal nas infrações contra a ordem tributária (art. 1º, I a IV, da Lei 8.137/1990) exige a prévia constituição do crédito tributário. Entretanto, não se podendo afastar de plano a hipótese de prática de outros delitos não dependentes de processo administrativo, não há falar em nulidade da medida de busca e apreensão. É que, ainda que abstraídos os fatos objeto do administrativo fiscal, o inquérito e a medida seriam juridicamente possíveis.","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"[ HC 107.362 , rel. min. Teori Zavascki , 2ª T, j. 10-2-2015, DJE 39 de 2-3-2015.]","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"Quanto aos delitos tributários materiais, esta nossa Corte dá pela necessidade do lançamento definitivo do tributo devido, como condição de caracterização do crime. Tal direção interpretativa está assentada na ideia-força de que, para a consumação dos crimes tributários descritos nos cinco incisos do art. 1º da Lei 8.137/1990, é imprescindível a ocorrência do resultado supressão ou redução de tributo. Resultado aferido, tão somente, após a constituição definitiva do crédito tributário (Súmula Vinculante 24). 3. Por outra volta, a consumação do delito de descaminho e a posterior abertura de processo-crime não estão a depender da constituição administrativa do débito fiscal. Primeiro, porque o delito de descaminho é rigorosamente formal, de modo a prescindir da ocorrência do resultado naturalístico. Segundo, porque a conduta materializadora desse crime é “iludir” o Estado quanto ao pagamento do imposto devido pela entrada, pela saída ou pelo consumo de mercadoria. E iludir não significa outra coisa senão fraudar, burlar, escamotear. Condutas essas minuciosamente narradas na inicial acusatória.","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"[ HC 99.740 , rel. min. Ayres Britto , 2ª T, j. 23-11-2010, DJE 20 de 1º-2-2011.]","deleted":false}],"heading":false},{"page":110,"runs":[{"text":"Inviabilidade de instauração da persecução penal antes da constituição definitiva do crédito tributário","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"EMENTA: DIREITO PENAL. RECLAMAÇÃO. ALEGAÇÃO DE VIOLAÇÃO À SÚMULA VINCULANTE 24. ADMISSIBILIDADE DE HABEAS CORPUS. AUSÊNCIA DE ADERÊNCIA ENTRE O ATO RECLAMADO E O PARADIGMA APONTADO COMO VIOLADO. 1. Os documentos dos autos não demonstram aderência entre o ato reclamado e a Súmula Vinculante 24. 2. Embora se exija o lançamento definitivo do crédito tributário para o início da persecução penal nos crimes de sonegação fiscal, o mesmo entendimento não se aplica à mera fase investigatória (HC 106.152, Relª. Minª. Rosa Weber; HC 130596 AgR, Rel. Alexandre de Moraes). 3. Se o inquérito já está suspenso, aguardando o término do processo administrativo, não há razão para trancá-lo antecipadamente. Se, ao fim do processo administrativo, o crédito tributário for mantido, prosseguirá o inquérito; se for anulado, será trancado o procedimento (Rcl 31194 AgR), minha relatoria). 4. Agravo interno a que se nega provimento.","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"[ Rcl 46.215 AgR , rel. min. Roberto Barroso , 1ª T, j. 27-4-2021, DJE 85 de 5-5-2021.]","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"(...) os crimes tributários são de natureza material, uma vez que sua consumação se dá não com a conduta de declaração falsa ou omissão de dados, mas com a ocorrência do resultado consistente na supressão ou redução do tributo. E não há tributo sem que a autoridade administrativa, após o devido processo legal, constitua o crédito em termos definitivos. 6. Nesse contexto, a justa causa deve ser aferida no momento da apresentação da exordial, já que os elementos indiciários de autoria e prova da materialidade devem lastrear a admissão da acusação. Em outras palavras, a condição objetiva de punibilidade não pode ser preenchida depois de iniciado o processo penal.","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"[ Rcl 31.194 MC , rel. min. Roberto Barroso , dec. monocrática, j. 29-11-2018, DJE 257 de 3-12-2018.]","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"Agravo regimental no recurso extraordinário com agravo. Matéria criminal. Crime contra a ordem tributária. Ausência de constituição definitiva do crédito tributário. Trancamento da ação penal por inexistência de justa causa. Súmula Vinculante 24. Pretendida absolvição sumária. Impossibilidade. Agravo regimental não provido. 1. A ausência de constituição definitiva do crédito tributário inviabiliza o desenvolvimento válido da persecução criminal, acarretando o trancamento da ação penal por ausência de justa causa, o que não impede o oferecimento de nova denúncia (ou aditamento da já existente) após o exaurimento da via administrativa, a teor do disposto na Súmula Vinculante 24.","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"[ ARE 1.047.419 AgR , rel. min. Dias Toffoli , 2ª T, j. 27-3-2018, DJE 77 de 23-4-2018.]","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"Em princípio, atesto que a decisão definitiva do processo administrativo consubstancia condição objetiva de punibilidade. Em outras palavras, não se pode afirmar a existência, nem tampouco fixar o montante da obrigação tributária até que haja o efeito preclusivo da decisão final administrativa. Vale ressaltar que, a partir do precedente firmado no HC 81.611/DF, firmou-se nesta Corte jurisprudência no sentido de que o crime contra a ordem tributária (art. 1º, I a IV, da Lei 8.137/1990) somente se consuma com o lançamento definitivo. É que, em razão da pendência de recurso administrativo perante as autoridades fazendárias, não se pode falar de crime. Uma vez que essa atividade persecutória funda-se tão somente na existência de suposto débito tributário, não é legítimo ao Estado instaurar processo penal cujo objeto coincida com o de apuração tributária que ainda não foi finalizada na esfera administrativa.","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"[ HC 102.477 , voto do rel. min. Gilmar Mendes , 2ª T, j. 28-6-2011, DJE 153 de 10-8-2011.]","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"É pacífica a jurisprudência do Supremo Tribunal Federal quanto à necessidade do exaurimento da via administrativa para a validade da ação penal, instaurada para apurar infração aos incisos I a IV do art. 1º da Lei 8.137/1990. (...) 2. A denúncia ministerial pública foi ajuizada antes do encerramento do procedimento administrativo fiscal. A configurar ausência de justa causa para a ação penal. Vício processual que não é passível de convalidação. 3. Ordem concedida para trancar a ação penal.","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"[ HC 100.333 , rel. min. Ayres Britto , 2ª T, j. 21-6-2011, DJE 201 de 19-10-2011.]","deleted":false}],"heading":false},{"page":111,"runs":[{"text":"Com efeito, revela-se juridicamente inviável a instauração de persecução penal, mesmo na fase investigatória, enquanto não se concluir, perante órgão competente da administração tributária, o procedimento fiscal","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"tendente a constituir, de modo definitivo, o crédito tributário. Enquanto tal não ocorrer, como sucedeu neste caso, estar-se-á diante de comportamento desvestido de tipicidade penal (RTJ 195/114), a evidenciar, portanto, a impossibilidade jurídica de se adotar, validamente, contra o (suposto) devedor, qualquer ato de persecução penal, seja na fase pré-processual (inquérito policial), seja na fase processual ( persecutio criminis in judicio ), pois - como se sabe - comportamentos atípicos (como na espécie) não justificam, por razões óbvias, a utilização, pelo Estado, de medidas de repressão criminal.","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"[ Rcl 10.644 MC , rel. min. Celso de Mello , dec. monocrática, j. 14-4-2011, DJE 74 de 19-4-2011.]","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"Mitigação da Súmula Vinculante 24 ante as peculiaridades do caso concreto","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"Os crimes contra a ordem tributária pressupõem a prévia constituição definitiva do crédito na via administrativa para fins de tipificação da conduta. A jurisprudência desta Corte deu origem à Súmula Vinculante 24 (...). 2. Não obstante a jurisprudência pacífica quanto ao termo inicial dos crimes contra a ordem tributária, o Supremo Tribunal Federal tem decidido que a regra contida na Súmula Vinculante 24 pode ser mitigada de acordo com as peculiaridades do caso concreto, sendo possível dar início à persecução penal antes de encerrado o procedimento administrativo, nos casos de embaraço à fiscalização tributária ou diante de indícios da prática de outros delitos, de natureza não fiscal.","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"[ ARE 936.653 AgR , rel. min. Roberto Barroso , 1ª T, j. 24-5-2016, DJE 122 de 14-6-2016.]","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"A questão posta no presente writ diz respeito à possibilidade de instauração de inquérito policial para apuração de crime contra a ordem tributária, antes do encerramento do procedimento administrativo-fiscal. 2. O tema relacionado à necessidade do prévio encerramento do procedimento administrativo-fiscal para configuração dos crimes contra a ordem tributária, previstos no art. 1º da Lei 8.137/1990, já foi objeto de aceso debate perante esta Corte (...). 3. A orientação que prevaleceu foi exatamente a de considerar a necessidade do exaurimento do processo administrativo-fiscal para a caracterização do crime contra a ordem tributária (Lei 8.137/1990, art. 1º) (...). 4. Entretanto, o caso concreto apresenta uma particularidade que afasta a aplicação dos precedentes mencionados. 5. Diante da recusa da empresa em fornecer documentos indispensáveis à fiscalização da Fazenda estadual, tornou-se necessária a instauração de inquérito policial para formalizar e instrumentalizar o pedido de quebra do sigilo bancário, diligência imprescindível para a conclusão da fiscalização e, consequentemente, para a apuração de eventual débito tributário. 6. Desse modo, entendo possível a instauração de inquérito policial para apuração de crime contra a ordem tributária, antes do encerramento do processo administrativo-fiscal, quando for imprescindível para viabilizar a fiscalização.","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"[ HC 95.443 , rel. min. Ellen Gracie , 2ª T, j. 2-2-2010, DJE 30 de 19-2-2010.]","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"Natureza tributária das contribuições devidas à Previdência Social","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"A questão reside em saber se o crédito é ou não devido, e não em averiguar quem deve ou pode averiguar sua exigibilidade. Acrescentando-se, por respeito à argumentação, que a competência reconhecida pelo art. 114, VII, da CF/1988, à Justiça do Trabalho para executar as contribuições previdenciárias é aquela decorrente das sentenças que proferir. Logo, o pressuposto de exigibilidade é a constituição do crédito pela própria decisão trabalhista. (...) esta Corte tem reiteradamente considerado, em seus julgados, que as contribuições devidas à Previdência Social possuem natureza tributária (...). Assim, a sistemática de imputação penal por crimes de sonegação contra a Previdência Social deve se sujeitar à mesma lógica aplicada àqueles contra a ordem tributária em sentido estrito. (...) Enquanto pendente a constituição definitiva de crédito previdenciário, que possui natureza tributária, não há como se imputar a alguém a prática de sonegação de contribuição previdenciária, simplesmente por persistir a dúvida quanto ao fato de essa contribuição ser devida ou não.","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"[ Inq 3.102 , voto do rel. min. Gilmar Mendes , P, j. 25-4-2013, DJE 184 de 19-9-2013.]","deleted":false}],"heading":false},{"page":112,"runs":[{"text":"Omissão reiterada no pagamento de tributos não legitima a instauração de persecução penal antes da constituição definitiva dos créditos tributários","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"(...) a jurisprudência deste Supremo Tribunal Federal é uníssona no sentido de que o crédito tributário somente se faz constituído após a conclusão do procedimento administrativo. Assim, não se pode apontar a suposta reiteração na omissão de pagamento de tributos, quando estes ainda não foram constituídos em definitivo. Ademais, a Súmula Vinculante 24 determina que “não se tipifica crime material contra a ordem tributária, previsto no art. 1º, incisos I a IV, da Lei 8.137/1990, antes do lançamento definitivo do tributo”. Com esse entendimento, é imperioso constatar que procedimentos administrativos em trâmite, considerados pelo STJ como condutas reincidentes ou reiteradas, não podem ser equiparados às condenações criminais com trânsito em julgado.","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"[ HC 136.843 MC , rel. min. Ricardo Lewandowski , dec. monocrática, j. 2-2-2017, DJE 23 de 7-2-2017.]","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"Parcelamento tributário e suspensão da pretensão punitiva do Estado","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"Diferente do alegado pela impetrante, a tipificação dos crimes contra a ordem tributária pressupõe o lançamento definitivo do crédito tributário. Incide na espécie a conclusão revelada no enunciado da Súmula Vinculante n. 24 do Supremo Tribunal: “Não se tipifica crime material contra a ordem tributária, previsto no art. 1º, inciso I a IV, da Lei n. 8.137/90, antes do lançamento definitivo do tributo”. 12. Como disposto no § 2º do art. 83 da Lei n. 9.430, de 27.12.1996, alterado pela Lei n. 12.382/2011, para suspender-se a pretensão punitiva do Estado, é necessário que o pedido de parcelamento tenha sido formalizado antes do recebimento da denúncia. Não é o caso dos autos: a constituição definitiva do crédito tributário deu-se em 3.5.2012, a denúncia formalizada contra o paciente foi recebida em 19.6.2013 e o requerimento de parcelamento do crédito tributário foi apresentado somente em 26.12.2013. 13. Não há, portanto, ilegalidade nas decisões proferidas na instância antecedente. (...) É de se anotar não se poder confundir a extinção da punibilidade pelo pagamento integral do crédito tributário, que não se submete ao momento do recebimento da denúncia, com suspensão da ação penal, decorrente de adesão a programa de parcelamento tributário. (...) Pelo exposto, nego seguimento ao habeas corpus (§ 1º do art. 21 do Regimento Interno do Supremo Tribunal Federal), prejudicada a medida liminar requerida.","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"[ HC 223.930 , rel. min. Cármen Lúcia , P, j. 23-01-2023, DJE s/n de 27-1-2023.]","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"Possibilidade de aplicação da Súmula Vinculante 24 a fatos anteriores a sua edição","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"I - As razões do agravo regimental são inaptas para desconstituir os fundamentos da decisão agravada, que, por isso, se mantêm hígidos. II - O Supremo Tribunal Federal tem admitido a aplicação da Súmula Vinculante 24 a fatos anteriores à sua edição, porquanto o respectivo enunciado apenas sintetiza a jurisprudência dominante desta Corte e, dessa forma, não pode ser considerada como retroação de norma mais gravosa ao réu. III - Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"[ ARE 1.053.709 AgR-ED-EDv-AgR , rel. min. Ricardo Lewandowski , P, j. 30-11-2018, DJE 263 de 7-12-2018.]","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"Possibilidade de realização de diligências investigatórias e instauração de procedimento cautelar preparatório antes do lançamento definitivo do tributo","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"3. A Súmula Vinculante nº 24 do STF veda a tipificação de crime material contra a ordem tributária antes do lançamento definitivo do tributo, mas não impede a realização de diligências investigatórias ou a instauração de procedimento cautelar preparatório.","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"[ HC 257.598 AgR , rel. min. Edson Fachin , 2ª T, j. 25-8-2025, DJE s/n 9-9-2025.]","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"Termo inicial da prescrição em crimes contra a ordem tributária","deleted":false}],"heading":false},{"page":113,"runs":[{"text":"5. Não se demonstra, no caso, contrariedade à Súmula Vinculante n. 24 deste Supremo Tribunal. Como anotei na decisão agravada, para afastar a pretensão de reconhecimento da prescrição quanto aos fatos do Processo (...), a autoridade reclamada reconheceu como data da consumação do crime tributário o lançamento definitivo desse crédito com a inscrição na dívida ativa, não tendo havido o transcurso do prazo prescricional de oito","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"anos, considerada a pena em concreto, entre essa inscrição e os demais marcos interruptivos. A análise do ato reclamado desfaz o argumento de que haveria ilicitude na conduta judicial questionada nesta reclamação, não estando evidenciada a prescrição da pretensão punitiva postulada pela defesa. Não se comprova, na espécie, contrariedade à Súmula Vinculante n. 24 deste Supremo Tribunal.","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"[ RCL 66.067 AGR , rel. min. Cármen Lúcia , 1ª T, j. 4-4-2024, DJE s/n de 8-4-2024.]","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"8. Depreende-se dos autos que a recorrente busca o reconhecimento da prescrição da pretensão punitiva em abstrato alusiva aos crimes de sonegação fiscal, sonegação de contribuição previdenciária e apropriação indébita previdenciária, todos com pena máxima de 5 anos reclusão. 9. Contudo, ao contrário do que alegado, a consumação dos crimes contra a ordem tributária pressupõe a constituição definitiva do crédito tributário. Incide, na espécie, a conclusão revelada no enunciado nº 24 da Súmula Vinculante (...) 11. Assim, a prescrição, ante a pena de 5 anos prevista em abstrato para cada crime, dá-se em 12 anos - artigo 109, inciso III, do CP. Observada a ocorrência do lançamento definitivo dos tributos devidos no ano de 2014, não transcorreu o período necessário ao reconhecimento da causa extintiva de punibilidade.","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"[ RHC 237.621 , rel. min. André Mendonça , dec. monocrática, j. 14-02-2024, DJE s/n de 15-02-2024.]","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"1. As questões suscitadas no recurso extraordinário encontram-se preclusas, haja vista que a jurisprudência da Corte é assente no sentido de ser incabível recurso extraordinário contra acórdão do Superior Tribunal de Justiça no qual se suscite questão resolvida na decisão de segundo grau. 2. Ainda que assim não fosse, segundo o entendimento da Corte, a consumação do crime tipificado no art. 1º da Lei 8.137/1990 somente se verifica com a constituição do crédito fiscal, começando a correr, a partir daí, a prescrição (HC 85.051/MG, Segunda Turma, Relator o Ministro Carlos Velloso, DJ de 1º/7/05). Esse entendimento encontra-se cristalizado no enunciado Súmula Vinculante 24 da Corte. 3. É ilógico permitir que a prescrição seguisse seu curso normal no período de duração do processo administrativo necessário à consolidação do crédito tributário. Se assim fosse, o recurso administrativo, por iniciativa do contribuinte, serviria mais como uma estratégia de defesa para alcançar a prescrição com o decurso do tempo do que a sua real finalidade, que é, segundo o Ministro Sepúlveda Pertence, propiciar a qualquer cidadão questionar, perante o Fisco, a exatidão do lançamento provisório de determinado tributo (HC 81.611/DF, Tribunal Pleno, DJ de 13/5/05). 4. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"[ ARE 1.031.806 AgR , rel. min. Dias Toffoli , 2ª T, j. 30-6-2017, DJE 177 de 14-8-2017.]","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"A prestação jurisdicional foi concedida nos termos da legislação vigente, apesar de ter sido a conclusão contrária aos interesses da parte recorrente. Quanto à prescrição retroativa do delito, não assiste razão ao recorrente. De acordo com a jurisprudência desta Corte, crimes contra a ordem tributária se consumam apenas com a constituição do crédito tributário (Súmula Vinculante 24). Assim, diferente do alegado pela defesa, o prazo prescricional começa a ocorrer apenas a partir do lançamento definitivo do tributo. (...) No caso, a pena aplicada ao recorrente foi de dois anos e nove meses, portanto, o delito prescreve em oito anos (art. 109, IV, do CP/1940). Verifica-se que entre o lançamento definitivo do crédito e a denúncia, bem como entre a denúncia e a decisão do TJ/SP, não decorreram os oito anos necessários para a prescrição da pretensão punitiva.","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"[ ARE 1.042.860 , rel. min. Gilmar Mendes , dec. monocrática, j. 12-5-2017, DJE 108 de 24-5-2017.]","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"O termo inicial da prescrição da ação dos crimes materiais previstos no art. 1º da Lei 8.137/1990 é a data da consumação do delito, que, conforme a jurisprudência do Supremo Tribunal Federal, corresponde à data da constituição definitiva do crédito tributário.","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"[ RHC 122.339 AgR , rel. min. Roberto Barroso , 1ª T, j. 4-8-2015, DJE 171 de 1º-9-2015.]","deleted":false}],"heading":false},{"page":114,"runs":[{"text":"Ademais, padece de plausibilidade jurídica a tese do recorrente de que a observância do enunciado da Súmula Vinculante 24 no caso concreto importaria interpretação judicial mais gravosa da lei de regência. Com efeito, a Súmula Vinculante em questão é mera consolidação da jurisprudência da Corte, que, há muito, tem entendido que “a consumação do crime tipificado no art. 1º da Lei 8.137/1990 somente se verifica com a constituição do","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"crédito fiscal, começando a correr, a partir daí, a prescrição” (HC 85.051/MG, Segunda Turma, rel. min. Carlos Velloso, DJ de 1º-7-2005). De fato, não haveria lógica permitir que a prescrição seguisse seu curso normal no período de duração do processo administrativo necessário à consolidação do crédito tributário. Se assim o fosse, o recurso administrativo, por iniciativa do contribuinte, serviria mais como uma estratégia de defesa para alcan- çar a prescrição com o decurso do tempo - quando se aposta na morosidade da Justiça -, do que sua real finalidade, que é, segundo o ministro Sepúlveda Pertence, propiciar a qualquer cidadão questionar, perante o Fisco, a exatidão do lançamento provisório de determinado tributo (HC 81.611/DF, Plenário, DJ de 13-5-2005).","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"[ RHC 122.774 , voto do rel. min. Dias Toffoli , 1ª T, j. 19-5-2015, DJE 111 de 11-6-2015.]","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"Segundo a Súmula Vinculante 24, o termo inicial para a contagem do prazo prescricional, nos delitos do art. 1º, I a IV, da Lei 8.137/1990, é a data do lan- çamento definitivo do crédito tributário. No presente caso, não há que se falar em prescrição retroativa, uma vez que não transcorreu o decurso de quatro anos entre a constituição definitiva do crédito e o recebimento da denúncia, ou entre os demais marcos interruptivos. É antiga a jurisprudência desta Corte no sentido de que os crimes definidos no art. 1º da Lei 8.137/1990 são materiais e somente se consumam com o lançamento definitivo do crédito. Por consequência, não há que se falar em prescrição, que somente se iniciará com a consumação do delito, nos termos do art. 111, I, do CP/1940.","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"[ ARE 649.120 , rel. min. Joaquim Barbosa , dec. monocrática, j. 28-5-2012, DJE 107 de 1º-6-2012.]","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"Com efeito, considerado o lançamento definitivo do tributo como elemento típico do delito, verifico que o posicionamento adotado pelo Tribunal Regional Federal da 2ª Região converge para o entendimento assentado por esta Suprema Corte, no sentido de que, “até o momento da consumação delitiva, sequer é de se cogitar da contagem do prazo prescricional” (...).","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"[ Rcl 13.220 , rel. min. Rosa Weber , dec. monocrática, j. 27-2-2012, DJE 45 de 5-3-2012.]","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"(...) considerada a constituição definitiva do débito tributário como elemento típico do delito, não é possível aderir, automaticamente, à proposição defensiva da extinção da punibilidade pela prescrição. É que, até o momento da consumação delitiva, sequer é de se cogitar da contagem do prazo prescricional, nos termos do inciso I do art. 111 do CP/1940.","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"[ HC 105.115 AgR , rel. min. Ayres Britto , 2ª T, j. 23-11-2010, DJE 28 de 11-2-2011.]","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":115,"runs":[{"text":"Data de publicação do enunciado: DJE de 11-12-2009.","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":115,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"25","number":"25","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":116,"endPage":117,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","paragraphs":[{"page":116,"runs":[{"text":"É ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade de depósito.","deleted":false}]}],"notes":[{"page":116,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":116,"runs":[{"text":"(...) diante do inequívoco caráter especial dos tratados internacionais que cuidam da proteção dos direitos humanos, não é difícil entender que a sua internalização no ordenamento jurídico, por meio do procedimento de ratificação previsto na CF/1988, tem o condão de paralisar a eficácia jurídica de toda e qualquer disciplina normativa infraconstitucional com ela conflitante. Nesse sentido, é possível concluir que, diante da supremacia da CF/1988 sobre os atos normativos internacionais, a previsão constitucional da prisão civil do depositário infiel (art. 5º, LXVII) não foi revogada (...), mas deixou de ter aplicabilidade diante do efeito paralisante desses tratados em relação à legislação infraconstitucional que disciplina a matéria (...). Tendo em vista o caráter supralegal desses diplomas normativos internacionais, a legislação infraconstitucional posterior que com eles seja conflitante também tem sua eficácia paralisada. (...) Enfim, desde a adesão do Brasil, no ano de 1992, ao PIDCP (art. 11) e à CADH - Pacto de São José da Costa Rica (art. 7º, 7), não há base legal para aplicação da parte final do art. 5º, LXVII, da CF/1988, ou seja, para a prisão civil do depositário infiel.","deleted":false}],"heading":false},{"page":116,"runs":[{"text":"[ RE 466.343 , rel. min. Cezar Peluso , voto do min. Gilmar Mendes , P, j. 3-12-2008, DJE 104 de 5-6-2009, Tema 60.]","deleted":false}],"heading":false},{"page":116,"runs":[{"text":"A matéria em julgamento neste habeas corpus envolve a temática da (in)admissibilidade da prisão civil do depositário infiel no ordenamento jurídico brasileiro no período posterior ao ingresso do Pacto de São José da Costa Rica no direito nacional. 2. Há o caráter especial do PIDCP (art. 11) e da CADH - Pacto de São José da Costa Rica (art. 7º, 7), ratificados, sem reserva, pelo Brasil, no ano de 1992. A esses diplomas internacionais sobre direitos humanos é reservado o lugar específico no ordenamento jurídico, estando abaixo da CF/1988, porém acima da legislação interna. O status normativo supralegal dos tratados internacionais de direitos humanos subscritos pelo Brasil torna inaplicável a legislação infraconstitucional com ele conflitante, seja ela anterior ou posterior ao ato de ratificação. 3. Na atualidade a única hipótese de prisão civil, no Direito brasileiro, é a do devedor de alimentos. O art. 5º, § 2º, da Carta Magna expressamente estabeleceu que os direitos e garantias expressos no caput do mesmo dispositivo não excluem outros decorrentes do regime dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte. O Pacto de São José da Costa Rica, entendido como um tratado internacional em matéria de direitos humanos, expressamente, só admite, no seu bojo, a possibilidade de prisão civil do devedor de alimentos e, consequentemente, não admite mais a possibilidade de prisão civil do depositário infiel. 4. Habeas corpus concedido.","deleted":false}],"heading":false},{"page":116,"runs":[{"text":"[ HC 95.967 , rel. min. Ellen Gracie , 2ª T, j. 11-11-2008, DJE 227 de 28-11-2008.]","deleted":false}],"heading":false},{"page":116,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":116,"runs":[{"text":"● É ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade de depósito.","deleted":false}],"heading":false},{"page":116,"runs":[{"text":"[Tese definida no RE 466.343 , rel. min. Cezar Peluso , P, j. 3-12-2008, DJE 104 de 5-6-2009, Tema 60.]","deleted":false}],"heading":false},{"page":116,"runs":[{"text":"O Plenário desta Corte, no julgamento conjunto dos HC 87.585 e HC 92.566, relator o ministro Marco Aurélio, e dos RE 466.343 e RE 349.703, relatores os ministros Cezar Peluso e Carlos Britto, sessão de 3-12-2008, fixou o entendimento de que a circunstância de o Brasil haver subscrito o Pacto de São José da Costa Rica conduziu à inexistência de balizas visando à eficácia do que previsto no art. 5º, LXVII, da CF/1988, restando, assim, derrogadas as normas estritamente legais definidoras da custódia do depositário infiel.","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"[ RE 716.101 , rel. min. Luiz Fux , dec. monocrática, j. 31-10-2012, DJE 220 de 8-11-2012.]","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"(...) impende enfatizar - quanto ao outro fundamento do recurso em questão - que a jurisprudência do Supremo Tribunal Federal firmou-se no sentido de que inexiste, em nosso sistema jurídico, a prisão civil do depositário infiel, inclusive a do depositário judicial a quem se haja atribuído infidelidade depositária (...). Essa orientação, por sua vez, acha-se contemplada em súmula desta Suprema Corte revestida de eficácia vinculante (Súmula Vinculante 25) (...).","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"[ AI 277.940 , rel. min. Celso de Mello , dec. monocrática, j. 31-5-2011, DJE 111 de 10-6-2011.]","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":117,"runs":[{"text":"Pedido de revisão da Súmula Vinculante 25","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"(...) para admitir-se a revisão ou o cancelamento de súmula vinculante, é necessário que seja evidenciada a superação da jurisprudência da Suprema Corte no trato da matéria; haja alteração legislativa quanto ao tema ou, ainda, modificação substantiva de contexto político, econômico ou social. Entretanto, a proponente não evidenciou, de modo convincente, nenhum dos aludidos pressupostos de admissão e, ainda, não se desincumbiu da exigência constitucional de apresentar decisões reiteradas do Supremo Tribunal Federal que demonstrassem a necessidade de alteração do teor redacional da Súmula Vinculante 25, o que impossibilita a análise da presente proposta.","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"[ PSV 54 , rel. min. presidente Ricardo Lewandowski , P, j. 24-9-2015, DJE 199 de 5-10-2015.]","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Status supralegal dos tratados e convenções internacionais sobre direitos humanos","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Esse caráter supralegal do tratado devidamente ratificado e internalizado na ordem jurídica brasileira - porém não submetido ao processo legislativo estipulado pelo art. 5º, § 3º, da CF/1988 - foi reafirmado pela edição da Súmula Vinculante 25, segundo a qual “é ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito”. Tal verbete sumular consolidou o entendimento deste Tribunal de que o art. 7º, item 7, da CADH teria ingressado no sistema jurídico nacional com status supralegal, inferior à CF/1988, mas superior à legislação interna, a qual não mais produziria qualquer efeito naquilo que conflitasse com a sua disposição de vedar a prisão civil do depositário infiel. Tratados e convenções internacionais com conteúdo de direitos humanos, uma vez ratificados e internalizados, ao mesmo passo em que criam diretamente direitos para os indivíduos, operam a supressão de efeitos de outros atos estatais infraconstitucionais que se contrapõem à sua plena efetivação.","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"[ ADI 5.240 , voto do rel. min. Luiz Fux , P, j. 20-8-2015, DJE 18 de 1º-2-2016.]","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":117,"runs":[{"text":"● Vide Súmula 619 (revogada).","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 60, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Data de publicação do enunciado: DJE de 23-12-2009.","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":117,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"26","number":"26","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":118,"endPage":123,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1271","paragraphs":[{"page":118,"runs":[{"text":"Para efeito de progressão de regime no cumprimento de pena por crime hediondo, ou equiparado, o juízo da execução observará a inconstitucionalidade do art. 2º da Lei 8.072, de 25 de julho de 1990, sem prejuízo de avaliar se o condenado preenche, ou não, os requisitos objetivos e subjetivos do benefício, podendo determinar, para tal fim, de modo fundamentado, a realização de exame criminológico.","deleted":false}]}],"notes":[{"page":118,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":118,"runs":[{"text":"PENA - REGIME DE CUMPRIMENTO - PROGRESSÃO - RAZÃO DE SER. A progressão no regime de cumprimento da pena, nas espécies fechado, semiaberto e aberto, tem como razão maior a ressocialização do preso, que, mais dia ou menos dia, voltará ao convívio social. PENA - CRIMES HEDIONDOS - REGIME DE CUMPRIMENTO - PROGRESSÃO - ÓBICE - ART. 2º, § 1º, DA LEI 8.072/1990 - INCONSTITUCIONALIDADE - EVOLUÇÃO JURISPRUDENCIAL. Conflita com a garantia da individualização da pena - art. 5º, inciso XLVI, da Constituição Federal - a imposição, mediante norma, do cumprimento da pena em regime integralmente fechado. Nova inteligência do princípio da individualização da pena, em evolução jurisprudencial, assentada a inconstitucionalidade do art. 2º, § 1º, da Lei 8.072/1990.","deleted":false}],"heading":false},{"page":118,"runs":[{"text":"[ HC 82.959 , rel. min. Marco Aurélio , P, j. 23-2-2006, DJ de 1º-9-2006.]","deleted":false}],"heading":false},{"page":118,"runs":[{"text":"A Constituição Federal, ao criar a figura do crime hediondo, assim dispôs no art. 5º, XLIII: (...). Não fez menção nenhuma à vedação de progressão de regime, como, aliás - é bom lembrar -, tampouco receitou tratamento penal stricto sensu (sanção penal) mais severo, quer no que tange ao incremento das penas, quer no tocante à sua execução. (...) Evidente, assim, que, perante a CF/1988, o princípio da individualização da pena compreende: a) proporcionalidade entre o crime praticado e a sanção abstratamente cominada no preceito secundário da norma penal; b) individualização da pena aplicada em conformidade com o ato singular praticado por agente em concreto (dosimetria da pena); c) individualização da sua execução, segundo a dignidade humana (art. 1º, III), o comportamento do condenado no cumprimento da pena (no cárcere ou fora dele, no caso das demais penas que não a privativa de liberdade) e à vista do delito cometido (art. 5º, XLVIII). Logo, tendo predicamento constitucional o princípio da individualização da pena (em abstrato, em concreto e em sua execução), exceção somente poderia aberta por norma de igual hierarquia nomológica.","deleted":false}],"heading":false},{"page":118,"runs":[{"text":"[ HC 82.959 , rel. min. Marco Aurélio , voto-vista do min. Cezar Peluso , P, j. 23-2-2006, DJ de 1º-9-2006.]","deleted":false}],"heading":false},{"page":118,"runs":[{"text":"Essas colocações têm a virtude de demonstrar que a declaração de inconstitucionalidade in concreto também se mostra passível de limitação de efeitos. (...) É que, nesses casos, tal como já argumentado, o afastamento do princípio da nulidade da lei assenta-se em fundamentos constitucionais e não em razões de conveniência. Se o sistema constitucional legitima a declaração de inconstitucionalidade restrita no controle abstrato, esta decisão poderá afetar, igualmente, os processos do modelo concreto ou incidental de normas. Do contrário, poder-se-ia ter inclusive um esvaziamento ou uma perda de significado da própria declaração de inconstitucionalidade restrita ou limitada. (...) No caso em tela, observa-se que eventual declaração de inconstitucionalidade com efeito ex tunc ocasionaria repercussões em todo o sistema vigente. (...) Com essas considerações, também eu, Senhor Presidente, declaro a inconstitucionalidade do art. 2º, § 1º, da Lei 8.072/1990. Faço isso, com efeito ex nunc , nos termos do art. 27 da Lei 9.868/1999, que entendo aplicável à espécie. Ressalto que esse efeito ex nunc deve ser entendido como aplicável às condenações que envolvam situações ainda suscetíveis de serem submetidas ao regime de progressão.","deleted":false}],"heading":false},{"page":118,"runs":[{"text":"[ HC 82.959 , rel. min. Marco Aurélio , voto do min. Gilmar Mendes , P, j. 23-2-2006, DJ de 1º-9-2006.]","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":119,"runs":[{"text":"● É inconstitucional a fixação ex lege , com base no art. 2º, § 1º, da Lei 8.072/1990, do regime inicial fechado, devendo o julgador, quando da condenação, ater-se aos parâmetros previstos no artigo 33 do Código Penal.","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"[Tese definida no ARE 1.052.700 RG , rel. min. Edson Fachin , P, j. 2-11-2017, DJE 18 de 1º-2-2018, Tema 972.]","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"Entendo que, se a Constituição Federal menciona que a lei regulará a individualização da pena, é natural que ela exista. Do mesmo modo, os critérios para a fixação do regime prisional inicial devem-se harmonizar com as garantias constitucionais, sendo necessário exigir-se sempre a fundamentação do regime imposto, ainda que se trate de crime hediondo ou equiparado. Deixo consignado, já de início, que tais circunstâncias não elidem a possibilidade de o magistrado, em eventual apreciação das condições subjetivas desfavoráveis, vir a estabelecer regime prisional mais severo, desde que o faça em razão de elementos concretos e individualizados, aptos a demonstrar a necessidade de maior rigor da medida privativa de liberdade do indivíduo, nos termos do § 3º do art. 33 c/c o art. 59 do CP/1940. A progressão de regime, ademais, quando se cuida de crime hediondo ou equiparado, também se dá em lapso temporal mais dilatado (Lei 8.072/1990, art. 2º, § 2º). (...) Feitas essas considerações, penso que deve ser superado o disposto na Lei dos Crimes Hediondos (obrigatoriedade de início do cumprimento de pena no regime fechado) para aqueles que preencham todos os demais requisitos previstos no art. 33, § 2º, b, e 3º, do CP/1940, admitindo-se o início do cumprimento de pena em regime diverso do fechado. Nessa conformidade, tendo em vista a declaração incidental de inconstitucionalidade do § 1º do art. 2º da Lei 8.072/1990, na parte em que impõe a obrigatoriedade de fixação do regime fechado para início do cumprimento da pena aos condenados pela prática de crimes hediondos ou equiparados, concedo a ordem para alterar o regime inicial de cumprimento das reprimendas impostas ao paciente para o semiaberto.","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"[ HC 111.840 , voto do rel. min. Dias Toffoli , P, j. 27-6-2012, DJE 249 de 17-12-2013.]","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"● A Lei 11.464/2007, que majorou o tempo necessário para progressão no cumprimento da pena, não se aplica a situações jurídicas que retratem crime hediondo ou equiparado cometido em momento anterior à respectiva vigência.","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"[Tese definida no RE 579.167 , rel. min. Marco Aurélio , P, j. 16-5-2013, DJE 207 de 18-10-2013, Tema 59.]","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"PENA. REGIME DE CUMPRIMENTO. PROGRESSÃO. FATOR TEMPORAL. A Lei 11.464/2007, que majorou o tempo necessário a progredir-se no cumprimento da pena, não se aplica a situações jurídicas que retratem crime cometido em momento anterior à respectiva vigência - precedentes.","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"[ RE 579.167 , rel. min. Marco Aurélio , P, j. 16-5-2013, DJE 207 de 18-10-2013, Tema 59.]","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":119,"runs":[{"text":"Declaração incidental de inconstitucionalidade da vedação à conversão da pena privativa de liberdade em restritiva de direitos nos crimes de tráfico de drogas","deleted":false}],"heading":false},{"page":119,"runs":[{"text":"Não há dúvida de que o descumprimento de qualquer dessas decisões importará, em maior ou menor intensidade, ofensa à autoridade das decisões da Suprema Corte, o que, numa interpretação literal e radical do art. 102, I, l da Constituição, permitiria a qualquer prejudicado, a intentar perante a Corte a ação de reclamação para “garantia da autoridade de suas decisões”. Todavia, tudo recomenda que se confira interpretação estrita a essa competência, (...). O mesmo sentido restritivo há de ser conferido à norma de competência sobre cabimento de reclamação. É que, considerando o vastíssimo elenco de decisões da Corte Suprema com eficácia expansiva, e a tendência de universalização dessa eficácia, a admissão incondicional de reclamação em caso de descumprimento de qualquer delas, transformará o Supremo Tribunal Federal em verdadeira Corte executiva, suprimindo instâncias locais e atraindo competências próprias das instâncias ordinárias. Em outras","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"palavras, não se pode estabelecer sinonímia entre força expansiva e eficácia vinculante erga omnes a ponto de criar uma necessária relação de mútua dependência entre decisão com força expansiva e cabimento de reclamação. (...) Considerada apenas a situação jurídica existente à data da sua propositura, a presente reclamação não seria cabível. Ocorre, porém, que, no curso do seu julgamento, foi editada a Súmula Vinculante 26, (...). Assim, considerado esse fato superveniente - a edição de súmula vinculante, cujo descumprimento enseja a propositura de reclamação, fato esse que deve ser levado em consideração, nos termos do art. 462 do CPC - a solução que hoje se impõe é a de conhecer e deferir o pedido.","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"[ Rcl 4.335 , rel. min. Gilmar Mendes , voto-vista do min. Teori Zavascki , P, j. 20-3-2014, DJE 208 de 22-10-2014.]","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"Confirmo, então, que o centrado desafio temático deste voto é saber se a proibição estabelecida pela nova lei, isto é, a Lei 11.343/2006, encontra ou não encon-tra suporte no sistema de comandos da CF/1988. O que demandará elaboração teórica mais cuidadosa para a perfeita compreensão da natureza e do alcance da garantia constitucional da individualização da pena. (...) 13. Leia-se a figura do crime hediondo, tal como descrita no inciso XLIII do art. 5º da CF/1988: (...). 14. Daqui já se pode vocalizar um primeiro juízo técnico: em tema de vedações de benefícios penais ao preso, ou, então, ao agente penalmente condenado, o Magno Texto Federal impõe à lei que verse por modo igual os delitos por ele de pronto indicados como hediondos e outros que venham a receber a mesma tarja. Sem diferenciação entre o que já é hediondo por qualificação diretamente constitucional e hediondo por descrição legal. Isonomia interna de tratamento, portanto, antecipadamente assegurada pela nossa CF/1988. 15. Um novo e complementar juízo: embora o Magno Texto Federal habilite a lei para completar a lista dos crimes hediondos, a ela impôs um limite material: a não concessão dos benefícios da fiança, da graça e da anistia para os que incidirem em tais direitos. É como dizer, a própria norma constitucional cuidou de enunciar as restrições a serem impostas àqueles que venham a cometer as infrações penais adjetivadas de hediondas. Não incluindo nesse catálogo de restrições a vedação à conversão da pena privativa de liberdade em restritiva de direitos. Ponto pacífico. Percepção acima de qualquer discussão ou contradita. 16. Insista-se na ideia: no tema em causa, a Constituição da República fez clara opção por não admitir tratamento penal ordinário mais rigoroso do que o nela mesma previsto.","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"[ HC 97.256 , voto do rel. min. Ayres Britto , P, j. 1º-9-2010, DJE 247 de 16-12-2010.]","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"Possibilidade de determinação, de modo fundamentado, da realização de exame criminológico para qualquer categoria de delito","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"A Súmula Vinculante 26 não se restringe a uma categoria específica de delitos, visto que sua ratio decidendi reside na faculdade do juízo da execução de, mediante decisão fundamentada, avaliar as condições subjetivas do apenado.","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"[ Rcl 83.845 AgR , rel. min. Gilmar Mendes , 2ª T, j. 13-10-2025, DJE s/n 14-10-2025.]","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"Os requisitos para a progressão de regime não se restringem aos referidos no art. 112 da LEP","deleted":false}],"heading":false},{"page":120,"runs":[{"text":"(...) a jurisprudência desta Corte tem demonstrado que a análise dos requisitos necessários para a progressão de regime não se restringe ao referido art. 112 da LEP, tendo em vista que elementos outros podem e devem ser considerados pelo julgador na delicada tarefa de individualização da resposta punitiva do Estado, especialmente na fase executória. (...) 17. Nessa linha, recordo, por exemplo, a recente decisão adotada por este Plenário no julgamento de agravo regimental na EP 22, de que sou relator. Oportunidade em que esta Corte declarou a constitucionalidade do art. 33, § 4º, do Código Penal, no ponto em que impõe ao apenado a reparação do dano causado à administração pública como condição para a progressão no regime prisional. Essa condição não figura nos requisitos do art. 112 da LEP. 18. Um outro exemplo está na possibilidade de o Juízo da Execução Penal determinar a realização do exame criminológico para avaliar o preenchimento, pelo sentenciado, do requisito subjetivo indispensável à progressão no regime prisional. Embora o exame criminológico tenha deixado de ser obrigatório, com a edição da Lei 10.792/2003, que alterou o art. 112 da LEP, este Tribunal tem permitido “a sua utilização para a formação do convencimento do magistrado sobre o","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"direito de promoção para regime mais brando” (RHC 116.033, rel. min. Ricardo Lewandowski). Essa orientação, consolidada na Corte, deu origem à Súmula Vinculante 26 (...). 19. A análise desses julgados demonstra que o julgador, atento às finalidades da pena e de modo fundamentado, está autorizado a lançar mão de requisitos outros, não necessariamente enunciados no art. 112 da LEP, mas extraídos do ordenamento jurídico, para avaliar a possibilidade de progressão no regime prisional, tendo como objetivo, sobretudo, o exame do merecimento do sentenciado.","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"[ EP 12 ProgReg-AgR , voto do rel. min. Roberto Barroso , P, j. 8-4-2015, DJE 111 de 11-6-2015.]","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"Possibilidade de exame criminológico para apenados que cumprem pena por fatos praticados antes da vigência da Lei 14.843/2024","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"2. Destaco que a irretroatividade da Lei 14.843/2024 não impede que, mediante fundamentação adequada, o Juízo competente, nos termos da Súmula Vinculante 26, determine a submissão do apenado à realização do exame criminológico, a seu critério, mesmo para os apenados que já cumprem pena por fatos praticados antes da vigência da Lei.","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"[ RE 1.531.639 , rel. min. Flávio Dino , 1ª T, j. 25-4-2025, DJE s/n 30-4-2025.","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"Possibilidade de realização de exame criminológico para progressão de regime, desde que por decisão fundamentada","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"1. A jurisprudência desta Suprema Corte, consolidada no enunciado da Súmula Vinculante 26, reputa viável a realização do exame criminológico nas situações em que o Juiz da Execução, forte no exercício do poder geral de cautela, considerar necessário para a formação do seu convencimento. 2. O magistrado de primeiro grau, ao considerar a situação concreta do apenado, determinou, mediante decisão fundamentada, a realização de exame criminológico. 3. Inexistente, na hipótese, qualquer ato praticado pela autoridade reclamada capaz de afrontar o enunciado da Súmula Vinculante 26.","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"[ Rcl 32.788 AgR , rel. min. Rosa Weber , 1ª T, j. 22-3-2019, DJE 63 de 29-3-2019.]","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"Na hipótese, verifica-se que a decisão do Tribunal a quo, ao determinar a realização do exame criminológico, é baseada em dados objetivos e no histórico prisional do paciente, visto que considerado o atestado de bom comportamento. Assim, observo que o magistrado da origem não descumpriu o disposto na Súmula Vinculante 26. É fato que, apesar do silêncio da Lei 10.792/2003 a respeito do exame criminológico, o Juiz, sempre que entender necessário, poderá determiná-lo, desde que fundamentadamente, e as conclusões advindas poderão subsidiar a decisão de deferimento ou indeferimento da progressão de regime pleiteada. Tal motivação deve se embasar em elementos concretos do caso em análise, o que vejo que ocorreu no presente caso.","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"[ HC 163.219 , rel. min. Gilmar Mendes , dec. monocrática, j. 4-10-2018, DJE 214 de 8-10-2018.]","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"3. A decisão judicial que determina, diante de pleito de progressão de regime, a realização de exame criminológico de forma desfundamentada, como decorrência de construção argumentativa despida de elementos concretos relacionados à execução da pena do reclamante, viola o verbete sumular vinculante 26 desta Suprema Corte. 4. Inexistindo indicação de base empírica que revele a gravidade concreta do crime praticado, tampouco apontamento das razões pelas quais o condenado ostentaria personalidade criminosa, o pedido de progressão de regime deve ser analisado sem a exigência de realização prévia de exame criminológico. 5. Agravo regimental a que se dá provimento para determinar que o Juízo da Execução Penal aprecie a questão associada à progressão de regime do reclamante, abstendo-se de exigir a realização prévia do exame criminológico.","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"[ Rcl 29.527 AgR , rel. min. Dias Toffoli , red. p/ o ac. min. Edson Fachin , 2ª T, j. 7-8-2018, DJE 221 de 17-10-2018.]","deleted":false}],"heading":false},{"page":121,"runs":[{"text":"A progressão de regime visa a propiciar a ressocialização do preso, possibilitando que no futuro ele possa se reintegrar à sociedade. Em casos de crimes graves, praticados com violência ou grave ameaça ou que","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"importem em lesão significativa à sociedade, é razoável exigir-se, antes de decisão sobre a progressão de regime, laudo de exame criminológico para que o julgador disponha de melhores informações acerca das condições do preso para transferência a um regime mais brando de cumprimento de pena. Não se justifica correr o risco de reintegrar à sociedade preso por crimes gravíssimos ainda não preparado para o convívio social. Então a exigência do laudo criminológico, por meio de decisão fundamentada, como medida prévia à avaliação judicial quanto à progressão de regime, nada tem de ilegal.","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"[ HC 111.830 , voto da rel. min. Rosa Weber , 1ª T, j. 18-12-2012, DJE 31 de 18-2-2013.]","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"O silêncio da lei, a respeito da obrigatoriedade do exame criminológico, não inibe o juízo da execução do poder determiná-lo, desde que fundamentadamente. Isso porque a análise do requisito subjetivo pressupõe a verificação do mérito do condenado, que não está adstrito ao “bom comportamento carcerário”, como faz parecer a literalidade da lei, sob pena de concretizar-se o absurdo de transformar o diretor do presídio no verdadeiro concedente do benefício e o juiz em simples homologador, como assentado na ementa do Tribunal a quo .","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"[ HC 106.678 , rel. min. Marco Aurélio , red. p/ o ac. min. Luiz Fux , 1ª T, j. 28-2-2012, DJE 74 de 17-4-2012.]","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"Com efeito, não obstante o advento da Lei 10.792/2003, que alterou o art. 112 da LEP - para dele excluir a referência ao exame criminológico -, nada impede que os magistrados determinem a realização de mencionado exame, quando o entenderem necessário, consideradas as eventuais peculiaridades do caso, desde que o façam, contudo, em decisão adequadamente motivada, tal como tem sido expressamente reconhecido pelo E. Superior Tribunal de Justiça (...). A razão desse entendimento apoia-se na circunstância de que, embora não mais indispensável, o exame criminológico - cuja realização está sujeita à avaliação discricionária do magistrado competente - reveste-se de utilidade inquestionável, pois propicia “ao juiz, com base em parecer técnico, uma decisão mais consciente a respeito do benefício a ser concedido ao condenado” (RT 613/278). Cumpre registrar, por oportuno, que o entendimento exposto nesta decisão encontra apoio em julgamentos emanados do Supremo Tribunal Federal (...) nos quais se reconheceu que, em tema de progressão de regime nos crimes hediondos (ou nos delitos a estes equiparados), cabe, ao Juízo da execução, proceder à análise dos demais requisitos, inclusive daqueles de ordem subjetiva, para decidir, então, sobre a possibilidade, ou não, de o condenado vir a ser beneficiado com a progressão para regime mais brando de cumprimento de pena, sendo lícito, ainda, ao juiz competente, se o julgar necessário, ordenar a realização do exame criminológico (...).","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"[ HC 101.316 , voto do rel. min. Celso de Mello , 2ª T, j. 22-6-2010, DJE 231 de 26-11-2012.]","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"Vedação da aplicação de lei penal mais gravosa em matéria relacionada à progressão de regime durante a execução da pena","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"No que se refere à tese de que o pedido de progressão de regime deu-se na vigência da Lei nº 14.843/2024, que reinseriu na legislação de regência a necessidade de realização do exame criminológico para fins de progressão de regime, com a nova redação dada ao § 1° do art. 112 da Lei nº 7.210/1984 (Lei de Execução Penal), importa destacar que a jurisprudência desta Suprema Corte veda a aplicação de lei penal mais gravosa inclusive em matéria relacionada à progressão de regime durante a execução da pena, como ocorre no caso dos autos.","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"[ Rcl 75.429 AgR , rel. min. Edson Fachin , 2ª T, j. 1º-9-2025, DJE s/n 13-10-2025.","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":122,"runs":[{"text":"● Vide Súmula 698.","deleted":false}],"heading":false},{"page":122,"runs":[{"text":"● Vide PSV 119, com proposta de redação de nova Súmula Vinculante, com o seguinte verbete: “É inconstitucional o art. 2º, § 1º, da Lei 8.072/1990, na redação dada pela Lei 11.464/2007, sendo vedado ao juiz fixar regime inicial fechado de forma automática, apenas por se tratar de crime hediondo ou equiparado, o que","deleted":false}],"heading":false},{"page":123,"runs":[{"text":"não impede o magistrado de fixar regime inicial mais severo, desde que o faça em razão de elementos concretos e individualizados, devidamente expressos na motivação, aptos a demonstrar a necessidade de maior rigor da pena privativa de liberdade.”","deleted":false}],"heading":false},{"page":123,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 59, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":123,"runs":[{"text":"Data de publicação do enunciado: DJE de 23-12-2009.","deleted":false}],"heading":false},{"page":123,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":123,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"27","number":"27","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":124,"endPage":125,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1274","paragraphs":[{"page":124,"runs":[{"text":"Compete à Justiça Estadual julgar causas entre consumidor e concessionária de serviço público de telefonia, quando a ANATEL não seja litisconsorte passiva necessária, assistente, nem opoente.","deleted":false}]}],"notes":[{"page":124,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":124,"runs":[{"text":"O litisconsórcio necessário estabelece-se pela natureza da relação jurídica ou por determinação legal, sendo insuficiente, para a sua caracterização, que a decisão a ser proferida no processo possa produzir efeitos sobre esfera jurídica de terceiro. A eficácia natural das sentenças, como regra, alcança terceiros, sem que esta circunstância obrigue à respectiva inclusão no processo. (...) Não há disposição expressa de lei a obrigar à formação de litisconsórcio, no caso em exame. Não exige a lei a participação da Anatel nas ações em que sejam parte as operadoras de telefonia e os consumidores. Também não resulta a pretendida obrigatoriedade do litisconsórcio, da natureza da relação jurídica. (...) Discute-se nos autos, conforme a lide delimitada na inicial, a relação entre o consumidor do serviço de telefonia e a concessionária, mais especificamente se há possibilidade de cobrança dos chamados “pulsos referentes a ligações locais além da franquia”. Não é a Anatel parte na relação de consumo. Ainda que o acolhimento do pleito do autor, ora recorrido, possa repercutir, em tese, jurídica ou economicamente, na relação mantida entre a concessionária e a Anatel - contrato de concessão, a exigir eventual ajuste nas bases da própria concessão, é certo que esta repercussão não decorre diretamente do resultado individual da presente lide e que o consumidor não mantém relação jurídica com a Anatel. Também não é da natureza da relação de consumo a participação direta de um ente fiscalizatório e normatizador.","deleted":false}],"heading":false},{"page":124,"runs":[{"text":"[ RE 571.572 , voto do rel. min. Gilmar Mendes , P, j. 8-10-2008, DJE 30 de 13-2-2009.]","deleted":false}],"heading":false},{"page":124,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":124,"runs":[{"text":"Competência da Justiça estadual e causas entre consumidor e concessionária de serviço público de telefonia","deleted":false}],"heading":false},{"page":124,"runs":[{"text":"Em prosseguimento, tem-se que o Plenário desta Corte, em sessão realizada por meio eletrônico, concluiu, no exame do RE 567.454/BA, relator o ministro Ayres Britto, pela existência da repercussão geral da matéria constitucional versada nestes autos. No julgamento do mérito do recurso, o Plenário do Supremo Tribunal Federal decidiu que o processamento e o julgamento dos feitos em que se discute a possibilidade da cobrança de tarifa de assinatura básica mensal de serviço de telefonia fixa estão no âmbito da competência da Justiça comum, inclusive na esfera dos juizados especiais.","deleted":false}],"heading":false},{"page":124,"runs":[{"text":"[ AI 740.217 , rel. min. Dias Toffoli , dec. monocrática, j. 7-2-2012, DJE 39 de 27- 2-2012.]","deleted":false}],"heading":false},{"page":124,"runs":[{"text":"Caso em que não se está a discutir o contrato de concessão entre a agência reguladora e a concessionária de serviço público. A controvérsia não vincula senão o consumidor e a concessionária de serviço de telefonia. De mais a mais, a agência reguladora Anatel não manifestou, expressamente, interesse na solução da controvérsia. Pelo que não há falar de interesse, jurídico ou econômico, da Anatel. 2. A questão alusiva à cobrança da assinatura básica é unicamente de direito e não apresenta complexidade apta a afastar o seu processamento pelo Juizado Especial. 3. Entendimento diverso do adotado pela instância judicante de origem demandaria o reexame da legislação infraconstitucional, notadamente o CDC/1990.","deleted":false}],"heading":false},{"page":124,"runs":[{"text":"[ AI 611.358 AgR , rel. min. Ayres Britto , 2ª T, j. 23-11-2010, DJE 41 de 2-3-2011.]","deleted":false}],"heading":false},{"page":125,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":125,"runs":[{"text":"● Vide Súmula 517.","deleted":false}],"heading":false},{"page":125,"runs":[{"text":"Data de publicação do enunciado: DJE de 11-12-2009.","deleted":false}],"heading":false},{"page":125,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":125,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"28","number":"28","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":126,"endPage":127,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1278","paragraphs":[{"page":126,"runs":[{"text":"É inconstitucional a exigência de depósito prévio como requisito de admissibilidade de ação judicial na qual se pretenda discutir a exigibilidade de crédito tributário.","deleted":false}]}],"notes":[{"page":126,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":126,"runs":[{"text":"O art. 19 da Lei 8.870/1994 impõe condição à propositura das ações cujo objeto seja a discussão de créditos tributários. Consubstancia barreira ao acesso ao Poder Judiciário. 2. Ação direta de inconstitucionalidade julgada procedente.","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"[ ADI 1.074 , rel. min. Eros Grau , P, j. 28-3-2007, DJE 23 de 25-5-2007.]","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":126,"runs":[{"text":"● Não viola o princípio da isonomia e o livre acesso à jurisdição a restrição de ingresso no parcelamento de dívida relativa à Contribuição para Financiamento da Seguridade Social - COFINS, instituída pela Portaria 655/1993, dos contribuintes que questionaram o tributo em juízo com depósito judicial dos débitos tributários.","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"[Tese definida no RE 640.905 , rel. min. Luiz Fux , P, j. 15-12-2016, DJE 18 de 1º-2-2018, Tema 573.]","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":126,"runs":[{"text":"Exigência de depósito recursal prevista no art. 1007, §4º do NCPC e afastamento da Súmula Vinculante 28","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"O parâmetro de confronto invocado é a Súmula Vinculante 28 (...), o paradigma tido como violado trata exclusivamente da cobrança de depósito como uma espécie de condição ou requisito para o processamento da ação inicial, o que \"limitará o próprio acesso à primeira instância\", como dito pelo Ministro REZEK. Assim, a presente reclamação é manifestamente improcedente, pois não se ajusta ao contexto do parâmetro de controle acima transcrito. Verifico, no ato impugnado, que a controvérsia dos autos gira em torno de decisão que determinou o recolhimento do preparo recursal, sob pena de deserção, conforme art. 1007, § 4º do CPC/2015, tema distinto ao objeto de análise da Súmula Vinculante 28. Nessas circunstâncias, em que não se tem presente o contexto específico do Enunciado 28, não há estrita aderência entre o ato impugnado e o paradigma invocado. É, portanto, inviável a presente reclamação.","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"[ Rcl 29.926 , rel. min. Alexandre de Moraes , dec. monocrática, j. 14-6-2018, DJE 121 de 19-6-2018.]","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"Garantia do juízo para recebimento dos embargos à execução fiscal e afastamento da Súmula Vinculante 28","deleted":false}],"heading":false},{"page":126,"runs":[{"text":"Conforme consignado na decisão embargada, não se verifica similitude entre o decidido no ato reclamado - que, com base no art. 16, § 1º, da Lei 6.830/1980, assentou a inadmissibilidade dos embargos do executado antes de garantida a execução - e o assentado por esta Corte na Súmula Vinculante 28 (...). Nesses termos, mostra-se inviável a invocação da Súmula Vinculante 28 para afastar a exigência de garantia do juízo nos embargos à execução fiscal. Cabe ressaltar que o enunciado da referida súmula se refere às ações judiciais que têm por objeto qualquer etapa do fluxo de constituição e de positivação do crédito tributário antecedente ao ajuizamento da ação de execução fiscal, momento em que ocorre a judicialização do inadimplemento do sujeito passivo. (...) A rigor, a aplicação da referida súmula às execuções fiscais implicaria a declaração de não recepção do art. 16, § 1º da Lei 6.830/1980, sem a observância do devido processo legal (Rcl 6.735 AgR, rel.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Min. Ellen Gracie, Pleno, DJ e de 10.09.2010). Além disso, não há nenhuma indicação de circunstância excepcional a apontar ser a garantia do juízo exigida pela Lei de Execuções Fiscais barreira intransponível ao direito de acesso à jurisdição.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"[ Rcl 32.139 ED , rel. min. Gilmar Mendes , dec. monocrática, j. 17-12-2018, DJE 272 de 19-12-2018.]","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"(...) Verifica-se que a controvérsia gira em torno do depósito recursal enquanto pressuposto processual, objetivo específico dos recursos trabalhistas interpostos exclusivamente pelo reclamado empregador, desde que haja condenação pecuniária. Possui, portanto, natureza jurídica de garantia do juízo, objetivando assegurar futura execução, tal qual o depósito nos embargos à execução fiscal, já reconhecido excepcionado do alcance do Enunciado Vinculante 28 (Rcl 20.617 AgR, Rel. Min. Roberto Barroso, Primeira Turma, julgado em 2/2/2016).","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"[ Rcl 28.327 , rel. min. Alexandre de Moraes , dec. monocrática, j. 11-10-2017, DJE 244 de 25-10-2017.]","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Assim, ao contrário do que sustenta a inicial, a decisão reclamada não está propriamente a exigir depósito, e sim garantia da execução, gênero do qual o depósito é apenas uma espécie, como se vê do art. 9º da Lei 6.830/1980 e do art. 655 do CPC/1973. Eventual rejeição de bens ofertados, por iliquidez, não pode ser equiparada à exigência de depósito prévio e pode ser objeto de questionamento na sede própria, valendo observar que reclamação não é sucedâneo recursal. 5. Nessas circunstâncias, mostra-se inviável a invocação da Súmula Vinculante 28 para afastar a exigência de garantia do juízo nos embargos à execução fiscal. Observe-se que adotar interpretação em sentido diverso implicaria o reconhecimento, em sede de reclamação constitucional, da não recepção do art. 16, § 1º, da Lei 6.830/1980, entendimento nunca afirmado pelo Plenário desta Corte. 6. Assim, não há relação de estrita identidade entre o ato reclamado e a súmula vinculante cuja autoridade a parte reclamante alega ter sido violada, o que torna inviável a reclamação.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"[ Rcl 20.617 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 2-2-2016, DJE 34 de 24-2-2016.]","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Nesta reclamação, de outra banda, o ora agravante se insurge contra decisão que determinou sua inclusão no polo passivo de execução fiscal. Questiona a exigência de garantia do juízo para o ajuizamento de embargos à execução, conforme previsão do art. 16, § 1º, da Lei 6.830/1980, que é coisa diversa daquela versada na Súmula Vinculante 28. O art. 9º do mesmo diploma legal prevê as seguintes formas de garantia do juízo (...). O que pretende o reclamante, em última aná- lise, é a declaração de inconstitucionalidade do art. 16, § 1º, da Lei 6.830/1980, providência inviável na estreita via da reclamação.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"[ Rcl 19.724 AgR , voto do rel. min. Luiz Fux , 1ª T, j. 17-3-2015, DJE 64 de 7-4-2015.]","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":127,"runs":[{"text":"● Vide Súmula Vinculante 21.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-2-2010.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":127,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"29","number":"29","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":128,"endPage":130,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1282","paragraphs":[{"page":128,"runs":[{"text":"É constitucional a adoção, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e outra.","deleted":false}]}],"notes":[{"page":128,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":128,"runs":[{"text":"Além disso, no que diz respeito ao argumento da utilização de base de cálculo própria de impostos, o Tribunal reconhece a constitucionalidade de taxas que, na apuração do montante devido, adote um ou mais dos elementos que compõem a base de cálculo própria de determinado imposto, desde que não se verifique identidade integral entre uma base e a outra. (...) O que a CF/1988 reclama é a ausência de completa identidade com a base de cálculo própria dos impostos e que, em seu cálculo, se verifique uma equivalência razoável entre o valor pago pelo contribuinte e o custo individual do serviço que lhe é prestado.","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"[ RE 576.321 QO-RG , voto do rel. min. Ricardo Lewandowski , P, j. 4-12-2008, DJE 30 de 13-2-2009, Tema 146.]","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":128,"runs":[{"text":"● (...) III - É constitucional a adoção, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e outra.","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"[Tese definida no RE 576.321 QO-RG , rel. min. Ricardo Lewandowski , P, j. 4-12-2008, DJE 30 de 13-2-2009, Tema 146.]","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"1. É inadequada a tomada de elementos estranhos à atividade estatal na base de cálculo das taxas, cujos valores devem traduzir correlação entre o custo da atividade estatal desenvolvida e os serviços públicos prestados (ADIs 6.211 e 5.374, Tema n. 146/RG e enunciados vinculantes n. 19 e 29 da Súmula).","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"[ARE 1.436.993 AGR, rel. min. Nunes Marques, P, j. 30-9-2024, DJE s/n de 16-10-2024.]","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"(...) observo que o Plenário do Supremo Tribunal Federal, resolvendo questão de ordem formulada no RE 576.321 RG-QO/SP, Rel. Min. Ricardo Lewandowski, nele proferiu decisão que torna acolhível a pretensão deduzida no presente recurso extraordinário. Em consequência do referido julgamento, o Pleno desta Suprema Corte formulou os enunciados consubstanciados nas Súmulas Vinculantes nºs 19 e 29, (...). Cabe destacar, por relevante, no que concerne à questão da compatibilidade, ou não, com o texto da Carta da República, da taxa de coleta de lixo domiciliar que utiliza a área do imóvel como elemento definidor do seu valor, que essa controvérsia jurídica já foi dirimida por ambas as Turmas do Supremo Tribunal Federal “(...) 5. O Supremo Tribunal Federal firmou o entendimento no sentido da constitucionalidade da utilização da área do imóvel como base de cálculo da taxa de coleta de lixo domiciliar. Incidência da Súmula Vinculante 29. 6. Agravos regimentais não providos.” (RE 901.412 AgR/BA, Rel. Min. Dias Toffoli) (...) 2. A jurisprudência do Supremo Tribunal Federal consolidou-se no sentido da constitucionalidade da cobrança de taxa de coleta de lixo domiciliar, com base de cálculo atrelada à área do imóvel. 3. Agravo interno a que se nega provimento.” (RE 965.594 AgR/SP, Rel. Min. Roberto Barroso).","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"[ RE 1.165.562 , rel. min. Celso de Mello , dec. monocrática, j. 20-11-2018, DJE 252 de 27-11-2018.]","deleted":false}],"heading":false},{"page":128,"runs":[{"text":"A pretensão recursal merece acolhida. (...) o Supremo Tribunal Federal, no julgamento do RE 576.321 RG-QO/SP (Tema 146 da Repercussão Geral), de minha relatoria, ratificou a jurisprudência desta Corte no sentido da constitucionalidade das taxas cobradas exclusivamente em razão dos serviços públicos de coleta,","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, bem como assentou a legitimidade da adoção, no cálculo do valor da taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e a outra. Ressalte-se, ainda, que o Plenário desta Corte, com apoio no referido julgamento, aprovou as Súmulas Vinculantes 19 e 29 (...). Além disso, observo que no julgamento do RE 576.321 RG-QO/SP, de minha relatoria, asseverei que, no cálculo das taxas, não há como se exigir correspondência precisa com o valor despendido na prestação do serviço, ou, ainda, a adoção de fatores exclusivamente vinculados ao seu custo. Basta uma equivalência razoável entre o valor pago pelo contribuinte e o custo individual do serviço que lhe é prestado.","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"[ RE 1.047.556 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 25-5-2017, DJE 114 de 31-5-2017.]","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"O acórdão do Tribunal de origem divergiu da jurisprudência firmada no Tema 146 da sistemática da repercussão geral, logo deve ser reformado. Precedente: RE 576.321 RG, de relatoria do ministro Ricardo Lewandowski, DJE de 26-3-2010. 3. A jurisprudência do Supremo Tribunal Federal consolidou-se no sentido da constitucionalidade da cobrança de taxa de coleta de lixo domiciliar, com base de cálculo atrelada à área do imóvel.","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"[ RE 971.511 AgR , rel. min. Edson Fachin , 1ª T, j. 14-10-2016, DJE 234 de 4-11-2016.]","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"(...) esta Corte consolidou o entendimento de que é constitucional a taxa de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, desde que essas atividades sejam completamente dissociadas de outros serviços públicos de limpeza realizados em benefício da população em geral. (...) No que se refere à alegação da impossibilidade de se ter a metragem do imóvel como base de cálculo da taxa em tela, o Supremo Tribunal Federal consignou a constitucionalidade da utilização da área do imóvel como base de cálculo do referido tributo. (...) Por fim, reafirmo que incidem no presente caso as Súmulas Vinculantes 19 e 29 (...).","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"[ RE 901.412 AgR , voto do rel. min. Dias Toffoli , 2ª T, j. 27-10-2015, DJE 249 de 11-12-2015.]","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"Conforme assinalado na decisão agravada, o acórdão recorrido está em conformidade com a jurisprudência desta Corte, que, no julgamento do RE 576.321 QO-RG/SP, de minha relatoria, manteve o entendimento pela constitucionalidade de taxas que, na apuração do montante devido, adotem um ou mais dos elementos da base de cálculo própria de determinado imposto, desde que não se verifique identidade integral entre uma base e outra.","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"[ RE 549.085 AgR , voto do rel. min. Ricardo Lewandowski , 2ª T, j. 23-8-2011, DJE 171 de 6-9-2011.]","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"As taxas que, na apuração do montante devido, adotem um ou mais elementos que compõem a base de cálculo própria de determinado imposto, desde que não se verifique identidade integral entre uma base e outra, são constitucionais (Súmula Vinculante 29 do STF).","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"[ RE 613.287 AgR , rel. min. Luiz Fux , 1ª T, j. 2-8-2011, DJE 159 de 19-8-2011.]","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":129,"runs":[{"text":"Ilegitimidade de taxa cobrada em razão de número de empregados","deleted":false}],"heading":false},{"page":129,"runs":[{"text":"A taxa é um tributo contraprestacional (vinculado) usado na remuneração de uma atividade específica, seja serviço ou exercício do poder de polícia e, por isso, não se atém a signos presuntivos de riqueza. As taxas comprometem-se tão somente com o custo do serviço específico e divisível que as motiva, ou com a atividade de polícia desenvolvida. 2. A base de cálculo proposta no art. 6º da Lei 9.670/1983 atinente à taxa de polícia se desvincula do maior ou menor trabalho ou atividade que o poder público se vê obrigado a desempenhar em decorrência da força econômica do contribuinte. O que se leva em conta, pois, não é a efetiva atividade do poder público, mas, simplesmente, um dado objetivo, meramente estimativo ou presuntivo de um ônus à Administração Pública. 3. No tocante à base de cálculo questionada nos autos, é de se notar que, no RE 88.327/SP, rel. min. Décio Miranda ( DJ de 28-9-1979), o Tribunal Pleno já havia assentado a ilegitimidade de","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"taxas cobradas em razão do número de empregados. Essa jurisprudência vem sendo mantida de forma mansa e pacífica.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"[ RE 554.951 , rel. min. Dias Toffoli , 1ª T, j. 15-10-2013, DJE 227 de 19-11-2013.]","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"Princípio da capacidade contributiva e base de cálculo de taxa de fiscalização","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"(...) o princípio da capacidade contributiva é também aplicável a essa modalidade de tributo, qual seja, à espécie tributária da taxa. Assim, é legítimo que o Estado se subsidie do conhecimento de determinada realidade do contribuinte, mesmo daquelas que possam adquirir conotação econômica, quando isso puder indicar, de alguma forma, uma atividade de fiscalização mais pronunciada. Essa, aliás, a principal mensagem entelada pela Súmula Vinculante 29, segundo a qual é constitucional a adoção, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e outra. E a razão a tanto está em que a base de cálculo dessa e de todas as demais espécies tributárias deve guardar necessariamente correlação com o fato gerador, sendo expressão material e quantitativa deste. (...) No presente julgamento, relevante notar que as legislações impugnadas determinaram a cobrança da TFRM [Taxa de Controle, Acompanhamento e Fiscalização das Atividades de Pesquisa, Lavra, Exploração e Aproveitamento de Recursos Minerários] em valor fixo correspondente a uma unidade fiscal incidente sobre cada tonelada de minério extraído. (...) A escolha do ato de extração dos recursos naturais, isto é, do volume de minério extraído, não o valor da operação de venda do mesmo, intrinsecamente atado à circulação do bem, resulta, com a incoincidência entre as bases de cálculo da TFRM e do ICMS, na tradução da higidez constitucional daquela.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"[ ADI 4.787 , rel. min. Luiz Fux , voto do min. Alexandre de Moraes , P, j. 1-8-2022, DJE 207 de 14-10-2022.]","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"2. Mesmo válida constitucionalmente a adoção do instituto, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto (Súmula Vinculante n. 29) exige-se do legislador equivalência razoável entre o custo real dos serviços e o montante que o contribuinte pode ser obrigado a pagar, tendo em vista a base de cálculo estabelecida pela lei e o quantum da alíquota por esta fixado. Precedentes. 3. A fixação do valor da taxa não pode se basear unicamente em elementos estranhos ao serviço prestado, afetos à condição da pessoa ou aos bens isoladamente considerados.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"[ ADI 3.775 , rel. min. Cármen Lúcia , P, j. 20-4-2020, DJE s/n 20-5-2020.]","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":130,"runs":[{"text":"● Vide Súmula Vinculante 19 e Súmula 595.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 146, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-2-2010.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":130,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"30","number":"30","scope":"main","kind":"vinculante","sectionId":"grupo-2","page":131,"endPage":131,"status":"pending","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=5780","paragraphs":[{"page":131,"runs":[{"text":"A Súmula Vinculante 30 está pendente de publicação.","deleted":false}]}],"notes":[]},{"id":"31","number":"31","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":132,"endPage":135,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1286","paragraphs":[{"page":132,"runs":[{"text":"É inconstitucional a incidência do imposto sobre serviços de qualquer natureza - ISS sobre operações de locação de bens móveis.","deleted":false}]}],"notes":[{"page":132,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":132,"runs":[{"text":"IMPOSTO SOBRE SERVIÇOS (ISS). LOCAÇÃO DE VEÍCULO AUTOMOTOR. INADMISSIBILIDADE, EM TAL HIPÓTESE, DA INCIDÊNCIA DESSE TRIBUTO MUNICIPAL. DISTINÇÃO NECESSÁRIA ENTRE LOCAÇÃO DE BENS MÓVEIS (OBRIGAÇÃO DE DAR OU DE ENTREGAR) E PRESTAÇÃO DE SERVIÇOS (OBRIGAÇÃO DE FAZER). IMPOSSIBILIDADE DE A LEGISLAÇÃO TRIBUTÁRIA MUNICIPAL ALTERAR A DEFINIÇÃO E O ALCANCE DE CONCEITOS DE DIREITO PRIVADO (CTN/1966, ART. 110). INCONSTITUCIONALIDADE DO ITEM 79 DA ANTIGA LISTA DE SERVIÇOS ANEXA AO DL 406/1968. PRECEDENTES DO SUPREMO TRIBUNAL FEDERAL. RECURSO IMPROVIDO. Não se revela tributável, mediante ISS, a locação de veículos automotores (que consubstancia obrigação de dar ou de entregar), eis que esse tributo municipal somente pode incidir sobre obrigações de fazer, a cuja matriz conceitual não se ajusta a figura contratual da locação de bens móveis.","deleted":false}],"heading":false},{"page":132,"runs":[{"text":"[ RE 446.003 AgR , rel. min. Celso de Mello , 2ª T, j. 30-5-2006, DJ de 4-8-2006.]","deleted":false}],"heading":false},{"page":132,"runs":[{"text":"TRIBUTO. FIGURINO CONSTITUCIONAL. A supremacia da Carta Federal é conducente a glosar-se a cobrança de tributo discrepante daqueles nela previstos. Imposto Sobre Serviços. Contrato de locação. A terminologia constitucional do Imposto Sobre Serviços revela o objeto da tributação. Conflita com a Lei Maior dispositivo que imponha o tributo considerado contrato de locação de bem móvel. Em Direito, os institutos, as expressões e os vocábulos têm sentido próprio, descabendo confundir a locação de serviços com a de móveis, práticas diversas regidas pelo Código Civil/1916, cujas definições são de observância inafastável - art. 110 do CTN/1966.","deleted":false}],"heading":false},{"page":132,"runs":[{"text":"[ RE 116.121 , rel. min. Octavio Gallotti , red. p/ o ac. min. Marco Aurélio , P, j. 11-10-2000, DJ de 25-5-2001.]","deleted":false}],"heading":false},{"page":132,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":132,"runs":[{"text":"● As operadoras de planos privados de assistência à saúde (plano de saúde e seguro-saúde) realizam prestação de serviço sujeita ao Imposto Sobre Serviços de Qualquer Natureza (ISSQN), previsto no art. 156, III, da CRFB/1988.","deleted":false}],"heading":false},{"page":132,"runs":[{"text":"[Tese definida no RE 651.703 , rel. min. Luiz Fux , P, j. 29-9-2016, DJE 86 de 26-4-2017, Tema 581.]","deleted":false}],"heading":false},{"page":132,"runs":[{"text":"(...) a Suprema Corte, no julgamento dos RE 547.245 e RE 592.905, ao permitir a incidência do ISSQN nas operações de leasing financeiro e leaseback , sinalizou que a interpretação do conceito de “serviços” no texto constitucional tem um sentido mais amplo do que tão somente vinculado ao conceito de “obrigação de fazer”, vindo a superar seu precedente no RE 116.121, em que decidira pela adoção do conceito de serviço sinteticamente eclipsada numa obrigação de fazer. (...) A finalidade dessa classificação (obrigação de dar e obrigação de fazer) escapa totalmente àquela que o legislador constitucional pretendeu alcançar, ao elencar os serviços no texto constitucional tributáveis pelos impostos (por exemplo, serviços de comunicação - tributáveis pelo ICMS; serviços financeiros e securitários - tributáveis pelo IOF; e, residualmente, os demais serviços de qualquer natureza - tributáveis pelo ISS), qual seja, a de captar todas as atividades empresariais cujos produtos fossem serviços, bens imateriais em contraposição aos bens materiais, sujeitos a remuneração no mercado. (...) Sob este ângulo, o conceito de prestação de serviços não tem por premissa a configuração dada pelo Direito Civil, mas relacionado ao oferecimento de uma utilidade para outrem, a partir de um conjunto de","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"atividades imateriais, prestados com habitualidade e intuito de lucro, podendo estar conjugada ou não com a entrega de bens ao tomador. (...) A LC 116/2003 teve por objetivo ampliar o campo de incidência do Imposto Sobre Serviço, principalmente no sentido de adaptar a sua anexa lista de serviços à realidade atual, relacionando numerosas atividades que não constavam dos atos legais antecedentes. (...) Ao longo dos anos a jurisprudência das cortes superiores evoluiu quanto ao entendimento acerca da tributação dos serviços médicos no que concerne à tributação do ISSQN. (...) A atualização da legislação vigente pela LC 116/2003 provocou a evolução da jurisprudência dos tribunais superiores ( overruling ), ao adotar-se a interpretação de que “existe a previsão de incidência do Imposto Sobre Serviços tanto sobre a atividade dos profissionais de medicina, quanto a atividade de fornecimento de planos de saúde e assistência médico-hospitalar” (...). Assentadas as premissas teóricas, impõe-se na repercussão geral a aplicação da tese ao caso concreto.","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"[ RE 651.703 , voto do rel. min. Luiz Fux , P, j. 29-9-2016, DJE 86 de 26-4-2017, Tema 581.]","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"● É inconstitucional a incidência do Imposto sobre Serviços de Qualquer Natureza (ISS) sobre operações de locação de bens móveis, dissociada da prestação de serviços.","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"[Tese definida no RE 626.706 , rel. min. Gilmar Mendes , P, j. 8-9-2010, DJE 179 de 24-9-2010, Tema 212.]","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"4. É certo que, nos debates travados ao exame da Proposta de Súmula Vinculante 35, que resultou na SV 31, suscitada dúvida no Plenário desta Corte quanto à situação em que a locação de bens móveis está associada à prestação de serviços, tendo-se concluído pela exclusão do termo “dissociadas da prestação de serviços”, uma vez não analisada a questão relativa aos contratos mistos. (...) 6. Em relações contratuais complexas ou mistas, apenas há falar em descumprimento da Súmula Vinculante 31 quando a locação de bem móvel esteja evidentemente dissociada da prestação de serviços, seja em relação ao objeto, seja no tocante ao valor detalhado da contraprestação financeira. (...) 8. Não há falar, pois, em contrariedade à Súmula Vinculante 31, que não contempla contratos mistos - locação de bens móveis acompanhado de prestação de serviço. 9. Verifica-se da sentença trazido pelo reclamante que, ao analisar o caso concreto, entendeu o Juízo de origem que as atividades prestadas não são apartadas, visto que, além da locação dos aparelhos de audiovisual, são disponibilizados os operadores, na prestação de serviço. (...) 13. Com essas ponderações, não estou a defender a impossibilidade de adequação da base de cálculo do ISS para dela excluir o valor relativo à locação do bem móvel, quando passível de delimitação. Estou simplesmente consignando que nada colhe a ação de reclamação constitucional para tal desiderato, à falta de jurisprudência consolidada nesse sentido. É que a verificação de possibilidade ou não de cisão da locação de bens móveis da prestação de serviços se dá com base no acervo fático-normativo do processo principal, matéria não sujeita à apreciação pela via da reclamação constitucional.","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"[ Rcl 28.324 , rel. min. Rosa Weber , dec. monocrática, j. 25-5-2018, DJE 107 de 30-5-2018.]","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"(...) verifico que o acórdão recorrido está em conformidade com a Súmula Vinculante 31 e no julgamento do RE-RG 626.706 (tema 212 da repercussão geral), no sentido de que é inconstitucional a incidência de ISSQN sobre as locações puras de bens móveis, em que não há prestação de serviço associada.","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"[ ARE 1.082.875 , rel. min. Roberto Barroso , dec. monocrática, j. 26-10-2017, DJE 250 de 31-10-2017.]","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"(...) o ato reclamado não representa violação ao enunciado sumular de índole vinculante apontado como paradigma, porquanto a interpretação conferida converge à jurisprudência do STF, segundo a qual o ISS só incide na parte correspondente à prestação de serviços nas operações denominadas mistas, isto é, quando abarca obrigações de dar e de fazer. Por outro lado, eventual impossibilidade de cisão dos serviços de locação de bens móveis e dos demais gatos geradores do ISSQN com base no acervo fático-normativo do processo principal não é matéria sujeita à apreciação desta Corte na estreita via da reclamação constitucional.","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"[ Rcl 24.917 , rel. min. Edson Fachin , dec. monocrática, j. 19-10-2016, DJE 226 de 24-10-2016.]","deleted":false}],"heading":false},{"page":133,"runs":[{"text":"Segundo entendimento desta Corte, o poder de tributar municipal não pode alterar o conceito de serviço consagrado pelo Direito Privado, consoante prevê o art. 110 do CTN/1966. Ademais, não há que se falar na","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"superação do entendimento da Súmula Vinculante 31 pelo advento da edição da LC 116/2003. É certo que a LC 116/2003 revogou a lista de serviço da legislação anterior e estabeleceu um novo rol de materialidades para o imposto. Na lista atual, a locação de bens móveis seria o item 3.01 (Locação de bens móveis) da lista de serviços tributáveis. Entretanto, a intenção do legislador não se confirmou por força do veto presidencial, que foi motivado pela orientação jurisprudencial desta Corte (...). 3. Também não merece prosperar o argumento de que há fortes indícios da superação do entendimento deste Tribunal a respeito da matéria em exame, uma vez que a jurisprudência permanece afirmando que não incide ISS sobre locação de bens móveis e que a CF/1988 não concede aos entes municipais da Federação a competência para alterar a definição e o alcance de conceitos de Direito Privado para fins de instituição do tributo.","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"[ RE 602.295 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 7-4-2015, DJE 75 de 23-4-2015.]","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"Na espécie, o imposto, conforme a própria nomenclatura, considerado o figurino constitucional, pressupõe a prestação de serviços e não o contrato de locação. Em face do texto da Carta Federal, não se tem como assentar a incidência do tributo na espécie, porque falta o núcleo dessa incidência, que são os serviços. Observem-se os institutos em vigor tal como se contêm na legislação de regência. As definições de locação de serviços e locação de móveis vêm-nos do Código Civil/2002. Em síntese, há de prevalecer a definição de cada instituto, e somente a prestação de serviços, envolvido na via direta o esforço humano, é fato gerador do tributo em comento. Prevalece a ordem natural das coisas cuja força surge insuplantável; prevalecem as balizas constitucionais, a conferirem segurança às relações Estado-contribuinte; prevalece, alfim, a organicidade do próprio Direito, sem a qual tudo será possível no agasalho de interesses do Estado, embora não enquadráveis como primários.","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"[ AI 623.226 AgR , voto do rel. min. Marco Aurélio , 1ª T, j. 1º-2-2011, DJE 46 de 11-3-2011.]","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"Tributário. Imposto Sobre Serviços (ISS). Não incidência sobre locação de bens móveis. Filmes cinematográficos, videoteipes, cartuchos para videogames e assemelhados. Súmula Vinculante 31. Art. 156, III, da Constituição Federal.","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"[ RE 626.706 , rel. min. Gilmar Mendes , P, j. 8-9-2010, DJE 179 de 24-9-2010, Tema 212.]","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":134,"runs":[{"text":"Cessão do direito de uso de marca e ISS","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"Por fim, ressalte-se que há alterações significativas no contexto legal e prático acerca da exigência de ISS, sobretudo após a edição da LC 116/2003, que adota nova disciplina sobre o mencionado tributo, prevendo a cessão de direito de uso de marcas e sinais na lista de serviços tributados, no item 3.02 do Anexo. Essas circunstâncias afastam a incidência da Súmula Vinculante 31 sobre o caso, uma vez que a cessão do direito de uso de marca não pode ser considerada locação de bem móvel, mas serviço autônomo especificamente previsto na LC 116/2003.","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"[ Rcl 8.623 AgR , voto do rel. min. Gilmar Mendes , 2ª T, j. 22-2-2011, DJE 45 de 10-3-2011.]","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"Incide o ISS a partir da cessão do espaço para sepultamento, uma vez configurada essa obrigação como mista","deleted":false}],"heading":false},{"page":134,"runs":[{"text":"(...) Nesse contexto, conforme consignado na decisão embargada, tratando-se de atividades mistas, primeiro deve-se verificar se estas estão elencadas no rol taxativo da Lei Complementar nº 116/2003 (ISS) e, não havendo sujeição expressa daquela atividade, residualmente passam a ser enquadradas na tributação pelo ICMS, sem olvidar as exceções expressas na lista em anexo àquela lei complementar. Assim, a legislação complementar de que trata o ISS é peça fundamental para aferir se as atividades mistas (fornecimento de mercadoria e prestação de serviços) se submetem ao referido imposto municipal ou se, de forma residual (expressa ou presumida), sujeitam-se ao ICMS. Nesses termos, reitera-se que no caso concreto não se exige que formalmente revisemos a Súmula Vinculante nº 31, uma vez que estamos diante de obrigações mistas, as","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"quais, conforme inúmeros precedentes desta Suprema Corte, encontram-se sujeitas ao ISS, desde que previstas em lei complementar. Em sendo assim, uma vez configurada a atividade como mista, não merece prosperar o argumento de que o ISS só poderia incidir após a efetiva ocorrência do sepultamento, eis que o item 25.05 trata da cessão do espaço em si, sendo o tributo devido - logicamente - a partir da cessão do espaço e não do sepultamento.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"[ ADI 5.869-ED , rel. min. Gilmar Mendes , P, j. 27-5-2023, DJE s/n de 9-6-2023.]","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Locação de bens móveis concomitante com prestação de serviço e ISS","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"A Súmula Vinculante 31, que assenta a inconstitucionalidade da incidência do Imposto sobre Serviços de Qualquer Natureza (ISS) nas operações de locação de bens móveis, somente pode ser aplicada em relações contratuais complexas se a locação de bens móveis estiver claramente segmentada da prestação de serviços, seja no que diz com o seu objeto, seja no que concerne ao valor específico da contrapartida financeira.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"[ Rcl 14.290 AgR , rel. min. Rosa Weber , P, j. 22-5-2014, DJE 118 de 20-6-2014.]","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"A Súmula Vinculante 31 não exonera a prestação de serviços concomitante à locação de bens móveis do pagamento do ISS. 2. Se houver ao mesmo tempo locação de bem móvel e prestação de serviços, o ISS incide sobre o segundo fato, sem atingir o primeiro. 3. O que a agravante poderia ter discutido, mas não o fez, é a necessidade de adequação da base de cálculo do tributo para refletir o vulto econômico da prestação de serviço, sem a inclusão dos valores relacionados à locação. Agravo regimental ao qual se nega provimento.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"[ ARE 656.709 AgR , rel. min. Joaquim Barbosa , 2ª T, j. 14-2-2012, DJE 48 de 8-3-2012.]","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Ocorre que a caracterização de parte da atividade como prestação de serviços não pode ser meramente pressuposta, dado que a constituição do crédito tributário é atividade administrativa plenamente vinculada, que não pode destoar do que permite a legislação (proibição do excesso da carga tributária) e o próprio quadro fático (motivação, contraditório e ampla defesa). (...) Assim, as autoridades fiscais não estão impedidas de exercer plenamente as faculdades que lhes confere a legislação para identificar precisamente quais receitas referem-se à prestação de serviços e quais receitas referem-se à isolada locação de bens móveis.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"[ AI 758.697 AgR , voto do rel. min. Joaquim Barbosa , 2ª T, j. 6-4-2010, DJE 81 de 7-5-2010.]","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Sublocação ou cessão secundária de direito de uso de espaços publicitários e ISS","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Em verdade, o Tribunal de origem entendeu que a sublocação de espaços para a veiculação de propaganda não poderia ser considerada agenciamento publicitário. (...) Conforme orientação consolidada da Súmula Vinculante 31, é inconstitucional a incidência do ISS sobre operação de locação de bens móveis. Ainda que o fato em exame fosse interpretado como cessão de direito, a mesma orientação apontada na Súmula Vinculante 31 seria aplicável. Portanto, o Tribunal de origem não afirmou pura e simplesmente que a lista de serviços não poderia ter interpretação extensiva. Tão somente examinou o quadro fático para lhe dar interpretação jurídica que não sofre a incidência do conceito de serviço de propaganda.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"[ AI 854.553 ED , voto do rel. min. Joaquim Barbosa , 2ª T, j. 28-8-2012, DJE 197 de 8-10-2012.]","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":135,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 212, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-2-2010.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":135,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"32","number":"32","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":136,"endPage":137,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1289","paragraphs":[{"page":136,"runs":[{"text":"O ICMS não incide sobre alienação de salvados de sinistro pelas seguradoras.","deleted":false}]}],"notes":[{"page":136,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":136,"runs":[{"text":"Incidência de ICMS na alienação, pela seguradora, de salvados de sinistro. 3. A alienação de salvados configura atividade integrante das operações de seguros e não tem natureza de circulação de mercadoria para fins de incidência do ICMS. 4. Inconstitucionalidade da expressão “e as seguradoras”, do inciso IV do art. 15 da Lei 6.763/1975, com redação dada pelo art. 1º da Lei 9.758/1989, do Estado de Minas Gerais. 5. Violação dos arts. 22, VII, e 153, V, da CF/1988.","deleted":false}],"heading":false},{"page":136,"runs":[{"text":"[ ADI 1.648 , rel. min. Gilmar Mendes , P, j. 16-2-2011, DJE 233 de 9-12-2011.]","deleted":false}],"heading":false},{"page":136,"runs":[{"text":"Registro que por vedação legal “As Sociedades Seguradoras não poderão explorar qualquer outro ramo de comércio ou indústria” (art. 73 do DL 73/1966), de maneira que elas não são e nem poderiam ser “comerciantes de ferro velho”. O que ocorre é que, por disposição contratual, as seguradoras recebem por ato unilateral a propriedade do bem nas hipóteses em que, em razão de sinistro, tenha perdido mais de 75% do valor segurado. Ressalto que as companhias de seguro são obrigadas a pagar ao segurado 100% do valor do bem. A posterior alienação dos salvados, pelas seguradoras, tem, quando muito, o condão de recuperar parcela da indenização que haja superado o dano ocorrido. Não há, dessa forma, finalidade de obter lucro, não havendo, portanto, intenção comercial. Este é o sentido da jurisprudência do Supremo Tribunal Federal, conforme se depreende do Enunciado 541 da Súmula do Tribunal (...). O objeto das operações das seguradoras é o seguro. A eventual alienação dos salvados não os torna mercadorias (...).","deleted":false}],"heading":false},{"page":136,"runs":[{"text":"[ RE 588.149 , voto do rel. min. Gilmar Mendes , P, j. 16-2-2011, DJE 107 de 6-6-2011.]","deleted":false}],"heading":false},{"page":136,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":136,"runs":[{"text":"ICMS na operação de saída do bem sinistrado da seguradora anterior à edição da Súmula Vinculante 32","deleted":false}],"heading":false},{"page":136,"runs":[{"text":"Como afirmado na decisão agravada, o que se pôs em foco nesta reclamação é se o Tribunal Administrativo de Recursos Fiscais do Estado do Rio Grande do Sul teria desrespeitado a Súmula Vinculante 32 do Supremo Tribunal Federal, ao inscrever a agravante na dívida ativa em razão de sua condenação no Processo 76487-14.00/10-4, no qual se reconheceu a incidência do Imposto sobre Circulação de Mercadorias e Serviços (ICMS) na operação de saída do bem sinistrado da seguradora. (...) Na espécie vertente, a decisão administrativa foi proferida pelo Tribunal Administrativo de Recursos Fiscais em 9-2-2011 (fl. 2, doc. 3) e a Súmula Vinculante 32 foi editada na sessão plenária de 16-2-2011, ou seja, posteriormente ao ato administrativo impugnado. Essa circunstância afasta a arguição de desrespeito a uma súmula vinculante até então inexistente. (...) Registre-se que a inscrição no cadastro da dívida ativa é ato jurídico que tem por objetivo legitimar a cobrança do crédito tributário pela Fazenda Pública, isto é, o crédito tributário é levado à inscrição como dívida ativa depois de definitivamente constituído. A dívida ativa tributária decorre de crédito tributário regularmente inscrito na repartição administrativa competente, depois de esgotado o prazo para pagamento fixado pela lei ou, como no caso dos autos, por decisão administrativa final proferida em processo regular, conforme dispõe o art. 201 do CTN/1966. A Súmula Vinculante 32 do Supremo Tribunal Federal apenas dispõe que “o ICMS não incide sobre alienação de salvados de sinistro pelas seguradoras”. Assim, não há identidade material entre a inscrição da agravante no cadastro da dívida ativa e o disposto na Súmula Vinculante 32 deste Supremo Tribunal, apontada como paradigma, conforme exige a jurisprudência do Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":137,"runs":[{"text":"[ Rcl 11.667 AgR , voto da rel. min. Cármen Lúcia , P, j. 30-6-2011, DJE 151 de 8-8-2011.]","deleted":false}],"heading":false},{"page":137,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":137,"runs":[{"text":"● Vide Súmula 541.","deleted":false}],"heading":false},{"page":137,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-2-2011.","deleted":false}],"heading":false},{"page":137,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":137,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"33","number":"33","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":138,"endPage":147,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1941","paragraphs":[{"page":138,"runs":[{"text":"Aplicam-se ao servidor público, no que couber, as regras do regime geral da previdência social sobre aposentadoria especial de que trata o artigo 40, § 4º, inciso III da Constituição Federal, até a edição de lei complementar específica.","deleted":false}]}],"notes":[{"page":138,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":138,"runs":[{"text":"A aposentadoria especial de servidor público portador de deficiência é assegurada mediante o preenchimento dos requisitos previstos na legislação aplicável à aposentadoria especial dos segurados do Regime Geral de Previdência Social, até que seja editada a lei complementar exigida pelo art. 40, § 4º, II, da CF/1988. (...) 2. A eficácia do direito à aposentadoria especial objeto do art. 40, § 4º, da CF/1988 exige regulamentação mediante lei complementar de iniciativa privativa do presidente da República, de modo que cabe ao Supremo Tribunal Federal, ex vi do art. 102, I, q , da Lei Maior, o julgamento do mandado de injunção impetrado com o objetivo de viabilizar o seu exercício.","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"[ MI 4.158 AgR-segundo , rel. min. Luiz Fux , P, j. 18-12-2013, DJE 34 de 19-2-2014.]","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"MANDADO DE INJUNÇÃO. APOSENTADORIA ESPECIAL DO SERVIDOR PÚBLICO. ART. 40, § 4º, DA CF/1988. AUSÊNCIA DE LEI COMPLEMENTAR A DISCIPLINAR A MATÉRIA. NECESSIDADE DE INTEGRAÇÃO LEGISLATIVA. 1. Servidor público. Investigador da polícia civil do Estado de São Paulo. Alegado exercício de atividade sob condições de periculosidade e insalubridade. 2. Reconhecida a omissão legislativa em razão da ausência de lei complementar a definir as condições para o implemento da aposentadoria especial. 3. Mandado de injunção conhecido e concedido para comunicar a mora à autoridade competente e determinar a aplicação, no que couber, do art. 57 da Lei 8.213/1991.","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"[ MI 795 , rel. min. Cármen Lúcia , P, j. 15-4-2009, DJE 94 de 22-5-2009.]","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":138,"runs":[{"text":"● Os guardas civis não possuem direito constitucional à aposentadoria especial por exercício de atividade de risco prevista no artigo 40, § 4º, inciso II, da Constituição Federal.","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"[Tese fixada no RE 1.215.727 RG , rel. min. Dias Toffoli, P, j. 29-8-2019, DJE 210 de 23-9-2019, Tema 1.057.]","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"3. O Supremo Tribunal Federal reitera que guardas municipais não têm direito à aposentadoria especial com base em atividade de risco, conforme o art. 40, § 4º, inc. II, da Constituição da República, uma vez que a periculosidade não é inerente à função desempenhada por essa categoria, conforme decidido no Tema de Repercussão Geral nº 1.057 (ARE nº 1.215.727-RG/SP). 4. A eventual exposição a situações de risco, como o porte de arma ou o recebimento de adicional de periculosidade, não confere, por si só, direito à aposentadoria especial, dada a autonomia entre o vínculo funcional e o previdenciário, conforme jurisprudência consolidada no Mandado de Injunção nº 6.770-AgR/DF.","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"[ RE 1.414.395 AGR , rel. min. André Mendonça , 2ª T, j. 9-9-2024, DJE de 28-10-2024.]","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"● Compete ao Supremo Tribunal Federal julgar mandado de injunção referente à omissão quanto à edição da lei complementar prevista no art. 40, § 4º, da Constituição de 1988.","deleted":false}],"heading":false},{"page":138,"runs":[{"text":"[Tese definida no RE 797.905 RG , rel. min. Gilmar Mendes , P, j. 15-5-2014, DJE 102 de 29-5-2014, Tema 727.]","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"Como se sabe, o Plenário do Supremo Tribunal Federal, ao formular a Súmula Vinculante 33/STF, firmou diretriz jurisprudencial cuja observância se impõe, em caráter obrigatório, aos órgãos e entes da Administração Pública federal, estadual, distrital e/ou municipal. (...) O conteúdo material da Súmula Vinculante 33/STF descaracteriza qualquer possível interesse processual da parte ora recorrente, pois, com sua superveniente formulação (e publicação), configurou-se típica hipótese de prejudicialidade, apta a legitimar a extinção do procedimento recursal (...). Cumpre ressaltar, finalmente, que o Plenário do Supremo Tribunal Federal, em diversos precedentes firmados sobre a matéria (...), salientou que, efetivada a integração normativa necessária ao exercício de direito pendente de disciplinação normativa, exaure-se a função jurídico-constitucional para a qual foi concebido (e instituído) o remédio constitucional do mandado de injunção (...).","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"[ MI 3.215 AgR-ED-AgR , voto do rel. min. Celso de Mello , P, j. 1º-8-2014, DJE 191 de 1º-10-2014.]","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"O governador do Estado não possui legitimidade para figurar no polo passivo de mandado de injunção sobre previdência dos servidores públicos, ante a necessidade da edição de norma regulamentadora de caráter nacional, cuja competência é da União. O Plenário do Supremo Tribunal Federal assentou a legitimidade do presidente da República para figurar no polo passivo de mandado de injunção sobre a matéria (RE 797.905 RG/SE, rel. min. Gilmar Mendes, unânime, DJE de 29-5-2014).","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"[ ARE 685.002 AgR-segundo , rel. min. Rosa Weber , 1ª T, j. 25-6-2014, DJE 159 de 19-8-2014.]","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"Assim, embora subsista a omissão legislativa (uma vez que não foi editada a lei complementar correspondente), o vácuo normativo não mais representa inviabilidade do gozo do direito à aposentadoria em regime especial pelos servidores públicos cujas atividades sejam exercidas sob condições especiais que prejudiquem a sua saúde ou a sua integridade física. Nessa conformidade, entendo que a edição da Súmula Vinculante 33 esvaziou o objeto da presente ação injuncional, porquanto tornou insubsistente o obstáculo ao exercício pelo servidor do direito de aposentar-se nos termos do art. 57 da Lei 8.213/1991.","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"[ MI 5.762 , rel. min. Dias Toffoli , dec. monocrática, j. 23-5-2014, DJE 101 de 28-5-2014.]","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"No que diz respeito à aposentadoria especial de servidores públicos que exerçam atividades sob condições prejudiciais à saúde ou à integridade física (CRFB/1988, art. 40, § 4º, III), a matéria já está pacificada por este Tribunal, tendo ficado caracterizada a omissão inconstitucional na hipótese. Nesse sentido, em 9-4-2014, o Plenário deste Tribunal aprovou a Súmula Vinculante 33 (...). 5. Nos termos do art. 103-A da Constituição, a referida súmula tem efeito vinculante em relação aos demais órgãos do Poder Judiciário e à Administração Pública direta e indireta, nas esferas federal, estadual e municipal. Eventual contrariedade à súmula enseja a propositura de reclamação perante o STF (CRFB/1988, art. 103- A, § 3º). 6. Assim, a parte autora não possui interesse processual para impetrar mandado de injunção, já que a autoridade administrativa não poderá alegar a ausência de lei específica para indeferir pedidos relativos à aposentadoria especial de servidores públicos que alegam exercer atividades sob condições prejudiciais à saúde ou à integridade física.","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"[ MI 6.323 , rel. min. Roberto Barroso , dec. monocrática, j. 2-5-2014, DJE 88 de 12-5-2014.]","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"Não obstante o disposto no art. 40, § 4º (a exigir “leis complementares” para a regulamentação das aposentadorias especiais em cada ente federado), e no art. 102, I, q , da Constituição (sobre a competência para mandados de injunção), o Plenário do Supremo Tribunal Federal decidiu que (a) a norma regulamentadora de que trata a inicial do mandado de injunção deve ser editada pela União, de modo que a legitimidade passiva nessa demanda é do presidente da República e (b) por essa razão, o STF é competente para os mandados de injunção envolvendo servidores públicos municipais, estaduais e distritais (...). 2. Por base nessa jurisprudência, em se tratando da matéria relativa à aposentadoria especial, enquanto não editada a lei reguladora nacional pelo presidente da República, os governadores de Estado não estão legitimados para figurar no polo passivo de mandado de injunção em tribunal estadual.","deleted":false}],"heading":false},{"page":139,"runs":[{"text":"[ ARE 678.410 AgR , rel. min. Ricardo Lewandowski , red. p/ o ac. min. Teori Zavascki , 2ª T, j. 19-11-2013, DJE 30 de 13-2-2014.]","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":140,"runs":[{"text":"Adequação de atividade de risco ou de atividade insalubre para fins de concessão de aposentadoria especial a servidor público","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"Como já demonstrado na decisão agravada, a Súmula Vinculante 33 concede o direito à aposentadoria especial àqueles que exercem atividades prejudiciais à saúde ou à integridade física (art. 40, § 4º, III, da Constituição Federal). Desse modo, tendo em vista que tais fatores degradantes não se revelam ínsitos à função de guarda municipal, inaplicável ao caso a referida súmula. Além disso, reitero que o Plenário desta Corte, por oportunidade do julgamento dos MIs 6.770, 6.773, 6.780 e 6.874, reconheceu não ter o legislador constitucional contemplado os guardas municipais com o direito à aposentadoria diferenciada, de modo que não se estende à classe o benefício da LC 51/1985. Com efeito, o entendimento firmado neste Tribunal é no sentido de que a eventual exposição dos guardas municipais e de outras categorias profissionais a riscos não configura direito subjetivo constitucional à aposentadoria especial.","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"[ ARE 1.133.887 AgR-segundo , rel. min. Gilmar Mendes , 2ª T, j. 12-3-2019, DJE 52 de 18-3-2019.]","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"1. Diante do caráter aberto da expressão atividades de risco (art. 40, § 4º, II, da Constituição) e da relativa liberdade de conformação do legislador, somente há omissão inconstitucional nos casos em que a periculosidade é inequivocamente inerente ao ofício. 2. A eventual exposição a situações de risco a que podem estar sujeitos os guardas municipais e, de resto, diversas outras categorias, não garante direito subjetivo constitucional à aposentadoria especial. 3. A percepção de gratificações ou adicionais de periculosidade, assim como o porte de arma de fogo, não são suficientes para reconhecer o direito à aposentadoria especial, em razão da autonomia entre o vínculo funcional e o previdenciário.","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"[ MI 6.770 AgR , rel. min. Alexandre de Moraes , red. p/ o ac. Roberto Barroso , P, j. 20-6-2018, DJE 251 de 26-11-2018.]","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"Cumpre assinalar, inicialmente, que o Plenário do Supremo Tribunal Federal, ao apreciar ação injuncional em que se pretendia a concessão de aposentadoria especial, não só reconheceu a mora do presidente da República ( mora agendi ) na apresentação de projeto de lei sobre a regulamentação do art. 40, § 4º, da Constituição, como, ainda, determinou a aplicação analógica do art. 57, § 1º, da Lei 8.213/1991, com o objetivo de colmatar a lacuna normativa existente (...). Registro, ainda, que esta Suprema Corte, em sucessivas decisões, reafirmou essa orientação (...) garantindo, em consequência, aos servidores públicos que se enquadrem nas hipóteses previstas nos incisos I, II e III do § 4º do art. 40 da Constituição (pessoa portadora de deficiência, exercício de atividades de risco ou execução de trabalhos em ambientes insalubres), o direito à aposentadoria especial (...). Cabe ressaltar, por necessário, que, diante do reconhecimento, em reiterados precedentes, da falta de integração normativa necessária ao exercício do direito à aposentadoria dos servidores “cujas atividades sejam exercidas sob condições especiais que prejudiquem a saúde ou a integridade física” (CF, art. 40, § 4º, III), o Supremo Tribunal Federal editou a Súmula Vinculante 33, garantindo-se, assim, a análise concreta do pedido de aposentadoria pela autoridade administrativa competente. Vê-se, desse modo, que o órgão ora reclamado, ao deixar de analisar o pleito do ora reclamante no sentido da concessão de aposentadoria especial por atividade desenvolvida em condições insalubres, desrespeitou o enunciado constante da Súmula Vinculante 33/STF. (...) julgo parcialmente procedente a presente reclamação, em ordem a determinar que a São Paulo Secretaria da Administração Penitenciária (CDP de Praia Grande) aprecie, concretamente, o pedido administrativo de aposentadoria especial formulado pelo ora reclamante, em conformidade com o enunciado constante da Súmula Vinculante 33/STF.","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"[ Rcl 22.202 , rel. min. Celso de Mello , dec. monocrática, j. 26-9-2016, DJE 207 de 28-9-2016.]","deleted":false}],"heading":false},{"page":140,"runs":[{"text":"(...) a atividade de agente penitenciário é reconhecida pelo STF como atividade de risco, não atividade insalubre, independentemente da qualificação atribuída ao adicional que lhe é pago pelo órgão ao qual o servidor é vinculado. Nesse contexto, não viola a Súmula Vinculante 33 o indeferimento da aposentadoria especial requerida pelo reclamante, já que no exercício da atividade de agente penitenciário não está sujeito a","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"condições insalubres, mas, sim, labora em uma atividade de risco inerente, tal como os policiais civis, cuja aposentadoria é regulamentada pela LC 51/1985, recepcionada pela Constituição Federal, consoante reiterada jurisprudência da Corte.","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"[ Rcl 23.780 , rel. min. Edson Fachin , dec. monocrática, j. 11-5-2016, DJE 97 de 13-5-2016.]","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"Nos termos do MI 833 e do MI 844, ambos de relatoria para o acórdão do ministro Roberto Barroso, a jurisprudência do STF firmou-se no sentido de que a expressão “atividade de risco”, contida no art. 40, § 4º, II, do Texto Constitucional, é aberta, de modo que os contornos de sua definição normativa comportam relativa liberdade de conformação por parte do Parlamento, desde que observado o procedimento das leis complementares. Logo, o estado de omissão inconstitucional ficaria restrito à indefinição das atividades em que o risco seja inerente, o que não se depreende da atividade dos oficiais de justiça. 2. A existência de gratificações ou adicionais de periculosidade para determinada categoria não garante o direito à aposentadoria especial, pois os vínculos funcional e previdenciário não se confundem.","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"[ MI 1.629 AgR , rel. min. Edson Fachin , P, j. 7-10-2015, DJE 214 de 27-10-2015.]","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"Competência da autoridade administrativa para verificar requisitos da aposentadoria especial","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"Saliento, ainda, que as decisões reiteradas em diversos Mandados de Injunção acarretaram na edição da Súmula Vinculante 33, permitindo, ainda, que o direito constitucional à aposentadoria especial seja também pleiteado na via reclamatória. Assim, somente haveria inobservância ao enunciado sumular caso a autoridade administrativa apontada estivesse se negando a apreciar o pedido de aposentadoria especial do reclamante sob a justificativa de que o ordenamento jurídico pátrio ainda carece de regulamentação legal específica do direito previsto no art. 40, § 4º, III, da Constituição Federal. Como se viu, na análise procedida, o Instituto de Previdência dos Servidores Municipais de Goiânia não obstaculizou a análise do pedido formulado de aposentadoria especial. Ao revés, com base no entendimento sumulado desta Suprema Corte, deu seguimento ao requerimento, determinando a realização de cálculos, ciência do ora reclamante para opção e remessa dos autos a outros órgãos da administração municipal. Entretanto, do pedido formulado nos autos, pode ser extraído que o reclamante pretende ver a sua aposentadoria especial concedida com integralidade e paridade, a despeito de que, aparentemente, o art. 40, § 4° da CF não assegure ao reclamante, necessariamente, o direito à integralidade e à paridade. Assim, entendo que a decisão atacada, além de não ter desobedecido o enunciado sumular paradigmático, não guarda relação de identidade com o mesmo, o que, inevitavelmente, levaria ao não conhecimento do pedido.","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"[ Rcl 32.392 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 7-11-2018, DJE 239 de 12-11-2018.]","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"O Tribunal editou o verbete vinculante 33 da Súmula (...). O pronunciamento possui efeito vinculante em relação à Administração Pública direta e indireta, nos três níveis da Federação, conforme o artigo 103-A, cabeça, da Constituição Federal. Eventual descumprimento abre a via da reclamação, nos termos do § 3º do mesmo dispositivo. Considerada a integração realizada pelo Supremo e a inviabilidade de a autoridade administrativa alegar lacuna legislativa, constata-se a perda superveniente do interesse processual para ver julgada a impetração.","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"[ MI 4.626 , rel. min. Marco Aurélio , dec. monocrática, j. 17-9-2018, DJE 197 de 19-9-2018.]","deleted":false}],"heading":false},{"page":141,"runs":[{"text":"1. A decisão que se pretende rescindir não diverge da orientação jurisprudencial estabelecida no Supremo Tribunal Federal à época da prolação do decisum rescindendo - e prevalente até a presente data - no sentido de se reconhecer a mora legislativa quanto à regulamentação do art. 40, § 4º, da Constituição, bem como se determinar a aplicação analógica do art. 57, § 1º, da Lei 8.213/1991 enquanto existir lacuna normativa, a fim de garantir o direito à aposentadoria especial em razão da insalubridade ou da periculosidade de atividades exercidas pelo servidores públicos. 2. Não há que se falar, portanto, em violação literal a dispositivo da Constituição Federal, tampouco em alteração do entendimento aplicado por esta Corte quando da prolação da decisão rescindenda. Cabível a negativa de seguimento à ação rescisória por incidência do óbice contido na","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"Súmula 343/STF. 3. Nos autos do MI 833/STF, esta Corte manifestou-se no sentido de que, diante do caráter aberto da expressão atividades de risco (art. 40, § 4º, II, da Constituição) e da relativa liberdade de conformação do legislador, somente há omissão inconstitucional quando a periculosidade seja inequivocamente inerente ao ofício. Conclusão que, todavia, não impede a apreciação do direito à aposentadoria especial a tais servidores públicos, se atendidos por eles os requisitos do art. 40, § 4º, inciso III, da CF/88, adotando-se, para tanto, na avaliação administrativa, os requisitos do art. 57, da Lei 8.213/1991, eleito por esta Corte como regra de simetria aos trabalhadores da rede privada. Entendimento cristalizado na Súmula Vinculante 33. 4. O julgado rescindendo, aplicando tal entendimento, tão somente assegurou a apreciação, pela autoridade administrativa competente, dos pleitos de aposentadoria especial da categoria, aplicando-se, no que couber, o art. 57, da Lei 8.213/1991, sem, contudo, lhes garantir o direito propriamente dito, o que, inclusive, refoge ao âmbito de decisão do mandado de injunção. 5. Agravo regimental não provido.","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"[ AR 2.512 AgR , rel. min. Dias Toffoli , P, j. 30-6-2017, DJE 222 de 29-9-2017.]","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"A partir da publicação da Súmula Vinculante 33, a Administração direta e indireta, nas esferas federal, estadual e municipal, deve aplicar a seus servidores, no que couber, as regras do regime geral da previdência social sobre a aposentadoria especial de que trata o art. 40, § 4º, III, da Constituição Federal, até a edição de lei complementar específica. 2. A afronta à Súmula Vinculante 33 ocorre quando a Administração se furta de examinar o pleito de concessão de aposentadoria especial ao fundamento de que inexistente a norma regulamentadora a que refere o art. 40, § 4º, III, da Constituição Federal, o que não é o caso dos autos, como deflui da própria inicial.","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"[ Rcl 21.360 AgR , rel. min. Rosa Weber , 1ª T, j. 7-3-2017, DJE 55 de 22-3-2017.]","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"Concessão de aposentadoria especial a servidor público portador de necessidades especiais por analogia conforme legislação do RGPS","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"Ultrapassado este ponto, remanesce a questão quanto ao direito de o servidor público que exerça atividades insalubres obter, independentemente da observância das regras de transição das Emendas Constitucionais nºs 41/03 e 47/05, aposentadoria especial com proventos calculados com base na integralidade e na paridade. (...) Logo, verifica-se que, nesse ponto, o acórdão do Tribunal de origem destoa da orientação firmada pelo Supremo Tribunal Federal. Isso porque, segundo o narrado nos autos, o preenchimento do requisito temporal para a aposentadoria especial (25 anos) teria sido garantido ao recorrido em decorrência da aplicação, por extensão, da regra do regime geral de previdência (art. 57 da Lei nº 8.213/1991). O reconhecimento do direito à paridade e à integralidade, contudo, decorreu do simples fato de o recorrido ter ingressado no serviço público antes do advento das Emendas Constitucionais 20/98 e 41/03. Conforme se nota nos precedentes desta Corte, não há amparo para o servidor público se aposentador com direito à paridade e à integralidade após a edição das Emendas Constitucionais nº 41/2003 e nº 47/2005, salvo as exceções já reconhecidas pelo Supremo Tribunal Federal e mencionadas nos julgados acima, quais sejam: (1) servidores que preencheram as regras de transição previstas nas emendas indicadas; e (2) a existência de norma específica a conferir tal direito, quando amparada no art. 40, § 4º, do texto constitucional, que autoriza a criação de critérios diferenciados a depender da sujeição a atividades especiais.","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"[ ARE 1.324.393 , rel. min. Gilmar Mendes , dec. monocrática, j. 4-9-2024, DJE s/n de 6-9-2024.]","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"Conforme destacado na decisão ora agravada, a Súmula Vinculante 33/STF concede o direito à aposentadoria especial àqueles que exercem atividades prejudiciais à saúde ou à integridade física (art. 40, § 4º, III, da Constituição Federal), então, concluí acertado o acórdão quanto à concessão de aposentadoria especial à servidora. Verifiquei que o caso em análise trata de servidora que ingressou no serviço público municipal em data anterior à EC 41/2003, aposentando-se em data posterior, e que a Corte de origem concedeu a integralidade de proventos por preencher os requisitos previstos no art. 7º da referida emenda, sem analisar os requisitos da EC 47/2005.","deleted":false}],"heading":false},{"page":142,"runs":[{"text":"[ ARE 1.322.634 ED , rel. min. Gilmar Mendes , 2ª T, j. 23-9-2024, DJE s/n de 27-9-2024.]","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"Na presente hipótese, em que o impetrante fundamenta seu pleito em omissão relativa ao artigo 40, § 4º, I da Constituição Federal, a solução do caso deve ser pautada pelo mesmo raciocínio que subsidiou a edição da Súmula Vinculante 33, (...). De forma a reconhecer, no caso, a ausência de lei complementar que discipline a matéria específica relacionada no inciso I, § 4º, art. 40, do texto constitucional, tornando, por decorrência lógica, necessária a integração da norma. Em julgamento sobre o tema, acompanhei a maioria formada no sentido de que a Lei Complementar 142/2013 é o parâmetro legislativo a ser aplicado, no que couber, para regulamentar o direito à aposentadoria especial de servidor público portador de deficiência (MI 1613 AgR-AgR, Rel. Min LUIZ FUX, Pleno, Dje de 26/5/2017). Diante do exposto, com base no art. 205, caput do Regimento Interno do Supremo Tribunal Federal, CONCEDO A ORDEM para reconhecer a mora legislativa e determinar ao órgão público competente que aprecie o pedido da impetrante, aplicando, no que couber, os termos da Lei 8.213/1991 ou da LC 142/2013, a depender do marco temporal em que o impetrante alcançou as condições para a obtenção do benefício.","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"[ MI 7.054 , rel. min. Alexandre de Moraes , dec. monocrática, j. 28-11-2018, DJE 257 3-12-2018.]","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"A jurisprudência é pacífica no sentido de que “o cômputo do tempo de serviço e os seus efeitos jurídicos regem-se pela lei vigente quando da sua prestação” (...). Como visto, antes do advento da LC 142/2013, não havia no regime geral norma específica para aposentadoria especial de pessoas com deficiência, razão pela qual este Tribunal sempre aplicou, por analogia, o art. 57 da Lei 8.213/1991. Com a entrada em vigor da referida lei complementar, somente o tempo de serviço posterior pode ser por ela disciplinado, conforme a máxima tempus regit actum . Do contrário, a União estaria se beneficiando de sua própria inércia, ao aplicar retroativamente os parâmetros da LC 142/2013, notadamente menos benéficos que os previstos na Lei 8.213/1991 (...).","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"[ MI 1.884 AgR , voto do rel. min. Roberto Barroso , P, j. 7-10-2015, DJE 214 de 27-10-2015.]","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"Ainda que se possa afastar o reconhecimento da prejudicialidade, em razão da falta de pertinência do que se contém na Súmula Vinculante 33/STF, considerado o contexto ora em exame (pessoa portadora de deficiência), o fato irrecusável é que, com a superveniência da LC 142/2013, esta Corte - ao estender à situação de servidores portadores de deficiência (ou de necessidades especiais), por analogia legis, referido diploma legislativo - tem rejeitado pretensões recursais que buscam reformar decisões, como a proferida nesta causa, que reconheceu, em favor de agentes públicos nas condições do art. 40, § 4º, I, da Constituição Federal, o direito à aposentadoria especial. Com efeito, o Supremo Tribunal Federal firmou entendimento no sentido de ser aplicável, por analogia, à aposentadoria especial do servidor público portador de deficiência, a da LC 142/2013, editada para disciplinar a aposentação de pessoa com deficiência (ou com necessidades especiais) segurada do Regime Geral de Previdência Social (CF, art. 201, § 1º), como se vê de inúmeros precedentes (...).”","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"[ MI 3.322 AgR-segundo-ED-ED-AgR , voto do rel. min. Celso de Mello , P, j. 1º-8-2014, DJE 213 de 30-10-2014.]","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"Contagem diferenciada e averbação de tempo de serviço prestado em condições especiais","deleted":false}],"heading":false},{"page":143,"runs":[{"text":"In casu, a averbação pretendida pela parte beneficiária é anterior à Emenda Constitucional nº 103/2019, devendo ser aplicada a legislação do regime geral de previdência social (Lei 8.213/1991) (...) se o entendimento assentado na Súmula Vinculante 33 e na tese firmada em sede de repercussão geral determina a aplicação das normas do Regime Geral de Previdência Social (Lei 8.213/1991) para viabilizar a concretização do direito à aposentadoria especial, não há razão para a desconsideração da legislação de regência, a qual possui previsão expressa acerca do modo de comprovação dos agentes nocivos à saúde. Não cabe ao magistrado desconsiderar a previsão normativa, aplicando ao caso concreto apenas parcialmente a lei. (...) Ante o exposto, julgo procedente a reclamação para cassar o acórdão reclamado determinando que outro seja proferido, desta vez com observância do entendimento firmado na Súmula Vinculante nº 33 e no julgamento do RE-RG 1.014.286.","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"[ Rcl 58.090 , rel. min. Gilmar Mendes , dec. monocrática, j. 26-6-2023, DJE s/n de 28-6-2023.]","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"1. Nada obstante seja cabível reclamação por violação à súmula vinculante, tem-se que o caso dos autos não fornece suporte fático para a incidência da Súmula Vinculante 33 do STF. 2. Não há, até o presente momento, em controle concentrado ou em Súmula Vinculante, decisão desta Corte admitindo a conversão de tempo de serviço especial em comum, quando exercido por servidor público vinculado a regime próprio de previdência social.","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"[ Rcl 27.045 AgR , rel. min. Edson Fachin , 2ª T, j. 20-2-2018, DJE 69 de 11-4-2018.]","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"APOSENTADORIA ESPECIAL DE SERVIDOR PÚBLICO. ART. 40, § 4º, III, DA CONSTITUIÇÃO FEDERAL. PEDIDO DE AVERBAÇÃO DE TEMPO DE SERVIÇO PRESTADO EM ATIVIDADES EXERCIDAS SOB CONDIÇÕES ESPECIAIS QUE PREJUDIQUEM A SAÚDE OU A INTEGRIDADE FÍSICA DO SERVIDOR, COM CONVERSÃO DO TEMPO ESPECIAL EM COMUM, MEDIANTE CONTAGEM DIFERENCIADA, PARA OBTENÇÃO DE OUTROS BENEFÍCIOS PREVIDENCIÁRIOS. QUESTÃO NÃO ABRANGIDA PELO ENUNCIADO DA SÚMULA VINCULANTE 33. REITERAÇÃO DA CONTROVÉRSIA EM MÚLTIPLOS PROCESSOS. IMPACTO DA DECISÃO NO EQUILÍBRIO FINANCEIRO E ATUARIAL DA PREVIDÊNCIA PÚBLICA. RECONHECIDA A EXISTÊNCIA DE REPERCUSSÃO GERAL.","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"[ RE 1.014.286 RG , rel. min. Luiz Fux , P, j. 20-4-2017, DJE 103 de 18-5-2017, Tema 942.]","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"1. Não guarda relação de estrita aderência com a Súmula Vinculante 33 decisão que julga improcedente pedido de contagem especial de tempo de trabalho prestado em condições insalubres, sob o regime celetista, em razão da ausência de prévia averbação administrativa. 2. Agravo interno desprovido.","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"[ Rcl 25.529 AgR , rel. min. Roberto Barroso , 1ª T, j. 17-2-2017, DJE 47 de 13-3-2017.]","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"Consoante registrado na decisão agravada, a partir da publicação da Súmula Vinculante 33, a Administração direta e indireta, nas esferas federal, estadual e municipal, deve aplicar a seus servidores, no que couber, as regras do regime geral da previdência social sobre a aposentadoria especial de que trata o art. 40, § 4º, III, da Magna Carta. (...) Nos debates havidos para a aprovação da Súmula Vinculante 33 (PSV 45/DF), ficou assentado que, diante da existência de diversos precedentes desta Suprema Corte no sentido da inviabilidade do mandado de injunção para garantir a contagem diferenciada e a averbação de tempo de serviço prestado em condições especiais, o referido tema não seria abrangido pela Súmula. O propósito da Corte, portanto, foi tão somente garantir a apreciação do pedido de aposentadoria especial com observância do art. 57 da Lei 8.213/1991, o que afasta o cabimento da presente reclamação.","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"[ Rcl 19.734 AgR , voto da rel. min. Rosa Weber , 1ª T, j. 9-11-2016, DJE 248 de 22-11-2016.]","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"(...) conclui-se que a orientação jurisprudencial até então consolidada nesta Corte é no sentido da inexistência de norma que reconheça o direito do servidor público à averbação do tempo de serviço prestado em atividade insalubre, com a respectiva conversão para tempo de serviço comum, para fins de futura aposentadoria, na forma como estabelecida pela Lei 8.213/1991 aos segurados do regime geral de previdência social. Mesmo com a edição da Súmula Vinculante 33 pelo STF, “a concessão da aposentadoria especial, nos termos do art. 57 da Lei 8.213/1991, hoje com a redação da Lei 9.032/1995, não modificou o entendimento desta Corte no sentido de que não cabe o reconhecimento da contagem diferenciada e da averba- ção do tempo de serviço prestado por servidor público em condições insalubres, por exorbitar, inclusive, da expressa disposição constitucional e porque não comporta esta hipótese em direito subjetivo estabelecido pela Constituição Federal” (ARE 841.148 AgR/SP, rel. min. Dias Toffoli, Segunda Turma).","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"[ ARE 818.552 AgR-segundo , voto do rel. min. Edson Fachin , 1ª T, j. 28-10-2016, DJE 244 de 18-11-2016.]","deleted":false}],"heading":false},{"page":144,"runs":[{"text":"O impetrante pretende o reconhecimento da contagem do tempo de serviço prestado em atividade insalubre, com a respectiva conversão em tempo comum, para fins de aposentadoria voluntária. (...) No exercício desse múnus constitucional, o Tribunal Pleno, ao apreciar mandados de injunção que versavam sobre o art. 40, § 4º, da Constituição Federal (os quais ensejaram a edição da Súmula Vinculante 33), consignou de forma explícita","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"que aquela via não comportava a discussão sobre a conversão de tempo de serviço prestado em atividades exercidas em condições nocivas, para fins de aproveitamento, como serviço comum, de outra espécie de aposentadoria. (...) Deveras, os julgados proferidos nos referidos mandados de injunção, bem como o entendimento consignado na Súmula Vinculante 33, asseguram o direito à aposentadoria especial, mediante comprovação do exercício de atividades em condições prejudiciais à saúde. Entretanto, não se afirma em momento algum a admissão da conversão de tempo de serviço prestado em atividades insalubres em serviço comum. Em tais circunstâncias, a pretensão do impetrante de contagem de tempo de serviço prestado em atividade insalubre, com a conversão em tempo comum, para fins de aposentadoria voluntária, não encontra respaldo na jurisprudência desta Corte, a revelar o insucesso da ordem pretendida.","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"[ MS 33.958 , rel. min. Luiz Fux , dec. monocrática, j. 2-8-2016, DJE 164 de 5-8-2016.]","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"Por fim, para evitar o ajuizamento de recursos futuros contra esta decisão do colegiado, anoto o entendimento sufragado na Corte acerca da impossibilidade de se conceder a ordem para autorizar a contagem diferenciada de tempo em exercício de atividade especial. Com efeito, não há omissão legislativa infraconstitucional no tocante à conversão de tempo de serviço especial em comum, pois não existe norma constitucional que reconheça esse direito para os servidores públicos e que necessite de regulamentação pelo Poder Legislativo. Ao contrário, esta Corte tem entendimento sedimentado no sentido de ser vedada a conversão de tempo de serviço especial em comum para fins de aposentadoria de servidor público, a teor do disposto no próprio § 4º do art. 40 da Constituição Federal, ora discutido.","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"[ MI 3.920 AgR , voto do rel. min. Edson Fachin , P, j. 26-11-2015, DJE 248 de 10-12-2015.]","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"A orientação do Supremo Tribunal Federal firmou-se no sentido de que o art. 40, § 4º, da Constituição Federal não garante a contagem de tempo de serviço diferenciada ao servidor público, porém, tão somente, a aposentadoria especial.","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"[ RE 788.025 AgR-segundo , rel. min. Ricardo Lewandowski , 2ª T, j. 26-8-2014, DJE 171 de 4-9-2014.]","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"Com efeito, a jurisprudência dessa Corte assentou o não cabimento de mandado de injunção que visa à contagem diferenciada e posterior averbação de tempo do serviço prestado em condições especiais, uma vez que não há previsão constitucional da referida contagem.","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"[ MI 1.278 AgR , voto do rel. min. Gilmar Mendes , P, j. 30-4-2014, DJE 94 de 19-5-2014.]","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"Não viola a Súmula Vinculante 33 decisão administrativa que indefere pedido de aposentadoria especial por ausência de comprovação dos requisitos do art. 40, § 4º, III, da CF/1988","deleted":false}],"heading":false},{"page":145,"runs":[{"text":"O requerimento de aposentadoria da agravante foi indeferido pelo coordenador jurídico da Secretaria de Estado de Saúde Pública do Rio Grande do Norte por ausência de idade para aposentadoria e de regulamentação dos arts. 57 e 58 da Lei 8.213/1991. 3. Como assentado na decisão agravada, a Súmula Vinculante 33 do Supremo Tribunal Federal foi editada em decorrência da consolidada jurisprudência deste Supremo Tribunal sobre a possibilidade de aplicar-se a norma do art. 57 da Lei 8.213/1991, a fim de viabilizar à Administração Pública a análise de requerimento de aposentadoria especial formulado por servidor público que exerce atividades em condições insalubres (art. 40, § 4º, III, da Constituição da República), até o advento de legislação específica sobre a matéria. 4. Na espécie, a autoridade reclamada não se recusou a examinar requerimento de aposentadoria especial da agravante. O pedido de aposentação também não foi indeferido com base na inexistência da lei complementar a que se refere o art. 40, § 4º, III, da Constituição da República. Não há identidade material entre a decisão reclamada e a súmula vinculante apontada como paradigma (...). Em reclamação, não é possível verificar se a agravante cumpre os requisitos da aposentadoria especial, sob pena de transformar esta ação em sucedâneo de recursos, o que não é admitido pelo Supremo Tribunal Federal (...). Ausente a identidade material entre a decisão reclamada e o alegado descumprimento da Súmula Vinculante 33 do Supremo Tribunal Federal, evidencia-se o desatendimento aos requisitos constitucionais da reclamação (arts. 102, I, l, e 103-A, § 3º, da Constituição da República), que não pode ser regularmente","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"processada.","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"[ Rcl 20.583 AgR , rel. min. Cármen Lúcia , 2ª T, j. 2-2-2016, DJE 35 de 25-2-2016.]","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"Proposta de revisão da Súmula Vinculante 33","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"Trata-se de proposta de revisão da Súmula Vinculante 33, formulada pelo procurador-geral da República, a fim de que esta Suprema Corte inclua na redação do aludido verbete o inciso I do § 4º do art. 40 da Constituição Federal. A redação sugerida é a seguinte: “Aplicam-se ao servidor público, no que couber, as regras do regime geral da previdência social sobre aposentadoria especial de que trata o art. 40, § 4º, I e III, da Constituição Federal, até a edição de lei complementar específica”. (...) verificada a adequação formal da presente proposta de súmula vinculante, determino à Secretaria Judiciária que providencie a publicação do edital previsto no art. 354-B do RISTF.","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"[ PSV 118 , rel. min. presidente Ricardo Lewandowski , dec. monocrática, j. 2-9-2015, DJE 177 de 9-9-2015.]","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"Servidores públicos militares e aposentadoria especial","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"A jurisprudência deste Supremo Tribunal firmou-se no sentido de que a LC 51/1985 - que trata da aposentadoria do servidor público policial - foi recepcionada pela Constituição da República de 1988, de modo que ausente omissão legislativa a respeito da aposentadoria especial dos policiais militares estaduais. Precedentes do STF. 2. Ausente, nesse contexto, a violação dos preceitos legais e constitucionais apontada na inicial desta ação, inviável concluir pela procedência do pedido de corte rescisório.","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"[ AR 2.420 AgR , rel. min. Rosa Weber , P, j. 17-3-2016, DJE 62 de 6-4-2016.]","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"O Plenário desta Corte, de fato, reconheceu a aplicação da lei geral da previdência para os casos de aposentadoria especial de servidor público civil (MI 721, rel. min. Marco Aurélio). Ocorre que a referida conclusão não pode ser aplicada indistintamente aos servidores públicos militares, porquanto há para a categoria disciplina constitucional própria (ARE 722.381 AgR, rel. min. Gilmar Mendes). 3. Com efeito, nos termos do art. 42 da Carta, não são aplicáveis aos servidores militares dos Estados, do Distrito Federal e dos Territórios as regras relativas aos critérios diferenciados de aposentadoria de servidores civis que exerçam atividades de risco ou sob condições especiais que prejudiquem a saúde ou a integridade física. Isso porque, nesses casos, cabe à lei própria fixar o regime jurídico de aposentadoria dos servidores militares. E, existindo norma específica (LC 51/1985 ou DL estadual 260/1970), não há que se falar em omissão legislativa.","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"[ ARE 775.070 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 30-9-2014, DJE 208 de 22-10-2014.]","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"(...) ALEGADA OMISSÃO ESTATAL NO ADIMPLEMENTO DE PRESTAÇÃO LEGISLATIVA DETERMINADA NO ART. 40, § 4º, DA CONSTITUIÇÃO FEDERAL. SERVIDOR POLICIAL. PRETENDIDO ACESSO AO BENEFÍCIO DA APOSENTADORIA ESPECIAL. INOCORRÊNCIA DE SITUAÇÃO CONFIGURADORA DE INÉRCIA ESTATAL. EXISTÊNCIA DE LEGISLAÇÃO, EDITADA PELA UNIÃO FEDERAL, PERTINENTE À DISCIPLINA NORMATIVA DA APOSENTADORIA ESPECIAL DOS SERVIDORES POLICIAIS INTEGRANTES DOS ÓRGÃOS DE SEGURANÇA PÚBLICA DO ESTADO (LC 51/1985), DISPONDO, DE MANEIRA PLENA, SOBRE A MATÉRIA. PRECEDENTES. INVIABILIDADE, DE OUTRO LADO, DO PEDIDO DE CONTAGEM DIFERENCIADA DO TEMPO DE SERVIÇO EXERCIDO EM ATIVIDADES DE RISCO OU INSALUBRES, PARA EFEITO DE CONVERSÃO EM TEMPO COMUM. INEXISTÊNCIA DE LACUNA TÉCNICA. PRECEDENTES. RECURSO DE AGRAVO IMPROVIDO.","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"[ MI 1.664 ED , rel. min. Celso de Mello , P, j. 1º-8-2014, DJE 213 de 30-10-2014.]","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":146,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 727, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":146,"runs":[{"text":"● Tema 942 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":147,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-4-2014.","deleted":false}],"heading":false},{"page":147,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":147,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"34","number":"34","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":148,"endPage":149,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1947","paragraphs":[{"page":148,"runs":[{"text":"A Gratificação de Desempenho de Atividade de Seguridade Social e do Trabalho - GDASST, instituída pela Lei 10.483/2002, deve ser estendida aos inativos no valor correspondente a 60 (sessenta) pontos, desde o advento da Medida Provisória 198/2004, convertida na Lei 10.971/2004, quando tais inativos façam jus à paridade constitucional (EC 20/1998, 41/2003 e 47/2005).","deleted":false}]}],"notes":[{"page":148,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":148,"runs":[{"text":"I - Gratificação de desempenho que deve ser estendida aos inativos no valor de 60 (sessenta) pontos, a partir do advento da MP 198/2004, convertida na Lei 10.971/2004, que alterou a sua base de cálculo. II - Embora de natureza pro labore faciendo , a falta de regulamentação das avaliações de desempenho trasmuda a GDASST em uma gratificação de natureza genérica, extensível aos servidores inativos. III - Inocorrência, na espécie, de violação ao princípio da isonomia.","deleted":false}],"heading":false},{"page":148,"runs":[{"text":"[ RE 572.052 , rel. min. Ricardo Lewandowski , P, j. 11-2-2009, DJE 71 de 17-4-2009.]","deleted":false}],"heading":false},{"page":148,"runs":[{"text":"(...) a jurisprudência do Supremo Tribunal Federal é firme no sentido de que, para caracterizar a natureza pro labore faciendo da gratificação (GDASST), seria necessária a edição de norma regulamentadora que viabilize as avaliações de desempenho. Sem a aferição de desempenho, a gratificação adquire um caráter de generalidade, que determina a sua extensão aos servidores inativos. 2. Sendo assim, a gratificação deve ser paga conforme pontuação preestabelecida, independente do desempenho individual de cada servidor, obedecendo aos critérios aplicáveis aos servidores ativos. (...) 4. Não há que se falar, portanto, em aplicação do disposto no art. 5º, parágrafo único, da Lei 10.404/2002, ao período de 1º-4-2002 a 30-4-2004, uma vez que é corolário da decisão proferida pelo Supremo Tribunal Federal que, ante a ausência de norma regulamentadora que viabilize as avaliações de desempenho, se aplicam aos inativos os mesmos critérios utilizados para os servidores em atividade, os quais estão previstos no art. 11 da lei instituidora da GDASST - Lei 10.483/2002.","deleted":false}],"heading":false},{"page":148,"runs":[{"text":"[ AI 804.478 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 26-8-2014, DJE 176 de 11-9-2014.]","deleted":false}],"heading":false},{"page":148,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":148,"runs":[{"text":"● A fixação da GDATA e da GDASST em relação aos servidores inativos deve obedecer aos critérios a que estão submetidos os servidores em atividade de acordo com a sucessão de leis de regência.","deleted":false}],"heading":false},{"page":148,"runs":[{"text":"[Tese definida no RE 597.154 QO-RG , rel. min. presidente Gilmar Mendes , P, j. 19-2-2009, DJE 99 de 29-5-2009, Tema 153.]","deleted":false}],"heading":false},{"page":148,"runs":[{"text":"A decisão ora reclamada assentou que o pagamento da GDASST aos inativos e pensionistas deve obedecer os critérios de quantificação estabelecidos em prol dos servidores ativos, nos termos da Lei 10.483/2002 e das subsequentes, destacando que essa sistemática persiste inclusive após a edição da EC 41/2003 (...). Em sede de análise liminar, o pronunciamento impugnado parece não ter observado a Súmula Vinculante 34 (...). Com efeito, prima facie , depreende-se estar presente o fumus boni iuris , diante da impossibilidade de inativos que não façam jus à paridade constitucional receberem valores a título de GDASST na mesma proporção dos percebidos por servidores em atividade. De outra parte, também entendo estar presente o periculum in mora , dado o fundado receio de que a decisão ora combatida, ainda não transitada em julgado pela pendência de análise de recurso interposto pela reclamante, venha a produzir efeitos de cunho executivo, incorrendo em prejuízos aos cofres públicos.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"[ Rcl 30.154 MC , rel. min. Edson Fachin , dec. monocrática, j. 17-7-2018, DJE 157 de 6-8-2018.]","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"A União figura como ré em demanda, formalizada por servidoras inativas, direcionada ao reconhecimento do direito à percepção da GDASST na mesma proporção devida aos ativos. Quanto a Joana (...), o pleito não foi atendido por não ser contemplada pela paridade remuneratória considerada a jubilação em 16 de outubro de 2006, posteriormente à publicação da Emenda Constitucional 41/2003. O Tribunal reclamado reviu o entendimento. Embora não verificada, no caso da citada beneficiária, a paridade, concluiu vedado o tratamento discriminatório entre servidores ante a garantia, no artigo 40, § 8º, da Constituição Federal, na redação conferida pela citada Emenda, do reajustamento de benefícios, mediante lei, objetivando a manutenção do valor real. (...) Mostra-se relevante a irresignação. A leitura da parte final do paradigma revela que o pressuposto para o acolhimento da pretensão ao pagamento igualitário, entre ativos e inativos, da GDASST é a paridade remuneratória. Não sendo a beneficiária favorecida pela paridade, está evidenciada a contrariedade ao paradigma.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"[ Rcl 30.153 MC , rel. min. Marco Aurélio , dec. monocrática, j. 9-5-2018, DJE 96 de 17-5-2018.]","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"Registre-se, por fim, que a Súmula Vinculante 34 limita-se a determinar a extensão da GDASST aos inativos no valor correspondente a 60 pontos, mas em momento algum garante a manutenção desse percentual na hipótese de sobrevir avaliação de desempenho dos servidores ativos, fator que define o caráter pro labore faciendo da vantagem.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"[ RE 941.514 , rel. min. Teori Zavascki , dec. monocrática, j. 4-3-2016, DJE 45 de 10-3-2016.]","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":149,"runs":[{"text":"● Vide Súmula Vinculante 20.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 153, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-4-2014.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":149,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"35","number":"35","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":150,"endPage":151,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1953","paragraphs":[{"page":150,"runs":[{"text":"A homologação da transação penal prevista no artigo 76 da Lei 9.099/1995 não faz coisa julgada material e, descumpridas suas cláusulas, retoma-se a situação anterior, possibilitando-se ao Ministério Público a continuidade da persecução penal mediante oferecimento de denúncia ou requisição de inquérito policial.","deleted":false}]}],"notes":[{"page":150,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":150,"runs":[{"text":"É que a Corte já decidiu que não fere os preceitos constitucionais indicados a possibilidade de propositura de ação penal em decorrência do não cumprimento das condições estabelecidas em transação penal (art. 76 da Lei 9.099/1995). E isso porque a homologação da transação penal não faz coisa julgada material e, descumpridas suas cláusulas, retorna-se ao status quo ante , possibilitando-se ao Ministério Público a continuidade da persecução penal (situação diversa daquela em que se pretende a conversão automática deste descumprimento em pena privativa de liberdade). (...) Não há que se falar, assim, em ofensa ao devido processo, à ampla defesa e ao contraditório. Ao contrário, a possibilidade de propositura de ação penal garante, no caso, que o acusado tenha a efetiva oportunidade de exercer sua defesa, com todos os direitos a ela inerentes.","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"[ RE 602.072 QO-RG , voto do rel. min. Cezar Peluso , P, j. 19-11-2009, DJE 35 de 26-2-2010.]","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":150,"runs":[{"text":"● As consequências jurídicas extrapenais previstas no art. 91 do Código Penal são decorrentes de sentença penal condenatória. Tal não ocorre, portanto, quando há transação penal (art. 76 da Lei 9.099/1995), cuja sentença tem natureza meramente homologatória, sem qualquer juízo sobre a responsabilidade criminal do aceitante. As consequências geradas pela transação penal são essencialmente aquelas estipuladas por modo consensual no respectivo instrumento de acordo.","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"[Tese definida no RE 795.567 , rel. min. Teori Zavascki , P, j. 28-5-2015, DJE 177 de 9-9-2015, Tema 187.]","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"● A homologação da transação penal prevista no art. 76 da Lei 9.099/1995 não faz coisa julgada material e, descumpridas suas cláusulas, retoma-se a situação anterior, possibilitando-se ao Ministério Público a continuidade da persecução penal mediante oferecimento de denúncia ou requisição de inquérito policial.","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"[Tese definida no RE 602.072 QO-RG , rel. min. Cezar Peluso , P, j. 19-11-2009, DJE 35 de 26-2-2010, Tema 238.]","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":150,"runs":[{"text":"Efeitos jurídicos do cumprimento parcial de acordo celebrado entre o Ministério Público e o acusado","deleted":false}],"heading":false},{"page":150,"runs":[{"text":"5. A Súmula Vinculante 35 consolidou a jurisprudência desta Suprema Corte no sentido da possibilidade de propositura de ação penal quando descumprida transação penal homologada, considerado o entendimento de que esta não produz coisa julgada material. 6. Consoante emerge dos excertos transcritos, o Juízo reclamado rejeitou a denúncia oferecida pela prática do crime previsto no art. 28 da Lei 11.343/2006 com base nos arts. 395, I e III, do Código de Processo Penal, sob a justificativa de que ausente justa causa para o exercício da persecução criminal, pois a pena abstratamente objetivada em lei para o caso de posse de droga para consumo pessoal teria sido alcançada com o comparecimento do autor do fato à audiência de advertência, em que ministrada palestra sobre os efeitos nocivos da droga. 7. Nesse contexto, não diviso a existência de estrita","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"aderência entre os atos confrontados, uma vez que a rejeição da denúncia oferecida pelo MPDFT não está fundamentada na tese de que a homologação da transação penal teria produzido coisa julgada material. Os efeitos jurídicos do cumprimento parcial de acordo celebrado entre o Ministério Público e o acusado referem-se a tema não abrangido pela Súmula Vinculante 35.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"[ Rcl 25.785 , rel. min. Rosa Weber , dec. monocrática, j. 31-10-2018, DJE 238 de 9-11-2018.]","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"1. Não existe aderência entre o ato reclamado e a Súmula Vinculante 35, uma vez que não se discute se a homologação da transação penal fez coisa julgada material, tendo em vista que a discussão gira em torno da suficiência, ou não, da pena de advertência para o ato de portar drogas para uso próprio. 2. Ademais, a advertência aplicada a indivíduo que portava drogas para uso próprio já configura sanção necessária e suficiente para a reprovação e prevenção da conduta de porte de drogas para uso próprio.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"[ Rcl 25.967 MC , rel. min. Roberto Barroso , dec. monocrática, j. 14-8-2017, DJE 180 de 17-8-2017.]","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"Com esta reclamação, o Ministério Público argui a inobservância do Verbete Vinculante 35 da Súmula do Supremo (...). Surge imprópria a irresignação, uma vez não evidenciada a adoção de óptica conflitante com o paradigma. Ao declarar extinta a punibilidade da interessada, o órgão reclamado não evocou eventual coisa julgada considerado o descumprimento parcial dos termos do acordo com ela firmado. Entendeu suficiente - certo ou errado, descabe perquirir -, presentes as penas previstas em lei para o crime de porte de entorpecente para consumo próprio, comparecimento à audiência preliminar, na qual veiculada advertência acerca dos efeitos do uso de drogas. Em síntese, não há identidade material entre a situação retratada e o teor do enunciado apontado como olvidado.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"[ Rcl 25.787 , rel. min. Marco Aurélio , dec. monocrática, j. 29-5-2017, DJE 116 de 2-6-2017.]","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"No caso concreto, articula-se violação à Súmula Vinculante 35 (...). Observo que o verbete trata exclusivamente da ausência de formação de coisa julgada na hipótese de homologação de transação penal e da consequente possibilidade de prosseguimento da persecução penal na hipótese de descumprimento das respectivas cláusulas. Contudo, o Supremo não se pronunciou expressamente, na oportunidade, acerca de eventuais efeitos jurídicos do cumprimento, ainda que parcial, de cláusulas entabuladas entre o Ministério Público e o acusado, e a possibilidade de que funcionem como espécie de detração penal ou interferiram no juízo de necessidade de resposta penal. Nessa linha, e pelas especificidades do caso concreto (agente acusado da prática da conduta prevista no art. 28 da Lei 11.343/2006), a autoridade reclamada atestou, diante da similitude entre as condições da transação e eventual sanção, a dispensabilidade da persecução penal. Com efeito, a interpretação da Turma Recursal, direcionada ao elastecimento da detração penal e associada à aferição da desnecessidade de instauração de ação penal, escapa do âmbito decisório acobertado pela súmula vinculante. Vale dizer, independentemente do acerto ou desacerto da decisão reclamada, o reconhecimento da ausência de interesse processual não traduz violação ao enunciado vinculante que, em verdade, não tratou da possibilidade, ou não, de que as condições da transação sejam ponderadas analogicamente a título de detração.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"[ Rcl 25.968 , rel. min. Edson Fachin , dec. monocrática, j. 16-12-2016, DJE 17 de 1º-2-2017.]","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":151,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 238, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-4-2014.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":151,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"36","number":"36","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":152,"endPage":153,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1957","paragraphs":[{"page":152,"runs":[{"text":"Compete à Justiça Federal comum processar e julgar civil denunciado pelos crimes de falsificação e de uso de documento falso quando se tratar de falsificação da Caderneta de Inscrição e Registro (CIR) ou de Carteira de Habilitação de Amador (CHA), ainda que expedidas pela Marinha do Brasil.","deleted":false}]}],"notes":[{"page":152,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":152,"runs":[{"text":"O Supremo Tribunal Federal, por sua vez, tem entendido, em casos idênticos ao ora em análise, que não se tem por configurada a competência da Justiça Militar da União, em tempo de paz, tratando-se de réus civis, se a ação eventualmente delituosa, por eles praticada, não afetar, de modo real ou potencial, a integridade, a dignidade, o funcionamento e a respeitabilidade das instituições militares que constituem, em essência, os bens jurídicos penalmente tutelados.","deleted":false}],"heading":false},{"page":152,"runs":[{"text":"[ HC 110.237 , voto do rel. min. Celso de Mello , 2ª T, j. 19-2-2013, DJE 41 de 4-3-2013.]","deleted":false}],"heading":false},{"page":152,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":152,"runs":[{"text":"Competência da justiça federal comum para processar e julgar crime de falsificação de documentos para a obtenção de Título de Registro de Embarcação Miúda","deleted":false}],"heading":false},{"page":152,"runs":[{"text":"1. No caso dos autos, entendo que é possível aferir a existência de ilegalidade, devendo-se, por conseguinte, conceder a ordem. 1.1. Observo que o STM concluiu pela competência da Justiça Militar para o processamento da ação penal, tendo em vista a ofensa à ordem militar administrativa, (...). Em matéria de competência da Justiça Militar para o julgamento do civil, cumpre consignar que “o Supremo Tribunal Federal vem trilhando o entendimento de que a submissão do civil, em tempo de paz, à Justiça Militar é excepcional, que só se legitima quando a conduta delituosa ofender diretamente bens jurídicos de que sejam titulares as Forças Armadas” (HC 111.663, Rel. Min. TEORI ZAVASCKI, Segunda Turma, Dje 9.12.2014). Nesse sentir, a orientação do Supremo Tribunal Federal no caso de crime de falsificação de documentos para a obtenção de Título de Registro de Embarcação Miúda (TIEM) perante a Marinha do Brasil compreende falecer competência à Justiça Castrense, por se tratar de emissão de licença de natureza civil. (...) Como se vê, a conduta em apreço não se subsume às hipóteses restritivas de determinação da competência da Justiça Militar, à míngua do indispensável malferimento à Administração Militar e do comprometimento da ordem militar, em consonância com as normas de regência (art. 124 da CF/1988 e art. 9º, III, do CPM/1969). 4. Ante o exposto, com fulcro no art. 192 do RISTF, concedo a ordem, a fim de reconhecer a competência da Justiça Federal para processar e julgar a causa de origem.","deleted":false}],"heading":false},{"page":152,"runs":[{"text":"[ HC 135.161 , rel. min. Edson Fachin , dec. monocrática, j. 19-12-2018, DJE 20 de 4-2-2019.]","deleted":false}],"heading":false},{"page":152,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 36 ao militar da reserva","deleted":false}],"heading":false},{"page":152,"runs":[{"text":"Reconheço que a jurisprudência do Supremo Tribunal Federal é pacífica no sentido de que a “Justiça militar não detém competência para julgar civil denunciado pela prática do crime de uso de documento falso (Carteira de Inscrição e Registro CIR, expedida pela Marinha do Brasil) (...)”. Essa jurisprudência deu ensejo à Súmula Vinculante 36 do STF (...). 9. No caso de que se trata, contudo, o acórdão impugnado evidencia que “o paciente era, na época da prática delituosa, e ainda é, militar, porque é da reserva”. Circunstância que atrai, em linha de princípio, a regra do art. 12 do CPM/1969, segundo a qual “o militar da reserva ou reformado, empregado na administração militar, equipara-se ao militar em situação de atividade, para o efeito da aplicação da lei penal militar”. De modo que não vejo teratologia, ilegalidade flagrante ou abuso de poder que autorize a concessão da ordem de ofício.","deleted":false}],"heading":false},{"page":153,"runs":[{"text":"[ HC 131.515 , rel. min. Roberto Barroso , dec. monocrática, j. 25-11-2015, DJE 240 de 27-11-2015.]","deleted":false}],"heading":false},{"page":153,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":153,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-10-2014.","deleted":false}],"heading":false},{"page":153,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":153,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"37","number":"37","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":154,"endPage":163,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1961","paragraphs":[{"page":154,"runs":[{"text":"Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob o fundamento de isonomia.","deleted":false}]}],"notes":[{"page":154,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":154,"runs":[{"text":"A questão central a ser discutida nestes autos refere-se à possibilidade de o Poder Judiciário ou a Administração Pública aumentar vencimentos ou estender vantagens a servidores públicos civis e militares, regidos pelo regime estatutário, com fundamento no princípio da isonomia, independentemente de lei. Inicialmente, salienta-se que, desde a Primeira Constituição Republicana, 1891, em seus arts. 34 e 25, já existia determinação de que a competência para reajustar os vencimentos dos servidores públicos é do Poder Legislativo, ou seja, ocorre mediante edição de lei. Atualmente, a Carta Magna de 1988, art. 37, X, trata a questão com mais rigor, uma vez que exige lei específica para o reajuste da remuneração de servidores públicos. A propósito, na sessão plenária de 13-12-1963, foi aprovado o Enunciado 339 da Súmula desta Corte (...). Dos precedentes que originaram essa orientação jurisprudencial sumulada, resta claro que esta Corte pacificou o entendimento no sentido de que aumento de vencimentos de servidores depende de lei e não pode ser efetuado apenas com suporte no princípio da isonomia. (...) Registre-se que, em sucessivos julgados, esta Corte tem reiteradamente aplicado o Enunciado 339 da Súmula do STF, denotando que sua inteligência permanece atual para a ordem constitucional vigente.","deleted":false}],"heading":false},{"page":154,"runs":[{"text":"[ RE 592.317 , voto do rel. min. Gilmar Mendes , P, j. 28-8-2014, DJE 220 de 10-11-2014, Tema 315.]","deleted":false}],"heading":false},{"page":154,"runs":[{"text":"Ressalto que, segundo entendimento pacificado no Supremo Tribunal Federal, não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob fundamento de isonomia, conforme preceitua o Enunciado 339 da Súmula desta Corte, nem ao próprio legislador é dado, segundo o art. 37, XIII, da CF/1988, estabelecer vinculação ou equiparação de vencimentos.","deleted":false}],"heading":false},{"page":154,"runs":[{"text":"[ ARE 762.806 AgR , voto do rel. min. Gilmar Mendes , 2ª T, j. 3-9-2013, DJE 183 de 18-9-2013.]","deleted":false}],"heading":false},{"page":154,"runs":[{"text":"Tese de Controle Concentrado","deleted":false}],"heading":true},{"page":154,"runs":[{"text":"● Não cabe ao Poder Judiciário, sob o fundamento de isonomia, conceder retribuição por substituição a advogados públicos federais em hipóteses não previstas em lei","deleted":false}],"heading":false},{"page":154,"runs":[{"text":"[Tese definida na ADI 5.519 , rel. min. Roberto Barroso , P, j. 22-2-2023, DJE de 2-3-2023.]","deleted":false}],"heading":false},{"page":154,"runs":[{"text":"1. Ação direta contra o art. 38, caput e §§ 1º e 2º, da Lei nº 8.112/1990, que concede ao servidor substituto retribuição pelo exercício de cargo ou função de direção ou chefia e de cargo de natureza especial em período de afastamento do titular superior a 30 (trinta) dias. Alegação de violação à isonomia, pelo não pagamento em caso de substituição de advogados públicos federais que não exercem tais funções. (...) 3. O legislador federal, ao fixar a remuneração devida aos advogados públicos federais, estabeleceu parâmetros que, a seu ver, são suficientes para remunerar esse grupo profissional pelo exercício das diversas atividades inerentes ao cargo efetivo que ocupam. O art. 5º, XI, da Lei nº 11.358/2006 dispõe que não são devidos aos integrantes das carreiras o adicional pela prestação de serviço extraordinário. 4. O deferimento da retribuição postulada configuraria verdadeiro aumento de vencimentos pelo Poder Judiciário, o que afronta a Constituição Federal e a jurisprudência pacífica desta Corte. Precedentes. Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob fundamento de isonomia (Súmula vinculante nº 37). (...) 6. Pedido improcedente. Tese: “Não cabe ao Poder Judiciário, sob o fundamento de isonomia, conceder retribuição por substituição a advogados públicos federais em hipóteses não previstas em lei”.","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[ ADI 5.519 , rel. min. Roberto Barroso , P, j. 22-2-2023, DJE s/n de 2-3-2023.]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":155,"runs":[{"text":"● O regime administrativo remuneratório da contratação temporária é diverso do regime jurídico dos servidores efetivos, sendo vedada a extensão por decisão judicial de parcelas de qualquer natureza, observado o Tema 551/RG.","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[Tese fixada no RE 1.500.990 RG , rel. min. Luís Roberto Barroso , P. j. 25-10-2024, DJE s/n de 05-12-2024, Tema 1.344.]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"Ocorre que as razões de decidir do Tema 551/RG, para vedar a extensão de parcelas de servidores efetivos ou mesmo de regime celetista, incidem igualmente para obstar qualquer extensão ou equiparação de regimes jurídicos em favor de servidores contratados temporários. (...) Isso significa que os regimes constitucionais de contratação de pessoal (estatutário, celetista ou temporário) são diversos e não podem ser equiparados por decisão judicial, salvo se houver desvirtuamento da contratação temporária. É o que registrou o Min. Edson Fachin em seu voto no RE 1.066.677 (...).","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[ RE 1.500.990 RG , rel. min. Luís Roberto Barroso , P. j. 25-10-2024, DJE s/n de 05-12-2024]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"● A concessão, por decisão judicial, de diferenças salariais relativas a 13,23% a servidores públicos federais, sem o devido amparo legal, viola o teor da Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[Tese definida no ARE 1.208.032 RG , rel. min. Dias Toffoli , P, j. 29-8-2019, DJE 210 de 26-9-2019, Tema 1.061.]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"1. Os recentes pronunciamentos desta Corte são no sentido de que a determinação judicial de incorporação da vantagem referente aos 13,23% (Lei 10.698/2003) importa ofensa às Súmulas Vinculantes 10 e 37. 2. In casu, a decisão reclamada concluiu que a Lei 10.698/2003 possui caráter de verdadeira revisão geral anual, afastando a aplicação do artigo 1º da referida Lei. 3. Decisão de órgão fracionário que, embora não tenha expressamente declarado a inconstitucionalidade da referida norma, afastou sua aplicação, sem observância da cláusula de reserva de plenário (art. 97 da Constituição Federal), e, consectariamente, do enunciado da Súmula Vinculante 10.","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[ Rcl 23.443 AgR , rel. min. Luiz Fux , j. 5-5-2017, 1ª T, DJE 104 de 19-5-2017.]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"RECLAMAÇÃO - AGRAVO INTERNO - SERVIDOR PÚBLICO - INCORPORAÇÃO DA VANTAGEM DE 13,23% - CONCESSÃO DE REAJUSTE, PELO PODER JUDICIÁRIO, COM BASE NO PRINCÍPIO DA ISONOMIA - INADMISSIBILIDADE - RESERVA DE LEI E POSTULADO DA SEPARAÇÃO DE PODERES - SÚMULA VINCULANTE 37/STF - APLICABILIDADE AO CASO - PRECEDENTES - PARECER DA PROCURADORIA-GERAL DA REPÚBLICA PELO NÃO PROVIMENTO DA POSTULAÇÃO RECURSAL - RECURSO DE AGRAVO IMPROVIDO.","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[ Rcl 24.272 AgR , rel. min. Celso de Mello , 2ª T, j. 17-3-2017, DJE 101 de 16-5-2017.]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"● A extensão, pelo Poder Judiciário, das verbas e vantagens concedidas pelo Conselho de Reitores das Universidades do Estado de São Paulo (Cruesp) aos empregados das instituições de ensino autônomas vinculadas às universidades estaduais paulistas contraria o disposto na Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"[Tese definida no ARE 1.057.577 RG , rel. min. Gilmar Mendes , P, j. 1º-2-2019, DJE 71 de 8-4-2019, Tema 1.027.]","deleted":false}],"heading":false},{"page":155,"runs":[{"text":"● O Supremo Tribunal Federal veda o aumento de vencimentos pelo Poder Judiciário com base no princípio da isonomia, na equiparação salarial ou a pretexto da revisão geral anual, não sendo devida, portanto, a extensão do maior reajuste concedido pela Lei estadual 7.622/2000 aos soldos de toda a categoria dos policiais militares do Estado da Bahia, dispensada a devolução de valores eventualmente","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"recebidos de boa-fé até a data de conclusão do presente julgamento no Plenário Virtual desta Corte.","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[Tese definida no RE 976.610 RG , rel. min. Dias Toffoli , P, j. 15-2-2018, DJE 36 de 26-2-2018, Tema 984.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"● Não é devida aos servidores do Poder Judiciário do Estado do Rio de Janeiro a extensão do reajuste concedido pela Lei 1.206/1987, dispensando-se a devolução das verbas eventualmente recebidas até 1º-9-2016 (data da conclusão deste julgamento).","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[Tese definida no ARE 909.437 RG , rel. min. Roberto Barroso , P, j. 1º-9-2016, DJE 217 de 11-10-2016, Tema 915.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"Verifico, assim, que a extensão do reajuste da Lei 1.206/1987 aos serventuários do Poder Judiciário importa em conceder aumento de vencimentos com base no princípio da isonomia, em clara afronta ao disposto na Súmula 339 e na Súmula Vinculante 37. (...) Considerando, porém, que diversos servidores vêm recebendo tais verbas há muitos anos, com amparo na jurisprudência do órgão especial do TJRJ e inclusive no reconhecimento administrativo do direito, é necessário dispensar a devolução de valores eventualmente recebidos até a data da conclusão do presente julgamento, em atenção à segurança jurídica (CPC/2015, art. 525, § 13).","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[ ARE 909.437 RG , voto do rel. min. Roberto Barroso , P, j. 1º-9-2016, DJE 217 de 11-10-2016, Tema 915.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"● Não cabe, ao Poder Judiciário, que não tem a função legislativa, aumentar vencimentos de servidores públicos sob o fundamento de isonomia.","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[Tese definida no RE 592.317 , rel. min. Gilmar Mendes , P, j. 28-8-2014, DJE 220 de 10-11-2014, Tema 315.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"4. O deferimento de adicional noturno aos policiais rodoviários federais para o exercício de funções inerentes ao cargo configuraria verdadeiro aumento de vencimentos pelo Poder Judiciário, o que afronta a Constituição Federal e a jurisprudência pacífica desta Corte. Precedentes. Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob fundamento de isonomia (Súmula Vinculante nº 37). 5. Por outro lado, o regime de subsídio não é hábil a afastar o direito dos servidores à retribuição pelas horas extras realizadas que eventualmente ultrapassem a quantidade remunerada pela parcela única (ADI 5.114).","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[ ADI 5.404 , rel. min. Roberto Barroso , P, j. 6-3-2023, DJE de 9-3-2023.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"1. A concessão de reajuste salarial pelo índice mais benéfico para corrigir distorções causadas pela instituição de abono em valor fixo a diferentes categorias de servidores traduz aumento remuneratório promovido pelo Poder Judiciário com base na regra constitucional da isonomia salarial, conduta vedada pela Súmula Vinculante 37 (...).","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[ Rcl 27.310 AgR , rel. min. Rosa Weber , 1ª T, j. 5-10-2018, DJE 220 de 16-10-2018.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"IV - A equiparação entre advogados autárquicos e fundacionais inativos com procuradores da administração direta, sob fundamento de isonomia, implica ofensa à Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"[ RE 985.305 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 17-8-2018, DJE 181 de 3-9-2018.]","deleted":false}],"heading":false},{"page":156,"runs":[{"text":"Com efeito, a disciplina jurídica da remuneração devida aos agentes públicos em geral está sujeita ao princípio da reserva absoluta de lei. Esse postulado constitucional submete ao domínio normativo da lei formal a veiculação das regras pertinentes ao instituto do estipêndio funcional. O princípio da divisão funcional do poder impede que, estando em plena vigência o ato legislativo, venham os Tribunais a ampliar-lhe o conteúdo normativo e a estender a sua eficácia jurídica a situações subjetivas nele não previstas, ainda que a pretexto de tornar efetiva a cláusula isonômica inscrita na Constituição. (...) Não cabe, pois, ao Poder Judiciário atuar na anômala condição de legislador positivo (...), para, em assim agindo, proceder à imposição de seus próprios critérios, afastando, desse modo, os fatores que, no âmbito de nosso sistema constitucional, só podem ser legitimamente definidos pelo Parlamento. (...) O exame da presente causa evidencia, como anteriormente","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"ressaltado, que o acórdão impugnado em sede recursal extraordinária diverge da orientação que venho de referir, notadamente do que se contém na Súmula Vinculante 37/STF, cabendo assinalar, por extremamente relevante, que a colenda Segunda Turma do Supremo Tribunal Federal consagrou esse mesmo entendimento, ao julgar o ARE 841.799 AgR/RJ, rel. min. Teori Zavascki.","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"[ ARE 952.851 AgR , voto do rel. min. Celso de Mello , 2ª T, j. 6-2-2017, DJE 47 de 13-3-2017.]","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"A extensão do reajuste instituído pela Lei estadual 1.206/1987 aos servidores públicos do Poder Judiciário do Estado do Rio de Janeiro, com base no princípio da isonomia, contraria firme jurisprudência do Supremo Tribunal Federal consubstanciada na Súmula Vinculante 37 (“Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob o fundamento de isonomia”).","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"[ ARE 841.799 AgR , rel. min. Teori Zavascki , 2ª T, j. 23-2-2016, DJE 95 de 12-5-2016.]","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"Ao Poder Judiciário compete propor alterações dos respectivos cargos e fun- ções ao Legislativo (art. 96 da Constituição da República), ao qual cabe, se tanto deliberar, segundo processo constitucionalmente estabelecido, criar a norma legal com as mudanças propostas. (...) Não pode o Poder Judiciário compelir o Legislativo a criar lei sobre equiparação de remuneração de servidor público, conduta constitucionalmente vedada. Tampouco cabe ao Judiciário a função de legislar, criando cargos ou equiparando remuneração de servidores públicos, para tanto se articulando com o princípio da isonomia.","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"[ ARE 742.574 ED , voto da rel. min. Cármen Lúcia , 2ª T, j. 3-3-2015, DJE 50 de 16-3-2015.]","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":157,"runs":[{"text":"Aplicação da Súmula Vinculante 37 a empregados públicos","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"(...) esta Suprema Corte tem assentado em reiteradas decisões que o mencionado enunciado vinculante alcança empregados públicos.","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"[ Rcl 72.366 , rel. min. Nunes Marques , 2ª T, j. 7-4-2025, DJE s/n 13-5-2025.]","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"Aplicação da Súmula Vinculante 37 às relações trabalhistas regidas pela CLT","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"Ao estender à interessada, servidora celetista, os mesmos direitos previstos no Estatuto do Servidores do Município de Passo Fundo (Lei Complementar n. 203/2008), a Oitava Turma do Tribunal Regional do Trabalho da Quarta Região aumentou os vencimentos da autora da reclamação trabalhista sem previsão legal, fundamentando sua decisão na isonomia. Descumprido, portanto, o enunciado da Súmula Vinculante n. 37.","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"[ Rcl 58.673 , rel. min. Cármen Lúcia , dec. monocrática, j. 30-3-2023, DJE 71 de 4-4-2023.]","deleted":false}],"heading":false},{"page":157,"runs":[{"text":"Nesse contexto, constato que o TRT4 deferiu à empregada pública o pagamento de diferenças relativas ao adicional de insalubridade considerando o salário básico do servidor público como base de cálculo, sob o fundamento de que a Lei Complementar Municipal 203/2008 é aplicável aos empregados públicos do Município reclamante, equiparando os empregados públicos e os servidores públicos municipais. Nesse contexto, constato que o TRT4 deferiu à empregada pública o pagamento de diferenças relativas ao adicional de insalubridade considerando o salário básico do servidor público como base de cálculo, sob o fundamento de que a Lei Complementar Municipal 203/2008 é aplicável aos empregados públicos do Município reclamante, equiparando os empregados públicos e os servidores públicos municipais. Acontece que a autoridade reclamada outorgou aumento aos vencimentos da parte beneficiária sem previsão legal, utilizando-se do princípio da isonomia como justificativa, entendimento vedado por esta Corte. (...) o Tribunal de origem concedeu à ora agravante, contratada pelo regime celetista, o direito de que o adicional de insalubridade seja calculado sobre o salário base do servidor público do município, fundamentando-se no Estatuto dos Servidores Estatutários Municipais (Lei Complementar 203/2008). Todavia, ao realizar tal concessão, a autoridade reclamada outorgou aumento aos vencimentos da parte beneficiária sem previsão legal, utilizando-se do princípio da isonomia como justificativa, entendimento vedado por esta Corte. Desse modo, constata-se","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"existência de afronta ao nunciado da Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"[ Rcl 55.963 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 05-12-2022, DJE 151 de 12-12-2022.]","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"(...) o ato reclamado atribui a servidores o direito a vencimentos em valor diverso (maior) do que o fixado em lei, a fim de que seu nível remuneratório seja corrigido em proporção equivalente (isonômica) à correção recebida pelo cargo de menor remuneração. Está clara a realização da conduta vedada pela Súmula Vinculante 37 (...). Por fim, cabe afastar o argumento de que o comando da Súmula Vinculante 37 não obrigaria em relações de caráter trabalhista, regidas pela CLT, como a existente entre o Reclamante e a Interessada. Não há questionamento nos autos quanto ao caráter de servidor da Interessada, ocupante de cargo público na administração direta. O ato reclamado constrói sua tese a partir dos direitos de servidores públicos, e a própria norma constitucional por ele invocada, o artigo 37, X, direciona seu preceito aos servidores públicos. De igual forma, não caberia vislumbrar, na expressão “servidor público” utilizada pela SV 37, qualquer separação a partir do regime jurídico, estatutário ou celetista, mas a referência ao gênero das pessoas físicas que prestam serviços permanentes ao Estado.","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"[ Rcl 27.333 , rel. min. Gilmar Mendes , dec. monocrática, j. 6-4-2018, DJE 69 de 11-4-2018.]","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"Aplicação de súmula vinculante a ato editado antes de sua publicação","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"É cediço que a discussão acerca da aplicação de súmula vinculante a ato editado antes de sua publicação é demasiadamente delicada. Primeiramente, devemos levar em consideração que a causa petendi das ações que visam à defesa da Constituição Federal deve ser aberta, isso porque o julgador não está limitado aos fundamentos jurídicos indicados pelas partes ( iuri novit curia ) para que possa efetivar a defesa do texto constitucional. Segundo ponto é consignar que a causa petendi da reclamação é a ofensa à autoridade do STF prevista constitucionalmente e não à base jurídica que leva a essa conclusão. Esse posicionamento foi adotado pelo Plenário no julgamento do SE 5.206 AgR, em voto proferido em 8-5-1997 (...). Ressalto ainda que o Plenário do STF, no julgamento da Rcl 4.335, de minha relatoria, DJE de 22-10-2014, levando em consideração as peculiaridades do caso concreto, entendeu pela aplicação da Súmula Vinculante 26 à reclamação ajuizada antes da sua edição. (...) Na hipótese dos autos, mutatis mutandis , entendo que também devem ser levadas em consideração as peculiaridades do caso concreto para que seja observado o entendimento da Súmula Vinculante 37, apesar de posterior ao ato reclamado, haja vista que apenas consolidou o entendimento já sedimentado há muito por esta Corte. (...) No caso em apreço, os atos do CSJT e do TST, apesar de tentarem disfarçar, estão nitidamente fundados naquela decisão judicial ora cassada (...) igualmente respaldando-se no princípio da isonomia e na suposta violação do art. 37, X, da CF/1988, para convolar incremento absoluto de R$ 59,87 (cinquenta e nove reais e oitenta e sete centavos) em aumento de 13,23% retroativo a 2003, sem nenhuma autorização legal, em clara e direta afronta não só ao princípio da legalidade, como também à caudalosa jurisprudência do STF, que originou a Súmula 339, posteriormente convertida na Súmula Vinculante 37. (...) Dessa forma, resta claro que esta Corte pacificou o entendimento no sentido de que aumento de vencimentos de servidores depende de lei e não pode ser efetuado apenas com suporte no princípio da isonomia.","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"[ Rcl 14.872 , voto do rel. min. Gilmar Mendes , 2ª T, j. 31-5-2016, DJE 135 de 29-6-2016.]","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"Ato administrativo concessivo de aumento sem previsão legal","deleted":false}],"heading":false},{"page":158,"runs":[{"text":"É indiscutível, portanto, que o Conselho da Justiça Federal não pode, utilizando-se do princípio da isonomia, aumentar os vencimentos dos servidores públicos. Os arts. 96, inciso II, “a”; e 61, caput , da CF, determinam a competência do Supremo Tribunal Federal, aos Tribunais Superiores e aos Tribunais de Justiça para propor ao Poder Legislativo a criação e a extinção de cargos e remuneração. A Lei 9.421/1996, revogada pela Lei 11.336/2006, não previu expressamente a Gratificação de Representação Mensal. A jurisprudência consolidada do Supremo Tribunal Federal é clara ao impedir a instituição de aumento de remuneração, de ofício ou por decisão judicial, com base no princípio da isonomia.","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"[ ADI 1.777 , rel. min. Gilmar Mendes , P, j. 30-8-2019, DJE 200 de 16-9-2019.]","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"Decisão judicial que concede recomposição salarial com base em legislação infraconstitucional específica","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"A Súmula Vinculante 37 foi editada após reiterados precedentes que afirmaram a impossibilidade de se estender vantagem a servidor estatutário, com o intuito de promover equiparação salarial, reproduzindo texto da Súmula 339/STF. No entanto, ainda que se possa admitir a aplicação do verbete aos servidores regidos pela CLT, a situação dos autos encontra peculiaridades que a retiram do âmbito de incidência da Súmula Vinculante 37. 3. Com efeito, a parte beneficiária da decisão reclamada é empregado público originalmente contratado pela Fundação Municipal de Ensino Superior de Marília, mas que, por força da Lei estadual 8.898/1994 (disposições transitórias - arts. 2º e 3º), presta serviços e encontra-se subordinado à Faculdade de Medicina de Marília (FAMENA). Conforme decisões reclamadas, a Famena, autarquia estadual, é regida pelo Decreto 41.554/1997, que expressamente a submete à política remuneratória das universidades paulistas. 4. Nessas circunstâncias, a Justiça do Trabalho não afirmou o direito do servidor à recomposição remuneratória isoladamente com base no princípio da isonomia, mas por força das regras locais acerca da criação da Famena, bem como da regência infraconstitucional da sucessão de obrigações trabalhistas, cessão de trabalhadores e desvio de função. A questão passa, portanto, ao largo do enunciado da Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"[ Rcl 24.417 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 7-3-2017, DJE 82 de 24-4-2017.]","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"Determinação do CNJ para tribunal regulamentar condições para percepção de gratificação prevista em lei","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"A Lei estadual 11.919, que criou a gratificação por condições especiais de trabalho, não afastou o direito dos demais servidores efetivos, à luz do art. 1º, caput , à percepção da gratificação. Essa interpretação é corroborada pelo fato de que o próprio Tribunal de Justiça, ao regulamentar a lei, estendeu a outros servidores efetivos o direito à CET. 3. Se há o direito à percepção, inexiste ilegalidade na decisão do Conselho que, reconhecendo a omissão, determina que o Tribunal de Justiça regulamente as condições pelas quais os supervisores dos juizados farão jus à gratificação.","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"[ MS 31.285 , rel. min. Marco Aurélio , red. p/ o ac. min. Edson Fachin , 1ª T, j. 2-8-2016, DJE 215 de 7-10-2016.]","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"Ofensa à Súmula Vinculante 37 na equiparação de cargos no Estado de Mato Grosso do Sul","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"Na esteira dessa remansosa jurisprudência, ao julgar o ARE 1.278.713, de minha relatoria na Presidência, Tema 1.126 da Repercussão Geral, DJe de 25/02/2021, o Plenário do Supremo Tribunal Federal fixou a seguinte tese: “Ofende a Súmula Vinculante 37 a equiparação, pela via judicial, dos cargos de Analista Judiciário área fim e Técnico de Nível Superior do Tribunal de Justiça do Estado de Mato Grosso do Sul, anteriormente à Lei Estadual 4.834/2016.”","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"[ RE 1.404.702 , rel. min. Luiz Fux , dec. monocrática, j. 17-2-2025, DJE s/n 18-2-2025.]","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"Princípio da simetria e Súmula Vinculante 37","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"14. Em que pese o acórdão recorrido não ter determinado de forma direta o aumento de vencimentos de servidores públicos sob o fundamento de isonomia, ao reputar a invalidade da Lei Complementar nº 03, de 2015 - devido à alteração trazida pela Lei Complementar nº 05, de 2017, influiu em aumento salarial do cargo de Procurador Jurídico da Câmara e, após, a Lei Complementar nº 10, de 2017, novamente -, acaba por incorrer na necessária imposição de que os vencimentos pagos ao Poder Legislativo diminuam em conformação aos pagos ao Poder Executivo. 15. Além disso, o enunciado nº 37 da Súmula Vinculante veda a equiparação sob o fundamento de isonomia. Portanto, entendo vedada, também, a aplicação do princípio da isonomia, na sua subespécie ¿paridade¿ para a equiparação salarial de poderes diferentes","deleted":false}],"heading":false},{"page":159,"runs":[{"text":"[ ARE 1.447.676 AgR , rel. min. André Mendonça , P, j. 7-8-2024, DJE s/n de 4-9-2024.]","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"QUESTÃO DE ORDEM NO AGRAVO REGIMENTAL NA RECLAMAÇÃO. SOBRESTAMENTO. RETIRADA. JULGAMENTO DO MÉRITO DA RECLAMAÇÃO. MAGISTRADO. CONVERSÃO DE UM TERÇO DE FÉRIAS EM ABONO PECUNIÁRIO. SIMETRIA COM OS MEMBROS DO MINISTÉRIO PÚBLICO. CONTRARIEDADE À SÚMULA VINCULANTE 37 DO SUPREMO TRIBUNAL FEDERAL. PRECEDENTES. RECLAMAÇÃO JULGADA PARCIALMENTE PROCEDENTE PARA CASSAR A DECISÃO RECLAMADA E DETERMINAR SOBRESTAMENTO DA AÇÃO NA ORIGEM.","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"[ Rcl 27.319 QO , rel. min. Cármen Lúcia , 2ª T, j. 11-6-2019, DJE 182 de 21-8-2019.]","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"(...) Da leitura do acórdão impugnado extrai-se haver a Turma Recursal assentado a pertinência do pagamento da verba, apesar da ausência de dispositivo legal específico a respaldá-lo, ante a suposta simetria existente, inclusive sob o ângulo remuneratório, entre os regimes jurídicos das carreiras da magistratura e do Ministério Público da União. (...) O quadro revela inobservância do paradigma. A pretexto de assegurar-se isonomia remuneratória - gênero -, no que incluídas vantagens indenizatórias, acabou-se reconhecendo a membro da magistratura o pagamento de ajuda de custo com base em legislação voltada a disciplinar a situação específica dos integrantes do Ministério Público da União. Consoante se verifica, o pronunciamento reclamado resultou, de modo imediato, em alteração da remuneração de servidor público, no que constatado, de forma direta, o impacto financeiro.","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"[ Rcl 32.086 MC , rel. min. Marco Aurélio , dec. monocrática, j. 11-10-2018, DJE 222 de 18-10-2018.]","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"8. Também posiciona-se esta Suprema Corte no sentido da necessidade de previsão legal específica para concessão de equiparação de vencimentos entre servidores, vedado ao Poder Judiciário conceder benefícios ao fundamento de isonomia, conforme enunciado da Súmula 339/STF (...). 10. Dessa forma, ainda que a decisão reclamada aponte como fundamento para a concessão de licença-prêmio de magistrado o contido na Lei Complementar 75/1993 (Lei Orgânica do Ministério Público da União) e a Resolução 133/2011 do Conselho Nacional de Justiça, que invoca a simetria entre as carreiras do Ministério Público e a Magistratura, reputo violada a Súmula Vinculante 37. E isso porquanto, ao conceder extensão de vantagem com fundamento na simetria entre as carreiras da Magistratura e do Ministério Público, essa calcada na isonomia, acabou a decisão reclamada por modificar a forma de remuneração dos magistrados sem prévia autorização legal, o que encontra óbice no entendimento sumulado deste Supremo Tribunal Federal. (...) 12. Ante o exposto, forte no art. 161, parágrafo único, do RISTF, julgo procedente a presente reclamação para cassar a decisão reclamada no Processo (...) e determinar que outra seja proferida com observância da Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"[ Rcl 26.923 , rel. min. Rosa Weber , dec. monocrática, j. 24-9-2018, DJE 210 de 2-10-2018.]","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"1. Até que sobrevenha decisão do STF na ADI 4.822/PE ou nos Temas 966 e 976 de repercussão geral (o que ocorrer primeiro), a eficácia da Súmula vinculante 37 obsta que o Poder Judiciário, no exercício da jurisdição, defira o pagamento de parcela remuneratória a magistrado com fundamento na alegada simetria constitucional com a carreira do Ministério Público (CF/88, art. 129, §4º) ou na Resolução 133/2011 do CNJ. 2. Agravo regimental provido, com a ressalva do posicionamento pessoal do Relator, para julgar parcialmente procedente a reclamação e, cassando a decisão impugnada, determinar o sobrestamento do processo em referência perante a autoridade reclamada até que sobrevenha decisão do STF na ADI 4.822/PE ou nos Temas 966 e 976 de repercussão geral (o que ocorrer primeiro), após o que deverá ela proceder a novo julgamento da causa como entender de direito.","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"[ Rcl 28.319 AgR , rel. min. Dias Toffoli , 2ª T, j. 7-8-2018, DJE 198 de 20-9-2018.]","deleted":false}],"heading":false},{"page":160,"runs":[{"text":"AGRAVO REGIMENTAL NA RECLAMAÇÃO. DIREITO CONSTITUCIONAL E ADMINISTRATIVO. MAGISTRADOS. CONCESSÃO DE VANTAGENS COM FUNDAMENTO NA ISONOMIA COM OS MEMBROS DO MINISTÉRIO PÚBLICO. SÚMULA VINCULANTE 37. PENDÊNCIA DA ANÁLISE DA CONSTITUCIONALIDADE DA RESOLUÇÃO 133 DO CNJ NA ADI 4.822. MATÉRIA SOB REPERCUSSÃO GERAL. TEMAS 966 E 976. SUSPENSÃO DO ATO RECLAMADO E SOBRESTAMENTO DO JULGAMENTO DA RECLAMAÇÃO. AGRAVO REGIMENTAL PROVIDO. 1. A controvérsia acerca da constitucionalidade da","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"Resolução 133 do CNJ, que dispõe sobre a concessão de equiparação de vantagens funcionais a magistrados com fundamento na simetria constitucional com os membros do Ministério Público, é objeto de questionamento por meio da ADI 4.822/PE, de relatoria do Min. Marco Aurélio e dos REs 1059466 (Tema 966) e 968646 (Tema 976), ambos da relatoria do Min. Alexandre de Moraes. 2. Em decorrência da verticalização das decisões do Plenário, impõe-se a suspensão do ato reclamado e o sobrestamento do julgamento da presente reclamação até a definição do mérito da matéria. 3. Agravo regimental provido para suspender o ato reclamado e determinar o sobrestamento dos autos.","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"[ Rcl 26.924 AgR , rel. min. Dias Toffoli , red. p/ o ac. min. Edson Fachin , 2ª T, j. 6-3-2018, DJE 113 de 8-6-2018.]","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"RECLAMAÇÃO. CONCESSÃO DE DIÁRIAS A INTEGRANTE DA MAGISTRATURA. PRINCÍPIO DA SIMETRIA. AUSÊNCIA DE IDENTIDADE MATERIAL ENTRE O ATO RECLAMADO E O VERBETE DA SÚMULA VINCULANTE 37. EXCEPCIONALIDADE DO DISPOSTO NO ART. 102, I, N, DA CONSTITUIÇÃO FEDERAL. AGRAVO REGIMENTAL A QUE SE NEGA PROVIMENTO. I - A concessão de diárias a integrante da Magistratura com fundamento no princípio da simetria não enseja reclamação por ofensa à Súmula Vinculante 37. II - A interpretação atual da regra do art. 102, I, n, da Constituição é no sentido de que somente se adequam à norma em exame aquelas demandas nas quais se demonstre a presença, cumulativamente, de dois requisitos, quais sejam: (i) a existência de interesse de toda a Magistratura; (ii) que esse interesse seja exclusivo dos Magistrados.","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"[ Rcl 28.655 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 20-2-2018, DJE 123 de 21-6-2018.]","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"AGRAVO REGIMENTAL. RECLAMAÇÃO. CONCESSÃO DE AJUDA DE CUSTO A INTEGRANTE DA MAGISTRATURA. PRINCÍPIO DA SIMETRIA. AUSÊNCIA DE IDENTIDADE MATERIAL ENTRE O ATO RECLAMADO E O VERBETE DA SÚMULA VINCULANTE 37. EXCEPCIONALIDADE DO DISPOSTO NO ART. 102, I, N, DA CONSTITUIÇÃO FEDERAL. AGRAVO REGIMENTAL A QUE SE NEGA PROVIMENTO. I - A concessão de ajuda de custo a integrante da Magistratura com fundamento no princípio da simetria não enseja reclamação por ofensa à Súmula Vinculante 37. II - A interpretação atual da regra do art. 102, I, n , da Constituição é no sentido de que somente se adequam à norma em exame aquelas demandas nas quais se demonstre a presença, cumulativamente, de dois requisitos, quais sejam: (i) a existência de interesse de toda a Magistratura; (ii) que esse interesse seja exclusivo dos Magistrados","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"[ Rcl 26.466 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 11-12-2017, DJE 23 de 8-2-2018.]","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"O Supremo Tribunal Federal há muito consolidou o entendimento segundo o qual não cabe ao Poder Judiciário conceder benefícios a servidores públicos sob a égide do princípio da isonomia, sendo inquestionável a necessidade de lei específica para tanto, nos termos do art. 39, § 1º, da Constituição Federal. (...) Assim, prima facie, depreende-se configurado o fumus boni iurisdiante da impossibilidade de que o Poder Judiciário promova aumento salarial a servidor público com base no princípio da isonomia. De outra parte, também entendo estar presente o periculum in mora, dado o fundado receio de que a decisão ora combatida venha a produzir efeitos de cunho executivo, incorrendo em prejuízos aos cofres públicos.","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"[ Rcl 25.460 MC , rel. min. Edson Fachin , dec. monocrática, j. 31-3-2017, DJE 69 de 6-4-2017.]","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"Reconhecimento do direito a férias e afastamento da Súmula Vinculante 37","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"In casu , não se revela qualquer violação à Súmula Vinculante 37, não cabendo confundir o reconhecimento do direito a férias com aumento de remuneração sob o fundamento de isonomia.","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"[ Rcl 19.627 AgR , rel. min. Luiz Fux , 1ª T, j. 23-2-2016, DJE 47 de 14-3-2016.]","deleted":false}],"heading":false},{"page":161,"runs":[{"text":"(...) o caso decorre de pretensão de recebimento de diferenças de gratificação natalina, férias acrescidas de terço constitucional (bem assim do reflexo dessas férias sobre a gratificação natalina), tendo a sentença, mantida pelo acórdão ora reclamado, julgado procedentes em parte os pedidos, reconhecendo o direito de professor temporário às férias proporcionais, uma vez que não houve fruição de férias nem o pagamento do","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"correspondente terço. No ponto, levou-se em conta, sob o princípio da isonomia, o período especial de férias de 45 dias dos professores ocupantes de cargo efetivo. Como se vê, houve majoração apenas da verba devida a título de férias proporcionais. Nessas circunstâncias, em que não acolhido pedido de aumento de vencimentos, não há falar em aderência estrita entre o ato reclamado e a Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"[ Rcl 19.720 AgR , voto do rel. min. Teori Zavascki , 2ª T, j. 25-8-2015, DJE 177 de 9-9-2015.]","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"Súmula Vinculante 37 e aplicação isonômica de lei concessiva de revisão geral de reajuste","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"Diversamente do que sugere o reclamante, da leitura do acórdão reclamado não se verifica ofensa direta ao enunciado vinculante em questão, haja vista que não se fez presente a concessão de aumento salarial pelo Poder Judiciário, mas a determinação de aplicação da Lei 8.970/2009 de forma uniforme a todos os servidores, diante da impossibilidade de se conceder revisão geral com distinção de índices entre os servidores, o que torna impertinente a alegação de violação àquele verbete. Em outras palavras, in casu , o Poder Judiciário não atuou como legislador positivo, o que é vedado pela Súmula, mas, apenas e tão somente, determinou a aplicação da lei de forma isonômica. Situação diversa seria aquela em que, não existindo lei concessiva de revisão, o Judiciário estendesse o reajuste. Entendimento idêntico foi esposado pelo ministro Celso de Mello no julgamento do AI 401.337 AgR/PE, ocasião em que se concluiu pela não incidência da Súmula 339 (que deu origem à Súmula Vinculante 37) (...).","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"[ Rcl 20.864 AgR , voto do rel. min. Luiz Fux , 1ª T, j. 15-12-2015, DJE 28 de 16- 2-2016.]","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"Vedação ao reposicionamento e recomposição salarial de empregado anistiado à luz da SUV 37","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"(...) O Supremo Tribunal Federal tem jurisprudência quanto ao entendimento de que o reconhecimento do direito do empregado anistiado e readmitido ao reposicionamento na carreira, progressões gerais e recomposição salarial, a título de isonomia, viola o disposto no verbete nº 37 da Súmula do STF, porquanto traduz aumento remuneratório promovido pelo Poder Judiciário com base na regra constitucional da isonomia.","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"[ Rcl 65.557 , rel. min. André Mendonça , 2ª T, j. 17-2-2025, DJE s/n 28-2-2025.]","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"Violação à Súmula Vinculante 37 e vantagem pecuniária individual concedida pela Lei 10.698/2003","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"INCORPORAÇÃO AO VENCIMENTO DE SERVIDOR PÚBLICO DO REAJUSTE DE 13,23%. CORREÇÃO DE DISTINÇÃO DE ÍNDICES. PRINCÍPIO DA ISONOMIA. EXISTÊNCIA DE AFRONTA À SÚMULA VINCULANTE 37. PRECEDENTES. 1. A concessão de reajuste salarial para corrigir distorções causadas pela instituição de vantagem pecuniária em valor fixo a diferentes categorias de servidores traduz aumento remuneratório promovido pelo Poder Judiciário com base na regra constitucional da isonomia salarial, conduta vedada pela Súmula Vinculante 37 (Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob o fundamento de isonomia).","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"[ Rcl 27.601 AgR , rel. min. Rosa Weber , 1ª T, j. 18-12-2018, DJE 29 de 13-2-2019.]","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"Agravo regimental na reclamação. Súmulas Vinculantes nºs 10 e 37. Lei 10.698/2003. Reajuste remuneratório de servidor público sem previsão legal. Princípio da isonomia. Agravo regimental não provido. 1 (...). 2. É defeso ao Poder Judiciário conceder, sem a devida previsão legal, reajuste remuneratório com fundamento no princípio da isonomia, sob pena de violar o conteúdo da Súmula Vinculante 37.","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"[ Rcl 30.063 AgR , rel. min. Dias Toffoli , 2ª T, j. 29-6-2018, DJE 174 de 24-8-2018.]","deleted":false}],"heading":false},{"page":162,"runs":[{"text":"O cerne da questão reside em verificar se a incorporação, por decisão judicial, das diferenças relativas à implementação da vantagem pecuniária individual - VPI, concedida aos servidores públicos federais pelas Leis 10.697/2003 e 10.698/2003, no patamar de 13,23%, violaria o Enunciado Vinculante em evidência. In casu , assiste razão à reclamante. A sentença reclamada, ao assentar como correta a concessão do reajuste, porquanto se trataria apenas de individuação do disposto na lei 10.698/2003, ofende o teor da Súmula Vinculante 37 do STF. (...) A superveniência da Lei 13.317/2016 não é fundamento capaz de infirmar o pacífico entendimento dessa Corte quanto à violação da Súmula Vinculante sub examine em situações análogas, uma","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"vez que a Lei 13.317/2016, tal qual a Lei 10.698/2003, em momento algum indica ser devido semelhante índice. Da ratio do dispositivo contido no art. 6º da Lei 13.317/2016 não se extrai o direito ao reajuste em tela, o que fica evidenciado, inclusive, pelas justificativas apresentadas quando da apresentação do Projeto de Lei que a originou (PL 2648/2015), pelo Supremo Tribunal Federal. (...) Outrossim, observo que, mesmo após a edição da Lei 13.317/2016, este Tribunal tem continuado a reiterar a posição segundo a qual a concessão do reajuste de 13,23% violaria a Súmula Vinculante 37","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"[ Rcl 25.655 , rel. min. Luiz Fux , dec. monocrática, j. 24-5-2018, DJE 103 de 28-5-2018.]","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"Os recentes pronunciamentos desta Corte são no sentido de que a determinação judicial de incorporação da vantagem referente aos 13,23% (Lei 10.698/2003) importa ofensa às Súmulas Vinculantes 10 e 37. 2. In casu , a decisão reclamada concluiu que a Lei 10.698/2003 possui caráter de verdadeira revisão geral anual, afastando a aplicação do art. 1º da referida lei. 3. Decisão de órgão fracionário que, embora não tenha expressamente declarado a inconstitucionalidade da referida norma, afastou sua aplicação, sem observância da cláusula de reserva de plenário (art. 97 da Constituição Federal), e, consectariamente, do enunciado da Súmula Vinculante 10.","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"[ Rcl 23.443 AgR , rel. min. Luiz Fux , 1ª T, j. 5-5-2017, DJE 104 de 19-5-2017.]","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"(...) verifica-se que, ao contrário do consignado pelo ato reclamado, a Lei 13.317/2016 não determinou a incorporação do percentual em discussão (13,23%), apenas assentou que a vantagem pecuniária individual instituída pela Lei 10.698/2003 e outras parcelas que tenham por origem a citada vantagem, concedidas por decisão administrativa ou judicial, ainda que decorrente de sentença transitada em julgado, ou não, ficariam absorvidas pela implementação do novo reajuste. (...) Dessa forma, verifica-se que a nova decisão do processo, ao conceder a incorporação dos 13,23% à remuneração do servidor, sem amparo legal, também violou o disposto na Súmula Vinculante 37 e a decisão definitiva desta reclamação.","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"[ Rcl 24.469 , rel. min. Gilmar Mendes , dec. monocrática, j. 13-3-2017, DJE 50 de 16-3-2017.]","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":163,"runs":[{"text":"● A Súmula Vinculante 37 resultou da conversão da Súmula 339.","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 315, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"● Tema 966 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"● Tema 976 de Repercussão Geral (reconhecida).","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-10-2014.","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":163,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"38","number":"38","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":164,"endPage":166,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2183","paragraphs":[{"page":164,"runs":[{"text":"É competente o Município para fixar o horário de funcionamento de estabelecimento comercial.","deleted":false}]}],"notes":[{"page":164,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":164,"runs":[{"text":"No caso, verifico que a competência para disciplinar o horário de funcionamento de estabelecimentos comerciais é do município, tendo em vista o que dispõe o art. 30, I, da CF/1988. Esta Corte já possui entendimento assentado nesse sentido, consolidado no enunciado da Súmula 645/STF: “É competente o município para fixar o horário de funcionamento de estabelecimento comercial”. (...) deve-se entender como interesse local, no presente contexto, aquele inerente às necessidades imediatas do Município, mesmo que possua reflexos no interesse regional ou geral. Dessa forma, não compete aos Estados a disciplina do horário das atividades de estabelecimento comercial, pois se trata de interesse local.","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"[ ADI 3.691 , voto do rel. min. Gilmar Mendes , P, j. 29-8-2007, DJE 83 de 9-5-2008.]","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"Está claramente definido no art. 30, I, da Constituição Federal que o Município tem competência para legislar sobre assuntos de interesse local. (...) 8. Entre as várias competências compreendidas na esfera legislativa do Município, sem dúvida estão aquelas que dizem respeito diretamente ao comércio, com a consequente liberação de alvarás de licença de instalação e a imposição de horário de funcionamento, daí parecer-me atual e em plena vigência, aplicável inclusive ao caso presente, a Súmula 419 desta Corte, que já assentara que “os Municípios têm competência para regular o horário do comércio local, desde que não infrinjam leis estaduais ou federais válidas”.","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"[ RE 189.170 , voto do rel. min. Marco Aurélio , P, j. 1º-2-2001, DJ de 8-8-2003.]","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":164,"runs":[{"text":"A normatização pelos Municípios deve obedecer às disposições das esferas federal e estadual","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"O juízo reclamado não desconsidera a competência municipal para regular o horário de funcionamento dos estabelecimentos comerciais. Entende, porém, que a normatização do ente local deve obedecer às disposições das esferas federal e estadual. Essa compreensão encontra amparo, inclusive, na Súmula 419 deste Tribunal. Só se poderia falar em transgressão ao enunciado vinculante n. 38 se o órgão reclamado tivesse, expressa ou tacitamente, negado a competência municipal para regular a matéria em enfoque. Não é esse, contudo, o cenário que se apreende dos autos.","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"[ Rcl 74.815 , rel. min. Nunes Marques , dec. monocrática, j. 3-2-2025, DJE s/n 12-2-2025.]","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"Aplicação dos princípios da razoabilidade e da livre iniciativa na imposição de restrição de horário de funcionamento de estabelecimento comercial pelo Município","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"4. O teor do enunciado nº 38 da Súmula Vinculante do STF , a par de assentar o respeito à competência do Município para fixar o horário de funcionamento de estabelecimento comercial, não implica a autorização ao ente para impor restrição de horário que não atenda aos princípios da razoabilidade e da livre iniciativa.","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"[ ARE 1.546.469 AgR , rel. min. André Mendonça , 2ª T, j. 19-8-2025, DJE s/n 28-8-2025.]","deleted":false}],"heading":false},{"page":164,"runs":[{"text":"Competência do Município para disciplinar o horário de funcionamento de estabelecimentos comerciais","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"1. Reclamação em que se impugna sentença na qual se afirmou, incidentalmente, a inconstitucionalidade material de dispositivo da Lei 5.954/2013 do Município de Colatina-ES que veda o funcionamento ininterrupto de farmácias. 2. A Súmula Vinculante 38 afirma a competência Municipal para estabelecer o horário de funcionamento do comércio local. Do seu texto, no entanto, não decorre a afirmação de constitucionalidade material de todas as normas editadas sob o exercício de tal competência.","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"[ Rcl 35.075 , rel. min. Roberto Barroso , 1ª T, j. 27-09-2019, DJE 220 de 10-10-2019.]","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"No caso, aponta-se ofensa à Súmula Vinculante 38, uma vez que a decisão reclamada teria violado a competência constitucionalmente conferida ao reclamante para dispor quanto ao horário de funcionamento dos estabelecimentos comerciais nele localizados da forma que melhor atendesse aos interesses locais. (...) Verifico que o ato reclamado respalda-se nos princípios da livre concorrência, da defesa do consumidor e da liberdade do exercício de atividade econômica para concluir, em juízo de prelibação, pela aparente inconstitucionalidade das normas municipais que impedem o funcionamento de estabelecimentos comerciais aos domingos e aos sábados à tarde, exceto quando se trate de serviço essencial (...). Dessa forma, resta claro que divergiu do entendimento contido na Súmula Vinculante 38, interferindo na autonomia de determinação do ente municipal a partir de juízo de ponderação com princípios constitucionais de pouca densidade normativa.","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"[ Rcl 24.518 MC , rel. min. Gilmar Mendes , dec. monocrática, j. 4-5-2017, DJE 97 de 10-5-2017.]","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"O recurso extraordinário é inadmissível. O Supremo Tribunal Federal já decidiu positivamente acerca da competência do Município, e não do Estado, para legislar a respeito de horário de funcionamento de estabelecimento comercial, inclusive para aqueles que comercializam bebidas alcoólicas, por ser matéria de interesse local, nos termos do art. 30, I, da Constituição Federal. (...) 5. Cabe ressaltar, ademais, que o Supremo Tribunal Federal, na sessão plenária de 11-3-2015, reafirmou o entendimento consagrado na Súmula 645/STF ao editar a Súmula Vinculante 38. (...). 6. Diante do exposto, nego provimento ao agravo regimental.","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"[ RE 852.233 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 26-8-2016, DJE 206 de 27-9-2016.]","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"Conforme consignado na decisão que se agrava, o acórdão recorrido está em harmonia com a orientação sedimentada nesta Corte na Súmula Vinculante 38, quanto à competência municipal para fixar horário de funcionamento de estabelecimento comercial. Ademais, constata-se que a Corte de origem declarou a inconstitucionalidade do parágrafo único do art. 1º da Lei 9.452/2009, que condicionava a abertura do comércio à realização de acordo ou convenção coletiva de trabalho, por extrapolar a competência municipal. Neste ponto, verifica-se a falta de interesse recursal da recorrente. Ante o exposto, nego provimento ao agravo regimental.","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"[ RE 732.222 AgR , rel. min. Edson Fachin , 1ª T, j. 15-3-2016, DJE 70 de 15-4-2016.]","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"Com efeito, a controvérsia constitucional instaurada na presente causa já se acha dirimida pelo Supremo Tribunal Federal, (...) ao julgar a ADI 3.691/MA, rel. min. Gilmar Mendes (...). Esse entendimento tem sido observado pelo Supremo Tribunal Federal, cujas decisões, proferidas em sucessivos julgamentos sobre a matéria ora em exame, reafirmaram a tese segundo a qual compete ao Município - por tratar-se de matéria de interesse local (CF, art. 30, I) - fixar o horário de funcionamento de estabelecimentos comerciais, sem que o exercício dessa prerrogativa institucional importe em ofensa aos postulados constitucionais da isonomia, da livre iniciativa, da livre concorrência, do direito à saúde ou da defesa do consumidor (...).","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"[ RE 926.993 , rel. min. Celso de Mello , dec. monocrática, j. 27-11-2015, DJE 245 de 4-12-2015.]","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"Competência do Município para legislar sobre interesse local e restrição ao princípio da livre iniciativa","deleted":false}],"heading":false},{"page":165,"runs":[{"text":"O Supremo Tribunal Federal, no julgamento da ADI 907, Rel. Min. Alexandre de Moraes, cujo acórdão coube a minha relatoria, entendeu que viola o princípio da livre iniciativa - art. 107, IV, da CF - a obrigatoriedade de exigir que os supermercados e estabelecimentos do gênero ofereçam serviço de empacotamento das compras. (...) O acórdão proferido pelo Tribunal de origem divergiu desta orientação, pois entendeu ser","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"constitucional a obrigatoriedade de oferecimento desse serviço, considerando inconstitucional apenas a obrigatoriedade de contratar empacotadores. Nesse sentido confira-se o RE 822.264, Rel. Min. Dias Toffoli, que declarou a inconstitucionalidade da Lei 9.770, de 24 de outubro de 2011, do Município de Sorocaba, que tornava obrigatória a instalação de serviço ambulatorial, contando com, no mínimo, um enfermeiro, destinado ao primeiro atendimento de clientes e funcionários, nos shoppings e hipermercados do município. Nesse ponto, o recurso merece provimento.","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"[ RE 402.136 , rel. min. Roberto Barroso , dec. monocrática, j. 25-4-2018, DJE 84 de 2-5-2018.]","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"2. Acerca do vício formal, toda e qualquer obrigação imposta a agentes privados acabará produzindo, direta ou indiretamente, impactos sobre a atividade empresarial ou de ordem trabalhista. Sendo assim, não se vislumbra usurpação da competência legislativa privativa da União, prevista no art. 22, I, da Constituição. Também não parece ser o caso de evidente invasão da competência dos Municípios para legislar sobre assuntos de interesse local, tal como disposto no art. 30, I, da CF/88, de que é exemplo a competência para disciplinar o horário de funcionamento de estabelecimentos comerciais (Súmula Vinculante 38). 3. Por outro lado, a Lei 2.130/1993, do Estado do Rio de Janeiro, padece de vício material. Isso porque a restrição ao princípio da livre iniciativa, protegido pelo art. 170, caput , da Constituição, a pretexto de proteger os consumidores, não atende ao princípio da proporcionalidade, nas suas três dimensões: (i) adequação; (ii) necessidade; e (iii) proporcionalidade em sentido estrito. 4. A providência imposta pela lei estadual é inadequada porque a simples presença de um empacotador em supermercados não é uma medida que aumente a proteção dos direitos do consumidor, mas sim uma mera conveniência em benefício dos eventuais clientes. Trata-se também de medida desnecessária, pois a obrigação de contratar um empregado ou um fornecedor de mão-de-obra exclusivamente com essa finalidade poderia ser facilmente substituída por um processo mecânico. Por fim, as sanções impostas revelam a desproporcionalidade em sentido estrito, eis que capazes de verdadeiramente falir um supermercado de pequeno ou médio porte. 5. Procedência da ação, para declarar a inconstitucionalidade da Lei 2.130/1993, (...).","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"[ ADI 907 , rel. min. Alexandre de Moraes , red. p/ o ac. Roberto Barroso , P, j. 1º-8-2017, DJE 266 de 24-11-2017.]","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"Pois bem. Considerando a natureza das atividades ordinariamente exercidas nos shoppings e nos hipermercados, constata-se que inexiste proporcionalidade na exigência feita pela lei municipal, a qual restringe o princípio da livre iniciativa: o diploma em questão determina que seja instalado nos estabelecimentos desses tipos localizados no Município de Sorocaba serviço ambulatorial, destinado a primeiro atendimento dos clientes, (...). Vide, ademais, que o não cumprimento dessa determinação nos prazos previstos resulta, sucessivamente, na imposição de multas progressivas e na interdição do estabelecimento, até que seja efetuada a regularização. De mais a mais, nem se diga que a lei impugnada deveria subsistir no tocante à obrigatoriedade de instalação, nos shoppings e hipermercados de Sorocaba, do serviço ambulatorial destinado a primeiro atendimento exclusivamente dos funcionários desses estabelecimentos. Afinal, é competência privativa da União legislar sobre direito do trabalho (art. 22, I, da Constituição Federal).","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"[ RE 822.264 , rel. min. Dias Toffoli , dec. monocrática, j. 27-9-2017, DJE 227 de 4-10-2017.]","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":166,"runs":[{"text":"● A Súmula Vinculante 38 resultou da conversão da Súmula 645.","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"● Vide Súmula 419.","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-3-2015.","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":166,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"39","number":"39","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":167,"endPage":168,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2197","paragraphs":[{"page":167,"runs":[{"text":"Compete privativamente à União legislar sobre vencimentos dos membros das polícias civil e militar e do corpo de bombeiros militar do Distrito Federal.","deleted":false}]}],"notes":[{"page":167,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":167,"runs":[{"text":"Ao instituir a chamada “gratificação por risco de vida” dos policiais e bombeiros militares do Distrito Federal, o Poder Legislativo distrital usurpou a competência material da União para “organizar e manter a polícia civil, a polícia militar e o corpo de bombeiros militar do Distrito Federal, bem como prestar assistência financeira ao Distrito Federal para a execução de serviços públicos, por meio de fundo próprio” (inciso XIV do art. 21 da Constituição Federal). Incidência da Súmula 647 do STF.","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"[ ADI 3.791 , rel. min. Ayres Britto , P, j. 16-6-2010, DJE 159 de 27-8-2010.]","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"Ao prescrever a Constituição (art. 21, XIV) que compete à União organizar e manter a polícia do Distrito Federal - apesar do contrassenso de entregá-la depois ao comando do governador (art. 144, § 6º) -, parece não poder a lei distrital dispor sobre o essencial do verbo “manter”, que é prescrever quanto custará pagar os quadros de servidores policiais: desse modo a liminar do Tribunal de Justiça local, que impõe a equiparação de vencimentos entre policiais - servidores mantidos pela União - e servidores do Distrito Federal, parece que, ou impõe a este despesa que cabe à União ou, se a imputa a esta, emana de autoridade incompetente e, em qualquer hipótese, acarreta risco de grave lesão à ordem administrativa.","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"[ SS 846 AgR , rel. min. Sepúlveda Pertence , P, j. 29-5-1996, DJ de 8-11-1996.]","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":167,"runs":[{"text":"● É vedada a equiparação remuneratória entre militares das Forças Armadas e policiais e bombeiros militares do Distrito Federal, visto que a Constituição Federal de 1988, em seu art. 37, XIII, coíbe a vinculação ou equiparação de quaisquer espécies remuneratórias no âmbito do serviço público.","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"[Tese definida no ARE 665.632 RG , rel. min. Teori Zavascki , P, j. 16-4-2015, DJE 78 de 28-4-2015, Tema 806.]","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"A presente demanda visa, em suma, ao pagamento dos soldos dos integrantes das Forças Armadas no mesmo patamar da remuneração devida aos militares do Distrito Federal. Os autores, ora recorrentes, fundamentam a pretensão no art. 24 do DL 667/1969: (...). Esse dispositivo, conforme bem apontado pela sentença, reproduzia vedação constante do art. 13, § 4º, da Constituição de 1967, na redação da EC 1/1969, que proibia o pagamento, ao pessoal das Polícias Militares e Corpo de Bombeiros Militares dos Estados, do Distrito Federal e dos Territórios, de remuneração superior à fixada para os postos e graduações correspondentes no Exército. Tal impedimento, entretanto, não foi reproduzido na Carta Magna de 1988. Na verdade, os arts. 42, § 1º, e 142, § 3º, X, da CF/88 limitam-se a conferir aos Estados a competência para fixar, mediante lei estadual específica, a remuneração dos militares integrantes dos quadros das suas Polícias Militares e Corpo de Bombeiros Militares. É certo, todavia, que essas normas não se aplicam ao Distrito Federal, cujas Polícias Civil e Militar e Corpo de Bombeiros Militar, por disposição do art. 21, XIV, da CF/88, são organizadas e mantidas pela União, a quem compete privativamente legislar sobre o vencimento dos integrantes de seus respectivos quadros.","deleted":false}],"heading":false},{"page":167,"runs":[{"text":"[ ARE 665.632 RG , voto do rel. min. Teori Zavascki , P, j. 16-4-2015, DJE 78 de 28-4-2015, Tema 806.]","deleted":false}],"heading":false},{"page":168,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":168,"runs":[{"text":"● A Súmula Vinculante 39 resultou da conversão da Súmula 647.","deleted":false}],"heading":false},{"page":168,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 806, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":168,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-3-2015.","deleted":false}],"heading":false},{"page":168,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":168,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"40","number":"40","scope":"main","kind":"vinculante","sectionId":"grupo-3","page":169,"endPage":170,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2204","paragraphs":[{"page":169,"runs":[{"text":"A contribuição confederativa de que trata o art. 8º, IV, da Constituição Federal, só é exigível dos filiados ao sindicato respectivo.","deleted":false}]}],"notes":[{"page":169,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":169,"runs":[{"text":"A questão a saber é se a denominada contribuição confederativa, inscrita no art. 8º, IV, da Constituição Federal, fixada pela assembleia geral, é devida pelos empregados não filiados ao sindicato. Noutras palavras, se apresenta ela caráter de compulsoriedade, vale dizer, se é obrigatório o seu pagamento por empregados não filiados ao sindicato. (...) Primeiro que tudo, é preciso distinguir a contribuição sindical, contribuição instituída por lei, de interesse das categorias profissionais - art. 149 da CF/1988 - com caráter tributário, assim compulsória, da denominada contribuição confederativa, instituída pela assembleia geral da entidade sindical - CF/1988, art. 8º, IV. A primeira, conforme foi dito, contribuição parafiscal ou especial, espécie tributária, é compulsória. A segunda, entretanto, é compulsória apenas para os filiados do sindicato.","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"[ RE 198.092 , voto do rel. min. Carlos Velloso , 2ª T, j. 27-8-1996, DJ de 11-10-1996.]","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":169,"runs":[{"text":"● É inconstitucional a instituição, por acordo, convenção coletiva ou sentença normativa, de contribuições que se imponham compulsoriamente a empregados da categoria não sindicalizados.","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"[Tese definida no ARE 1.018.459 RG , rel. min. Gilmar Mendes , P, j. 23-2-2017, DJE 46 de 10-3-2017, Tema 935.]","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":169,"runs":[{"text":"Ausência de identidade entre a Súmula Vinculante 40 e decisão que considerou legítimos os descontos referentes à contribuição assistencial","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"Examinando detidamente os autos, verifico que o ato reclamado considerou legal o desconto de contribuição assistencial, prevista no art. 513 da Consolidação das Leis do Trabalho. Trata-se de situação específica, não abarcada pelo comando previsto na Súmula Vinculante 40, razão pela qual ela não guarda relação de estrita pertinência com o ato reclamado, necessária ao cabimento da reclamação.","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"[ Rcl 21.851 , rel. min. Edson Fachin , dec. monocrática, j. 17-5-2016, DJE 103 de 20-5-2016.]","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"Exigência de contribuição confederativa sindical apenas a filiados","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"O Sindicato recorrente alega violação ao art. 8º, IV, da Carta. Sustenta que a contribuição sindical compulsória foi recepcionada pela Carta de 1988. Afirma que a referida contribuição deve ser exigida de todos os servidores representados pela categoria, ainda que não sejam filiados ao sindicato. A pretensão recursal não merece prosperar. A jurisprudência desta Corte entende que é exigível dos servidores públicos civis a contribuição sindical prevista no art. 8º, IV, da Constituição Federal. (...) Embora a contribuição sindical seja exigível também dos servidores públicos civis, a jurisprudência do Supremo Tribunal Federal é firme no sentido de que a exigência restringe-se aos filiados ao sindicato. (...) A reiterada jurisprudência da Corte a respeito desse tema deu origem à Súmula Vinculante 40.","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"[ ARE 1.042.384 , rel. min. Roberto Barroso , dec. monocrática, j. 24-5-2017, DJE 116 de 2-6-2017.]","deleted":false}],"heading":false},{"page":169,"runs":[{"text":"Pedido de cancelamento da Súmula Vinculante 40","deleted":false}],"heading":false},{"page":170,"runs":[{"text":"(...) deve-se destacar que os argumentos trazidos pela proponente são idênticos àqueles debatidos no julgamento do RE 194.603/SP, relator o ministro Marco Aurélio, e redator para o acórdão ministro Nelson Jobim, cujo resultado foi paradigma para a elaboração da Súmula 666 do Supremo Tribunal Federal, convertida, posteriormente, na Súmula Vinculante 40. Portanto, o mero descontentamento ou divergência quanto ao conteúdo de verbete vinculante não propicia a reabertura de debate sobre matéria devidamente sedimentada por esta Corte. Ademais, a proponente não se desincumbiu da exigência constitucional de apresentar decisões reiteradas do Supremo Tribunal Federal para suportar o seu pedido de cancelamento da Súmula Vinculante 40, com o que também não se verifica a necessária adequação formal da presente proposta.","deleted":false}],"heading":false},{"page":170,"runs":[{"text":"[ PSV 117 , rel. min. presidente Ricardo Lewandowski , dec. monocrática, j. 2-9-2015, DJE 177 de 9-9-2015.]","deleted":false}],"heading":false},{"page":170,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":170,"runs":[{"text":"● A Súmula Vinculante 40 resultou da conversão da Súmula 666.","deleted":false}],"heading":false},{"page":170,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-3-2015.","deleted":false}],"heading":false},{"page":170,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":170,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"41","number":"41","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":171,"endPage":172,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2218","paragraphs":[{"page":171,"runs":[{"text":"O serviço de iluminação pública não pode ser remunerado mediante taxa.","deleted":false}]}],"notes":[{"page":171,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":171,"runs":[{"text":"I - Lei que restringe os contribuintes da Cosip aos consumidores de energia elétrica do Município não ofende o princípio da isonomia, ante a impossibilidade de se identificar e tributar todos os beneficiários do serviço de iluminação pública. II - A progressividade da alíquota, que resulta do rateio do custo da iluminação pública entre os consumidores de energia elétrica, não afronta o princípio da capacidade contributiva. III - Tributo de caráter sui generis , que não se confunde com um imposto, porque sua receita se destina a finalidade específica, nem com uma taxa, por não exigir a contraprestação individualizada de um serviço ao contribuinte. IV - Exação que, ademais, se amolda aos princípios da razoabilidade e da proporcionalidade.","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"[ RE 573.675 , rel. min. Ricardo Lewandowski , P, j. 25-3-2009, DJE 94 de 22-5-2009, Tema 44.]","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"A orientação do Supremo Tribunal Federal é no sentido de que a Taxa de Iluminação Pública é inconstitucional, uma vez que seu fato gerador tem caráter inespecífico e indivisível.","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"[ AI 479.587 AgR , rel. min. Joaquim Barbosa , 2ª T, j. 3-3-2009, DJE 53 de 20-3-2009.]","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"É assente nesta colenda Corte que as taxas de iluminação pública e de limpeza pública se referem a atividades estatais que se traduzem em prestação de utilidades inespecíficas, indivisíveis e insuscetíveis de serem vinculadas a determinado contribuinte, não podendo ser custeadas senão por meio do produto da arrecadação dos impostos gerais.","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"[ AI 463.910 AgR , rel. min. Ayres Britto , 1ª T, j. 20-6-2006, DJ de 8-9-2006.]","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":171,"runs":[{"text":"● O serviço de iluminação pública não pode ser remunerado mediante taxa.","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"[Tese definida no RE 573.675 , rel. min. Ricardo Lewandowski , P, j. 25-3-2009, DJE 94 de 22-5-2009, Tema 44.]","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":171,"runs":[{"text":"É constitucional a cobrança de COSIP, ainda que não haja serviço de iluminação pública em frente à residência do contributário","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"(...) as contribuições, diferentemente das taxas, não são tributos vinculados à utilização de serviço específico e divisível prestado ao contribuinte ou posto à sua disposição. Assim, ainda que não haja o serviço de iluminação pública em frente à residência do contributário, a cobrança da COSIP é constitucional, quando amparada em legislação municipal, vez que instituída em virtude da prestação de serviço coletivo e universal, a promover a segurança à população em geral nos diversos espaços públicos do Município. O acórdão recorrido divergiu desse entendimento, devendo ser reformado, portanto.","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"[ RE 1.438.471 , rel. min. Nunes Marques , dec. monocrática, j. 1-8-2024, DJE s/n de 13-8-2024.]","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"Inconstitucionalidade da cobrança de taxa de segurança pública de instituição bancária","deleted":false}],"heading":false},{"page":171,"runs":[{"text":"Destaco, ao contrário do alegado nas razões do agravo regimental, a atividade de segurança pública é serviço público geral e indivisível, a ser remunerado mediante imposto, e não por meio da Taxa de Segurança para","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"Eventos, como pleiteia o agravante. Consoante consignado no acórdão recorrido, “(...) a cobrança de ingressos para acesso a determinado evento não altera a natureza universal e indivisível do serviço de segurança pública prestado/disponibilizado pelos competentes órgãos estatais, devendo ser custeado pela receita dos impostos, nos termos dos arts. 144, caput , e 145, I, ambos da Constituição Federal” (...). O Tribunal Pleno, ao julgar o mérito da ADI 1.942/PA, rel. min. Edson Fachin, reafirmou a jurisprudência no sentido de que a atividade de segurança pública é serviço público geral e indivisível, logo deve ser remunerada mediante imposto. Isto é, viola o art. 145, II, do Texto Constitucional a exigência de taxa para sua fruição. (...) As razões do agravo regimental não se mostram aptas a infirmar os fundamentos que lastrearam a decisão agravada. Agravo regimental conhecido e não provido","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"[ ARE 931.872 AgR , rel. min. Rosa Weber , 1ª T, j. 5-4-2016, DJE 76 de 20-4-2016.]","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"A jurisprudência do Supremo Tribunal Federal se consolidou no sentido de que a atividade de segurança pública é serviço público geral e indivisível, logo deve ser remunerada mediante imposto, isto é, viola o art. 145, II, do Texto Constitucional, a exigência de taxa para sua fruição. 2. Da argumentação exposta pela parte requerente não se extrai a inconstitucionalidade in totum do dispositivo impugnado, assim se aplica ao caso a teoria da divisibilidade das leis, segundo a qual, em sede de jurisdição constitucional, somente se deve proferir a nulidade dos dispositivos maculados pelo vício de inconstitucionalidade, de maneira que todos aqueles dispositivos legais que puderem subsistir autonomamente não são abarcados pelo juízo de inconstitucionalidade. 3. Ação direta de inconstitucionalidade a que se dá parcial procedência, a fim de declarar inconstitucional a expressão “serviço ou atividade policial militar, inclusive policiamento preventivo” constante no art. 2º da Lei 6.010/1996 do Estado do Pará, assim como a Tabela V do mesmo diploma legal.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"[ ADI 1.942 , rel. min. Edson Fachin , P, j. 18-12-2015, DJE 27 de 15-2-2016.]","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"Consoante consignei na decisão atacada, o Supremo, no Verbete Vinculante 41 da Súmula, assentou a inconstitucionalidade da cobrança de taxa em razão da prestação de serviço de iluminação pública, considerada a natureza geral e indivisível da atividade estatal praticada. O Tribunal consolidou o entendimento quanto à violação ao art. 145, II, da Carta da República. Atua-se, em sede extraordinária, a partir das balizas assentadas na origem. O Tribunal de Justiça do Estado do Rio Grande do Sul consignou tratar-se de taxa exigida em virtude de potencial atividade de segurança pública, embora tenha concluído pelo caráter específico e divisível. Todavia, considerada a natureza da atividade, o benefício é dirigido a toda a coletividade, revelando serviço público geral e indivisível, a ser remunerado mediante impostos. No mais, quando exigida a obrigação em razão de contribuinte particular - instituição financeira -, decorrente de indevida solicitação do serviço, tem-se a descaracterização da figura da taxa, aproximando-se de sanção administrativa.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"[ RE 739.311 AgR , voto do rel. min. Marco Aurélio , 1ª T, j. 22-9-2015, DJE 204 de 13-10-2015.]","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"Observações","deleted":false}],"heading":true},{"page":172,"runs":[{"text":"● A Súmula Vinculante 41 resultou da conversão da Súmula 670.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"● Vide Súmula Vinculante 19.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 44, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-3-2015.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":172,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"42","number":"42","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":173,"endPage":175,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2222","paragraphs":[{"page":173,"runs":[{"text":"É inconstitucional a vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária.","deleted":false}]}],"notes":[{"page":173,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":173,"runs":[{"text":"De se ver, pois, que o entendimento prevalecente no Supremo Tribunal Federal é no sentido de que o reajuste automático de vencimentos de servidores públicos, tomando-se como base a variação de indexadores de atualização monetária, como o Índice de Preços ao Consumidor (IPC), desrespeita a autonomia dos Estados-membros e a vedação constitucional de vinculação, para efeito de remuneração de servidores públicos, nos termos dos arts. 25 e 37, XIII, da Constituição da República, respectivamente.","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"[ ADI 285 , voto da rel. min. Cármen Lúcia , P, j. 4-2-2010, DJE 50 de 19-3-2010, republicação no DJE 96 de 28-5-2010.]","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":173,"runs":[{"text":"Afronta o enunciado da SV 42 a incidência de percentuais devidos a título de progressão na carreira municipal sobre o valor atualizado do piso nacional","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"3. A determinação de que percentuais devidos a título de progressão na carreira municipal incidam sobre o valor atualizado do piso nacional implica sobreposição de índices de reajuste e, consequentemente, aumento de vencimentos de servidor público municipal atrelado a parâmetro federal, o que ofende a Súmula Vinculante 42: “É inconstitucional a vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária”. Precedente: Rcl 57.806-AgR, Rel. Min. Alexandre de Moraes. 4. Agravo interno a que se nega provimento.","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"[ Rcl 59.757-AgR , rel. min. Roberto Barroso , 1ª T, j. 15-8-2023, DJE s/n de 18-8-2023.]","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"1. A decisão que substituiu o índice de correção de vencimento, fixado por lei local, para a progressão na carreira de Professor, por um índice geral, fixado em lei federal exclusivamente para a correção do valor do piso nacional, ofende o teor da Súmula Vinculante 42. 2. O enunciado da Súmula Vinculante 42 determina que é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público. Ele decorre de precedentes desta CORTE que preconizam o respeito às competências constitucionais, especialmente a separação de poderes e a autonomia dos entes federados.","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"[ Rcl 59.754 AgR , rel. min. Alexandre de Moraes , 1ª T, j. 3-7-2023, DJE s/n de 11-7-2023.]","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"Aplicabilidade a títulos judiciais formados antes da publicação da súmula","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"AGRAVO REGIMENTAL NO RECURSO EXTRAORDINÁRIO. EXECUÇÃO FISCAL. TÍTULO EXECUTIVO. NULIDADE. COISA JULGADA. SÚMULA VINCULANTE 42. 1. Debate sob a ótica infraconstitucional acerca de violação à coisa julgada não ostenta repercussão geral. Precedente: RE 748.371-RG, Rel. Min. Gilmar Mendes, DJe 1º.08.2013 (Tema 660). 2. É aplicável a Súmula Vinculante 42 a execuções de títulos judiciais formados anteriormente à publicação do verbete, caso este se remeta a julgamentos anteriores ao trânsito em julgado do ato exequendo.","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"[ RE 977.068 AgR , rel. min. Edson Fachin , 2ª T, j. 17-11-2017, DJE 279 de 5-12-2017.]","deleted":false}],"heading":false},{"page":173,"runs":[{"text":"Aplicabilidade da Súmula Vinculante 42 à revisão geral anual","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"(...) não obstante a Súmula Vinculante 42/STF faça referência tão somente a “reajuste”, tal entendimento é igualmente aplicável à revisão geral anual, tal como decidido na ADI 5.584/MT (Rel. Min. Ricardo Lewandowski, Tribunal Pleno, j. 6.12.2021, DJe 14.12.2021).","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"[ RE 1.424.451 , rel. min. Edson Fachin , 2ª T, j. 8-4-2025, DJE s/n 15-5-2025.]","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"Vedação de reajuste automático de qualquer despesa de pessoal estadual ou municipal por índices federais","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"A Súmula Vinculante nº 42 não se limita, em sua razão de decidir, à natureza jurídica estritamente salarial da verba, mas à vedação de qualquer mecanismo de reajuste automático de despesas de pessoal estaduais ou municipais com base em índices federais, em afronta à autonomia federativa e ao modelo constitucional de fixação e revisão da remuneração dos servidores públicos. O que se proíbe é a indexação, isto é, a substituição da deliberação política e orçamentária local por parâmetros definidos em esfera diversa, independentemente da rubrica formal atribuída à vantagem.","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"[ Rcl 89.054 , rel. min. Flávio Dino , dec. monocrática, j. 4-2-2026, DJE s/n 5-2-2026.]","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"Vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"O Juízo reclamado entendeu a Lei Municipal 1.122/2012, ao estabelecer \"que o piso salarial do Magistério é instituído em conformidade com a lei federal\", teria autorizado o reajuste automático dos vencimentos mediante utilização de índices federais. Essa ratio decidendi viola o enunciado da Súmula Vinculante n. 42. Friso que a vinculação ao piso previsto na lei federal refere-se, exclusivamente, à proteção dos profissionais que recebam remuneração menor do que o citado piso. Reajustes para classes que recebam remuneração acima do piso dependem da edição de lei municipal específica, a teor da Súmula Vinculante n. 42 do STF.","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"[ Rcl 72.854 , rel. min. Flávio Dino , dec. monocrática, j. 22-10-2024, DJE s/n de 23-10-2024.]","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"Não procede a alegação do agravante de que o IGP-M, por ser um índice de preços apurado por uma entidade privada, Fundação Getúlio Vargas, afastaria a incidência da Súmula Vinculante nº 42/STF. Ao contrário, apesar de ser calculado por uma entidade privada, o IGP-M é um índice oficial de variação de preços e possui a mesma finalidade dos demais índices de preços adotados como indexadores de correção monetária, como o IPCA e o INPC, calculados pelo IBGE, e o IPC-FIPE, apurado pela Fundação Instituto de Pesquisas Econômicas (FIPE), essa última também uma organização de natureza privada.","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"[ RE 1.475.806 AgR , rel. min Dias Toffoli , 2ª T, j. 20-4-2024, DJE de 23-5-2024.]","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"O recurso não merece acolhida. A decisão preferida pelo Tribunal de origem está alinhada com a jurisprudência do Supremo Tribunal Federal (STF), consolidada na Súmula Vinculante 42, no sentido de ser inconstitucional a lei que estabeleça a vinculação de reajuste de vencimentos de servidores públicos a índices federais de correção monetária.","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"[ ARE 1.184.971 , rel. min. Roberto Barroso , dec. monocrática, j. 20-2-2019, DJE 39 de 26-2-2019.]","deleted":false}],"heading":false},{"page":174,"runs":[{"text":"Surge imprópria a irresignação. Consoante se observa da leitura do pronunciamento atacado, o órgão reclamado, embora haja reconhecido a vigência das Leis municipais 10.688/1988 e 10.722/1989 durante certo interregno, considerado o panorama econômico do País ao final da década de 1980, admitiu a ocorrência da chamada inconstitucionalidade progressiva. Em síntese, assentou inadequada a vinculação do reajuste de vencimentos de servidores locais a índices federais de correção, restringindo a incidência do disposto nos citados diplomas tendo em vista o direito adquirido. (...) Permitiu-se a aplicação do que previsto nas Leis municipais 10.688/1988 e 10.722/1989 - o reajuste pelo índice federal -, no tocante ao mês de fevereiro de 1995, presente o direito adquirido dos servidores, uma vez que a Lei 11.722, publicada em 14 de fevereiro de 1995, não poderia retroagir para alcançar momento anterior ao da própria vigência. Analisou o conflito - certo ou errado, não cabe perquirir - com base nas normas constitucionais envolvidas, não estando verificado o","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"desrespeito ao Verbete Vinculante 42 da Súmula do Supremo.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"[ Rcl 24.225 , rel. min. Marco Aurélio , dec. monocrática, j. 13-6-2016, DJE 124 de 16-6-2016.]","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"O Plenário do Supremo Tribunal Federal, no julgamento do RE 251.238/RS, sob a relatoria do ministro Marco Aurélio, assentou a inconstitucionalidade do art. 7º e parágrafos da Lei municipal 7.428/1994, com redação dada pela Lei municipal 7.539/1994. A Corte entendeu que a referida norma municipal vincula receita de impostos com despesas de pessoal, o que viola os termos do art. 167, IV, da Constituição. (...) O Supremo Tribunal Federal editou a Súmula 681, atualmente consolidada na Súmula Vinculante 42, que pacifica o entendimento no sentido da inconstitucionalidade da vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária, exatamente o que pretendia fazer a Lei municipal 7.428/1994, declarada incompatível com a Constituição Federal por esta Corte.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"[ RE 626.386 , rel. min. Roberto Barroso , dec. monocrática, j. 3-11-2015, DJE 224 de 3-11-2015.]","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Vinculação dos vencimentos de professores da educação básica municipal aos reajustes do piso salarial nacional da categoria, calculado pelo Ministério da Educação","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Rememoro que o entendimento assentado na Súmula Vinculante 42/STF buscou preservar a autonomia dos Estados e Municípios para fixar os padrões de vencimento e demais componentes do sistema remuneratório dos seus servidores, em homenagem ao equilíbrio do pacto federativo. Nesses termos, entendo que a autoridade reclamada, ao determinar o reajuste automático dos vencimentos de profissional da educação básica municipal, mediante aplicação de parâmetros previstos em lei federal, mesmo para os profissionais que auferem vencimento básico superior ao piso nacional, violou o disposto na Súmula Vinculante 42.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"[ Rcl 68.406-AgR , rel. min. Edson Fachin , red. p/ o ac. min. Gilmar Mendes , 2ª T, j. 2-12-2024, DJE s/n 28-2-2025.]","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Ora, ainda que não se trate de índice federal de correção monetária em sentido estrito, a atualização do piso nacional dos professores da educação básica se dá com base em cálculos efetuados pelo Ministério da Educação, segundo sistemática estabelecida em normas federais, por meio da utilização de critérios que não guardam nenhuma relação com as finanças municipais. (...) Nesses termos, entendo que a autoridade reclamada, ao determinar o reajuste automático dos vencimentos de profissional da educação básica do Município de Sarandi, mediante aplicação de parâmetros previstos em lei federal, mesmo para os profissionais que auferem vencimento básico superior ao piso nacional, violou o disposto na Súmula Vinculante 42.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"[ Rcl 72.289 , rel. min. Gilmar Mendes , dec. monocrática, j. 7-10-2024, DJE s/n de 8-10-2024.]","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices de correção monetária estabelecido por Conselho Estadual","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"No que tange à alegação de ofensa à Súmula Vinculante 42, não houve vinculação do reajuste de vencimentos de servidor a índice federal de atualização monetária, mas sim aplicação de política de revisão remuneratória a empregado, com base em índices estabelecidos a cada ano por meio de resoluções do Conselho de Reitores das Universidades Estaduais de São Paulo (CRUESP), conforme autorização legal.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"[ Rcl 24.417 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 7-3-2017, DJE 82 de 24-4-2017.]","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":175,"runs":[{"text":"● A Súmula Vinculante 42 resultou da conversão da Súmula 681.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Data de publicação do enunciado: DJE de 20-3-2015.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":175,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"43","number":"43","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":176,"endPage":181,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2348","paragraphs":[{"page":176,"runs":[{"text":"É inconstitucional toda modalidade de provimento que propicie ao servidor investir-se, sem prévia aprovação em concurso público destinado ao seu provimento, em cargo que não integra a carreira na qual anteriormente investido.","deleted":false}]}],"notes":[{"page":176,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":176,"runs":[{"text":"Ação direta de inconstitucionalidade. Ascensão ou acesso, transferência e aproveitamento no tocante a cargos ou empregos públicos. O critério do mérito aferível por concurso público de provas ou de provas e títulos é, no atual sistema constitucional, ressalvados os cargos em comissão declarados em lei de livre nomeação e exoneração, indispensável para cargo ou emprego público isolado ou em carreira. Para o isolado, em qualquer hipótese; para o em carreira, para o ingresso nela, que só se fará na classe inicial e pelo concurso público de provas ou de provas e títulos, não o sendo, porém, para os cargos subsequentes que nela se escalonam até o final dela, pois, para estes, a investidura se fará pela forma de provimento que é a “promoção”. Estão, pois, banidas das formas de investidura admitidas pela Constituição a ascensão e a transferência, que são formas de ingresso em carreira diversa daquela para a qual o servidor público ingressou por concurso e que não são, por isso mesmo, ínsitas ao sistema de provimento em carreira, ao contrário do que sucede com a promoção, sem a qual obviamente não haverá carreira, mas, sim, uma sucessão ascendente de cargos isolados. O inciso II do art. 37 da Constituição também não permite o “aproveitamento”, uma vez que, nesse caso, há igualmente o ingresso em outra carreira sem o concurso exigido pelo mencionado dispositivo.","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"[ ADI 231 , rel. min. Moreira Alves , P, j. 5-8-1992, DJ de 13-11-1992.]","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":176,"runs":[{"text":"● É inconstitucional dispositivo de Constituição estadual que permite transposição, absorção ou aproveitamento de empregado público no quadro estatutário da Administração Pública estadual sem prévia aprovação em concurso público, nos termos do art. 37, II, da Constituição Federal.","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"[Tese definida no RE 1.232.885, rel. min. Nunes Marques , P, j. 13-4-2023, DJE s/n de 2-5-2023, Tema 1128.]","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"● É inconstitucional o aproveitamento de servidor, aprovado em concurso público a exigir formação de nível médio, em cargo que pressuponha escolaridade superior","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"[Tese definida no RE 740.008 , rel. min. Marco Aurélio, P, j. 21-10-2020, DJE de 21-4-2021, Tema 697.]","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"Por tais razões, todas as características referentes ao cargo, inclusive o grau de escolaridade correspondente e a respectiva remuneração, devem ser amplamente divulgadas antes do certame, por força do princípio constitucional da publicidade, a fim de possibilitar a participação do maior número possível de interessados. Nesse contexto, o fato de que as atribuições do novo cargo são idênticas às do cargo em extinção não é razão suficiente para afastar a inconstitucionalidade da norma impugnada, visto que o vício constitucional a afastar a equiparação salarial entre os cargos não decorre da diferença de qualificação do servidor público, mas sim da inexistência de aprovação prévia em concurso para cargo efetivo de nível superior.","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"[ RE 740.008 , voto do min. Alexandre de Moraes , P, j. 21-10-2020, DJE 70 de 14-4-2021.]","deleted":false}],"heading":false},{"page":176,"runs":[{"text":"Tese de Controle Concentrado","deleted":false}],"heading":true},{"page":176,"runs":[{"text":"● A equiparação de carreira de nível médio a outra de nível superior constitui forma de provimento derivado vedada pelo art. 37, II, da CF/88.","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"[ Tese fixada na ADI 6.532 , rel. min. Luís Roberto Barroso , P, j. 19-12-2023, DJE s/n de 15-2-2024.]","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":177,"runs":[{"text":"Aplicação do princípio da segurança jurídica para a manutenção dos atos de provimento derivado ocorridos entre 1987 e 1992","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"O recurso não merece acolhida. Extrai-se dos autos que a autora ingressou no serviço público em 21/12/1961, no cargo de Datiloscopista, sendo transposta ao cargo de Delegado de Polícia em 02/04/1990. Dispõe o enunciado da Súmula Vinculante 43 (...). Não obstante, esta Corte tem decidido pela subsistência dos atos ocorridos entre 1987 a 1992, (...). Com a edição da Carta da República, ficou instituído o concurso público como forma de investidura em cargo ou emprego público (CF, art. 37, II), sendo que o STF, somente em 17.02.1993, na MC na ADI 837-4, suspendeu a eficácia do art. 8º, III e do art. 10, X, parágrafo único, da Lei 8.112/1990, com efeito ex nunc , prevalecendo a orientação do não cabimento de concursos internos e, na sessão realizada em 27.08.1998, foi julgado o mérito da referida ADI, sendo declaradas inconstitucionais as formas de provimento derivado representadas pela ascensão ou acesso, transferência e aproveitamento no tocante a cargos ou empregos públicos, com efeito ex nunc . Desta forma, como a transposição da parte autora ocorrera em 02/04/1990, não há falar em ofensa ao artigo 37, II, da Constituição Federal, na esteira da jurisprudência desta Corte.","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"[ RE 995.113 , rel. min. Edson Fachin , dec. monocrática, j. 14-3-2018, DJE 51 de 16-3-2018.]","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"3. É certo que, com a promulgação da Constituição Federal em 5 de outubro de 1988, a parte recorrida, ao lograr aprovação em concurso interno, não teria preenchido os requisitos necessários para o provimento do cargo de Delegado de Polícia, frisa-se, admitido pela ordem constitucional anterior. Com o advento da nova ordem constitucional passou a ser exigida a aprovação em concurso público para o ingresso em cargos que não integram a carreira na qual o servidor se encontrava anteriormente investido, sendo que tal entendimento restou consagrado no enunciado de Súmula 685/STF, o qual passou a ter efeitos vinculantes com a aprovação do enunciado 43/STF. 4. Conforme consta na decisão monocrática ora impugnada, o autor tomou posse em 14.08.1992, após o provimento de apelação em mandado de segurança, a qual transitou em julgado. A autoridade de tal decisão definitiva esta sendo contestada na presente ação rescisória que, após 15 anos à aprovação do recorrido em concurso interno para o cargo de Delegado de Polícia, chegou ao Superior Tribunal de Justiça, tendo transcorrido já 23 anos da data da posse e a situação do recorrido ainda não encontrou o seu desfecho final. 5. Assim, em razão da adoção de interpretação que buscou a aplicação mais razoável da norma, o recorrido teve provido o seu recurso especial que julgou improcedente a presente ação rescisória que visa desconstituir mandado de segurança que reconheceu o direito líquido e certo à nomeação em concurso interno realizado em 1991, sob a vigência da atual Constituição. 6. Entender de forma distinta, após decorridos mais de 20 anos de exercício do cargo pelo recorrido, resguardado por sentença judicial transitada em julgado, e exigir-lhe a realização de concurso público para o provimento originário do cargo de delegado no qual provavelmente se aposentaria, levaria por violar os princípios da razoabilidade, da segurança jurídica e da proteção da confiança.","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"[ RE 552.145 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 27-10-2017, DJE 258 de 14-11-2017.]","deleted":false}],"heading":false},{"page":177,"runs":[{"text":"Agravo regimental no agravo regimental no recurso extraordinário. Administrativo. Provimento derivado. Manutenção de ato administrativo concretizado em 1990. ADI 837 MC. Efeitos ex nunc . RE 442.683/RS. Princípios da boa-fé e da segurança jurídica. Precedentes. 1. A jurisprudência do Supremo Tribunal Federal é no sentido de ser inconstitucional toda forma de provimento derivado após a Constituição Federal de 1988, sendo necessária a prévia provação em concurso de provas ou de provas e títulos para o ingresso em cargos públicos. 2. Contudo, no julgamento da medida cautelar na ADI 837, relator o ministro Moreira Alves, DJ de 17-2-1993, suspendeu-se, com efeitos ex nunc , a eficácia dos arts. 8º, III, e das expressões “acesso e ascensão”, do art. 13, § 4º, “ou ascensão” e “ou ascender”, do art. 17, e do inciso IV do art. 33, todos da Lei 8.112, de 1990. 3. Posteriormente, com fundamento na referida ação direta de inconstitucionalidade, cujo","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"mérito foi julgado em 27-8-1998 ( DJ de 25-6-1999), a Segunda Turma da Corte, ao examinar o RE 442.683/RS, concluiu pela subsistência de atos administrativos de provimentos derivados ocorridos entre 1987 a 1992, em respeito aos postulados da boa-fé e da segurança jurídica. Consignou-se que, à época dos fatos, o entendimento a respeito do tema não era pacífico, o que teria ocorrido somente em 17-2-1993 (data da publicação da decisão proferida na medida cautelar). 4. Agravo regimental não provido.","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"[ RE 605.762 AgR-AgR , rel. min. Dias Toffoli , 2ª T, j. 24-5-2016, DJE 118 de 9-6-2015.]","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"Extinção de órgão ou ente público, com aproveitamento dos seus servidores mediante novo enquadramento funcional","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"A transposição de cargos públicos, sem concurso, é vedada pela Súmula Vinculante 43, que proíbe o provimento derivado de cargo diverso daquele para o qual o servidor foi originalmente investido. (...) Entretanto, o enunciado da Súmula Vinculante nº 43 encontra exceção justamente na hipótese de extinção de órgão ou ente público, com aproveitamento de seus servidores mediante novo enquadramento funcional, desde que preenchidos os requisitos de: (i) identidade substancial entre os cargos de origem e o de destino; (ii) compatibilidade funcional; (iii) similitude remuneratória; e (iv) equivalência dos requisitos exigidos em concurso público.","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"[ RMS 39.343 , rel. min. Flávio Dino , 1ª T, j. 12-11-2024, DJE s/n 25-2-2025.]","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"Exigência de concurso público para ingresso, remoção e permuta em serventias extrajudiciais","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"DIREITO CONSTITUCIONAL. AGRAVO INTERNO EM MANDADO DE SEGURANÇA. CONVALIDAÇÃO DE PERMUTAS E REMOÇÕES ENVOLVENDO TITULARES DE SERVENTIAS EXTRAJUDICIAIS. CONCURSO PÚBLICO. ILEGITIMIDADE JÁ RECONHECIDA. 1. Com o advento da Constituição de 1988, o concurso público é inafastável tanto para o ingresso nas serventias extrajudiciais quanto para a remoção e para a permuta (dupla remoção simultânea). Precedentes. 2. Reconhecida a ilegitimidade do ato, não é lícito que o agravante permaneça como titular da serventia para a qual se removeu por permuta. 3. A nulidade declarada é apenas da remoção/permuta ilegítima, de modo que a parte interessada pode requerer, nas vias ordinárias, o que entender de direito. 4. Agravo a que se nega provimento.","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"[ MS 32.123 AgR , rel. min. Roberto Barroso , 1ª T, j. 24-2-2017, DJE 48 de 14-3-2017.]","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"Impossibilidade de manutenção de servidores admitidos sem prévio concurso público após o advento da atual Constituição","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"Percebe-se que, como assentado pelo Tribunal de origem, a pretensão dos recorrentes viola o disposto no art. 37, II, da CF. Com efeito, não há possibilidade de servidor admitido para exercício de cargo temporário ser efetivado em cargo permanente em razão da natureza jurídica das funções que exerce. 6. Esse tem sido o entendimento desta Corte que, diante de circunstâncias diversas relativas à violação ao art. 37, II, assentou: (i) a vedação de provimento derivado (Súmula Vinculante 43); (ii) a manutenção de servidores/empregados públicos admitidos sem prévio concurso (...); (iii) a impossibilidade de o passar do tempo sanar situações irregulares, rechaçando a tese do fato consumado (...); (iv) a impossibilidade de transmudação do regime de cargo temporário para cargo efetivo. 7. A razão de decidir em todos esses casos é a mesma: impossibilidade de manutenção de servidores admitidos sem prévio concurso público após o advento da atual Constituição. Desse entendimento não divergiu o acórdão recorrido, sendo inviável o provimento da pretensão recursal.","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"[ ARE 800.998 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 19-4-2016, DJE 89 de 4-5-2016.]","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"Não viola a SUV 43 a unificação de carreiras para fins de reorganização administrativa quando há similitude de atribuições, remuneração e grau de escolaridade","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"2. Não está configurado desrespeito ao verbete vinculante n. 43 quando observada, em situação de unificação de carreiras distintas, a similitude de atribuições, remuneração e grau de escolaridade.","deleted":false}],"heading":false},{"page":178,"runs":[{"text":"[ Rcl 52.717 AgR , rel. min. Nunes Marques , 2ª T, j. 19-11-2024, DJE s/n 14-8-2024.]","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"Obrigatoriedade de ingresso na classe inicial de cargos com carreira estruturada","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"(...), entendo pela inconstitucionalidade do dispositivo em questão, por não encontrar no texto constitucional nenhum discrimen que pudesse levar à conclusão de que referida circunstância não venha a malferir o princípio da impessoalidade. Ressalte-se que esta Corte, em votos memoráveis proferidos nos primeiros anos de vigência da Constituição, já decidiu que o ingresso nos cargos estruturados em carreira deve dar-se na classe inicial da carreira, consoante se depreende de um dos precedentes que originou a Súmula 685, hoje Súmula Vinculante 43 (...).","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"[ ADI 1.240 , rel. min. Cármen Lúcia , voto do min. Edson Fachin , P, j. 28-2-2019, DJE 140 de 28-6-2019.]","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"Mudança de regime celetista para estatutário antes da CF/1988 não viola a SUV 43","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"(...) o ato apresentado não se mostra suficiente a vislumbrar o provimento pelos requeridos na ação de origem, sem prévia aprovação em concurso público, em cargo que não integra a carreira na qual anteriormente investidos, a configurar de forma inequívoca o desrespeito à referida Súmula Vinculante. Com efeito, depreende-se dos documentos acostados aos autos que a Lei Municipal 7.555/17 estabeleceu a mudança de regime dos servidores de celetista para o estatutário, o que é permitido, tendo em vista que a ausência de prévia submissão a concurso, antes do advento da Constituição Federal de 1988, não impede a modificação do regime a que está subordinado o servidor nessa situação. Assim, não verifico violação à SV 43 a dar ensejo ao acolhimento do pedido formulado na inicial.","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"[ Rcl 31.953 , rel. min. Gilmar Mendes , dec. monocrática, j. 24-9-2018, DJE 204 de 26-9-2018.]","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"Viola a ordem constitucional a investidura em cargo por meio de transferência de servidores","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"(...) as normas impugnadas autorizam a transposição de servidores do Sistema Financeiro Bandern e do Banco de Desenvolvimento do Rio Grande do Norte S.A. (BDRN) para órgãos ou entidades da Administração direta, autárquica e fundacional do mesmo Estado (...). 3. A jurisprudência desta Corte é firme no sentido da inconstitucionalidade das normas que permitem a investidura em cargos ou empregos públicos diversos daqueles para os quais se prestou concurso. (...) 5. Vale ressaltar que os dispositivos impugnados não se enquadram na exceção à regra do concurso público, visto que não tratam de provimento de cargos em comissão, nem contratação por tempo determinado para suprir necessidade temporária de excepcional interesse público. 6. Portanto, a transferência de servidores para cargos diferentes daqueles nos quais ingressaram através de concurso público demonstra clara afronta ao postulado constitucional do concurso público.","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"[ ADI 3.552 , voto do rel. min. Roberto Barroso , P, j. 17-3-2016, DJE 69 de 14-4-2016.]","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"Viola a ordem constitucional a investidura por ascensão funcional","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"1. Esta Corte tem reconhecido a constitucionalidade da norma legal que, no contexto de reestruturação administrativa, promove o enquadramento de servidores ocupantes de cargos extintos em carreiras distintas quando há (i) uniformidade de atribuições entre os cargos extintos e aqueles nos quais serão os servidores enquadrados; (ii) identidade dos requisitos de escolaridade para ingresso no cargo público e (iii) identidade remuneratória entre os cargos criados e aqueles extintos. (...) 3. Os fundamentos que embasam o acórdão reclamado, ao permitir o reenquadramento da servidora pública ocupante de cargo de nível de 1º grau, sem concurso público, para o cargo de Técnico Judiciário, no qual se exige o nível médio, revelam-se em dissonância com o teor da Súmula Vinculante 43(...).","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"[ Rcl 63.598 AgR , rel. min. Edson Fachin , j. 2ª T, j. 7-10-2024, DJE s/n de 16-10-2024.]","deleted":false}],"heading":false},{"page":179,"runs":[{"text":"No caso, verifico que o Tribunal de origem, com base nas provas dos autos, consignou ter havido provimento derivado de cargo público, o que seria incompatível com a atual ordem constitucional. (...) Nesse contexto, vale ressaltar que esta Corte, por meio de julgamento da ADI 837, Rel. Min. Moreira Alves, DJ 25.6.1999, reafirmou o entendimento exarado na ADI 231, no sentido de que são inconstitucionais as formas de provimento derivado","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"representadas pela ascensão ou acesso, transferência e aproveitamento no tocante a cargos ou empregos públicos. (...) O Tribunal de origem, portanto, ao assentar a inconstitucionalidade da transposição de cargos no caso, na modalidade de provimento derivado mediante acesso, por violação ao princípio do concurso público, decidiu em conformidade com a jurisprudência pacificada deste Supremo Tribunal Federal ao indeferir a possibilidade de evolução salarial no cargo atualmente ocupado.","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"[ ARE 1.183.394 , rel. min. Gilmar Mendes , dec. monocrática, j. 1º-2-2019, DJE 23 de 6-2-2019.]","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"Agravo regimental em recurso extraordinário com agravo. 2. Direito Administrativo. 3. Admissão, como empregada pública, anterior à CF/88. Inconstitucionalidade da Lei Estadual 4.546/92. ADI 982. Ascensão funcional. Impossibilidade. Nulidade da Portaria que a instituiu. Súmula Vinculante 43. 4. Situações inconstitucionais não se consolidam pelo transcurso do tempo. 5. Ausência de argumentos capazes de infirmar a decisão agravada. 6. Negativa de provimento ao agravo regimental.","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"[ ARE 943.787 AgR , rel. min. Gilmar Mendes , 2ª T, j. 6-11-2018, DJE 250 de 23-11-2018.]","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"(...) manifesta a inconstitucionalidade dos dispositivos impugnados, que permitem a ascensão funcional sem concurso público, na linha da jurisprudência deste Tribunal (...). Dessa forma, confirmo a medida cautelar e julgo procedente a ação direta para declarar a inconstitucionalidade do art. 18 e parágrafos da Lei Complementar do Estado de São Paulo 763/1994.","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"[ ADI 1.342 , voto do rel. min. Gilmar Mendes , P, j. 2-9-2015, DJE 239 de 26-11-2015, republicação no DJE 245 de 4-12-2015.]","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"Viola a ordem constitucional a investidura resultante da transformação ou transposição de cargos e funções públicas","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"19. Outro ponto que evidencia a plausibilidade jurídica do pedido refere-se à aparente inconstitucionalidade do art. 3º da Emenda Constitucional estadual impugnada. Em síntese, os incisos do art. 3º da EC 50/2014 realizam transformação de cargos, concedem equiparação remuneratória entre cargos de carreiras distintas e determinam o direito a paridade de proventos de aposentadoria e pensão dos cargos transformados. Todas essas medidas representam possíveis violações à regra do concurso público (art. 37, II, c/c art. 132, CF/88), à vedação de equiparação ou vinculação remuneratória entre cargos públicos diversos (art. 37, XIII, CF/88) e aos critérios de fixação remuneratória dos servidores públicos (art. 39, §1º, CF/88). 20. Quanto a essa questão, o Supremo Tribunal Federal tem firme entendimento no sentido de que não é permitida a transformação de cargo do titular de determinada investidura em cargo diverso, tendo em vista que isso ofende a regra do concurso público e seu consectário, o princípio da impessoalidade. (...) Esse entendimento foi, inclusive, consolidado pelo enunciado de Súmula 685/STF, convertido na Súmula Vinculante 43, (...).","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"[ ADI 5.215 MC , rel. min. Roberto Barroso , dec. monocrática, j. 19-12-2017, DJE 18 de 1º-2-2018.]","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"A Suprema Corte, ao interpretar o disposto do art. 37, II, da Carta Republicana, assentou que o provimento aos cargos públicos somente se dá através de concurso. Todavia, foram criadas diversas fórmulas para superar essa exigência, posteriormente declaradas inconstitucionais pelo STF. A jurisprudência pacífica deste Tribunal excetua apenas aquelas situações onde se extingue uma carreira e se aproveita seus servidores na nova classificação funcional, desde que haja correspondência e pertinência temática entre aquelas carreiras. Destaco, nesse sentido, a decisão proferida no julgamento da ADI 2335/DF, (...). Entendo, assim, que a transposição dos agravantes não observou os critérios estabelecidos pelo STF para considerar constitucional o aproveitamento de servidores de uma carreira para outra. (...) No mesmo sentido, verifico que a transposição dos reclamantes para carreira diversa daquela na qual foram aprovados em concurso público afronta a Súmula Vinculante 43, (...).","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"[ Rcl 26.103 AgR , rel. min. Ricardo Lewandowski , dec. monocrática, j. 30-10-2017, DJE 252 de 7-11-2017.]","deleted":false}],"heading":false},{"page":180,"runs":[{"text":"(...) o acórdão reclamado não ofendeu o disposto nas Súmulas Vinculantes 37 e 43, visto que não aumentou salário com base, exclusivamente, em argumento de isonomia salarial, e também não incorreu em","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"transposição de cargo público. (...) Destarte, verifica-se que a decisão hostilizada limitou-se a deferir o pagamento de diferenças salariais advindas “da inobservância do piso salarial previsto na Lei 11.738/2008 no período contratual imprescrito havido até dezembro/2009 e no Plano de Carreira do Magistério (Lei municipal 144/2009) no período contratual posterior”. Assim, verifico que falta aderência entre o objeto do ato reclamado e o enunciado das súmulas vinculantes que se reputam violadas, o que é requisito de admissibilidade da reclamação perante o Supremo Tribunal Federal. (...) Nesse contexto, impende consignar que o agravo revela-se manifestamente improcedente, notadamente em função da reiterada rejeição dos argumentos repetidamente expendidos pela parte nas suas manifestações anteriores.","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"[ Rcl 24.185 ED-AgR , voto do rel. min. Luiz Fux , 1ª T, j. 20-4-2017, DJE 98 de 11-5-2017.]","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Com efeito, o Tribunal de origem concluiu que a norma legal que determinou ao presidente do Tribunal de Contas do Estado do Amazonas o enquadramento dos servidores nas categorias funcionais e nos níveis de remuneração definidos no art. 7º da Lei 3.138/2007, por meio de ato administrativo, conforme a instrução de cada servidor, independentemente de aprovação prévia em concurso público de provas, ou de provas e títulos, ofende as regras constitucionais do concurso público. Entendeu-se que a equivalência funcional e remuneratória evidencia burla às regras da moralidade e igualdade. (...) Constata-se, portanto, que o acórdão recorrido está em harmonia com a jurisprudência desta Corte, sedimentada na Súmula Vinculante 43 (...). Ante o exposto, nego provimento ao presente agravo regimental.","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"[ RE 995.436 AgR , voto do rel. min. Edson Fachin , 1ª T, j. 9-12-2016, DJE 268 de 19-12-2016.]","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Com efeito, conforme já asseverado, o Tribunal a quo não divergiu da jurisprudência do Supremo Tribunal Federal no sentido de que a transposição, transformação ou ascensão funcional, de servidores públicos de uma categoria para outra, posto consubstanciar modalidades de provimento derivado, sem prévia aprovação em concurso público de provas e títulos, não se coadunam com a nova ordem constitucional. Essa orientação está consolidada na Súmula Vinculante 43 (...). Demais disso, a análise do argumento da parte ora agravante no sentido de que ambos os cargos pertencem a mesma carreira, demandaria a interpretação da legislação infraconstitucional de regência, de forma que eventual ofensa à Constituição Federal seria meramente indireta e reflexa, o que inviabiliza o exame da matéria na via estreita do recurso extraordinário.","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"[ RE 827.424 AgR , voto do rel. min. Luiz Fux , 1ª T, j. 14-10-2016, DJE 234 de 4-11-2016.]","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Viola a ordem constitucional a investidura resultante de provimento derivado","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"1. É vedado o provimento derivado de cargo público que possibilite a investidura de servidor em cargo com atribuições, níveis de escolaridade e de formação profissional diversos do cargo originalmente ocupado (CF, art. 37, II).","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"[ ARE 1.440.124 AgR , rel. min. Nunes Marque s, 2ª T, j. 20-5-2024, DJE de 3-6-2024.]","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"O Supremo Tribunal Federal firmou o entendimento de que viola a exigência de realização de concurso público o acesso a cargo público por qualquer forma de provimento derivado, sendo que tal interpretação restou consolidada no enunciado de Súmula Vinculante 43 (...).","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"[ ARE 853.656 AgR , rel. min. Roberto Barroso , 1ª T, j. 29-3-2016, DJE 78 de 25-4-2016.]","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":181,"runs":[{"text":"● A Súmula Vinculante 43 resultou da conversão da Súmula 685.","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-4-2015.","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":181,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"44","number":"44","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":182,"endPage":184,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2358","paragraphs":[{"page":182,"runs":[{"text":"Só por lei se pode sujeitar a exame psicotécnico a habilitação de candidato a cargo público.","deleted":false}]}],"notes":[{"page":182,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":182,"runs":[{"text":"Antiga é a jurisprudência desta Corte no sentido de que a exigência de avaliação psicológica ou teste psicotécnico, como requisito ou condição necessária ao acesso a determinados cargos públicos de carreira, somente é possível, nos termos da CF/1988, se houver lei em sentido material (ato emanado do Poder Legislativo) que expressamente a autorize, além de previsão no edital do certame. Ademais, o exame psicotécnico necessita de um grau mínimo de objetividade e de publicidade dos atos em que se procede. A inexistência desses requisitos torna o ato ilegítimo, por não possibilitar o acesso à tutela jurisdicional para a verificação de lesão de direito individual pelo uso desses critérios.","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"[ AI 758.533 QO-RG , voto do rel. min. Gilmar Mendes , P, j. 23-6-2010, DJE 149 de 13-8-2010, Tema 338.]","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":182,"runs":[{"text":"● No caso de declaração de nulidade de exame psicotécnico previsto em lei e em edital, é indispensável a realização de nova avaliação, com critérios objetivos, para prosseguimento no certame.","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"[Tese definida no RE 1.133.146 RG , rel. min. Luiz Fux , P, j. 20-9-2018, DJE 204 de 26-9-2018, Tema 1009.]","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"● A exigência do exame psicotécnico em concurso depende de previsão em lei e no edital, e deve seguir critérios objetivos.","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"[Tese definida no AI 758.533 QO-RG , rel. min. Gilmar Mendes , P, j. 23-6-2010, DJE 149 de 13-8-2010, Tema 338.]","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"O Supremo Tribunal Federal, em várias oportunidades e, em casos idênticos aos presente, concluiu pela validade do exame psicotécnico para o ingresso nas carreiras militares daquele Estado, fundado na Lei estadual 10.123/1968 (Lei Orgânica da Polícia), a qual, no seu art. 36, VI, estabelece como requisito para matrícula nos cursos de formação ou nomeação para as carreiras policiais “possuir temperamento adequado ao exercício da função policial, apurado em exame psicotécnico”.","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"[ Rcl 26.239 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 20-2-2018, DJE 39 de 1º-3-2018.]","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"AGRAVO INTERNO. RECLAMAÇÃO. ALEGADA OFENSA À SÚMULA VINCULANTE 44. INEXISTÊNCIA NO CASO CONCRETO. 1. A sentença que indica haver leis amparando a exigência do exame psicotécnico em concurso público está de acordo com a Súmula Vinculante 44 (“Só por lei se pode sujeitar a exame psicotécnico a habilitação de candidato a cargo público”). 2. A alegação de que as leis citadas não preveem o teste psicológico extrapola o restrito âmbito da reclamação. 3. Reclamação não é recurso. Não está entre suas importantes finalidades funcionar como um atalho para trazer ao Supremo Tribunal Federal toda e qualquer discussão em curso nas instâncias ordinárias.","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"[ Rcl 26.711 AgR , rel. min. Alexandre de Moraes , 1ª T, j. 2-6-2017, DJE 133 de 20-6-2017.]","deleted":false}],"heading":false},{"page":182,"runs":[{"text":"No caso em exame, a inobservância da Súmula foi justificada (...). (...) o Tribunal consignou que a exigência de avaliação psicológica, de caráter eliminatório, tem previsão no edital do concurso público. Ora, o embasamento em edital não atende a necessidade indicada pelo precedente desta Corte. Assim, relevantes os fundamentos trazidos pelo reclamante, cumprindo examinar se também está presente o requisito da urgência. Neste ponto, há que se observar que o reclamante almeja reverter decisão que se negou a anular ato administrativo que o","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"considerou inapto em uma das fases do concurso público para admissão no cargo de soldado PM de 2ª classe, razão pela qual há evidente prejuízo e razoável risco de que, caso somente ao término desta ação seja-lhe deferido o pedido, quede-se ineficaz o provimento judicial. Ante o exposto, com fulcro no art. 989, II, do Código de Processo Civil, determino a suspensão do ato reclamado (...) até o julgamento final da presente reclamação.","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"[ Rcl 26.821 MC , rel. min. Edson Fachin , dec. monocrática, j. 4-5-2017, DJE 96 de 9-5-2017.]","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"O STF editou a Súmula Vinculante 44 em consonância com sua jurisprudência reiterada, no sentido da necessidade de previsão legal específica para fins de se admitir a realização de exame psicotécnico como etapa de habilitação em concurso de ingresso no serviço público, devendo os critérios de avaliação observar um grau mínimo de objetividade e publicidade (...). Não se extrai da Súmula Vinculante 44, porquanto ausente a pertinência temática com os precedentes da jurisprudência desta Suprema Corte que justificaram sua edição, a obrigatoriedade de que os critérios objetivos a serem observados pelos avaliadores estejam discriminados em lei em sentido estrito para fins de se conferir o grau de segurança jurídica e publicidade mínimos exigidos. Em outras palavras, a Súmula Vinculante 44 não possui aderência estrita com a tese de que não é legítima a realização do exame psicotécnico previsto em lei como etapa de habilitação em concurso público ou processo seletivo caso os critérios objetivos especificados no edital não estejam normatizados em lei em sentido estrito. Tampouco a Súmula Vinculante 44 possui pertinência temática com a discussão acerca de qual é o instrumento adequado para regulamentar os padrões de aferição do exame psicotécnico instituído como etapa de concurso - se somente o decreto regulamentar ou se é suficiente o edital do certame -, para fins de se fazer respeitar o disposto no parágrafo único do art. 36 da Lei 10.123/1968 do Estado de São Paulo.","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"[ Rcl 25.230 AgR , rel. min. Dias Toffoli , 2ª T, j. 13-12-2016, DJE 34 de 21-2-2017.]","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"A questão contravertida refere-se à legalidade do exame psicotécnico realizado no processo seletivo interno para preenchimento de cadastro de reserva de pilotos da Polícia Militar. Questiona-se a necessidade de edição de lei estadual específica com previsão do exame a ser realizado para o processo seletivo em questão ou se é suficiente a previsão do exame no Código Brasileiro de Aeronáutica, dada a especificidade do cargo, conforme consta do edital. Esta Corte já se pronunciou sobre a matéria reiteradamente e firmou entendimento unânime, no sentido de ser indispensável a previsão em lei do exame psicotécnico, conforme a Súmula Vinculante 44 (...). Contudo, a definição quanto à necessidade de edição de lei específica ou a possibilidade de remissão ao Código Brasileiro da Aeronáutica, que disciplina o exame psicotécnico para pilotos de aeronaves, é matéria de mérito que não pode ser apreciada em pedido de suspensão. Quanto à existência de risco de lesão, concluo que o custeio de curso de formação de pilotos de aeronaves, no valor de R$ 333.025,25 (...) por aluno, a título precário, para policiais reprovados em exame psicotécnico, apresenta grave risco à economia pública. Assevero, finalmente, haver a possibilidade de dano à segurança da população, em virtude da dúvida existente sobre a capacidade psicotécnica dos candidatos para o exercício da função de pilotos de aeronave. Ante o exposto, voto pelo não provimento do agravo regimental.","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"[ SS 5.021 AgR , voto do rel. min. presidente Ricardo Lewandowski , P, j. 2-12-2015, DJE 254 de 17-12-2015.]","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":183,"runs":[{"text":"Necessidade de legislação autorizativa e a previsão em edital para realização de exame psicológico","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"(...) em análise ao ato impugnado foi constatado que houve exame do edital do certame, na parte em que constam os critérios da avaliação psicológica, e que os requisitos apontados pela jurisprudência e pela legislação foram satisfatoriamente atendidos. Desse modo, tendo sido verificadas pela autoridade reclamada a existência de legislação autorizativa e a previsão em edital para realização de exame psicológico, o ato impugnado não viola a Súmula Vinculante 44.","deleted":false}],"heading":false},{"page":183,"runs":[{"text":"[ Rcl 69.191 ED , rel. min. Cristiano Zanin , 2ª T, j. 23-9-2024, DJE s/n de 26-9-2024.]","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"Necessidade de lei estrita para a exigência de exame psicotécnico em concurso público realizado por empresa estatal","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"DIREITO ADMINISTRATIVO. AGRAVO INTERNO EM RECURSO EXTRAORDINÁRIO. CONCURSO PÚBLICO. EMPRESA ESTATAL. NATUREZA ADMINISTRATIVA. COMPETÊNCIA. JUSTIÇA COMUM. EXAME PSICOTÉCNICO. PREVISÃO LEGAL. CRITÉRIOS OBJETIVOS. CARÁTER PROTELATÓRIO. 1. Compete à Justiça comum julgar causas sobre critérios para seleção de pessoal por concurso público em que é parte sociedade de economia mista, em razão de se tratar de ato de natureza administrativa. Precedentes. 2. O Supremo Tribunal Federal já decidiu pela imprescindibilidade de lei para dispor acerca da realização de exame psicotécnico em concurso público, bem como da observância de critérios objetivos (Súmula 686/STF, ratificada pela Súmula Vinculante 44), entendimento que também se aplica às empresas estatais.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"[ RE 937.625 AgR , rel. min. Roberto Barroso , 1ª T, j. 7-4-2017, DJE 78 de 19-4-2017.]","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"Resolução do CNJ e seu caráter de ato normativo primário","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"(...) O cotejo analítico realizado entre a hipótese dos autos e o paradigma invocado indica a inocorrência de violação à Súmula Vinculante 44, haja vista que o exame psicotécnico realizado tinha previsão na Resolução nº 75 do Conselho Nacional de Justiça - CNJ. Saliente-se, no ponto, que esta Corte já consolidou o entendimento de que os atos normativos do CNJ são constituídos de força legal, configurandose atos normativos primários, não havendo que se falar, na espécie, em necessidade de veiculação da regra por meio de lei complementar.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"[ Rcl 60.445 AgR , rel. min. Luiz Fux , 1ª T, j. 22-8-2023, DJE s/n de 31-8-2023.]","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"O exame psicológico no concurso está previsto em ato normativo primário, que, segundo a jurisprudência da Corte, tem força de lei (ADI 533 MC, Relator(a): Min. CARLOS VELLOSO, Tribunal Pleno, DJ 27-09-1991). Desse modo, a Resolução 81 supre a exigência da Súmula vinculante 44, de modo que a não submissão do ora recorrido a tal teste importa sua eliminação do certame. Essas foram as razões da decisão agravada. Não há reparo a fazer no entendimento aplicado. (...) Diante do exposto, nego provimento ao agravo interno.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"[ RE 1.074.855 AgR AgR , rel. min. Alexandre de Moraes , 1ª T, j. 7-5-2018, DJE 258 de 17-5-2018.]","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":184,"runs":[{"text":"● A Súmula Vinculante 44 resultou da conversão da Súmula 686.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 338, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-4-2015.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":184,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"45","number":"45","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":185,"endPage":186,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2362","paragraphs":[{"page":185,"runs":[{"text":"A competência constitucional do Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual.","deleted":false}]}],"notes":[{"page":185,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":185,"runs":[{"text":"No que concerne à competência do Tribunal do Júri, para o processo e julgamento dos crimes dolosos contra a vida, tem o STF decidido que apenas podem ser excepcionadas, nos casos de foro especial por prerrogativa de função, as hipóteses previstas na própria CF/1988, quanto à competência para o processo e julgamento de crimes comuns em geral, consoante se depreende dos arts. 102, I, b e c ; 105, I, a; 108, I, a . (...) o foro especial por prerrogativa de função, regulado em Constituição de Estado-membro, não afasta a norma especial e expressa da competência do Júri, ut art. 5º, XXXVIII, d , da CF/1988, ao conferir ao Tribunal do Júri a competência para o processo e julgamento dos crimes dolosos contra a vida.","deleted":false}],"heading":false},{"page":185,"runs":[{"text":"[ RHC 80.477 , voto do rel. min. Néri da Silveira , 2ª T, j. 31-10-2000, DJ de 4-5-2001.]","deleted":false}],"heading":false},{"page":185,"runs":[{"text":"Habeas corpus. 2. Procurador do Estado da Paraíba condenado por crime doloso contra a vida. 3. A Constituição do Estado da Paraíba prevê, no art. 136, XII, foro especial por prerrogativa de função, dos procuradores do Estado, no Tribunal de Justiça, onde devem ser processados e julgados nos crimes comuns e de responsabilidade. 4. O art. 136, XII, da Constituição da Paraíba não pode prevalecer, em confronto com o art. 5º, XXXVIII, d , da CF/1988, porque somente regra expressa da Lei Magna da República, prevendo foro especial por prerrogativa de função, para autoridade estadual, nos crimes comuns e de responsabilidade, pode afastar a incidência do art. 5º, XXXVIII, d, da CF/1988, quanto à competência do Júri. 5. Em se tratando, portanto, de crimes dolosos contra a vida, os procuradores do Estado da Paraíba hão de ser processados e julgados pelo Júri.","deleted":false}],"heading":false},{"page":185,"runs":[{"text":"[ HC 78.168 , rel. min. Néri da Silveira , P, j. 18-11-1998, DJ de 29-8-2003.]","deleted":false}],"heading":false},{"page":185,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":185,"runs":[{"text":"Foro por prerrogativa de função previsto em Constituição Estadual","deleted":false}],"heading":false},{"page":185,"runs":[{"text":"Quanto à prerrogativa de foro, anoto que a jurisprudência tradicional desta Corte reconhece que a Constituição Federal “ao outorgar, sem reserva, ao Estado-membro, o poder de definir a competência dos seus tribunais (art. 125, § 1º) - situou positivamente no âmbito da organização judiciária estadual a outorga do foro especial por prerrogativa de função, com as únicas limitações que decorram explícita ou implicitamente da própria Constituição Federal” (HC 70.474, rel. min. Sepúlveda Pertence, Primeira Turma, julgado em 17-8-1993). (...) Na mesma linha, a Súmula Vinculante 45 enuncia: “A competência constitucional do tribunal do júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual”. Ao reconhecer a prevalência da competência definida na Constituição Federal, o Tribunal Pleno, ainda que de forma implícita, atestou a higidez da prerrogativa de foro definida em Constituição Estadual, desde que observadas, à obviedade, as diretrizes da Constituição Federal. Assim, de acordo com a jurisprudência da Corte, que observo por força do Princípio da Colegialidade, não há mácula na norma contida na Constituição Estadual que, ao disciplinar a competência do Tribunal de Justiça, elenca a competência penal originária de processamento e julgamento de vereador, na medida em que, ainda nos termos da posição colegiada, referida previsão não destoa das balizas traçadas pela norma nacional. Impende salientar que a prerrogativa de foro conferida aos vereadores não pode ser estendida pela Constituição Estadual no que atine aos Tribunais Regionais Federais, cuja organização foi expressamente estabelecida na Constituição Federal, inexistindo, por","deleted":false}],"heading":false},{"page":186,"runs":[{"text":"óbvio, espaço de conformação a ser preenchido pelo constituinte decorrente. Por fim, o Tribunal local reconheceu a conexão entre as infrações supostamente praticadas pelos denunciados, inferência que resultou na unicidade de processamento e julgamento. Tal proceder alinha-se à Súmula 704 desta Corte (...).","deleted":false}],"heading":false},{"page":186,"runs":[{"text":"[ RHC 135.366 , rel. min. Edson Fachin , dec. monocrática, j. 1º-8-2016, DJE 184 de 31-8-2016.]","deleted":false}],"heading":false},{"page":186,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":186,"runs":[{"text":"● A Súmula Vinculante 45 resultou da conversão da Súmula 721.","deleted":false}],"heading":false},{"page":186,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-4-2015.","deleted":false}],"heading":false},{"page":186,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":186,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"46","number":"46","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":187,"endPage":191,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2368","paragraphs":[{"page":187,"runs":[{"text":"A definição dos crimes de responsabilidade e o estabelecimento das respectivas normas de processo e julgamento são de competência legislativa privativa da União.","deleted":false}]}],"notes":[{"page":187,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":187,"runs":[{"text":"A definição das condutas típicas configuradoras do crime de responsabilidade e o estabelecimento de regras que disciplinem o processo e julgamento dos agentes políticos federais, estaduais ou municipais envolvidos são da competência legislativa privativa da União e devem ser tratados em lei nacional especial (art. 85 da Constituição da República).","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"[ ADI 2.220 , rel. min. Cármen Lúcia , P, j. 16-11-2011, DJE 232 de 7-12-2011.]","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"Tese de Controle Concentrado","deleted":false}],"heading":true},{"page":187,"runs":[{"text":"● É inconstitucional disposição de Constituição estadual ou Lei Orgânica distrital que, em desacordo com o previsto no art. 78, § 3º, da Lei nº 1.079/1950, atribuam à Assembleia ou Câmara Legislativa o julgamento do Governador por crime de responsabilidade","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"[Tese definida na ADI 3.466 , rel. min. Dias Toffoli , red. p/ acórdão min. Roberto Barroso , P, j. 12-4-2023, DJE s/n de 28-6-2023.]","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"De acordo com a Súmula Vinculante nº 46, “[a] definição dos crimes de responsabilidade e o estabelecimento das respectivas normas de processo e julgamento são da competência legislativa privativa da União”. 3. O Plenário do STF já decidiu que o art. 78, § 3º, da Lei nº 1.079/1950, que define que o julgamento de Governadores por crimes de responsabilidade seja “proferido por um tribunal especial de julgamento, composto de cinco membros do Legislativo e cinco desembargadores, para julgar os crimes de responsabilidade dos Governadores”, foi recepcionado pela Constituição de 1988. Precedente. 4. A concentração do juízo de admissibilidade da acusação e do julgamento dos crimes de responsabilidade do Governador na Assembleia Legislativa do Estado ou na Câmara Legislativa do Distrito Federal ofende a lógica do juízo institucional bifásico, prevista no art. 86 da Constituição. 5. Procedência do pedido. Tese de julgamento: “É inconstitucional disposição de Constituição estadual ou Lei Orgânica distrital que, em desacordo com o previsto no art. 78, § 3º, da Lei nº 1.079/1950, atribuam à Assembleia ou Câmara Legislativa o julgamento do Governador por crime de responsabilidade”.","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"[ ADI 3.466 , rel. min. Dias Toffoli , red. p/ acórdão min. Roberto Barroso , P, j. 12-4-2023, DJE s/n de 28-6-2023.]","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"● É vedado aos Estados-membros a ampliação do rol de autoridades sujeitas à convocação pela Assembleia Legislativa e à sanção por crime de responsabilidade, por afronta ao princípio da simetria (art. 50, caput e § 2º, CF) e à competência privativa da União para legislar sobre o tema (art. 22, I, CF e Súmula Vinculante nº 46)","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"[Tese definida na ADI 6.646 , rel. min. Roberto Barroso , P, j. 22-2-2023, DJE s/n de 2-3-2023.]","deleted":false}],"heading":false},{"page":187,"runs":[{"text":"● É vedado às unidades federativas instituírem normas que condicionem a instauração de ação penal contra o Governador, por crime comum, à prévia autorização da casa legislativa, cabendo ao Superior Tribunal de Justiça dispor, fundamentadamente, sobre a aplicação de medidas cautelares penais, inclusive afastamento do cargo.","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"[Tese definida na ADI 4.764 , rel. min. Celso de Mello , red. p/ o ac. min. Roberto Barroso , P, j. 4-5-2017, DJE 178 de 15-8-2017.]","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"(...) tem-se que a autoridade reclamada, ao entender que as normas locais e estaduais se sobrepõem ao que dispõe a legislação nacional naquilo que tange à disciplina de processo e julgamento de crimes de responsabilidade, afronta o que determina a SV 46, assim como o que decidido na ADPF 378/DF, porquanto legitima o recebimento de denúncia e da deliberação pela cassação do mandato do prefeito do Município de Novo Progresso/PA por escrutínio secreto. Nesse sentido: Rcl 22.034/SP, Rel. Min. Roberto Barroso, 24/11/2015. Ante o exposto, nos termos do art. 161, parágrafo único, do Regimento Interno desta Suprema Corte, julgo procedente a presente reclamação para cassar a decisão reclamada proferida no Agravo de Instrumento (...), para que outra seja proferida observando-se a Súmula Vinculante 46 e a ADPF 378/DF.","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"[ Rcl 24.727 , rel. min. Dias Toffoli , dec. monocrática, j. 2-5-2018, DJE 87 de 7-5-2018.]","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"É certo que a possibilidade de afastamento/suspensão temporária do exercício do cargo de prefeito municipal em razão da tramitação de processo jurídico-político de cassação de mandato perante a Câmara Municipal está a merecer por parte deste Supremo Tribunal Federal análise mais detida à luz da normatividade que diretamente deflui da Constituição da República. De qualquer sorte, no caso concreto e na fase em que se encontra o Processo de Cassação de Mandato 1/2016, está-se diante de ato/decisão (Decreto Legislativo 03/2016) lastreado exclusivamente em atos normativos de origem estadual e municipal, a evidenciar plausibilidade de sua contrariedade com o enunciado da Súmula Vinculante 46.","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"[ Rcl 24.461 MC , rel. min. Edson Fachin , dec. monocrática, j. 13-7-2016, DJE 150 de 1º-8-2016.]","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"Conforme disposto na Súmula Vinculante 46, a definição dos crimes de responsabilidade e das respectivas normas de processo e julgamento é de competência legislativa privativa da União. No que concerne ao regime pertinente aos prefeitos municipais, a referida competência foi exercida com a edição do DL 201/1967. 13. No caso concreto, a decisão reclamada reconheceu que o diploma normativo adotado para o julgamento da parte reclamante foi o Regimento Interno da Câmara Municipal. A Câmara Municipal prestou informações no mesmo sentido. O parâmetro normativo utilizado, portanto, é incontroverso. 14. A Súmula Vinculante 46, originada da Súmula 722/STF (aprovada em 26-11-2003), não se presta a servir como fundamento para toda e qualquer alegação de ofensa às normas federais que definem os crimes de responsabilidade e as respectivas regras de processo e julgamento. No entanto, trata-se de caso em que expressamente se admite a utilização de parâmetro normativo diverso do DL 201/1967. A violação à Súmula vinculante, portanto, é clara.","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"[ Rcl 22.034 MC , rel. min. Roberto Barroso , dec. monocrática, j. 16-11-2015, DJE 236 de 24-11-2015.]","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":188,"runs":[{"text":"Competência privativa da União na definição dos crimes de responsabilidade e das regras de processo e julgamento dos vereadores","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"1. A Súmula Vinculante 46 dispõe que a definição dos crimes de responsabilidade e das regras de processo e julgamento é competência legislativa privativa da União para todos os agentes políticos federais, estaduais ou municipais regulados pela legislação nacional especial - o que inclui os vereadores alcançados pelo art. 7º do Decreto-Lei 201/1967.","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"[ Rcl 80.211 AgR , rel. min. Flávio Dino , 1ª T, j. 6-8-2025, DJE s/n 13-8-2025.]","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"Normas de processo e julgamento dos crimes de responsabilidade previstas em legislação de Ente estadual ou municipal","deleted":false}],"heading":false},{"page":188,"runs":[{"text":"3. A tipificação de crimes de responsabilidade e o estabelecimento de regras relativas a seu processamento e julgamento, sob o pretexto de disciplinar hipóteses de infrações administrativas cometidas por Conselheiros do Tribunal de Contas do Estado do Rio de Janeiro, usurpam a competência privativa da União para legislar sobre direito penal e processual (CF/1988, art. 22, I), segundo jurisprudência uníssona do STF sintetizada na Súmula","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"vinculante nº 46, e devem ser regulados em lei nacional especial (CF/1988, art. 85).","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"[ ADI 4190 , rel. min. Nunes Marques , P, j. 24-2-2025, DJE s/n 11-3-2025.]","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"1. A Constituição de 1988 atribuiu ao Legislativo função fiscalizadora do Executivo mediante, entre outros mecanismos, a convocação de autoridades para prestarem informações presencialmente ou por escrito. O não comparecimento injustificado, a recusa em prestar as informações requeridas ou o fornecimento de informações falsas ensejam a imputação do crime de responsabilidade (CF, art. 50, caput e § 2º) 2. Por força do princípio constitucional da simetria (CF, art. 25), não é dado ao legislador estadual alargar o catálogo de autoridades sujeitas ao poder fiscalizatório do Parlamento exercido mediante a requisição de informações por escrito. Precedentes. 3. A Constituição Federal (art. 22, I) prevê expressamente a competência privativa da União para legislar sobre direito penal, inserindo-se no tema a definição dos crimes de responsabilidade. Enunciado vinculante n. 46 da Súmula. 4. Pedido julgado procedente.","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"[ ADI 6.653 , rel. min. Nunes Marques , P, j. 27-11-2023, DJE s/n de 22-1-2024.]","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"Também nas normas impugnadas, em contrariedade à Súmula Vinculante n. 46, se dispõe serem crimes de responsabilidade a ausência injustificada na prestação de informações ou o fornecimento de informações falsas pelos Secretários de Estado (atos do Poder Executivo) e “suas entidades de administração indireta”, além de Procuradores Gerais, quando requisitadas pela Assembleia Legislativa do Rio de Janeiro, pelos respectivos deputados ou comissões: (...) Na esteira da súmula vinculante e dos precedentes apontados, revela-se inequívoca a inconstitucionalidade formal das disposições impugnadas da Constituição do Rio de Janeiro, pela afronta ao disposto no inc. I do art. 22 e parágrafo único do art. 85 da Constituição da República. (...) O alcance das normas impugnadas há de se restringir, portanto, ao direito de acesso à informação constitucionalmente assegurado (inc. XXXIII do art. 5º), na forma da lei nacional, com maior relevo à competência fiscalizatória das Assembleias Legislativas, excluídas as imputações de crimes de responsabilidade, verificada a incompatibilidade formal com o disposto no inc. I do art. 22 e parágrafo único do art. 85 da Constituição da República.","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"[ ADI 6.637 , rel. min. Cármen Lúcia , P, j. 17-12-2022, DJE 13 de 25-1-2023.]","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"Da leitura dos autos, sobretudo da manifestação do reclamado, vê-se que o afastamento do reclamante, do cargo de Prefeito, deu-se com base no Decreto Legislativo 01/2018, editado de acordo a decisão do Plenário da Câmara de Nova Olinda, que, em uma única sessão, recebeu a denúncia apenas após sua leitura e a formalização de pedido de vistas, sem votação no Plenário, e afastou o reclamante de seu cargo, reduzindo seu subsídio pela metade, tudo com base na Lei Estadual 12.550/1995 e Lei Orgânica daquele Município. In casu , estamos diante de ato reclamado editado exclusivamente com base em lei estadual e municipal, a evidenciar plausibilidade de sua contrariedade com a Súmula Vinculante 46. Mais: houve supressão do mandato popular sem que, antes, tenha sido oportunizado a seu detentor o prévio contraditório (art. 5º, LV, da CF/88). Sobre o tema, o Decreto-Lei 201/1967, em seu art. 2º, I, estabelece que, “antes de receber a denúncia, o Juiz ordenará a notificação do acusado para apresentar defesa prévia, no prazo de cinco dias.” Parece prematura e açodada, portanto, a suspensão do mandato popular sem sequer ouvir o acusado, com a inobservância do procedimento legalmente estabelecido e em violação às garantias processuais estabelecidas pela Constituição da República. Ante o exposto, defiro a liminar para suspender a eficácia do Decreto Legislativo 01/2018 da Câmara de Nova Olinda/CE, editado em 15.2.2019, e determinar o imediato retorno do reclamante ao cargo.","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"[ Rcl 33.597 MC , rel. min. Gilmar Mendes , dec. monocrática, j. 8-3-2019, DJE 48 de 12-3-2019.]","deleted":false}],"heading":false},{"page":189,"runs":[{"text":"Na espécie, a parte reclamante sustenta que a autoridade reclamada, ao proceder à intimação do ora reclamante nos termos do art. 86-A, I, da LOM de Pacajus/CE, em detrimento do Decreto-Lei 201/1967, teria afrontado a decisão desta Corte, consubstanciada na citada súmula, tendo em vista a inadmissibilidade da adoção, na hipótese dos autos, de parâmetro normativo diverso do citado decreto-lei. Nesse contexto, afirma que deveria ter sido intimado pessoalmente, tal como estabelece o art. 5º, IV, do Decreto-Lei 201/1967, para","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"participação do interrogatório e oitiva de testemunhas, apresentação de razões finais escritas, bem como para a sessão de julgamento do processo. (...), depreende-se que a autoridade reclamada baseou-se no art. 5º, V, Decreto-Lei 201/1967, para determinar a intimação do ora reclamante por meio de edital. Nesses termos, verifica-se que, na verdade, a autoridade reclamada não se baseou na lei orgânica municipal para proceder à intimação do ora reclamante, mas, sim, no citado Decreto-Lei 201/1967, inexistindo, assim, afronta à Súmula Vinculante 46. (...) Desse modo, não se constata afronta à Súmula Vinculante 46, uma vez que, no caso concreto, houve a aplicação tão somente do Decreto-Lei 201/1967.","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"[ Rcl 32.175 , rel. min. Gilmar Mendes , dec. monocrática, j. 5-12-2018, DJE 263 de 7-12-2018.]","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"A análise dos autos demonstra a plausibilidade do direito defendido, pois o ato reclamado, ao determinar a realização da oitiva das testemunhas em regime de sigilo, com base no art. 41 do Regimento Interno da Câmara Municipal de Cabedelo-PB, claramente, negou observância ao enunciado da Súmula Vinculante 46, uma vez que estabeleceu norma procedimental não prevista no Decreto-lei 201/1967, norma federal aplicável ao caso. (...) A Súmula Vinculante 46 foi aprovada por unanimidade e editada em 09 de abril de 2015, mediante a conversão da antiga Súmula 722 da CORTE. (...) A orientação consolidada na Súmula 722/STF, hoje prevalecente na jurisprudência desta Suprema Corte, conduz ao reconhecimento de que não assiste, ao Estado-membro e ao Município, mediante regramento normativo próprio, competência para definir tanto os crimes de responsabilidade (ainda que sob a denominação de infrações administrativas ou político-administrativas) quanto o respectivo procedimento ritual (...). É fundamental, portanto, ter presente que o processo e julgamento das infrações político-administrativas definidas no art. 4º do DL 201/1967 não preve a inquirição das testemunhas sob o regime de sigilo, conforme demonstra o art. 5º do referido Decreto, (...). Diante do exposto, presentes o fumus boni iuris e o periculum in mora , DEFIRO O PEDIDO LIMINAR para determinar à Câmara Municipal de Cabedelo - PB que afaste o sigilo da oitiva das testemunhas (...), até pronunciamento definitivo desta CORTE, (...).","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"[ Rcl 31.850 MC , rel. min. Alexandre de Moraes , dec. monocrática, j. 19-9-2018, DJE 201 de 24-9-2018.]","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"Estados e Municípios não possuem competência para estabelecer normas definidoras de crimes de responsabilidade, ainda que sob a designação de infrações político-administrativ as","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"Sem razão, pois a decisão reclamada corroborou o entendimento da Câmara Municipal de Curitiba em privilegiar a legislação local em detrimento do previsto no DL n. 201/67, no que se refere ao processo de cassação de vereador por quebra de decoro parlamentar (...). Ademais, a jurisprudência desta Corte é no sentido de que os Estados-Membros e os Municípios não dispõem de competência para estabelecer normas definidoras de crimes de responsabilidade, mesmo que sob a designação de infrações político-administrativas.","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"[ Rcl 55.948 AgR , rel. min. Flávio Dino , 1ª T j. 28-10-2024, DJE s/n 5-12-2024.]","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"Impossibilidade de afastamento provisório de prefeito municipal por falta de previsão no Decreto-lei 201/1967","deleted":false}],"heading":false},{"page":190,"runs":[{"text":"A análise dos autos demonstra a plausibilidade do direito defendido. Tanto a determinação de afastamento cautelar do prefeito pelo prazo de cento e oitenta dias, quanto à imposição de reabertura do procedimento legislativo, claramente, ofendem o Decreto-lei 201/1967, norma federal aplicável ao caso. (...) Com a edição da SV 46 o posicionamento adotado pelo SUPREMO TRIBUNAL FEDERAL tornou-se vinculante no tocante a competência privativa da União para legislar sobre a definição dos crimes de responsabilidade e o estabelecimento das respectivas normas de processo e julgamento; (...) É fundamental, portanto, ter presente que o processo e julgamento das infrações político-administrativas definidas no art. 4º do DL 201/1967 não prevê o afastamento liminar do prefeito denunciado. Além disso, a referida norma determina a conclusão do procedimento dentro do prazo de noventa dias, devendo ser arquivado imediatamente ao final desse prazo, (...). Dessa forma, a manutenção de medidas não previstas no DL 201/1967, norma federal aplicável ao caso, configura, por decorrência lógica, contrariedade ao enunciado da Súmula Vinculante 46.","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"[ Rcl 29.796 , rel. min. Alexandre de Moraes , dec. monocrática, j. 28-2-2018, DJE 41 de 5-3-2018.]","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"Normas de processo e julgamento dos crimes de responsabilidade previstas no Regimento Interno da Câmara dos Deputados","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"É POSSÍVEL A APLICAÇÃO SUBSIDIÁRIA DOS REGIMENTOS INTERNOS DA CÂMARA E DO SENADO (ITEM B DO PEDIDO CAUTELAR): A aplicação subsidiária do Regimento Interno da Câmara dos Deputados e do Senado ao processamento e julgamento do impeachment não viola a reserva de lei especial imposta pelo art. 85, parágrafo único, da Constituição, desde que as normas regimentais sejam compatíveis com os preceitos legais e constitucionais pertinentes, limitando-se a disciplinar questões interna corporis . Improcedência do pedido.","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"[ ADPF 378 MC , rel. min. Edson Fachin , red. p/ o ac. min. Roberto Barroso , P, j. 17-12-2015, DJE 43 de 8-3-2016.]","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"O Partido requerente, quanto aos arts. 19 a 23, caput , da Lei 1.079/1950, requer a declaração de recepção de tais dispositivos pela ordem Constitucional vigente, “a fim de afastar interpretação permissiva de que regras procedimentais ali previstas sejam substituídas pelas do art. 218 do Regimento Interno da Câmara dos Deputados (RICD)”. Ora, hoje não paira mais dúvida de que somente a União detém competência legislativa para estabelecer as normas de processo e julgamento dos crimes de responsabilidade. A jurisprudência da Corte está absolutamente consolidada a respeito do tema, consolidada na Súmula Vinculante 46 (...). Como já ressaltei acima, o Regimento Interno, nessa matéria, é norma infralegal, que deverá ater-se apenas à disciplina interna corporis das Casas Legislativas e, principalmente, observar com fidedignidade os preceitos legais e constitucionais correspondentes. Dessa forma, a exemplo dos demais atos infralegais, não pode inovar no mundo jurídico e criar normas processuais em matéria de crimes de responsabilidade, pois, se assim procederem, usurparão a competência do próprio Congresso Nacional no tocante à nobilíssima função de legislar, no sentido estrito da palavra.","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"[ ADPF 378 MC , rel. min. Edson Fachin , red. p/ o ac. min. Roberto Barroso , voto do min. Ricardo Lewandowski , P, j. 17-12-2015, DJE 43 de 8-3-2016.]","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":191,"runs":[{"text":"● A Súmula Vinculante 46 resultou da conversão da Súmula 722.","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"Data de publicação do enunciado: DJE de 17-4-2015.","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":191,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"47","number":"47","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":192,"endPage":197,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2504","paragraphs":[{"page":192,"runs":[{"text":"Os honorários advocatícios incluídos na condenação ou destacados do montante principal devido ao credor consubstanciam verba de natureza alimentar cuja satisfação ocorrerá com a expedição de precatório ou requisição de pequeno valor, observada ordem especial restrita aos créditos dessa natureza.","deleted":false}]}],"notes":[{"page":192,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":192,"runs":[{"text":"ALEGADO FRACIONAMENTO DE EXECUÇÃO CONTRA A FAZENDA PÚBLICA DE ESTADO-MEMBRO. HONORÁRIOS ADVOCATÍCIOS. VERBA DE NATUREZA ALIMENTAR, A QUAL NÃO SE CONFUNDE COM O DÉBITO PRINCIPAL. AUSÊNCIA DE CARÁTER ACESSÓRIO. TITULARES DIVERSOS. POSSIBILIDADE DE PAGAMENTO AUTÔNOMO. REQUERIMENTO DESVINCULADO DA EXPEDIÇÃO DO OFÍCIO REQUISITÓRIO PRINCIPAL. VEDAÇÃO CONSTITUCIONAL DE REPARTIÇÃO DE EXECUÇÃO PARA FRAUDAR O PAGAMENTO POR PRECATÓRIO. INTERPRETAÇÃO DO ART. 100, § 8º (ORIGINARIAMENTE § 4º), DA CONSTITUIÇÃO DA REPÚBLICA. RECURSO AO QUAL SE NEGA SEGUIMENTO.","deleted":false}],"heading":false},{"page":192,"runs":[{"text":"[ RE 564.132 , rel. min. Eros Grau , red. p/ o ac. min. Cármen Lúcia , P, j. 30-10- 2014, DJE 27 de 10-2-2015, Tema 18.]","deleted":false}],"heading":false},{"page":192,"runs":[{"text":"A finalidade do preceito acrescentado pela EC 37/2002 (art. 100, § 4º) ao texto da CF/1988 é a de evitar que o exequente se valha simultaneamente, mediante o fracionamento, repartição ou quebra do valor da dívida, de dois sistemas de satisfação de crédito: o do precatório para uma parte dela e o do pagamento imediato (sem expedição de precatório) para outra. 23. Daí que a regra constitucional apenas se aplica a situações nas quais o crédito seja atribuído a um mesmo titular. E isso de sorte que, a verba honorária não se confundindo com o principal, o preceito não se aplica quando o titular do crédito decorrente de honorários pleiteie o seu recebimento. Ele não sendo titular de dois créditos não incide, no caso, o disposto no art. 100, § 4º, da Constituição do Brasil. 24. A verba honorária consubstancia direito autônomo, podendo mesmo ser executada em separado. Não se confundindo com o crédito principal que cabe à parte, o advogado tem o direito de executar seu crédito nos termos do disposto nos arts. 86 e 87 do ADCT. 25. A única exigência a ser, no caso, observada é a de que o fracionamento da execução ocorra antes da expedição do ofício requisitório, sob pena de quebra da ordem cronológica dos precatórios.","deleted":false}],"heading":false},{"page":192,"runs":[{"text":"[ RE 564.132 , voto do rel. min. Eros Grau , red. p/ o ac. min. Cármen Lúcia , P, j. 30-10-2014, DJE 27 de 10-2-2015, Tema 18.]","deleted":false}],"heading":false},{"page":192,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":192,"runs":[{"text":"● Os honorários advocatícios incluídos na condenação ou destacados do montante principal devido ao credor consubstanciam verba de natureza alimentar cuja satisfação ocorrerá com a expedição de precatório ou requisição de pequeno valor, observada ordem especial restrita aos créditos dessa natureza.","deleted":false}],"heading":false},{"page":192,"runs":[{"text":"[Tese definida no RE 564.132 , rel. min. Eros Grau , red. p/ o ac. min. Cármen Lúcia , P, j. 30-10-2014, DJE 27 de 10-2-2015, Tema 18.]","deleted":false}],"heading":false},{"page":192,"runs":[{"text":"A situação dos autos distingue-se do paradigma. Isso porque o tribunal de origem entendeu que a natureza alimentar dos honorários advocatícios é compatível com o arresto de valores superiores aos considerados necessários para a manutenção da subsistência do credor. Como essa questão específica não foi objeto de análise na Súmula Vinculante 47 ou nos precedentes que resultaram em sua edição, não há a necessária","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"relação de aderência estrita entre a decisão reclamada e o paradigma invocado, o que impede o prosseguimento da reclamação.","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"[ Rcl 31.193 , rel. min. Roberto Barroso , dec. monocrática, j. 5-9-2018, DJE 188 de 10-9-2018.]","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"Verifica-se, pois, que o juízo reclamado, ao afirmar que a execução autônoma da verba honorária implica fracionamento da execução, divergiu da orientação firmada por este Tribunal na linha de que assiste ao advogado o direito de requerer, em separado, a execução dos honorários - verba que lhe pertence e que possui natureza alimentar -, haja vista a inexistência de acessoriedade em relação ao crédito principal e, ainda, a circunstância de ser titularizado por credor diverso do titular da verba principal.","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"[ Rcl 21.516 , rel. min. Luiz Fux , dec. monocrática, j. 27-8-2015, DJE 171 de 1º-9-2015.]","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"● A interpretação do § 4º do art. 100, alterado e hoje § 8º do art. 100 da Constituição da República, permite o pagamento dos débitos em execução nos casos de litisconsórcio facultativo.","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"[Tese definida no RE 568.645 , rel. min. Cármen Lúcia , P, j. 24-9-2014, DJE 223 de 13-11-2014, Tema 148.]","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"Agravo regimental no recurso extraordinário. Constitucional e Processual. Ação promovida em litisconsórcio facultativo. Honorários advocatícios. Execução proporcional à fração de cada litisconsorte. Artigo 100, § 8º, da CF. Violação. Ocorrência. Precedentes. 1. Nas causas em que a Fazenda Pública for condenada ao pagamento da verba honorária de forma global, é vedado o fracionamento de crédito único, consistente no valor total dos honorários advocatícios devidos, proporcionalmente à fração de cada litisconsorte, sob pena de afronta ao art. 100, § 8º, da Constituição Federal. 2. Agravo regimental ao qual se dá provimento.","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"[ RE 1.038.035 AgR , rel. min. Edson Fachin , red. p/ o ac. min. Dias Toffoli , 2ª T, j. 7-11-2017, DJE 45 de 9-3-2018.]","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"Os honorários configuram crédito único do advogado, sendo vedado o fracionamento em tantas execuções quantos forem os credores litisconsortes facultativos, ante a autonomia dos valores devidos ao patrono das partes em relação ao principal a ser satisfeito aos litigantes, observada a regra do art. 100, § 8º, da Carta da República.","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"[ RE 919.267 AgR-segundo , rel. min. Marco Aurélio , 1ª T , j. 16-8-2016, DJE 201 de 21-9-2016.]","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"(...) considerando os princípios norteadores do ordenamento jurídico vigente, notadamente os princípios da economia e da celeridade processuais, nas execuções relativas a ações iniciadas por litisconsortes ativos facultativos é viável a expedição de requisições de pequeno valor ou de precatórios, adotando-se como parâmetro os valores específicos de cada um dos litisconsortes. Aliás, outro não foi o entendimento do Plenário do Supremo Tribunal Federal, que, no julgamento do RE 568.645 RG, rel. min. Cármen Lúcia, DJE de 13-11-2014, firmou jurisprudência no sentido de que a execução ou o pagamento singularizado dos valores devidos às partes integrantes de litisconsórcio facultativo simples não contraria o § 8º (originariamente § 4º) do art. 100 da Constituição da República. Assim, a forma de pagamento, por Requisição de Pequeno Valor ou precatório, dependerá dos valores isoladamente considerados. Tal orientação, firmada sob a sistemática da repercussão geral, aplica-se, de igual modo, à possibilidade de individualização dos honorários advocatícios, proporcionalmente à fração de cada um dos litisconsortes facultativos, sob pena de se desestimular a formação de litisconsórcios facultativos simples para a discussão judicial de pedidos idênticos. (...) Com efeito, admitindo-se o ajuizamento individualizado da execução pelos litisconsortes ativos facultativos, deve-se permitir também que os respectivos honorários advocatícios sejam executados de forma singularizada, guardando-se a proporção com o crédito de cada exequente.","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"[ RE 930.251 AgR , voto do rel. min. Luiz Fux , 1ª T , j. 15-3-2016, DJE 77 de 22-4-2016.]","deleted":false}],"heading":false},{"page":193,"runs":[{"text":"A controvérsia submetida pelo recurso extraordinário ao exame desta Corte diz respeito à legitimidade do pagamento individualizado, por Requisição de Pequeno Valor (RPV), de honorários advocatícios em casos de execução de sentença contra a Fazenda Pública decorrente de ação de conhecimento com litisconsórcio ativo","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"facultativo. (...) No RE 568.645, o STF assentou que “a execução ou o pagamento singularizado dos valores devidos a partes integrantes de litisconsórcio facultativo simples não contrariam o § 8º (originariamente § 4º) do art. 100 da Constituição Federal”. Embora a questão do “fracionamento dos honorários advocatícios” constasse do recurso extraordinário, não foi conhecida, na ocasião, em razão da ausência de prequestionamento. No RE 564.132, por sua vez, o Pleno firmou a orientação de que é possível a execução autônoma dos honorários advocatícios, por se tratar de verba de natureza alimentar, que não se confunde com o débito principal, pertencente a titular diverso. Conquanto a Corte não tenha decidido matéria idêntica à presente no RE 564.132, é certo que foram fornecidas as balizas necessárias para o deslinde deste caso. É que, ao defender a legitimidade da execução dos honorários advocatícios de forma autônoma do débito principal, o voto condutor do acórdão, da lavra do ministro Eros Grau, ressaltou o fato de que as quantias (a) possuem naturezas distintas; (b) podem ser, segundo o Estatuto da Advocacia, executadas de forma autônoma; e, o que é mais importante, (c) têm titulares diversos. (...) No caso dos autos, a parte recorrente pretende promover a execução dos honorários advocatícios, não apenas de forma autônoma do débito principal, mas também de forma fracionada, levando-se em conta o número de litisconsortes ativos. Ora, como a verba honorária pertence a um mesmo titular, é evidente que seu pagamento de forma fracionada, por RPV, encontra óbice no art. 100, § 8º, da Constituição Federal.","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"[ RE 919.050 , rel. min. Teori Zavascki , dec. monocrática, j. 24-2-2016, DJE 37 de 29-2-2016.]","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"O acórdão recorrido não divergiu da jurisprudência firmada no âmbito deste Supremo Tribunal Federal, cristalizada na Súmula Vinculante 47 (...). Na esteira da jurisprudência desta Corte, não ofende o art. 100 da Constituição Federal o fracionamento do valor da execução proposta contra a Fazenda Pública para pagamento de honorários advocatícios, os quais possuem natureza alimentar e caráter autônomo, não se confundindo com o débito principal. (...) Na hipótese, pretende-se que o crédito relativo aos honorários advocatícios, já destacado do montante devido ao credor, pertencentes a um único titular, seja fracionado em tantos quantos forem as partes integrantes do litisconsórcio ativo formado na ação de conhecimento, a fim de que o pagamento se faça por requisição de pequeno valor. Ao exame da controvérsia, a Corte de origem indeferiu o pedido, possibilitando, no entanto, a execução autônoma do valor integral dos honorários de advogado. Nesse contexto, não diviso a apontada violação da Constituição da República.","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"[ RE 918.672 , rel. min. Rosa Weber , dec. monocrática, j. 11-11-2015, DJE 231 de 18-11-2015.]","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":194,"runs":[{"text":"Execução autônoma de créditos decorrentes de honorários advocatícios fixados de forma global sobre o valor da condenação","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"Constitucional e Processual. Regra do art. 100, § 8º, da CF. Litisconsórcio ativo facultativo. Honorários advocatícios. Crédito autônomo, uno e indiviso fixado de forma global. Execução proporcional à fração de cada litisconsorte. Impossibilidade. Embargos de divergência providos. 1. Uma vez que o crédito do advogado se origina de uma relação de direito processual, sendo devido em função de atos únicos praticados no curso do processo, em proveito de todos os litisconsortes e independentemente de quantos eles sejam, fixados os honorários de forma global sobre o valor da condenação, o crédito constituído é uno, indivisível e guarda total autonomia no que concerne ao crédito dos litisconsortes. 2. Nas causas em que a Fazenda Pública for condenada ao pagamento da verba honorária de forma global, é vedado o fracionamento de crédito único, consistente no valor total dos honorários advocatícios devidos, proporcionalmente à fração de cada litisconsorte, sob pena de afronta ao art. 100, § 8º, da Constituição.","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"[ RE 919.793 AgR-ED-EDv , rel. min. Dias Toffoli , P, 7-2-2019, DJE 138 de 26-6-2019.]","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"Execução autônoma de créditos decorrentes de honorários advocatícios contratuais","deleted":false}],"heading":false},{"page":194,"runs":[{"text":"Nada obstante, esta Suprema Corte firmou entendimento no sentido da inaplicabilidade da Súmula Vinculante 47 aos honorários advocatícios contratuais. Isso porque os honorários sucumbenciais são estipulados pelo","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"título executivo judicial, que produz efeitos para as partes que integraram a relação jurídica processual, enquanto os honorários contratuais têm por origem o contrato de prestação de serviços advocatícios, que vincula o advogado e o cliente, mas não a Fazenda Pública.","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"[ ARE 1.489.948 AgR , rel. min. Luiz Fux , 1ª T, j. 1º-7-2024, DJE s/n de 2-8-2024.]","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"(...) a parte proponente não demonstrou a existência de controvérsia atual sobre o alcance do enunciado da Súmula Vinculante nº 47, notadamente quanto à possibilidade de a interpretação do referido verbete autorizar, ou não, a expedição de RPV ou de precatório para pagamento de honorários contratuais dissociados do montante principal. Os únicos dois precedentes invocados pelo proponente correspondem a decisões monocráticas prolatadas em 2015, uma no bojo do RE nº 917803, Relator o Ministro Luiz Fux, e outra na Rcl nº 21299, Relator o Ministro Roberto Barroso, e que, quando da apresentação da presente proposta de revisão, em abril de 2023, já estavam ultrapassados pela jurisprudência deste Supremo Tribunal Federal, que se firmou no sentido da “inviabilidade de expedição de RPV ou de precatório paga pagamento de honorários contratuais dissociados do principal a ser requisitado, à luz do art. 100, § 8º, da Constituição Federal” (ARE 1374239, Relator o Ministro Dias Toffoli, DJe de 09.08.2022). (...) Ante o exposto, à míngua de demonstração de controvérsia atual, suscetível de acarretar grave insegurança jurídica e relevante multiplicação de processos, no tocante à questão enfocada pelo proponente, reputo ausente requisito formal previsto no art. 2º, § 1º, da Lei nº 11.417/2006 e, portanto, determino o arquivamento desta proposta de revisão de súmula vinculante.","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"[ PSV 146 , rel. min. Rosa Weber , dec. monocrática, j. 4-8-2023, DJE s/n de 8-8-2023.]","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"Agravo regimental no recurso extraordinário. Processual Civil. Honorários advocatícios contratuais. Fracionamento para pagamento por RPV ou precatório. Impossibilidade. Súmula Vinculante 47. Inaplicabilidade. Precedentes. 1. A jurisprudência da Corte é firme no sentido de que a Súmula Vinculante 47 não alcança os honorários contratuais resultantes do contrato firmado entre advogado e cliente, não abrangendo aquele que não fez parte do acordo. 2. O Supremo Tribunal Federal já assentou a inviabilidade de expedição de RPV ou de precatório para pagamento de honorários contratuais dissociados do principal a ser requisitado, à luz do art. 100, § 8º, da Constituição Federal. 3. Agravo regimental não provido.","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"[ RE 1.094.439 AgR , rel. min. Dias Toffoli , 2ª T, j. 2-3-2018, DJE 52 de 19-3-2018.]","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"7. A proposta de edição da Súmula Vinculante 47 (PSV 85), de autoria da Ordem dos Advogados do Brasil, fundamentou-se nos arts. 22, § 4º, e 23, da Lei 8.906/1994, que tratam, respectivamente, dos honorários contratuais e dos incluídos na condenação por sucumbência ou arbitramento. Nos debates que antecederam a aprovação da súmula, não foi acolhida sugestão para que seu texto contivesse limitação expressa aos honorários incluídos na condenação (art. 23 da Lei 8.906/1994). Parte do texto aprovado para a súmula parece, ainda, remeter ao § 4º do art. 22 da Lei 8.906/1994 (“Os honorários advocatícios incluídos na condenação ou destacados do montante principal devido ao credor consubstanciam verba de natureza alimentar cuja satisfação ocorrerá com a expedição de precatório ou requisição de pequeno valor, observada ordem especial restrita aos créditos dessa natureza”). Adotando essas razões, inicialmente concluí que os honorários contratuais eram alcançados pela Súmula Vinculante 47. 8. Posteriormente, ambas as turmas desta Corte afirmaram, em precedentes unânimes, a inaplicabilidade da Súmula Vinculante 47 aos honorários advocatícios contratuais. A jurisprudência desta Corte tem apontado inexistir relação de estrita aderência entre decisões sobre o fracionamento de execução contra a Fazenda Pública, para o pagamento de honorários contratuais, e a Súmula Vinculante 47: Rcl 21.916, rel. Min. Marco Aurélio; Rcl 24.201, rel. Min. Cármen Lúcia; (...). 9. Assim, adiro à posição adotada pela maioria dos membros desta Corte e concluo que a Súmula Vinculante 47 não alcança o debate relativo ao fracionamento fracionamento de execução contra a Fazenda Pública para pagamento, separado do montante principal, de créditos decorrentes de honorários advocatícios contratuais.","deleted":false}],"heading":false},{"page":195,"runs":[{"text":"[ Rcl 26.840 AgR , rel. min. Roberto Barroso , dec. monocrática, j. 23-11-2017, DJE 268 de 27-11-2017.]","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"1. A jurisprudência do STF não admite a expedição de requisitório em separado para pagamento de honorários advocatícios contratuais, à luz do art. 100, §8º, da Constituição da República. 2. A possibilidade de oposição de contrato de honorários contratuais não honrado antes da expedição de requisitório decorre de legislação infraconstitucional, notadamente o Estatuto da Ordem dos Advogados do Brasil, e a controvérsia referente ao adimplemento de negócio jurídico entre causídico e respectivo cliente não possui relevância para a Fazenda Pública devedora e a operabilidade da sistemática dos precatórios. 3. A presente controvérsia não guarda semelhança com o do RE 564.132, que deu fundamento à edição da Súmula Vinculante 47 do STF, pois a autonomia entre o débito a ser recebido pelo jurisdicionado e o valor devido a título de honorários advocatícios restringe-se aos sucumbenciais, haja vista a previsão legal destes contra a Fazenda Pública, o que não ocorre na avença contratual entre advogado e particular.","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"[ RE 1.035.724 AgR , rel. min. Edson Fachin , 2ª T, j. 11-9-2017, DJE 214 de 21-9-2017.]","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"A Súmula Vinculante 47 não alcança os honorários contratuais, resultante do contrato firmado entre advogado e cliente, não alcançando aquele que não fez parte do acordo. 2. A pretensão de adimplemento de honorários decorrentes de cláusula de contrato de prestação de serviço firmado entre a parte vencedora e seu patrono por meio de precatório ou requisição de pequeno valor de forma destacada do montante principal é matéria que não possui aderência estrita com o entendimento consubstanciado na Súmula Vinculante 47.","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"[ Rcl 23.886 AgR , rel. min. Dias Toffoli , 2ª T , j. 9-12-2016, DJE 30 de 15-2-2017.]","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"O acórdão recorrido não divergiu da jurisprudência firmada no âmbito deste Supremo Tribunal Federal, cristalizada na Súmula Vinculante 47/STF (...). Na esteira da jurisprudência desta Corte, não ofende o art. 100 da Constituição Federal o fracionamento do valor da execução proposta contra a Fazenda Pública para pagamento de honorários advocatícios, os quais possuem natureza alimentar e caráter autônomo, não se confundindo com o débito principal. (...) Esse entendimento alcança os honorários contratuais (...).","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"[ RE 917.665 , rel. min. Rosa Weber , dec. monocrática, j. 19-10-2015, DJE 214 de 27-10-2015.]","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"Ordem de preferência de créditos tributários e honorários advocatícios de natureza alimentar","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"(...) o enunciado vinculante não tratou sobre preferência de créditos. Apenas estabeleceu uma ordem de preferência na expedição dos precatórios de natureza alimentar, reconhecendo esta natureza também à verba honorária a ser quitada por meio de requisitório, nos termos do art. 100, §§ 1º e 2º, da Constituição Federal. Com efeito, do enunciado acima transcrito, depreende-se que a citada súmula vinculante trata do caráter alimentar dos honorários advocatícios, assentando a possibilidade do fracionamento de sua execução, para satisfação autônoma. Por sua vez, o ato reclamado assentou-se no fundamento quanto à preferência dos créditos tributários em relação aos honorários advocatícios na expedição dos precatórios de natureza alimentar. Assim, não se verifica similitude entre o decidido no ato reclamado e o assentado por esta Corte na Súmula Vinculante 47, o que acarreta a inadmissibilidade da ação, por ausência de pressuposto de cabimento necessário.","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"[ Rcl 30.833 , rel. min. Luiz Fux , dec. monocrática, j. 29-6-2018, DJE 153 de 1º-8-2018.]","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"(...) observo que a autoridade reclamada, em sede de cumprimento de sentença, ao analisar o caso dos autos (...), assentou que a decisão do STJ, que reconheceu a preferência dos créditos tributários sobre os honorários advocatícios, não teria afrontado a SV 47. (...) a citada súmula vinculante trata do caráter alimentar dos honorários advocatícios, assentando a possibilidade do fracionamento de sua execução, para satisfação autônoma. (...) Assim, não se verifica similitude entre o decidido no ato reclamado e o assentado por esta Corte na Súmula Vinculante 47, o que acarreta a inadmissibilidade da ação, por ausência de pressuposto de cabimento necessário.","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"[ Rcl 27.651 , rel. min. Gilmar Mendes , dec. monocrática, j. 21-8-2017, DJE 187 de 24-8-2017.]","deleted":false}],"heading":false},{"page":196,"runs":[{"text":"Transmudação da natureza de precatório alimentar em normal em virtude de cessão do direito nele estampado","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"Ao concluir que o percentual de precatório conserva a sua natureza de crédito preferencial, uma vez que o titular continua a fazer jus ao benefício constitucional, o órgão fracionário do Tribunal estadual não diverge da jurisprudência desta Suprema Corte.","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"[ ARE 1.517.977 , rel. min. Nunes Marques , dec. monocrática, j. 2-12-2024, DJE s/n de 3-12-2024.]","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"Esta Corte vem - ao menos desde o ano de 1996 - assentando a natureza alimentar dos precatórios referentes aos honorários advocatícios. (...) A uniformidade sobre o tema levou o STF a editar a Súmula Vinculante 47 (...). Em relação ao alegado, reconheço que a matéria - transmudação da natureza de precatório alimentar em normal, em virtude de cessão do direito nele estampado - está sendo tratada em sede de repercussão geral no Tema 361. Entretanto, observo que não houve nenhuma determinação pelo relator do feito sobre sobrestamento de processos para que se aguardasse o julgamento pelo STF, de forma que esta demanda deve prosseguir regularmente. Quanto à cessão, anoto que se aplica a Resolução 115/2010 do CNJ (...). Segundo essa resolução, a cessão de crédito não altera a natureza alimentar do precatório, de sorte que não há mutação de sua classificação originária. Sob essa ótica, o Precatório (...) deve ser considerado como de natureza alimentar, tendo em vista que se trata de honorários advocatícios, independentemente da ocorrência de cessão.","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"[ Rcl 23.796 , voto do rel. min. Gilmar Mendes , 2ª T, j. 13-12-2016, DJE 28 de 13-2-2017.]","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":197,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 18, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"Data de publicação do enunciado: DJE de 2-6-2015.","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":197,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"48","number":"48","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":198,"endPage":199,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2505","paragraphs":[{"page":198,"runs":[{"text":"Na entrada de mercadoria importada do exterior, é legítima a cobrança do ICMS por ocasião do desembaraço aduaneiro.","deleted":false}]}],"notes":[{"page":198,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":198,"runs":[{"text":"Desnecessário muito esforço interpretativo para concluir-se que a necessidade de definição do Estado competente para a exigência do ICMS decorreu da altera- ção introduzida quanto ao elemento temporal referido ao fato gerador do tributo, que na hipótese em tela deixou de ser o momento da entrada da mercadoria no estabelecimento do importador, para ser o do recebimento da mercadoria importada. (...) Antecipado o elemento temporal para o momento do recebimento da mercadoria, vale dizer, do desembaraço, fez-se ela necessária, tendo em vista que a entrada da mercadoria, não raro, se dá em terminal portuário ou aéreo situado fora dos limites do Estado de destino da mercadoria. Consagrou a nova Carta, portanto, finalmente, a pretensão, de há muito perseguida pelos Estados, de verem condicionado o desembaraço da mercadoria ou do bem importado ao recolhimento, não apenas dos tributos federais, mas também do ICMS incidente sobre a operação. O benefício decorrente da medida salta à vista: reduzir praticamente a zero a sonegação, com simultânea redução do esforço de fiscalização, sem gravame maior para o contribuinte.","deleted":false}],"heading":false},{"page":198,"runs":[{"text":"[ RE 193.817 , voto do rel. min. Ilmar Galvão , P, j. 23-10-1996, DJ de 10-8-2001.]","deleted":false}],"heading":false},{"page":198,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":198,"runs":[{"text":"● Não incide o ICMS na operação de arrendamento mercantil internacional, salvo na hipótese de antecipação da opção de compra, quando configurada a transferência da titularidade do bem.","deleted":false}],"heading":false},{"page":198,"runs":[{"text":"[Tese definida no RE 540.829 , rel. min. Gilmar Mendes , red. p/ o ac. min. Luiz Fux , P, j. 11-9-2014, DJE 226 de 18-11-2014, Tema 297.]","deleted":false}],"heading":false},{"page":198,"runs":[{"text":"Assim, a autoridade reclamada, analisando o caso concreto, concluiu que a (...) para se beneficiar de sua própria torpeza ao dissimular o negócio jurídico de compra de aeronaves concluído em novembro de 2008, dando aparência de “contrato de arrendamento mercantil, a fim de retardar o recolhimento do ICMS”, tendo concluído pela improcedência da pretensão. Em outras palavras, decidiu-se que é legítima a incidência do ICMS desde novembro de 2008, em razão de as mercadorias (aeronaves) terem sido recebidas pela empresa importadora desde a entrada no território nacional sob a aparência de contrato de leasing . A SV 48 não pretendeu exaurir as hipóteses, como a presente, em que se debata a existência de simulação por parte do contribuinte como forma de se furtar ou retardar o pagamento dos tributos que seriam devidos. A aderência estrita do objeto do ato reclamado ao conteúdo do paradigma é requisito de admissibilidade da reclamação constitucional, a qual não se verifica na presente reclamação.","deleted":false}],"heading":false},{"page":198,"runs":[{"text":"[ Rcl 27.540 , rel. min. Dias Toffoli , dec. monocrática, j. 25-9-2017, DJE 219 de 27-9-2017.]","deleted":false}],"heading":false},{"page":198,"runs":[{"text":"O recorrente (...) contesta a tese do julgado que afastou a ilegalidade da retenção de mercadoria importada por ausência de comprovação do recolhimento do ICMS. Não prospera a alegação de afronta do julgado ao art. 155, II, da Constituição Federal. Para afastar a incidência do ICMS, o recorrente alega que a operação realizada não constitui compra e venda de equipamentos médicos, e sim arrendamento mercantil ( leasing ). O exame da questão da natureza da operação que gerou a incidência do ICMS e a verificação da ocorrência ou não de transferência de domínio, a caracterizar eventual arrendamento mercantil internacional, apto a afastar a incidência da exação, como bem colocado pelo parecer da Procuradoria-Geral da República, demanda a análise de aspectos fáticos e de elementos de prova, o que inviabiliza o extraordinário, a teor da Súmula","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"279/STF. (...) Além disso, ressalto que o acórdão recorrido não diverge da jurisprudência desta Corte, assentado na Súmula Vinculante 48 (...).","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"[ RE 600.980 , rel. min. Ricardo Lewandowski , dec. monocrática, j. 18-9-2017, DJE 215 de 22-9-2017.]","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":199,"runs":[{"text":"Incidência de ICMS na importação de mercadorias para contribuinte não habitual após a edição da EC 33/2001 e da LC 114/2002","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"(...) ressalta-se que o acórdão recorrido não diverge da jurisprudência desta Corte, segundo a qual, “na entrada de mercadoria importada do exterior, é legítima a cobrança do ICMS por ocasião do desembaraço aduaneiro” (Súmula 661 do STF). Confira-se, a propósito, o seguinte precedente: “(...) O Plenário do Supremo Tribunal Federal já decidiu que o fato gerador do ICMS, incidente sobre mercadoria importada, ocorre por ocasião do recebimento da mercadoria, no respectivo desembaraço aduaneiro (RE 193.817, rel. min. Ilmar Galvão). Nessas condições, não fica constatada nenhuma coação indireta na exigência, fundada em lei, do recolhimento dos tributos relativos ao desembaraço aduaneiro de bens importados. Agravo regimental a que se nega provimento” (RE 810.035 AgR, rel. min. Roberto Barroso, Primeira Turma, julgado em 7-4-2015, Processo Eletrônico DJE -075, divulg 22-4-2015, public 23-4-2015). Ante o exposto, nego seguimento ao agravo, nos termos do art. 21, § 1º, do RISTF.","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"[ ARE 1.022.791 , rel. min. Edson Fachin , dec. monocrática, j. 15-2-2017, DJE 33 de 20-2-2017.]","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"Verifico que o Tribunal de origem decidiu pela incidência do ICMS sobre a operação de importação de bem por contribuinte não habitual do ICMS após a EC 33/2001 e LC 114/2002. No caso, a importação ocorreu já na vigência da Lei estadual 13.099/2008, a qual alterou a redação dos arts. 3º, VI, e 6º, parágrafo único, a da Lei estadual 8.820/1989, passando a regular, no Estado do Rio Grande do Sul, a incidência do ICMS na importação de bens, por pessoa física ou jurídica, ainda que não seja contribuinte habitual do imposto, qualquer que seja a sua finalidade. Desse modo, note-se que a decisão da instância de origem não divergiu do entendimento firmado por esta Corte (...).","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"[ ARE 1.021.712 , rel. min. Dias Toffoli , dec. monocrática, j. 1º-2-2017, DJE 29 de 14-2-2017.]","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"Observações","deleted":false}],"heading":true},{"page":199,"runs":[{"text":"● A Súmula Vinculante 48 resultou da conversão da Súmula 661.","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"● Vide Súmula 660.","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 297, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"Data de publicação do enunciado: DJE de 2-6-2015.","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":199,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"49","number":"49","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":200,"endPage":201,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2506","paragraphs":[{"page":200,"runs":[{"text":"Ofende o princípio da livre concorrência lei municipal que impede a instalação de estabelecimentos comerciais do mesmo ramo em determinada área.","deleted":false}]}],"notes":[{"page":200,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":200,"runs":[{"text":"A Constituição Federal assegura o livre exercício de qualquer atividade econômica, independentemente de autorização do poder público, salvo nos casos previstos em lei. 2. Observância de distância mínima da farmácia ou drogaria existente para a instalação de novo estabelecimento no perímetro. Lei municipal 10.991/1991. Limitação geográfica que induz à concentração capitalista, em detrimento do consumidor, e implica cerceamento do exercício do princípio constitucional da livre concorrência, que é uma manifestação da liberdade de iniciativa econômica privada.","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"[ RE 193.749 , rel. min. Carlos Velloso , red. p/ o ac. min. Maurício Corrêa , P, j. 4-6-1998, DJ de 4-5-2001.]","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":200,"runs":[{"text":"Exceção à aplicação da Súmula Vinculante 49 por motivo de segurança e de proteção à saúde e ao meio ambiente","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"(...) o entendimento adotado na decisão impugnada não se constitui em ofensa à tese firmada na Súmula Vinculante 49 (...). Deveras, o direito à livre concorrência contido no enunciado da Súmula Vinculante 49 não é absoluto, porquanto a própria jurisprudência desta Corte que fundamentou a edição do referido verbete sumular trouxe temperamentos a essa prerrogativa, por imperativos de segurança e de proteção à saúde e ao meio ambiente. Daí a ausência da estrita aderência entre a decisão impugnada e o paradigma sumular apontado, fator imprescindível para o conhecimento do pleito reclamatório. Com efeito, a jurisprudência desta Corte, que se refletiu na edição da Súmula Vinculante que se alega violada, entende legítima a imposição de restrições à localização de determinados tipos de estabelecimentos comerciais, como postos de combustíveis.","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"[ Rcl 32.229 , rel. min. Luiz Fux , dec. monocrática, j. 17-10-2018, DJE 223 de 19-10-2018.]","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"As razões recursais não conseguem infirmar esses fundamentos. Conforme consignado, a jurisprudência pacífica da CORTE é no sentido de que lei municipal que fixa distância mínima para a instalações de novos postos de combustíveis, por motivo de segurança, não ofende os princípios constitucionais da livre iniciativa e da livre concorrência (RE 199101, Relator Min. SEPÚLVEDA PERTENCE, Primeira Turma, DJ 30/9/2005; RE 204.187, Relatora Min. ELLEN GRACIE, Segunda Turma, DJ 2/4/2004). Por esse motivo, não há estrita aderência entre o ato impugnado e a SV 49.","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"[ Rcl 30.986 AgR , voto do rel. min. Alexandre de Moraes , 1ª T, j. 21-9-2018, DJE 205 de 27-9-2018.]","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"Regulamentação por lei municipal de instalação de estabelecimento comercial","deleted":false}],"heading":false},{"page":200,"runs":[{"text":"Procede o inconformismo. Ao se impedir a instalação de posto de combustíveis tendo em conta o critério da distância entre estabelecimentos congêneres, acabou desrespeitado o verbete vinculante 49 da Súmula do Supremo. (...) Consoante se observa, o verbete encerra entendimento, em tese e vinculante, no sentido da insubsistência de norma local voltada a restringir a abertura de comércios de idêntica atividade considerado o critério geográfico. Nele não há - certo ou errado, descabe, nesta via, perquirir - ressalva, inclusive no tocante a possível necessidade de tutelar-se a segurança de munícipes. É impróprio, contudo, ante os termos do pedido formulado, assentar, de forma geral e abstrata, a suspensão da eficácia do dispositivo de lei local e determinar a imediata concessão da licença requerida. Mostra-se inadequada a atuação do Judiciário em substituição à do","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"administrador e a utilização da reclamação como mecanismo de controle abstrato de norma, porquanto o alcance está limitado ao caso concreto. 3. Julgo parcialmente procedente o pleito formulado nesta reclamação para cassar o ato administrativo praticado no pedido de construção de comércio (...) determinando seja o pleito analisado independentemente do previsto no artigo 21, inciso IV, da Lei municipal 709/1993, com a redação conferida pela Lei 2.127/2017","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"[ Rcl 31.252 , rel. min. Marco Aurélio , dec. monocrática, j. 29-10-2018, DJE 233 de 5-11-2018.]","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"O ato administrativo reclamado, prima facie , não proíbe a instalação do empreendimento da reclamante na mesma área onde já estão instalados outros empreendimentos que desempenham a mesma atividade. Isso porque, de acordo com o parecer jurídico que serve de fundamento para a decisão reclamada, “a área que se pretende ver licenciada para extração de areia é considerada pela legislação municipal (Plano Diretor, Leis 16/22 de 2011) como passível de implantação de condomínios e loteamentos visando exploração de turismo e lazer, impedida a exploração de qualquer outro empreendimento”. Ou seja, de acordo com a decisão reclamada, não haveria, na área objeto do pedido administrativo da reclamante, “estabelecimentos comerciais do mesmo ramo” de atividade, tal como exigido para a aplicação da Súmula Vinculante 49. (...) A atividade econômica da reclamante, por outro lado, não prescinde de licença administrativa, como torna evidente a própria decisão reclamada. Assim, não é possível asseverar, no atual momento processual, ter havido violação à ratio decidendi da Súmula Vinculante 49 (...). (...) em um juízo preliminar, não haveria restrição legal ao exercício das atividades pretendidas pela reclamante no mesmo local onde estão instalados os empreendimentos de mesma natureza, desde que preenchidos determinados requisitos, os quais não foram objeto da Súmula Vinculante 49. (...) Diante do exposto, indefiro o pedido liminar.","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"[ Rcl 25.482 MC , rel. min. Roberto Barroso , dec. monocrática, j. 24-11-2016, DJE 254 de 30-11-2016.]","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":201,"runs":[{"text":"● A Súmula Vinculante 49 resultou da conversão da Súmula 646.","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"Data de publicação do enunciado: DJE de 23-6-2015.","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":201,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"50","number":"50","scope":"main","kind":"vinculante","sectionId":"grupo-4","page":202,"endPage":203,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2604","paragraphs":[{"page":202,"runs":[{"text":"Norma legal que altera o prazo de recolhimento de obrigação tributária não se sujeita ao princípio da anterioridade.","deleted":false}]}],"notes":[{"page":202,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":202,"runs":[{"text":"(...) para mim, a questão posta não envolve criação ou aumento de tributo, e sim deslocamento do prazo de recolhimento da respectiva taxação. O art. 195, § 6º, da Constituição Federal criou a anterioridade mitigada, todavia o Tribunal tem entendido que, na hipótese apenas de mudança de prazo para efeito de recolhimento do tributo, não se exige a referida anterioridade.","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"[ RE 240.266 , rel. min. Marco Aurélio , voto do red. p/ o ac. min. Maurício Corrêa , P, j. 22-9-1999, DJ de 3-3-2000.]","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"O postulado da anterioridade em matéria tributária, além de traduzir insuperável limitação jurídica ao poder de tributar do Estado, representa expressiva garantia de caráter individual que compõe o estatuto constitucional do contribuinte ( RTJ 151/755-756), qualificando-se, por isso mesmo - consoante adverte o magistério jurisprudencial desta Suprema Corte ( RTJ 83/501) -, como instrumento destinado a impedir que o sujeito passivo da obrigação fiscal venha a ser surpreendido pela imediata aplicabilidade e incidência de leis que tenham (a) instituído tributos novos ou (b) majorado espécies tributárias já existentes. É por essa razão que o postulado da anterioridade deixa de incidir, quando o poder público, em vez de criar tributo novo ou de majorar tributos já existentes, edita legislação destinada a tornar menos oneroso, para o contribuinte, o gravame tributário, conforme decidiu o Supremo Tribunal Federal (...).","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"[ RE 240.266 , rel. min. Marco Aurélio , red. p/ o ac. min. Maurício Corrêa , voto do min. Celso de Mello , P, j. 22-9-1999, DJ de 3-3-2000.]","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"A matéria a ser examinada no recurso diz respeito unicamente à aplicação do princípio constitucional da anterioridade, fixado no art. 195, § 6º, da Constituição. (...) A exigência da contribuição, assim, só se dará após decorrido o prazo estabelecido pela norma. Cumpre saber se a alteração de prazo de recolhimento da exação fiscal, imposta pela legislação impugnada, estaria abrangida no conceito de modificação inserto no mencionado artigo. Impõe-se a negativa. Em realidade, nem toda alteração introduzida, por lei, no sistema de exigência dessas contribuições há de ser entendida como sinônimo da modificação. Não seria admissível que se aguardasse o protraimento da eficácia da regra legislativa, simplesmente por haver alterado a data de pagamento da obrigação tributária, sem qualquer outra repercussão.","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"[ RE 209.386 , voto do rel. min. Ilmar Galvão , 1ª T, j. 5-12-1997, DJ de 27-2-1998.]","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":202,"runs":[{"text":"Incabível nova contagem a partir da conversão da medida provisória em lei, sem alteração substancial do texto anterior","deleted":false}],"heading":false},{"page":202,"runs":[{"text":"3. Ora, considerando que a anterioridade (anual ou nonagesimal) é uma limitação constitucional ao poder de tributar, voltada à proteção do contribuinte, no sentido de não dar eficácia imediata às alterações legais que aumentam a carga tributária, é comezinha a noção de que, quando as alterações legislativas não promovem esse impacto de assoberbar a carga tributária, a norma de anterioridade não se faz incidente. Exemplo conhecido é o do enunciado nº 50 da Súmula Vinculante do STF, no qual foi consignado que (...). 4. Logo, havendo a redução de alíquotas previstas originalmente na medida provisória em comparação ao texto","deleted":false}],"heading":false},{"page":203,"runs":[{"text":"sobrevindo de sua conversão em lei, é desenganada a conclusão de que não se sujeita a redação superveniente ao princípio da anterioridade.","deleted":false}],"heading":false},{"page":203,"runs":[{"text":"[ ARE 1.468.509 AgR , rel. min. André Mendonça , 2ª T, j. 4-3-2024, DJE s/n de 23-4-2024.]","deleted":false}],"heading":false},{"page":203,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":203,"runs":[{"text":"● A Súmula Vinculante 50 resultou da conversão da Súmula 669.","deleted":false}],"heading":false},{"page":203,"runs":[{"text":"Data de publicação do enunciado: DJE de 23-6-2015.","deleted":false}],"heading":false},{"page":203,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":203,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"51","number":"51","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":204,"endPage":205,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2607","paragraphs":[{"page":204,"runs":[{"text":"O reajuste de 28,86%, concedido aos servidores militares pelas Leis 8622/1993 e 8627/1993, estende-se aos servidores civis do poder executivo, observadas as eventuais compensações decorrentes dos reajustes diferenciados concedidos pelos mesmos diplomas legais.","deleted":false}]}],"notes":[{"page":204,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":204,"runs":[{"text":"Ao julgar o RMS 22.307, o Plenário desta Corte decidiu, por maioria, que as Leis 8.622/1993 e 8.627/1993 concederam revisão geral de vencimentos aos servidores públicos, da ordem de 28,86%, nos termos do inciso X do art. 37 da Carta de Outubro (redação anterior à EC 19/1998). Posteriormente, ao apreciar os embargos de declaração opostos (RMS 22.307 ED), entendeu, também por maioria, que deveriam ser compensados, em cada caso, os índices eventualmente concedidos pela própria Lei 8.627/1993. Tal decisão autoriza concluir que a citada revisão, sendo geral, na forma do dispositivo constitucional em apreço (cuja redação originária não comportava distinção entre civis e militares), é devida, por igual, aos servidores militares, também com a mencionada compensação.","deleted":false}],"heading":false},{"page":204,"runs":[{"text":"[ RE 445.018 AgR , rel. min. Ayres Britto , 1ª T, j. 29-6-2005, DJ de 21-10-2005.]","deleted":false}],"heading":false},{"page":204,"runs":[{"text":"(...) para chegar-se ao índice de 28,86%, que foi tido como correspondente ao reajuste geral concedido a todo o funcionalismo, civil e militar, e, como tal, aplicado aos servidores do Poder Legislativo, do Poder Judiciário, dos servidores do Tribunal de Contas da União e do Ministério Público Federal, considerou-se a média percentual resultante da adequação dos postos e gradações dos servidores militares. Melhor exame da Lei 8.627/1993, entretanto, revela que não apenas os servidores militares resultaram por ela beneficiados, por meio da “adequação dos postos e graduações”, mas também nada menos que vinte categorias de servidores civis, contemplados pelo eufêmico “reposicionamento” previsto em seus arts. 1º e 3º, entre elas a dos “servidores do Plano de Classificação de Cargos das Leis 5.645/1970 e 6.550/1978”. Assim, conforme enfatizou o em. ministro Octavio Gallotti, quando do julgamento ora embargado, “não houve (...) uma singela extensão, a servidores civis, de valores de soldos de militares”, o que a jurisprudência do STF não tolerava, mas a extensão de reajuste concedido aos militares e a numerosíssimas carreiras do funcionalismo civil. Trata-se de circunstância que não se pode deixar de ter em conta, quando se cuida de estender o percentual de 28,86% às categorias funcionais que restaram excluídas da revisão geral.","deleted":false}],"heading":false},{"page":204,"runs":[{"text":"[ RMS 22.307 ED , rel. min. Marco Aurélio , voto do red. p/ o ac. min. Ilmar Galvão , P, j. 11-3-1998, DJ de 26-6-1998.]","deleted":false}],"heading":false},{"page":204,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":204,"runs":[{"text":"● Estende-se o reajuste de 28,86% aos servidores militares contemplados com índices inferiores pelas Leis 8.622/1993 e 8.627/1993, já que se trata de revisão geral dos servidores públicos, observadas, entretanto, as compensações dos reajustes concedidos e a limitação temporal da Medida Provisória 2.131/2000, atual Medida Provisória 2.215-10/2001.","deleted":false}],"heading":false},{"page":204,"runs":[{"text":"[Tese definida no RE 584.313 QO-RG , rel. min. Gilmar Mendes , P, j. 6-10-2010, DJE 200 de 22-10-2010, Tema 340.]","deleted":false}],"heading":false},{"page":204,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":204,"runs":[{"text":"Incorporação do índice de 28,86% à remuneração de servidor em razão da modificação do regime jurídico de vencimentos","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"No caso concreto, o Tribunal de Contas da União, por meio do Acórdão 2.756/2012, assentou que a parcela correspondente ao percentual de 28,86%, objeto da decisão proferida no processo 94.0002414-2, da 3ª Vara Federal da Seção Judiciária do Estado de Mato Grosso, transitada em julgado em 6-3-1996, foi ulteriormente absorvida por reestruturações remuneratórias na carreira da impetrante, em especial a decorrente da MP 1.704-1, de 30-7-1998. A respeito desse índice específico, a Corte editou a Súmula Vinculante 51 (...). Como visto, o Tribunal de Contas da União expressamente anotou no acórdão impugnado que o índice de 28,86% concedido à impetrante pela decisão judicial foi compensado pela modificação do regime jurídico de vencimentos. Assim, não se revela cabível regular a atuação do Tribunal de Contas da União, ao afastar a aplicação continuada de índices, quando demonstradas mudanças significativas na estrutura salarial do regime remuneratório a que se submete o servidor, pois estar-se-ia reconhecendo a existência de direito adquirido a regime de vencimentos, contrariando-se expressamente jurisprudência sedimentada deste Supremo Tribunal Federal. (...) concedo parcialmente a segurança, apenas para afastar a devolução dos valores percebidos pela impetrante até a data desta decisão, ficando prejudicado o agravo regimental interposto pela União.","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"[ MS 31.543 , rel. min. Edson Fachin , dec. monocrática, j. 16-6-2016, DJE 128 de 21-6-2016.]","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"Obrigatoriedade da aplicação da Súmula Vinculante 51 na fase de execução","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"3. A jurisprudência do STF, consolidada na Súmula 672 e na Súmula Vinculante 51, e reafirmada no RE 584.313 (RG), é no sentido de que o reajuste de 28,86% estende-se aos servidores civis, com compensação dos reajustes já recebidos, sendo obrigatória sua observância inclusive na execução.","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"[ ARE 1.127.074 , rel. min. Gilmar Mendes , 2ª T, j. 10-6-2025, DJE s/n 18-6-2025.]","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":205,"runs":[{"text":"● A Súmula Vinculante 51 resultou da conversão da Súmula 672.","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 340, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"Data de publicação do enunciado: DJE de 23-6-2015.","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":205,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"52","number":"52","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":206,"endPage":208,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2610","paragraphs":[{"page":206,"runs":[{"text":"Ainda quando alugado a terceiros, permanece imune ao IPTU o imóvel pertencente a qualquer das entidades referidas pelo art. 150, VI, \"c\", da Constituição Federal, desde que o valor dos aluguéis seja aplicado nas atividades para as quais tais entidades foram constituídas.","deleted":false}]}],"notes":[{"page":206,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":206,"runs":[{"text":"O Tribunal de origem não divergiu da orientação da Corte no sentido de que a regra imunizante contida no art. 150, VI, c, da CF/1988 afasta a incidência do IPTU sobre os imóveis de propriedade das instituições de assistência social sem fins lucrativos, mesmo que alugados a terceiros, desde que o valor dos aluguéis seja aplicado nas suas atividades essenciais (Súmula 724/STF). 2. O acórdão recorrido concluiu pelo enquadramento da instituição como entidade de assistência social sem fins lucrativos, a partir da análise dos requisitos previstos no art. 14 do CTN/1966. Para ultrapassar o entendimento consagrado pelo Tribunal a quo, necessário seria o reexame dos fatos e das provas e da legislação infraconstitucional de regência. Precedentes. 3. A presunção de que o imóvel ou as rendas da entidade assistencial reconhecidamente imune estão afetados às suas finalidades institucionais milita em favor da entidade. Cabe ao Fisco elidir a presunção, mediante a constituição de prova em contrário.","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"[ ARE 760.876 AgR , rel. min. Dias Toffoli , 1ª T, j. 4-2-2014, DJE 65 de 2-4-2014.]","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":206,"runs":[{"text":"● A imunidade tributária prevista no art. 150, VI, c, da CF/88 aplica-se aos bens imóveis, temporariamente ociosos, de propriedade das instituições de educação e de assistência social sem fins lucrativos que atendam os requisitos legais.","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"[Tese definida no RE 767.332 RG , rel. min. Gilmar Mendes , P, j. 31-10-2013, DJE 230 de 22-11-2013, Tema 693.]","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":206,"runs":[{"text":"Imóvel destinado à residência de ministro religioso","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"O fato de os imóveis estarem sendo utilizados como escritório e residência de membros da entidade não afasta a imunidade prevista no art. 150, VI, c , § 4º, da Constituição Federal.","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"[ ARE 895.972 AgR , rel. min. Roberto Barroso , 1ª T, j. 2-2-2016, DJE 34 de 24-2-2016.]","deleted":false}],"heading":false},{"page":206,"runs":[{"text":"Conforme destaquei na decisão agravada, a jurisprudência desta Corte fixou orientação no sentido de que a imunidade tributária prevista no art. 150, VI, b , da Constituição abrange não apenas os locais destinados à celebração de cultos, mas se estende, também, a todos os imóveis pertencentes à entidade religiosa e destinados ao atendimento de suas finalidades essenciais, ainda que alugados a terceiros. Nesse sentido, transcrevo a Súmula 724 do STF (...). Dessa forma, o argumento sustentado pelo recorrente, no sentido de que seria possível a incidência de IPTU sobre o imóvel destinado à residência de pastores, dado que a imunidade discutida abarcaria apenas os locais destinados à realização de atos religiosos, não encontra amparo no entendimento firmado por este Tribunal a respeito do tema. Com efeito, se a circunstância de a recorrida alugar o imóvel de sua propriedade a terceiro, sem qualquer vínculo com ela, não afasta a imunidade sob exame, não há qualquer razão que justifique o óbice ao gozo do benefício na hipótese de o bem em questão ser destinado à residência dos seus ministros religiosos.","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"[ ARE 694.453 AgR , rel. min. Ricardo Lewandowski , 2ª T, j. 25-6-2013, DJE 156 de 12-8-2013.]","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"Recursos relativos aos aluguéis do imóvel destinados à manutenção do objetivo social da fundação e imunidade de IPTU","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"O Tribunal de origem, com base nos fatos da causa, reconheceu a imunidade em relação ao IPTU sobre o imóvel alugado à entidade sem fins lucrativos. (...) Sobre a matéria, a jurisprudência do SUPREMO TRIBUNAL FEDERAL, é firme no sentido de que há presunção que milita em favor das entidades beneficiadas no tocante à regra imunizante contida na supracitada norma constitucional. Desse modo, cabe ao Fisco afastá-la com a finalidade de cobrar os impostos que lhe são devidos. (...) O acórdão impugnado não divergiu desse entendimento, razão pela qual não merece ser reformado.","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"[ ARE 1.129.395 , rel. min. Alexandre de Moraes , dec. monocrática, j. 7-5-2018, DJE 92 de 14-5-2018.]","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"A irresignação não merece prosperar. Verifico que o Tribunal a quo não divergiu do entendimento do Supremo Tribunal Federal quanto ao ponto referente ao instituto da imunidade ante os imóveis alugados (...). Ademais, para acolher a pretensão do recorrente acerca da análise da relação do patrimônio com as finalidades essenciais da entidade e do preenchimento dos demais requisitos para fim de configuração da imunidade tributária, seria necessário o reexame do conjunto fático-probatório dos autos, bem como da legislação infraconstitucional pertinente, o que é inviável em sede de apelo extremo, a teor do enunciado da Súmula 279 desta Corte. (...) Por fim, no entendimento atual da Corte, a presun- ção de que o imóvel ou as rendas da entidade estão afetados às suas finalidades institucionais milita em favor da entidade. Cabe ao Fisco o ônus de elidir a presunção, mediante a constituição de prova em contrário. (...) Ante o exposto, nos termos do art. 21, § 1º, do Regimento Interno do Supremo Tribunal Federal, nego seguimento ao recurso.","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"[ ARE 987.801 , rel. min. Dias Toffoli , dec. monocrática, j. 25-8-2016, DJE 194 de 12-9-2016.]","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"AGRAVO REGIMENTAL EM RECURSO EXTRAORDINÁRIO COM AGRAVO. DIREITO TRIBUTÁRIO. IPTU. IMUNIDADE TRIBUTÁRIA. INSTITUIÇÃO DE ENSINO. FUNDAÇÃO SEM FINS LUCRATIVOS. REQUISITOS. 1. A imunidade conferida às entidades de educação sem fins lucrativos, prevista no art. 150, VI, c , da Constituição Federal, é de natureza subjetiva e incide sobre quaisquer bens, patrimônio ou serviços dessas instituições, desde que vinculados às suas atividades essenciais. Precedente: RE 767.332 RG, de relatoria do ministro Gilmar Mendes, DJE 22-11-2013. 2. Ainda quando alugado a terceiros, permanece imune ao IPTU o imóvel pertencente a qualquer das entidades referidas pelo art. 150, VI, c , da Constituição, desde que o valor dos aluguéis seja aplicado nas atividades essenciais de tais entidades. Súmula 724 do STF. 3. Eventual divergência ao entendimento adotado pelo Tribunal de origem, em relação à aplicação de recursos nas atividades essenciais das entidades referidas no art. 150, IV, c, da Constituição da República, demandaria o reexame de fatos e provas. Súmula 279 do STF. 4. Agravo regimental a que se nega provimento.","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"[ ARE 933.174 AgR , rel. min. Edson Fachin , 1ª T, j. 31-5-2016, DJE 122 de 14-6-2016.]","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"A irresignação merece prosperar. Verifico que o Supremo Tribunal Federal firmou entendimento no sentido de que a imunidade fixada no art. 150, VI, c, da CF/88 alcança os imóveis das entidades de assistência social sem fins lucrativos, mesmo que esses bens sejam alugados para terceiros. Incidência do enunciado da Súmula 724 desta Corte. (...) Ademais, verifico que o Tribunal a quo consignou que compete à entidade de assistência social a comprovação de que o imóvel objeto da presente lide e sua renda advinda do aluguel estejam vinculados às suas finalidades essenciais. Todavia, a instância de origem contrariou o entendimento desta Corte firmado no sentido de que a presunção de que o imóvel ou as rendas da entidade assistencial estão afetados às suas finalidades institucionais milita em favor da entidade. Cabe ao Fisco o ônus de elidir a presunção, mediante a constituição de prova em contrário. (...) Ante o exposto, conheço do agravo e dou provimento ao recurso extraordinário para restabelecer a sentença de primeiro grau, inclusive quanto aos ônus sucumbenciais.","deleted":false}],"heading":false},{"page":207,"runs":[{"text":"[ ARE 875.619 , rel. min. Dias Toffoli , dec. monocrática, j. 2-12-2015, DJE 10 de 1º-2-2016.]","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"As razões recursais não merecem prosperar. Isso porque a jurisprudência desta Corte Suprema firmou-se no sentido de que a verificação do preenchimento dos requisitos legais e constitucionais ensejadores da concessão da imunidade tributária demanda a reapreciação dos fatos e provas constantes dos autos, o que inviabiliza o processamento do recurso extraordinário, nos termos do Enunciado 279 da Súmula do STF. (...) Ademais, observa-se que o acórdão recorrido reconheceu a imunidade tributária nos termos do que estabelece a Súmula 724 do STF (...). Ante o exposto, conheço do presente agravo para negar-lhe provimento (art. 544, § 4º, II, a , do CPC).","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"[ ARE 917.485 , rel. min. Gilmar Mendes , dec. monocrática, j. 16-10-2015, DJE 213 de 26-10-2015.]","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"(...) o acórdão recorrido encontra-se em consonância com a pacífica jurisprudência do Supremo Tribunal Federal, consubstanciada na Súmula Vinculante 52: (...). No caso dos autos, o Tribunal de origem consignou que a recorrida aplica os recursos relativos aos aluguéis do imóvel tributado tão somente na manutenção de seu objetivo social.","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"[ ARE 891.596 , rel. min. Teori Zavascki , dec. monocrática, j. 16-9-2015, DJE 188 de 22-9-2015.]","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":208,"runs":[{"text":"● A Súmula Vinculante 52 resultou, com ajustes em sua redação, da conversão da Súmula 724.","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 693, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"Data de publicação do enunciado: DJE de 22-6-2015.","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":208,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"53","number":"53","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":209,"endPage":211,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=2613","paragraphs":[{"page":209,"runs":[{"text":"A competência da Justiça do Trabalho prevista no art. 114, VIII, da Constituição Federal alcança a execução de ofício das contribuições previdenciárias relativas ao objeto da condenação constante das sentenças que proferir e acordos por ela homologados.","deleted":false}]}],"notes":[{"page":209,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":209,"runs":[{"text":"Ora, o que se executa não é a contribuição social, mas o título que a corporifica ou representa, assim como o que se executa no juízo comum não é o crédito representado no cheque, mas o próprio cheque. O requisito primordial de toda execução é a existência de um título, judicial ou extrajudicial. No caso da contribuição social atrelada ao salário objeto da condenação, é fácil perceber que o título que a corporifica é a própria sentença cuja execução, uma vez que contém o comando para o pagamento do salário, envolve o cumprimento do dever legal de retenção das parcelas devidas ao sistema previdenciário. De outro lado, entender possível a execução de contribuição social desvinculada de qualquer condenação ou transação seria consentir em uma execução sem título executivo, já que a sentença de reconhecimento do vínculo, de carga predominantemente declaratória, não comporta execução que origine o seu recolhimento. No caso, a decisão trabalhista que não dispõe sobre o pagamento de salários, mas apenas se limita a reconhecer a existência do vínculo não constitui título executivo judicial no que se refere ao crédito de contribuições previdenciárias (...).","deleted":false}],"heading":false},{"page":209,"runs":[{"text":"[ RE 569.056 , voto do rel. min. Menezes Direito , P, j. 11-9-2008, DJE 236 de 12-12-2008.]","deleted":false}],"heading":false},{"page":209,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":209,"runs":[{"text":"● A competência da Justiça do Trabalho prevista no art. 114, VIII, da Constituição Federal alcança somente a execução das contribuições previdenciárias relativas ao objeto da condenação constante das sentenças que proferir, não abrangida a execução de contribuições previdenciárias atinentes ao vínculo de trabalho reconhecido na decisão, mas sem condenação ou acordo quanto ao pagamento das verbas salariais que lhe possam servir como base de cálculo.","deleted":false}],"heading":false},{"page":209,"runs":[{"text":"[Tese definida no RE 569.056 , rel. min. Menezes Direito , P, j. 11-9-2008, DJE 236 de 12-12-2008, Tema 36.]","deleted":false}],"heading":false},{"page":209,"runs":[{"text":"2. A presente reclamação foi ajuizada, após esgotadas as instâncias ordinárias de impugnação, em face de decisão do Juízo (...), na qual se afirmou que o termo inicial da incidência de juros de mora e correção monetária sobre contribuições previdenciárias decorrentes de condenação trabalhista é a data da prestação de serviço. (...) 3. O reclamante alegou afronta à decisão proferida pelo STF no RE 569.056/PR, (...). 4. Como afirmado na decisão agravada, no julgamento do RE 569.056/PR, paradigma do tema 36 da repercussão geral, (...), que resultou na edição da Súmula Vinculante 53, esta Corte delimitou o alcance da competência prevista no art. 114, VIII, da Constituição. 5. Assim, a tese firmada no paradigma invocado não guarda reclamação de estrita aderência com o debate acerca do termo inicial da incidência de juros de mora e correção monetária sobre crédito de contribuições previdenciárias que são objeto de execução em razão de condenação trabalhista. É dizer, a questão incidental decidida pelo juízo reclamado é estranha à tese firmada no julgamento do tema 36 da repercussão geral.","deleted":false}],"heading":false},{"page":209,"runs":[{"text":"[ Rcl 26.671 AgR , voto do rel. min. Roberto Barroso , 1ª T, j. 20-2-2018, DJE 39 de 1º-3-2018.]","deleted":false}],"heading":false},{"page":209,"runs":[{"text":"No que concerne à suposta competência da Justiça do Trabalho para o lançamento das contribuições, a irresignação também não merece acolhida. O Supremo Tribunal Federal editou a Súmula Vinculante 53 para fixar o entendimento de que a competência da Justiça do Trabalho prevista no art. 114, VIII, da Constituição alcança apenas a execução das contribuições previdenciárias relativas ao objeto da condenação constante das","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"sentenças que proferir e acordos por ela homologados. (...) Diferentemente, nas hipóteses não abrangidas por sentenças condenatórias proferidas pela Justiça trabalhista, a competência para o lançamento das contribuições previdenciárias, atualmente, é da Secretaria da Receita Federal.","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"[ ARE 1.031.969 , rel. min. Roberto Barroso , dec. monocrática, j. 24-4-2017, DJE 89 de 2-5-2017.]","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":210,"runs":[{"text":"Competência da Justiça do Trabalho para a execução de ofício das contribuições previdenciárias devidas","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"A Súmula Vinculante 53 repele a execução pela Justiça Laboral de contribuições previdenciárias relativas a rubricas que não foram objeto de discussão em sentenças proferidas ou em acordos homologados por si homologados. (...) No caso dos autos, o acórdão reclamado ratificou a sentença de primeiro grau que condenou o empregador ao recolhimento de todos os encargos previdenciários (...). Não há falar, pois, em violação à Súmula Vinculante 53, na medida em que o quadro fático do caso concreto é exatamente aquele em que se autoriza a execução das contribuições pela Justiça do Trabalho. Em síntese, não há afronta à SV 53, senão observância.","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"[ Rcl 27.447 ED , rel. min. Edson Fachin , dec. monocrática, j. 17-1-2019, DJE 19 de 1º-2-2019.]","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"Verifico, então, que assiste razão à autoridade suscitante do presente conflito negativo de competência, eis que o entendimento emanado do Juízo (...) está em consonância com o enunciado da Súmula Vinculante 53, (...). É essa, precisamente, a hipótese destes autos, em que a União interpôs recurso ordinário buscando o reconhecimento da competência da Justiça do Trabalho para executar as contribuições previdenciárias devidas, concernentes ao período do vínculo empregatício reconhecido pelo Juízo (...). Diante do exposto, com base no art. 955, parágrafo único, inciso I, do Código de Processo Civil, conheço do presente conflito, reconhecendo a competência da Justiça do Trabalho para a execução de ofício das contribuições previdenciárias devidas, relativas ao acordo homologado pelo Juízo da Vara do Trabalho (...), determinando, por conseguinte, a remessa dos presentes autos ao Tribunal Superior do Trabalho.","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"[ CC 7.984 , rel. min. Alexandre de Moraes , dec. monocrática, j. 26-10-2017, DJE 250 de 31-10-2017.]","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"Comissão reconhecida em sentença trabalhista e recolhimento de encargos previdenciários","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"O acórdão reclamado, que ratificou a sentença, reconheceu que o empregado recebia comissão - que tem natureza de verba salarial e, justamente porque já recebia, não houve condenação a pagamento de tal verba. Registre-se, entretanto, que a sentença condenou o empregador ao recolhimento de todos os encargos previdenciários, inclusive aqueles incidentes sobre as comissões (e-doc 6). A Súmula Vinculante 53, por sua vez, repele a execução de contribuições previdenciárias relativas a rubricas que não foram objeto de discussão em sentenças proferidas ou em acordos homologados pela Justiça do Trabalho. No presente caso, como já mencionado, as comissões pagas ao empregado foram reconhecidas como verbas salariais a ele devidas e houve condenação ao pagamento das contribuições previdenciárias. Portanto, a matéria que deu origem à Súmula Vinculante 53 é estranha àquela objeto do julgamento que ora se impugna, devendo, pois, ser mantida a decisão agravada.","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"[ Rcl 21.987 AgR , voto do rel. min. Edson Fachin , 1ª T, j. 23-2-2016, DJE 47 de 14-3-2016.]","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"Decisão judicial que se limita a declarar a existência de vínculo laboral não viola a Súmula Vinculante 53","deleted":false}],"heading":false},{"page":210,"runs":[{"text":"Cabe asseverar que o Supremo assentou, por ocasião do julgamento do precedente que deu origem à Súmula Vinculante 53, que o requisito primordial de toda execução é a existência de um título, judicial ou extrajudicial, e que “a decisão trabalhista que não dispõe sobre o pagamento de salários, mas apenas se limita a reconhecer a existência do vínculo, não constitui título executivo judicial no que se refere ao crédito de contribuições previdenciárias” (excerto do voto do ministro Menezes Direito, no RE 569.056). Nesse contexto, tratando-se de","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"título executivo que prevê apenas pagamento de verbas indenizatórias e reconhecimento de vínculo, não há crédito de contribuições previdenciárias a serem executadas de ofício pelo juiz e, portanto, inexiste a alegada desobediência à Súmula Vinculante 53.","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"[ Rcl 21.860 MC , rel. min. Edson Fachin , dec. monocrática, j. 3-11-2015, DJE 220 de 5-11-2015.]","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"Impossibilidade de execução de ofício de título executivo que prevê apenas pagamento de verbas indenizatórias e reconhecimento de vínculo empregatício","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"Consoante fundamenta o magistrado no despacho cuja revogação se requer, o indeferimento da execução das contribuições previdenciárias não se deu pelo reconhecimento da incompetência do juízo, mas, sim, pela inexistência de título executivo. Consta da decisão que o acordo firmado entre as partes não previu verbas remuneratórias, sobre as quais incidiria contribuição previdenciária, mas somente reconhecimento de vínculo e verbas indenizatórias, cuja incidência de contribuição é vedada pela legislação pertinente. (...) Nesse contexto, tratando-se de título executivo que prevê apenas pagamento de verbas indenizatórias e reconhecimento de vínculo, não há crédito de contribuições previdenciárias a serem executadas de ofício pelo juiz e, portanto, inexiste a alegada desobediência à Súmula Vinculante 53.","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"[ Rcl 21.860 MC , rel. min. Edson Fachin , dec. monocrática, j. 3-11-2015, DJE 220 de 5-11-2015.]","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":211,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 36, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"Data de publicação do enunciado: DJE de 23-6-2015.","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":211,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"54","number":"54","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":212,"endPage":213,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=3009","paragraphs":[{"page":212,"runs":[{"text":"A medida provisória não apreciada pelo congresso nacional podia, até a Emenda Constitucional 32/2001, ser reeditada dentro do seu prazo de eficácia de trinta dias, mantidos os efeitos de lei desde a primeira edição.","deleted":false}]}],"notes":[{"page":212,"runs":[{"text":"Precedentes representativos","deleted":false}],"heading":true},{"page":212,"runs":[{"text":"Ao apreciar o RE 232.896/PA, relator o ministro Carlos Velloso, DJ de 1º-10-1999, o Pleno desta Suprema Corte pacificou entendimento no sentido de que, à luz da redação original do art. 62 da CF/1988, não perde eficácia a medida provisória não apreciada pelo Congresso Nacional que é reeditada, por meio de nova medida provisória, dentro de seu prazo de validade de trinta dias. No particular, o termo a ser considerado é o da reedição ou da conversão em lei, conforme inteligência do parágrafo único do art. 62 da CF/1988, na redação anterior à EC 32/2001, como bem observou o ministro Sepúlveda Pertence ao julgar o AI 321.629/MG, DJ de 6-10-2006 (...).","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"[ RE 592.315 AgR , voto do rel. min. Dias Toffoli , 1ª T, j. 8-2-2011, DJE 66 de 7-4-2011.]","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"A medida provisória não apreciada pelo Congresso Nacional pode ser reeditada dentro do seu prazo de validade de trinta dias, mantendo a eficácia de lei desde a sua primeira edição.","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"[ RE 231.630 AgR , rel. min. Néri da Silveira , 2ª T, j. 24-8-1999, DJ de 24-9-1999.]","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"Não perde eficácia a medida provisória, com força de lei, não apreciada pelo Congresso Nacional, mas reeditada, por meio de outro provimento da mesma espécie, dentro de seu prazo de validade de trinta dias.","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"[ ADI 1.612 , rel. min. Carlos Velloso , P, j. 6-5-1999, DJ de 18-6-1999.]","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":212,"runs":[{"text":"Constitucionalidade de reedições sucessivas de medidas provisórias anteriores à EC 32/2001","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"[...] 2. A Lei 6.903/1981, recepcionada pela Carta de 1988 (MS 25064, Rel. Min. Ayres Britto; e MS 24805, Rel. Min. Gilmar Mendes), respaldava a aposentadoria estatutária tout court de juiz classista. Esse diploma legal, contudo, deixou de ter eficácia a partir da publicação, em 14.10.1996, da Medida Provisória 1.523/1996, cujo art. 3º dispunha: “Art. 3º Os magistrados classistas temporários da Justiça do Trabalho e os magistrados da Justiça Eleitoral nomeados na forma dos incisos II do art. 119 e III do art. 120 da Constituição Federal serão aposentados de acordo com as normas estabelecidas pela legislação previdenciária a que estavam submetidos antes da investidura na magistratura, mantida a referida vinculação previdenciária durante o exercício do mandato. Parágrafo único. O aposentado de qualquer regime previdenciário que exercer a magistratura nos termos deste artigo vincula-se, obrigatoriamente, ao Regime Geral de Previdência Social - RGPS.” 3. O mencionado dispositivo da Medida Provisória 1.523/1996 foi sucessivamente reeditado, sempre com observância do trintídio previsto na redação original do art. 62, parágrafo único, da Magna Carta, até a sua conversão no art. 5º da Lei 9.528/1997. (...) 7. Ante o exposto, com amparo no art. 205 do RISTF, denego a segurança.","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"[ MS 25.970 , rel. min. Rosa Weber , dec. monocrática, j. 7-4-2017, DJE 75 de 17-4-2017.]","deleted":false}],"heading":false},{"page":212,"runs":[{"text":"Trata-se de recurso extraordinário interposto em mandado de segurança visando afastar a exigência de cobrança da Taxa de Saúde Suplementar. (...) a parte recorrente aponta, com base no art. 102, III, a , da Constituição Federal, violação aos seguintes dispositivos constitucionais: (...) (e) art. 150, III, b , visto que “a exigência da TSS no mesmo exercício em que foi instituída revela-se maculada de inconstitucionalidade posto","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"ser tal cobrança expressamente proibida pela Carta constitucionalmente (...), ao determinar a observância da anterioridade” (...). 5. Por fim, no tocante à ofensa ao princípio da anterioridade tributária, o recurso extraordinário também não merece ser provido. Isso porque o STF possui o entendimento de que “a medida provisória não apreciada pelo Congresso Nacional podia, até a EC 32/2001, ser reeditada dentro do seu prazo de eficácia de trinta dias, mantidos os efeitos de lei desde a primeira edição” (Súmula 651). Assim, tendo a MP 1.928/1999 sido reeditada nas MP 2.003/2000 e MP 2.012/2000, sendo esta última convertida na Lei 9.961/2000, o termo inicial do prazo da anterioridade tributária será a data da publicação da medida provisória original.","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"[ RE 929.954 , rel. min. Teori Zavascki , dec. monocrática, j. 12-9-2016, DJE 198 de 16-9-2016.]","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"O recurso extraordinário é inadmissível. O Tribunal de origem manteve os termos da sentença no sentido de que a Lei 8.237/1991 estava expressamente revogada pela MP 2.251/2001 quando o recorrente reuniu os requisitos necessários para a aposentadoria, de modo que não faz jus ao recebimento de indenização de transporte e a perceber remuneração equivalente ao último posto ou graduação que possuía na ativa. (...) Em sede de embargos de declaração, esclareceu, ainda, que não há qualquer inconstitucionalidade nas reedições sucessivas da medida provisória anteriores à EC 32/2001, de modo que é irrelevante “o fato de as medidas provisórias anteriores à MP 2.215-10/2001 terem perdido sua eficácia em razão do descumprimento do prazo de trinta dias previsto no parágrafo único do art. 62 da Constituição, na redação originária”. Tais conclusões estão de acordo com as Súmulas 359 e 651/STF.","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"[ RE 630.160 , rel. min. Roberto Barroso , dec. monocrática, j. 6-5-2016, DJE 95 de 12-5-2016.]","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"O recurso não merece provimento. Esta Corte firmou orientação no sentido da constitucionalidade da majoração da alíquota da Contribuição Social sobre o Lucro Líquido (CSLL) realizada pela MP 1.807/1999 e suas reedições. Ademais, é firme a jurisprudência do Supremo Tribunal Federal no sentido de que o termo inicial da contagem do prazo relativo à anterioridade nonagesimal para a cobrança de tributos instituídos ou majorados por medidas provisórias e reedições é a publicação da primeira medida da série. A respeito do tema, trago à colação os seguintes julgados: “1. A jurisprudência do Supremo Tribunal Federal é firme no sentido de que é constitucional a majoração da alíquota da CSLL pela MP 1.807/1999 e suas reedições. Súmula 651 do STF. 2. Agravo regimental a que se nega provimento” (ARE 804.464 ED, rel. min. Edson Fachin, Primeira Turma, DJE de 30-9-2015). (...) Ex positis , desprovejo o agravo, com fundamento no art. 21, § 1º, do RISTF.","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"[ ARE 956.826 , rel. min. Luiz Fux , dec. monocrática, j. 31-3-2016, DJE 63 de 7-4-2016.]","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":213,"runs":[{"text":"● A Súmula Vinculante 54 resultou da conversão da Súmula 651.","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"Data de publicação do enunciado: DJE de 28-3-2016.","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":213,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"55","number":"55","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":214,"endPage":215,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=3014","paragraphs":[{"page":214,"runs":[{"text":"O direito ao auxílio-alimentação não se estende aos servidores inativos.","deleted":false}]}],"notes":[{"page":214,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":214,"runs":[{"text":"Esta Corte tem entendido que o direito ao vale-alimentação ou auxílio-alimentação não se estende aos inativos por força do § 4º do art. 40 da CF/1988, porquanto se trata, em verdade, de verba indenizatória destinada a cobrir os custos de refeição devida exclusivamente ao servidor que se encontrar no exercício de suas funções, não se incorporando à remuneração nem aos proventos de aposentadoria (assim, a título exemplificativo, nos RE 220.713, RE 220.048, RE 228.083, RE 237.362 e RE 227.036). E ainda em face do § 8º do art. 40 na redação dada pela EC 20/1998, o Plenário deste Tribunal, ao julgar a ADI 575, manteve o entendimento de que “a regra de extensão aos inativos das melhorias da remuneração dos correspondentes servidores em atividade (CF/1988, art. 40, § 8º, cf. EC 20/1998) não implica a permanente e absoluta paridade entre proventos e vencimentos, dado que nos últimos se podem incluir vantagens pecuniárias que, por sua natureza, só podem ser atribuídas ao serviço ativo”.","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"[ RE 318.684 , rel. min. Moreira Alves , 1ª T, j. 9-10-2001, DJ de 9-11-2001.]","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"Como visto, foi determinante para a decisão da controvérsia a circunstância de estar-se, no caso, diante de verba indenizatória, destinada a cobrir os custos de uma refeição diária, e, portanto, devida exclusivamente ao servidor que se encontrar no exercício de suas funções, não se incorporando à remuneração e, por óbvio, aos proventos de aposentadoria. Se assim é, relativamente aos servidores ativos, não poderia ser diferente em relação aos servidores que se inativaram antes da edição da lei instituidora do auxílio em tela.","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"[ RE 228.083 , voto do rel. min. Ilmar Galvão , 1ª T, j. 26-3-1999, DJ de 25-6-1999.]","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":214,"runs":[{"text":"Natureza indenizatória do auxílio-alimentação","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"7. Na espécie, a autoridade reclamada reconheceu o direito de os servidores inativos e os pensionistas substituídos pelo interessado receberem cartão-alimentação sob o seguinte fundamento: “Com o advento do Decreto 7.150, de 31 de maio de 2017, os servidores inativos e pensionistas foram excluídos do rol de beneficiários do cartão-alimentação, instituído pela Lei Municipal 3.117/1995 alterado para cartão cesta-básica pela Lei 4.623 de 12 de dezembro de 2008. (...) Mas, em exame do referido decreto (fls. 51/52), percebe-se que nenhum dos seus dispositivos revoga a parte da Lei Municipal 3.117/1995, que garante a continuação do pagamento integral do benefício 'f) aos servidores afastados por motivo de doença ou acidente, inclusive àqueles em gozo de auxílio-doença ou auxílio acidente, junto ao INSS.' (fl. 57) Destarte, por prever a manutenção do pagamento cartão alimentação nos casos acima descritos, evidente é sua natureza remuneratória. Restando afastada, portanto, a hipótese de aplicação da Súmula 680 do Supremo Tribunal Federal e a Súmula Vinculante 55” (...). Esse entendimento diverge da Súmula Vinculante 55 do Supremo Tribunal Federal, pela qual se dispõe que “o direito ao auxílio-alimentação não se estende aos servidores inativos”. (...) 8. Pelo exposto, julgo procedente a presente reclamação para cassar a decisão reclamada e determinar outra seja proferida, com a observância da Súmula Vinculante 55 do Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"[ Rcl 31.157 , rel. min. Cármen Lúcia , dec. monocrática, j. 26-11-2018, DJE 261 de 5-12-2018.]","deleted":false}],"heading":false},{"page":214,"runs":[{"text":"O recurso merece ser provido. No caso em tela, alegou a servidora inativa, ora recorrida, que não lhe foi oportunizado o direito à defesa quando da supressão de seus proventos da parcela referente ao","deleted":false}],"heading":false},{"page":215,"runs":[{"text":"auxílio-alimentação pela Corte de Contas e pelo Tribunal de Justiça do Estado de Santa Catarina. (...) a jurisprudência desta Corte se firmou no sentido de que o auxílio-alimentação não se estende aos servidores inativos, por se tratar de verba indenizatória. Confira-se, à guisa de exemplo, (...) o AI 345.898 AgR, rel. min. Maurício Corrêa, Segunda Turma, DJ de 22-3-2002, que possui a seguinte ementa: “(...) O benefício do vale-alimentação, dada a sua natureza indenizatória, não integra a remuneração dos servidores públicos, não sendo devido, portanto, aos inativos. Precedentes. Agravo regimental a que se nega provimento.” Ex positis , provejo o recurso extraordinário.","deleted":false}],"heading":false},{"page":215,"runs":[{"text":"[ RE 878.114 , rel. min. Luiz Fux , dec. monocrática, j. 22-9-2016, DJE 206 de 27-9-2016]","deleted":false}],"heading":false},{"page":215,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":215,"runs":[{"text":"● A Súmula Vinculante 55 resultou da conversão da Súmula 680.","deleted":false}],"heading":false},{"page":215,"runs":[{"text":"Data de publicação do enunciado: DJE de 28-3-2016.","deleted":false}],"heading":false},{"page":215,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":215,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"56","number":"56","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":216,"endPage":220,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=3352","paragraphs":[{"page":216,"runs":[{"text":"A falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso, devendo-se observar, nessa hipótese, os parâmetros fixados no RE 641.320/RS.","deleted":false}]}],"notes":[{"page":216,"runs":[{"text":"Precedente representativo","deleted":false}],"heading":true},{"page":216,"runs":[{"text":"Cumprimento de pena em regime fechado, na hipótese de inexistir vaga em estabelecimento adequado a seu regime. Violação aos princípios da individualização da pena (art. 5º, XLVI) e da legalidade (art. 5º, XXXIX). A falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso. 3. Os juízes da execução penal poderão avaliar os estabelecimentos destinados aos regimes semiaberto e aberto, para qualificação como adequados a tais regimes. São aceitáveis estabelecimentos que não se qualifiquem como “colônia agrícola, industrial” (regime semiaberto) ou “casa de albergado ou estabelecimento adequado” (regime aberto) (art. 33, § 1º, b e c ). No entanto, não deverá haver alojamento conjunto de presos dos regimes semiaberto e aberto com presos do regime fechado. 4. Havendo déficit de vagas, deverão ser determinados: (i) a saída antecipada de sentenciado no regime com falta de vagas; (ii) a liberdade eletronicamente monitorada ao sentenciado que sai antecipadamente ou é posto em prisão domiciliar por falta de vagas; (iii) o cumprimento de penas restritivas de direito e/ou estudo ao sentenciado que progride ao regime aberto. Até que sejam estruturadas as medidas alternativas propostas, poderá ser deferida a prisão domiciliar ao sentenciado.","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"[ RE 641.320 , rel. min. Gilmar Mendes , P, j. 11-5-2016, DJE 159 de 1º-8-2016, Tema 423.]","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":216,"runs":[{"text":"● Considerando que é dever do Estado, imposto pelo sistema normativo, manter em seus presídios os padrões mínimos de humanidade previstos no ordenamento jurídico, é de sua responsabilidade, nos termos do art. 37, § 6º, da Constituição, a obrigação de ressarcir os danos, inclusive morais, comprovadamente causados aos detentos em decorrência da falta ou insuficiência das condições legais de encarceramento.","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"[Tese definida no RE 580.252 , rel. min. Teori Zavascki , red. p/ o ac. min. Gilmar Mendes , P, j. 16-2-2017, DJE 204 de 11-9-2017, Tema 365.]","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"● I - A falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso;","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"II - Os juízes da execução penal poderão avaliar os estabelecimentos destinados aos regimes semiaberto e aberto, para qualificação como adequados a tais regimes. São aceitáveis estabelecimentos que não se qualifiquem como “colônia agrícola, industrial” (regime semiaberto) ou “casa de albergado ou estabelecimento adequado” (regime aberto) (art. 33, § 1º, b e c);","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"III - Havendo déficit de vagas, deverá determinar-se:","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"(i) a saída antecipada de sentenciado no regime com falta de vagas;","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"(ii) a liberdade eletronicamente monitorada ao sentenciado que sai antecipadamente ou é posto em prisão domiciliar por falta de vagas;","deleted":false}],"heading":false},{"page":216,"runs":[{"text":"(iii) o cumprimento de penas restritivas de direito e/ou estudo ao sentenciado que progride ao regime aberto. Até que sejam estruturadas as medidas alternativas propostas, poderá ser deferida a prisão domiciliar ao","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"sentenciado.","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"[Tese definida no RE 641.320 , rel. min. Gilmar Mendes , P, j. 11-5-2016, DJE 159 de 1º-8-2016, Tema 423.]","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"2. (...), no que tange à alegação de que os presos do regime intermediário estariam no ócio, e não lhes estaria sendo observado o direito ao trabalho, embora se reconheça que o quadro, se confirmado, avilta ao objetivo precípuo de ressocialização do apenado, trata-se de fato que refoge ao âmbito de atuação da via eleita, por ausência de aderência estrita entre o aduzido pelo reclamante e a decisão apontada como paradigma. 3. Tampouco há como acolher o argumento de que a separação de presos do regime semiaberto e fechado, em alas diversas, é insuficiente para a plena concretização do quanto decidido na Súmula Vinculante 56, pois não se confunde alojamento conjunto de presos, o que é vedado pelo entendimento sumular, com custódia de presos em um mesmo estabelecimento carcerário, conduta que, por si só, não afronta o precedente vinculante. 4. A inexistência de argumentação apta a infirmar o julgamento monocrático conduz à manutenção da decisão recorrida. 5. Agravo regimental desprovido.","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"[ Rcl 26.374 AgR , rel. min. Edson Fachin , 2ª T, j. 30-10-2018, DJE 238 de 9-11-2018.]","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"(...) o reclamante foi condenado às penas de 03 (três) meses, em regime inicial semiaberto, e ao pagamento de 10 (dez) dias-multa, pena essa mantida pelo Colégio Recursal da Comarca (...). Após o pagamento da multa (...), foi cumprido mandado de prisão para que ele iniciasse o cumprimento de sua pena, em regime inicial semiaberto. Em razão disso, em fase de execução criminal, o reclamante requereu a concessão de prisão domiciliar - uma vez que se encontra acometido de doença grave (epilepsia e Alzheimer) que não encontra tratamento adequado no sistema prisional brasileiro, sem perder de vista, o tempo de progressão da pena(...). 13. Nesta análise perfunctória, entendo que existe plausibilidade do direito do reclamante, uma vez que, a meu ver, caberia à autoridade reclamada apreciar o pedido de colocação em prisão domiciliar enquanto não houvesse vaga no estabelecimento adequado ao cumprimento da pena em regime semiaberto. Não pode o magistrado se negar a decidir questão cuja não apreciação implica constrangimento ilegal, ao fundamento de que tal análise caberia a órgão administrativo. Ao quedar-se inerte, a autoridade reclamada permite que o reclamante cumpra pena em regime mais gravoso do que o determinado na sentença, o que é vedado pela súmula vinculante 56.","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"[ Rcl 32.055 , rel. min. Roberto Barroso , dec. monocrática, j. 2-10-2018, DJE 212 de 4-10-2018.]","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"Agravo regimental em reclamação. 2. Direito Processual Penal. Execução Penal. 3. Cumprimento de pena em regime semiaberto. 4. Suposta violação à Súmula Vinculante 56. 5. Não ocorrência. Decisão do juiz devidamente fundamentada. 6. A sentenciada está usufruindo dos benefícios inerentes a sua condição prisional (saídas diárias para o trabalho e recolhimento noturno). 6.1. Pernoite em celas com outras detentas, estas, em regime fechado. 6.2. Iniciadas obras de ampliação dos aposentos específicos do regime semiaberto. 7. Agravo regimental a que se nega provimento, com recomendação para transferência para pernoitar em cela/ala específica do regime semiaberto.","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"[ Rcl 27.676 AgR , rel. min. Gilmar Mendes , 2ª T, j. 17-8-2018, DJE 175 de 27-8-2018.]","deleted":false}],"heading":false},{"page":217,"runs":[{"text":"Analisando os autos, verifico que o apenado (...) efetivamente cumpre pena no regime aberto desde o dia 01.02.2017, com data prevista para o término da pena em 25.06.2026 (fls. 319/320). Ademais, é importante frisar que todos os apenados que cumprem pena no regime aberto na Cadeia Pública (...), quando do seu recolhimento nos finais de semana, ficam em celas distintas das dos apenados do regime fechado, não mantendo qualquer tipo de contato com estes últimos. Assim sendo, embora nesta Comarca não exista Casa de Albergado, o local onde os apenados do regime aberto cumprem pena e considerado adequado (art. 33, §1, \"c\", do CP), atendendo, dessa forma, ao que foi decidido no julgamento do RE 641.320/STF (...). Diante do exposto, INDEFIRO o pedido formulado pelo apenado (...). Nota-se, portanto, que a fundamentação apresentada na decisão acima transcrita aponta quais seriam os motivos concretos para a negativa da concessão de prisão domiciliar, razão pela qual não há falar-se em ofensa à Súmula Vinculante 56 (o próprio Juízo destacou que os presos, dentre eles o reclamante, quando dos finais de semana, ficariam em celas","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"distintas daquelas dos apenados do regime fechado, em estrita observância ao que fora decidido no RE 641.320/RS). Com efeito, tem-se que o ato reclamado está em harmonia com as balizas fixadas por esta CORTE, à medida que a concessão de prisão domiciliar deve ser a última opção a ser adotada, e não a primeira, como pretendido nesta Reclamação (Rcl 28.381/SP, Rel. Min. Alexandre de Moraes, DJe de 21/09/2017). Não há, portanto, qualquer ilegalidade no ato reclamado.","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"[ Rcl 29.298 , rel. min. Alexandre de Moraes , dec. monocrática, j. 9-8-2018, DJE 164 de 14-8-2018.]","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"Inconformado, o reclamante articula com o desrespeito ao verbete vinculante 56 da Súmula do Supremo, (...). Improcede a irresignação. Consoante se depreende da leitura das peças que acompanham a inicial, a controvérsia reside na adequação da Penitenciária Industrial de Joinville para albergar condenados submetidos ao regime semiaberto. Embora este Tribunal tenha proclamado, no paradigma, a inviabilidade de manter-se apenado em regime mais gravoso, assentou, na mesma oportunidade, cumprir aos juízes da execução penal - considerada, inclusive, a instância recursal - a avaliação quanto à conformação do estabelecimento ao regime imposto, descabendo ao Supremo adentrar a problemática. No caso, havendo o Tribunal de Justiça reconhecido a existência de local apropriado, nas instalações da Penitenciária, para a custódia do reclamante, no que garantido inclusive o trabalho externo, tendo em vista o regime semiaberto, surge ausente contrariedade ao paradigma.","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"[ Rcl 29.410 , rel. min. Marco Aurélio , dec. monocrática, j. 15-5-2018, DJE 98 de 21-5-2018.]","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"RECLAMAÇÃO CONSTITUCIONAL. PROCESSUAL PENAL. PROGRESSÃO DE REGIME: POSSIBILIDADE DE CUMPRIMENTO DAS PENAS DO REGIME SEMIABERTO EM ESTABELECIMENTO QUE NÃO SE CARACTERIZA COMO COLÔNIA DE TRABALHO. AUSÊNCIA DE CONTRARIEDADE AO VERBETE VINCULANTE 56 DESTE SUPREMO TRIBUNAL. RECLAMAÇÃO JULGADA IMPROCEDENTE. I - É certo que a falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso, entretanto, não há que se descartar a possibilidade de cumprimento das penas do regime semiaberto em estabelecimento que não se caracteriza como colônia de trabalho, desde que respeitados os parâmetros estipulados por esta Suprema Corte. II - Não há que se falar em desrespeito ao enunciado da Súmula Vinculante 56, pois a decisão combatida harmoniza-se com a orientação jurisprudencial desta Suprema Corte.","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"[ Rcl 25.123 , rel. min. Ricardo Lewandowski , 2ª T, j. 18-4-2017, DJE 168 de 1º-8-2017.]","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"A inexistência de argumentação apta a infirmar o julgamento monocrático conduz à manutenção da decisão recorrida. 2. No RE 641.320/RS, julgado de relatoria do ministro Gilmar Mendes que espelha a Súmula Vinculante 56, o Tribunal Pleno concluiu que “os juízes da execução penal poderão avaliar os estabelecimentos destinados aos regimes semiaberto e aberto, para qualificação como adequados a tais regimes”. 3. No caso concreto, o Tribunal de Justiça reconheceu a compatibilidade entre o local de custódia e o regime semiaberto, conclusão que, por desafiar reexame ou dilação probatórias, não admite rediscussão pela via reclamatória. 4. A alegação de que o Tribunal local considerou estabelecimento prisional distinto do atual local de custódia, por não traduzir violação à autoridade desta Corte, não admite acolhimento em sede reclamatória. O acerto ou desacerto da decisão, à luz das particularidades fáticas do caso concreto, é tema que incumbe às instâncias próprias.","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"[ Rcl 25.328 AgR , rel. min. Edson Fachin , 1ª T, j. 18-10-2016, DJE 236 de 7-11-2016.]","deleted":false}],"heading":false},{"page":218,"runs":[{"text":"A Súmula Vinculante 56 teve por objetivo evitar que o condenado cumprisse pena em regime mais gravoso do que o determinado na sentença ou do que o autorizado por lei. 2. A prisão domiciliar é medida adequada a ser adotada pelo Juízo diante da constatação de que o condenado preenche os requisitos para a progressão de regime, mas está impossibilitado de fazê-lo apenas pela falta de estabelecimento adequado. 3. Em cognição sumária, há indícios de violação ao enunciado da Súmula Vinculante 56 quando o acórdão determina a manutenção do reclamante em regime fechado tão somente ante a ausência de estabelecimento adequado ao cumprimento de pena em regime semiaberto ou aberto, ainda que o condenado cumpra os requisitos legais","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"para a progressão de regime. 4. Liminar deferida.","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"[ Rcl 24.840 MC , rel. min. Roberto Barroso , dec. monocrática, j. 10-8-2016, DJE 170 de 15-8-2016.]","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":219,"runs":[{"text":"Aplicação dos parâmetros fixados no precedente representativo da Súmula Vinculante 56 para o cumprimento das penas do regime semiaberto em estabelecimento que não se caracteriza como colônia agrícola ou industrial","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"De início, cabe ressaltar que da análise dos autos verifica-se a complexidade do presente caso. Devido à gravidade do ato cometido, a aplicação de uma medida socioeducativa é imprescindível para que o infrator compreenda a seriedade e a maleficência do abuso praticado, principalmente no que diz respeito às consequências traumáticas para a vítima. Portanto, não cabe dizer, como alega a defesa, que a aplicação de medida socioeducativa, mesmo após o transcurso de um longo prazo, não surtiria efeitos na vida e consciência do ora recorrente. Ressalta-se que o paciente ainda não completou 21 anos (...), de modo que não há óbice para a aplicação do ECA neste momento. Assim, vale citar que não foi atingido o limite temporal fixado pelo STJ nos termos da súmula 605 (...). Ao prestar informações, a juíza de primeiro grau comunicou que foi expedido mandado para o recolhimento do paciente, porém, a medida socioeducativa não pôde ser aplicada, pois não havia vaga disponível nas casas de semiliberdade do estado de Santa Catarina. A ausência de vagas para aplicação da medida socioeducativa não poderia ensejar o recolhimento em um regime mais gravoso para o cumprimento da determinação imposta ao sentenciado, já que constitui violação ao que determina a Súmula Vinculante 56 deste STF. Nos termos do precedente representativo do referido enunciado (...). Da análise do caso, nos termos da SV 56 deste STF e da ausência de vagas em regime de semiliberdade informada pelo juízo de primeiro grau, concluo que a medida socioeducativa de liberdade assistida, nos termos do artigo 118, caput , do Estatuto da Criança e do Adolescente, é a mais adequada às circunstâncias apresentadas. Diante dessas ponderações, dou parcial provimento ao presente recurso ordinário em habeas corpus, nos termos do art. 192, caput , do RISTF. Determino que o Juízo de origem estabeleça o prazo de duração e proceda à aplicação da medida socioeducativa de liberdade assistida.","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"[ RHC 157.228 , rel. min. Gilmar Mendes , dec. monocrática, j. 8-10-2018, DJE 219 de 15-10-2018.]","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"A Súmula Vinculante 56 teve por objetivo evitar que o condenado cumprisse pena em regime mais gravoso do que o determinado na sentença ou do que o autorizado por lei. 2. O RE 641.320, ao qual a Súmula Vinculante 56 faz referência, permite que o cumprimento da pena em regime semiaberto ocorra em estabelecimento que não seja caracterizado como colônia agrícola, ficando a cargo do magistrado estabelecer a adequação do estabelecimento à medida. 3. No presente caso, as informações prestadas pela autoridade reclamada demonstram que o local em que a reclamante cumpre a pena é adequado ao seu regime, ainda que não se qualifique como Colônia Agrícola ou Penitenciária Industrial. 4. Reclamação julgada improcedente.","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"[ Rcl 25.054 , rel. min. Luís Roberto Barroso , j. 10-3-2017, dec. monocrática, DJE 48 de 14-3-2017.]","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"Ausência de direito automático à prisão domiciliar diante da falta de vagas no regime adequado","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"Com efeito, esta Suprema Corte não impôs, indistintamente, a obrigatoriedade da concessão de prisão domiciliar, baseado unicamente na constatação de ausência de vagas no regime em que o apenado deveria cumprir a pena, sem que sejam observados os requisitos exigidos para a fruição do benefício. É que devem ser consideradas as circunstâncias pessoais do condenado, seu comportamento no curso da execução, a natureza dos crimes praticados, bem como a possibilidade de saída antecipada de sentenciados em regimes menos graves ou mais antigos. Conforme exposto no julgamento do RE 641.320, os juízes da execução penal deverão avaliar medidas alternativas, antes da colocação imediata do apenado em regime domiciliar.","deleted":false}],"heading":false},{"page":219,"runs":[{"text":"[ RHC 252.373 , rel. min. Luiz Fux , dec. monocrática, j. 14-2-2025, DJE s/n 17-2-2025.]","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"2. Eventual ausência de estabelecimento adequado na comarca não autoriza a automática concessão de regime aberto ou domiciliar. Incidência da Súmula Vinculante 56/STF, ao enunciar que “a falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso, devendo-se observar, nessa hipótese, os parâmetros fixados no RE 641.320/RS...”. 3. Habeas corpus não conhecido. Ordem concedida de ofício para que o Juízo da execução penal, após o incidente de unificação das penas impostas ao paciente, observe as diretrizes fixadas pelo Plenário do STF no RE 641.320 e na Súmula Vinculante 56 do STF.","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"[ HC 141.648 , rel. min. Marco Aurélio , red. do ac. min. Luís Roberto Barroso, j. 16-10-2018, 1ª T, DJE 25 de 8-2-2019.]","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"[...] esta Suprema Corte não impôs, indistintamente, a obrigatoriedade da concessão de prisão domiciliar, baseado unicamente na constatação de ausência de vagas no regime em que o apenado deveria cumprir a pena, sem que sejam observados os requisitos exigidos para a fruição do benefício. É que devem ser consideradas as circunstâncias pessoais do condenado, seu comportamento no curso da execução, a natureza dos crimes praticados, bem como a possibilidade de saída antecipada de sentenciados em regimes menos graves ou mais antigos. Conforme exposto no julgamento do RE 641.320, os juízes da execução penal deverão avaliar medidas alternativas, antes da colocação imediata do apenado em regime domiciliar.","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"[ Rcl 31.685 , rel. min. Luiz Fux , j. 15-10-2018, dec. monocrática, DJE 222 de 18-10-2018.]","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"Competência do juiz da execução para verificar a adequação do estabelecimento prisional ao regime de cumprimento da pena","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"Nos termos da Súmula Vinculante n. 56 e do RE 641.320-RG (Rel. Min. GILMAR MENDES, Tribunal Pleno, DJe de 1º/8/2016), a falta de estabelecimento penal adequado não autoriza a manutenção do condenado em regime prisional mais gravoso, sob pena de afronta aos princípios constitucionais da individualização da pena (art. 5º, XLVI) e da legalidade (art. 5º, XXXIX). (...) compete aos Magistrados responsáveis pelas execuções penais verificar se a unidade prisional proporciona a determinado sentenciado os direitos compatíveis com o regime imposto, atendendo, assim, aos parâmetros fixados no Recurso Extraordinário 641.320/RS. Sem isso, não se mostra possível avaliar eventual violação da Súmula Vinculante 56. E, no caso em tela, não houve a devida análise acerca das várias hipóteses previstas na Súmula Vinculante 56. (...) Ausente, por parte da autoridade judicial, o referido juízo de valor acerca da condição individual do sentenciado e do estabelecimento prisional em que está custodiado, não é possível reconhecer a violação da tese assentada nesta CORTE SUPREMA.","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"[ Rcl 56.354 , rel. min. Alexandre de Moraes , dec. monocrática, j. 18-10-2022, DJE 211 de 20-10-2022.]","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":220,"runs":[{"text":"Data de publicação do enunciado: DJE de 8-8-2016.","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":220,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"57","number":"57","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":221,"endPage":221,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=5966","paragraphs":[{"page":221,"runs":[{"text":"A imunidade tributária constante do art. 150, VI, d, da CF/88 aplica-se à importação e comercialização, no mercado interno, do livro eletrônico (e-book) e dos suportes exclusivamente utilizados para fixá-los, como leitores de livros eletrônicos (e-readers), ainda que possuam funcionalidades acessórias.","deleted":false}]}],"notes":[{"page":221,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":221,"runs":[{"text":"O art. 150, VI, d, da Constituição não se refere apenas ao método gutenberguiano de produção de livros, jornais e periódicos. O vocábulo “papel” não é, do mesmo modo, essencial ao conceito desses bens finais. O suporte das publicações é apenas o continente (corpus mechanicum) que abrange o conteúdo (corpus misticum) das obras. O corpo mecânico não é o essencial ou o condicionante para o gozo da imunidade, pois a variedade de tipos de suporte (tangível ou intangível) que um livro pode ter aponta para a direção de que ele só pode ser considerado como elemento acidental no conceito de livro. A imunidade de que trata o art. 150, VI, d, da Constituição, portanto, alcança o livro digital (e-book). (...) A teleologia da regra de imunidade igualmente alcança os aparelhos leitores de livros eletrônicos (ou e-readers) confeccionados exclusivamente para esse fim, ainda que, eventualmente, estejam equipados com funcionalidades acessórias ou rudimentares que auxiliam a leitura digital, tais como dicionário de sinônimos, marcadores, escolha do tipo e do tamanho da fonte etc. Esse entendimento não é aplicável aos aparelhos multifuncionais, como tablets, smartphone e laptops, os quais vão muito além de meros equipamentos utilizados para a leitura de livros digitais.","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"[ RE 330.817 , rel. min. Dias Toffoli , P, j. 8-3-2017, DJE 195 de 31-8-2017, Tema 593.]","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":221,"runs":[{"text":"● A imunidade tributária constante do art. 150, VI, d, da CF/88 aplica-se ao livro eletrônico (e-book), inclusive aos suportes exclusivamente utilizados para fixá-lo.","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"[Tese definida no RE 330.817 , rel. min. Dias Toffoli , P, j. 8-3-2017, DJE 195 de 31-8-2017, Tema 593.]","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":221,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 57 quanto ao PIS e à Cofins","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"No mais, a decisão impugnada está em consonância com o entendimento do Supremo. O Pleno, em 24 de abril de 2020, aprovou a edição do verbete vinculante nº 57 da súmula do Supremo com a seguinte redação (...). O enunciado editado, no que aludiu ao artigo 150, inciso VI, alínea “d”, da Constituição Federal, revela, a mais não poder, a ideia de que a imunidade refere-se apenas a impostos, surgindo descabida a articulação no tocante ao PIS e à Cofins.","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"[ ARE 1.266.675 , rel. min. Marco Aurélio , dec. monocrática, j. 16-6-2021, DJE s/n de 18-6-2021.]","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":221,"runs":[{"text":"Data de publicação do enunciado: DJE de 24-04-2020.","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":221,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"58","number":"58","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":222,"endPage":223,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=5973","paragraphs":[{"page":222,"runs":[{"text":"Inexiste direito a crédito presumido de IPI relativamente à entrada de insumos isentos, sujeitos à alíquota zero ou não tributáveis, o que não contraria o princípio da não cumulatividade.","deleted":false}]}],"notes":[{"page":222,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":222,"runs":[{"text":"Quando a matéria-prima é tributada, tem o industrial o direito a creditar-se do valor do imposto pago na sua entrada, para fim de compensação com o IPI recebido dos adquirentes do produto fabricado, recolhendo aos cofres públicos a diferença apurada, ao final de cada dez dias, tendo em vista o princípio da não-cumulatividade. (...). A compensação, portanto, só se dará com o que for cobrado, sendo intuitivo admitir que, se nada foi cobrado na operação anterior, nada há a compensar. (...) Ora, a não-exigência do IPI sobre a matéria-prima se dá sempre que é essa adquirida sob os regimes, indistintamente, de isenção (exclusão do imposto incidente), alíquota zero (redução da alíquota ao fator zero) ou de não incidência (produto não compreendido na esfera material de incidência do tributo). Conquanto não se trate de institutos análogos, é como se o fossem, para o efeito de que se trata, nestes autos, em que se pretende o reconhecimento de direito a crédito por tributo não pago.","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"[ RE 370.682 , voto do rel. min. Ilmar Galvão , P, j. 25-6-2007, DJE 165 de 19-12-2007.]","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"IPI - INSUMO - ALÍQUOTA ZERO - AUSÊNCIA DE DIREITO AO CREDITAMENTO. Conforme disposto no inciso II do § 3º do artigo 153 da Constituição Federal, observa-se o princípio da não-cumulatividade compensando-se o que for devido em cada operação com o montante cobrado nas anteriores, ante o que não se pode cogitar de direito a crédito quando o insumo entra na indústria considerada a alíquota zero. (...).","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"[ RE 353.657 , rel. min. Marco Aurélio , P, j. 26-6-2007, DJE 41 de 7-3-2008.]","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":222,"runs":[{"text":"● O princípio da não cumulatividade não assegura direito de crédito presumido de IPI para o contribuinte adquirente de insumos não tributados, isentos ou sujeitos à alíquota zero.","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"[Tese definida no RE 398.365 RG , rel. min. Gilmar Mendes , P, j. 27-8-2015, DJE 118 de 22-9-2015, Tema 844.]","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":222,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 58 à monofasia tributária relativa ao PIS e à Cofins","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"(...) há referência no aresto impugnado ao Tema nº 1.093 da sistemática dos Recursos Repetitivos do Superior Tribunal de Justiça, em cuja tese, para afastar o direito ao creditamento do PIS e da Cofins em regime monofásico, consta expressa citação do enunciado nº 58 da Súmula Vinculante do STF: “Inexiste direito a crédito presumido de IPI relativamente à entrada de insumos isentos, sujeitos à alíquota zero ou não tributáveis, o que não contraria o princípio da não cumulatividade”. 6. Nada obstante, o enunciado vinculante do Supremo Tribunal Federal está adstrito ao Imposto sobre Produtos Industrializados, e a jurisprudência desta Corte com relação à monofasia tributária relativa ao PIS e à Cofins aponta para um discussão restrita ao âmbito infraconstitucional.","deleted":false}],"heading":false},{"page":222,"runs":[{"text":"[ ARE 1.459.623 , rel. min. André Mendonça , dec. monocrática, j. 7-12-2023, DJE s/n de 11-12-2023.]","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"Inexistência de direito a crédito presumido de IPI na aquisição de insumos da Zona Franca de Manaus sob alíquota zero ou não tributáveis","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"1. Uma vez envolvida aquisição de insumos da Zona Franca de Manaus sob alíquota zero, cumpre observar o disposto no enunciado vinculante n. 58, segundo o qual “inexiste direito a crédito presumido de IPI relativamente à entrada de insumos isentos, sujeitos à alíquota zero ou não tributáveis, o que não contraria o princípio da não cumulatividade”. 2. O Supremo, ao apreciar o Tema n. 322 da sistemática da repercussão geral, fixou tese a reconhecer o direito a creditamento de IPI quanto a insumos adquiridos junto à Zona Franca de Manaus tão somente sob regime de isenção, não alcançados aqueles sujeitos à alíquota zero ou não tributáveis.","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"[ Rcl 50.670 AgR , rel. min. Nunes Marques , 2ª T, j. 16-9-2024, DJE de 24-9-2024.]","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"Suspensão do IPI e inexistência de crédito tributário","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"O princípio da não cumulatividade pressupõe a efetiva cobrança do tributo na operação anterior; inexistindo pagamento do imposto - como ocorre nos casos de suspensão que redunda na ulterior remissão do crédito tributário - não há crédito a ser apropriado pelo adquirente. 4. A sistemática do art. 29, § 5º, da Lei nº 10.637/2002 representa uma escolha legislativa legítima, voltada à etapa inicial da cadeia produtiva, compatível com a Constituição e com a jurisprudência do STF (Tema 844 e Súmula Vinculante 58). (...) A suspensão do IPI, ainda que tecnicamente distinta da isenção ou alíquota zero, possui os mesmos efeitos econômicos em relação ao creditamento, não gerando ônus tributário compensável.","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"[ ADI 7.135 , rel. min. Gilmar Mendes , P, j. 19-8-2025, DJE s/n de 26-8-2025.]","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":223,"runs":[{"text":"● Tese de Repercussão Geral definida no Tema 844, aprovada nos termos do item 2 da Ata da 12ª Sessão Administrativa do STF, realizada em 9-12-2015.","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"Data de publicação do enunciado: DJE de 7-5-2020.","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":223,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"59","number":"59","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":224,"endPage":226,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=8161","paragraphs":[{"page":224,"runs":[{"text":"É impositiva a fixação do regime aberto e a substituição da pena privativa de liberdade por restritiva de direitos quando reconhecida a figura do tráfico privilegiado (art. 33, § 4º, da Lei 11.343/06) e ausentes vetores negativos na primeira fase da dosimetria (art. 59 do CP), observados os requisitos do art. 33, § 2º, alínea c, e do art. 44, ambos do Código Penal.","deleted":false}]}],"notes":[{"page":224,"runs":[{"text":"Precedente Representativo","deleted":false}],"heading":true},{"page":224,"runs":[{"text":"1. O tráfico de entorpecentes privilegiado (art. 33, § 4º, da Lei n. 11.343/2006) não se harmoniza com a hediondez do tráfico de entorpecentes definido no caput e § 1º do art. 33 da Lei de Tóxicos. 2. O tratamento penal dirigido ao delito cometido sob o manto do privilégio apresenta contornos mais benignos, menos gravosos, notadamente porque são relevados o envolvimento ocasional do agente com o delito, a não reincidência, a ausência de maus antecedentes e a inexistência de vínculo com organização criminosa. 3. Há evidente constrangimento ilegal ao se estipular ao tráfico de entorpecentes privilegiado os rigores da Lei n. 8.072/90.","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"[ HC 118.533 , rel. min. Cármen Lúcia , P, j. 23-6-2016, DJE 229 de 19-9-2016.]","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"5. Ordem parcialmente concedida tão-somente para remover o óbice da parte final do art. 44 da Lei 11.343/2006, assim como da expressão análoga “vedada a conversão em penas restritivas de direitos”, constante do §4° do art. 33 do mesmo diploma legal. Declaração incidental de inconstitucionalidade, com efeito ex nunc , da proibição de substituição da pena privativa de liberdade pela pena restritiva de direitos; determinando-se ao Juízo da execução penal que faça a avaliação das condições objetivas e subjetivas da convolação em causa, na concreta situação do paciente.","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"[ HC 97.256 , rel. min. Ayres Britto , P, j. 1-9-2010, DJE 247 de 16-12-2010.]","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":224,"runs":[{"text":"A minorante do tráfico privilegiado aplica-se ao traficante ocasional sem envolvimento com a criminalidade","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"3. Os contornos do delito denotam não se tratar de traficante ocasional, surgindo imprópria a aplicação da minorante prevista no art. 33, § 4º, da Lei nº 11.343, de 2006. 4. Assentada pelas instâncias antecedentes a dedicação do paciente a atividades criminosas, a partir de dados concretos, alcançar conclusão diversa demandaria o reexame do acervo fático-probatório, incabível na via estreita do habeas corpus. 5. Descabe reconhecer a ocorrência de bis in idem consideradas a primeira e terceira fases da dosimetria da pena, uma vez que os fundamentos utilizados para afastar o redutor não se limitaram à quantidade do entorpecente, levando-se em conta todo o contexto em que ocorrido o delito. 6. Mantido o afastamento da minorante do tráfico privilegiado, fica prejudicada a aplicação do enunciado nº 59 da Súmula Vinculante do STF.","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"[ HC 241.193 AgR , rel. min. André Mendonça , 2ª T, j. 9-9-2024, DJE de 25-9-2024.]","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"Concessão de ordem de ofício","deleted":false}],"heading":false},{"page":224,"runs":[{"text":"A fundamentação apresentada e o convencimento motivado do Tribunal de origem para alterar a primeira e a terceira fases da dosimetria da pena imposta à paciente não podem ser revistos em habeas corpus nem em ação mandamental da defesa, o que evidenciaria inadmissível reformatio in pejus. Impõe-se, assim, considerar-se o que fixado na dosimetria da ação penal já transitada em julgado, ou seja, a) pena-base fixada no mínimo legal em face das circunstâncias judiciais favoráveis; b) reconhecimento do tráfico privilegiado; c)","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"pena final inferior à quatro anos de reclusão; d) substituição da pena privativa de liberdade por restritiva de direitos. 16. Nessas circunstâncias, impositiva a fixação do regime aberto, em estrito cumprimento ao enunciado da Súmula Vinculante n. 59, estando evidenciado o manifesto constrangimento ilegal apontado pela defesa. 17. Anote-se que aquela súmula vinculante também determina a observância do art. 44 do Código Penal, especialmente quando esse dispositivo disciplina as providências a serem adotadas pelo magistrado nos casos de descumprimento das medidas substitutivas impostas. 18. Pelo exposto, nego seguimento ao habeas corpus (§ 1º do art. 21 do Regimento Interno do Supremo Tribunal Federal), concedendo, contudo, ordem de ofício para fixar o regime aberto de cumprimento da pena imposta à paciente na Apelação Criminal n. (...), nos termos da Súmula Vinculante n. 59.","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"[ HC 234.867 , rel. min. Cármen Lúcia , dec. monocrática, j. 8-11-2023, DJE s/n de 14-11-2023.]","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"No caso, embora inexistentes circunstâncias judiciais desfavoráveis na primeira fase da dosimetria (art. 59 do CP) e fixada a reprimenda final em 3 anos 4 meses de reclusão, a decisão impugnada manteve o regime inicial semiaberto e proibiu a substituição da pena privativa de liberdade por sanção restritiva de direitos, (...) Esse entendimento, porém, está em desacordo com a atual jurisprudência do Supremo Tribunal Federal - STF. Posto isso, (...) concedo a ordem de habeas corpus para, desde já, fixar o regime prisional aberto e substituir a pena privativa de liberdade por sanção restritiva de direitos, (...).","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"[ HC 234.875 , rel. min. Cristiano Zanin , dec. monocrática, j. 7-11-2023, DJE s/n de 8-11-2023.]","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 59 diante da valoração negativa de vetores na dosimetria da pena","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"A valoração negativa da “culpabilidade, as consequências e as circunstâncias do crime” na dosimetria da pena (eDoc 4, fl. 13) torna impertinente o enunciado vinculante n. 59 da Súmula.","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"[ Rcl 64.435 ], rel. min. Nunes Marques , 2ª T, j. 26-2-2024, DJE s/n 8-3-2024.]","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"Inaplicabilidade da Súmula Vinculante 59 diante da valoração negativa da quantidade e natureza da droga","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"A valoração negativa da quantidade e da natureza do entorpecente apreendido, nos termos do art. 42 da Lei n. 11.343/2006, torna impertinente o enunciado vinculante n. 59 da Súmula.","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"[ RHC 232.994 ], rel. min. Nunes Marques , 2ª T, j. 21-11-2023, DJE s/n 7-12-2023.]","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"Possibilidade de fixação de regime mais gravoso ante às peculiaridades do caso concreto","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"2. In casu, (i) os fundamentos empregados para a fixação do regime inicial semiaberto consideraram o que dispõe o artigo 33, § 3º, do Código Penal, o qual estabelece que “A determinação do regime inicial de cumprimento da pena far-se-á com observância dos critérios previstos no art. 59 deste Código”; (ii) verifica-se que o reconhecimento de que “as circunstâncias judiciais específicas são desfavoráveis, no que diz respeito à variedade de entorpecentes e em razão da prática do crime em época de evento cultural (jogos do interior) e próximo à escola”, afasta a aplicação do referido entendimento sumular, tendo em vista que a orientação firmada nesta Suprema Corte é no sentido de ser idônea a fixação de regime inicial mais gravoso à luz das particularidades do caso concreto, máxime quando reconhecida e valorada negativamente circunstância judicial. 3. Deveras, o Supremo Tribunal Federal, ao editar o enunciado da Súmula Vinculante n. 59, sintetizou jurisprudência dominante desta Corte que autoriza a fixação do regime inicial aberto diante do reconhecimento de ausência de circunstâncias judiciais desfavoráveis e da fixação da pena-base no mínimo legal.","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"[ Rcl 71.325 AgR , rel. min. Luiz Fux , 1ª T, j. 6-11-2024, DJE s/n de 8-11-2024.]","deleted":false}],"heading":false},{"page":225,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":225,"runs":[{"text":"Data de publicação do enunciado: DJE de 27-10-2023.","deleted":false}],"heading":false},{"page":226,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":226,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"60","number":"60","scope":"main","kind":"vinculante","sectionId":"grupo-5","page":227,"endPage":231,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=9260","paragraphs":[{"page":227,"runs":[{"text":"O pedido e a análise administrativos de fármacos na rede pública de saúde, a judicialização do caso, bem ainda seus desdobramentos (administrativos e jurisdicionais), devem observar os termos dos 3 (três) acordos interfederativos (e seus fluxos) homologados pelo Supremo Tribunal Federal, em governança judicial colaborativa, no tema 1.234 da sistemática da repercussão geral RE 1.366.243.","deleted":false}]}],"notes":[{"page":227,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":227,"runs":[{"text":"1. É da jurisprudência do Supremo Tribunal Federal que o tratamento médico adequado aos necessitados se insere no rol dos deveres do Estado, porquanto responsabilidade solidária dos entes federados. O polo passivo pode ser composto por qualquer um deles, isoladamente, ou conjuntamente. 2. A fim de otimizar a compensação entre os entes federados, compete à autoridade judicial, diante dos critérios constitucionais de descentralização e hierarquização, direcionar, caso a caso, o cumprimento conforme as regras de repartição de competências e determinar o ressarcimento a quem suportou o ônus financeiro. 3. As ações que demandem fornecimento de medicamentos sem registro na ANVISA deverão necessariamente ser propostas em face da União. Precedente específico: RE 657.718, Rel. Min. Alexandre de Moraes.","deleted":false}],"heading":false},{"page":227,"runs":[{"text":"[ RE 855.178 ED , rel. Min. Luiz Fux , red. p/ ac. min. Edson Fachin , P, j. 23-5-2019, DJE 90 de 16-4-2020, Tema 793.]","deleted":false}],"heading":false},{"page":227,"runs":[{"text":"1. O Estado não pode ser obrigado a fornecer medicamentos experimentais. 2. A ausência de registro na ANVISA impede, como regra geral, o fornecimento de medicamento por decisão judicial. 3. É possível, excepcionalmente, a concessão judicial de medicamento sem registro sanitário, em caso de mora irrazoável da ANVISA em apreciar o pedido de registro (prazo superior ao previsto na Lei nº 13.411/2016), quando preenchidos três requisitos: (i) a existência de pedido de registro do medicamento no Brasil (salvo no caso de medicamentos órfãos para doenças raras e ultrarraras); (ii) a existência de registro do medicamento em renomadas agências de regulação no exterior; e (iii) a inexistência de substituto terapêutico com registro no Brasil. 4. As ações que demandem fornecimento de medicamentos sem registro na Anvisa deverão necessariamente ser propostas em face da União.","deleted":false}],"heading":false},{"page":227,"runs":[{"text":"[ Tese definida no RE 657.718 , rel. min. Marco Aurélio , red. p/ ac. min. Roberto Barroso , j. 22-5-2019, DJE 267 de 09-11-2020, Tema 500 .]","deleted":false}],"heading":false},{"page":228,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":228,"runs":[{"text":"● I - Competência. 1) Para fins de fixação de competência, as demandas relativas a medicamentos não incorporados na política pública do SUS e medicamentos oncológicos, ambos com registro na ANVISA, tramitarão perante a Justiça Federal, nos termos do art. 109, I, da Constituição Federal, quando o valor do tratamento anual específico do fármaco ou do princípio ativo, com base no Preço Máximo de Venda do Governo (PMVG - situado na alíquota zero), divulgado pela Câmara de Regulação do Mercado de Medicamentos (CMED - Lei 10.742/2003), for igual ou superior ao valor de 210 salários mínimos, na forma do art. 292 do CPC. 1.1) Existindo mais de um medicamento do mesmo princípio ativo e não sendo solicitado um fármaco específico, considera-se, para efeito de competência, aquele listado no menor valor na lista CMED (PMVG, situado na alíquota zero). 1.2) No caso de inexistir valor fixado na lista CMED, considera-se o valor do tratamento anual do medicamento solicitado na demanda, podendo o magistrado, em caso de impugnação pela parte requerida, solicitar auxílio à CMED, na forma do art. 7º da Lei 10.742/2003. 1.3) Caso inexista resposta em tempo hábil da CMED, o juiz analisará de acordo com o orçamento trazido pela parte autora. 1.4) No caso de cumulação de pedidos, para fins de competência, será considerado apenas o valor do(s) medicamento(s) não incorporado(s) que deverá(ão) ser somado(s), independentemente da existência de cumulação alternativa de outros pedidos envolvendo obrigação de fazer, pagar ou de entregar coisa certa. II - Definição de Medicamentos Não Incorporados. 2.1) Consideram-se medicamentos não incorporados aqueles que não constam na política pública do SUS; medicamentos previstos nos PCDTs para outras finalidades; medicamentos sem registro na ANVISA; e medicamentos off label sem PCDT ou que não integrem listas do componente básico. 2.1.1) Conforme decidido pelo Supremo Tribunal Federal na tese fixada no tema 500 da sistemática da repercussão geral, é mantida a competência da Justiça Federal em relação às ações que demandem fornecimento de medicamentos sem registro na Anvisa, as quais deverão necessariamente ser propostas em face da União, observadas as especificidades já definidas no aludido tema. III - Custeio. 3) As ações de fornecimento de medicamentos incorporados ou não incorporados, que se inserirem na competência da Justiça Federal, serão custeadas integralmente pela União, cabendo, em caso de haver condenação supletiva dos Estados e do Distrito Federal, o ressarcimento integral pela União, via repasses Fundo a Fundo (FNS ao FES), na situação de ocorrer redirecionamento pela impossibilidade de cumprimento por aquela, a ser implementado mediante ato do Ministério da Saúde, previamente pactuado em instância tripartite, no prazo de até 90 dias. 3.1) Figurando somente a União no polo passivo, cabe ao magistrado, se necessário, promover a inclusão do Estado ou Município para possibilitar o cumprimento efetivo da decisão, o que não importará em responsabilidade financeira nem em ônus de sucumbência, devendo ser realizado o ressarcimento pela via acima indicada em caso de eventual custo financeiro ser arcado pelos referidos entes. 3.2) Na determinação judicial de fornecimento do medicamento, o magistrado deverá estabelecer que o valor de venda do medicamento seja limitado ao preço com desconto, proposto no processo de incorporação na Conitec (se for o caso, considerando o venire contra factum proprium/tu quoque e observado o índice de reajuste anual de preço de medicamentos definido pela CMED), ou valor já praticado pelo ente em compra pública, aquele que seja identificado como menor valor, tal como previsto na parte final do art. 9º na Recomendação 146, de 28.11.2023, do CNJ. Sob nenhuma hipótese, poderá haver pagamento judicial às pessoas físicas/jurídicas acima descritas em valor superior ao teto do PMVG, devendo ser operacionalizado pela serventia judicial junto ao fabricante ou distribuidor. 3.3) As ações que permanecerem na Justiça Estadual e cuidarem de medicamentos não incorporados, as quais impuserem condenações aos Estados e Municípios, serão ressarcidas pela União, via repasses Fundo a Fundo (FNS ao FES ou ao FMS). Figurando somente um dos entes no polo passivo, cabe ao magistrado, se necessário, promover a inclusão do outro para possibilitar o cumprimento efetivo da decisão. 3.3.1) O ressarcimento descrito no item 3.3 ocorrerá no percentual de 65% (sessenta e cinco por cento) dos desembolsos decorrentes de condenações oriundas de ações cujo valor da causa seja superior a 7 (sete) e inferior a 210 (duzentos e dez) salários mínimos, a ser implementado mediante ato","deleted":false}],"heading":false},{"page":229,"runs":[{"text":"do Ministério da Saúde, previamente pactuado em instância tripartite, no prazo de até 90 dias. 3.4) Para fins de ressarcimento interfederativo, quanto aos medicamentos para tratamento oncológico, as ações ajuizadas previamente a 10 de junho de 2024 serão ressarcidas pela União na proporção de 80% (oitenta por cento) do valor total pago por Estados e por Municípios, independentemente do trânsito em julgado da decisão, a ser implementado mediante ato do Ministério da Saúde, previamente pactuado em instância tripartite, no prazo de até 90 dias. O ressarcimento para os casos posteriores a 10 de junho de 2024 deverá ser pactuado na CIT, no mesmo prazo. IV - Análise judicial do ato administrativo de indeferimento de medicamento pelo SUS. 4) Sob pena de nulidade do ato jurisdicional (art. 489, § 1º, V e VI, c/c art. 927, III, § 1º, ambos do CPC), o Poder Judiciário, ao apreciar pedido de concessão de medicamentos não incorporados, deverá obrigatoriamente analisar o ato administrativo comissivo ou omissivo da não incorporação pela Conitec e da negativa de fornecimento na via administrativa, tal como acordado entre os Entes Federativos em autocomposição no Supremo Tribunal Federal. 4.1) No exercício do controle de legalidade, o Poder Judiciário não pode substituir a vontade do administrador, mas tão somente verificar se o ato administrativo específico daquele caso concreto está em conformidade com as balizas presentes na Constituição Federal, na legislação de regência e na política pública no SUS. 4.2) A análise jurisdicional do ato administrativo que indefere o fornecimento de medicamento não incorporado restringe-se ao exame da regularidade do procedimento e da legalidade do ato de não incorporação e do ato administrativo questionado, à luz do controle de legalidade e da teoria dos motivos determinantes, não sendo possível incursão no mérito administrativo, ressalvada a cognição do ato administrativo discricionário, o qual se vincula à existência, à veracidade e à legitimidade dos motivos apontados como fundamentos para a sua adoção, a sujeitar o ente público aos seus termos. 4.3) Tratando-se de medicamento não incorporado, é do autor da ação o ônus de demonstrar, com fundamento na Medicina Baseada em Evidências, a segurança e a eficácia do fármaco, bem como a inexistência de substituto terapêutico incorporado pelo SUS. 4.4) Conforme decisão da STA 175-AgR, não basta a simples alegação de necessidade do medicamento, mesmo que acompanhada de relatório médico, sendo necessária a demonstração de que a opinião do profissional encontra respaldo em evidências científicas de alto nível, ou seja, unicamente ensaios clínicos randomizados, revisão sistemática ou meta-análise. V - Plataforma Nacional. 5) Os Entes Federativos, em governança colaborativa com o Poder Judiciário, implementarão uma plataforma nacional que centralize todas as informações relativas às demandas administrativas e judiciais de acesso a fármaco, de fácil consulta e informação ao cidadão, na qual constarão dados básicos para possibilitar a análise e eventual resolução administrativa, além de posterior controle judicial. 5.1) A porta de ingresso à plataforma será via prescrições eletrônicas, devidamente certificadas, possibilitando o controle ético da prescrição, a posteriori, mediante ofício do Ente Federativo ao respectivo conselho profissional. 5.2) A plataforma nacional visa a orientar todos os atores ligados ao sistema público de saúde, possibilitando a eficiência da análise pelo Poder Público e compartilhamento de informações com o Poder Judiciário, mediante a criação de fluxos de atendimento diferenciado, a depender de a solicitação estar ou não incluída na política pública de assistência farmacêutica do SUS e de acordo com os fluxos administrativos aprovados pelos próprios Entes Federativos em autocomposição. 5.3) A plataforma, entre outras medidas, deverá identificar quem é o responsável pelo custeio e fornecimento administrativo entre os Entes Federativos, com base nas responsabilidades e fluxos definidos em autocomposição entre todos os Entes Federativos, além de possibilitar o monitoramento dos pacientes beneficiários de decisões judiciais, com permissão de consulta virtual dos dados centralizados nacionalmente, pela simples consulta pelo CPF, nome de medicamento, CID, entre outros, com a observância da Lei Geral de Proteção da Dados e demais legislações quanto ao tratamento de dados pessoais sensíveis. 5.4) O serviço de saúde cujo profissional prescrever medicamento não incorporado ao SUS deverá assumir a responsabilidade contínua pelo acompanhamento clínico do paciente, apresentando, periodicamente, relatório atualizado do estado clínico do paciente, com informações detalhadas sobre o progresso do tratamento, incluindo melhorias, estabilizações ou deteriorações no estado de saúde do paciente, assim como qualquer mudança relevante no plano terapêutico. VI -","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Medicamentos incorporados. 6) Em relação aos medicamentos incorporados, conforme conceituação estabelecida no âmbito da Comissão Especial e constante do Anexo I, os Entes concordam em seguir o fluxo administrativo e judicial detalhado no Anexo I, inclusive em relação à competência judicial para apreciação das demandas e forma de ressarcimento entre os Entes, quando devido. 6.1) A(o) magistrada(o) deverá determinar o fornecimento em face de qual ente público deve prestá-lo (União, estado, Distrito Federal ou Município), nas hipóteses previstas no próprio fluxo acordado pelos Entes Federativos, anexados ao presente acórdão.","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"[Tese definida no RE 1.366.243 , rel. min. Gilmar Mendes , P, j. 16-9-2024, DJE de 11-10-2024, Tema 1234,e alterada no RE 1.366.243 ED, rel. min. Gilmar Mendes , j. 16-12-2024, P, DJE de 5-2-2025.]","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":230,"runs":[{"text":"Aplicação da Súmula Vinculante 60 em casos de medicamentos à base de canabidiol","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Há precedentes desta Suprema Corte que reconhecem a aplicação das Súmulas Vinculantes nº 60 e 61, bem como dos Temas 6 e 1234, inclusive em casos de medicamentos à base de canabidiol.","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"[ Rcl 87.801 , rel. min. Flávio Dino , dec. monocrática, j. 1º-12-2025, DJE s/n 2-12-2025.]","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Atrai a competência da Justiça Federal a incorporação de medicamento ao SUS e que integra a Rename/2022","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Na espécie vertente, busca-se a condenação do reclamante ao fornecimento do fármaco Baricitinibe 4mg para tratamento da doença artrite reumatoide. Esse medicamento obteve registro na Agência Nacional de Vigilância Sanitária- Anvisa e foi incluído na Relação Nacional de Medicamentos Essenciais de 2022 (Rename). Foi, assim, padronizado e incorporado às políticas públicas executadas pelo Sistema Único de Saúde- SUS. Assim, aplicando-se o entendimento firmado neste Supremo Tribunal sobre o tema, é de assentar-se a necessidade de inclusão da União no polo passivo da ação subjacente, na forma do julgamento do Tema 1.234 da repercussão geral, consolidado na Súmula Vinculante n. 60 deste Supremo Tribunal, com o consequente deslocamento da competência para a Justiça Federal.","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"[ Rcl 73.562 , rel. min. Cármen Lúcia , dec. monocrática, j. 9-11-2024, DJE s/n 12-11-2024.]","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Fornecimento Judicial de Medicamento do Grupo 1A da Rename 2022: Custeio Integral pela União e Observância do Teto do PMVG","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Desta feita, considerando que o medicamento em questão foi incorporado ao Sistema Único de Saúde e integra o grupo de financiamento 1A, de acordo com a RENAME 2022, verifica-se que: a) a responsabilidade pelo custeio total cabe à União (competência da Justiça Federal), cabendo a essa, em caso de haver condenação dos Estados e do Distrito Federal, o ressarcimento integral via repasses Fundo a Fundo; b) há necessidade de a determinação judicial de fornecimento de medicamentos estabelecer que a venda do medicamento deve se processar mediante desconto, vedado o pagamento judicial às pessoas físicas/jurídicas em valor superior ao teto do PMVG.","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"[ Rcl 75.109 , rel. min. Flávio Dino , dec. monocrática, j. 14-01-2025, DJE s/n de 15-01-2025.]","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"Irrelevância do limite de 210 salários-mínimos de custo anual do fornecimento de medicamentos para fins de competência jurisdicional quando o acordo interfederativo homologado atribuir à União a responsabilidade pelo custeio","deleted":false}],"heading":false},{"page":230,"runs":[{"text":"É irrelevante, para fins de competência e formação do polo passivo, a alegação de que o custo anual do tratamento seria inferior a 210 salários-mínimos. Tal baliza não é capaz de afastar a competência delineada pelo art. 109, I, da Constituição quando, por força do Tema 1.234 (RE 1.366.243) e da Súmula Vinculante nº 60, há acordo interfederativo homologado que classifica o medicamento como de aquisição centralizada (Grupo 1A do CEAF) e atribui à União a responsabilidade pelo custeio e aquisição.","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"[ Rcl 82.262 AgR , rel. min. Flávio Dino , 1ª T, j. 6-10-2025, DJE s/n 13-10-2025.]","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"Marco temporal para deslocamento da competência no Tema 1234","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"Após o julgamento dos Embargos de Declaração nos autos do RE 1366243, esta Corte elucidou que os efeitos do Tema 1234 - RG, quanto à competência, somente se aplicam às ações que forem ajuizadas após a publicação do resultado do julgamento de mérito no Diário de Justiça Eletrônico (19.9.2024). Considerou-se, portanto, suficiente a publicação da ata, em que pese o inteiro teor do acórdão ter sido publicado somente em 11.10.2024. (...), os embargos de declaração devem ser acolhidos para retificar que a data considerada como parâmetro para deslocamento de competência, na forma do Tema 1234 - RG e da Súmula Vinculante 60, é 19.09.2024. (...) o processo foi ajuizado em 01.10.2024, portanto, em data posterior ao referido marco, havendo necessidade de inclusão da União no polo passivo e de deslocamento de competência para a Justiça Federal.","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"[ Rcl 75.119 ED , rel. min. Flávio Dino , dec. monocrática, j. 19-2-2025, DJE s/n de 20-2-2025.]","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"Não atrai a competência da Justiça Federal a incorporação de medicamento ao SUS e que consta no grupo de financiamento 1B - Rename/2022","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"8. Na espécie vertente, busca-se a condenação do reclamante ao fornecimento dos fármacos Valsartana e Sacubitril 50mg, para tratamento de doenças graves. Esse medicamento obteve registro na Agência Nacional de Vigilância Sanitária- Anvisa. O medicamento está incorporado ao Sistema Único de Saúde- SUS, incluído no Grupo 1B do Componente Especializado da Assistência Farmacêutica, cuja aquisição é realizada pelas Secretarias de Saúde dos Estados e do Distrito Federal, com transferência de recursos financeiros pelo Ministério da Saúde, para ressarcimento, na modalidade Fundo a Fundo; e a responsabilidade pelo armazenamento, pela distribuição e pela dispensação é das Secretarias de Saúde dos Estados e do Distrito Federal. Assim, aplicando-se o entendimento firmado neste Supremo Tribunal sobre o tema, é de assentar-se a desnecessidade de inclusão da União no polo passivo da ação subjacente, na forma do julgamento do Tema 1.234 da repercussão geral, consolidado na Súmula Vinculante n. 60 deste Supremo Tribunal, como proferido pela Oitava Turma Recursal de Fazenda Pública do Tribunal de Justiça do Estado de São Paulo na decisão reclamada.","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"[ Rcl 74.616 , rel. min Cármen Lúcia , dec. monocrática, j. 13-12-2024, DJE s/n 17-12-2024.]","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":231,"runs":[{"text":"Data de publicação do enunciado: DJE de 16-9-2024.","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":231,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"61","number":"61","scope":"main","kind":"vinculante","sectionId":"grupo-6","page":232,"endPage":234,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=9296","paragraphs":[{"page":232,"runs":[{"text":"A concessão judicial de medicamento registrado na ANVISA, mas não incorporado às listas de dispensação do Sistema Único de Saúde, deve observar as teses firmadas no julgamento do Tema 6 da Repercussão Geral (RE 566.471).","deleted":false}]}],"notes":[{"page":232,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":232,"runs":[{"text":"46. Porém, para fins de reduzir e racionalizar, tanto quanto possível, a judicialização nessas situações, proponho 5 (cinco) requisitos cumulativos que devem ser observados pelo Poder Judiciário para o deferimento de uma prestação de saúde. São eles: (i) a incapacidade financeira do requerente para arcar com o custo correspondente, (ii) a demonstração de que a não incorporação do medicamento não resultou de decisão expressa dos órgãos competentes, (iii) a inexistência de substituto terapêutico incorporado pelo SUS, (iv) a comprovação de eficácia do medicamento pleiteado à luz da medicina baseada em evidências, e (v) a propositura da demanda necessariamente em face da União. Ademais, deve-se exigir a observância de 1 (um) parâmetro procedimental relativo à realização de diálogo interinstitucional entre o Poder Judiciário e entes ou pessoas com expertise técnica na área da saúde (e.g., câmaras e núcleos de apoio técnico em saúde no âmbito dos tribunais, profissionais do SUS e CONITEC), para fins de aferir a presença dos requisitos de dispensação e determinar aos órgãos competentes, no caso de deferimento judicial do medicamento, que avaliem a possibilidade de sua incorporação pelo SUS.","deleted":false}],"heading":false},{"page":232,"runs":[{"text":"[ RE 566.471 , rel. min. Marco Aurélio , red. p/ o ac. min. Luís Roberto Barroso , P, j. 26-9-2024, DJE 28-11-2024.]","deleted":false}],"heading":false},{"page":232,"runs":[{"text":"Teses de Repercussão Geral","deleted":false}],"heading":true},{"page":232,"runs":[{"text":"● 1. O Estado não pode ser obrigado a fornecer medicamentos experimentais. 2. A ausência de registro na ANVISA impede, como regra geral, o fornecimento de medicamento por decisão judicial. 3. É possível, excepcionalmente, a concessão judicial de medicamento sem registro sanitário, em caso de mora irrazoável da ANVISA em apreciar o pedido (prazo superior ao previsto na Lei nº 13.411/2016), quando preenchidos três requisitos: (i) a existência de pedido de registro do medicamento no Brasil (salvo no caso de medicamentos órfãos para doenças raras e ultrarraras);(ii) a existência de registro do medicamento em renomadas agências de regulação no exterior; e (iii) a inexistência de substituto terapêutico com registro no Brasil. 4. As ações que demandem fornecimento de medicamentos sem registro na ANVISA deverão necessariamente ser propostas em face da União.","deleted":false}],"heading":false},{"page":232,"runs":[{"text":"[Tese definida no RE 657.718, rel. min. Marco Aurélio, red. p/ o ac. min. Luís Roberto Barroso, P, j. 22-5-2019, DJE 267 de 9-11-2020, Tema 500.]","deleted":false}],"heading":false},{"page":232,"runs":[{"text":"● 1. A ausência de inclusão de medicamento nas listas de dispensação do Sistema Único de Saúde - SUS (RENAME, RESME, REMUME, entre outras) impede, como regra geral, o fornecimento do fármaco por decisão judicial, independentemente do custo. 2. É possível, excepcionalmente, a concessão judicial de medicamento registrado na ANVISA, mas não incorporado às listas de dispensação do Sistema Único de Saúde, desde que preenchidos, cumulativamente, os seguintes requisitos, cujo ônus probatório incumbe ao autor da ação: (a) negativa de fornecimento do medicamento na via administrativa, nos termos do item '4' do Tema 1234 da repercussão geral; (b) ilegalidade do ato de não incorporação do medicamento pela Conitec, ausência de pedido de incorporação ou da mora na sua apreciação, tendo em vista os prazos e critérios previstos nos artigos 19-Q e 19-R da Lei nº 8.080/1990 e no Decreto nº 7.646/2011; c) impossibilidade de substituição por outro medicamento constante das","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"listas do SUS e dos protocolos clínicos e diretrizes terapêuticas; (d) comprovação, à luz da medicina baseada em evidências, da eficácia, acurácia, efetividade e segurança do fármaco, necessariamente respaldadas por evidências científicas de alto nível, ou seja, unicamente ensaios clínicos randomizados e revisão sistemática ou meta-análise; (e) imprescindibilidade clínica do tratamento, comprovada mediante laudo médico fundamentado, descrevendo inclusive qual o tratamento já realizado; e (f) incapacidade financeira de arcar com o custeio do medicamento. 3. Sob pena de nulidade da decisão judicial, nos termos do artigo 489, § 1º, incisos V e VI, e artigo 927, inciso III, § 1º, ambos do Código de Processo Civil, o Poder Judiciário, ao apreciar pedido de concessão de medicamentos não incorporados, deverá obrigatoriamente: (a) analisar o ato administrativo comissivo ou omissivo de não incorporação pela Conitec ou da negativa de fornecimento da via administrativa, à luz das circunstâncias do caso concreto e da legislação de regência, especialmente a política pública do SUS, não sendo possível a incursão no mérito do ato administrativo; (b) aferir a presença dos requisitos de dispensação do medicamento, previstos no item 2, a partir da prévia consulta ao Núcleo de Apoio Técnico do Poder Judiciário (NATJUS), sempre que disponível na respectiva jurisdição, ou a entes ou pessoas com expertise técnica na área, não podendo fundamentar a sua decisão unicamente em prescrição, relatório ou laudo médico juntado aos autos pelo autor da ação; e (c) no caso de deferimento judicial do fármaco, oficiar aos órgãos competentes para avaliarem a possibilidade de sua incorporação no âmbito do SUS.","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"[Tese definida no RE 566.471, rel. min. Marco Aurélio, red. p/ o ac. min. Luís Roberto Barroso, P, j. 26-9-2024, DJE 361 de 28-11-2024, Tema 06.]","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"Incumbe ao autor da ação o ônus probatório para concessão de medicamento não incorporado ao SUS","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"No que tange ao Tema 06 - RG (RE 566.471) e à Súmula Vinculante 61, destaco que restou assentado por esta Corte que a concessão judicial de medicamento registrado na ANVISA, mas não incorporado às listas de dispensação do Sistema Único de Saúde é medida excepcional, que só poderá ocorrer quando preenchidos cumulativamente os seguintes requisitos cujo ônus probatório incumbe ao autor da ação originária","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"[ Rcl 75.049 AgR , rel. min. Flávio Dino , 1ª T, j. 25-6-2025, DJE s/n 30-6-2025.]","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"Necessidade de observância do juízo técnico da Conitec pelo julgador","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"35. À vista disso, sem desconsiderar a alegada relevância da intervenção para a garantia do direito à saúde da parte beneficiária, a decisão reclamada inobservou requisito fixado quando do julgamento do Tema 06 - RG e da Súmula Vinculante 61 acerca para a excepcional concessão judicial de medicamento registrado na ANVISA, mas não incorporado às listas de dispensação do Sistema Único de Saúde. 36. Houve desconsideração, pelo Poder Judiciário, da análise de viabilidade econômica realizada pelo Ministério da Saúde, sob a alegação de que o tratamento direcionado apenas a pacientes elegíveis não seria capaz de impactar na sustentabilidade do sistema de saúde, o que justificaria a assunção do custo orçamentário.","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"[ Rcl 75.471 , rel. min. Flávio Dino , dec. monocrática, j. 25-2-2025, DJE s/n 26-2-2025.]","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"Aplicabilidade das diretrizes dos Temas 6 e 1234 da RG em ações prestacionais de saúde","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"A ressalva consignada nos julgamentos das teses dos Temas nºs 6 e 1234 da RG não constitui impedimento para que suas diretrizes sejam observadas em ações prestacionais de saúde independentemente de estarem relacionadas a medicamentos, de modo a formar demanda qualificada e propiciar decisões também qualificadas no contexto da judicialização da saúde.","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"[ Rcl 73.135 , rel. min. Dias Toffoli , dec. monocrática, j. 13-12-2024, DJE s/n 17-12-2024.]","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"Observação","deleted":false}],"heading":false},{"page":233,"runs":[{"text":"Data de publicação do enunciado: DJE de 3-10-2024.","deleted":false}],"heading":false},{"page":234,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":234,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"62","number":"62","scope":"main","kind":"vinculante","sectionId":"grupo-6","page":235,"endPage":235,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=9347","paragraphs":[{"page":235,"runs":[{"text":"É legítima a revogação da isenção estabelecida no art. 6º, II, da Lei Complementar 70/1991 pelo art. 56 da Lei 9.430/1996, dado que a LC 70/1991 é apenas formalmente complementar, mas materialmente ordinária com relação aos dispositivos concernentes à contribuição social por ela instituída.","deleted":false}]}],"notes":[{"page":235,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":235,"runs":[{"text":"a) Exigência de reserva de plenário para as situações de não-aplicação do art. 56 da Lei nº 9.430/96, que revogou a isenção da COFINS para as sociedades prestadoras de serviços. b) Necessidade de lei complementar para a revogação da isenção da COFINS para as sociedades prestadoras de serviços.","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"[ RE 377.457 , rel. min. Gilmar Mendes , P, j. 17-9-2008, DJE 19-12-2008, Tema 71.]","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"Embargos de declaração em embargos de divergência em embargos de declaração em agravo regimental em agravo de instrumento. 2. Direito Tributário. 3. Acórdão recorrido que destoa da jurisprudência do Supremo Tribunal Federal. 4. Revogação, pelo art. 56 da Lei 9.430/96, de isenção da COFINS concedida às sociedades civis de profissão legalmente regulamentada pelo art. 6º, II, da Lei Complementar 70/91. Legitimidade 5. Inexistência de relação hierárquica entre lei ordinária e lei complementar. Questão exclusivamente constitucional relacionada à distribuição material entre as espécies legais. Precedentes. 6. A Lei Complementar 70/91 é apenas formalmente complementar, mas materialmente ordinária, com relação aos dispositivos concernentes à contribuição social por ela instituída. ADC 1, Rel. Moreira Alves, RTJ 156/721 7. Ausência de omissão, contradição ou obscuridade. Acórdão embargado suficientemente motivado. Embargos protelatórios. 8. Embargos de declaração rejeitados.","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"[ AI 597.906-AgR-ED-EDv-ED , rel. min. Gilmar Mendes , P, j. 18-8-2020, DJE 4-9-2020.]","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"Tese de Repercussão Geral","deleted":false}],"heading":true},{"page":235,"runs":[{"text":"● É legítima a revogação da isenção estabelecida no art. 6º, II, da Lei Complementar 70/1991 pelo art. 56 da Lei 9.430/1996, dado que a LC 70/1991 é apenas formalmente complementar, mas materialmente ordinária com relação aos dispositivos concernentes à contribuição social por ela instituída.","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"[Tese definida no RE 377.457 , rel. min. Gilmar Mendes , P, j. 17-9-2008, DJE 19-12-2008, Tema 71].","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":235,"runs":[{"text":"Data de publicação do enunciado: DJE de 9-1-2025.","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":235,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]},{"id":"63","number":"63","scope":"main","kind":"vinculante","sectionId":"grupo-6","page":236,"endPage":236,"status":"as_provided","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=9519","paragraphs":[{"page":236,"runs":[{"text":"O tráfico privilegiado (art. 33, § 4º, da Lei 11.343/2006) não configura crime hediondo, afastando-se a aplicação dos parâmetros mais rigorosos de progressão de regime e de livramento condicional.","deleted":false}]}],"notes":[{"page":236,"runs":[{"text":"Precedentes Representativos","deleted":false}],"heading":true},{"page":236,"runs":[{"text":"O tráfico de entorpecentes privilegiado (art. 33, § 4º, da Lei n. 11.313/2006) não se harmoniza com a hediondez do tráfico de entorpecentes definido no caput e § 1º do art. 33 da Lei de Tóxicos.","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"[ HC 118.533 , rel. min. Cármen Lúcia , P, j. 23-6-2016, DJE 19-9-2016.]","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"É constitucional a concessão de indulto a condenado por tráfico privilegiado, uma vez que o crime não tem natureza hedionda","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"[ RE 1.542.482 RG , rel. min. Luís Roberto Barroso , P, j. 30-5-2025, DJE 9-6-2025, Tema 1400 .]","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"Jurisprudência selecionada","deleted":false}],"heading":true},{"page":236,"runs":[{"text":"Condenação anterior por tráfico privilegiado não configura crime hediondo para fins de reincidência","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"(...) a Súmula Vinculante 63 é taxativa ao afastar a natureza hedionda do tráfico privilegiado. Dessa forma, a condenação anterior por esse delito não tem o condão de caracterizar a reincidência específica em crime hediondo ou equiparado, requisito indispensável para a incidência do percentual mais gravoso de 60%. Portanto, a decisão reclamada, ao desconsiderar a natureza não hedionda do tráfico privilegiado para fins de cálculo da progressão de regime, afrontou a autoridade da Súmula Vinculante 63 e dissentiu da jurisprudência pacífica deste Supremo Tribunal Federal.","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"[ Rcl 87.875 , rel. min. Gilmar Mendes , dec. monocrática, j. 1º-2-2026, DJE s/n 6-2-2026.]","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"Necessidade de reconhecimento da figura do tráfico privilegiado pelo juízo a quo para aplicação da Súmula Vinculante 63","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"Com efeito, uma das condições prévias necessárias à aplicação das Súmulas Vinculantes 59 e 63 é que tenha sido reconhecida a figura do tráfico privilegiado pelo juízo a quo .","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"[ Rcl 89.182 , rel. min. Cristiano Zanin , dec. monocrática, j. 2-2-2026, DJE s/n 3-2-2026.]","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"Observação","deleted":false}],"heading":true},{"page":236,"runs":[{"text":"Data de publicação do enunciado: DJE de 22-10-2025.","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"Para informações adicionais, clique aqui.","deleted":false}],"heading":false},{"page":236,"runs":[{"text":"Para pesquisar menções a esta súmula no banco de jurisprudência do STF, utilizando o nosso critério de pesquisa, clique aqui.","deleted":false}],"heading":false}]}]}];
